             </button>
        </div>
      </aside>

      <main className="flex-1 overflow-auto p-10 bg-[#020617] relative">
        <div className="max-w-7xl mx-auto">
          {activeTab === 'dashboard' && (
            <Dashboard 
              accounts={accounts} 
              transactions={transactions} 
              onNavigate={setActiveTab}
              onAddAccount={() => setActiveTab('accounts')}
              onAddTransaction={() => setActiveTab('transactions')}
              onAddGoal={() => setActiveTab('goals')}
              formatCurrency={formatCurrency} 
            />
          )}
          {activeTab === 'transactions' && (
            <Transactions 
              transactions={transactions} 
              accounts={accounts}
              onDelete={handleDeleteTransaction}
              onAdd={handleAddTransaction}
              formatCurrency={formatCurrency}
              onNavigateToAccounts={() => setActiveTab('accounts')}
              userPlan={userPlan}
            />
          )}
          {activeTab === 'accounts' && (
              <Accounts 
                  accounts={accounts} 
                  budgets={budgets}
                  transactions={transactions}
                  userPlan={userPlan}
                  onAdd={handleAddAccount}
                  onUpdate={handleUpdateAccount}
                  onDelete={handleDeleteAccount}
                  formatCurrency={formatCurrency}
                  userName={userName}
                  userAvatar={userAvatar}
                  userAvatarZoom={userAvatarZoom}
                  userAvatarPos={userAvatarPos}
                  onNavigate={setActiveTab}
              />
          )}
          {activeTab === 'insights' && (
            <Insights 
              transactions={transactions} 
              userPlan={userPlan} 
              onUpgradeClick={() => setActiveTab('plans')}
              formatCurrency={formatCurrency} 
            />
          )}
          {activeTab === 'goals' && (
            <Goals 
              goals={goals} 
              budgets={budgets} 
              transactions={transactions}
              onAddGoal={(g) => setGoals([...goals, g])}
              onUpdateGoal={(g) => setGoals(goals.map(prev => prev.id === g.id ? g : prev))}
              onAddBudget={(b) => setBudgets([...budgets, b])}
              onDeleteBudget={(id) => setBudgets(budgets.filter(b => b.id !== id))}
              formatCurrency={formatCurrency} 
            />
          )}
          {activeTab === 'plans' && (
            <Plans 
              currentPlan={userPlan} 
              onUpgrade={() => {
                setUserPlan('pro');
                localStorage.setItem('nova_user_plan', 'pro');
                setActiveTab('dashboard');
                setShowDangerModal(false); // Hide modal after upgrade
              }} 
            />
          )}
          {activeTab === 'settings' && (
            <Settings 
              userName={userName}
              userEmail={userEmail}
              userAvatar={userAvatar}
              userAvatarZoom={userAvatarZoom}
              userAvatarPos={userAvatarPos}
              userPlan={userPlan}
              onUpdateProfile={handleUpdateProfile} 
              addToast={addToast}
              onExportData={() => {}}
              onImportData={() => {}}
              onClearData={() => {}}
              language="en"
              onUpdateLanguage={() => {}}
              currency="USD"
              onUpdateCurrency={() => {}}
            />
          )}
        </div>
      </main>
      <ToastContainer toasts={toasts} onRemove={removeToast} />

      {/* Emergency Upsell Modal */}
      {showDangerModal && (
        <EmergencyUpsellModal 
          onClose={() => setShowDangerModal(false)} 
          onUpgrade={() => {
            setShowDangerModal(false);
            setActiveTab('plans');
          }} 
        />
      )}

      {/* Pro Feedback Floating Action Button */}
      {isPro && (
        <button
          onClick={() => setShowFeedbackModal(true)}
          className="fixed bottom-8 right-8 z-40 w-14 h-14 md:w-16 md:h-16 rounded-full bg-gradient-to-r from-indigo-600 to-violet-600 text-white shadow-[0_10px_40px_-10px_rgba(79,70,229,0.5)] border border-white/20 flex items-center justify-center hover:scale-110 active:scale-95 transition-all group overflow-hidden"
          title="Priority Coach Feedback"
        >
          <div className="absolute inset-0 bg-gradient-to-tr from-transparent via-white/20 to-transparent translate-y-full group-hover:translate-y-0 transition-transform duration-500"></div>
          <MessageSquareQuote className="w-7 h-7 md:w-8 md:h-8 fill-current" />
          <span className="absolute top-0 right-0 w-4 h-4 rounded-full bg-amber-400 border-2 border-[#020617] animate-pulse"></span>
        </button>
      )}

      {/* Feedback Modal */}
      {showFeedbackModal && (
          <FeedbackModal onClose={() => setShowFeedbackModal(false)} onSend={() => { setShowFeedbackModal(false); addToast('Feedback sent to coach priority inbox.', 'success'); }} />
      )}

    </div>
  );
};

