              userAvatar={userAvatar}
              userAvatarZoom={userAvatarZoom}
              userAvatarPos={userAvatarPos}
              userPlan={userPlan}
              onUpdateProfile={handleUpdateProfile} 
              addToast={addToast}
              onExportData={() => {}}
              onImportData={() => {}}
              onClearData={() => {}}
              language="en"
              onUpdateLanguage={() => {}}
              currency="USD"
              onUpdateCurrency={() => {}}
            />
          )}
        </div>
      </main>
      <ToastContainer toasts={toasts} onRemove={removeToast} />

      {/* Emergency Upsell Modal (Free Plan Only) */}
      {showDangerModal && (
        <EmergencyUpsellModal 
