                         )}
                    </div>
                </div>

                <h3 className="text-xl font-bold text-white">{name}</h3>
                <p className="text-slate-400 text-sm mb-4">{email}</p>

                <div className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-bold uppercase tracking-wider ${isPro ? 'bg-amber-500/10 text-amber-400 border border-amber-500/20' : 'bg-slate-700/50 text-slate-300 border border-white/5'}`}>
