import React, { useState, useMemo } from 'react';
import { Account, Budget, Transaction, TransactionType, UserPlan } from '../types';
import { Plus, Wallet, CreditCard, Landmark, TrendingUp, Edit2, Trash2, XCircle, DollarSign, AlertCircle, User as UserIcon, ArrowRightCircle } from 'lucide-react'; // Import User as UserIcon to avoid conflict with `User` in AuthPage.tsx

interface AccountsProps {
  accounts: Account[];
  budgets: Budget[];
  transactions: Transaction[];
  userPlan: UserPlan;
  onAdd: (account: Account) => void;
  onUpdate: (account: Account) => void;
  onDelete: (id: string) => void;
  formatCurrency: (amount: number) => string;
  userName: string;
  userAvatar: string;
  userAvatarZoom: number;
  userAvatarPos: { x: number; y: number };
  userBorder: string; // New prop
  onNavigate: (tab: string) => void; // New prop for routing
}

const Accounts: React.FC<AccountsProps> = ({ 
  accounts, 
  budgets, 
  transactions, 
  userPlan, 
  onAdd, 
  onUpdate, 
  onDelete, 
  formatCurrency,
  userName,
  userAvatar,
  userAvatarZoom,
  userAvatarPos,
  userBorder,
  onNavigate
}) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingAccount, setEditingAccount] = useState<Account | null>(null);

  const isPro = userPlan === 'pro';

  const netWorth = useMemo(() => accounts.reduce((acc, curr) => acc + curr.balance, 0), [accounts]);

  // AI Overspend Detection Logic
  const isRisky = useMemo(() => {
    if (!isPro) return false;
    const now = new Date();

    // Check if any budget is violated
    return budgets.some(budget => {
      const spent = transactions
        .filter(t => t.category === budget.category && 
                    t.type === TransactionType.EXPENSE && 
                    new Date(t.date).getMonth() === now.getMonth() && 
                    new Date(t.date).getFullYear() === now.getFullYear())
        .reduce((acc, t) => acc + t.amount, 0);
      return spent > budget.limit;
    });
  }, [budgets, transactions, isPro]);

  const handleEditClick = (account: Account) => {
    setEditingAccount(account);
    setIsModalOpen(true);
  };

  const handleDeleteClick = (id: string) => {
    if (window.confirm('Are you sure you want to delete this account? associated transactions will remain but balances may need adjustment.')) {
      onDelete(id);
    }
  };

  const handleModalClose = () => {
    setIsModalOpen(false);
    setEditingAccount(null);
  };

  const getAccountIcon = (type: string) => {
    switch (type) {
      case 'Checking': return <Wallet className="w-6 h-6" />;
      case 'Savings': return <Landmark className="w-6 h-6" />;
      case 'Credit Card': return <CreditCard className="w-6 h-6" />;
      case 'Investment': return <TrendingUp className="w-6 h-6" />;
      case 'Profile': return <UserIcon className="w-6 h-6" />; // Use UserIcon for profile
      default: return <Wallet className="w-6 h-6" />;
    }
  };

  const getBorderClasses = (style: string) => {
    if (!isPro && style !== 'default') return 'ring-2 ring-white/10';
    switch (style) {
      case 'gold': return 'ring-2 ring-amber-400 shadow-[0_0_15px_rgba(251,191,36,0.6)]';
      case 'rainbow': return 'ring-4 ring-transparent bg-gradient-to-tr from-rose-500 via-yellow-500 to-cyan-500 bg-[length:400%_400%] animate-gradient-xy p-[2px]';
      case 'neon': return 'ring-2 ring-cyan-400 shadow-[0_0_15px_rgba(34,211,238,0.6)]';
      case 'plasma': return 'ring-2 ring-fuchsia-500 shadow-[0_0_15px_rgba(217,70,239,0.6)]';
      default: return 'ring-2 ring-white/10';
    }
  };

  const isImageAvatar = userAvatar.includes('http') || userAvatar.startsWith('data:');

  // Static user profile account
  const userProfileAccount: Account = useMemo(() => ({
    id: 'user-profile-account',
    name: userName || 'Your Profile',
    type: 'Profile',
    balance: netWorth, // Display overall net worth here
    institution: 'Nova AI Core',
    color: '#6366f1', // A default accent color for the system account
  }), [userName, netWorth]);

  const allAccounts = useMemo(() => [...accounts, userProfileAccount], [accounts, userProfileAccount]);

  return (
    <div className="space-y-8 animate-slide-up pb-10">
      <div className="flex flex-col md:flex-row justify-between items-end gap-4">
        <div>
          <h2 className="text-3xl font-bold text-white tracking-tight">My Accounts</h2>
          <p className="text-slate-400 mt-2 font-medium">Manage your connected institutions and manual accounts.</p>
        </div>
        <button 
          onClick={() => setIsModalOpen(true)}
          className="flex items-center gap-2 bg-indigo-600 hover:bg-indigo-500 text-white px-6 py-3 rounded-full text-sm font-bold transition-all shadow-lg shadow-indigo-500/25 hover:scale-105 active:scale-95 group border border-indigo-400/20"
        >
          <Plus className="w-5 h-5 group-hover:rotate-90 transition-transform" />
          Add Account
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {allAccounts.map((acc) => {
          const isOverdrawn = acc.balance < 0;
          return (
            <div key={acc.id} className={`group glass-card p-6 rounded-[2rem] relative overflow-hidden transition-all hover:-translate-y-1 hover:shadow-xl ${acc.id === 'user-profile-account' ? 'border-amber-400/30 ring-1 ring-amber-400/20 bg-amber-500/5' : isOverdrawn ? 'border-rose-500/30 ring-1 ring-rose-500/10' : 'border-t border-white/10'}`}>
              <div 
                className="absolute top-0 right-0 w-64 h-64 opacity-10 rounded-full blur-3xl -mr-16 -mt-16 transition-opacity group-hover:opacity-20 pointer-events-none"
                style={{ backgroundColor: isOverdrawn && acc.id !== 'user-profile-account' ? '#f43f5e' : acc.color }}
              ></div>

              <div className="flex justify-between items-start mb-6 relative z-10">
                <div 
                  className={`w-14 h-14 rounded-2xl flex items-center justify-center text-white shadow-lg ${acc.id === 'user-profile-account' ? getBorderClasses(userBorder) : 'ring-1 ring-white/10'} ${acc.id === 'user-profile-account' ? userAvatar : ''} overflow-hidden`} // Apply dynamic border to profile
                  style={acc.id === 'user-profile-account' && isImageAvatar ? {backgroundColor: 'transparent'} : { backgroundColor: acc.color }}
                >
                  {acc.id === 'user-profile-account' && isImageAvatar ? (
                      <img 
                          src={userAvatar} 
                          alt="User Profile" 
                          className="w-full h-full object-cover transition-transform duration-100" 
                          style={{ 
                            transform: `scale(${userAvatarZoom}) translate(${userAvatarPos.x}px, ${userAvatarPos.y}px)`,
                          }}
                      />
                  ) : (
                      getAccountIcon(acc.type)
                  )}
                </div>
                {acc.id !== 'user-profile-account' && ( // Hide buttons for user profile account
                  <div className="flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                    <button onClick={() => handleEditClick(acc)} className="p-2 rounded-xl hover:bg-white/10 text-slate-400 hover:text-white transition-colors"><Edit2 className="w-4 h-4" /></button>
                    <button onClick={() => handleDeleteClick(acc.id)} className="p-2 rounded-xl hover:bg-rose-500/10 text-slate-400 hover:text-rose-400 transition-colors"><Trash2 className="w-4 h-4" /></button>
                  </div>
                )}
              </div>

              <div className="relative z-10">
                <p className="text-sm font-bold text-slate-400 uppercase tracking-wider mb-1">{acc.institution}</p>
                <h3 className="text-xl font-bold text-white mb-4">{acc.name}</h3>
                <div className="flex items-baseline gap-1 mb-2">
                  <span className={`text-3xl font-bold tracking-tight ${acc.balance < 0 ? 'text-rose-500' : 'text-white'}`}>
                      {formatCurrency(Math.abs(acc.balance))}
                  </span>
                  {acc.balance < 0 && <span className="text-sm text-rose-400 font-bold bg-rose-500/10 px-2 py-0.5 rounded-md border border-rose-500/20">DR</span>}
                </div>

                <div className="flex flex-wrap gap-2 mt-2 items-center">
                  <div className={`inline-flex items-center gap-2 px-3 py-1.5 rounded-lg bg-slate-800/50 border border-white/5 text-xs font-medium text-slate-300 ${acc.id === 'user-profile-account' ? 'bg-amber-500/20 border-amber-500/30 text-amber-200' : ''}`}>
                    <div className={`w-2 h-2 rounded-full ${isRisky && acc.id !== 'user-profile-account' ? 'bg-rose-500 animate-pulse' : 'bg-emerald-500'} transition-colors ${acc.id === 'user-profile-account' ? 'bg-indigo-400' : ''}`}></div>
                    {isRisky && acc.id !== 'user-profile-account' ? 'RISKY • OVERSPENT' : acc.type}
                  </div>

                  {/* Overdraft Alert & Coach Link */}
                  {isOverdrawn && acc.id !== 'user-profile-account' && (
                     <button 
                        onClick={() => onNavigate('insights')}
                        className="inline-flex items-center gap-1.5 px-3 py-1.5 bg-rose-500/10 hover:bg-rose-500/20 text-rose-400 rounded-lg border border-rose-500/20 text-[10px] font-bold uppercase tracking-widest animate-pulse transition-all group/alert"
                      >
                         <AlertCircle className="w-3 h-3" /> 
                         Consult Coach
                         <ArrowRightCircle className="w-3 h-3 opacity-0 group-hover/alert:opacity-100 transition-opacity -ml-1 group-hover/alert:ml-0" />
                     </button>
                  )}

                  {isRisky && !isOverdrawn && acc.id !== 'user-profile-account' && (
                      <div className="inline-flex items-center gap-1 px-2 py-1 bg-rose-500/20 text-rose-400 rounded-lg border border-rose-500/30 text-[10px] font-bold uppercase tracking-widest animate-fade-in">
                          <AlertCircle className="w-3 h-3" /> AI Warning
                      </div>
                  )}
                  {acc.id === 'user-profile-account' && (
                      <div className="inline-flex items-center gap-1 px-2 py-1 bg-indigo-500/20 text-indigo-400 rounded-lg border border-indigo-500/30 text-[10px] font-bold uppercase tracking-widest animate-fade-in">
                          <Wallet className="w-3 h-3" /> Net Worth
                      </div>
                  )}
                </div>
              </div>
            </div>
          )
        })}
        <button 
            onClick={() => setIsModalOpen(true)}
            className="border-2 border-dashed border-slate-700/50 rounded-[2rem] flex flex-col items-center justify-center p-8 text-slate-500 hover:border-indigo-500/50 hover:text-indigo-400 hover:bg-slate-800/30 transition-all group min-h-[240px]"
        >
            <div className="w-16 h-16 rounded-full bg-slate-800/80 group-hover:bg-indigo-500/10 flex items-center justify-center mb-5 transition-colors ring-1 ring-white/10 group-hover:ring-indigo-500/30 group-hover:scale-110 duration-300">
                <Plus className="w-8 h-8 group-hover:rotate-90 transition-transform duration-300" />
            </div>
            <span className="font-bold text-base">Connect Account</span>
        </button>
      </div>

      {isModalOpen && (
        <AccountModal 
          isOpen={isModalOpen}
          onClose={handleModalClose}
          onSubmit={editingAccount ? onUpdate : onAdd}
          initialData={editingAccount}
        />
      )}
    </div>
  );
};

interface AccountModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSubmit: (account: Account) => void;
  initialData: Account | null;
}

const AccountModal: React.FC<AccountModalProps> = ({ isOpen, onClose, onSubmit, initialData }) => {
  const [name, setName] = useState(initialData?.name || '');
  const [institution, setInstitution] = useState(initialData?.institution || '');
  const [type, setType] = useState<Account['type']>(initialData?.type || 'Checking');
  const [balance, setBalance] = useState(initialData?.balance.toString() || '');
  const [color, setColor] = useState(initialData?.color || '#3b82f6');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const account: Account = {
      id: initialData?.id || `acc_${Date.now()}`,
      name,
      institution,
      type,
      balance: parseFloat(balance) || 0,
      color
    };
    onSubmit(account);
    onClose();
  };

  const colors = ['#3b82f6', '#6366f1', '#8b5cf6', '#ec4899', '#f43f5e', '#f59e0b', '#10b981', '#06b6d4'];

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/70 backdrop-blur-md animate-fade-in">
        <div className="bg-[#0f172a] border border-white/10 rounded-3xl w-full max-w-md shadow-2xl overflow-hidden animate-slide-up relative ring-1 ring-white/5">
            <button onClick={onClose} className="absolute top-4 right-4 p-2 text-slate-400 hover:text-white z-10"><XCircle className="w-6 h-6" /></button>
            <div className="p-8 border-b border-white/5 bg-gradient-to-r from-indigo-900/20 to-transparent">
                <h3 className="text-2xl font-bold text-white flex items-center gap-2">
                   {initialData ? <Edit2 className="w-6 h-6 text-indigo-400" /> : <Plus className="w-6 h-6 text-indigo-400" />}
                   {initialData ? 'Edit Account' : 'Add Account'}
                </h3>
                <p className="text-slate-400 text-sm mt-1">Enter account details manually.</p>
            </div>
            <form onSubmit={handleSubmit} className="p-8 space-y-5">
                <div>
                    <label className="text-xs font-bold text-slate-400 uppercase tracking-wider">Account Name</label>
                    <input required type="text" value={name} onChange={e => setName(e.target.value)} className="w-full bg-slate-950/50 border border-white/10 rounded-xl p-3.5 text-white mt-2 focus:border-indigo-500 focus:outline-none focus:ring-4 focus:ring-indigo-500/10 transition-all placeholder:text-slate-600" placeholder="e.g. Primary Checking" />
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div>
                      <label className="text-xs font-bold text-slate-400 uppercase tracking-wider">Institution</label>
                      <input required type="text" value={institution} onChange={e => setInstitution(e.target.value)} className="w-full bg-slate-950/50 border border-white/10 rounded-xl p-3.5 text-white mt-2 focus:border-indigo-500 focus:outline-none focus:ring-4 focus:ring-indigo-500/10 transition-all placeholder:text-slate-600" placeholder="e.g. Chase" />
                  </div>
                  <div>
                      <label className="text-xs font-bold text-slate-400 uppercase tracking-wider">Type</label>
                      <select value={type} onChange={e => setType(e.target.value as any)} className="w-full bg-slate-950/50 border border-white/10 rounded-xl p-3.5 text-white mt-2 focus:border-indigo-500 focus:outline-none focus:ring-4 focus:ring-indigo-500/10 transition-all appearance-none cursor-pointer">
                        <option value="Checking">Checking</option>
                        <option value="Savings">Savings</option>
                        <option value="Credit Card">Credit Card</option>
                        <option value="Investment">Investment</option>
                      </select>
                  </div>
                </div>
                <div>
                    <label className="text-xs font-bold text-slate-400 uppercase tracking-wider">Current Balance</label>
                    <div className="relative mt-2">
                        <DollarSign className="absolute left-3.5 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500" />
                        <input required type="number" step="0.01" value={balance} onChange={e => setBalance(e.target.value)} className="w-full bg-slate-950/50 border border-white/10 rounded-xl p-3.5 pl-9 text-white focus:border-indigo-500 focus:outline-none focus:ring-4 focus:ring-indigo-500/10 transition-all placeholder:text-slate-600" placeholder="0.00" />
                    </div>
                </div>
                <div>
                    <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-3 block">Theme Color</label>
                    <div className="flex flex-wrap gap-3">
                      {colors.map(c => (
                        <button key={c} type="button" onClick={() => setColor(c)} className={`w-8 h-8 rounded-full transition-transform hover:scale-110 ${color === c ? 'ring-2 ring-white ring-offset-2 ring-offset-slate-900 scale-110' : ''}`} style={{ backgroundColor: c }} />
                      ))}
                    </div>
                </div>
                <button type="submit" className="w-full py-4 bg-indigo-600 hover:bg-indigo-500 text-white font-bold rounded-xl shadow-lg shadow-indigo-500/20 mt-4 active:scale-95 transition-all">
                  {initialData ? 'Update Account' : 'Create Account'}
                </button>
            </form>
        </div>
    </div>
  );
};

export default Accounts;

export enum TransactionType {
  INCOME = 'INCOME',
  EXPENSE = 'EXPENSE',
}

export enum Category {
  HOUSING = 'Housing',
  FOOD = 'Food & Dining',
  TRANSPORT = 'Transportation',
  ENTERTAINMENT = 'Entertainment',
  SHOPPING = 'Shopping',
  UTILITIES = 'Utilities',
  HEALTH = 'Health',
  INCOME = 'Income',
  INVESTMENT = 'Investment',
  OTHER = 'Other'
}

export interface Transaction {
  id: string;
  date: string;
  merchant: string;
  amount: number;
  category: Category;
  type: TransactionType;
  accountId: string;
  notes?: string; // Added optional notes field
}

export interface Account {
  id: string;
  name: string;
  nickname?: string; // Added optional nickname for AI reference
  type: 'Checking' | 'Savings' | 'Credit Card' | 'Investment' | 'Profile'; // Added 'Profile' type
  balance: number;
  institution: string;
  color: string;
}

