                </div>
                <div>
                    <label className="text-xs font-bold text-slate-400 uppercase tracking-wider flex items-center gap-2">Nickname <span className="text-[9px] bg-indigo-500/20 text-indigo-300 px-1.5 rounded">FOR AI</span></label>
