import { Transaction, TransactionType, Category, Account, UserPlan } from '../types';
import { Search, ArrowUpCircle, ArrowDownCircle, Filter, Calendar, Trash2, Tag, Plus, X, Check, DollarSign, Wallet, FileText, Sparkles, Loader2, StickyNote } from 'lucide-react';
import { categorizeTransaction } from '../services/geminiService';

interface TransactionsProps {
  transactions: Transaction[];
  accounts?: Account[]; // Made optional to prevent breaking if not passed immediately, but logic depends on it
  onDelete?: (id: string) => void;
  onAdd?: (transaction: Transaction) => void;
  formatCurrency: (amount: number) => string;
  onNavigateToAccounts?: () => void;
  userPlan?: UserPlan;
}

const Transactions: React.FC<TransactionsProps> = ({ transactions, accounts = [], onDelete, onAdd, formatCurrency, onNavigateToAccounts, userPlan }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [filterType, setFilterType] = useState<TransactionType | 'ALL'>('ALL');
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);

  const filtered = transactions.filter(t => {
    const matchesSearch = t.merchant.toLowerCase().includes(searchTerm.toLowerCase()) || 
                          t.category.toLowerCase().includes(searchTerm.toLowerCase()) ||
                          (t.notes && t.notes.toLowerCase().includes(searchTerm.toLowerCase()));
    const matchesType = filterType === 'ALL' || t.type === filterType;
    return matchesSearch && matchesType;
  });

  const getAccountName = (id: string) => {
    const acc = accounts.find(a => a.id === id);
    return acc ? acc.name : 'Unknown Account';
  };

  return (
    <div className="flex flex-col h-full animate-slide-up space-y-6 relative">
      <div className="glass-card p-4 rounded-3xl flex flex-col md:flex-row justify-between items-center gap-4">
          <div className="flex items-center gap-4 w-full md:w-auto px-2">
              <h2 className="text-lg font-bold text-white">Recent Activity</h2>
              <span className="px-3 py-1 rounded-full bg-slate-800/60 border border-white/10 text-xs font-bold text-indigo-300 shadow-inner">{filtered.length}</span>
          </div>

          <div className="flex flex-col md:flex-row gap-3 w-full md:w-auto">
            <div className="relative group flex-1 md:flex-initial">
              <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500 group-focus-within:text-indigo-400 transition-colors" />
              <input
                type="text"
                placeholder="Search merchant or notes..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full bg-slate-950/50 border border-white/10 rounded-2xl pl-10 pr-4 py-3 text-sm text-white focus:outline-none focus:border-indigo-500/50 focus:bg-slate-900/80 transition-all md:w-64 placeholder:text-slate-600 shadow-inner"
              />
            </div>

            <div className="flex gap-3">
                <div className="relative">
                    <select
                    value={filterType}
                    onChange={(e) => setFilterType(e.target.value as any)}
                    className="appearance-none bg-slate-950/50 border border-white/10 rounded-2xl pl-4 pr-10 py-3 text-sm text-white focus:outline-none focus:border-indigo-500/50 hover:bg-slate-900/80 transition-all cursor-pointer shadow-inner font-medium h-full"
                    >
                    <option value="ALL">All Types</option>
                    <option value={TransactionType.INCOME}>Income</option>
                    <option value={TransactionType.EXPENSE}>Expense</option>
                    </select>
                    <Filter className="absolute right-3.5 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-slate-500 pointer-events-none" />
                </div>

                <button 
                    onClick={() => setIsAddModalOpen(true)}
                    className="bg-indigo-600 hover:bg-indigo-500 text-white px-4 py-3 rounded-2xl font-bold text-sm shadow-lg shadow-indigo-500/20 active:scale-95 transition-all flex items-center gap-2"
                >
                    <Plus className="w-4 h-4" /> <span className="hidden md:inline">Add New</span>
                </button>
            </div>
          </div>
      </div>

      <div className="flex-1 overflow-auto custom-scrollbar space-y-3 pb-4">
          <div className="hidden md:grid grid-cols-12 px-6 py-2 text-xs font-bold text-slate-500 uppercase tracking-wider">
              <div className="col-span-2">Date</div>
              <div className="col-span-4">Merchant & Details</div>
              <div className="col-span-3">Category & Account</div>
              <div className="col-span-3 text-right">Amount</div>
          </div>

          {filtered.map(t => (
            <div 
                key={t.id} 
                className="group glass-card rounded-2xl p-4 md:px-6 md:py-4 flex flex-col md:grid md:grid-cols-12 items-center gap-4 transition-all duration-300 hover:scale-[1.005] hover:shadow-[0_10px_20px_rgba(0,0,0,0.2)] hover:bg-slate-800/40 hover:border-indigo-500/20"
            >
                <div className="w-full md:col-span-2 flex items-center gap-3 text-slate-400 order-2 md:order-1 justify-between md:justify-start">
                    <div className="flex items-center gap-2">
                         <div className="p-2 rounded-lg bg-slate-800/50 border border-white/5 group-hover:bg-slate-800 transition-colors">
                            <Calendar className="w-4 h-4 opacity-70" />
                         </div>
                         <span className="text-sm font-medium">{new Date(t.date).toLocaleDateString('en-US', { month: 'short', day: 'numeric' })}</span>
                    </div>
                     <span className={`md:hidden text-base font-bold ${t.type === TransactionType.INCOME ? 'text-emerald-400' : 'text-white'}`}>
                        {t.type === TransactionType.INCOME ? '+' : ''}
                        {formatCurrency(t.amount)}
                     </span>
                </div>

                <div className="w-full md:col-span-4 flex items-center gap-4 order-1 md:order-2">
                     <div className={`p-2.5 rounded-full border border-white/5 shadow-sm shrink-0 transition-colors ${t.type === TransactionType.INCOME ? 'bg-emerald-500/10 group-hover:bg-emerald-500/20' : 'bg-rose-500/10 group-hover:bg-rose-500/20'}`}>
                        {t.type === TransactionType.INCOME ? 
                        <ArrowUpCircle className="w-5 h-5 text-emerald-500" /> : 
                        <ArrowDownCircle className="w-5 h-5 text-rose-500" />
                        }
                    </div>
                    <div className="min-w-0">
                        <span className="block text-base font-bold text-slate-100 group-hover:text-white transition-colors truncate">{t.merchant}</span>
                        {t.notes && (
                            <div className="flex items-center gap-1 mt-0.5">
                                <StickyNote className="w-3 h-3 text-slate-600" />
                                <span className="text-xs text-slate-500 truncate max-w-[200px]">{t.notes}</span>
                            </div>
                        )}
                        <span className="md:hidden text-xs text-slate-500">{t.category} • {getAccountName(t.accountId)}</span>
                    </div>
                </div>

                <div className="hidden md:block col-span-3 order-3">
                   <div className="flex flex-col gap-1.5 items-start">
                        <span className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-semibold border shadow-sm backdrop-blur-md ${
                            t.category === 'Food & Dining' ? 'bg-orange-500/10 border-orange-500/20 text-orange-400' :
                            t.category === 'Shopping' ? 'bg-blue-500/10 border-blue-500/20 text-blue-400' :
                            t.category === 'Transportation' ? 'bg-purple-500/10 border-purple-500/20 text-purple-400' :
                            t.category === 'Income' ? 'bg-emerald-500/10 border-emerald-500/20 text-emerald-400' :
                            t.category === 'Subscription' ? 'bg-cyan-500/10 border-cyan-500/20 text-cyan-400' :
                            'bg-slate-800/50 border-slate-700 text-slate-400'
                        }`}>
                            <Tag className="w-3 h-3" />
                            {t.category}
                        </span>
                        {t.accountId !== 'manual' && (
                             <span className="inline-flex items-center gap-1.5 px-2 py-0.5 rounded-md text-[10px] font-bold text-slate-500 border border-white/5 bg-slate-900/50">
                                <Wallet className="w-3 h-3" />
                                {getAccountName(t.accountId)}
                            </span>
                        )}
                   </div>
                </div>

                <div className="hidden md:flex col-span-3 order-4 justify-end items-center gap-4">
                     <span className={`text-base font-bold tracking-tight ${t.type === TransactionType.INCOME ? 'text-emerald-400 drop-shadow-[0_0_8px_rgba(16,185,129,0.3)]' : 'text-white'}`}>
                        {t.type === TransactionType.INCOME ? '+' : ''}
                        {formatCurrency(t.amount)}
                    </span>
                    {onDelete && (
                      <button 
                        onClick={(e) => { e.stopPropagation(); onDelete(t.id); }}
                        className="p-2 text-slate-600 hover:text-rose-500 hover:bg-rose-500/10 rounded-lg transition-all opacity-0 group-hover:opacity-100 translate-x-2 group-hover:translate-x-0"
                        title="Delete"
                      >
                        <Trash2 className="w-4 h-4" />
                      </button>
                    )}
                </div>
            </div>
          ))}

          {filtered.length === 0 && (
              <div className="glass-card rounded-3xl p-16 flex flex-col items-center justify-center text-center">
                  <div className="w-20 h-20 rounded-full bg-slate-800/50 flex items-center justify-center mb-6 shadow-inner ring-1 ring-white/5">
                    <Search className="w-8 h-8 text-slate-600" />
                  </div>
                  <h3 className="text-xl font-bold text-white mb-2">No transactions found</h3>
                  <p className="text-slate-400 max-w-xs">We couldn't find any transactions matching your filters.</p>
              </div>
          )}
      </div>

      {isAddModalOpen && onAdd && (
        <AddTransactionModal 
            onClose={() => setIsAddModalOpen(false)} 
            onAdd={onAdd}
            accounts={accounts}
            onNavigateToAccounts={onNavigateToAccounts}
            userPlan={userPlan}
            formatCurrency={formatCurrency}
        />
      )}
    </div>
  );
};

const AddTransactionModal: React.FC<{ 
    onClose: () => void; 
    onAdd: (t: Transaction) => void;
    accounts: Account[];
    onNavigateToAccounts?: () => void;
    userPlan?: UserPlan;
    formatCurrency: (amount: number) => string;
}> = ({ onClose, onAdd, accounts, onNavigateToAccounts, userPlan, formatCurrency }) => {
    const [type, setType] = useState<TransactionType>(TransactionType.EXPENSE);
    const [merchant, setMerchant] = useState('');
    const [amount, setAmount] = useState('');
    const [category, setCategory] = useState<Category | ''>('');
    const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
    const [selectedAccountId, setSelectedAccountId] = useState<string>('');
    const [notes, setNotes] = useState('');
    const [isAutoCategorizing, setIsAutoCategorizing] = useState(false);

    // Categories filtered by type
    const expenseCategories = [Category.HOUSING, Category.FOOD, Category.TRANSPORT, Category.ENTERTAINMENT, Category.SHOPPING, Category.UTILITIES, Category.HEALTH, Category.SUBSCRIPTION, Category.OTHER];
    const incomeCategories = [Category.INCOME, Category.INVESTMENT, Category.OTHER];

    const hasAccounts = accounts.length > 0;
    const canAddExpense = type === TransactionType.INCOME || hasAccounts;

    const handleMerchantBlur = async () => {
        if (!merchant || isAutoCategorizing || userPlan !== 'pro' || category) return;

        setIsAutoCategorizing(true);
        try {
            // Simulate amount of 0 just for categorization context if needed, or pass current amount
            const predictedCategory = await categorizeTransaction(merchant, parseFloat(amount) || 0);

            // Check if returned string is a valid Category
            const isValidCategory = Object.values(Category).includes(predictedCategory as Category);

            if (isValidCategory) {
                setCategory(predictedCategory as Category);
            }
        } catch (error) {
            console.error("Auto-cat failed", error);
        } finally {
            setIsAutoCategorizing(false);
        }
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (!merchant || !amount || !category) return;
        if (type === TransactionType.EXPENSE && !selectedAccountId) return;

        const newTx: Transaction = {
            id: Date.now().toString(),
            date,
            merchant,
            amount: parseFloat(amount),
            category: category as Category,
            type,
            accountId: selectedAccountId || 'manual',
            notes: notes // Save the notes
        };
        onAdd(newTx);
        onClose();
    };

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/80 backdrop-blur-md animate-fade-in">
            <div className="bg-[#0f172a] border border-white/10 rounded-3xl w-full max-w-lg shadow-2xl overflow-hidden animate-slide-up relative ring-1 ring-white/5 flex flex-col max-h-[90vh]">
                <button onClick={onClose} className="absolute top-4 right-4 p-2 text-slate-400 hover:text-white z-10"><X className="w-6 h-6" /></button>

                <div className="p-8 border-b border-white/5 bg-gradient-to-r from-indigo-900/20 to-transparent flex-shrink-0">
                    <h3 className="text-2xl font-bold text-white flex items-center gap-2"><Plus className="w-6 h-6 text-indigo-400" /> New Transaction</h3>
                    <p className="text-slate-400 text-sm mt-1">Log your income or spending.</p>
                </div>

                <div className="overflow-y-auto p-8 custom-scrollbar">
                    {!canAddExpense ? (
                        <div className="text-center py-8">
                            <div className="w-16 h-16 bg-slate-800 rounded-full flex items-center justify-center mx-auto mb-4">
                                <Wallet className="w-8 h-8 text-slate-500" />
                            </div>
                            <h4 className="text-white font-bold text-lg mb-2">No Accounts Found</h4>
                            <p className="text-slate-400 text-sm mb-6">You need to add a savings or checking account before you can track expenses.</p>
                            <button 
                                onClick={() => { onClose(); if(onNavigateToAccounts) onNavigateToAccounts(); }}
                                className="px-6 py-3 bg-indigo-600 hover:bg-indigo-500 text-white font-bold rounded-xl transition-all"
                            >
                                Add Account
                            </button>
                        </div>
                    ) : (
                        <form onSubmit={handleSubmit} className="space-y-6">
                            {/* Toggle Type */}
                            <div className="flex bg-slate-900 rounded-xl p-1 border border-white/5">
                                <button 
                                    type="button" 
                                    onClick={() => { setType(TransactionType.EXPENSE); setCategory(''); }}
                                    className={`flex-1 py-3 rounded-lg text-sm font-bold transition-all ${type === TransactionType.EXPENSE ? 'bg-rose-500/10 text-rose-400 shadow-sm border border-rose-500/20' : 'text-slate-500 hover:text-slate-300'}`}
                                >
                                    Expense
                                </button>
                                <button 
                                    type="button" 
                                    onClick={() => { setType(TransactionType.INCOME); setCategory(''); }}
                                    className={`flex-1 py-3 rounded-lg text-sm font-bold transition-all ${type === TransactionType.INCOME ? 'bg-emerald-500/10 text-emerald-400 shadow-sm border border-emerald-500/20' : 'text-slate-500 hover:text-slate-300'}`}
                                >
                                    Income
                                </button>
                            </div>

                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <label className="text-xs font-bold text-slate-400 uppercase tracking-wider">Amount</label>
                                    <div className="relative mt-2">
                                        <DollarSign className="absolute left-3.5 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500" />
                                        <input 
                                            required 
                                            type="number" 
                                            step="0.01" 
                                            value={amount} 
                                            onChange={e => setAmount(e.target.value)} 
                                            className="w-full bg-slate-950/50 border border-white/10 rounded-xl p-3.5 pl-9 text-white focus:border-indigo-500 focus:outline-none focus:ring-4 focus:ring-indigo-500/10 transition-all placeholder:text-slate-600 font-mono text-lg" 
                                            placeholder="0.00" 
                                        />
                                    </div>
                                </div>
                                <div>
                                    <label className="text-xs font-bold text-slate-400 uppercase tracking-wider">Date</label>
                                    <input 
                                        required 
                                        type="date" 
                                        value={date} 
                                        onChange={e => setDate(e.target.value)} 
                                        className="w-full bg-slate-950/50 border border-white/10 rounded-xl p-3.5 text-white mt-2 focus:border-indigo-500 focus:outline-none focus:ring-4 focus:ring-indigo-500/10 transition-all [color-scheme:dark]" 
                                    />
                                </div>
                            </div>

                            <div>
                                <label className="text-xs font-bold text-slate-400 uppercase tracking-wider flex justify-between">
                                    Merchant / Source
                                    {isAutoCategorizing && <span className="text-indigo-400 flex items-center gap-1 text-[10px]"><Loader2 className="w-3 h-3 animate-spin" /> AI Categorizing...</span>}
                                </label>
                                <input 
                                    required 
                                    type="text" 
                                    value={merchant} 
                                    onChange={e => setMerchant(e.target.value)}
                                    onBlur={handleMerchantBlur}
                                    className="w-full bg-slate-950/50 border border-white/10 rounded-xl p-3.5 text-white mt-2 focus:border-indigo-500 focus:outline-none focus:ring-4 focus:ring-indigo-500/10 transition-all placeholder:text-slate-600" 
                                    placeholder={type === TransactionType.INCOME ? "e.g. Salary, Freelance" : "e.g. Starbucks, Uber"}
                                />
                            </div>

                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                <div>
                                    <label className="text-xs font-bold text-slate-400 uppercase tracking-wider">Category</label>
                                    <select 
                                        required 
                                        value={category} 
                                        onChange={e => setCategory(e.target.value as Category)} 
                                        className="w-full bg-slate-950/50 border border-white/10 rounded-xl p-3.5 text-white mt-2 focus:border-indigo-500 focus:outline-none focus:ring-4 focus:ring-indigo-500/10 transition-all appearance-none cursor-pointer"
                                    >
                                        <option value="" disabled>Select...</option>
                                        {type === TransactionType.INCOME 
                                            ? incomeCategories.map(c => <option key={c} value={c}>{c}</option>)
                                            : expenseCategories.map(c => <option key={c} value={c}>{c}</option>)
                                        }
                                    </select>
                                </div>

                                <div>
                                    <label className="text-xs font-bold text-slate-400 uppercase tracking-wider">
                                        {type === TransactionType.INCOME ? 'Deposit To' : 'Payment Method'}
                                    </label>
                                    <div className="relative mt-2">
                                        <Wallet className="absolute left-3.5 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500 pointer-events-none" />
                                        <select
                                            required={type === TransactionType.EXPENSE}
                                            value={selectedAccountId}
                                            onChange={(e) => setSelectedAccountId(e.target.value)}
                                            className="w-full bg-slate-950/50 border border-white/10 rounded-xl p-3.5 pl-10 text-white focus:border-indigo-500 focus:outline-none focus:ring-4 focus:ring-indigo-500/10 transition-all appearance-none cursor-pointer"
                                        >
                                            <option value="" disabled>Select Account</option>
                                            {accounts.map(acc => (
                                                <option key={acc.id} value={acc.id}>{acc.name} ({formatCurrency(acc.balance)})</option>
                                            ))}
                                        </select>
                                    </div>
                                </div>
                            </div>

                            <div>
                                <label className="text-xs font-bold text-slate-400 uppercase tracking-wider flex items-center gap-2">
                                    Notes / Context <span className="text-[10px] text-slate-600 font-normal lowercase">(how you lost money)</span>
                                </label>
                                <div className="relative mt-2">
                                    <FileText className="absolute left-3.5 top-3.5 w-4 h-4 text-slate-500" />
                                    <textarea
                                        value={notes}
                                        onChange={(e) => setNotes(e.target.value)}
                                        className="w-full bg-slate-950/50 border border-white/10 rounded-xl p-3.5 pl-10 text-white focus:border-indigo-500 focus:outline-none focus:ring-4 focus:ring-indigo-500/10 transition-all placeholder:text-slate-600 min-h-[100px] resize-none"
                                        placeholder="e.g. Impulse buy, forgot to cancel subscription..."
                                    />
                                </div>
                            </div>

                            <button type="submit" className="w-full py-4 bg-indigo-600 hover:bg-indigo-500 text-white font-bold rounded-xl shadow-lg shadow-indigo-500/20 active:scale-95 transition-all flex items-center justify-center gap-2">
                                <Check className="w-5 h-5" /> Save Transaction
                            </button>
                        </form>
                    )}
                </div>
            </div>
        </div>
    );
};

export default Transactions;

import React, { useState, useEffect, useMemo } from 'react';
import { Account, Budget, Goal, Transaction, UserPlan, ToastMessage, TransactionType, Category } from './types';
import { ACCOUNTS, INITIAL_TRANSACTIONS, INITIAL_BUDGETS, INITIAL_GOALS, NAV_ITEMS } from './constants';
import Dashboard from './components/Dashboard';
import Transactions from './components/Transactions';
import Accounts from './components/Accounts';
import Insights from './components/Insights';
import Goals from './components/Goals';
import Plans from './components/Plans';
import Settings from './components/Settings';
import LandingPage from './components/LandingPage';
import ToastContainer from './components/Toast';
import { Sparkles, LogOut, Ambulance, Activity, X, ArrowRight, Bell, Zap, ShieldAlert, TrendingUp, CheckCircle, ChevronRight, Send, Lock } from 'lucide-react';

// Interfaces for Nova Bot Logic
interface AiNotification {
    id: string;
    type: 'critical' | 'warning' | 'success' | 'info';
    title: string;
    message: string;
    actionLabel?: string;
    actionTab?: string;
}

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');

  // --- PERSISTENCE LAYER ---
  // Load initial state from LocalStorage or fall back to constants (which are empty now)
  const [accounts, setAccounts] = useState<Account[]>(() => {
      const saved = localStorage.getItem('nova_accounts');
      return saved ? JSON.parse(saved) : ACCOUNTS;
  });
  const [transactions, setTransactions] = useState<Transaction[]>(() => {
      const saved = localStorage.getItem('nova_transactions');
      return saved ? JSON.parse(saved) : INITIAL_TRANSACTIONS;
  });
  const [budgets, setBudgets] = useState<Budget[]>(() => {
      const saved = localStorage.getItem('nova_budgets');
      return saved ? JSON.parse(saved) : INITIAL_BUDGETS;
  });
  const [goals, setGoals] = useState<Goal[]>(() => {
      const saved = localStorage.getItem('nova_goals');
      return saved ? JSON.parse(saved) : INITIAL_GOALS;
  });

  const [userPlan, setUserPlan] = useState<UserPlan>(() => localStorage.getItem('nova_user_plan') as UserPlan || 'free');
  const [isLoggedIn, setIsLoggedIn] = useState(() => localStorage.getItem('nova_auth_token') !== null);
  const [toasts, setToasts] = useState<ToastMessage[]>([]);
  const [showDangerModal, setShowDangerModal] = useState(false);
  const [showCoachLockModal, setShowCoachLockModal] = useState(false);

  // Bot States
  const [showBotPanel, setShowBotPanel] = useState(false);
  const [botNotifications, setBotNotifications] = useState<AiNotification[]>([]);

  const [userName, setUserName] = useState(() => localStorage.getItem('nova_user_name') || '');
  const [userEmail, setUserEmail] = useState(() => localStorage.getItem('nova_user_email') || 'pilot@nova.io');
  const [userAvatar, setUserAvatar] = useState(() => localStorage.getItem('nova_user_avatar') || 'bg-indigo-600');
  const [userAvatarZoom, setUserAvatarZoom] = useState(() => parseFloat(localStorage.getItem('nova_user_avatar_zoom') || '1'));
  const [userAvatarPos, setUserAvatarPos] = useState(() => {
    const x = parseFloat(localStorage.getItem('nova_user_avatar_pos_x') || '0');
    const y = parseFloat(localStorage.getItem('nova_user_avatar_pos_y') || '0');
    return { x, y };
  });
  const [userBorder, setUserBorder] = useState(() => localStorage.getItem('nova_user_border') || 'default');

  // --- AUTO-SAVE EFFECTS ---
  useEffect(() => { localStorage.setItem('nova_accounts', JSON.stringify(accounts)); }, [accounts]);
  useEffect(() => { localStorage.setItem('nova_transactions', JSON.stringify(transactions)); }, [transactions]);
  useEffect(() => { localStorage.setItem('nova_budgets', JSON.stringify(budgets)); }, [budgets]);
  useEffect(() => { localStorage.setItem('nova_goals', JSON.stringify(goals)); }, [goals]);

  const addToast = (message: string, type: ToastMessage['type'] = 'success') => {
    const id = Date.now().toString();
    setToasts(prev => [...prev, { id, message, type }]);
  };

  const removeToast = (id: string) => {
    setToasts(prev => prev.filter(toast => toast.id !== id));
  };

  const formatCurrency = (amount: number) => `$${amount.toLocaleString()}`;

  const handleAddAccount = (acc: Account) => setAccounts([...accounts, acc]);
  const handleUpdateAccount = (acc: Account) => setAccounts(accounts.map(a => a.id === acc.id ? acc : a));
  const handleDeleteAccount = (id: string) => setAccounts(accounts.filter(a => a.id !== id));

  const handleAddTransaction = (t: Transaction) => {
    setTransactions(prev => [t, ...prev]);
    if (t.accountId && t.accountId !== 'manual') {
      setAccounts(prev => prev.map(acc => {
        if (acc.id === t.accountId) {
          const newBalance = t.type === TransactionType.EXPENSE
            ? acc.balance - t.amount
            : acc.balance + t.amount;
          return { ...acc, balance: newBalance };
        }
        return acc;
      }));
    }
    addToast('Transaction recorded & Balance updated.', 'success');
  };

  const handleDeleteTransaction = (id: string) => {
    const txToDelete = transactions.find(t => t.id === id);
    setTransactions(prev => prev.filter(t => t.id !== id));
    if (txToDelete && txToDelete.accountId && txToDelete.accountId !== 'manual') {
      setAccounts(prev => prev.map(acc => {
        if (acc.id === txToDelete.accountId) {
          const newBalance = txToDelete.type === TransactionType.EXPENSE
            ? acc.balance + txToDelete.amount
            : acc.balance - txToDelete.amount;
          return { ...acc, balance: newBalance };
        }
        return acc;
      }));
    }
    addToast('Transaction removed & Balance reverted.', 'info');
  };

  const handleBatchCategoryUpdate = (merchant: string, category: Category) => {
    // Case-insensitive matching for batch update
    const normalizedMerchant = merchant.toLowerCase().trim();
    setTransactions(prev => prev.map(t => 
        t.merchant.toLowerCase().trim() === normalizedMerchant ? { ...t, category } : t
    ));
    addToast(`All transactions for ${merchant} marked as ${category}`, 'success');
  };

  const handleUpdateProfile = (name: string, email: string, avatar: string, zoom: number, pos: { x: number; y: number }, border: string) => {
    setUserName(name);
    setUserEmail(email);
    setUserAvatar(avatar);
    setUserAvatarZoom(zoom);
    setUserAvatarPos(pos);
    setUserBorder(border);

    try {
      localStorage.setItem('nova_user_name', name);
      localStorage.setItem('nova_user_email', email);
      localStorage.setItem('nova_user_avatar', avatar);
      localStorage.setItem('nova_user_avatar_zoom', zoom.toString());
      localStorage.setItem('nova_user_avatar_pos_x', pos.x.toString());
      localStorage.setItem('nova_user_avatar_pos_y', pos.y.toString());
      localStorage.setItem('nova_user_border', border);
    } catch (e) {
      addToast("Storage full. Image may not persist.", "error");
    }
  };

  const handleSignOut = () => {
    // Only remove auth, keep data
    localStorage.removeItem('nova_auth_token');
    localStorage.removeItem('nova_user_name');
    localStorage.removeItem('nova_user_email');
    localStorage.removeItem('nova_user_avatar');
    setIsLoggedIn(false);
  };

  const handleClearData = () => {
      // Nuclear Reset
      localStorage.removeItem('nova_accounts');
      localStorage.removeItem('nova_transactions');
      localStorage.removeItem('nova_budgets');
      localStorage.removeItem('nova_goals');

      setAccounts([]);
      setTransactions([]);
      setBudgets([]);
      setGoals([]);
      addToast("Core data system wiped. Starting fresh.", "error");
  };

  // --- NOVA INTELLIGENCE SYSTEM ---
  useEffect(() => {
      const generateNotifications = () => {
          const notes: AiNotification[] = [];
          const now = new Date();

          const netWorth = accounts.reduce((acc, curr) => acc + curr.balance, 0);
          if (netWorth < 0) {
              notes.push({
                  id: 'risk-nw',
                  type: 'critical',
                  title: 'Net Worth Critical',
                  message: 'Your liabilities exceed your assets. Immediate intervention recommended.',
                  actionLabel: 'View Analysis',
                  actionTab: 'insights'
              });
              // Pro users don't see the sales modal, but free users do
              if (userPlan !== 'pro') setShowDangerModal(true);
          }

          budgets.forEach(budget => {
              const spent = transactions
                  .filter(t => t.category === budget.category && 
                              t.type === TransactionType.EXPENSE && 
                              new Date(t.date).getMonth() === now.getMonth() && 
                              new Date(t.date).getFullYear() === now.getFullYear())
                  .reduce((acc, t) => acc + t.amount, 0);

              if (spent > budget.limit) {
                  notes.push({
                      id: `over-${budget.id}`,
                      type: 'critical',
                      title: 'Budget Breached',
                      message: `You have exceeded your limit for ${budget.category} by ${formatCurrency(spent - budget.limit)}. Stop spending now.`,
                      actionLabel: 'Adjust Budget',
                      actionTab: 'goals'
                  });
              } else if (spent > budget.limit * 0.85) {
                   notes.push({
                      id: `warn-${budget.id}`,
                      type: 'warning',
                      title: 'Budget at Risk',
                      message: `You are at 85% of your ${budget.category} limit. Slow down.`,
                      actionLabel: 'Check Spending',
                      actionTab: 'transactions'
                  });
              }
          });

          goals.forEach(goal => {
              const progress = goal.currentAmount / goal.targetAmount;
              if (progress >= 1 && goal.currentAmount > 0) {
                  notes.push({
                      id: `goal-${goal.id}`,
                      type: 'success',
                      title: 'Goal Achieved!',
                      message: `Outstanding work. You've fully funded "${goal.name}". Set a new target to keep the momentum.`,
                      actionLabel: 'New Goal',
                      actionTab: 'goals'
                  });
              } else if (progress > 0.5 && progress < 0.6) {
                   notes.push({
                      id: `prog-${goal.id}`,
                      type: 'info',
                      title: 'Halfway There',
                      message: `You're over 50% of the way to "${goal.name}". Consistency is key. Keep pushing.`,
                  });
              }
          });

          if (transactions.length === 0) {
               notes.push({
                  id: 'empty-state',
                  type: 'info',
                  title: 'System Idle',
                  message: 'No financial data detected. Feed the system transactions to generate insights.',
                  actionLabel: 'Log Expense',
                  actionTab: 'transactions'
              });
          }

          setBotNotifications(notes);
      };

      generateNotifications();
  }, [accounts, transactions, budgets, goals, userPlan]);

  if (!isLoggedIn) {
    return <LandingPage onLoginSuccess={(name) => { setUserName(name); setIsLoggedIn(true); }} />;
  }

  const isPro = userPlan === 'pro';
  const isImageAvatar = userAvatar.includes('http') || userAvatar.startsWith('data:');
  const filteredNavItems = NAV_ITEMS.filter(item => !(isPro && item.id === 'plans'));

  const hasCritical = botNotifications.some(n => n.type === 'critical');
  const hasSuccess = botNotifications.some(n => n.type === 'success');
  const notificationCount = botNotifications.length;

  const getBorderClasses = (style: string) => {
    if (!isPro && style !== 'default') return 'ring-2 ring-white/10'; // Fallback if user downgrades
    switch (style) {
      case 'gold': return 'ring-2 ring-amber-400 shadow-[0_0_15px_rgba(251,191,36,0.6)]';
      case 'rainbow': return 'ring-4 ring-transparent bg-gradient-to-tr from-rose-500 via-yellow-500 to-cyan-500 bg-[length:400%_400%] animate-gradient-xy p-[2px]';
      case 'neon': return 'ring-2 ring-cyan-400 shadow-[0_0_15px_rgba(34,211,238,0.6)]';
      case 'plasma': return 'ring-2 ring-fuchsia-500 shadow-[0_0_15px_rgba(217,70,239,0.6)]';
      default: return 'ring-1 ring-white/20';
    }
  };

  return (
    <div className="flex h-screen bg-[#020617] text-slate-200 font-sans">
      <aside className="w-64 bg-[#0f172a] border-r border-white/5 p-6 flex flex-col hidden md:flex">
        <div className="flex items-center gap-3 mb-12 relative group">
          <div className={`
            w-10 h-10 rounded-xl flex items-center justify-center shadow-lg transition-all duration-700
            ${isPro
                ? 'bg-gradient-to-br from-amber-300 via-amber-500 to-orange-700 shadow-[0_0_30px_rgba(251,191,36,0.8)] ring-2 ring-white/80 relative overflow-hidden'
                : 'bg-indigo-600 shadow-indigo-600/20'
            }`}
          >
            {isPro ? (
                <>
                    <Sparkles className="w-7 h-7 text-white drop-shadow-[0_0_10px_rgba(255,255,255,0.8)] relative z-10" />
                </>
            ) : (
                <span className="text-white font-black text-lg">N</span>
            )}
          </div>
          <div>
            <h1 className="text-xl font-black tracking-tighter text-white">Nova AI</h1>
            {isPro && (
                <div className="absolute -top-1 -right-4">
                  <span className="bg-gradient-to-r from-amber-400 to-orange-500 text-white text-[8px] font-black px-1.5 py-0.5 rounded border border-amber-500/20 shadow-md shadow-amber-500/30 uppercase tracking-widest">PRO</span>
                </div>
            )}
          </div>
        </div>
        <nav className="flex-1 space-y-1">
          {filteredNavItems.map(item => (
            <button
              key={item.id}
              onClick={() => setActiveTab(item.id)}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-semibold transition-all ${
                activeTab === item.id 
                  ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-600/20' 
                  : 'text-slate-400 hover:text-white hover:bg-white/5'
              }`}
            >
              <item.icon className="w-5 h-5" />
              {item.label}
            </button>
          ))}
        </nav>

        {/* User Profile Footer */}
        <div className="mt-auto pt-6 border-t border-white/5 space-y-3">
             <div 
                className="flex items-center gap-3 p-3 rounded-2xl bg-white/5 border border-white/5 hover:bg-white/10 transition-colors cursor-pointer group relative overflow-hidden"
                onClick={() => setActiveTab('settings')}
             >
                <div className={`w-10 h-10 rounded-full bg-slate-800 shrink-0 overflow-hidden relative shadow-sm transition-all ${getBorderClasses(userBorder)}`}>
                    {isImageAvatar ? (
                         <img 
                            src={userAvatar} 
                            alt="Profile"
                            className="w-full h-full object-cover"
                            style={{ 
                                transform: `scale(${userAvatarZoom}) translate(${userAvatarPos.x}px, ${userAvatarPos.y}px)` 
                            }}
                         />
                    ) : (
                        <div className={`w-full h-full ${userAvatar}`}></div>
                    )}
                </div>
                <div className="min-w-0 flex-1">
                    <h4 className="text-sm font-bold text-white truncate">{userName || 'Nova Pilot'}</h4>
                    <div className="flex items-center gap-2 mt-0.5">
                        <span className={`text-[9px] font-black px-1.5 py-0.5 rounded border uppercase tracking-widest ${isPro ? 'bg-amber-500/10 text-amber-400 border-amber-500/20' : 'bg-slate-700/50 text-slate-400 border-slate-600/50'}`}>
                            {isPro ? 'PRO PLAN' : 'FREE'}
                        </span>
                    </div>
                </div>
             </div>

             <button 
                onClick={handleSignOut}
                className="w-full flex items-center justify-center gap-2 p-2 text-xs font-bold text-slate-500 hover:text-rose-400 hover:bg-rose-500/10 rounded-lg transition-colors group"
             >
                <LogOut className="w-3.5 h-3.5 group-hover:translate-x-0.5 transition-transform" /> Sign Out
             </button>
        </div>
      </aside>

      <main className="flex-1 overflow-auto p-4 md:p-10 bg-[#020617] relative">
        <div className="max-w-7xl mx-auto pb-20 md:pb-0">
            {/* Mobile Header */}
            <div className="md:hidden flex justify-between items-center mb-6">
                <div className="flex items-center gap-2">
                    <div className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center font-black text-white">N</div>
                    <span className="font-bold text-white">Nova AI</span>
                </div>
                 <div className="flex gap-2">
                     {NAV_ITEMS.slice(0, 3).map(item => (
                         <button key={item.id} onClick={() => setActiveTab(item.id)} className={`p-2 rounded-lg ${activeTab === item.id ? 'bg-indigo-600 text-white' : 'bg-slate-800 text-slate-400'}`}>
                             <item.icon className="w-5 h-5" />
                         </button>
                     ))}
                 </div>
            </div>

          {activeTab === 'dashboard' && (
            <Dashboard 
              accounts={accounts} 
              transactions={transactions} 
              onNavigate={setActiveTab}
              onAddAccount={() => setActiveTab('accounts')}
              onAddTransaction={() => setActiveTab('transactions')}
              onAddGoal={() => setActiveTab('goals')}
              onBatchCategoryUpdate={handleBatchCategoryUpdate} // Pass handler
              formatCurrency={formatCurrency} 
            />
          )}
          {activeTab === 'transactions' && (
            <Transactions 
              transactions={transactions} 
              accounts={accounts}
              onDelete={handleDeleteTransaction}
              onAdd={handleAddTransaction}
              formatCurrency={formatCurrency}
              onNavigateToAccounts={() => setActiveTab('accounts')}
              userPlan={userPlan}
            />
          )}
          {activeTab === 'accounts' && (
              <Accounts 
                  accounts={accounts} 
                  budgets={budgets}
                  transactions={transactions}
                  userPlan={userPlan}
                  onAdd={handleAddAccount}
                  onUpdate={handleUpdateAccount}
                  onDelete={handleDeleteAccount}
                  formatCurrency={formatCurrency}
                  userName={userName}
                  userAvatar={userAvatar}
                  userAvatarZoom={userAvatarZoom}
                  userAvatarPos={userAvatarPos}
                  userBorder={userBorder}
                  onNavigate={setActiveTab}
              />
          )}
          {activeTab === 'insights' && (
            <Insights 
              transactions={transactions} 
              userPlan={userPlan} 
              onUpgradeClick={() => setActiveTab('plans')}
              formatCurrency={formatCurrency} 
            />
          )}
          {activeTab === 'goals' && (
            <Goals 
              goals={goals} 
              budgets={budgets} 
              transactions={transactions}
              onAddGoal={(g) => setGoals([...goals, g])}
              onUpdateGoal={(g) => setGoals(goals.map(prev => prev.id === g.id ? g : prev))}
              onAddBudget={(b) => setBudgets([...budgets, b])}
              onDeleteBudget={(id) => setBudgets(budgets.filter(b => b.id !== id))}
              formatCurrency={formatCurrency} 
            />
          )}
          {activeTab === 'plans' && (
            <Plans 
              currentPlan={userPlan} 
              onUpgrade={() => {
                setUserPlan('pro');
                localStorage.setItem('nova_user_plan', 'pro');
                setActiveTab('dashboard');
                setShowDangerModal(false); 
                setShowCoachLockModal(false);
              }} 
            />
          )}
          {activeTab === 'settings' && (
            <Settings 
              userName={userName}
              userEmail={userEmail}
              userAvatar={userAvatar}
              userAvatarZoom={userAvatarZoom}
              userAvatarPos={userAvatarPos}
              userBorder={userBorder}
              userPlan={userPlan}
              onUpdateProfile={handleUpdateProfile} 
              addToast={addToast}
              onExportData={() => {}}
              onImportData={() => {}}
              onClearData={handleClearData} // Pass the new logic
              language="en"
              onUpdateLanguage={() => {}}
              currency="USD"
              onUpdateCurrency={() => {}}
            />
          )}
        </div>
      </main>
      <ToastContainer toasts={toasts} onRemove={removeToast} />

      {/* Emergency Upsell Modal (Critical Risk) */}
      {showDangerModal && (
        <EmergencyUpsellModal 
          onClose={() => setShowDangerModal(false)} 
          onUpgrade={() => {
            setShowDangerModal(false);
            setActiveTab('plans');
          }} 
        />
      )}

      {/* Coach Lock Upsell Modal (Feature Lock) */}
      {showCoachLockModal && (
        <CoachLockModal 
          onClose={() => setShowCoachLockModal(false)} 
          onUpgrade={() => {
            setShowCoachLockModal(false);
            setActiveTab('plans');
          }} 
        />
      )}

      {/* --- NOVA BOT NOTIFICATION SYSTEM --- */}
      <div className="fixed bottom-6 right-6 z-[100] flex flex-col items-end">

          {/* Notification Stream Panel (Only show if Pro) */}
          {showBotPanel && isPro && (
              <div className="mb-4 w-80 md:w-96 glass-card rounded-3xl border border-white/20 overflow-hidden shadow-2xl animate-slide-up origin-bottom-right">
                  <div className={`p-4 flex items-center justify-between border-b border-white/10 bg-gradient-to-r ${hasCritical ? 'from-rose-900/80 to-slate-900' : 'from-indigo-900/80 to-slate-900'}`}>
                      <div className="flex items-center gap-3">
                          <div className={`w-8 h-8 rounded-full flex items-center justify-center ${hasCritical ? 'bg-rose-500 animate-pulse' : 'bg-indigo-500'}`}>
                              <Zap className="w-5 h-5 text-white fill-white" />
                          </div>
                          <div>
                              <h3 className="text-white font-bold text-sm">Nova Command</h3>
                              <p className="text-[10px] text-slate-300 font-bold uppercase tracking-wider">{hasCritical ? 'Alerts Active' : 'System Nominal'}</p>
                          </div>
                      </div>
                      <button onClick={() => setShowBotPanel(false)} className="text-white/50 hover:text-white"><X className="w-5 h-5" /></button>
                  </div>

                  <div className="max-h-[60vh] overflow-y-auto custom-scrollbar bg-[#0f172a]/95">
                      {botNotifications.length === 0 ? (
                          <div className="p-8 text-center">
                              <ShieldAlert className="w-10 h-10 text-slate-600 mx-auto mb-3" />
                              <p className="text-slate-400 text-xs">No active directives. You are running optimally.</p>
                          </div>
                      ) : (
                          <div className="flex flex-col">
                              {botNotifications.map((note) => (
                                  <div key={note.id} className={`p-5 border-b border-white/5 last:border-0 hover:bg-white/5 transition-colors ${note.type === 'critical' ? 'bg-rose-500/10' : note.type === 'success' ? 'bg-emerald-500/5' : ''}`}>
                                      <div className="flex gap-3 mb-2">
                                          {note.type === 'critical' && <ShieldAlert className="w-5 h-5 text-rose-500 shrink-0" />}
                                          {note.type === 'warning' && <Activity className="w-5 h-5 text-amber-500 shrink-0" />}
                                          {note.type === 'success' && <CheckCircle className="w-5 h-5 text-emerald-400 shrink-0" />}
                                          {note.type === 'info' && <Bell className="w-5 h-5 text-blue-400 shrink-0" />}
                                          <h4 className={`text-sm font-bold ${note.type === 'critical' ? 'text-rose-400' : 'text-white'}`}>{note.title}</h4>
                                      </div>
                                      <p className="text-xs text-slate-300 leading-relaxed mb-3 pl-8">{note.message}</p>
                                      {note.actionLabel && (
                                          <div className="pl-8">
                                              <button 
                                                onClick={() => {
                                                    if (note.actionTab) setActiveTab(note.actionTab);
                                                    setShowBotPanel(false);
                                                }}
                                                className={`text-[10px] font-bold uppercase tracking-wider flex items-center gap-1 hover:underline ${note.type === 'critical' ? 'text-rose-400' : 'text-indigo-400'}`}
                                              >
                                                  {note.actionLabel} <ChevronRight className="w-3 h-3" />
                                              </button>
                                          </div>
                                      )}
                                  </div>
                              ))}
                          </div>
                      )}
                  </div>
              </div>
          )}

          {/* THE NOVA BOT AVATAR */}
          <button 
            onClick={() => {
                if (isPro) {
                    setShowBotPanel(!showBotPanel);
                } else {
                    setShowCoachLockModal(true);
                }
            }}
            className="relative group cursor-pointer focus:outline-none"
          >
              {/* Alert Ripple Effect - Only for Pro */}
              {isPro && hasCritical && (
                  <>
                    <span className="absolute inline-flex h-full w-full rounded-full bg-rose-500 opacity-20 animate-[ping_1.5s_ease-in-out_infinite]"></span>
                    <span className="absolute inline-flex h-full w-full rounded-full bg-rose-500 opacity-10 animate-[ping_2s_ease-in-out_infinite] delay-75"></span>
                  </>
              )}

              {/* Bot Body Container */}
              <div className={`
                relative w-14 h-14 rounded-2xl flex items-center justify-center transition-all duration-300 shadow-[0_10px_30px_-10px_rgba(0,0,0,0.5)] border
                ${!isPro 
                    ? 'bg-slate-800 border-white/10 shadow-black/50 hover:scale-105'
                    : hasCritical 
                        ? 'bg-gradient-to-br from-rose-900 to-slate-900 border-rose-500/50 shadow-rose-500/30 hover:scale-105 animate-[shake_0.5s_ease-in-out_infinite]' 
                        : hasSuccess
                            ? 'bg-gradient-to-br from-emerald-900 to-slate-900 border-emerald-500/50 shadow-emerald-500/30 hover:scale-110 animate-float'
                            : 'bg-gradient-to-br from-indigo-600 to-violet-900 border-white/20 shadow-indigo-500/40 hover:scale-110 animate-float'
                }
              `}>
                  {/* Bot Head Design */}
                  <div className={`relative z-10 w-8 h-5 rounded-lg backdrop-blur-sm border flex items-center justify-center gap-1 overflow-hidden ${!isPro ? 'bg-slate-700/50 border-white/5' : 'bg-black/40 border-white/10'}`}>
                       {/* Bot Eyes */}
                       {!isPro ? (
                           <Lock className="w-3 h-3 text-slate-400" />
                       ) : (
                           <>
                            <div className={`w-1.5 h-1.5 rounded-full ${hasCritical ? 'bg-rose-500 animate-[pulse_0.2s_infinite]' : 'bg-cyan-400 animate-[pulse_4s_infinite]'}`}></div>
                            <div className={`w-1.5 h-1.5 rounded-full ${hasCritical ? 'bg-rose-500 animate-[pulse_0.2s_infinite]' : 'bg-cyan-400 animate-[pulse_4s_infinite]'}`}></div>
                           </>
                       )}
                  </div>

                  {/* Antenna */}
                  <div className="absolute -top-3 left-1/2 -translate-x-1/2 flex flex-col items-center">
                      <div className={`w-1.5 h-1.5 rounded-full mb-0.5 ${!isPro ? 'bg-slate-600' : hasCritical ? 'bg-rose-500 animate-ping' : 'bg-white/80 animate-pulse'}`}></div>
                      <div className={`w-0.5 h-2 ${!isPro ? 'bg-slate-700' : 'bg-white/30'}`}></div>
                  </div>

                  {/* Notification Badge */}
                  {isPro && notificationCount > 0 && (
                      <div className={`absolute -top-1 -right-1 min-w-[18px] h-[18px] px-1 rounded-full flex items-center justify-center text-[10px] font-bold text-white border border-[#020617] z-20 ${hasCritical ? 'bg-rose-500' : 'bg-amber-500'}`}>
                          {notificationCount}
                      </div>
                  )}

                  {/* Lock Badge for Free Plan */}
                  {!isPro && (
                       <div className="absolute -bottom-1 -right-1 w-5 h-5 rounded-full bg-slate-700 border border-[#020617] flex items-center justify-center text-[10px] font-bold text-slate-400 z-20">
                          <Lock className="w-3 h-3" />
                      </div>
                  )}
              </div>
          </button>
      </div>

    </div>
  );
};

// Internal Component for Critical Alert
const EmergencyUpsellModal: React.FC<{ onClose: () => void, onUpgrade: () => void }> = ({ onClose, onUpgrade }) => {
    return (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/90 backdrop-blur-xl animate-fade-in">
             <div className="relative max-w-lg w-full bg-[#0f172a] rounded-[2rem] border-2 border-rose-500 shadow-[0_0_100px_rgba(244,63,94,0.3)] overflow-hidden animate-slide-up">
                 {/* Emergency Header */}
                 <div className="bg-rose-600 p-6 flex items-center gap-4 relative overflow-hidden">
                      <div className="absolute inset-0 bg-[linear-gradient(45deg,transparent_25%,rgba(255,255,255,0.1)_50%,transparent_75%)] bg-[length:20px_20px] animate-shimmer-fast opacity-30"></div>
                      <div className="p-3 bg-white/20 rounded-xl backdrop-blur-sm animate-pulse shadow-inner">
                          <Ambulance className="w-8 h-8 text-white" />
                      </div>
                      <div>
                          <h2 className="text-2xl font-black text-white uppercase tracking-tighter">Medical Alert</h2>
