                 </button>
                 <button onClick={onAddTransaction} className="group glass-card p-8 rounded-[2rem] text-left border border-white/5 hover:border-emerald-500/30 transition-all hover:-translate-y-2 hover:shadow-2xl">
                    <div className="w-14 h-14 rounded-2xl bg-emerald-500/10 flex items-center justify-center mb-6 group-hover:bg-emerald-500 group-hover:text-white transition-colors text-emerald-400 shadow-inner"><PlusCircle className="w-7 h-7" /></div>
                    <h3 className="text-xl font-bold text-white mb-2">Log Transaction</h3>
                    <p className="text-slate-400 text-sm leading-relaxed">Start tracking your daily income and expenses manually to build a history.</p>
                 </button>
                 <button onClick={onAddGoal} className="group glass-card p-8 rounded-[2rem] text-left border border-white/5 hover:border-rose-500/30 transition-all hover:-translate-y-2 hover:shadow-2xl">
                    <div className="w-14 h-14 rounded-2xl bg-rose-500/10 flex items-center justify-center mb-6 group-hover:bg-rose-500 group-hover:text-white transition-colors text-rose-400 shadow-inner"><Target className="w-7 h-7" /></div>
                    <h3 className="text-xl font-bold text-white mb-2">Set Goals</h3>
                    <p className="text-slate-400 text-sm leading-relaxed">Define your financial targets and let Nova help you save for the future.</p>
                 </button>
            </div>
        </div>
     );
  }

  return (
    <div className="space-y-6 animate-slide-up">
      {/* Top Metrics Row */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
