export default Dashboard;

import React, { useMemo } from 'react';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import { Account, Transaction, TransactionType, Category } from '../types';
import { ArrowUpRight, DollarSign, Activity, Layers, Flame, TrendingUp, MoreHorizontal, ArrowRight, Wallet, PlusCircle, CreditCard, Target, ChevronRight, Quote, Landmark, Zap, Radio, RefreshCw, Repeat, Check } from 'lucide-react';

interface DashboardProps {
  accounts: Account[];
  transactions: Transaction[];
  onNavigate: (tab: string) => void;
  onAddAccount?: () => void;
  onAddTransaction?: () => void;
  onAddGoal?: () => void;
  formatCurrency: (amount: number) => string;
  onBatchCategoryUpdate?: (merchant: string, category: Category) => void; // New prop
}

const COLORS = ['#6366f1', '#ec4899', '#10b981', '#f59e0b', '#8b5cf6', '#3b82f6'];

const QUOTES = [
  { text: "Do not save what is left after spending, but spend what is left after saving.", author: "Warren Buffett" },
  { text: "A budget is telling your money where to go instead of wondering where it went.", author: "Dave Ramsey" },
  { text: "It's not your salary that makes you rich, it's your spending habits.", author: "Charles A. Jaffe" },
  { text: "The art is not in making money, but in keeping it.", author: "Proverb" },
];

const Dashboard: React.FC<DashboardProps> = ({ accounts, transactions, onNavigate, onAddAccount, onAddTransaction, onAddGoal, formatCurrency, onBatchCategoryUpdate }) => {
  const hasData = accounts.length > 0 || transactions.length > 0;
  const randomQuote = useMemo(() => QUOTES[Math.floor(Math.random() * QUOTES.length)], []);
  const netWorth = useMemo(() => accounts.reduce((acc, curr) => acc + curr.balance, 0), [accounts]);

  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const currentMonth = today.getMonth();
  const currentYear = today.getFullYear();
  const dayOfMonth = today.getDate();
  const daysInMonth = new Date(currentYear, currentMonth + 1, 0).getDate();

  const monthlySpending = useMemo(() => {
    return transactions
      .filter(t => {
        const d = new Date(t.date);
        return t.type === TransactionType.EXPENSE && d.getMonth() === currentMonth && d.getFullYear() === currentYear;
      })
      .reduce((acc, curr) => acc + curr.amount, 0);
  }, [transactions, currentMonth, currentYear]);

  const monthlyIncome = useMemo(() => {
    return transactions
      .filter(t => {
        const d = new Date(t.date);
        return t.type === TransactionType.INCOME && d.getMonth() === currentMonth && d.getFullYear() === currentYear;
      })
      .reduce((acc, curr) => acc + curr.amount, 0);
  }, [transactions, currentMonth, currentYear]);

  const burnRate = monthlySpending / Math.max(dayOfMonth, 1);

  // --- Recurring Expense Logic (Vampire Detector v3) ---
  const recurringData = useMemo(() => {
      // Key: Normalized merchant name (lowercase, trimmed)
      // Value: Stats
      const merchantMap = new Map<string, { 
          count: number; 
          total: number; 
          amounts: number[]; 
          displayNames: string[]; 
          categories: Set<Category>; // Track all categories used for this merchant
      }>();

      transactions
        .filter(t => t.type === TransactionType.EXPENSE)
        .forEach(t => {
            const normalizedKey = t.merchant.toLowerCase().trim();
            const existing = merchantMap.get(normalizedKey) || { 
                count: 0, 
                total: 0, 
                amounts: [], 
                displayNames: [], 
                categories: new Set() 
            };

            existing.count++;
            existing.total += t.amount;
            existing.amounts.push(t.amount);
            existing.displayNames.push(t.merchant);
            existing.categories.add(t.category);

            merchantMap.set(normalizedKey, existing);
        });

      const recurringItems: { merchant: string; avgCost: number; frequency: string; isSubscription: boolean }[] = [];
      let totalMonthlyFixed = 0;

      merchantMap.forEach((data, key) => {
          const avg = data.total / data.count;

          // 1. Is it explicitly tagged as a subscription in ANY transaction?
          const isExplicitSubscription = data.categories.has(Category.SUBSCRIPTION);

          // 2. Is it a detected recurring pattern? (Count > 1 AND consistent amount)
          const isConsistent = data.amounts.every(a => Math.abs(a - avg) / avg < 0.25); // 25% variance
          const hasExactMatches = new Set(data.amounts).size < data.amounts.length;
          const isDetectedPattern = data.count > 1 && (isConsistent || hasExactMatches);

          if (isExplicitSubscription || isDetectedPattern) {
              // Find most common display name
              const nameCounts = data.displayNames.reduce((acc, name) => {
                  acc[name] = (acc[name] || 0) + 1;
                  return acc;
              }, {} as Record<string, number>);
              const bestName = Object.keys(nameCounts).reduce((a, b) => nameCounts[a] > nameCounts[b] ? a : b);

              recurringItems.push({
                  merchant: bestName,
                  avgCost: avg,
                  frequency: 'Monthly',
                  isSubscription: isExplicitSubscription
              });
              totalMonthlyFixed += avg;
          }
      });

      return { items: recurringItems.sort((a,b) => b.avgCost - a.avgCost), total: totalMonthlyFixed };
  }, [transactions]);

  const spendingData = useMemo(() => {
    const dataPoints: { date: string, actual: number | null, predicted: number | null, timestamp: number }[] = [];

    // 1. Map existing expenses
    const expenseMap = new Map<string, number>();
    transactions
      .filter(t => t.type === TransactionType.EXPENSE)
      .forEach(t => {
        const d = new Date(t.date);
        d.setHours(0, 0, 0, 0);
        const key = d.toDateString();
        expenseMap.set(key, (expenseMap.get(key) || 0) + t.amount);
      });

    // 2. Generate past 30 days
    const startDate = new Date(today);
    startDate.setDate(today.getDate() - 30);

    for (let i = 0; i <= 30; i++) {
        const d = new Date(startDate);
        d.setDate(startDate.getDate() + i);
        d.setHours(0, 0, 0, 0);

        const key = d.toDateString();
        dataPoints.push({
            date: d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }),
            actual: expenseMap.get(key) || 0,
            predicted: null,
            timestamp: d.getTime()
        });
    }

    // 3. Anchor prediction point at the current day
    const lastPoint = dataPoints[dataPoints.length - 1];
    lastPoint.predicted = lastPoint.actual;

    // 4. Future 7 days Predictions
    for (let i = 1; i <= 7; i++) {
        const d = new Date(today);
        d.setDate(today.getDate() + i);
        d.setHours(0, 0, 0, 0);

        const trendModifier = 1 + (Math.sin(i * 0.5) * 0.1); 
        const predAmount = Math.max(burnRate * trendModifier, 0);

        dataPoints.push({
            date: d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }),
            actual: null,
            predicted: predAmount,
            timestamp: d.getTime()
        });
    }

    return dataPoints.sort((a, b) => a.timestamp - b.timestamp);
  }, [transactions, burnRate]);

  const categoryData = useMemo(() => {
    const map = new Map<string, number>();
    transactions
      .filter(t => t.type === TransactionType.EXPENSE)
      .forEach(t => {
        map.set(t.category, (map.get(t.category) || 0) + t.amount);
      });
    const total = Array.from(map.values()).reduce((a, b) => a + b, 0);
    return Array.from(map.entries())
        .map(([name, value]) => ({ name, value, percent: total > 0 ? (value / total) * 100 : 0 }))
        .sort((a, b) => b.value - a.value);
  }, [transactions]);

  const demoData = useMemo(() => [
    { date: 'Dec 01', actual: 450, predicted: 450 },
    { date: 'Dec 05', actual: 620, predicted: 600 },
    { date: 'Dec 10', actual: 800, predicted: 850 },
    { date: 'Dec 15', actual: 550, predicted: 600 },
    { date: 'Dec 20', actual: 900, predicted: 880 },
    { date: 'Dec 25', actual: null, predicted: 950 },
    { date: 'Dec 30', actual: null, predicted: 1100 },
  ], []);

  if (!hasData) {
     return (
        <div className="flex flex-col items-center justify-center w-full min-h-full py-12 animate-fade-in text-center relative">
            <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[600px] h-[600px] bg-indigo-500/10 rounded-full blur-[120px] pointer-events-none animate-pulse-slow"></div>
            <div className="max-w-4xl mx-auto mb-12 relative z-10">
                <div className="flex justify-center mb-8">
                    <div className="w-14 h-14 rounded-2xl bg-gradient-to-tr from-amber-400 to-orange-500 flex items-center justify-center shadow-[0_0_30px_rgba(251,191,36,0.3)] rotate-3">
                        <Quote className="w-7 h-7 text-white fill-current" />
                    </div>
                </div>
                <h1 className="text-3xl md:text-4xl font-bold text-white tracking-tight mb-4 leading-tight px-4">"{randomQuote.text}"</h1>
                <p className="text-lg text-slate-400 font-medium italic tracking-wide">— {randomQuote.author}</p>
            </div>
            <div className="w-full max-w-4xl mb-12 relative z-10 animate-slide-up px-4" style={{ animationDelay: '0.1s' }}>
                <div className="glass-card p-8 rounded-3xl border border-white/10 relative overflow-hidden group hover:border-indigo-500/30 transition-colors">
                     <div className="absolute top-0 right-0 w-64 h-64 bg-indigo-500/10 rounded-full blur-3xl -mr-16 -mt-16 pointer-events-none"></div>
                     <div className="flex justify-between items-center mb-6 relative z-10">
                        <div className="text-left">
                            <h3 className="text-lg font-bold text-white flex items-center gap-2">
                                <TrendingUp className="w-5 h-5 text-indigo-400" /> Cash Flow Forecast
                            </h3>
                            <p className="text-slate-400 text-sm">AI-driven spending trajectory (Preview)</p>
                        </div>
                    </div>
                    <div className="h-[240px] w-full relative z-10 opacity-90 group-hover:opacity-100 transition-opacity">
                        <ResponsiveContainer width="100%" height="100%">
                          <AreaChart data={demoData} margin={{ top: 10, right: 0, left: -20, bottom: 0 }}>
                            <defs>
                              <linearGradient id="colorDemoActual" x1="0" y1="0" x2="0" y2="1">
                                <stop offset="5%" stopColor="#6366f1" stopOpacity={0.5}/>
                                <stop offset="95%" stopColor="#6366f1" stopOpacity={0}/>
                              </linearGradient>
                              <linearGradient id="colorDemoPredicted" x1="0" y1="0" x2="0" y2="1">
                                <stop offset="5%" stopColor="#94a3b8" stopOpacity={0.2}/>
                                <stop offset="95%" stopColor="#94a3b8" stopOpacity={0}/>
                              </linearGradient>
                            </defs>
                            <Area type="monotone" dataKey="actual" stroke="#6366f1" fillOpacity={1} fill="url(#colorDemoActual)" strokeWidth={3} connectNulls />
                            <Area type="monotone" dataKey="predicted" stroke="#94a3b8" strokeDasharray="5 5" fill="url(#colorDemoPredicted)" strokeWidth={2} connectNulls />
                          </AreaChart>
                        </ResponsiveContainer>
                    </div>
                </div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6 w-full max-w-5xl relative z-10 px-4">
                 <button onClick={onAddAccount} className="group glass-card p-8 rounded-[2rem] text-left border border-white/5 hover:border-indigo-500/30 transition-all hover:-translate-y-2 hover:shadow-2xl">
                    <div className="w-14 h-14 rounded-2xl bg-indigo-500/10 flex items-center justify-center mb-6 group-hover:bg-indigo-500 group-hover:text-white transition-colors text-indigo-400 shadow-inner"><Landmark className="w-7 h-7" /></div>
                    <h3 className="text-xl font-bold text-white mb-2">Connect Accounts</h3>
                    <p className="text-slate-400 text-sm leading-relaxed">Link your bank or add manual accounts to instantly visualize your net worth.</p>
                 </button>
                 <button onClick={onAddTransaction} className="group glass-card p-8 rounded-[2rem] text-left border border-white/5 hover:border-emerald-500/30 transition-all hover:-translate-y-2 hover:shadow-2xl">
                    <div className="w-14 h-14 rounded-2xl bg-emerald-500/10 flex items-center justify-center mb-6 group-hover:bg-emerald-500 group-hover:text-white transition-colors text-emerald-400 shadow-inner"><PlusCircle className="w-7 h-7" /></div>
                    <h3 className="text-xl font-bold text-white mb-2">Log Transaction</h3>
                    <p className="text-slate-400 text-sm leading-relaxed">Start tracking your daily income and expenses manually to build a history.</p>
                 </button>
                 <button onClick={onAddGoal} className="group glass-card p-8 rounded-[2rem] text-left border border-white/5 hover:border-rose-500/30 transition-all hover:-translate-y-2 hover:shadow-2xl">
                    <div className="w-14 h-14 rounded-2xl bg-rose-500/10 flex items-center justify-center mb-6 group-hover:bg-rose-500 group-hover:text-white transition-colors text-rose-400 shadow-inner"><Target className="w-7 h-7" /></div>
                    <h3 className="text-xl font-bold text-white mb-2">Set Goals</h3>
                    <p className="text-slate-400 text-sm leading-relaxed">Define your financial targets and let Nova help you save for the future.</p>
                 </button>
            </div>
        </div>
     );
  }

  return (
    <div className="space-y-6 animate-slide-up">
      {/* Top Metrics Row */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <div className={`group glass-card p-6 rounded-3xl relative overflow-hidden transition-all duration-500 hover:-translate-y-1 hover:shadow-[0_20px_40px_-15px_rgba(59,130,246,0.2)] ${netWorth < 0 ? 'border-rose-500/30' : ''}`}>
          <div className="absolute inset-0 bg-gradient-to-br from-blue-600/10 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-opacity"></div>
          <div className="flex justify-between items-start relative z-10">
            <div>
              <p className="text-slate-400 text-xs font-bold uppercase tracking-wider mb-2">Total Net Worth</p>
              <h3 className={`text-3xl font-bold tracking-tight ${netWorth < 0 ? 'text-rose-500 animate-pulse' : 'text-emerald-400'}`}>
                  {formatCurrency(netWorth)}
              </h3>
            </div>
            <div className="w-12 h-12 rounded-2xl bg-blue-500/10 flex items-center justify-center border border-blue-500/10 group-hover:scale-110 transition-transform duration-300">
              <Wallet className="w-6 h-6 text-blue-400" />
            </div>
          </div>
        </div>

        <div className="group glass-card p-6 rounded-3xl relative overflow-hidden transition-all duration-500 hover:-translate-y-1 hover:shadow-[0_20px_40px_-15px_rgba(16,185,129,0.2)]">
          <div className="absolute inset-0 bg-gradient-to-br from-emerald-600/10 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-opacity"></div>
          <div className="flex justify-between items-start relative z-10">
            <div>
              <p className="text-slate-400 text-xs font-bold uppercase tracking-wider mb-2">Monthly Income</p>
              <h3 className="text-3xl font-bold text-white tracking-tight">{formatCurrency(monthlyIncome)}</h3>
            </div>
             <div className="w-12 h-12 rounded-2xl bg-emerald-500/10 flex items-center justify-center border border-emerald-500/10 group-hover:scale-110 transition-transform duration-300">
              <Activity className="w-6 h-6 text-emerald-400" />
            </div>
          </div>
           <div className="mt-6 relative z-10">
              <div className="w-full h-1.5 bg-slate-800 rounded-full overflow-hidden">
                  <div className="h-full bg-gradient-to-r from-emerald-500 to-teal-400 rounded-full shadow-[0_0_10px_#10b981]" style={{ width: '100%' }}></div>
              </div>
          </div>
        </div>

        <div className="group glass-card p-6 rounded-3xl relative overflow-hidden transition-all duration-500 hover:-translate-y-1 hover:shadow-[0_20px_40px_-15px_rgba(244,63,94,0.2)]">
           <div className="absolute inset-0 bg-gradient-to-br from-rose-600/10 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-opacity"></div>
          <div className="flex justify-between items-start relative z-10">
            <div>
              <p className="text-slate-400 text-xs font-bold uppercase tracking-wider mb-2">Daily Burn</p>
              <h3 className="text-3xl font-bold text-white tracking-tight">{formatCurrency(burnRate)}</h3>
            </div>
            <div className="w-12 h-12 rounded-2xl bg-rose-500/10 flex items-center justify-center border border-rose-500/10 group-hover:scale-110 transition-transform duration-300">
              <Flame className="w-6 h-6 text-rose-400" />
            </div>
          </div>
           <div className="mt-6 flex items-center gap-2 relative z-10">
              <span className="text-xs text-slate-500 font-medium">Monthly Est. {formatCurrency(burnRate * daysInMonth)}</span>
           </div>
        </div>

         <div onClick={() => onNavigate('accounts')} className="group glass-card p-6 rounded-3xl relative overflow-hidden transition-all duration-500 hover:-translate-y-1 hover:shadow-[0_20px_40px_-15px_rgba(139,92,246,0.2)] cursor-pointer">
          <div className="absolute inset-0 bg-gradient-to-br from-violet-600/10 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-opacity"></div>
          <div className="flex justify-between items-start relative z-10">
