                                </button>
                                <button 
                                    type="button" 
                                    onClick={() => { setType(TransactionType.INCOME); setCategory(''); }}
                                    className={`relative z-10 flex-1 flex items-center justify-center gap-2 text-sm font-bold transition-colors duration-300 ${type === TransactionType.INCOME ? 'text-white' : 'text-slate-500 hover:text-slate-300'}`}
                                >
                                    <ArrowUp className={`w-4 h-4 ${type === TransactionType.INCOME ? 'animate-bounce' : ''}`} /> 
                                    Income
                                </button>
                            </div>

                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <label className="text-xs font-bold text-slate-400 uppercase tracking-wider">Amount</label>
                                    <div className="relative mt-2">
                                        <DollarSign className="absolute left-3.5 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500" />
                                        <input 
                                            required 
                                            type="number" 
                                            step="0.01" 
                                            value={amount} 
                                            onChange={e => setAmount(e.target.value)} 
                                            className="w-full bg-slate-950/50 border border-white/10 rounded-xl p-3.5 pl-9 text-white focus:border-indigo-500 focus:outline-none focus:ring-4 focus:ring-indigo-500/10 transition-all placeholder:text-slate-600 font-mono text-lg" 
                                            placeholder="0.00" 
                                        />
                                    </div>
                                </div>
                                <div>
                                    <label className="text-xs font-bold text-slate-400 uppercase tracking-wider">Date</label>
                                    <input 
                                        required 
                                        type="date" 
                                        value={date} 
                                        onChange={e => setDate(e.target.value)} 
                                        className="w-full bg-slate-950/50 border border-white/10 rounded-xl p-3.5 text-white mt-2 focus:border-indigo-500 focus:outline-none focus:ring-4 focus:ring-indigo-500/10 transition-all [color-scheme:dark]" 
                                    />
                                </div>
                            </div>

                            <div>
                                <label className="text-xs font-bold text-slate-400 uppercase tracking-wider flex justify-between">
                                    Merchant / Source
                                    {isAutoCategorizing && <span className="text-indigo-400 flex items-center gap-1 text-[10px]"><Loader2 className="w-3 h-3 animate-spin" /> AI Categorizing...</span>}
                                </label>
                                <input 
                                    required 
                                    type="text" 
                                    value={merchant} 
                                    onChange={e => setMerchant(e.target.value)}
                                    onBlur={handleMerchantBlur}
                                    className="w-full bg-slate-950/50 border border-white/10 rounded-xl p-3.5 text-white mt-2 focus:border-indigo-500 focus:outline-none focus:ring-4 focus:ring-indigo-500/10 transition-all placeholder:text-slate-600" 
                                    placeholder={type === TransactionType.INCOME ? "e.g. Salary, Freelance" : "e.g. Starbucks, Uber"}
                                />
                            </div>

                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                <div>
                                    <label className="text-xs font-bold text-slate-400 uppercase tracking-wider">Category</label>
                                    <select 
                                        required 
                                        value={category} 
                                        onChange={e => setCategory(e.target.value as Category)} 
                                        className="w-full bg-slate-950/50 border border-white/10 rounded-xl p-3.5 text-white mt-2 focus:border-indigo-500 focus:outline-none focus:ring-4 focus:ring-indigo-500/10 transition-all appearance-none cursor-pointer"
                                    >
                                        <option value="" disabled>Select...</option>
                                        {type === TransactionType.INCOME 
                                            ? incomeCategories.map(c => <option key={c} value={c}>{c}</option>)
                                            : expenseCategories.map(c => <option key={c} value={c}>{c}</option>)
                                        }
                                    </select>
                                </div>

                                <div>
                                    <label className="text-xs font-bold text-slate-400 uppercase tracking-wider">
                                        {type === TransactionType.INCOME ? 'Deposit To' : 'Payment Method'}
                                    </label>
                                    <div className="relative mt-2">
                                        <Wallet className="absolute left-3.5 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500 pointer-events-none" />
                                        <select
                                            required={type === TransactionType.EXPENSE}
                                            value={selectedAccountId}
                                            onChange={(e) => setSelectedAccountId(e.target.value)}
                                            className="w-full bg-slate-950/50 border border-white/10 rounded-xl p-3.5 pl-10 text-white focus:border-indigo-500 focus:outline-none focus:ring-4 focus:ring-indigo-500/10 transition-all appearance-none cursor-pointer"
                                        >
                                            <option value="" disabled>Select Account</option>
                                            {accounts.map(acc => (
                                                <option key={acc.id} value={acc.id}>{acc.name} ({formatCurrency(acc.balance)})</option>
                                            ))}
                                        </select>
                                    </div>
                                </div>
                            </div>

                            <div>
                                <label className="text-xs font-bold text-slate-400 uppercase tracking-wider flex items-center gap-2">
                                    Notes / Context <span className="text-[10px] text-slate-600 font-normal lowercase">(how you lost money)</span>
                                </label>
                                <div className="relative mt-2">
                                    <FileText className="absolute left-3.5 top-3.5 w-4 h-4 text-slate-500" />
                                    <textarea
                                        value={notes}
                                        onChange={(e) => setNotes(e.target.value)}
                                        className="w-full bg-slate-950/50 border border-white/10 rounded-xl p-3.5 pl-10 text-white focus:border-indigo-500 focus:outline-none focus:ring-4 focus:ring-indigo-500/10 transition-all placeholder:text-slate-600 min-h-[100px] resize-none"
                                        placeholder="e.g. Impulse buy, forgot to cancel subscription..."
                                    />
                                </div>
                            </div>

                            <button type="submit" className="w-full py-4 bg-indigo-600 hover:bg-indigo-500 text-white font-bold rounded-xl shadow-lg shadow-indigo-500/20 active:scale-95 transition-all flex items-center justify-center gap-2">
                                <Check className="w-5 h-5" /> Save Transaction
                            </button>
                        </form>
                    )}
                </div>
            </div>
        </div>
    );
};

export default Transactions;

import React, { useState, useEffect, useMemo } from 'react';
import { Account, Budget, Goal, Transaction, UserPlan, ToastMessage, TransactionType, Category } from './types';
import { ACCOUNTS, INITIAL_TRANSACTIONS, INITIAL_BUDGETS, INITIAL_GOALS, NAV_ITEMS } from './constants';
import Dashboard from './components/Dashboard';
import Transactions from './components/Transactions';
import Accounts from './components/Accounts';
import Insights from './components/Insights';
import Goals from './components/Goals';
import Plans from './components/Plans';
import Settings from './components/Settings';
import LandingPage from './components/LandingPage';
import ToastContainer from './components/Toast';
import { Sparkles, LogOut, Ambulance, Activity, X, ArrowRight, Bell, Zap, ShieldAlert, TrendingUp, CheckCircle, ChevronRight, Send, Lock } from 'lucide-react';

// Interfaces for Nova Bot Logic
interface AiNotification {
    id: string;
    type: 'critical' | 'warning' | 'success' | 'info';
    title: string;
    message: string;
    actionLabel?: string;
    actionTab?: string;
}

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');

  // --- PERSISTENCE LAYER ---
  // Load initial state from LocalStorage or fall back to constants (which are empty now)
  const [accounts, setAccounts] = useState<Account[]>(() => {
      const saved = localStorage.getItem('nova_accounts');
      return saved ? JSON.parse(saved) : ACCOUNTS;
  });
  const [transactions, setTransactions] = useState<Transaction[]>(() => {
      const saved = localStorage.getItem('nova_transactions');
      return saved ? JSON.parse(saved) : INITIAL_TRANSACTIONS;
  });
  const [budgets, setBudgets] = useState<Budget[]>(() => {
      const saved = localStorage.getItem('nova_budgets');
      return saved ? JSON.parse(saved) : INITIAL_BUDGETS;
  });
  const [goals, setGoals] = useState<Goal[]>(() => {
      const saved = localStorage.getItem('nova_goals');
      return saved ? JSON.parse(saved) : INITIAL_GOALS;
  });

  const [userPlan, setUserPlan] = useState<UserPlan>(() => localStorage.getItem('nova_user_plan') as UserPlan || 'free');
  const [isLoggedIn, setIsLoggedIn] = useState(() => localStorage.getItem('nova_auth_token') !== null);
  const [toasts, setToasts] = useState<ToastMessage[]>([]);
  const [showDangerModal, setShowDangerModal] = useState(false);
  const [showCoachLockModal, setShowCoachLockModal] = useState(false);

  // Bot States
  const [showBotPanel, setShowBotPanel] = useState(false);
  const [botNotifications, setBotNotifications] = useState<AiNotification[]>([]);
  const [pendingChatQuery, setPendingChatQuery] = useState<string | null>(null);

  // User Appearance States
  const [userName, setUserName] = useState(() => localStorage.getItem('nova_user_name') || '');
  const [userEmail, setUserEmail] = useState(() => localStorage.getItem('nova_user_email') || 'pilot@nova.io');
  const [userAvatar, setUserAvatar] = useState(() => localStorage.getItem('nova_user_avatar') || 'bg-indigo-600');
  const [userAvatarZoom, setUserAvatarZoom] = useState(() => parseFloat(localStorage.getItem('nova_user_avatar_zoom') || '1'));
  const [userAvatarPos, setUserAvatarPos] = useState(() => {
    const x = parseFloat(localStorage.getItem('nova_user_avatar_pos_x') || '0');
    const y = parseFloat(localStorage.getItem('nova_user_avatar_pos_y') || '0');
    return { x, y };
  });
  const [userBorder, setUserBorder] = useState(() => localStorage.getItem('nova_user_border') || 'default');
  const [userBackground, setUserBackground] = useState(() => localStorage.getItem('nova_user_background') || '');

  // --- AUTO-SAVE EFFECTS ---
  useEffect(() => { localStorage.setItem('nova_accounts', JSON.stringify(accounts)); }, [accounts]);
  useEffect(() => { localStorage.setItem('nova_transactions', JSON.stringify(transactions)); }, [transactions]);
  useEffect(() => { localStorage.setItem('nova_budgets', JSON.stringify(budgets)); }, [budgets]);
  useEffect(() => { localStorage.setItem('nova_goals', JSON.stringify(goals)); }, [goals]);

  const addToast = (message: string, type: ToastMessage['type'] = 'success') => {
    const id = Date.now().toString();
    setToasts(prev => [...prev, { id, message, type }]);
  };

  const removeToast = (id: string) => {
    setToasts(prev => prev.filter(toast => toast.id !== id));
  };

  const formatCurrency = (amount: number) => `$${amount.toLocaleString()}`;

  const handleAddAccount = (acc: Account) => setAccounts([...accounts, acc]);
  const handleUpdateAccount = (acc: Account) => setAccounts(accounts.map(a => a.id === acc.id ? acc : a));
  const handleDeleteAccount = (id: string) => setAccounts(accounts.filter(a => a.id !== id));

  const handleAddTransaction = (t: Transaction) => {
    setTransactions(prev => [t, ...prev]);
    if (t.accountId && t.accountId !== 'manual') {
      setAccounts(prev => prev.map(acc => {
        if (acc.id === t.accountId) {
          const newBalance = t.type === TransactionType.EXPENSE
            ? acc.balance - t.amount
            : acc.balance + t.amount;
          return { ...acc, balance: newBalance };
        }
        return acc;
      }));
    }
    addToast('Transaction recorded & Balance updated.', 'success');
  };

  const handleDeleteTransaction = (id: string) => {
    const txToDelete = transactions.find(t => t.id === id);
    setTransactions(prev => prev.filter(t => t.id !== id));
    if (txToDelete && txToDelete.accountId && txToDelete.accountId !== 'manual') {
      setAccounts(prev => prev.map(acc => {
        if (acc.id === txToDelete.accountId) {
          const newBalance = txToDelete.type === TransactionType.EXPENSE
            ? acc.balance + txToDelete.amount
            : acc.balance - txToDelete.amount;
          return { ...acc, balance: newBalance };
        }
        return acc;
      }));
    }
    addToast('Transaction removed & Balance reverted.', 'info');
  };

  const handleBatchCategoryUpdate = (merchant: string, category: Category) => {
    // Case-insensitive matching for batch update
    const normalizedMerchant = merchant.toLowerCase().trim();
    setTransactions(prev => prev.map(t => 
        t.merchant.toLowerCase().trim() === normalizedMerchant ? { ...t, category } : t
    ));
    addToast(`All transactions for ${merchant} marked as ${category}`, 'success');
  };

  const handleUpdateProfile = (name: string, email: string, avatar: string, zoom: number, pos: { x: number; y: number }, border: string) => {
    setUserName(name);
    setUserEmail(email);
    setUserAvatar(avatar);
    setUserAvatarZoom(zoom);
    setUserAvatarPos(pos);
    setUserBorder(border);

    try {
      localStorage.setItem('nova_user_name', name);
      localStorage.setItem('nova_user_email', email);
      localStorage.setItem('nova_user_avatar', avatar);
      localStorage.setItem('nova_user_avatar_zoom', zoom.toString());
      localStorage.setItem('nova_user_avatar_pos_x', pos.x.toString());
      localStorage.setItem('nova_user_avatar_pos_y', pos.y.toString());
      localStorage.setItem('nova_user_border', border);
    } catch (e) {
      addToast("Storage full. Image may not persist.", "error");
    }
  };

  const handleUpdateBackground = (bg: string) => {
      setUserBackground(bg);
      try {
          localStorage.setItem('nova_user_background', bg);
      } catch (e) {
          addToast("Image too large to save.", "error");
      }
  };

  const handleSignOut = () => {
    // Only remove auth, keep data
    localStorage.removeItem('nova_auth_token');
    localStorage.removeItem('nova_user_name');
    localStorage.removeItem('nova_user_email');
    localStorage.removeItem('nova_user_avatar');
    setIsLoggedIn(false);
  };

  const handleClearData = () => {
      // Nuclear Reset
      localStorage.removeItem('nova_accounts');
      localStorage.removeItem('nova_transactions');
      localStorage.removeItem('nova_budgets');
      localStorage.removeItem('nova_goals');
      localStorage.removeItem('nova_user_background');
      setUserBackground('');

      setAccounts([]);
      setTransactions([]);
      setBudgets([]);
      setGoals([]);
      addToast("Core data system wiped. Starting fresh.", "error");
  };

  const handleAskCoach = (query: string) => {
      setPendingChatQuery(query);
      setActiveTab('insights');
  };

  // --- NOVA INTELLIGENCE SYSTEM ---
  useEffect(() => {
      const generateNotifications = () => {
          const notes: AiNotification[] = [];
          const now = new Date();

          const netWorth = accounts.reduce((acc, curr) => acc + curr.balance, 0);
          if (netWorth < 0) {
              notes.push({
                  id: 'risk-nw',
                  type: 'critical',
                  title: 'Net Worth Critical',
                  message: 'Your liabilities exceed your assets. Immediate intervention recommended.',
                  actionLabel: 'View Analysis',
                  actionTab: 'insights'
              });
              // Pro users don't see the sales modal, but free users do
              if (userPlan !== 'pro') setShowDangerModal(true);
          }

          budgets.forEach(budget => {
              const spent = transactions
                  .filter(t => t.category === budget.category && 
                              t.type === TransactionType.EXPENSE && 
                              new Date(t.date).getMonth() === now.getMonth() && 
                              new Date(t.date).getFullYear() === now.getFullYear())
                  .reduce((acc, t) => acc + t.amount, 0);

              if (spent > budget.limit) {
                  notes.push({
                      id: `over-${budget.id}`,
                      type: 'critical',
                      title: 'Budget Breached',
                      message: `You have exceeded your limit for ${budget.category} by ${formatCurrency(spent - budget.limit)}. Stop spending now.`,
                      actionLabel: 'Adjust Budget',
                      actionTab: 'goals'
                  });
              } else if (spent > budget.limit * 0.85) {
                   notes.push({
                      id: `warn-${budget.id}`,
                      type: 'warning',
                      title: 'Budget at Risk',
                      message: `You are at 85% of your ${budget.category} limit. Slow down.`,
                      actionLabel: 'Check Spending',
                      actionTab: 'transactions'
                  });
              }
          });

          goals.forEach(goal => {
              const progress = goal.currentAmount / goal.targetAmount;
              if (progress >= 1 && goal.currentAmount > 0) {
                  notes.push({
                      id: `goal-${goal.id}`,
                      type: 'success',
                      title: 'Goal Achieved!',
                      message: `Outstanding work. You've fully funded "${goal.name}". Set a new target to keep the momentum.`,
                      actionLabel: 'New Goal',
                      actionTab: 'goals'
                  });
              } else if (progress > 0.5 && progress < 0.6) {
                   notes.push({
                      id: `prog-${goal.id}`,
                      type: 'info',
                      title: 'Halfway There',
                      message: `You're over 50% of the way to "${goal.name}". Consistency is key. Keep pushing.`,
                  });
              }
          });

          if (transactions.length === 0) {
               notes.push({
                  id: 'empty-state',
                  type: 'info',
                  title: 'System Idle',
                  message: 'No financial data detected. Feed the system transactions to generate insights.',
                  actionLabel: 'Log Expense',
                  actionTab: 'transactions'
              });
          }

          setBotNotifications(notes);
      };

      generateNotifications();
  }, [accounts, transactions, budgets, goals, userPlan]);

  if (!isLoggedIn) {
    return <LandingPage onLoginSuccess={(name) => { setUserName(name); setIsLoggedIn(true); }} />;
  }

  const isPro = userPlan === 'pro';
  const isImageAvatar = userAvatar.includes('http') || userAvatar.startsWith('data:');
  const filteredNavItems = NAV_ITEMS.filter(item => !(isPro && item.id === 'plans'));

  const hasCritical = botNotifications.some(n => n.type === 'critical');
  const hasSuccess = botNotifications.some(n => n.type === 'success');
  const notificationCount = botNotifications.length;

  const getBorderClasses = (style: string) => {
    if (!isPro && style !== 'default') return 'ring-2 ring-white/10'; // Fallback if user downgrades
    switch (style) {
      case 'gold': return 'ring-2 ring-amber-400 shadow-[0_0_15px_rgba(251,191,36,0.6)]';
      case 'rainbow': return 'ring-4 ring-transparent bg-gradient-to-tr from-rose-500 via-yellow-500 to-cyan-500 bg-[length:400%_400%] animate-gradient-xy p-[2px]';
      case 'neon': return 'ring-2 ring-cyan-400 shadow-[0_0_15px_rgba(34,211,238,0.6)]';
      case 'plasma': return 'ring-2 ring-fuchsia-500 shadow-[0_0_15px_rgba(217,70,239,0.6)]';
      default: return 'ring-1 ring-white/20';
    }
  };

  return (
    <div 
        className="flex h-screen text-slate-200 font-sans bg-cover bg-center transition-all duration-700 relative"
        style={{ 
            backgroundColor: '#020617',
            backgroundImage: userBackground ? `url(${userBackground})` : undefined 
        }}
    >
      {/* Background Overlay for readability if custom image is used */}
      {userBackground && <div className="absolute inset-0 bg-slate-950/70 backdrop-blur-sm pointer-events-none z-0"></div>}

      <aside className="w-64 bg-[#0f172a]/90 backdrop-blur-xl border-r border-white/5 p-6 flex flex-col hidden md:flex z-10">
        <div className="flex items-center gap-3 mb-12 relative group">
          <div className={`
            w-10 h-10 rounded-xl flex items-center justify-center shadow-lg transition-all duration-700
            ${isPro
                ? 'bg-gradient-to-br from-amber-300 via-amber-500 to-orange-700 shadow-[0_0_30px_rgba(251,191,36,0.8)] ring-2 ring-white/80 relative overflow-hidden'
                : 'bg-indigo-600 shadow-indigo-600/20'
            }`}
          >
            {isPro ? (
                <>
                    <Sparkles className="w-7 h-7 text-white drop-shadow-[0_0_10px_rgba(255,255,255,0.8)] relative z-10" />
                </>
            ) : (
                <span className="text-white font-black text-lg">N</span>
            )}
          </div>
          <div>
            <h1 className="text-xl font-black tracking-tighter text-white">Nova AI</h1>
            {isPro && (
                <div className="absolute -top-1 -right-4">
                  <span className="bg-gradient-to-r from-amber-400 to-orange-500 text-white text-[8px] font-black px-1.5 py-0.5 rounded border border-amber-500/20 shadow-md shadow-amber-500/30 uppercase tracking-widest">PRO</span>
                </div>
            )}
          </div>
        </div>
        <nav className="flex-1 space-y-1">
          {filteredNavItems.map(item => (
            <button
              key={item.id}
              onClick={() => setActiveTab(item.id)}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-semibold transition-all ${
                activeTab === item.id 
                  ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-600/20' 
                  : 'text-slate-400 hover:text-white hover:bg-white/5'
              }`}
            >
              <item.icon className="w-5 h-5" />
              {item.label}
            </button>
          ))}
        </nav>

        {/* User Profile Footer */}
        <div className="mt-auto pt-6 border-t border-white/5 space-y-3">
             <div 
                className="flex items-center gap-3 p-3 rounded-2xl bg-white/5 border border-white/5 hover:bg-white/10 transition-colors cursor-pointer group relative overflow-hidden"
                onClick={() => setActiveTab('settings')}
             >
                <div className={`w-10 h-10 rounded-full bg-slate-800 shrink-0 overflow-hidden relative shadow-sm transition-all ${getBorderClasses(userBorder)}`}>
                    {isImageAvatar ? (
                         <img 
                            src={userAvatar} 
                            alt="Profile"
                            className="w-full h-full object-cover"
                            style={{ 
                                transform: `scale(${userAvatarZoom}) translate(${userAvatarPos.x}px, ${userAvatarPos.y}px)` 
                            }}
                         />
                    ) : (
                        <div className={`w-full h-full ${userAvatar}`}></div>
                    )}
                </div>
                <div className="min-w-0 flex-1">
                    <h4 className="text-sm font-bold text-white truncate">{userName || 'Nova Pilot'}</h4>
                    <div className="flex items-center gap-2 mt-0.5">
                        <span className={`text-[9px] font-black px-1.5 py-0.5 rounded border uppercase tracking-widest ${isPro ? 'bg-amber-500/10 text-amber-400 border-amber-500/20' : 'bg-slate-700/50 text-slate-400 border-slate-600/50'}`}>
                            {isPro ? 'PRO PLAN' : 'FREE'}
                        </span>
                    </div>
                </div>
             </div>

             <button 
                onClick={handleSignOut}
                className="w-full flex items-center justify-center gap-2 p-2 text-xs font-bold text-slate-500 hover:text-rose-400 hover:bg-rose-500/10 rounded-lg transition-colors group"
             >
                <LogOut className="w-3.5 h-3.5 group-hover:translate-x-0.5 transition-transform" /> Sign Out
             </button>
        </div>
      </aside>

      <main className="flex-1 overflow-auto p-4 md:p-10 relative z-10">
