                                        required 
                                        value={category} 
                                        onChange={e => setCategory(e.target.value as Category)} 
                                        className="w-full bg-slate-950/50 border border-white/10 rounded-xl p-3.5 text-white mt-2 focus:border-indigo-500 focus:outline-none focus:ring-4 focus:ring-indigo-500/10 transition-all appearance-none cursor-pointer"
                                    >
                                        <option value="" disabled>Select...</option>
