    e.preventDefault();
    const account: Account = {
      id: initialData?.id || `acc_${Date.now()}`,
      name,
      nickname: nickname || undefined,
      institution,
      type,
      balance: parseFloat(balance) || 0,
      color
    };
    onSubmit(account);
    onClose();
  };

