const AddTransactionModal: React.FC<{ 
    onClose: () => void; 
    onAdd: (t: Transaction) => void;
    accounts: Account[];
    onNavigateToAccounts?: () => void;
    userPlan?: UserPlan;
    formatCurrency: (amount: number) => string;
    scanUsage: number;
    onIncrementScan?: () => void;
}> = ({ onClose, onAdd, accounts, onNavigateToAccounts, userPlan, formatCurrency, scanUsage, onIncrementScan }) => {
    const [type, setType] = useState<TransactionType>(TransactionType.EXPENSE);
    const [merchant, setMerchant] = useState('');
    const [amount, setAmount] = useState('');
    const [category, setCategory] = useState<Category | ''>('');
    const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
    const [selectedAccountId, setSelectedAccountId] = useState<string>('');
    const [notes, setNotes] = useState('');
    const [isAutoCategorizing, setIsAutoCategorizing] = useState(false);
    const [isScanning, setIsScanning] = useState(false);
    const [scanError, setScanError] = useState<string | null>(null);
    const fileInputRef = useRef<HTMLInputElement>(null);

    // Limit Logic
    const isPro = userPlan === 'pro';
    const isFree = !isPro;
    const canScan = (isFree && scanUsage < 1) || (isPro && scanUsage < 50);
    const scanLimitReached = !canScan;

    // Categories filtered by type
    const expenseCategories = [
        Category.HOUSING, Category.FOOD, Category.TRANSPORT, Category.ENTERTAINMENT, 
        Category.SHOPPING, Category.UTILITIES, Category.HEALTH, Category.SUBSCRIPTION, 
        Category.EDUCATION, Category.TRAVEL, Category.PETS, Category.KIDS, 
        Category.GIFTS, Category.SERVICES, Category.OTHER
    ];
    const incomeCategories = [Category.INCOME, Category.INVESTMENT, Category.OTHER];

    const hasAccounts = accounts.length > 0;
    const canAddExpense = type === TransactionType.INCOME || hasAccounts;

    const handleMerchantBlur = async () => {
        if (!merchant || isAutoCategorizing || userPlan !== 'pro' || category) return;

        setIsAutoCategorizing(true);
        try {
            const predictedCategory = await categorizeTransaction(merchant, parseFloat(amount) || 0);
            const isValidCategory = Object.values(Category).includes(predictedCategory as Category);
            if (isValidCategory) setCategory(predictedCategory as Category);
        } catch (error) {
            console.error("Auto-cat failed", error);
        } finally {
            setIsAutoCategorizing(false);
        }
    };

    const handleScanClick = () => {
        if (scanLimitReached) return;
        fileInputRef.current?.click();
    };

    const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;

        setIsScanning(true);
        setScanError(null);

        // Reset file input so user can select same file again if failed
        if (fileInputRef.current) fileInputRef.current.value = '';

        try {
            const reader = new FileReader();
            reader.readAsDataURL(file);
            reader.onload = async () => {
                const base64 = (reader.result as string).split(',')[1];
                const result = await parseReceiptImage(base64);

                if (result) {
                    setMerchant(result.merchant || 'Unknown Merchant');
                    setAmount(result.amount?.toString() || '');
                    if (result.date) setDate(result.date);
                    if (result.category && Object.values(Category).includes(result.category as Category)) {
                        setCategory(result.category as Category);
                    }
                    if (onIncrementScan) onIncrementScan();
                } else {
                    setScanError("Could not extract data. Please fill manually.");
                }
                setIsScanning(false);
            };
            reader.onerror = () => {
                setScanError("Failed to read image file.");
                setIsScanning(false);
            }
        } catch (err) {
            setScanError("AI Connection Failed.");
            setIsScanning(false);
        }
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (!merchant || !amount || !category) return;
        if (type === TransactionType.EXPENSE && !selectedAccountId) return;

        const newTx: Transaction = {
            id: Date.now().toString(),
            date,
            merchant,
            amount: parseFloat(amount),
            category: category as Category,
            type,
            accountId: selectedAccountId || 'manual',
            notes: notes 
        };
        onAdd(newTx);
        onClose();
    };

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/80 backdrop-blur-md animate-fade-in">
            <div className="bg-[#0f172a] border border-white/10 rounded-3xl w-full max-w-lg shadow-2xl overflow-hidden animate-slide-up relative ring-1 ring-white/5 flex flex-col max-h-[90vh]">
                <button onClick={onClose} className="absolute top-4 right-4 p-2 text-slate-400 hover:text-white z-10"><X className="w-6 h-6" /></button>

                <div className="p-8 border-b border-white/5 bg-gradient-to-r from-indigo-900/20 to-transparent flex-shrink-0">
                    <h3 className="text-2xl font-bold text-white flex items-center gap-2"><Plus className="w-6 h-6 text-indigo-400" /> New Transaction</h3>
                    <p className="text-slate-400 text-sm mt-1">Log your income or spending.</p>
                </div>

                <div className="overflow-y-auto p-8 custom-scrollbar">
                    {!canAddExpense ? (
                        <div className="text-center py-8">
                            <div className="w-16 h-16 bg-slate-800 rounded-full flex items-center justify-center mx-auto mb-4">
                                <Wallet className="w-8 h-8 text-slate-500" />
                            </div>
                            <h4 className="text-white font-bold text-lg mb-2">No Accounts Found</h4>
                            <p className="text-slate-400 text-sm mb-6">You need to add a savings or checking account before you can track expenses.</p>
                            <button 
                                onClick={() => { onClose(); if(onNavigateToAccounts) onNavigateToAccounts(); }}
                                className="px-6 py-3 bg-indigo-600 hover:bg-indigo-500 text-white font-bold rounded-xl transition-all"
                            >
                                Add Account
                            </button>
                        </div>
                    ) : (
                        <form onSubmit={handleSubmit} className="space-y-6">

                            {/* AI Receipt Scanner Button */}
                            <div className="relative">
                                <input type="file" accept="image/*" ref={fileInputRef} onChange={handleFileChange} hidden />
                                <button 
                                    type="button" 
                                    onClick={handleScanClick}
                                    disabled={scanLimitReached || isScanning}
                                    className={`w-full py-3 rounded-xl border-2 border-dashed transition-all group relative overflow-hidden ${
                                        isScanning ? 'border-indigo-500 bg-indigo-500/10 cursor-wait' :
                                        scanLimitReached 
                                            ? 'border-slate-700 bg-slate-800/30 text-slate-500 cursor-not-allowed' 
                                            : 'border-slate-600 bg-slate-800/50 hover:border-indigo-500 hover:bg-indigo-500/10 text-slate-300 hover:text-white'
                                    }`}
                                >
                                    {isScanning ? (
                                        <div className="flex items-center justify-center gap-2 text-indigo-400">
                                            <Loader2 className="w-5 h-5 animate-spin" />
                                            <span className="text-sm font-bold animate-pulse">Extracting Data...</span>
                                        </div>
                                    ) : (
                                        <div className="flex items-center justify-center gap-2">
                                            {scanLimitReached ? <AlertCircle className="w-5 h-5" /> : <Camera className="w-5 h-5" />}
                                            <span className="text-sm font-bold">
                                                {scanLimitReached ? (isFree ? "Free Scan Limit Reached" : "Monthly Scan Limit Reached") : "Scan Receipt with AI"}
                                            </span>
                                        </div>
                                    )}
                                    {/* Scan beam animation */}
                                    {isScanning && (
                                        <div className="absolute top-0 left-0 w-full h-full bg-gradient-to-b from-transparent via-indigo-500/20 to-transparent animate-[slideUp_1.5s_infinite]"></div>
                                    )}
                                </button>
                                {scanLimitReached && isFree && (
                                    <p className="text-[10px] text-center mt-1 text-slate-500">
                                        Upgrade to Pro for 50 scans/month.
                                    </p>
                                )}
                                {scanError && (
                                    <div className="mt-2 text-xs text-rose-400 bg-rose-500/10 p-2 rounded-lg border border-rose-500/20 flex items-center gap-2">
                                        <AlertCircle className="w-3 h-3 shrink-0" /> {scanError}
                                    </div>
                                )}
                            </div>

                            {/* Improved Sliding Toggle UI */}
                            <div className="relative flex bg-slate-950 rounded-2xl p-1.5 border border-white/10 cursor-pointer h-14 shadow-inner">
                                <div 
                                    className={`absolute top-1.5 bottom-1.5 rounded-xl shadow-lg transition-all duration-300 ease-spring ${
                                        type === TransactionType.EXPENSE 
                                            ? 'left-1.5 w-[calc(50%-6px)] bg-gradient-to-br from-rose-500 to-red-600 border border-rose-400/30' 
                                            : 'left-[calc(50%+3px)] w-[calc(50%-6px)] bg-gradient-to-br from-emerald-500 to-green-600 border border-emerald-400/30'
                                    }`}
                                >
                                    {/* Inner glow effect for active pill */}
                                    <div className="absolute inset-0 bg-white/10 rounded-xl opacity-50"></div>
                                </div>

                                <button 
                                    type="button" 
