import { GoogleGenAI, Type, Schema } from "@google/genai";
import { Transaction, AIAnalysisResponse, BotMode, Category } from '../types';

// Use process.env.API_KEY directly in constructor as per naming requirements.
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const cleanJsonResponse = (text: string) => {
  // Removes markdown code block indicators if Gemini includes them
  return text.replace(/```json/g, '').replace(/```/g, '').trim();
};

export const analyzeFinancialData = async (transactions: Transaction[]): Promise<AIAnalysisResponse | null> => {
  // Filter to last 50 transactions for context
  const recentTxs = transactions.slice(0, 50);
  const dataString = JSON.stringify(recentTxs);

  const prompt = `
  Act as a strict but helpful financial wellness coach named Nova. Analyze these transactions.

  1. Identify critical spending anomalies or bad habits (e.g., too much coffee, subscriptions).
  2. Suggest specific budget limits for categories where spending is high.
  3. Predict the total spending for next month based on this trajectory.
  4. Assign a 'risk score' from 0-100 (100 being very financially risky behavior).

  Return strict JSON matching the schema.`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: `Data: ${dataString}. ${prompt}`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            insights: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  title: { type: Type.STRING },
                  description: { type: Type.STRING },
                  type: { type: Type.STRING, enum: ['success', 'warning', 'info', 'critical'] },
                  actionable: { type: Type.BOOLEAN },
                  metric: { type: Type.STRING }
                }
              }
            },
            budget_suggestions: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  category: { type: Type.STRING },
                  current_spend: { type: Type.NUMBER },
                  suggested_limit: { type: Type.NUMBER },
                  reason: { type: Type.STRING }
                }
              }
            },
            predicted_spend_next_month: { type: Type.NUMBER },
            risk_score: { type: Type.NUMBER }
          }
        }
      }
    });

    const rawText = response.text;
    if (rawText) {
      const cleanText = cleanJsonResponse(rawText);
      return JSON.parse(cleanText) as AIAnalysisResponse;
    }
    return null;

  } catch (error) {
    console.error("Gemini Analysis Error:", error);
    return null;
  }
};

export const categorizeTransaction = async (merchant: string, amount: number): Promise<string> => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: `Categorize a transaction for "${merchant}" with amount ${amount}. 
      Return only one of these exact strings: 'Housing', 'Food & Dining', 'Transportation', 'Entertainment', 'Shopping', 'Utilities', 'Health', 'Subscription', 'Education', 'Travel', 'Pets', 'Kids', 'Gifts', 'Services', 'Investment', 'Other'.
      Do not return JSON, just the string.`,
    });
    return response.text?.trim() || 'Other';
  } catch (e) {
    return 'Other';
  }
};

export const chatWithFinancialCoach = async (message: string, context: Transaction[], mode: BotMode = 'ruthless'): Promise<string> => {
  const recentTxs = context.slice(0, 20);
  const dataSummary = JSON.stringify(recentTxs);

  const ruthlessInstructions = `
    STYLE: Cold, Analytical System Message.
    - You are a money management system, NOT a person.
    - State violations with exact numbers.
    - Show downstream consequences (e.g., "Month-end projection reduced by $X").
    - Require a resolution.
    - NO emojis. NO sympathy. NO praise. NO "it's okay".
    - Output unavoidable truth and consequences only.
  `;

  const supportiveInstructions = `
    STYLE: Supportive Translation Layer.
    - You are a helpful financial assistant.
    - Present the EXACT SAME hard facts, numbers, and consequences as the analytical system.
    - Use warmer phrasing, but DO NOT soften the financial reality or outcome.
    - DO NOT cheerlead or say "it's okay" if they lost money.
    - You may use MAX ONE optional emoji at the very end.
    - Focus on the data, but gently.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: `
        System: You are Nova. 
        Current Explanation Style: ${mode === 'ruthless' ? ruthlessInstructions : supportiveInstructions}

        Context: User's recent transactions: ${dataSummary}.
        User Question: ${message}

        Instructions:
        - Keep answers concise (under 3 sentences).
        - Use data from the transactions if relevant.
        - Do not use markdown formatting like bold or italics, just plain text.
      `,
    });
    return response.text || "System error. Calculation failed.";
  } catch (error) {
    console.error("Chat Error:", error);
    return "Connection lost. Retry.";
  }
};

export const parseReceiptImage = async (base64Image: string): Promise<{ merchant: string; date: string; amount: number; category: string } | null> => {
  const categoriesList = Object.values(Category).join(', ');

  try {
