import { generateNegotiationScript } from '../services/geminiService';

interface DashboardProps {
  accounts: Account[];
  transactions: Transaction[];
  onNavigate: (tab: string) => void;
  onAddAccount?: () => void;
  onAddTransaction?: () => void;
  onAddGoal?: () => void;
  formatCurrency: (amount: number) => string;
  onBatchCategoryUpdate?: (merchant: string, category: Category) => void; 
  userPlan?: UserPlan;
  onAskCoach?: (message: string) => void;
  negotiationUsage: number;
  onIncrementNegotiation: () => void;
}

const COLORS = ['#6366f1', '#ec4899', '#10b981', '#f59e0b', '#8b5cf6', '#3b82f6'];

const QUOTES = [
  { text: "Do not save what is left after spending, but spend what is left after saving.", author: "Warren Buffett" },
  { text: "A budget is telling your money where to go instead of wondering where it went.", author: "Dave Ramsey" },
  { text: "It's not your salary that makes you rich, it's your spending habits.", author: "Charles A. Jaffe" },
  { text: "The art is not in making money, but in keeping it.", author: "Proverb" },
];

const Dashboard: React.FC<DashboardProps> = ({ accounts, transactions, onNavigate, onAddAccount, onAddTransaction, onAddGoal, formatCurrency, onBatchCategoryUpdate, userPlan, onAskCoach, negotiationUsage, onIncrementNegotiation }) => {
  const hasData = accounts.length > 0 || transactions.length > 0;
  const randomQuote = useMemo(() => QUOTES[Math.floor(Math.random() * QUOTES.length)], []);
  const netWorth = useMemo(() => accounts.reduce((acc, curr) => acc + curr.balance, 0), [accounts]);

  const [isNegotiating, setIsNegotiating] = useState(false);
  const [script, setScript] = useState<string | null>(null);
  const [scriptMerchant, setScriptMerchant] = useState('');
  const [showNegotiationModal, setShowNegotiationModal] = useState(false);
  const [copySuccess, setCopySuccess] = useState(false);

  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const currentMonth = today.getMonth();
  const currentYear = today.getFullYear();
  const dayOfMonth = today.getDate();
  const daysInMonth = new Date(currentYear, currentMonth + 1, 0).getDate();

  const monthlySpending = useMemo(() => {
    return transactions
      .filter(t => {
        const d = new Date(t.date);
        return t.type === TransactionType.EXPENSE && d.getMonth() === currentMonth && d.getFullYear() === currentYear;
      })
      .reduce((acc, curr) => acc + curr.amount, 0);
  }, [transactions, currentMonth, currentYear]);

  const monthlyIncome = useMemo(() => {
    return transactions
      .filter(t => {
        const d = new Date(t.date);
        return t.type === TransactionType.INCOME && d.getMonth() === currentMonth && d.getFullYear() === currentYear;
      })
      .reduce((acc, curr) => acc + curr.amount, 0);
  }, [transactions, currentMonth, currentYear]);

  const burnRate = monthlySpending / Math.max(dayOfMonth, 1);

  // --- Recurring Expense Logic (Vampire Detector v3) ---
  const recurringData = useMemo(() => {
      const merchantMap = new Map<string, { 
          count: number; 
          total: number; 
          amounts: number[]; 
          displayNames: string[]; 
          categories: Set<Category>; 
      }>();

      transactions
        .filter(t => t.type === TransactionType.EXPENSE)
        .forEach(t => {
            const normalizedKey = t.merchant.toLowerCase().trim();
            const existing = merchantMap.get(normalizedKey) || { 
                count: 0, 
                total: 0, 
                amounts: [], 
                displayNames: [], 
                categories: new Set() 
            };

            existing.count++;
            existing.total += t.amount;
            existing.amounts.push(t.amount);
            existing.displayNames.push(t.merchant);
            existing.categories.add(t.category);

            merchantMap.set(normalizedKey, existing);
        });

      const recurringItems: { merchant: string; avgCost: number; frequency: string; isSubscription: boolean }[] = [];
      let totalMonthlyFixed = 0;

      merchantMap.forEach((data, key) => {
          const avg = data.total / data.count;

          const isExplicitSubscription = data.categories.has(Category.SUBSCRIPTION);
          const isConsistent = data.amounts.every(a => Math.abs(a - avg) / avg < 0.25);
          const hasExactMatches = new Set(data.amounts).size < data.amounts.length;
          const isDetectedPattern = data.count > 1 && (isConsistent || hasExactMatches);

          if (isExplicitSubscription || isDetectedPattern) {
              const nameCounts = data.displayNames.reduce((acc, name) => {
                  acc[name] = (acc[name] || 0) + 1;
                  return acc;
              }, {} as Record<string, number>);
              const bestName = Object.keys(nameCounts).reduce((a, b) => nameCounts[a] > nameCounts[b] ? a : b);

              recurringItems.push({
                  merchant: bestName,
                  avgCost: avg,
                  frequency: 'Monthly',
                  isSubscription: isExplicitSubscription
              });
              totalMonthlyFixed += avg;
          }
      });

      return { items: recurringItems.sort((a,b) => b.avgCost - a.avgCost), total: totalMonthlyFixed };
  }, [transactions]);

  const spendingData = useMemo(() => {
    const dataPoints: { date: string, actual: number | null, predicted: number | null, timestamp: number }[] = [];
    const expenseMap = new Map<string, number>();
    transactions
      .filter(t => t.type === TransactionType.EXPENSE)
      .forEach(t => {
        const d = new Date(t.date);
        d.setHours(0, 0, 0, 0);
        const key = d.toDateString();
        expenseMap.set(key, (expenseMap.get(key) || 0) + t.amount);
      });

    const startDate = new Date(today);
    startDate.setDate(today.getDate() - 30);

    for (let i = 0; i <= 30; i++) {
        const d = new Date(startDate);
        d.setDate(startDate.getDate() + i);
        d.setHours(0, 0, 0, 0);

        const key = d.toDateString();
        dataPoints.push({
            date: d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }),
            actual: expenseMap.get(key) || 0,
            predicted: null,
            timestamp: d.getTime()
        });
    }

    const lastPoint = dataPoints[dataPoints.length - 1];
    lastPoint.predicted = lastPoint.actual;

    for (let i = 1; i <= 7; i++) {
        const d = new Date(today);
        d.setDate(today.getDate() + i);
        d.setHours(0, 0, 0, 0);

        const trendModifier = 1 + (Math.sin(i * 0.5) * 0.1); 
        const predAmount = Math.max(burnRate * trendModifier, 0);

        dataPoints.push({
            date: d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }),
            actual: null,
            predicted: predAmount,
            timestamp: d.getTime()
        });
    }

    return dataPoints.sort((a, b) => a.timestamp - b.timestamp);
  }, [transactions, burnRate]);

  const categoryData = useMemo(() => {
    const map = new Map<string, number>();
    transactions
      .filter(t => t.type === TransactionType.EXPENSE)
      .forEach(t => {
        map.set(t.category, (map.get(t.category) || 0) + t.amount);
      });
    const total = Array.from(map.values()).reduce((a, b) => a + b, 0);
    return Array.from(map.entries())
        .map(([name, value]) => ({ name, value, percent: total > 0 ? (value / total) * 100 : 0 }))
        .sort((a, b) => b.value - a.value);
  }, [transactions]);

  const handleNegotiateClick = async (merchant: string, amount: number) => {
      // Limits: Starter (1), Pro (5), Elite (Unlimited)
      const limit = userPlan === 'ultra' ? Infinity : userPlan === 'pro' ? 5 : 1;

      if (negotiationUsage >= limit) {
          onNavigate('plans');
          return; 
      }

      setIsNegotiating(true);
      setScriptMerchant(merchant);
      setScript(null);
      setShowNegotiationModal(true);

      const generatedScript = await generateNegotiationScript(merchant, amount);
      setScript(generatedScript);
      setIsNegotiating(false);
      onIncrementNegotiation();
  };

  const handleCopyScript = () => {
      if (script) {
          navigator.clipboard.writeText(script);
          setCopySuccess(true);
          setTimeout(() => setCopySuccess(false), 2000);
      }
  };

  const demoData = useMemo(() => [
    { date: 'Dec 01', actual: 450, predicted: 450 },
    { date: 'Dec 05', actual: 620, predicted: 600 },
    { date: 'Dec 10', actual: 800, predicted: 850 },
    { date: 'Dec 15', actual: 550, predicted: 600 },
    { date: 'Dec 20', actual: 900, predicted: 880 },
    { date: 'Dec 25', actual: null, predicted: 950 },
    { date: 'Dec 30', actual: null, predicted: 1100 },
  ], []);

  if (!hasData) {
     return (
        <div className="flex flex-col items-center justify-center w-full min-h-full py-12 animate-fade-in text-center relative">
            <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[600px] h-[600px] bg-indigo-500/10 rounded-full blur-[120px] pointer-events-none animate-pulse-slow"></div>
            <div className="max-w-4xl mx-auto mb-12 relative z-10">
                <div className="flex justify-center mb-8">
                    <div className="w-14 h-14 rounded-2xl bg-gradient-to-tr from-amber-400 to-orange-500 flex items-center justify-center shadow-[0_0_30px_rgba(251,191,36,0.3)] rotate-3">
                        <Quote className="w-7 h-7 text-white fill-current" />
                    </div>
                </div>
                <h1 className="text-3xl md:text-4xl font-bold text-white tracking-tight mb-4 leading-tight px-4">"{randomQuote.text}"</h1>
                <p className="text-lg text-slate-400 font-medium italic tracking-wide">— {randomQuote.author}</p>
            </div>
            <div className="w-full max-w-4xl mb-12 relative z-10 animate-slide-up px-4" style={{ animationDelay: '0.1s' }}>
                <div className="glass-card p-8 rounded-3xl border border-white/10 relative overflow-hidden group hover:border-indigo-500/30 transition-colors">
                     <div className="absolute top-0 right-0 w-64 h-64 bg-indigo-500/10 rounded-full blur-3xl -mr-16 -mt-16 pointer-events-none"></div>
                     <div className="flex justify-between items-center mb-6 relative z-10">
                        <div className="text-left">
                            <h3 className="text-lg font-bold text-white flex items-center gap-2">
                                <TrendingUp className="w-5 h-5 text-indigo-400" /> Cash Flow Forecast
                            </h3>
                            <p className="text-slate-400 text-sm">AI-driven spending trajectory (Preview)</p>
                        </div>
                    </div>
                    <div className="h-[240px] w-full relative z-10 opacity-90 group-hover:opacity-100 transition-opacity">
                        <ResponsiveContainer width="100%" height="100%">
                          <AreaChart data={demoData} margin={{ top: 10, right: 0, left: -20, bottom: 0 }}>
                            <defs>
