import confetti from 'canvas-confetti';

interface GoalsProps {
  goals?: Goal[];
  budgets?: Budget[];
  transactions?: Transaction[];
  onAddGoal?: (goal: Goal) => void;
  onUpdateGoal?: (goal: Goal) => void;
  onAddBudget?: (budget: Budget) => void;
  onDeleteBudget?: (id: string) => void;
  formatCurrency: (amount: number) => string;
}

const Goals: React.FC<GoalsProps> = ({ goals = [], budgets = [], transactions = [], onAddGoal, onUpdateGoal, onAddBudget, onDeleteBudget, formatCurrency }) => {
    const [isAddGoalModalOpen, setIsAddGoalModalOpen] = useState(false);
    const [isAddBudgetModalOpen, setIsAddBudgetModalOpen] = useState(false);
    const [selectedGoal, setSelectedGoal] = useState<Goal | null>(null);
    const [depositAmount, setDepositAmount] = useState('');
    const [streak, setStreak] = useState(0);

    useEffect(() => {
        const lastVisit = localStorage.getItem('nova_last_visit');
        const currentStreak = parseInt(localStorage.getItem('nova_streak') || '0');
        const today = new Date().toDateString();

        if (lastVisit !== today) {
            const yesterday = new Date();
            yesterday.setDate(yesterday.getDate() - 1);
            if (lastVisit === yesterday.toDateString()) {
                const newStreak = currentStreak + 1;
                setStreak(newStreak);
                localStorage.setItem('nova_streak', newStreak.toString());
            } else {
                setStreak(1);
                localStorage.setItem('nova_streak', '1');
            }
            localStorage.setItem('nova_last_visit', today);
        } else {
            setStreak(currentStreak || 1);
        }
    }, []);

    const handleDeposit = (e: React.FormEvent) => {
        e.preventDefault();
        if (!selectedGoal || !depositAmount) return;

        const amount = parseFloat(depositAmount);
        const newAmount = selectedGoal.currentAmount + amount;

        const updatedGoal = { ...selectedGoal, currentAmount: newAmount };
        if (onUpdateGoal) onUpdateGoal(updatedGoal);

        if (newAmount >= selectedGoal.targetAmount && selectedGoal.currentAmount < selectedGoal.targetAmount) {
             confetti({
                particleCount: 150,
                spread: 100,
                origin: { y: 0.6 },
                colors: ['#6366f1', '#ec4899', '#10b981', '#fbbf24']
            });
        }
        setSelectedGoal(null);
        setDepositAmount('');
    };

    return (
        <div className="space-y-12 animate-fade-in pb-10">
            <div><h2 className="text-3xl font-bold text-white tracking-tight">Goals & Budgets</h2><p className="text-slate-400 mt-2 font-medium max-w-lg">Manage your monthly limits and save for your biggest dreams.</p></div>

            <div className="relative bg-gradient-to-br from-indigo-900 to-violet-900 p-8 rounded-[2rem] shadow-2xl overflow-hidden group hover:scale-[1.01] transition-all duration-500 border border-white/10">
                <div className="absolute top-0 right-0 w-80 h-80 bg-gradient-to-br from-indigo-500/20 via-purple-500/20 to-transparent rounded-full blur-3xl -mr-20 -mt-20 group-hover:opacity-100 transition-opacity"></div>
                <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-full h-full bg-[radial-gradient(ellipse_at_center,_var(--tw-gradient-stops))] from-amber-500/10 via-transparent to-transparent opacity-50 pointer-events-none"></div>
                <div className="relative z-10 flex flex-col md:flex-row items-center gap-6 text-center md:text-left">
                    <div className="w-20 h-20 bg-gradient-to-tr from-amber-400 to-orange-500 rounded-3xl flex items-center justify-center shadow-[0_0_30px_rgba(251,191,36,0.4)] ring-4 ring-white/10 rotate-3 group-hover:rotate-6 transition-transform duration-500"><Trophy className="w-10 h-10 text-white drop-shadow-md" /></div>
                    <div className="flex-1">
                        <div className="flex items-center justify-center md:justify-start gap-3 mb-1"><h3 className="text-2xl font-extrabold text-white tracking-tight">{streak} Day Streak!</h3><span className="text-2xl animate-bounce filter drop-shadow-lg">🔥</span></div>
                        <p className="text-indigo-100 text-sm leading-relaxed font-medium max-w-xl opacity-90">Consistency compounds! You've checked in <span className="text-amber-300 font-bold">{streak} days in a row</span>.</p>
                    </div>
                </div>
            </div>

            <div>
                <div className="flex justify-between items-center mb-6"><h3 className="text-xl font-bold text-white flex items-center gap-2"><PieChart className="w-5 h-5 text-indigo-400" />Monthly Limits</h3><button onClick={() => setIsAddBudgetModalOpen(true)} className="px-4 py-2 bg-slate-800 hover:bg-slate-700 text-white rounded-xl text-sm font-bold border border-white/10 transition-colors flex items-center gap-2"><Plus className="w-4 h-4" /> Set Limit</button></div>
                {budgets.length === 0 ? (
                    <div className="glass-card p-10 rounded-3xl text-center border-dashed border-2 border-slate-700"><div className="w-16 h-16 rounded-full bg-slate-800/50 flex items-center justify-center mx-auto mb-4"><Wallet className="w-8 h-8 text-slate-500" /></div><h4 className="text-lg font-bold text-white mb-2">No active budgets</h4><p className="text-slate-400 text-sm max-w-sm mx-auto mb-6">Take control of your spending by setting limits for categories like Food or Shopping.</p><button onClick={() => setIsAddBudgetModalOpen(true)} className="text-indigo-400 hover:text-indigo-300 font-bold text-sm">Create your first budget &rarr;</button></div>
                ) : (
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                        {budgets.map((budget) => (<BudgetCard key={budget.id} budget={budget} transactions={transactions} onDelete={onDeleteBudget} formatCurrency={formatCurrency} />))}
                    </div>
                )}
            </div>

            <div className="h-px bg-white/5 w-full"></div>

            <div>
                <div className="flex justify-between items-center mb-6"><h3 className="text-xl font-bold text-white flex items-center gap-2"><Target className="w-5 h-5 text-emerald-400" />Savings Targets</h3><button onClick={() => setIsAddGoalModalOpen(true)} className="px-4 py-2 bg-slate-800 hover:bg-slate-700 text-white rounded-xl text-sm font-bold border border-white/10 transition-colors flex items-center gap-2"><Plus className="w-4 h-4" /> New Goal</button></div>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                    {goals.map((goal) => {
                        const progress = Math.min((goal.currentAmount / goal.targetAmount) * 100, 100);
                        const isCompleted = progress >= 100;
                        return (
                            <div key={goal.id} onClick={() => setSelectedGoal(goal)} className={`group glass-card p-7 rounded-[2rem] transition-all duration-300 hover:-translate-y-2 shadow-xl relative overflow-hidden cursor-pointer ${isCompleted ? 'border-amber-400/30 shadow-[0_0_50px_rgba(251,191,36,0.15)]' : 'border-white/5 hover:border-white/20'}`}>
                                <div className={`absolute top-0 right-0 w-48 h-48 bg-gradient-to-br ${goal.color} opacity-10 blur-[60px] rounded-full -mr-10 -mt-10 group-hover:opacity-25 transition-opacity duration-500`}></div>
                                {isCompleted && <div className="absolute inset-0 bg-gradient-to-br from-amber-500/10 to-transparent pointer-events-none"></div>}
                                <div className="flex justify-between items-start mb-8 relative z-10">
                                    <div className={`p-4 rounded-2xl bg-gradient-to-br ${goal.color} shadow-lg shadow-black/20 text-white ring-1 ring-white/20 transform group-hover:scale-110 transition-transform duration-300`}>
                                        {goal.icon === 'plane' && <Plane className="w-7 h-7" />}{goal.icon === 'shield' && <Target className="w-7 h-7" />}{goal.icon === 'laptop' && <Laptop className="w-7 h-7" />}{goal.icon === 'home' && <Home className="w-7 h-7" />}{!['plane','shield','laptop','home'].includes(goal.icon) && <Star className="w-7 h-7" />}
                                    </div>
                                    <div className="text-right"><span className="text-2xl font-bold text-white tracking-tight block">{formatCurrency(goal.currentAmount)}</span><p className="text-xs text-slate-400 font-bold uppercase tracking-wider mt-1">of {formatCurrency(goal.targetAmount)}</p></div>
                                </div>
                                <div className="flex items-center gap-2 mb-5 relative z-10"><h3 className="text-xl font-bold text-white">{goal.name}</h3>{isCompleted && (<span className="bg-amber-500/20 text-amber-300 text-[10px] font-bold px-2 py-0.5 rounded-full border border-amber-500/20 flex items-center gap-1 shadow-[0_0_10px_rgba(251,191,36,0.3)]"><Star className="w-3 h-3 fill-amber-300" /> Done</span>)}</div>
                                <div className="relative z-10">
                                    <div className="flex justify-between text-xs text-slate-400 mb-2 font-bold uppercase tracking-wider"><span>Progress</span><span className={isCompleted ? 'text-amber-400' : 'text-white'}>{progress.toFixed(0)}%</span></div>
                                    <div className="w-full bg-slate-800/80 h-3.5 rounded-full overflow-hidden border border-white/5 relative shadow-inner"><div className={`h-full rounded-full transition-all duration-1000 ease-out bg-gradient-to-r ${goal.color} relative`} style={{ width: `${progress}%` }}><div className="absolute inset-0 bg-white/20 animate-shimmer w-full translate-x-[-100%]"></div></div></div>
                                    <div className="mt-4 flex justify-between items-center text-xs text-slate-500 font-medium"><span>Target: {new Date(goal.deadline).toLocaleDateString()}</span>{isCompleted ? <span className="text-emerald-400 font-bold flex items-center gap-1"><Check className="w-4 h-4" /> Goal Reached!</span> : <span className="text-indigo-400 font-bold group-hover:underline flex items-center gap-1">Deposit Funds <Plus className="w-3 h-3" /></span>}</div>
                                </div>
                            </div>
                        );
                    })}
                    <button onClick={() => setIsAddGoalModalOpen(true)} className="border-2 border-dashed border-slate-700/50 rounded-[2rem] flex flex-col items-center justify-center p-8 text-slate-500 hover:border-indigo-500/50 hover:text-indigo-400 hover:bg-slate-800/30 transition-all group h-full min-h-[280px]">
                        <div className="w-16 h-16 rounded-full bg-slate-800/80 group-hover:bg-indigo-500/10 flex items-center justify-center mb-5 transition-colors ring-1 ring-white/10 group-hover:ring-indigo-500/30 group-hover:scale-110 duration-300"><Plus className="w-8 h-8 group-hover:rotate-90 transition-transform duration-300" /></div><span className="font-bold text-base">Add New Goal</span>
                    </button>
                </div>
            </div>

            {isAddGoalModalOpen && onAddGoal && (<AddGoalModal onClose={() => setIsAddGoalModalOpen(false)} onSubmit={onAddGoal} />)}
            {isAddBudgetModalOpen && onAddBudget && (<AddBudgetModal onClose={() => setIsAddBudgetModalOpen(false)} onSubmit={onAddBudget} />)}
            {selectedGoal && onUpdateGoal && (<DepositModal goal={selectedGoal} amount={depositAmount} setAmount={setDepositAmount} onClose={() => setSelectedGoal(null)} onSubmit={handleDeposit} />)}
        </div>
    );
};

const BudgetCard: React.FC<{ budget: Budget, transactions: Transaction[], onDelete?: (id: string) => void, formatCurrency: (amount: number) => string }> = ({ budget, transactions, onDelete, formatCurrency }) => {
    const spent = useMemo(() => {
        const now = new Date();
        return transactions.filter(t => t.category === budget.category && t.type === TransactionType.EXPENSE && new Date(t.date).getMonth() === now.getMonth() && new Date(t.date).getFullYear() === now.getFullYear()).reduce((acc, t) => acc + t.amount, 0);
    }, [budget.category, transactions]);
    const percentage = Math.min((spent / budget.limit) * 100, 100);
    const remaining = budget.limit - spent;
    const isOver = spent > budget.limit;
    const isWarning = percentage > 80 && !isOver;
    let statusColor = "bg-emerald-500";
    if (isWarning) statusColor = "bg-amber-500";
    else if (isOver) statusColor = "bg-rose-500";

    return (
        <div className="glass-card p-6 rounded-3xl relative group overflow-hidden border border-white/5 hover:border-white/20 transition-all">
            {onDelete && (<button onClick={() => onDelete(budget.id)} className="absolute top-4 right-4 p-2 bg-slate-900/50 rounded-lg text-slate-500 hover:text-rose-400 hover:bg-rose-950 opacity-0 group-hover:opacity-100 transition-all z-20"><Trash2 className="w-4 h-4" /></button>)}
            <div className="flex justify-between items-start mb-4">
                <div className="flex items-center gap-3"><div className={`p-3 rounded-xl bg-slate-800/50 border border-white/10 ${isOver ? 'ring-2 ring-rose-500/20' : ''}`}><PieChart className={`w-6 h-6 ${isOver ? 'text-rose-400' : 'text-indigo-400'}`} /></div><div><h4 className="font-bold text-white">{budget.category}</h4><p className="text-xs text-slate-400 font-medium">{isOver ? 'Over Budget' : `${percentage.toFixed(0)}% Used`}</p></div></div>
            </div>
            <div className="space-y-2">
                <div className="flex justify-between text-sm font-bold text-slate-300"><span className={isOver ? 'text-rose-400' : ''}>{formatCurrency(spent)}</span><span className="text-slate-500">/{formatCurrency(budget.limit)}</span></div>
                <div className="w-full bg-slate-800 h-2.5 rounded-full overflow-hidden flex border border-white/5"><div className={`h-full rounded-full transition-all duration-1000 ${statusColor} relative`} style={{ width: `${percentage}%` }}>{isOver && <div className="absolute inset-0 bg-white/20 animate-pulse"></div>}</div></div>
                <div className="flex justify-between items-center mt-2"><span className="text-xs font-bold text-slate-500 uppercase tracking-wider">Remaining</span><span className={`text-xs font-bold ${remaining < 0 ? 'text-rose-400' : 'text-emerald-400'}`}>{remaining < 0 ? '-' : ''}{formatCurrency(Math.abs(remaining))}</span></div>
            </div>
        </div>
    );
};

const AddGoalModal: React.FC<{ onClose: () => void, onSubmit: (g: Goal) => void }> = ({ onClose, onSubmit }) => {
    const [name, setName] = useState('');
    const [target, setTarget] = useState('');
    const [date, setDate] = useState('');
    const [error, setError] = useState('');

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        setError('');

        // Date Validation
        const today = new Date();
        today.setHours(0, 0, 0, 0);
        const inputDate = new Date(date);

        // Check 1: Is valid date
        if (isNaN(inputDate.getTime())) {
            setError("Please enter a valid date.");
            return;
        }

        // Check 2: Not in past
        if (inputDate < today) {
            setError("Goal deadline cannot be in the past.");
            return;
        }

        // Check 3: Not exceeding reasonable range (e.g., 50 years)
        const maxDate = new Date();
        maxDate.setFullYear(maxDate.getFullYear() + 50);
        if (inputDate > maxDate) {
            setError("Date exceeds valid range (50 years). Please enter a closer target.");
            return;
        }

        const newGoal: Goal = { 
            id: Date.now().toString(), 
            name, 
            targetAmount: parseFloat(target), 
            currentAmount: 0, 
            deadline: date, 
            icon: 'star', 
            color: 'from-pink-500 to-rose-500' 
        };
        onSubmit(newGoal);
        onClose();
    };

    const minDate = new Date().toISOString().split('T')[0];

    return (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/90 backdrop-blur-xl animate-fade-in">
             <div className="bg-[#0f172a] border border-white/10 rounded-3xl w-full max-w-sm shadow-2xl overflow-hidden animate-slide-up relative ring-1 ring-white/5">
                 <button onClick={onClose} className="absolute top-4 right-4 p-2 text-slate-400 hover:text-white z-10"><XCircle className="w-6 h-6" /></button>
                 <div className="p-8 border-b border-white/5 bg-gradient-to-br from-indigo-900/20 to-transparent"><h3 className="text-2xl font-bold text-white flex items-center gap-2"><Target className="w-6 h-6 text-indigo-400" />New Goal</h3><p className="text-slate-400 text-sm mt-1">Set a target and track your progress.</p></div>
                 <form onSubmit={handleSubmit} className="p-8 space-y-5">
                     <div><label className="text-xs font-bold text-slate-400 uppercase tracking-wider">Goal Name</label><input required type="text" value={name} onChange={e => setName(e.target.value)} className="w-full bg-slate-950/50 border border-white/10 rounded-xl p-3.5 text-white mt-2 focus:border-indigo-500 focus:outline-none focus:ring-4 focus:ring-indigo-500/10 transition-all placeholder:text-slate-600" placeholder="e.g. Dream Vacation" /></div>
                     <div><label className="text-xs font-bold text-slate-400 uppercase tracking-wider">Target Amount</label><div className="relative mt-2"><DollarSign className="absolute left-3.5 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500" /><input required type="number" value={target} onChange={e => setTarget(e.target.value)} className="w-full bg-slate-950/50 border border-white/10 rounded-xl p-3.5 pl-9 text-white focus:border-indigo-500 focus:outline-none focus:ring-4 focus:ring-indigo-500/10 transition-all placeholder:text-slate-600" placeholder="10000" /></div></div>
                     <div>
                         <label className="text-xs font-bold text-slate-400 uppercase tracking-wider">Target Date</label>
