export default Accounts;

import React, { useState, useEffect, useMemo } from 'react';
import { Account, Budget, Goal, Transaction, UserPlan, ToastMessage, TransactionType, Category, BotMode } from './types';
import { ACCOUNTS, INITIAL_TRANSACTIONS, INITIAL_BUDGETS, INITIAL_GOALS, NAV_ITEMS } from './constants';
import Dashboard from './components/Dashboard';
import Transactions from './components/Transactions';
import Accounts from './components/Accounts';
import Insights from './components/Insights';
import Goals from './components/Goals';
import Plans from './components/Plans';
import Settings from './components/Settings';
import LandingPage from './components/LandingPage';
import ToastContainer from './components/Toast';
import { Sparkles, LogOut, Ambulance, Activity, X, ArrowRight, Bell, Zap, ShieldAlert, TrendingUp, CheckCircle, ChevronRight, Send, Lock, Crown } from 'lucide-react';

// Interfaces for Nova Bot Logic
interface AiNotification {
    id: string;
    type: 'critical' | 'warning' | 'success' | 'info';
    title: string;
    message: string;
    actionLabel?: string;
    actionTab?: string;
}

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');

  // --- PERSISTENCE LAYER ---
  // Load initial state from LocalStorage or fall back to constants (which are empty now)
  const [accounts, setAccounts] = useState<Account[]>(() => {
      const saved = localStorage.getItem('nova_accounts');
      return saved ? JSON.parse(saved) : ACCOUNTS;
  });
  const [transactions, setTransactions] = useState<Transaction[]>(() => {
      const saved = localStorage.getItem('nova_transactions');
      return saved ? JSON.parse(saved) : INITIAL_TRANSACTIONS;
  });
  const [budgets, setBudgets] = useState<Budget[]>(() => {
      const saved = localStorage.getItem('nova_budgets');
      return saved ? JSON.parse(saved) : INITIAL_BUDGETS;
  });
  const [goals, setGoals] = useState<Goal[]>(() => {
      const saved = localStorage.getItem('nova_goals');
      return saved ? JSON.parse(saved) : INITIAL_GOALS;
  });

  const [userPlan, setUserPlan] = useState<UserPlan>(() => localStorage.getItem('nova_user_plan') as UserPlan || 'free');

  // Free Trial & Usage State
  const [freeTrialUsage, setFreeTrialUsage] = useState(() => parseInt(localStorage.getItem('nova_free_trial') || '0'));
  const [scanUsage, setScanUsage] = useState(() => parseInt(localStorage.getItem('nova_scan_usage') || '0'));
  const [negotiationUsage, setNegotiationUsage] = useState(() => parseInt(localStorage.getItem('nova_negotiation_usage') || '0'));

  const [isLoggedIn, setIsLoggedIn] = useState(() => localStorage.getItem('nova_auth_token') !== null);
  const [toasts, setToasts] = useState<ToastMessage[]>([]);
  const [showDangerModal, setShowDangerModal] = useState(false);
  const [showCoachLockModal, setShowCoachLockModal] = useState(false);

  // Bot States
  const [showBotPanel, setShowBotPanel] = useState(false);
  const [botNotifications, setBotNotifications] = useState<AiNotification[]>([]);
  const [dismissedNotificationIds, setDismissedNotificationIds] = useState<string[]>([]);
  const [pendingChatQuery, setPendingChatQuery] = useState<string | null>(null);
  const [botMode, setBotMode] = useState<BotMode>(() => (localStorage.getItem('nova_bot_mode') as BotMode) || 'ruthless');

  // User Appearance States
  const [userName, setUserName] = useState(() => localStorage.getItem('nova_user_name') || '');
  const [userEmail, setUserEmail] = useState(() => localStorage.getItem('nova_user_email') || 'pilot@nova.io');
  const [userAvatar, setUserAvatar] = useState(() => localStorage.getItem('nova_user_avatar') || 'bg-indigo-600');
  const [userAvatarZoom, setUserAvatarZoom] = useState(() => parseFloat(localStorage.getItem('nova_user_avatar_zoom') || '1'));
  const [userAvatarPos, setUserAvatarPos] = useState(() => {
    const x = parseFloat(localStorage.getItem('nova_user_avatar_pos_x') || '0');
    const y = parseFloat(localStorage.getItem('nova_user_avatar_pos_y') || '0');
    return { x, y };
  });
  const [userBorder, setUserBorder] = useState(() => localStorage.getItem('nova_user_border') || 'default');
  const [userBackground, setUserBackground] = useState(() => localStorage.getItem('nova_user_background') || '');

  // --- AUTO-SAVE EFFECTS ---
  useEffect(() => { localStorage.setItem('nova_accounts', JSON.stringify(accounts)); }, [accounts]);
  useEffect(() => { localStorage.setItem('nova_transactions', JSON.stringify(transactions)); }, [transactions]);
  useEffect(() => { localStorage.setItem('nova_budgets', JSON.stringify(budgets)); }, [budgets]);
  useEffect(() => { localStorage.setItem('nova_goals', JSON.stringify(goals)); }, [goals]);
  useEffect(() => { localStorage.setItem('nova_free_trial', freeTrialUsage.toString()); }, [freeTrialUsage]);
  useEffect(() => { localStorage.setItem('nova_scan_usage', scanUsage.toString()); }, [scanUsage]);
  useEffect(() => { localStorage.setItem('nova_negotiation_usage', negotiationUsage.toString()); }, [negotiationUsage]);
  useEffect(() => { localStorage.setItem('nova_bot_mode', botMode); }, [botMode]);

  const addToast = (message: string, type: ToastMessage['type'] = 'success') => {
    const id = Date.now().toString();
    setToasts(prev => [...prev, { id, message, type }]);
  };

  const removeToast = (id: string) => {
    setToasts(prev => prev.filter(toast => toast.id !== id));
  };

  const formatCurrency = (amount: number) => `$${amount.toLocaleString()}`;

  const handleAddAccount = (acc: Account) => setAccounts([...accounts, acc]);
  const handleUpdateAccount = (acc: Account) => setAccounts(accounts.map(a => a.id === acc.id ? acc : a));
  const handleDeleteAccount = (id: string) => setAccounts(accounts.filter(a => a.id !== id));

  const handleAddTransaction = (t: Transaction) => {
    setTransactions(prev => [t, ...prev]);
    if (t.accountId && t.accountId !== 'manual') {
      setAccounts(prev => prev.map(acc => {
        if (acc.id === t.accountId) {
          const newBalance = t.type === TransactionType.EXPENSE
            ? acc.balance - t.amount
            : acc.balance + t.amount;
          return { ...acc, balance: newBalance };
        }
        return acc;
      }));
    }
    addToast('Transaction recorded & Balance updated.', 'success');
  };

  const handleDeleteTransaction = (id: string) => {
    const txToDelete = transactions.find(t => t.id === id);
    setTransactions(prev => prev.filter(t => t.id !== id));
    if (txToDelete && txToDelete.accountId && txToDelete.accountId !== 'manual') {
      setAccounts(prev => prev.map(acc => {
        if (acc.id === txToDelete.accountId) {
          const newBalance = txToDelete.type === TransactionType.EXPENSE
            ? acc.balance + txToDelete.amount
            : acc.balance - txToDelete.amount;
          return { ...acc, balance: newBalance };
        }
        return acc;
      }));
    }
    addToast('Transaction removed & Balance reverted.', 'info');
  };

  const handleBatchCategoryUpdate = (merchant: string, category: Category) => {
    // Case-insensitive matching for batch update
    const normalizedMerchant = merchant.toLowerCase().trim();
    setTransactions(prev => prev.map(t => 
        t.merchant.toLowerCase().trim() === normalizedMerchant ? { ...t, category } : t
    ));
    addToast(`All transactions for ${merchant} marked as ${category}`, 'success');
  };

  const handleUpdateProfile = (name: string, email: string, avatar: string, zoom: number, pos: { x: number; y: number }, border: string) => {
    setUserName(name);
    setUserEmail(email);
    setUserAvatar(avatar);
    setUserAvatarZoom(zoom);
    setUserAvatarPos(pos);
    setUserBorder(border);

    try {
      localStorage.setItem('nova_user_name', name);
      localStorage.setItem('nova_user_email', email);
      localStorage.setItem('nova_user_avatar', avatar);
      localStorage.setItem('nova_user_avatar_zoom', zoom.toString());
      localStorage.setItem('nova_user_avatar_pos_x', pos.x.toString());
      localStorage.setItem('nova_user_avatar_pos_y', pos.y.toString());
      localStorage.setItem('nova_user_border', border);
    } catch (e) {
      addToast("Storage full. Image may not persist.", "error");
    }
  };

  const handleUpdateBackground = (bg: string) => {
      setUserBackground(bg);
      try {
          localStorage.setItem('nova_user_background', bg);
      } catch (e) {
          addToast("Image too large to save.", "error");
      }
  };

  const handleSignOut = () => {
    // Only remove auth, keep data
    localStorage.removeItem('nova_auth_token');
    localStorage.removeItem('nova_user_name');
    localStorage.removeItem('nova_user_email');
    localStorage.removeItem('nova_user_avatar');
    setIsLoggedIn(false);
  };

  const handleClearData = () => {
      // Nuclear Reset
      localStorage.removeItem('nova_accounts');
      localStorage.removeItem('nova_transactions');
      localStorage.removeItem('nova_budgets');
      localStorage.removeItem('nova_goals');
      localStorage.removeItem('nova_user_background');
      localStorage.removeItem('nova_free_trial');
      localStorage.removeItem('nova_scan_usage');
      localStorage.removeItem('nova_negotiation_usage');
      setUserBackground('');
      setFreeTrialUsage(0);
      setScanUsage(0);
      setNegotiationUsage(0);

      setAccounts([]);
      setTransactions([]);
      setBudgets([]);
      setGoals([]);
      addToast("Core data system wiped. Starting fresh.", "error");
  };

  const handleAskCoach = (query: string) => {
      setPendingChatQuery(query);
      setActiveTab('insights');
  };

  const handleApplyBudgets = (newBudgets: Budget[]) => {
      setBudgets(prev => {
          const updated = [...prev];
          newBudgets.forEach(nb => {
              const index = updated.findIndex(b => b.category === nb.category);
              if (index >= 0) {
                  // Update existing
                  updated[index] = { ...updated[index], limit: nb.limit };
              } else {
                  // Add new
                  updated.push({ ...nb, id: Date.now().toString() + Math.random() });
              }
          });
          return updated;
      });
      addToast('Budgets auto-tuned by Nova AI.', 'success');
  };

  const handleIncrementTrial = () => {
      const newCount = freeTrialUsage + 1;
      setFreeTrialUsage(newCount);
      if (newCount >= 1) {
           // Push notification immediately when limit is hit
           setBotNotifications(prev => [
              ...prev,
              {
                  id: 'trial-ended',
                  type: 'warning',
                  title: 'Trial Limit Reached',
                  message: 'You have used your 1 free AI interaction. Upgrade to Pro for unlimited access.',
                  actionLabel: 'Upgrade Now',
                  actionTab: 'plans'
              }
           ]);
           // Ensure panel opens to show the notification
           setShowBotPanel(true);
      }
  };

  const handleIncrementScan = () => {
      setScanUsage(prev => prev + 1);
  };

  const handleIncrementNegotiation = () => {
      setNegotiationUsage(prev => prev + 1);
  };

  const handleUpgradePlan = (plan: UserPlan) => {
      setUserPlan(plan);
      localStorage.setItem('nova_user_plan', plan);
      setActiveTab('dashboard');
      setShowDangerModal(false); 
      setShowCoachLockModal(false);
      addToast(`Plan upgraded to ${plan.toUpperCase()}.`, 'success');
  };

  // --- NOVA INTELLIGENCE SYSTEM ---
  useEffect(() => {
      const generateNotifications = () => {
          const notes: AiNotification[] = [];
          const now = new Date();

          // Preserving existing trial ended notification if it exists in state
          const existingTrialNote = botNotifications.find(n => n.id === 'trial-ended');
          if (existingTrialNote) notes.push(existingTrialNote);

          const netWorth = accounts.reduce((acc, curr) => acc + curr.balance, 0);
          if (netWorth < 0 && !dismissedNotificationIds.includes('risk-nw')) {
              notes.push({
                  id: 'risk-nw',
                  type: 'critical',
                  title: 'Net Worth Critical',
                  message: 'Your liabilities exceed your assets. Immediate intervention recommended.',
                  actionLabel: 'View Analysis',
                  actionTab: 'insights'
              });
              // Pro users don't see the sales modal, but free users do
              if (userPlan === 'free') setShowDangerModal(true);
          }

          budgets.forEach(budget => {
              const spent = transactions
                  .filter(t => t.category === budget.category && 
                              t.type === TransactionType.EXPENSE && 
                              new Date(t.date).getMonth() === now.getMonth() && 
                              new Date(t.date).getFullYear() === now.getFullYear())
                  .reduce((acc, t) => acc + t.amount, 0);

              if (spent > budget.limit && !dismissedNotificationIds.includes(`over-${budget.id}`)) {
                  notes.push({
                      id: `over-${budget.id}`,
                      type: 'critical',
                      title: 'Budget Breached',
                      message: `You have exceeded your limit for ${budget.category} by ${formatCurrency(spent - budget.limit)}. Stop spending now.`,
                      actionLabel: 'Adjust Budget',
                      actionTab: 'goals'
                  });
              } else if (spent > budget.limit * 0.85 && !dismissedNotificationIds.includes(`warn-${budget.id}`)) {
                   notes.push({
                      id: `warn-${budget.id}`,
                      type: 'warning',
                      title: 'Budget at Risk',
                      message: `You are at 85% of your ${budget.category} limit. Slow down.`,
                      actionLabel: 'Check Spending',
                      actionTab: 'transactions'
                  });
              }
          });

          goals.forEach(goal => {
              const progress = goal.currentAmount / goal.targetAmount;
              if (progress >= 1 && goal.currentAmount > 0 && !dismissedNotificationIds.includes(`goal-${goal.id}`)) {
                  notes.push({
                      id: `goal-${goal.id}`,
                      type: 'success',
                      title: 'Goal Achieved!',
                      message: `Outstanding work. You've fully funded "${goal.name}". Set a new target to keep the momentum.`,
                      actionLabel: 'New Goal',
                      actionTab: 'goals'
                  });
              } else if (progress > 0.5 && progress < 0.6 && !dismissedNotificationIds.includes(`prog-${goal.id}`)) {
                   notes.push({
                      id: `prog-${goal.id}`,
                      type: 'info',
                      title: 'Halfway There',
                      message: `You're over 50% of the way to "${goal.name}". Consistency is key. Keep pushing.`,
                  });
              }
          });

          if (transactions.length === 0 && !dismissedNotificationIds.includes('empty-state')) {
               notes.push({
                  id: 'empty-state',
                  type: 'info',
                  title: 'System Idle',
                  message: 'No financial data detected. Feed the system transactions to generate insights.',
                  actionLabel: 'Log Expense',
                  actionTab: 'transactions'
              });
          }

          setBotNotifications(prev => {
              // Merge newly generated notes with current state (to keep the trial notification if triggered manually)
              const ids = new Set(notes.map(n => n.id));
              const currentTrial = prev.find(n => n.id === 'trial-ended');
              if (currentTrial && !ids.has('trial-ended')) {
                  return [...notes, currentTrial];
              }
              return notes;
          });
      };

      generateNotifications();
  }, [accounts, transactions, budgets, goals, userPlan, dismissedNotificationIds]);

  if (!isLoggedIn) {
    return <LandingPage onLoginSuccess={(name) => { setUserName(name); setIsLoggedIn(true); }} />;
  }

  const isPro = userPlan === 'pro' || userPlan === 'ultra';
  const isElite = userPlan === 'ultra';

  const isImageAvatar = userAvatar.includes('http') || userAvatar.startsWith('data:');
  const filteredNavItems = NAV_ITEMS.filter(item => !(isPro && item.id === 'plans'));

  const hasCritical = botNotifications.some(n => n.type === 'critical');
  const hasWarning = botNotifications.some(n => n.type === 'warning');
  const hasSuccess = botNotifications.some(n => n.type === 'success');
  const notificationCount = botNotifications.length;

  const getBorderClasses = (style: string) => {
    if (!isElite && style !== 'default') return 'ring-2 ring-white/10'; // Fallback if not Elite
    switch (style) {
      case 'gold': return 'ring-2 ring-amber-400 shadow-[0_0_15px_rgba(251,191,36,0.6)]';
      case 'rainbow': return 'ring-4 ring-transparent bg-gradient-to-tr from-rose-500 via-yellow-500 to-cyan-500 bg-[length:400%_400%] animate-gradient-xy p-[2px]';
      case 'neon': return 'ring-2 ring-cyan-400 shadow-[0_0_15px_rgba(34,211,238,0.6)]';
      case 'plasma': return 'ring-2 ring-fuchsia-500 shadow-[0_0_15px_rgba(217,70,239,0.6)]';
      default: return 'ring-1 ring-white/20';
    }
  };

  return (
    <div 
        className="flex h-screen text-slate-200 font-sans bg-cover bg-center transition-all duration-700 relative"
        style={{ 
            backgroundColor: '#020617',
            backgroundImage: userBackground ? `url(${userBackground})` : undefined 
        }}
    >
      {/* Background Overlay for readability if custom image is used */}
      {userBackground && <div className="absolute inset-0 bg-slate-950/70 backdrop-blur-sm pointer-events-none z-0"></div>}

      <aside className="w-64 bg-[#0f172a]/90 backdrop-blur-xl border-r border-white/5 p-6 flex flex-col hidden md:flex z-10">
        <div className="flex items-center gap-3 mb-12 relative group">
          <div className={`
            w-10 h-10 rounded-xl flex items-center justify-center shadow-lg transition-all duration-700
            ${isElite
                ? 'bg-gradient-to-br from-purple-600 via-indigo-600 to-violet-800 shadow-[0_0_30px_rgba(124,58,237,0.5)] ring-2 ring-purple-500/50'
                : isPro 
                    ? 'bg-gradient-to-br from-amber-400 via-orange-500 to-yellow-600 shadow-[0_0_30px_rgba(251,191,36,0.5)] ring-2 ring-amber-400/50'
                    : 'bg-indigo-600 shadow-indigo-600/20'
            }`}
          >
            {isElite ? (
                <Crown className="w-6 h-6 text-white drop-shadow-md" />
            ) : isPro ? (
                <Sparkles className="w-6 h-6 text-white drop-shadow-md" />
            ) : (
                <span className="text-white font-black text-lg">N</span>
            )}
          </div>
          <div>
            <h1 className="text-xl font-black tracking-tighter text-white">Nova AI</h1>
            {isPro && (
                <div className="absolute -top-1 -right-4">
                  <span className={`text-white text-[8px] font-black px-1.5 py-0.5 rounded border shadow-md uppercase tracking-widest ${isElite ? 'bg-gradient-to-r from-purple-500 to-indigo-600 border-purple-500/20 shadow-purple-500/30' : 'bg-gradient-to-r from-amber-400 to-orange-500 border-amber-500/20 shadow-amber-500/30'}`}>
                      {userPlan === 'ultra' ? 'ELITE' : 'PRO'}
                  </span>
                </div>
            )}
          </div>
        </div>
        <nav className="flex-1 space-y-1">
          {filteredNavItems.map(item => (
            <button
              key={item.id}
              onClick={() => setActiveTab(item.id)}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-semibold transition-all ${
                activeTab === item.id 
                  ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-600/20' 
                  : 'text-slate-400 hover:text-white hover:bg-white/5'
              }`}
            >
              <item.icon className="w-5 h-5" />
              {item.label}
            </button>
          ))}
        </nav>

        {/* User Profile Footer */}
        <div className="mt-auto pt-6 border-t border-white/5 space-y-3">
             <div 
                className="flex items-center gap-3 p-3 rounded-2xl bg-white/5 border border-white/5 hover:bg-white/10 transition-colors cursor-pointer group relative overflow-hidden"
                onClick={() => setActiveTab('settings')}
             >
                <div className={`w-10 h-10 rounded-full bg-slate-800 shrink-0 overflow-hidden relative shadow-sm transition-all ${getBorderClasses(userBorder)}`}>
                    {isImageAvatar ? (
                         <img 
                            src={userAvatar} 
                            alt="Profile"
                            className="w-full h-full object-cover"
                            style={{ 
                                transform: `scale(${userAvatarZoom}) translate(${userAvatarPos.x}px, ${userAvatarPos.y}px)` 
                            }}
                         />
                    ) : (
                        <div className={`w-full h-full ${userAvatar}`}></div>
                    )}
                </div>
                <div className="min-w-0 flex-1">
                    <h4 className="text-sm font-bold text-white truncate">{userName || 'Nova Pilot'}</h4>
                    <div className="flex items-center gap-2 mt-0.5">
                        <span className={`text-[9px] font-black px-1.5 py-0.5 rounded border uppercase tracking-widest ${isElite ? 'bg-purple-500/10 text-purple-400 border-purple-500/20' : isPro ? 'bg-amber-500/10 text-amber-400 border-amber-500/20' : 'bg-slate-700/50 text-slate-400 border-slate-600/50'}`}>
                            {userPlan === 'ultra' ? 'ELITE PLAN' : userPlan === 'pro' ? 'PRO PLAN' : 'FREE'}
                        </span>
                    </div>
                </div>
             </div>

             <button 
                onClick={handleSignOut}
                className="w-full flex items-center justify-center gap-2 p-2 text-xs font-bold text-slate-500 hover:text-rose-400 hover:bg-rose-500/10 rounded-lg transition-colors group"
             >
                <LogOut className="w-3.5 h-3.5 group-hover:translate-x-0.5 transition-transform" /> Sign Out
             </button>
        </div>
      </aside>

      <main className="flex-1 overflow-auto p-4 md:p-10 relative z-10">
        <div className="max-w-7xl mx-auto pb-20 md:pb-0">
            {/* Mobile Header */}
            <div className="md:hidden flex justify-between items-center mb-6">
                <div className="flex items-center gap-2">
                    <div className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center font-black text-white">N</div>
                    <span className="font-bold text-white">Nova AI</span>
                </div>
                 <div className="flex gap-2">
                     {NAV_ITEMS.slice(0, 3).map(item => (
                         <button key={item.id} onClick={() => setActiveTab(item.id)} className={`p-2 rounded-lg ${activeTab === item.id ? 'bg-indigo-600 text-white' : 'bg-slate-800 text-slate-400'}`}>
                             <item.icon className="w-5 h-5" />
                         </button>
                     ))}
                 </div>
            </div>

          {activeTab === 'dashboard' && (
            <Dashboard 
              accounts={accounts} 
              transactions={transactions} 
              onNavigate={setActiveTab}
              onAddAccount={() => setActiveTab('accounts')}
              onAddTransaction={() => setActiveTab('transactions')}
              onAddGoal={() => setActiveTab('goals')}
              onBatchCategoryUpdate={handleBatchCategoryUpdate} 
              formatCurrency={formatCurrency} 
              userPlan={userPlan} 
              onAskCoach={handleAskCoach}
              negotiationUsage={negotiationUsage}
              onIncrementNegotiation={handleIncrementNegotiation}
            />
          )}
          {activeTab === 'transactions' && (
            <Transactions 
              transactions={transactions} 
              accounts={accounts}
              onDelete={handleDeleteTransaction}
              onAdd={handleAddTransaction}
              formatCurrency={formatCurrency}
              onNavigateToAccounts={() => setActiveTab('accounts')}
              userPlan={userPlan}
              scanUsage={scanUsage}
              onIncrementScan={handleIncrementScan}
            />
          )}
          {activeTab === 'accounts' && (
              <Accounts 
                  accounts={accounts} 
                  budgets={budgets} 
                  transactions={transactions}
                  userPlan={userPlan}
                  onAdd={handleAddAccount}
                  onUpdate={handleUpdateAccount}
                  onDelete={handleDeleteAccount}
                  formatCurrency={formatCurrency}
                  userName={userName}
                  userAvatar={userAvatar}
                  userAvatarZoom={userAvatarZoom}
                  userAvatarPos={userAvatarPos}
                  userBorder={userBorder}
                  onNavigate={setActiveTab}
              />
          )}
          {activeTab === 'insights' && (
            <Insights 
              transactions={transactions} 
              userPlan={userPlan} 
              onUpgradeClick={() => setActiveTab('plans')}
              formatCurrency={formatCurrency} 
              initialPrompt={pendingChatQuery}
              onPromptHandled={() => setPendingChatQuery(null)} 
              onApplyBudgets={handleApplyBudgets} 
              freeTrialUsage={freeTrialUsage}
              onIncrementTrial={handleIncrementTrial}
              botMode={botMode}
            />
          )}
          {activeTab === 'goals' && (
            <Goals 
              goals={goals} 
              budgets={budgets} 
              transactions={transactions}
              onAddGoal={(g) => setGoals([...goals, g])}
              onUpdateGoal={(g) => setGoals(goals.map(prev => prev.id === g.id ? g : prev))}
              onAddBudget={(b) => setBudgets([...budgets, b])}
              onDeleteBudget={(id) => setBudgets(budgets.filter(b => b.id !== id))}
              formatCurrency={formatCurrency} 
            />
          )}
          {activeTab === 'plans' && (
            <Plans 
              currentPlan={userPlan} 
              onUpgrade={handleUpgradePlan}
              onDowngrade={() => {
                setUserPlan('free');
                localStorage.setItem('nova_user_plan', 'free');
                addToast("Plan deactivated. AI Coach access revoked.", "info");
              }}
            />
          )}
          {activeTab === 'settings' && (
            <Settings 
              userName={userName}
              userEmail={userEmail}
              userAvatar={userAvatar}
              userAvatarZoom={userAvatarZoom}
              userAvatarPos={userAvatarPos}
              userBorder={userBorder}
              userBackground={userBackground}
              onUpdateBackground={handleUpdateBackground}
              userPlan={userPlan}
              onUpdateProfile={handleUpdateProfile} 
              addToast={addToast}
              onExportData={() => {}}
              onImportData={() => {}}
              onClearData={handleClearData} 
              language="en"
              onUpdateLanguage={() => {}}
              currency="USD"
              onUpdateCurrency={() => {}}
              botMode={botMode}
              onUpdateBotMode={setBotMode}
            />
          )}
        </div>
      </main>
      <ToastContainer toasts={toasts} onRemove={removeToast} />

      {showDangerModal && (
        <EmergencyUpsellModal 
          onClose={() => setShowDangerModal(false)} 
          onUpgrade={() => {
            setShowDangerModal(false);
            setActiveTab('plans');
          }} 
        />
      )}

      {showCoachLockModal && (
        <CoachLockModal 
          onClose={() => setShowCoachLockModal(false)} 
          onUpgrade={() => {
            setShowCoachLockModal(false);
            setActiveTab('plans');
          }} 
        />
      )}

      {/* --- NOVA BOT NOTIFICATION SYSTEM --- */}
      <div className="fixed bottom-6 right-6 z-[100] flex flex-col items-end">

          {showBotPanel && (
              <div className="mb-4 w-80 md:w-96 glass-card rounded-3xl border border-white/20 overflow-hidden shadow-2xl animate-slide-up origin-bottom-right">
                  <div className={`p-4 flex items-center justify-between border-b border-white/10 bg-gradient-to-r ${hasCritical ? 'from-rose-900/80 to-slate-900' : hasWarning ? 'from-amber-900/80 to-slate-900' : 'from-indigo-900/80 to-slate-900'}`}>
                      <div className="flex items-center gap-3">
                          <div className={`w-8 h-8 rounded-full flex items-center justify-center ${hasCritical ? 'bg-rose-500 animate-pulse' : hasWarning ? 'bg-amber-500' : 'bg-indigo-500'}`}>
                              <Zap className="w-5 h-5 text-white fill-white" />
                          </div>
                          <div>
                              <h3 className="text-white font-bold text-sm">Nova Command</h3>
                              <p className="text-[10px] text-slate-300 font-bold uppercase tracking-wider">{hasCritical ? 'Alerts Active' : hasWarning ? 'Warning Active' : 'System Nominal'}</p>
                          </div>
                      </div>
                      <button onClick={() => setShowBotPanel(false)} className="text-white/50 hover:text-white"><X className="w-5 h-5" /></button>
                  </div>

                  <div className="max-h-[60vh] overflow-y-auto custom-scrollbar bg-[#0f172a]/95">
                      {botNotifications.length === 0 ? (
                          <div className="p-8 text-center">
                              <ShieldAlert className="w-10 h-10 text-slate-600 mx-auto mb-3" />
                              <p className="text-slate-400 text-xs">No active directives. You are running optimally.</p>
                          </div>
                      ) : (
                          <div className="flex flex-col">
                              {botNotifications.map((note) => (
                                  <div key={note.id} className={`p-5 border-b border-white/5 last:border-0 hover:bg-white/5 transition-colors ${note.type === 'critical' ? 'bg-rose-500/10' : note.type === 'warning' ? 'bg-amber-500/10' : note.type === 'success' ? 'bg-emerald-500/5' : ''}`}>
                                      <div className="flex gap-3 mb-2">
                                          {note.type === 'critical' && <ShieldAlert className="w-5 h-5 text-rose-500 shrink-0" />}
                                          {note.type === 'warning' && <Activity className="w-5 h-5 text-amber-500 shrink-0" />}
                                          {note.type === 'success' && <CheckCircle className="w-5 h-5 text-emerald-400 shrink-0" />}
                                          {note.type === 'info' && <Bell className="w-5 h-5 text-blue-400 shrink-0" />}
                                          <h4 className={`text-sm font-bold ${note.type === 'critical' ? 'text-rose-400' : note.type === 'warning' ? 'text-amber-400' : 'text-white'}`}>{note.title}</h4>
                                      </div>
                                      <p className="text-xs text-slate-300 leading-relaxed mb-3 pl-8">{note.message}</p>
                                      {note.actionLabel && (
                                          <div className="pl-8">
                                              <button 
                                                onClick={() => {
                                                    if (note.actionTab) setActiveTab(note.actionTab);
                                                    setShowBotPanel(false);
                                                    setShowDangerModal(false); 
                                                    setDismissedNotificationIds(prev => [...prev, note.id]);
                                                }}
                                                className={`text-[10px] font-bold uppercase tracking-wider flex items-center gap-1 hover:underline ${note.type === 'critical' ? 'text-rose-400' : note.type === 'warning' ? 'text-amber-400' : 'text-indigo-400'}`}
                                              >
                                                  {note.actionLabel} <ChevronRight className="w-3 h-3" />
                                              </button>
                                          </div>
                                      )}
                                  </div>
                              ))}
                          </div>
                      )}
                  </div>
              </div>
          )}

          <button 
            onClick={() => {
                setShowBotPanel(!showBotPanel);
            }}
            className="relative group cursor-pointer focus:outline-none"
          >
              {(hasCritical || hasWarning) && (
                  <>
                    <span className={`absolute inline-flex h-full w-full rounded-full ${hasCritical ? 'bg-rose-500' : 'bg-amber-500'} opacity-20 animate-[ping_1.5s_ease-in-out_infinite]`}></span>
                    <span className={`absolute inline-flex h-full w-full rounded-full ${hasCritical ? 'bg-rose-500' : 'bg-amber-500'} opacity-10 animate-[ping_2s_ease-in-out_infinite] delay-75`}></span>
                  </>
              )}

              <div className={`
                relative w-14 h-14 rounded-2xl flex items-center justify-center transition-all duration-300 shadow-[0_10px_30px_-10px_rgba(0,0,0,0.5)] border
                ${!isPro 
                    ? hasWarning 
                        ? 'bg-gradient-to-br from-amber-900 to-slate-900 border-amber-500/50 shadow-amber-500/30 hover:scale-105 animate-[shake_0.5s_ease-in-out_infinite]'
                        : 'bg-slate-800 border-white/10 shadow-black/50 hover:scale-105'
                    : hasCritical 
                        ? 'bg-gradient-to-br from-rose-900 to-slate-900 border-rose-500/50 shadow-rose-500/30 hover:scale-105 animate-[shake_0.5s_ease-in-out_infinite]' 
                        : hasSuccess
                            ? 'bg-gradient-to-br from-emerald-900 to-slate-900 border-emerald-500/50 shadow-emerald-500/30 hover:scale-110 animate-float'
                            : 'bg-gradient-to-br from-indigo-600 to-violet-900 border-white/20 shadow-indigo-500/40 hover:scale-110 animate-float'
                }
              `}>
                  <div className={`relative z-10 w-8 h-5 rounded-lg backdrop-blur-sm border flex items-center justify-center gap-1 overflow-hidden ${!isPro ? 'bg-slate-700/50 border-white/5' : 'bg-black/40 border-white/10'}`}>
                       {!isPro ? (
                            hasWarning ? (
                                <>
                                    <div className="w-1.5 h-1.5 rounded-full bg-amber-500 animate-[pulse_0.2s_infinite]"></div>
                                    <div className="w-1.5 h-1.5 rounded-full bg-amber-500 animate-[pulse_0.2s_infinite]"></div>
                                </>
                            ) : (
                                <Lock className="w-3 h-3 text-slate-400" />
                            )
                       ) : (
                           <>
                            <div className={`w-1.5 h-1.5 rounded-full ${hasCritical ? 'bg-rose-500 animate-[pulse_0.2s_infinite]' : 'bg-cyan-400 animate-[pulse_4s_infinite]'}`}></div>
                            <div className={`w-1.5 h-1.5 rounded-full ${hasCritical ? 'bg-rose-500 animate-[pulse_0.2s_infinite]' : 'bg-cyan-400 animate-[pulse_4s_infinite]'}`}></div>
                           </>
                       )}
                  </div>

                  <div className="absolute -top-3 left-1/2 -translate-x-1/2 flex flex-col items-center">
                      <div className={`w-1.5 h-1.5 rounded-full mb-0.5 ${!isPro ? (hasWarning ? 'bg-amber-500 animate-pulse' : 'bg-slate-600') : hasCritical ? 'bg-rose-500 animate-ping' : 'bg-white/80 animate-pulse'}`}></div>
                      <div className={`w-0.5 h-2 ${!isPro ? 'bg-slate-700' : 'bg-white/30'}`}></div>
                  </div>

                  {notificationCount > 0 && (
                      <div className={`absolute -top-1 -right-1 min-w-[18px] h-[18px] px-1 rounded-full flex items-center justify-center text-[10px] font-bold text-white border border-[#020617] z-20 ${hasCritical ? 'bg-rose-500' : hasWarning ? 'bg-amber-500' : 'bg-indigo-500'}`}>
                          {notificationCount}
                      </div>
                  )}

                  {!isPro && notificationCount === 0 && (
                       <div className="absolute -bottom-1 -right-1 w-5 h-5 rounded-full bg-slate-700 border border-[#020617] flex items-center justify-center text-[10px] font-bold text-slate-400 z-20">
                          <Lock className="w-3 h-3" />
                      </div>
                  )}
              </div>
          </button>
      </div>

    </div>
  );
};

// Internal Component for Critical Alert
const EmergencyUpsellModal: React.FC<{ onClose: () => void, onUpgrade: () => void }> = ({ onClose, onUpgrade }) => {
    return (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/90 backdrop-blur-xl animate-fade-in">
             <div className="relative max-w-lg w-full bg-[#0f172a] rounded-[2rem] border-2 border-rose-500 shadow-[0_0_100px_rgba(244,63,94,0.3)] overflow-hidden animate-slide-up">
                 {/* Emergency Header */}
                 <div className="bg-rose-600 p-6 flex items-center gap-4 relative overflow-hidden">
                      <div className="absolute inset-0 bg-[linear-gradient(45deg,transparent_25%,rgba(255,255,255,0.1)_50%,transparent_75%)] bg-[length:20px_20px] animate-shimmer-fast opacity-30"></div>
                      <div className="p-3 bg-white/20 rounded-xl backdrop-blur-sm animate-pulse shadow-inner">
                          <Ambulance className="w-8 h-8 text-white" />
                      </div>
                      <div>
                          <h2 className="text-2xl font-black text-white uppercase tracking-tighter">Medical Alert</h2>
                          <p className="text-rose-100 text-xs font-bold uppercase tracking-widest">Financial Health Critical</p>
                      </div>
                      <button onClick={onClose} className="absolute top-6 right-6 text-white/70 hover:text-white transition-colors">
                          <X className="w-6 h-6" />
                      </button>
