export default Plans;

import React, { useState, useEffect } from 'react';
import { Account, Budget, Goal, Transaction, UserPlan, ToastMessage, BotMode, Currency, Language } from './types';
import { ACCOUNTS, INITIAL_TRANSACTIONS, INITIAL_BUDGETS, INITIAL_GOALS, NAV_ITEMS } from './constants';
import Dashboard from './components/Dashboard';
import Transactions from './components/Transactions';
import Accounts from './components/Accounts';
import Insights from './components/Insights';
import Goals from './components/Goals';
import Plans from './components/Plans';
import Settings from './components/Settings';
import LandingPage from './components/LandingPage';
import ToastContainer from './components/Toast';
import { Sparkles, LogOut } from 'lucide-react';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');

  // --- PERSISTENCE LAYER ---
  const [accounts, setAccounts] = useState<Account[]>(() => {
      const saved = localStorage.getItem('nova_accounts');
      return saved ? JSON.parse(saved) : ACCOUNTS;
  });
  const [transactions, setTransactions] = useState<Transaction[]>(() => {
      const saved = localStorage.getItem('nova_transactions');
      return saved ? JSON.parse(saved) : INITIAL_TRANSACTIONS;
  });
  const [budgets, setBudgets] = useState<Budget[]>(() => {
      const saved = localStorage.getItem('nova_budgets');
      return saved ? JSON.parse(saved) : INITIAL_BUDGETS;
  });
  const [goals, setGoals] = useState<Goal[]>(() => {
      const saved = localStorage.getItem('nova_goals');
      return saved ? JSON.parse(saved) : INITIAL_GOALS;
  });

  const [userPlan, setUserPlan] = useState<UserPlan>(() => localStorage.getItem('nova_user_plan') as UserPlan || 'free');

  // Free Trial & Usage State
  const [freeTrialUsage, setFreeTrialUsage] = useState(() => parseInt(localStorage.getItem('nova_free_trial') || '0'));
  const [scanUsage, setScanUsage] = useState(() => parseInt(localStorage.getItem('nova_scan_usage') || '0'));
  const [negotiationUsage, setNegotiationUsage] = useState(() => parseInt(localStorage.getItem('nova_negotiation_usage') || '0'));

  const [isLoggedIn, setIsLoggedIn] = useState(() => localStorage.getItem('nova_auth_token') !== null);
  const [toasts, setToasts] = useState<ToastMessage[]>([]);

  // Bot States
  const [botMode, setBotMode] = useState<BotMode>('ruthless');
  const [pendingChatQuery, setPendingChatQuery] = useState<string | null>(null);

  // Profile State
  const [userName, setUserName] = useState(() => localStorage.getItem('nova_user_name') || 'Pilot');
  const [userEmail, setUserEmail] = useState(() => localStorage.getItem('nova_user_email') || 'pilot@nova.io');
  const [userAvatar, setUserAvatar] = useState(() => localStorage.getItem('nova_user_avatar') || '');
  const [userAvatarZoom, setUserAvatarZoom] = useState(1);
  const [userAvatarPos, setUserAvatarPos] = useState({ x: 0, y: 0 });
  const [userBorder, setUserBorder] = useState('default');
  const [userBackground, setUserBackground] = useState(() => localStorage.getItem('nova_user_bg') || '');
  const [currency, setCurrency] = useState<Currency>('USD');
  const [language, setLanguage] = useState<Language>('en');

  // Persistence Effects
  useEffect(() => localStorage.setItem('nova_accounts', JSON.stringify(accounts)), [accounts]);
  useEffect(() => localStorage.setItem('nova_transactions', JSON.stringify(transactions)), [transactions]);
  useEffect(() => localStorage.setItem('nova_budgets', JSON.stringify(budgets)), [budgets]);
  useEffect(() => localStorage.setItem('nova_goals', JSON.stringify(goals)), [goals]);
  useEffect(() => localStorage.setItem('nova_user_plan', userPlan), [userPlan]);
  useEffect(() => localStorage.setItem('nova_free_trial', freeTrialUsage.toString()), [freeTrialUsage]);
  useEffect(() => localStorage.setItem('nova_scan_usage', scanUsage.toString()), [scanUsage]);
  useEffect(() => localStorage.setItem('nova_negotiation_usage', negotiationUsage.toString()), [negotiationUsage]);
  useEffect(() => localStorage.setItem('nova_user_bg', userBackground), [userBackground]);

  const addToast = (message: string, type: 'success' | 'error' | 'info' = 'info') => {
    setToasts(prev => [...prev, { id: Date.now().toString(), message, type }]);
  };

  const removeToast = (id: string) => {
    setToasts(prev => prev.filter(t => t.id !== id));
  };

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('en-US', { style: 'currency', currency: currency }).format(amount);
  };

  const handleLogin = (name: string) => {
    setIsLoggedIn(true);
    setUserName(name);
    localStorage.setItem('nova_user_name', name);
  };

  const handleLogout = () => {
    localStorage.removeItem('nova_auth_token');
    setIsLoggedIn(false);
  };

  const handleUpdateProfile = (name: string, email: string, avatar: string, zoom: number, pos: { x: number; y: number }, border: string) => {
      setUserName(name);
      localStorage.setItem('nova_user_name', name);
      setUserEmail(email);
      localStorage.setItem('nova_user_email', email);
      setUserAvatar(avatar);
      localStorage.setItem('nova_user_avatar', avatar);
      setUserAvatarZoom(zoom);
      setUserAvatarPos(pos);
      setUserBorder(border);
  };

  const handleClearData = () => {
      localStorage.clear();
      setAccounts(ACCOUNTS);
      setTransactions(INITIAL_TRANSACTIONS);
      setBudgets(INITIAL_BUDGETS);
      setGoals(INITIAL_GOALS);
      setUserPlan('free');
      setIsLoggedIn(false);
      window.location.reload();
  };

  const handleImportData = (file: File) => {
      const reader = new FileReader();
      reader.onload = (e) => {
          try {
              const data = JSON.parse(e.target?.result as string);
              if (data.accounts) setAccounts(data.accounts);
              if (data.transactions) setTransactions(data.transactions);
              if (data.budgets) setBudgets(data.budgets);
              if (data.goals) setGoals(data.goals);
              addToast('Data imported successfully', 'success');
          } catch (err) {
              addToast('Failed to import data', 'error');
          }
      };
      reader.readAsText(file);
  };

  const handleExportData = () => {
      const data = { accounts, transactions, budgets, goals, userPlan };
      const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `nova_backup_${new Date().toISOString().split('T')[0]}.json`;
      a.click();
  };

  const handleAskCoach = (msg: string) => {
      setPendingChatQuery(msg);
      setActiveTab('insights');
  };

  if (!isLoggedIn) {
    return <LandingPage onLoginSuccess={handleLogin} />;
  }

  return (
    <div className="flex h-screen bg-[#020617] text-slate-100 font-sans selection:bg-indigo-500/30 overflow-hidden relative">
      {userBackground && (
          <div className="absolute inset-0 z-0">
               <img src={userBackground} alt="bg" className="w-full h-full object-cover opacity-40 blur-sm" />
               <div className="absolute inset-0 bg-[#020617]/70"></div>
          </div>
      )}

      {!userBackground && (
          <div className="fixed inset-0 z-0 pointer-events-none">
             <div className="absolute top-[-10%] left-[-10%] w-[50%] h-[50%] bg-indigo-900/20 rounded-full blur-[120px] animate-pulse-slow"></div>
             <div className="absolute bottom-[-10%] right-[-10%] w-[50%] h-[50%] bg-purple-900/20 rounded-full blur-[120px] animate-pulse-slow" style={{ animationDelay: '1s' }}></div>
          </div>
      )}

      {/* Sidebar */}
      <aside className="hidden md:flex flex-col w-64 p-4 z-20 bg-slate-950/40 backdrop-blur-md border-r border-white/5 relative">
        <div className="flex items-center gap-3 px-4 py-3 mb-8">
            <div className="w-10 h-10 rounded-xl bg-gradient-to-tr from-indigo-600 to-violet-600 flex items-center justify-center shadow-lg shadow-indigo-500/20 ring-1 ring-white/10">
                <Sparkles className="w-6 h-6 text-white" />
            </div>
            <div>
                <h1 className="text-xl font-bold tracking-tight text-white">Nova AI</h1>
                <p className="text-[10px] text-slate-500 font-bold uppercase tracking-wider">{userPlan === 'ultra' ? 'Elite System' : userPlan === 'pro' ? 'Pro System' : 'Core System'}</p>
            </div>
        </div>

        <nav className="flex-1 space-y-1">
            {NAV_ITEMS.map((item) => {
                const isActive = activeTab === item.id;
                return (
                    <button
                        key={item.id}
                        onClick={() => setActiveTab(item.id)}
                        className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold transition-all duration-300 group ${isActive ? 'bg-indigo-600/10 text-indigo-400 shadow-[0_0_20px_rgba(99,102,241,0.15)] ring-1 ring-indigo-500/20' : 'text-slate-400 hover:text-white hover:bg-white/5'}`}
                    >
                        <item.icon className={`w-5 h-5 transition-colors ${isActive ? 'text-indigo-400' : 'text-slate-500 group-hover:text-white'}`} />
                        {item.label}
                    </button>
                );
            })}
        </nav>

        <div className="mt-auto pt-6 border-t border-white/5">
             <div className="px-4 py-4 rounded-2xl bg-slate-900/50 border border-white/5 flex items-center gap-3 mb-4">
                 <div className="w-10 h-10 rounded-full bg-indigo-500 flex items-center justify-center text-white overflow-hidden relative border border-white/10">
                     {userAvatar ? (
                         <img src={userAvatar} className="w-full h-full object-cover" alt="User" style={{ transform: `scale(${userAvatarZoom}) translate(${userAvatarPos.x}px, ${userAvatarPos.y}px)` }} />
                     ) : (
                         <span className="font-bold text-lg">{userName.charAt(0)}</span>
                     )}
                 </div>
                 <div className="overflow-hidden">
                     <h4 className="font-bold text-white text-sm truncate">{userName}</h4>
                     <p className="text-xs text-slate-500 truncate">{userPlan.charAt(0).toUpperCase() + userPlan.slice(1)} Plan</p>
                 </div>
             </div>
             <button onClick={handleLogout} className="w-full flex items-center gap-2 px-4 py-2 text-xs font-bold text-slate-500 hover:text-rose-400 transition-colors">
                 <LogOut className="w-4 h-4" /> Sign Out
             </button>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col min-w-0 z-10 relative overflow-hidden">
        {/* Mobile Header */}
        <header className="md:hidden flex items-center justify-between p-4 bg-slate-950/80 backdrop-blur-md border-b border-white/5 z-20">
             <div className="flex items-center gap-2">
                <div className="w-8 h-8 rounded-lg bg-indigo-600 flex items-center justify-center">
                    <Sparkles className="w-4 h-4 text-white" />
                </div>
                <span className="font-bold text-white">Nova</span>
             </div>
             <button onClick={() => { /* mobile menu logic */ }} className="text-slate-400 hover:text-white">
                 <div className="w-6 h-6 flex flex-col justify-center gap-1.5">
                     <span className="w-full h-0.5 bg-current rounded-full"></span>
                     <span className="w-full h-0.5 bg-current rounded-full"></span>
                     <span className="w-full h-0.5 bg-current rounded-full"></span>
                 </div>
             </button>
        </header>

        {/* Mobile Navigation Bar */}
        <div className="md:hidden fixed bottom-0 left-0 w-full bg-slate-950/90 backdrop-blur-lg border-t border-white/5 p-2 flex justify-around z-50">
            {NAV_ITEMS.slice(0, 5).map(item => (
                <button 
                    key={item.id}
                    onClick={() => setActiveTab(item.id)}
                    className={`flex flex-col items-center gap-1 p-2 rounded-lg ${activeTab === item.id ? 'text-indigo-400' : 'text-slate-500'}`}
                >
                    <item.icon className="w-5 h-5" />
                    <span className="text-[10px] font-medium">{item.label}</span>
                </button>
            ))}
        </div>

        <div className="flex-1 overflow-y-auto p-4 md:p-8 pb-24 md:pb-8 custom-scrollbar">
            {activeTab === 'dashboard' && (
                <Dashboard 
                    accounts={accounts} 
                    transactions={transactions} 
                    onNavigate={setActiveTab} 
                    onAddAccount={() => setActiveTab('accounts')}
                    onAddTransaction={() => setActiveTab('transactions')}
                    onAddGoal={() => setActiveTab('goals')}
                    formatCurrency={formatCurrency}
                    onBatchCategoryUpdate={(merchant, category) => {
                         const updated = transactions.map(t => t.merchant === merchant ? { ...t, category } : t);
                         setTransactions(updated);
                         addToast(`Updated all ${merchant} transactions`, 'success');
                    }}
                    userPlan={userPlan}
                    onAskCoach={handleAskCoach}
                    negotiationUsage={negotiationUsage}
                    onIncrementNegotiation={() => setNegotiationUsage(prev => prev + 1)}
                />
            )}

            {activeTab === 'transactions' && (
                <Transactions 
                    transactions={transactions} 
                    accounts={accounts}
                    onDelete={(id) => setTransactions(prev => prev.filter(t => t.id !== id))}
                    onAdd={(t) => { setTransactions(prev => [t, ...prev]); addToast('Transaction added', 'success'); }}
                    formatCurrency={formatCurrency}
                    onNavigateToAccounts={() => setActiveTab('accounts')}
                    userPlan={userPlan}
                    scanUsage={scanUsage}
                    onIncrementScan={() => setScanUsage(prev => prev + 1)}
                />
            )}

            {activeTab === 'accounts' && (
                <Accounts 
                    accounts={accounts} 
                    budgets={budgets} 
                    transactions={transactions} 
                    userPlan={userPlan}
                    onAdd={(acc) => { setAccounts(prev => [...prev, acc]); addToast('Account connected', 'success'); }}
                    onUpdate={(acc) => { setAccounts(prev => prev.map(a => a.id === acc.id ? acc : a)); addToast('Account updated', 'success'); }}
                    onDelete={(id) => { setAccounts(prev => prev.filter(a => a.id !== id)); addToast('Account removed', 'info'); }}
                    formatCurrency={formatCurrency}
                    userName={userName}
                    userAvatar={userAvatar}
                    userAvatarZoom={userAvatarZoom}
                    userAvatarPos={userAvatarPos}
                    userBorder={userBorder}
                    onNavigate={setActiveTab}
                />
            )}

            {activeTab === 'insights' && (
                <Insights 
                    transactions={transactions} 
                    userPlan={userPlan} 
                    onUpgradeClick={() => setActiveTab('plans')}
                    formatCurrency={formatCurrency}
                    freeTrialUsage={freeTrialUsage}
                    onIncrementTrial={() => setFreeTrialUsage(prev => prev + 1)}
                    onApplyBudgets={(newBudgets) => {
                         const existingCats = new Set(budgets.map(b => b.category));
                         const toAdd = newBudgets.filter(b => !existingCats.has(b.category));
                         setBudgets(prev => [...prev, ...toAdd]);
                         addToast(`Applied ${toAdd.length} new budget limits`, 'success');
                    }}
                    initialPrompt={pendingChatQuery}
                    onPromptHandled={() => setPendingChatQuery(null)}
                    botMode={botMode}
                />
            )}

            {activeTab === 'goals' && (
                <Goals 
                    goals={goals} 
                    budgets={budgets} 
                    transactions={transactions}
                    onAddGoal={(g) => { setGoals(prev => [...prev, g]); addToast('Goal created', 'success'); }}
                    onUpdateGoal={(g) => { setGoals(prev => prev.map(goal => goal.id === g.id ? g : goal)); addToast('Goal updated', 'success'); }}
                    onAddBudget={(b) => { setBudgets(prev => [...prev, b]); addToast('Budget limit set', 'success'); }}
                    onDeleteBudget={(id) => { setBudgets(prev => prev.filter(b => b.id !== id)); addToast('Budget removed', 'info'); }}
                    formatCurrency={formatCurrency} 
                />
            )}

            {activeTab === 'plans' && (
                <Plans 
                    currentPlan={userPlan} 
                    onUpgrade={(plan) => { setUserPlan(plan); addToast(`Welcome to ${plan.charAt(0).toUpperCase() + plan.slice(1)}`, 'success'); }}
                    onDowngrade={() => { setUserPlan('free'); addToast('Plan downgraded to Free', 'info'); }}
                />
            )}

            {activeTab === 'settings' && (
                <Settings 
                    userName={userName}
                    userEmail={userEmail}
                    userAvatar={userAvatar}
                    userAvatarZoom={userAvatarZoom}
                    userAvatarPos={userAvatarPos}
                    userBorder={userBorder}
                    userBackground={userBackground}
                    onUpdateBackground={setUserBackground}
                    userPlan={userPlan}
                    onUpdateProfile={handleUpdateProfile}
                    addToast={addToast}
                    onExportData={handleExportData}
                    onImportData={handleImportData}
                    onClearData={handleClearData}
                    language={language}
                    onUpdateLanguage={setLanguage}
                    currency={currency}
                    onUpdateCurrency={setCurrency}
                    botMode={botMode}
                    onUpdateBotMode={setBotMode}
                />
            )}
        </div>
      </main>

      <ToastContainer toasts={toasts} onRemove={removeToast} />
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { UserPlan } from '../types';
import { Check, Star, Zap, Shield, Sparkles, CreditCard, Lock, X, Loader2, Smartphone, BrainCircuit, Target, BarChart3, PartyPopper, AlertTriangle, Crown, Infinity } from 'lucide-react';
import confetti from 'canvas-confetti';

interface PlansProps {
  currentPlan: UserPlan;
  onUpgrade: (plan: UserPlan) => void;
  onDowngrade: () => void;
}

const Plans: React.FC<PlansProps> = ({ currentPlan, onUpgrade, onDowngrade }) => {
  const [isCheckoutOpen, setIsCheckoutOpen] = useState(false);
  const [selectedPlan, setSelectedPlan] = useState<UserPlan | null>(null);
  const [isDowngradeOpen, setIsDowngradeOpen] = useState(false);
  const [showCelebration, setShowCelebration] = useState(false);

  // Generate static star field for Elite card to avoid re-render jitter
  const eliteStars = useMemo(() => {
    return Array.from({ length: 70 }).map((_, i) => ({
      id: i,
      top: `${Math.random() * 100}%`,
      left: `${Math.random() * 100}%`,
      size: Math.random() < 0.2 ? '3px' : Math.random() < 0.5 ? '2px' : '1px', // Varied sizes
      delay: `${Math.random() * 5}s`,
      duration: `${Math.random() * 3 + 2}s`,
      opacity: Math.random() * 0.5 + 0.3
    }));
  }, []);

  const handleUpgradeClick = (plan: UserPlan) => {
    setSelectedPlan(plan);
    setIsCheckoutOpen(true);
  };

  const handleConfirmUpgrade = () => {
    if (selectedPlan) {
        onUpgrade(selectedPlan);
        setIsCheckoutOpen(false);
        setShowCelebration(true);
        confetti({
            particleCount: 150,
            spread: 70,
            origin: { y: 0.6 },
            colors: selectedPlan === 'ultra' ? ['#6366f1', '#ec4899', '#8b5cf6'] : ['#f59e0b', '#fbbf24', '#ffffff']
        });
    }
  };

  const handleDowngradeClick = () => {
      setIsDowngradeOpen(true);
  };

  const handleConfirmDowngrade = () => {
      onDowngrade();
      setIsDowngradeOpen(false);
  };

  return (
    <div className="animate-slide-up pb-10">
      <div className="text-center max-w-2xl mx-auto mb-12">
        <h2 className="text-4xl font-bold text-white tracking-tight mb-4">Choose your trajectory</h2>
        <p className="text-slate-400 text-lg">
          Unlock the full power of Nova AI to accelerate your financial freedom.
        </p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 max-w-6xl mx-auto">

        {/* Starter Plan */}
        <div className="glass-card p-6 rounded-[2.5rem] relative flex flex-col border border-white/5 hover:border-white/10 transition-all">
          <div className="mb-6">
            <h3 className="text-lg font-bold text-white mb-2">Starter</h3>
            <div className="flex items-baseline gap-1">
              <span className="text-3xl font-bold text-white">$0</span>
              <span className="text-slate-500 font-medium">/mo</span>
            </div>
            <p className="text-slate-400 text-xs mt-3 leading-relaxed">
              Essential tools for tracking expenses and understanding your spending.
            </p>
          </div>

          <div className="space-y-3 mb-8 flex-1">
            <FeatureItem text="Unlimited Transactions" />
            <FeatureItem text="Basic Dashboard" />
            <FeatureItem text="1 AI Scan / Month" />
            <FeatureItem text="1 Negotiation Script" />
            <FeatureItem text="Overspend Auto-messages" />
          </div>

          <button 
            onClick={handleDowngradeClick}
            disabled={currentPlan === 'free'}
            className={`w-full py-3 rounded-xl font-bold border text-xs transition-all ${currentPlan !== 'free' ? 'bg-slate-800 border-white/10 text-slate-300 hover:bg-white/5 cursor-pointer' : 'bg-white/5 border-transparent text-white/50 cursor-default'}`}
          >
            {currentPlan === 'free' ? 'Current Plan' : 'Downgrade to Free'}
          </button>
        </div>

        {/* Pro Plan - Gold/Amber Theme */}
        <div className="glass-card p-6 rounded-[2.5rem] relative flex flex-col border border-amber-500/30 overflow-hidden group hover:scale-[1.02] transition-transform duration-300">
          <div className="absolute inset-0 bg-gradient-to-b from-amber-500/5 to-transparent pointer-events-none"></div>

          <div className="absolute top-5 right-5">
            <span className="bg-amber-500 text-white text-[10px] font-bold px-2 py-0.5 rounded-full shadow-lg shadow-amber-500/40 flex items-center gap-1">
                <Sparkles className="w-3 h-3 fill-white" /> Popular
            </span>
          </div>

          <div className="mb-6 relative z-10 pr-16">
            <h3 className="text-lg font-bold text-white mb-2">Pro</h3>
            <div className="flex items-baseline gap-1">
              <span className="text-3xl font-bold text-white">$15.99</span>
              <span className="text-slate-500 font-medium">/mo</span>
            </div>
            <p className="text-amber-200 text-xs mt-3 leading-relaxed">
              Supercharge your finances with AI coaching and automation.
            </p>
          </div>

          <div className="space-y-3 mb-8 flex-1 relative z-10">
            <FeatureItem text="AI Financial Coach" icon={<Zap className="w-3.5 h-3.5 text-amber-400" />} />
            <FeatureItem text="Smart Auto-Categorization" />
            <FeatureItem text="50 AI Scans / Month" />
            <FeatureItem text="5 Negotiation Scripts / Month" />
            <FeatureItem text="Advanced Risk Analysis" />
          </div>

          <button 
            onClick={() => handleUpgradeClick('pro')}
            disabled={currentPlan === 'pro'}
            className="w-full py-3 rounded-xl font-bold text-xs text-white bg-gradient-to-r from-amber-500 to-orange-500 hover:from-amber-400 hover:to-orange-400 shadow-lg shadow-amber-500/25 active:scale-95 transition-all relative z-10 disabled:opacity-80 disabled:saturation-0"
          >
            {currentPlan === 'pro' ? 'Current Plan' : 'Upgrade to Pro'}
          </button>

          {currentPlan === 'free' && (
              <p className="text-[10px] text-center text-amber-300/60 mt-3 relative z-10 font-medium">
                  Unlock 50 scans & 5 scripts immediately.
