                     {userAvatar ? (
                         <img src={userAvatar} className="w-full h-full object-cover" alt="User" style={{ transform: `scale(${userAvatarZoom}) translate(${userAvatarPos.x}px, ${userAvatarPos.y}px)` }} />
                     ) : (
                         <span className="font-bold text-lg">{userName.charAt(0)}</span>
                     )}
                 </div>
                 <div className="overflow-hidden">
                     <h4 className="font-bold text-white text-sm truncate">{userName}</h4>
                     <p className="text-xs text-slate-500 truncate">{userPlan.charAt(0).toUpperCase() + userPlan.slice(1)} Plan</p>
                 </div>
             </div>
             <button onClick={handleLogout} className="w-full flex items-center gap-2 px-4 py-2 text-xs font-bold text-slate-500 hover:text-rose-400 transition-colors">
                 <LogOut className="w-4 h-4" /> Sign Out
             </button>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col min-w-0 z-10 relative overflow-hidden">
        {/* Mobile Header */}
        <header className="md:hidden flex items-center justify-between p-4 bg-slate-950/80 backdrop-blur-md border-b border-white/5 z-20">
             <div className="flex items-center gap-2">
                <div className={`w-8 h-8 rounded-lg flex items-center justify-center ${branding.bg}`}>
                    {branding.icon}
                </div>
                <span className="font-bold text-white">Nova</span>
             </div>
             <button onClick={() => { /* mobile menu logic */ }} className="text-slate-400 hover:text-white">
                 <div className="w-6 h-6 flex flex-col justify-center gap-1.5">
                     <span className="w-full h-0.5 bg-current rounded-full"></span>
                     <span className="w-full h-0.5 bg-current rounded-full"></span>
                     <span className="w-full h-0.5 bg-current rounded-full"></span>
                 </div>
             </button>
        </header>

        {/* Mobile Navigation Bar */}
        <div className="md:hidden fixed bottom-0 left-0 w-full bg-slate-950/90 backdrop-blur-lg border-t border-white/5 p-2 flex justify-around z-50">
            {NAV_ITEMS.slice(0, 5).map(item => (
                <button 
                    key={item.id}
                    onClick={() => setActiveTab(item.id)}
                    className={`flex flex-col items-center gap-1 p-2 rounded-lg ${activeTab === item.id ? 'text-indigo-400' : 'text-slate-500'}`}
                >
                    <item.icon className="w-5 h-5" />
                    <span className="text-[10px] font-medium">{item.label}</span>
                </button>
            ))}
        </div>

        <div className="flex-1 overflow-y-auto p-4 md:p-8 pb-24 md:pb-8 custom-scrollbar">
