const FeatureItem: React.FC<{ text: string; highlighted?: boolean; icon?: React.ReactNode; className?: string; customIconBg?: string }> = ({ text, highlighted, icon, className, customIconBg }) => (
  <div className="flex items-center gap-3">
    <div className={`w-5 h-5 rounded-full flex items-center justify-center shrink-0 ${customIconBg ? customIconBg : highlighted 
        ? 'bg-gradient-to-br from-indigo-500 to-purple-600 text-white shadow-md ring-1 ring-indigo-400/50' 
        : 'bg-slate-800 text-slate-400'}`}>
      {highlighted && !icon ? <Sparkles className="w-3 h-3" /> : (icon || <Check className="w-3 h-3" />)}
