import React, { useState, useEffect, useMemo } from 'react';
import { Transaction, Budget, UserPlan, TransactionType, Category } from '../types';
import { Zap, AlertTriangle, TrendingUp, Calendar, X, MessageCircle } from 'lucide-react';

interface FloatingAssistantProps {
  transactions: Transaction[];
  budgets: Budget[];
  userPlan: UserPlan;
  onOpenChat: (initialMessage?: string) => void;
  isVisible: boolean;
}

type RobotMood = 'neutral' | 'alert' | 'thinking' | 'happy' | 'prediction';

const FloatingAssistant: React.FC<FloatingAssistantProps> = ({ transactions, budgets, userPlan, onOpenChat, isVisible }) => {
  const [message, setMessage] = useState<string | null>(null);
  const [mood, setMood] = useState<RobotMood>('neutral');
  const [isHovered, setIsHovered] = useState(false);
  const [alertType, setAlertType] = useState<'violation' | 'prediction' | 'irreversible' | null>(null);

  // --- Financial Brain Logic ---
  useEffect(() => {
    if (!isVisible) return;

    const checkFinancialHealth = () => {
      const now = new Date();
      const currentMonth = now.getMonth();

      // 1. CRITICAL: Budget Breaches (Highest Priority)
      const breachedBudget = budgets.find(b => {
        const spent = transactions
          .filter(t => t.category === b.category && t.type === TransactionType.EXPENSE && new Date(t.date).getMonth() === currentMonth)
          .reduce((acc, t) => acc + t.amount, 0);
        return spent > b.limit;
      });

      if (breachedBudget) {
        setMood('alert');
        setAlertType('violation');
        setMessage(`Violation detected: ${breachedBudget.category} budget exceeded by $${(transactions.filter(t => t.category === breachedBudget.category && t.type === TransactionType.EXPENSE).reduce((a,c)=>a+c.amount,0) - breachedBudget.limit).toFixed(0)}.`);
        return;
      }

      // 2. IRREVERSIBLE: Upcoming Subscription Detection (Heuristic)
      // Look for subscriptions paid around this day of the month in previous months
      const todayDay = now.getDate();
      const upcomingSub = transactions.find(t => {
        const tDate = new Date(t.date);
        return t.category === Category.SUBSCRIPTION && Math.abs(tDate.getDate() - todayDay) < 3 && tDate.getMonth() !== currentMonth;
      });

      if (upcomingSub) {
        setMood('thinking');
        setAlertType('irreversible');
        setMessage(`Irreversibility Watch: ${upcomingSub.merchant} renewal expected in ~2 days. Cancel now or accept charge.`);
        return;
      }

      // 3. ELITE PREDICTION: Burn Rate Forecasting
      if (userPlan === 'ultra') {
        const expenses = transactions.filter(t => t.type === TransactionType.EXPENSE && new Date(t.date).getMonth() === currentMonth);
        const totalSpent = expenses.reduce((acc, t) => acc + t.amount, 0);
        const daysPassed = Math.max(1, now.getDate());
        const dailyBurn = totalSpent / daysPassed;
        const daysInMonth = new Date(now.getFullYear(), currentMonth + 1, 0).getDate();
        const projectedSpend = dailyBurn * daysInMonth;

        // Simple income heuristic
        const income = transactions
            .filter(t => t.type === TransactionType.INCOME && new Date(t.date).getMonth() === currentMonth)
            .reduce((acc, t) => acc + t.amount, 0);

        if (income > 0 && projectedSpend > income) {
           const daysUntilBroke = (income - totalSpent) / dailyBurn;
           if (daysUntilBroke > 0 && daysUntilBroke < 10) {
               setMood('prediction');
               setAlertType('prediction');
               setMessage(`⚠️ Prediction Mode: At current pace, plans break in ${daysUntilBroke.toFixed(0)} days. Immediate reallocation required.`);
               return;
           }
        }
      }

      // 4. Default / Passive State
      setMood('neutral');
      setAlertType(null);
      // Occasional friendly tip or silence
      if (Math.random() > 0.7) {
          setMessage(userPlan === 'ultra' ? "System optimal. Monitoring nodes." : "I'm analyzing your spending patterns.");
      } else {
          setMessage(null);
      }
    };

    // Run check immediately and then every 30 seconds
    checkFinancialHealth();
    const interval = setInterval(checkFinancialHealth, 30000);
    return () => clearInterval(interval);

  }, [transactions, budgets, userPlan, isVisible]);

  if (!isVisible) return null;

  const handleClick = () => {
      onOpenChat(message || "Give me a financial status report.");
      setMessage(null); // Clear message on click
  };

  const getEyeColor = () => {
      switch(mood) {
          case 'alert': return 'bg-rose-500 shadow-[0_0_10px_#f43f5e]';
          case 'prediction': return 'bg-amber-400 shadow-[0_0_10px_#fbbf24]';
          case 'thinking': return 'bg-purple-400 shadow-[0_0_10px_#c084fc]';
          case 'happy': return 'bg-emerald-400 shadow-[0_0_10px_#34d399]';
          default: return 'bg-cyan-400 shadow-[0_0_10px_#22d3ee]';
      }
  };

  return (
    <div className="fixed bottom-6 right-6 z-[60] flex flex-col items-end gap-2">

        {/* The Speech Bubble */}
        {message && (
            <div 
                className={`max-w-[200px] mb-2 p-3 rounded-2xl rounded-br-sm backdrop-blur-xl border shadow-xl text-[11px] font-medium animate-slide-up cursor-pointer transform hover:scale-105 transition-all
                ${alertType === 'violation' ? 'bg-rose-950/90 border-rose-500/50 text-white' : 
                  alertType === 'prediction' ? 'bg-amber-950/90 border-amber-500/50 text-amber-100' :
                  alertType === 'irreversible' ? 'bg-indigo-950/90 border-indigo-500/50 text-indigo-100' :
                  'bg-slate-900/90 border-white/10 text-slate-200'}`}
                onClick={handleClick}
            >
                {alertType === 'violation' && <div className="flex items-center gap-1 text-rose-400 font-bold uppercase text-[9px] mb-1"><AlertTriangle className="w-3 h-3" /> Breach Protocol</div>}
                {alertType === 'prediction' && <div className="flex items-center gap-1 text-amber-400 font-bold uppercase text-[9px] mb-1"><TrendingUp className="w-3 h-3" /> Forecast</div>}
                {alertType === 'irreversible' && <div className="flex items-center gap-1 text-indigo-400 font-bold uppercase text-[9px] mb-1"><Calendar className="w-3 h-3" /> Upcoming</div>}

                {message}

                {alertType && (
                    <div className="mt-2 pt-2 border-t border-white/10 flex justify-end">
                        <span className="text-[9px] opacity-70 flex items-center gap-1 hover:opacity-100 transition-opacity">
                            View Actions <MessageCircle className="w-2.5 h-2.5" />
                        </span>
                    </div>
                )}
            </div>
        )}

        {/* The Robot Unit */}
        <button 
            onClick={handleClick}
            onMouseEnter={() => setIsHovered(true)}
            onMouseLeave={() => setIsHovered(false)}
            className={`relative w-16 h-16 group transition-all duration-300 ${mood === 'alert' ? 'animate-shake' : 'animate-float'}`}
        >
            {/* Antenna */}
            <div className="absolute -top-3 left-1/2 -translate-x-1/2 w-1 h-3 bg-slate-500 z-0 transition-all group-hover:-top-4"></div>
            <div className={`absolute -top-4 left-1/2 -translate-x-1/2 w-2 h-2 rounded-full z-10 transition-colors duration-500 ${mood === 'alert' ? 'bg-rose-500 animate-ping' : mood === 'prediction' ? 'bg-amber-400 animate-pulse' : 'bg-cyan-500'}`}></div>

            {/* Head Container */}
            <div className={`w-16 h-16 rounded-2xl bg-slate-900 border-2 relative z-10 overflow-hidden transition-all duration-300 shadow-2xl flex flex-col items-center justify-center
                ${mood === 'alert' ? 'border-rose-500 shadow-rose-900/50' : 
                  mood === 'prediction' ? 'border-amber-500 shadow-amber-900/50' : 
                  'border-indigo-500/50 shadow-indigo-500/30 group-hover:border-indigo-400'}`}
            >
                {/* Screen Scanlines */}
                <div className="absolute inset-0 bg-[linear-gradient(rgba(18,16,16,0)_50%,rgba(0,0,0,0.25)_50%),linear-gradient(90deg,rgba(255,0,0,0.06),rgba(0,255,0,0.02),rgba(0,0,255,0.06))] z-20 bg-[length:100%_2px,3px_100%] pointer-events-none opacity-20"></div>
                <div className="absolute inset-0 bg-gradient-to-tr from-slate-900 via-slate-800 to-indigo-900/50 z-0"></div>

                {/* Face Interface */}
                <div className="relative z-30 flex gap-2 items-center">
                    {/* Left Eye */}
                    <div className={`w-3 h-4 rounded-sm transition-all duration-300 ${getEyeColor()} ${mood === 'neutral' ? 'animate-blink' : 'scale-110'}`}></div>
                    {/* Right Eye */}
                    <div className={`w-3 h-4 rounded-sm transition-all duration-300 ${getEyeColor()} ${mood === 'neutral' ? 'animate-blink' : 'scale-110'}`}></div>
                </div>

                {/* Mouth / Status Bar */}
                <div className="relative z-30 mt-2 w-8 h-1 rounded-full bg-slate-700 overflow-hidden">
                    <div className={`h-full w-full ${mood === 'alert' ? 'bg-rose-500' : mood === 'prediction' ? 'bg-amber-400' : mood === 'thinking' ? 'bg-purple-500 animate-progress' : 'bg-cyan-500'}`}></div>
                </div>
            </div>

            {/* Hover Glow */}
            <div className={`absolute -inset-2 bg-indigo-500/30 rounded-full blur-xl transition-opacity duration-300 -z-10 ${isHovered ? 'opacity-100' : 'opacity-0'}`}></div>
        </button>

        {/* Global Styles for Custom Animations */}
        <style>{`
            @keyframes blink {
                0%, 90%, 100% { transform: scaleY(1); }
                95% { transform: scaleY(0.1); }
            }
            @keyframes shake {
                0%, 100% { transform: translateX(0); }
                25% { transform: translateX(-2px) rotate(-5deg); }
                75% { transform: translateX(2px) rotate(5deg); }
            }
            @keyframes progress {
                0% { width: 0%; transform: translateX(-100%); }
                50% { width: 100%; transform: translateX(0); }
                100% { width: 0%; transform: translateX(100%); }
            }
            .animate-blink { animation: blink 4s infinite; }
            .animate-shake { animation: shake 0.5s infinite; }
            .animate-progress { animation: progress 1.5s infinite linear; }
        `}</style>
    </div>
  );
};

export default FloatingAssistant;

import React, { useState, useEffect } from 'react';
import { Account, Budget, Goal, Transaction, UserPlan, ToastMessage, BotMode, Currency, Language } from './types';
import { ACCOUNTS, INITIAL_TRANSACTIONS, INITIAL_BUDGETS, INITIAL_GOALS, NAV_ITEMS } from './constants';
import Dashboard from './components/Dashboard';
import Transactions from './components/Transactions';
import Accounts from './components/Accounts';
import Insights from './components/Insights';
import Goals from './components/Goals';
import Plans from './components/Plans';
import Settings from './components/Settings';
import LandingPage from './components/LandingPage';
import ToastContainer from './components/Toast';
import FloatingAssistant from './components/FloatingAssistant'; // Imported new component
import { Sparkles, LogOut, MessageCircle, Zap, Crown } from 'lucide-react';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');

  // --- PERSISTENCE LAYER ---
  const [accounts, setAccounts] = useState<Account[]>(() => {
      const saved = localStorage.getItem('nova_accounts');
      return saved ? JSON.parse(saved) : ACCOUNTS;
  });
  const [transactions, setTransactions] = useState<Transaction[]>(() => {
      const saved = localStorage.getItem('nova_transactions');
      return saved ? JSON.parse(saved) : INITIAL_TRANSACTIONS;
  });
  const [budgets, setBudgets] = useState<Budget[]>(() => {
      const saved = localStorage.getItem('nova_budgets');
      return saved ? JSON.parse(saved) : INITIAL_BUDGETS;
  });
  const [goals, setGoals] = useState<Goal[]>(() => {
      const saved = localStorage.getItem('nova_goals');
      return saved ? JSON.parse(saved) : INITIAL_GOALS;
  });

  const [userPlan, setUserPlan] = useState<UserPlan>(() => localStorage.getItem('nova_user_plan') as UserPlan || 'free');

  // Free Trial & Usage State
  const [freeTrialUsage, setFreeTrialUsage] = useState(() => parseInt(localStorage.getItem('nova_free_trial') || '0'));
  const [scanUsage, setScanUsage] = useState(() => parseInt(localStorage.getItem('nova_scan_usage') || '0'));
  const [negotiationUsage, setNegotiationUsage] = useState(() => parseInt(localStorage.getItem('nova_negotiation_usage') || '0'));

  const [isLoggedIn, setIsLoggedIn] = useState(() => localStorage.getItem('nova_auth_token') !== null);
  const [toasts, setToasts] = useState<ToastMessage[]>([]);

  // Bot States
  const [botMode, setBotMode] = useState<BotMode>('ruthless');
  const [pendingChatQuery, setPendingChatQuery] = useState<string | null>(null);

  // Profile State
  const [userName, setUserName] = useState(() => localStorage.getItem('nova_user_name') || 'Pilot');
  const [userEmail, setUserEmail] = useState(() => localStorage.getItem('nova_user_email') || 'pilot@nova.io');
  const [userAvatar, setUserAvatar] = useState(() => localStorage.getItem('nova_user_avatar') || '');
  const [userAvatarZoom, setUserAvatarZoom] = useState(1);
  const [userAvatarPos, setUserAvatarPos] = useState({ x: 0, y: 0 });
  const [userBorder, setUserBorder] = useState('default');
  const [userBackground, setUserBackground] = useState(() => localStorage.getItem('nova_user_bg') || '');
  const [currency, setCurrency] = useState<Currency>('USD');
  const [language, setLanguage] = useState<Language>('en');

  // Persistence Effects
  useEffect(() => localStorage.setItem('nova_accounts', JSON.stringify(accounts)), [accounts]);
  useEffect(() => localStorage.setItem('nova_transactions', JSON.stringify(transactions)), [transactions]);
  useEffect(() => localStorage.setItem('nova_budgets', JSON.stringify(budgets)), [budgets]);
  useEffect(() => localStorage.setItem('nova_goals', JSON.stringify(goals)), [goals]);
  useEffect(() => localStorage.setItem('nova_user_plan', userPlan), [userPlan]);
  useEffect(() => localStorage.setItem('nova_free_trial', freeTrialUsage.toString()), [freeTrialUsage]);
  useEffect(() => localStorage.setItem('nova_scan_usage', scanUsage.toString()), [scanUsage]);
  useEffect(() => localStorage.setItem('nova_negotiation_usage', negotiationUsage.toString()), [negotiationUsage]);
  useEffect(() => localStorage.setItem('nova_user_bg', userBackground), [userBackground]);

  const addToast = (message: string, type: 'success' | 'error' | 'info' = 'info') => {
    setToasts(prev => [...prev, { id: Date.now().toString(), message, type }]);
  };

  const removeToast = (id: string) => {
    setToasts(prev => prev.filter(t => t.id !== id));
  };

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('en-US', { style: 'currency', currency: currency }).format(amount);
  };

  const handleLogin = (name: string) => {
    setIsLoggedIn(true);
    setUserName(name);
    localStorage.setItem('nova_user_name', name);
  };

  const handleLogout = () => {
    localStorage.removeItem('nova_auth_token');
    setIsLoggedIn(false);
  };

  const handleUpdateProfile = (name: string, email: string, avatar: string, zoom: number, pos: { x: number; y: number }, border: string) => {
      setUserName(name);
      localStorage.setItem('nova_user_name', name);
      setUserEmail(email);
      localStorage.setItem('nova_user_email', email);
      setUserAvatar(avatar);
      localStorage.setItem('nova_user_avatar', avatar);
      setUserAvatarZoom(zoom);
      setUserAvatarPos(pos);
      setUserBorder(border);
  };

  const handleClearData = () => {
      localStorage.clear();
      setAccounts(ACCOUNTS);
      setTransactions(INITIAL_TRANSACTIONS);
      setBudgets(INITIAL_BUDGETS);
      setGoals(INITIAL_GOALS);
      setUserPlan('free');
      setIsLoggedIn(false);
      window.location.reload();
  };

  const handleImportData = (file: File) => {
      const reader = new FileReader();
      reader.onload = (e) => {
          try {
              const data = JSON.parse(e.target?.result as string);
              if (data.accounts) setAccounts(data.accounts);
              if (data.transactions) setTransactions(data.transactions);
              if (data.budgets) setBudgets(data.budgets);
              if (data.goals) setGoals(data.goals);
              addToast('Data imported successfully', 'success');
          } catch (err) {
              addToast('Failed to import data', 'error');
          }
      };
      reader.readAsText(file);
  };

  const handleExportData = () => {
      const data = { accounts, transactions, budgets, goals, userPlan };
      const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `nova_backup_${new Date().toISOString().split('T')[0]}.json`;
      a.click();
  };

  const handleAskCoach = (msg: string) => {
      setPendingChatQuery(msg);
      setActiveTab('insights');
  };

  // Helper to determine Plan visual identity
  const getPlanBranding = () => {
      if (userPlan === 'ultra') return {
          icon: <Crown className="w-6 h-6 text-white" />,
          bg: 'bg-gradient-to-tr from-indigo-600 via-purple-600 to-indigo-600',
          label: 'ELITE SYSTEM',
          shadow: 'shadow-indigo-500/40'
      };
      if (userPlan === 'pro') return {
          icon: <Zap className="w-6 h-6 text-white" />,
          bg: 'bg-gradient-to-tr from-amber-500 to-orange-500',
          label: 'PRO SYSTEM',
          shadow: 'shadow-amber-500/40'
      };
      return {
          icon: <Sparkles className="w-6 h-6 text-white" />,
          bg: 'bg-gradient-to-tr from-indigo-600 to-violet-600',
          label: 'CORE SYSTEM',
          shadow: 'shadow-indigo-500/20'
      };
  };

  const branding = getPlanBranding();

  if (!isLoggedIn) {
    return <LandingPage onLoginSuccess={handleLogin} />;
  }

  return (
    <div className="flex h-screen bg-[#020617] text-slate-100 font-sans selection:bg-indigo-500/30 overflow-hidden relative">
      {userBackground && (
          <div className="absolute inset-0 z-0">
               <img src={userBackground} alt="bg" className="w-full h-full object-cover opacity-40 blur-sm" />
               <div className="absolute inset-0 bg-[#020617]/70"></div>
          </div>
      )}

      {!userBackground && (
          <div className="fixed inset-0 z-0 pointer-events-none">
             <div className="absolute top-[-10%] left-[-10%] w-[50%] h-[50%] bg-indigo-900/20 rounded-full blur-[120px] animate-pulse-slow"></div>
             <div className="absolute bottom-[-10%] right-[-10%] w-[50%] h-[50%] bg-purple-900/20 rounded-full blur-[120px] animate-pulse-slow" style={{ animationDelay: '1s' }}></div>
          </div>
      )}

      {/* Floating Assistant (Nova Droid) */}
      <FloatingAssistant 
          transactions={transactions}
          budgets={budgets}
          userPlan={userPlan}
          isVisible={activeTab !== 'insights'} // Hide when already in chat
          onOpenChat={handleAskCoach}
      />

      {/* Sidebar */}
      <aside className="hidden md:flex flex-col w-64 p-4 z-20 bg-slate-950/40 backdrop-blur-md border-r border-white/5 relative">
        <div className="flex items-center gap-3 px-4 py-3 mb-8">
            <div className={`w-10 h-10 rounded-xl flex items-center justify-center shadow-lg ring-1 ring-white/10 ${branding.bg} ${branding.shadow}`}>
                {branding.icon}
            </div>
            <div>
                <h1 className="text-xl font-bold tracking-tight text-white">Nova AI</h1>
                <p className={`text-[10px] font-bold uppercase tracking-wider ${userPlan === 'ultra' ? 'text-purple-400' : userPlan === 'pro' ? 'text-amber-400' : 'text-slate-500'}`}>
                    {branding.label}
                </p>
            </div>
        </div>

        <nav className="flex-1 space-y-1">
            {NAV_ITEMS.map((item) => {
                const isActive = activeTab === item.id;
                return (
                    <button
                        key={item.id}
                        onClick={() => setActiveTab(item.id)}
                        className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold transition-all duration-300 group ${isActive ? 'bg-indigo-600/10 text-indigo-400 shadow-[0_0_20px_rgba(99,102,241,0.15)] ring-1 ring-indigo-500/20' : 'text-slate-400 hover:text-white hover:bg-white/5'}`}
                    >
                        <item.icon className={`w-5 h-5 transition-colors ${isActive ? 'text-indigo-400' : 'text-slate-500 group-hover:text-white'}`} />
                        {item.label}
                    </button>
                );
            })}
        </nav>

        <div className="mt-auto pt-6 border-t border-white/5">
             <div className="px-4 py-4 rounded-2xl bg-slate-900/50 border border-white/5 flex items-center gap-3 mb-4">
                 <div className="w-10 h-10 rounded-full bg-indigo-500 flex items-center justify-center text-white overflow-hidden relative border border-white/10">
                     {userAvatar ? (
                         <img src={userAvatar} className="w-full h-full object-cover" alt="User" style={{ transform: `scale(${userAvatarZoom}) translate(${userAvatarPos.x}px, ${userAvatarPos.y}px)` }} />
                     ) : (
                         <span className="font-bold text-lg">{userName.charAt(0)}</span>
                     )}
                 </div>
                 <div className="overflow-hidden">
                     <h4 className="font-bold text-white text-sm truncate">{userName}</h4>
                     <p className="text-xs text-slate-500 truncate">{userPlan.charAt(0).toUpperCase() + userPlan.slice(1)} Plan</p>
                 </div>
             </div>
             <button onClick={handleLogout} className="w-full flex items-center gap-2 px-4 py-2 text-xs font-bold text-slate-500 hover:text-rose-400 transition-colors">
                 <LogOut className="w-4 h-4" /> Sign Out
             </button>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col min-w-0 z-10 relative overflow-hidden">
        {/* Mobile Header */}
        <header className="md:hidden flex items-center justify-between p-4 bg-slate-950/80 backdrop-blur-md border-b border-white/5 z-20">
             <div className="flex items-center gap-2">
                <div className={`w-8 h-8 rounded-lg flex items-center justify-center ${branding.bg}`}>
                    {branding.icon}
                </div>
                <span className="font-bold text-white">Nova</span>
             </div>
             <button onClick={() => { /* mobile menu logic */ }} className="text-slate-400 hover:text-white">
                 <div className="w-6 h-6 flex flex-col justify-center gap-1.5">
                     <span className="w-full h-0.5 bg-current rounded-full"></span>
                     <span className="w-full h-0.5 bg-current rounded-full"></span>
                     <span className="w-full h-0.5 bg-current rounded-full"></span>
                 </div>
             </button>
        </header>

        {/* Mobile Navigation Bar */}
        <div className="md:hidden fixed bottom-0 left-0 w-full bg-slate-950/90 backdrop-blur-lg border-t border-white/5 p-2 flex justify-around z-50">
            {NAV_ITEMS.slice(0, 5).map(item => (
                <button 
                    key={item.id}
                    onClick={() => setActiveTab(item.id)}
                    className={`flex flex-col items-center gap-1 p-2 rounded-lg ${activeTab === item.id ? 'text-indigo-400' : 'text-slate-500'}`}
                >
                    <item.icon className="w-5 h-5" />
                    <span className="text-[10px] font-medium">{item.label}</span>
                </button>
            ))}
        </div>

        <div className="flex-1 overflow-y-auto p-4 md:p-8 pb-24 md:pb-8 custom-scrollbar">
            {activeTab === 'dashboard' && (
                <Dashboard 
                    accounts={accounts} 
                    transactions={transactions} 
                    onNavigate={setActiveTab} 
                    onAddAccount={() => setActiveTab('accounts')}
                    onAddTransaction={() => setActiveTab('transactions')}
                    onAddGoal={() => setActiveTab('goals')}
                    formatCurrency={formatCurrency}
                    onBatchCategoryUpdate={(merchant, category) => {
                         const updated = transactions.map(t => t.merchant === merchant ? { ...t, category } : t);
                         setTransactions(updated);
                         addToast(`Updated all ${merchant} transactions`, 'success');
                    }}
                    userPlan={userPlan}
                    onAskCoach={handleAskCoach}
                    negotiationUsage={negotiationUsage}
                    onIncrementNegotiation={() => setNegotiationUsage(prev => prev + 1)}
                />
            )}

            {activeTab === 'transactions' && (
                <Transactions 
                    transactions={transactions} 
                    accounts={accounts}
                    onDelete={(id) => setTransactions(prev => prev.filter(t => t.id !== id))}
                    onAdd={(t) => { setTransactions(prev => [t, ...prev]); addToast('Transaction added', 'success'); }}
                    formatCurrency={formatCurrency}
                    onNavigateToAccounts={() => setActiveTab('accounts')}
                    userPlan={userPlan}
                    scanUsage={scanUsage}
                    onIncrementScan={() => setScanUsage(prev => prev + 1)}
                />
            )}

            {activeTab === 'accounts' && (
                <Accounts 
                    accounts={accounts} 
                    budgets={budgets} 
                    transactions={transactions} 
                    userPlan={userPlan}
                    onAdd={(acc) => { setAccounts(prev => [...prev, acc]); addToast('Account connected', 'success'); }}
                    onUpdate={(acc) => { setAccounts(prev => prev.map(a => a.id === acc.id ? acc : a)); addToast('Account updated', 'success'); }}
                    onDelete={(id) => { setAccounts(prev => prev.filter(a => a.id !== id)); addToast('Account removed', 'info'); }}
                    formatCurrency={formatCurrency}
                    userName={userName}
                    userAvatar={userAvatar}
                    userAvatarZoom={userAvatarZoom}
                    userAvatarPos={userAvatarPos}
                    userBorder={userBorder}
                    onNavigate={setActiveTab}
                />
            )}

            {activeTab === 'insights' && (
                <Insights 
                    transactions={transactions} 
                    userPlan={userPlan} 
                    onUpgradeClick={() => setActiveTab('plans')}
                    formatCurrency={formatCurrency}
                    freeTrialUsage={freeTrialUsage}
                    onIncrementTrial={() => setFreeTrialUsage(prev => prev + 1)}
                    onApplyBudgets={(newBudgets) => {
                         const existingCats = new Set(budgets.map(b => b.category));
                         const toAdd = newBudgets.filter(b => !existingCats.has(b.category));
                         setBudgets(prev => [...prev, ...toAdd]);
                         addToast(`Applied ${toAdd.length} new budget limits`, 'success');
                    }}
                    initialPrompt={pendingChatQuery}
                    onPromptHandled={() => setPendingChatQuery(null)}
                    botMode={botMode}
                />
            )}

            {activeTab === 'goals' && (
                <Goals 
                    goals={goals} 
                    budgets={budgets} 
                    transactions={transactions}
                    onAddGoal={(g) => { setGoals(prev => [...prev, g]); addToast('Goal created', 'success'); }}
                    onUpdateGoal={(g) => { setGoals(prev => prev.map(goal => goal.id === g.id ? g : goal)); addToast('Goal updated', 'success'); }}
                    onAddBudget={(b) => { setBudgets(prev => [...prev, b]); addToast('Budget limit set', 'success'); }}
                    onDeleteBudget={(id) => { setBudgets(prev => prev.filter(b => b.id !== id)); addToast('Budget removed', 'info'); }}
                    formatCurrency={formatCurrency} 
                />
            )}

            {activeTab === 'plans' && (
                <Plans 
                    currentPlan={userPlan} 
                    onUpgrade={(plan) => { setUserPlan(plan); addToast(`Welcome to ${plan.charAt(0).toUpperCase() + plan.slice(1)}`, 'success'); }}
                    onDowngrade={() => { setUserPlan('free'); addToast('Plan downgraded to Free', 'info'); }}
                />
            )}

            {activeTab === 'settings' && (
                <Settings 
                    userName={userName}
                    userEmail={userEmail}
                    userAvatar={userAvatar}
                    userAvatarZoom={userAvatarZoom}
                    userAvatarPos={userAvatarPos}
                    userBorder={userBorder}
                    userBackground={userBackground}
                    onUpdateBackground={setUserBackground}
                    userPlan={userPlan}
                    onUpdateProfile={handleUpdateProfile}
                    addToast={addToast}
                    onExportData={handleExportData}
                    onImportData={handleImportData}
                    onClearData={handleClearData}
                    language={language}
                    onUpdateLanguage={setLanguage}
                    currency={currency}
                    onUpdateCurrency={setCurrency}
                    botMode={botMode}
                    onUpdateBotMode={setBotMode}
                    onDowngrade={() => { setUserPlan('free'); addToast('Plan downgraded to Free', 'info'); }}
                />
            )}
        </div>
      </main>

      <ToastContainer toasts={toasts} onRemove={removeToast} />
    </div>
  );
};

