import React, { useState, useEffect, useMemo } from 'react';
import { Transaction, Budget, UserPlan, TransactionType, Category } from '../types';
import { Zap, AlertTriangle, TrendingUp, Calendar, X, MessageCircle, AlertOctagon, CheckSquare, ArrowRight, ShieldAlert } from 'lucide-react';

interface FloatingAssistantProps {
  transactions: Transaction[];
  budgets: Budget[];
  userPlan: UserPlan;
  onOpenChat: (initialMessage?: string) => void;
  isVisible: boolean;
}

interface FinancialAlert {
  id: string;
  type: 'violation' | 'irreversible' | 'prediction' | 'choice';
  riskScore: number; // 0-100
  title: string;
  message: string;
  amount: number;
  actions: string[]; // Max 3 bullet points
  contextPayload: string; // Structured data for the LLM
}

const FloatingAssistant: React.FC<FloatingAssistantProps> = ({ transactions, budgets, userPlan, onOpenChat, isVisible }) => {
  const [activeAlert, setActiveAlert] = useState<FinancialAlert | null>(null);
  const [panelMode, setPanelMode] = useState<'none' | 'inline' | 'diagnostic'>('none');
  const [isHovered, setIsHovered] = useState(false);

  // --- Deterministic Risk Engine ---
  useEffect(() => {
    // Silent if not visible context, but we keep engine running to check for interrupts
    const evaluateRisk = () => {
      const now = new Date();
      const currentMonth = now.getMonth();
      const currentYear = now.getFullYear();

      let highestRiskAlert: FinancialAlert | null = null;

      // 1. CHECK: Budget Violations (High Priority)
      // Logic: Normalize overspend % into risk score.
      budgets.forEach(b => {
        const spent = transactions
          .filter(t => t.category === b.category && t.type === TransactionType.EXPENSE && new Date(t.date).getMonth() === currentMonth)
          .reduce((acc, t) => acc + t.amount, 0);

        if (spent > b.limit) {
          const overspend = spent - b.limit;
          const ratio = overspend / b.limit;
          // Risk Formula: Base 50 + (Ratio * 50). Cap at 95.
          // Example: 10% over = 55 (Diagnostic). 50% over = 75 (Critical).
          const risk = Math.min(95, 50 + (ratio * 50));

          if (!highestRiskAlert || risk > highestRiskAlert.riskScore) {
            highestRiskAlert = {
              id: `budget_${b.category}`,
              type: 'violation',
              riskScore: risk,
              title: 'Budget Breach',
              message: `${b.category} limit exceeded by $${overspend.toFixed(0)}.`,
              amount: overspend,
              actions: [
                `Stop spending in ${b.category} immediately`,
                `Move funds from Savings to cover $${overspend.toFixed(0)}`,
                `Review recent ${b.category} transactions`
              ],
              contextPayload: `SYSTEM_INTERRUPT: BUDGET_VIOLATION. Category: ${b.category}. Limit: ${b.limit}. Spent: ${spent}. Over: ${overspend}. Risk_Score: ${risk}. Immediate remediation required.`
            };
          }
        }
      });

      // 2. CHECK: Irreversible Events (Subscriptions/Bills)
      // Logic: Heuristic check for recurring payments due in < 48 hours.
      if (!highestRiskAlert || highestRiskAlert.riskScore < 100) {
          const todayDay = now.getDate();
          const upcomingSub = transactions.find(t => {
            const tDate = new Date(t.date);
            const isSub = t.category === Category.SUBSCRIPTION || t.category === Category.UTILITIES;
            const isUpcoming = Math.abs(tDate.getDate() - todayDay) < 2 && tDate.getMonth() !== currentMonth;
            return isSub && isUpcoming;
          });

          if (upcomingSub) {
              // Risk Formula: Base 30 + (Amount / 10). Cap at 80.
              // Example: $10 sub = 31 (Inline). $200 bill = 50 (Diagnostic).
              const risk = Math.min(80, 30 + (upcomingSub.amount / 10));

              if (!highestRiskAlert || risk > highestRiskAlert.riskScore) {
                  highestRiskAlert = {
                      id: `sub_${upcomingSub.id}`,
                      type: 'irreversible',
                      riskScore: risk,
                      title: 'Auto-Renewal Imminent',
                      message: `${upcomingSub.merchant} charges $${upcomingSub.amount} in ~24h.`,
                      amount: upcomingSub.amount,
                      actions: [
                          `Cancel ${upcomingSub.merchant} via app/site`,
                          `Confirm account balance > $${upcomingSub.amount}`,
                          `Mark as authorized in Dashboard`
                      ],
                      contextPayload: `SYSTEM_INTERRUPT: IRREVERSIBLE_EVENT. Type: Subscription Renewal. Merchant: ${upcomingSub.merchant}. Amount: ${upcomingSub.amount}. Time_Impact: <24h. Risk_Score: ${risk}. Decision needed: Cancel or Authorize.`
                  };
              }
          }
      }

      // 3. CHECK: Elite Prediction (Runway Analysis)
      // Only for Elite users.
      if (userPlan === 'ultra' && (!highestRiskAlert || highestRiskAlert.riskScore < 90)) {
          const expenses = transactions.filter(t => t.type === TransactionType.EXPENSE && new Date(t.date).getMonth() === currentMonth);
          const income = transactions.filter(t => t.type === TransactionType.INCOME && new Date(t.date).getMonth() === currentMonth)
                                     .reduce((acc, t) => acc + t.amount, 0);

          if (income > 0) {
              const totalSpent = expenses.reduce((acc, t) => acc + t.amount, 0);
              const daysPassed = Math.max(1, now.getDate());
              const dailyBurn = totalSpent / daysPassed;
              const projectedSpend = dailyBurn * 30; // approx month

              if (projectedSpend > income) {
                  const remainingBudget = income - totalSpent;
                  const daysRunway = remainingBudget / dailyBurn;

                  // Risk Formula: Reverse exponential based on days left.
                  // < 7 days = 90 (Critical). < 14 days = 50 (Diagnostic).
                  let risk = 0;
                  if (daysRunway < 5) risk = 90;
                  else if (daysRunway < 10) risk = 70;
                  else if (daysRunway < 15) risk = 50;

                  if (risk > 0 && (!highestRiskAlert || risk > highestRiskAlert.riskScore)) {
                      highestRiskAlert = {
                          id: 'pred_runway',
                          type: 'prediction',
                          riskScore: risk,
                          title: 'Cash Flow Critical',
                          message: `At current pace, funds deplete in ${daysRunway.toFixed(0)} days.`,
                          amount: projectedSpend - income,
                          actions: [
                              `Initiate emergency cutbacks`,
                              `Transfer liquid assets`,
                              `Review fixed burn rate`
                          ],
                          contextPayload: `SYSTEM_INTERRUPT: PREDICTIVE_RISK. Metric: Runway. Days_Remaining: ${daysRunway.toFixed(1)}. Projected_Overspend: ${projectedSpend - income}. Risk_Score: ${risk}. Immediate reallocation strategy required.`
                      };
                  }
              }
          }
      }

      setActiveAlert(highestRiskAlert);
    };

    evaluateRisk();
    const interval = setInterval(evaluateRisk, 5000); 
    return () => clearInterval(interval);
  }, [transactions, budgets, userPlan]);

  // --- Interaction Router ---
  const handleInteraction = () => {
      if (!activeAlert) return;

      // 1. Critical Risk (>= 70): Force Redirect
      if (activeAlert.riskScore >= 70) {
          onOpenChat(activeAlert.contextPayload);
          setPanelMode('none');
          return;
      }

      // 2. Medium Risk (40-69): Diagnostic Panel
      if (activeAlert.riskScore >= 40) {
          setPanelMode(prev => prev === 'diagnostic' ? 'none' : 'diagnostic');
          return;
      }

      // 3. Low Risk (< 40): Inline Action Panel
      setPanelMode(prev => prev === 'inline' ? 'none' : 'inline');
  };

  const handleManualRedirect = () => {
      if (activeAlert) {
          onOpenChat(activeAlert.contextPayload);
          setPanelMode('none');
      }
  };

  if (!isVisible && !activeAlert) return null; // Hide completely if no alert and chat open

  // Visuals based on Risk
  const isCritical = activeAlert?.riskScore ? activeAlert.riskScore >= 70 : false;
  const isDiagnostic = activeAlert?.riskScore ? activeAlert.riskScore >= 40 && activeAlert.riskScore < 70 : false;

  const getGlowColor = () => {
      if (!activeAlert) return 'shadow-indigo-500/20 border-indigo-500/30'; // Idle
      if (isCritical) return 'shadow-rose-500/50 border-rose-500 animate-pulse';
      if (isDiagnostic) return 'shadow-amber-500/40 border-amber-500';
      return 'shadow-cyan-500/30 border-cyan-500'; // Low risk
  };

  return (
    <div className={`fixed bottom-6 right-6 z-[60] flex flex-col items-end gap-4 ${!isVisible ? 'pointer-events-none opacity-0' : 'pointer-events-auto opacity-100'} transition-opacity duration-300`}>

        {/* --- ROUTE 1: INLINE PANEL (< 40) --- */}
        {panelMode === 'inline' && activeAlert && (
            <div className="bg-slate-900/95 border border-cyan-500/30 p-4 rounded-2xl shadow-2xl backdrop-blur-xl w-64 animate-slide-up origin-bottom-right mb-2">
                <div className="flex items-start justify-between mb-3 border-b border-white/5 pb-2">
                    <h4 className="text-cyan-400 font-bold text-xs uppercase tracking-wider flex items-center gap-1.5">
                        <Zap className="w-3 h-3" /> {activeAlert.title}
                    </h4>
                    <button onClick={() => setPanelMode('none')} className="text-slate-500 hover:text-white"><X className="w-3 h-3" /></button>
                </div>
                <p className="text-slate-300 text-xs mb-3 font-medium">{activeAlert.message}</p>
                <div className="space-y-2">
                    {activeAlert.actions.map((action, i) => (
                        <div key={i} className="flex gap-2 items-start text-[10px] text-slate-400">
                            <CheckSquare className="w-3 h-3 text-cyan-500 shrink-0 mt-0.5" />
                            <span>{action}</span>
                        </div>
                    ))}
                </div>
            </div>
        )}

        {/* --- ROUTE 2: DIAGNOSTIC PANEL (40-69) --- */}
        {panelMode === 'diagnostic' && activeAlert && (
            <div className="bg-[#0f172a] border border-amber-500/30 p-6 rounded-[1.5rem] shadow-2xl w-80 animate-slide-up origin-bottom-right mb-2 ring-1 ring-amber-500/20">
                <div className="flex items-center gap-3 mb-4">
                    <div className="w-10 h-10 rounded-xl bg-amber-500/10 flex items-center justify-center border border-amber-500/20">
                        <AlertOctagon className="w-6 h-6 text-amber-500" />
                    </div>
                    <div>
                        <h4 className="text-white font-bold text-sm">Diagnostic Alert</h4>
                        <div className="flex items-center gap-2 mt-0.5">
                            <span className="h-1.5 w-16 bg-slate-800 rounded-full overflow-hidden">
                                <div className="h-full bg-amber-500" style={{ width: `${activeAlert.riskScore}%` }}></div>
                            </span>
                            <span className="text-[10px] text-amber-500 font-bold">{activeAlert.riskScore}/100 Risk</span>
                        </div>
                    </div>
                </div>

                <div className="bg-slate-900/50 rounded-xl p-3 mb-4 border border-white/5">
                    <p className="text-slate-200 text-xs font-medium leading-relaxed">{activeAlert.message}</p>
                    <div className="mt-2 text-[10px] text-slate-500 font-mono">IMPACT: ${activeAlert.amount.toFixed(2)}</div>
                </div>

                <div className="space-y-2 mb-5">
                    <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Recommended Actions</p>
                    {activeAlert.actions.slice(0, 2).map((action, i) => (
                        <div key={i} className="flex items-center gap-2 text-xs text-slate-400">
                            <div className="w-1.5 h-1.5 rounded-full bg-amber-500/50"></div>
                            {action}
                        </div>
                    ))}
                </div>

                <div className="grid grid-cols-2 gap-3">
                    <button onClick={() => setPanelMode('none')} className="py-2.5 rounded-lg text-xs font-bold text-slate-400 hover:text-white hover:bg-white/5 transition-colors">Dismiss</button>
                    <button 
                        onClick={handleManualRedirect}
                        className="py-2.5 rounded-lg bg-amber-600 hover:bg-amber-500 text-white text-xs font-bold shadow-lg shadow-amber-500/20 flex items-center justify-center gap-2"
                    >
                        Resolve with Coach <ArrowRight className="w-3 h-3" />
                    </button>
                </div>
            </div>
        )}

        {/* --- SYSTEM TRIGGER (ROBOT) --- */}
        {/* Only visible if there is an active alert or explicit visibility requested, otherwise hidden/silent */}
        {activeAlert && (
            <>
                {/* Speech Bubble for Critical/Diagnostic only */}
                {!panelMode.match(/inline|diagnostic/) && (
                    <div 
                        onClick={handleInteraction}
                        className={`cursor-pointer px-4 py-2 rounded-xl backdrop-blur-xl border text-xs font-bold shadow-xl animate-slide-up hover:scale-105 transition-transform flex items-center gap-2
                        ${isCritical ? 'bg-rose-950/90 border-rose-500 text-white' : 
                          isDiagnostic ? 'bg-amber-950/90 border-amber-500 text-amber-100' : 
                          'bg-cyan-950/90 border-cyan-500 text-cyan-100'}`}
                    >
                        {isCritical ? <ShieldAlert className="w-4 h-4 animate-pulse" /> : <TrendingUp className="w-4 h-4" />}
                        {activeAlert.title}
                        {isCritical && <span className="ml-1 text-[9px] bg-white/20 px-1.5 py-0.5 rounded uppercase">Critical</span>}
                    </div>
                )}

                <button 
                    onClick={handleInteraction}
                    onMouseEnter={() => setIsHovered(true)}
                    onMouseLeave={() => setIsHovered(false)}
                    className={`relative w-16 h-16 group transition-all duration-300 ${isCritical ? 'animate-shake' : 'animate-float'}`}
                >
                    {/* Status Indicator / Antenna */}
                    <div className="absolute -top-3 left-1/2 -translate-x-1/2 w-1 h-3 bg-slate-600 z-0 group-hover:-top-4 transition-all"></div>
                    <div className={`absolute -top-4 left-1/2 -translate-x-1/2 w-2.5 h-2.5 rounded-full z-10 transition-colors duration-300 ${isCritical ? 'bg-rose-500 animate-ping' : isDiagnostic ? 'bg-amber-500 animate-pulse' : 'bg-cyan-500'}`}></div>

                    {/* Main Unit */}
                    <div className={`w-16 h-16 rounded-2xl bg-[#0b1121] border-2 relative z-10 overflow-hidden shadow-2xl flex flex-col items-center justify-center transition-all duration-300 ${getGlowColor()}`}>

                        {/* Scanlines */}
                        <div className="absolute inset-0 bg-[linear-gradient(rgba(18,16,16,0)_50%,rgba(0,0,0,0.25)_50%),linear-gradient(90deg,rgba(255,0,0,0.06),rgba(0,255,0,0.02),rgba(0,0,255,0.06))] z-20 bg-[length:100%_2px,3px_100%] pointer-events-none opacity-20"></div>

                        {/* Eyes */}
                        <div className="relative z-30 flex gap-2 items-center">
                            <div className={`w-3 h-4 rounded-sm transition-all duration-300 ${isCritical ? 'bg-rose-500 shadow-[0_0_10px_#f43f5e] scale-110' : isDiagnostic ? 'bg-amber-500 shadow-[0_0_8px_#f59e0b]' : 'bg-cyan-400 shadow-[0_0_8px_#22d3ee] animate-blink'}`}></div>
                            <div className={`w-3 h-4 rounded-sm transition-all duration-300 ${isCritical ? 'bg-rose-500 shadow-[0_0_10px_#f43f5e] scale-110' : isDiagnostic ? 'bg-amber-500 shadow-[0_0_8px_#f59e0b]' : 'bg-cyan-400 shadow-[0_0_8px_#22d3ee] animate-blink'}`}></div>
                        </div>

                        {/* Mouth / Data Processor */}
                        <div className="relative z-30 mt-2 w-8 h-1 rounded-full bg-slate-800 overflow-hidden">
                            <div className={`h-full w-full ${isCritical ? 'bg-rose-600 animate-shimmer-fast' : isDiagnostic ? 'bg-amber-500' : 'bg-cyan-500'}`}></div>
                        </div>
                    </div>
                </button>
            </>
        )}

        <style>{`
            @keyframes blink { 0%, 90%, 100% { transform: scaleY(1); } 95% { transform: scaleY(0.1); } }
            @keyframes shake { 0%, 100% { transform: translateX(0); } 25% { transform: translateX(-3px) rotate(-5deg); } 75% { transform: translateX(3px) rotate(5deg); } }
            .animate-blink { animation: blink 4s infinite; }
            .animate-shake { animation: shake 0.4s infinite; }
        `}</style>
    </div>
  );
};

