  const [toasts, setToasts] = useState<ToastMessage[]>([]);

  // Bot States
  const [botMode, setBotMode] = useState<BotMode>('ruthless');
  const [pendingChatQuery, setPendingChatQuery] = useState<string | null>(null);

  // Profile State
  const [userName, setUserName] = useState(() => localStorage.getItem('nova_user_name') || 'Pilot');
  const [userEmail, setUserEmail] = useState(() => localStorage.getItem('nova_user_email') || 'pilot@nova.io');
  const [userAvatar, setUserAvatar] = useState(() => localStorage.getItem('nova_user_avatar') || '');
  const [userAvatarZoom, setUserAvatarZoom] = useState(1);
  const [userAvatarPos, setUserAvatarPos] = useState({ x: 0, y: 0 });
  const [userBorder, setUserBorder] = useState('default');
  const [userBackground, setUserBackground] = useState(() => localStorage.getItem('nova_user_bg') || '');
  const [currency, setCurrency] = useState<Currency>('USD');
  const [language, setLanguage] = useState<Language>('en');

  // Persistence Effects (Wrapped in try/catch via safeSetItem)
  useEffect(() => safeSetItem('nova_accounts', JSON.stringify(accounts)), [accounts]);
  useEffect(() => safeSetItem('nova_transactions', JSON.stringify(transactions)), [transactions]);
  useEffect(() => safeSetItem('nova_budgets', JSON.stringify(budgets)), [budgets]);
  useEffect(() => safeSetItem('nova_goals', JSON.stringify(goals)), [goals]);
  useEffect(() => safeSetItem('nova_user_plan', userPlan), [userPlan]);

  // Save Usage with Timestamp
  useEffect(() => {
      const now = new Date();
      const meta = { month: now.getMonth(), year: now.getFullYear() };
      safeSetItem('nova_insight_usage', JSON.stringify({ ...meta, count: insightUsage }));
  }, [insightUsage]);

  useEffect(() => {
      const now = new Date();
      const meta = { month: now.getMonth(), year: now.getFullYear() };
      safeSetItem('nova_scan_usage', JSON.stringify({ ...meta, count: scanUsage }));
  }, [scanUsage]);

  useEffect(() => {
      const now = new Date();
      const meta = { month: now.getMonth(), year: now.getFullYear() };
      safeSetItem('nova_negotiation_usage', JSON.stringify({ ...meta, count: negotiationUsage }));
  }, [negotiationUsage]);

  useEffect(() => safeSetItem('nova_user_bg', userBackground), [userBackground]);

  const addToast = (message: string, type: 'success' | 'error' | 'info' = 'info') => {
    setToasts(prev => [...prev, { id: Date.now().toString(), message, type }]);
  };

  const removeToast = (id: string) => {
    setToasts(prev => prev.filter(t => t.id !== id));
  };

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('en-US', { style: 'currency', currency: currency }).format(amount);
  };

  const handleLogin = (name: string) => {
    setIsLoggedIn(true);
    setUserName(name);
    localStorage.setItem('nova_user_name', name);
  };

  const handleLogout = () => {
    localStorage.removeItem('nova_auth_token');
    setIsLoggedIn(false);
  };

  const handleUpdateProfile = (name: string, email: string, avatar: string, zoom: number, pos: { x: number; y: number }, border: string) => {
      setUserName(name);
      localStorage.setItem('nova_user_name', name);
      setUserEmail(email);
      localStorage.setItem('nova_user_email', email);
      setUserAvatar(avatar);
      // Avatar might be large, use safeSetItem
      safeSetItem('nova_user_avatar', avatar);
      setUserAvatarZoom(zoom);
      setUserAvatarPos(pos);
      setUserBorder(border);
  };

  const handleClearData = () => {
      localStorage.clear();
      setAccounts(ACCOUNTS);
      setTransactions(INITIAL_TRANSACTIONS);
      setBudgets(INITIAL_BUDGETS);
      setGoals(INITIAL_GOALS);
      setUserPlan('free');
      setIsLoggedIn(false);
      window.location.reload();
  };

  const handleImportData = (file: File) => {
      const reader = new FileReader();
      reader.onload = (e) => {
          try {
              const data = JSON.parse(e.target?.result as string);
              if (data.accounts) setAccounts(data.accounts);
              if (data.transactions) setTransactions(data.transactions);
              if (data.budgets) setBudgets(data.budgets);
              if (data.goals) setGoals(data.goals);
              addToast('Data imported successfully', 'success');
          } catch (err) {
              addToast('Failed to import data', 'error');
          }
      };
      reader.readAsText(file);
  };

  const handleExportData = () => {
      const data = { accounts, transactions, budgets, goals, userPlan };
      const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `nova_backup_${new Date().toISOString().split('T')[0]}.json`;
      a.click();
  };

  const handleAskCoach = (msg: string) => {
      setPendingChatQuery(msg);
      setActiveTab('insights');
  };

  // Helper to determine Plan visual identity
  const getPlanBranding = () => {
      if (userPlan === 'ultra') return {
          icon: <Crown className="w-6 h-6 text-white" />,
          bg: 'bg-gradient-to-tr from-indigo-600 via-purple-600 to-indigo-600',
          label: 'ELITE SYSTEM',
          shadow: 'shadow-indigo-500/40'
      };
      if (userPlan === 'pro') return {
          icon: <Zap className="w-6 h-6 text-white" />,
          bg: 'bg-gradient-to-tr from-amber-500 to-orange-500',
          label: 'PRO SYSTEM',
          shadow: 'shadow-amber-500/40'
      };
      return {
          icon: <Sparkles className="w-6 h-6 text-white" />,
          bg: 'bg-gradient-to-tr from-indigo-600 to-violet-600',
          label: 'CORE SYSTEM',
          shadow: 'shadow-indigo-500/20'
      };
  };

  const branding = getPlanBranding();

  if (!isLoggedIn) {
    return <LandingPage onLoginSuccess={handleLogin} />;
  }

  return (
    <div className="flex h-screen bg-[#020617] text-slate-100 font-sans selection:bg-indigo-500/30 overflow-hidden relative">
      {userBackground && (
          <div className="absolute inset-0 z-0">
               <img src={userBackground} alt="bg" className="w-full h-full object-cover opacity-40 blur-sm" />
               <div className="absolute inset-0 bg-[#020617]/70"></div>
          </div>
      )}

      {!userBackground && (
          <div className="fixed inset-0 z-0 pointer-events-none">
             <div className="absolute top-[-10%] left-[-10%] w-[50%] h-[50%] bg-indigo-900/20 rounded-full blur-[120px] animate-pulse-slow"></div>
             <div className="absolute bottom-[-10%] right-[-10%] w-[50%] h-[50%] bg-purple-900/20 rounded-full blur-[120px] animate-pulse-slow" style={{ animationDelay: '1s' }}></div>
          </div>
      )}

      {/* Floating Assistant (Nova Droid) */}
      <FloatingAssistant 
          transactions={transactions}
          budgets={budgets}
          userPlan={userPlan}
          isVisible={activeTab !== 'insights'} // Hide when already in chat
          onOpenChat={handleAskCoach}
      />

      {/* Sidebar */}
      <aside className="hidden md:flex flex-col w-64 p-4 z-20 bg-slate-950/40 backdrop-blur-md border-r border-white/5 relative">
        <div className="flex items-center gap-3 px-4 py-3 mb-8">
            <div className={`w-10 h-10 rounded-xl flex items-center justify-center shadow-lg ring-1 ring-white/10 ${branding.bg} ${branding.shadow}`}>
                {branding.icon}
            </div>
            <div>
                <h1 className="text-xl font-bold tracking-tight text-white">Nova AI</h1>
                <p className={`text-[10px] font-bold uppercase tracking-wider ${userPlan === 'ultra' ? 'text-purple-400' : userPlan === 'pro' ? 'text-amber-400' : 'text-slate-500'}`}>
                    {branding.label}
                </p>
            </div>
        </div>

        <nav className="flex-1 space-y-1">
            {NAV_ITEMS.map((item) => {
                const isActive = activeTab === item.id;
                return (
                    <button
                        key={item.id}
                        onClick={() => setActiveTab(item.id)}
                        className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold transition-all duration-300 group ${isActive ? 'bg-indigo-600/10 text-indigo-400 shadow-[0_0_20px_rgba(99,102,241,0.15)] ring-1 ring-indigo-500/20' : 'text-slate-400 hover:text-white hover:bg-white/5'}`}
                    >
                        <item.icon className={`w-5 h-5 transition-colors ${isActive ? 'text-indigo-400' : 'text-slate-500 group-hover:text-white'}`} />
                        {item.label}
                    </button>
                );
            })}
        </nav>

        <div className="mt-auto pt-6 border-t border-white/5">
             <button onClick={() => setActiveTab('settings')} className="w-full text-left px-4 py-4 rounded-2xl bg-slate-900/50 border border-white/5 flex items-center gap-3 mb-4 hover:bg-slate-800 transition-colors group">
                 <div className="w-10 h-10 rounded-full bg-indigo-500 flex items-center justify-center text-white overflow-hidden relative border border-white/10">
                     {userAvatar ? (
                         <img src={userAvatar} className="w-full h-full object-cover" alt="User" style={{ transform: `scale(${userAvatarZoom}) translate(${userAvatarPos.x}px, ${userAvatarPos.y}px)` }} />
                     ) : (
                         <span className="font-bold text-lg">{userName.charAt(0)}</span>
                     )}
                 </div>
                 <div className="overflow-hidden">
                     <h4 className="font-bold text-white text-sm truncate group-hover:text-indigo-400 transition-colors">{userName}</h4>
                     <p className="text-xs text-slate-500 truncate">{userPlan.charAt(0).toUpperCase() + userPlan.slice(1)} Plan</p>
                 </div>
             </button>
             <button onClick={handleLogout} className="w-full flex items-center gap-2 px-4 py-2 text-xs font-bold text-slate-500 hover:text-rose-400 transition-colors">
                 <LogOut className="w-4 h-4" /> Sign Out
             </button>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col min-w-0 z-10 relative overflow-hidden">
        {/* Mobile Header */}
        <header className="md:hidden flex items-center justify-between p-4 bg-slate-950/80 backdrop-blur-md border-b border-white/5 z-20">
             <div className="flex items-center gap-2">
                <div className={`w-8 h-8 rounded-lg flex items-center justify-center ${branding.bg}`}>
                    {branding.icon}
                </div>
                <span className="font-bold text-white">Nova</span>
             </div>
             <button onClick={() => { /* mobile menu logic */ }} className="text-slate-400 hover:text-white">
                 <div className="w-6 h-6 flex flex-col justify-center gap-1.5">
                     <span className="w-full h-0.5 bg-current rounded-full"></span>
                     <span className="w-full h-0.5 bg-current rounded-full"></span>
                     <span className="w-full h-0.5 bg-current rounded-full"></span>
                 </div>
             </button>
        </header>

        {/* Mobile Navigation Bar */}
        <div className="md:hidden fixed bottom-0 left-0 w-full bg-slate-950/90 backdrop-blur-lg border-t border-white/5 p-2 flex justify-around z-50">
            {NAV_ITEMS.slice(0, 5).map(item => (
                <button 
                    key={item.id}
                    onClick={() => setActiveTab(item.id)}
                    className={`flex flex-col items-center gap-1 p-2 rounded-lg ${activeTab === item.id ? 'text-indigo-400' : 'text-slate-500'}`}
                >
                    <item.icon className="w-5 h-5" />
                    <span className="text-[10px] font-medium">{item.label}</span>
                </button>
            ))}
        </div>

        <div className="flex-1 overflow-y-auto p-4 md:p-8 pb-24 md:pb-8 custom-scrollbar">
            {activeTab === 'dashboard' && (
                <Dashboard 
                    accounts={accounts} 
                    transactions={transactions} 
                    onNavigate={setActiveTab} 
                    onAddAccount={() => setActiveTab('accounts')}
                    onAddTransaction={() => setActiveTab('transactions')}
                    onAddGoal={() => setActiveTab('goals')}
                    formatCurrency={formatCurrency}
                    onBatchCategoryUpdate={(merchant, category) => {
                         const updated = transactions.map(t => t.merchant === merchant ? { ...t, category } : t);
                         setTransactions(updated);
                         addToast(`Updated all ${merchant} transactions`, 'success');
                    }}
                    userPlan={userPlan}
                    onAskCoach={handleAskCoach}
                    negotiationUsage={negotiationUsage}
                    onIncrementNegotiation={() => setNegotiationUsage(prev => prev + 1)}
                />
            )}

            {activeTab === 'transactions' && (
                <Transactions 
                    transactions={transactions} 
                    accounts={accounts}
                    onDelete={(id) => setTransactions(prev => prev.filter(t => t.id !== id))}
                    onAdd={(t) => { setTransactions(prev => [t, ...prev]); addToast('Transaction added', 'success'); }}
                    formatCurrency={formatCurrency}
                    onNavigateToAccounts={() => setActiveTab('accounts')}
                    userPlan={userPlan}
                    scanUsage={scanUsage}
                    onIncrementScan={() => setScanUsage(prev => prev + 1)}
                />
            )}

            {activeTab === 'accounts' && (
                <Accounts 
                    accounts={accounts} 
                    budgets={budgets} 
                    transactions={transactions} 
                    userPlan={userPlan}
                    onAdd={(acc) => { setAccounts(prev => [...prev, acc]); addToast('Account connected', 'success'); }}
                    onUpdate={(acc) => { setAccounts(prev => prev.map(a => a.id === acc.id ? acc : a)); addToast('Account updated', 'success'); }}
                    onDelete={(id) => { 
                        // Migration Logic: Remove account, keep transactions (set to 'manual')
                        setAccounts(prev => prev.filter(a => a.id !== id));
                        setTransactions(prev => prev.map(t => t.accountId === id ? { ...t, accountId: 'manual' } : t));
                        addToast('Account removed (history preserved)', 'info'); 
                    }}
                    formatCurrency={formatCurrency}
                    userName={userName}
                    userAvatar={userAvatar}
                    userAvatarZoom={userAvatarZoom}
                    userAvatarPos={userAvatarPos}
                    userBorder={userBorder}
                    onNavigate={setActiveTab}
                />
            )}

            {activeTab === 'insights' && (
                <Insights 
                    transactions={transactions} 
                    userPlan={userPlan} 
                    onUpgradeClick={() => setActiveTab('plans')}
                    formatCurrency={formatCurrency}
                    insightUsage={insightUsage}
                    onIncrementUsage={() => setInsightUsage(prev => prev + 1)}
                    onApplyBudgets={(newBudgets) => {
                         const existingCats = new Set(budgets.map(b => b.category));
                         const toAdd = newBudgets.filter(b => !existingCats.has(b.category));
                         setBudgets(prev => [...prev, ...toAdd]);
                         addToast(`Applied ${toAdd.length} new budget limits`, 'success');
                    }}
                    initialPrompt={pendingChatQuery}
                    onPromptHandled={() => setPendingChatQuery(null)}
                    botMode={botMode}
                />
            )}

            {activeTab === 'goals' && (
                <Goals 
                    goals={goals} 
                    budgets={budgets} 
                    transactions={transactions}
                    onAddGoal={(g) => { setGoals(prev => [...prev, g]); addToast('Goal created', 'success'); }}
                    onUpdateGoal={(g) => { setGoals(prev => prev.map(goal => goal.id === g.id ? g : goal)); addToast('Goal updated', 'success'); }}
                    onAddBudget={(b) => { setBudgets(prev => [...prev, b]); addToast('Budget limit set', 'success'); }}
                    onDeleteBudget={(id) => { setBudgets(prev => prev.filter(b => b.id !== id)); addToast('Budget removed', 'info'); }}
                    formatCurrency={formatCurrency} 
                />
            )}

            {activeTab === 'plans' && (
                <Plans 
                    currentPlan={userPlan} 
                    onUpgrade={(plan) => { setUserPlan(plan); addToast(`Welcome to ${plan.charAt(0).toUpperCase() + plan.slice(1)}`, 'success'); }}
                    onDowngrade={() => { setUserPlan('free'); addToast('Plan downgraded to Free', 'info'); }}
                />
            )}

            {activeTab === 'settings' && (
                <Settings 
                    userName={userName}
                    userEmail={userEmail}
                    userAvatar={userAvatar}
                    userAvatarZoom={userAvatarZoom}
                    userAvatarPos={userAvatarPos}
                    userBorder={userBorder}
                    userBackground={userBackground}
                    onUpdateBackground={setUserBackground}
                    userPlan={userPlan}
                    onUpdateProfile={handleUpdateProfile}
                    addToast={addToast}
                    onExportData={handleExportData}
                    onImportData={handleImportData}
                    onClearData={handleClearData}
                    language={language}
                    onUpdateLanguage={setLanguage}
                    currency={currency}
                    onUpdateCurrency={setCurrency}
                    botMode={botMode}
                    onUpdateBotMode={setBotMode}
                    onDowngrade={() => { setUserPlan('free'); addToast('Plan downgraded to Free', 'info'); }}
                />
            )}
        </div>
      </main>

      <ToastContainer toasts={toasts} onRemove={removeToast} />
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { User, Mail, Save, Download, Trash2, Camera, RefreshCw, ZoomIn, FileJson, UserCircle, Upload, Move, Sparkles, Lock, AlertTriangle, XCircle, Image as ImageIcon, Heart, Terminal, Crown, CreditCard, Zap } from 'lucide-react';
import { UserPlan, Language, Currency, ToastMessage, BotMode } from '../types';

interface SettingsProps {
  userName: string;
  userEmail: string;
  userAvatar: string;
  userAvatarZoom: number;
  userAvatarPos: { x: number; y: number };
  userBorder: string; 
  userBackground: string; 
  onUpdateBackground: (bg: string) => void;
  userPlan: UserPlan;
  onUpdateProfile: (name: string, email: string, avatar: string, zoom: number, pos: { x: number; y: number }, border: string) => void;
  addToast: (message: string, type?: ToastMessage['type']) => void;
  onExportData: () => void;
  onImportData: (file: File) => void;
  onClearData: () => void;
  language: Language;
  onUpdateLanguage: (lang: Language) => void;
  currency: Currency;
  onUpdateCurrency: (curr: Currency) => void;
  botMode: BotMode;
  onUpdateBotMode: (mode: BotMode) => void;
  onDowngrade?: () => void;
}

const AVATAR_PRESETS = [
  'bg-gradient-to-br from-indigo-500 to-purple-500',
  'bg-gradient-to-br from-emerald-400 to-cyan-500',
  'bg-gradient-to-br from-rose-500 to-orange-400',
  'bg-gradient-to-br from-amber-400 to-yellow-600',
  'bg-gradient-to-br from-blue-600 to-indigo-700',
  'bg-gradient-to-br from-slate-600 to-slate-800',
];

const BORDER_STYLES = [
  { id: 'default', label: 'Default', class: 'ring-1 ring-white/20' },
  { id: 'gold', label: 'Gold', class: 'ring-2 ring-amber-400 shadow-[0_0_15px_rgba(251,191,36,0.6)]' },
  { id: 'rainbow', label: 'Rainbow', class: 'ring-4 ring-transparent bg-gradient-to-tr from-rose-500 via-yellow-500 to-cyan-500 bg-[length:400%_400%] animate-gradient-xy p-[2px] },
  { id: 'neon', label: 'Neon', class: 'ring-2 ring-cyan-400 shadow-[0_0_15px_rgba(34,211,238,0.6)]' },
  { id: 'plasma', label: 'Plasma', class: 'ring-2 ring-fuchsia-500 shadow-[0_0_15px_rgba(217,70,239,0.6)]' },
];

const Settings: React.FC<SettingsProps> = ({ 
  userName, 
  userEmail, 
  userAvatar, 
  userAvatarZoom, 
  userAvatarPos,
  userBorder,
  userBackground,
  onUpdateBackground,
  userPlan, 
  onUpdateProfile, 
  addToast,
  onExportData, 
  onImportData, 
  onClearData, 
  language, 
  onUpdateLanguage, 
  currency, 
  onUpdateCurrency,
  botMode,
  onUpdateBotMode,
  onDowngrade
}) => {
  const [name, setName] = useState(userName);
  const [email, setEmail] = useState(userEmail);
  const [avatar, setAvatar] = useState(userAvatar);
  const [zoom, setZoom] = useState(userAvatarZoom);
  const [pos, setPos] = useState(userAvatarPos);
  const [border, setBorder] = useState(userBorder);
  const [isSaving, setIsSaving] = useState(false);
  const [isDragging, setIsDragging] = useState(false);
  const [showResetConfirm, setShowResetConfirm] = useState(false);
  const [showDowngradeConfirm, setShowDowngradeConfirm] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const bgInputRef = useRef<HTMLInputElement>(null);
  const dragRef = useRef<{ startX: number; startY: number; startPosX: number; startPosY: number } | null>(null);
  const isPro = userPlan === 'pro' || userPlan === 'ultra';
  const isElite = userPlan === 'ultra';

  useEffect(() => {
    setName(userName);
    setEmail(userEmail);
    setAvatar(userAvatar);
    setZoom(userAvatarZoom);
    setPos(userAvatarPos);
    setBorder(userBorder);
  }, [userName, userEmail, userAvatar, userAvatarZoom, userAvatarPos, userBorder]);

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    setIsSaving(true);
    setTimeout(() => {
      onUpdateProfile(name, email, avatar, zoom, pos, border);
      setIsSaving(false);
      addToast('Profile Saved: Your identity and avatar are updated.', 'success');
    }, 800);
  };

  // Image Compressor to prevent localStorage crashes
  const compressImage = (file: File): Promise<string> => {
      return new Promise((resolve) => {
          const reader = new FileReader();
          reader.readAsDataURL(file);
          reader.onload = (e) => {
              const img = new Image();
              img.src = e.target?.result as string;
              img.onload = () => {
                  const canvas = document.createElement('canvas');
                  const MAX_WIDTH = 300; // Resize to reasonable avatar size
                  const scale = MAX_WIDTH / img.width;
                  canvas.width = MAX_WIDTH;
                  canvas.height = img.height * scale;

                  const ctx = canvas.getContext('2d');
                  if (ctx) {
                      ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
                      // High compression for storage
                      resolve(canvas.toDataURL('image/jpeg', 0.7)); 
                  } else {
                      // Fallback if canvas context fails
                      resolve(img.src);
                  }
              }
          }
      });
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      try {
          const compressed = await compressImage(file);
          setAvatar(compressed);
          setZoom(1);
          setPos({ x: 0, y: 0 });
      } catch (err) {
          addToast('Failed to process image. Try a smaller file.', 'error');
      }
    }
  };

  const handleBackgroundChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (file) {
          // No compression for background needed yet as it's less frequent, but careful with size
          const reader = new FileReader();
          reader.onloadend = () => {
              const result = reader.result as string;
              onUpdateBackground(result);
              addToast('Dashboard background updated.', 'success');
          };
          reader.readAsDataURL(file);
      }
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    if (!isImageAvatar) return;
    setIsDragging(true);
    dragRef.current = {
      startX: e.clientX,
      startY: e.clientY,
      startPosX: pos.x,
      startPosY: pos.y
    };
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isDragging || !dragRef.current) return;

    // Zoom sensitivity should decrease as zoom increases to prevent hyper-fast movement
    const sensitivity = 0.5 / zoom;
    const dx = (e.clientX - dragRef.current.startX) * sensitivity;
    const dy = (e.clientY - dragRef.current.startY) * sensitivity;

    setPos({
      x: Math.max(-100, Math.min(100, dragRef.current.startPosX + dx)),
      y: Math.max(-100, Math.min(100, dragRef.current.startPosY + dy))
    });
  };

  const handleMouseUp = () => {
    setIsDragging(false);
    dragRef.current = null;
  };

  const handleImportFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      onImportData(file);
    }
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const isImageAvatar = avatar.includes('http') || avatar.startsWith('data:');

  const getBorderClasses = (styleId: string) => {
     const style = BORDER_STYLES.find(s => s.id === styleId);
     return style ? style.class : BORDER_STYLES[0].class;
  };

  return (
