import { categorizeTransaction, parseReceiptImage } from '../services/geminiService';

interface TransactionsProps {
  transactions: Transaction[];
  accounts?: Account[]; 
  onDelete?: (id: string) => void;
  onAdd?: (transaction: Transaction) => void;
  formatCurrency: (amount: number) => string;
  onNavigateToAccounts?: () => void;
  userPlan?: UserPlan;
  scanUsage?: number;
  onIncrementScan?: () => void;
}

const Transactions: React.FC<TransactionsProps> = ({ transactions, accounts = [], onDelete, onAdd, formatCurrency, onNavigateToAccounts, userPlan, scanUsage = 0, onIncrementScan }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [debouncedSearchTerm, setDebouncedSearchTerm] = useState('');
  const [filterType, setFilterType] = useState<TransactionType | 'ALL'>('ALL');
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);

  // Debounce Logic
  useEffect(() => {
    const handler = setTimeout(() => {
      setDebouncedSearchTerm(searchTerm);
    }, 300);

    return () => {
      clearTimeout(handler);
    };
  }, [searchTerm]);

  const filtered = transactions.filter(t => {
    const matchesSearch = t.merchant.toLowerCase().includes(debouncedSearchTerm.toLowerCase()) || 
                          t.category.toLowerCase().includes(debouncedSearchTerm.toLowerCase()) ||
                          (t.notes && t.notes.toLowerCase().includes(debouncedSearchTerm.toLowerCase()));
    const matchesType = filterType === 'ALL' || t.type === filterType;
    return matchesSearch && matchesType;
  });

  const getAccountName = (id: string) => {
    const acc = accounts.find(a => a.id === id);
    if (!acc && id === 'manual') return 'Cash / Manual';
    return acc ? acc.name : 'Unknown Account';
  };

  return (
    <div className="flex flex-col h-full animate-slide-up space-y-6 relative">
      <div className="glass-card p-4 rounded-3xl flex flex-col md:flex-row justify-between items-center gap-4">
          <div className="flex items-center gap-4 w-full md:w-auto px-2">
              <h2 className="text-lg font-bold text-white">Recent Activity</h2>
              <span className="px-3 py-1 rounded-full bg-slate-800/60 border border-white/10 text-xs font-bold text-indigo-300 shadow-inner">{filtered.length}</span>
          </div>

          <div className="flex flex-col md:flex-row gap-3 w-full md:w-auto">
            <div className="relative group flex-1 md:flex-initial">
              <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500 group-focus-within:text-indigo-400 transition-colors" />
              <input
                type="text"
                placeholder="Search merchant or notes..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full bg-slate-950/50 border border-white/10 rounded-2xl pl-10 pr-4 py-3 text-sm text-white focus:outline-none focus:border-indigo-500/50 focus:bg-slate-900/80 transition-all md:w-64 placeholder:text-slate-600 shadow-inner"
              />
            </div>

            <div className="flex gap-3">
                <div className="relative">
                    <select
                    value={filterType}
                    onChange={(e) => setFilterType(e.target.value as any)}
                    className="appearance-none bg-slate-950/50 border border-white/10 rounded-2xl pl-4 pr-10 py-3 text-sm text-white focus:outline-none focus:border-indigo-500/50 hover:bg-slate-900/80 transition-all cursor-pointer shadow-inner font-medium h-full"
                    >
                    <option value="ALL">All Types</option>
                    <option value={TransactionType.INCOME}>Income</option>
                    <option value={TransactionType.EXPENSE}>Expense</option>
                    </select>
                    <Filter className="absolute right-3.5 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-slate-500 pointer-events-none" />
                </div>

                <button 
                    onClick={() => setIsAddModalOpen(true)}
                    className="bg-indigo-600 hover:bg-indigo-500 text-white px-4 py-3 rounded-2xl font-bold text-sm shadow-lg shadow-indigo-500/20 active:scale-95 transition-all flex items-center gap-2"
                >
                    <Plus className="w-4 h-4" /> <span className="hidden md:inline">Add New</span>
                </button>
            </div>
          </div>
      </div>

      <div className="flex-1 overflow-auto custom-scrollbar space-y-3 pb-4">
          <div className="hidden md:grid grid-cols-12 px-6 py-2 text-xs font-bold text-slate-500 uppercase tracking-wider">
              <div className="col-span-2">Date</div>
              <div className="col-span-4">Merchant & Details</div>
              <div className="col-span-3">Category & Account</div>
              <div className="col-span-3 text-right">Amount</div>
          </div>

          {filtered.map(t => (
            <div 
                key={t.id} 
                className="group glass-card rounded-2xl p-4 md:px-6 md:py-4 flex flex-col md:grid md:grid-cols-12 items-center gap-4 transition-all duration-300 hover:scale-[1.005] hover:shadow-[0_10px_20px_rgba(0,0,0,0.2)] hover:bg-slate-800/40 hover:border-indigo-500/20"
            >
                <div className="w-full md:col-span-2 flex items-center gap-3 text-slate-400 order-2 md:order-1 justify-between md:justify-start">
                    <div className="flex items-center gap-2">
                         <div className="p-2 rounded-lg bg-slate-800/50 border border-white/5 group-hover:bg-slate-800 transition-colors">
                            <Calendar className="w-4 h-4 opacity-70" />
                         </div>
                         <span className="text-sm font-medium">{new Date(t.date).toLocaleDateString('en-US', { month: 'short', day: 'numeric' })}</span>
                    </div>
                     <span className={`md:hidden text-base font-bold ${t.type === TransactionType.INCOME ? 'text-emerald-400' : 'text-white'}`}>
                        {t.type === TransactionType.INCOME ? '+' : ''}
                        {formatCurrency(t.amount)}
                     </span>
                </div>

                <div className="w-full md:col-span-4 flex items-center gap-4 order-1 md:order-2">
                     <div className={`p-2.5 rounded-full border border-white/5 shadow-sm shrink-0 transition-colors ${t.type === TransactionType.INCOME ? 'bg-emerald-500/10 group-hover:bg-emerald-500/20' : 'bg-rose-500/10 group-hover:bg-rose-500/20'}`}>
                        {t.type === TransactionType.INCOME ? 
                        <ArrowUpCircle className="w-5 h-5 text-emerald-500" /> : 
                        <ArrowDownCircle className="w-5 h-5 text-rose-500" />
                        }
                    </div>
                    <div className="min-w-0">
                        <span className="block text-base font-bold text-slate-100 group-hover:text-white transition-colors truncate">{t.merchant}</span>
                        {t.notes && (
                            <div className="flex items-center gap-1 mt-0.5">
                                <StickyNote className="w-3 h-3 text-slate-600" />
                                <span className="text-xs text-slate-500 truncate max-w-[200px]">{t.notes}</span>
                            </div>
                        )}
                        <span className="md:hidden text-xs text-slate-500">{t.category} • {getAccountName(t.accountId)}</span>
                    </div>
                </div>

                <div className="hidden md:block col-span-3 order-3">
                   <div className="flex flex-col gap-1.5 items-start">
                        <span className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-semibold border shadow-sm backdrop-blur-md ${
                            t.category === Category.FOOD ? 'bg-orange-500/10 border-orange-500/20 text-orange-400' :
                            t.category === Category.SHOPPING ? 'bg-blue-500/10 border-blue-500/20 text-blue-400' :
                            t.category === Category.TRANSPORT ? 'bg-purple-500/10 border-purple-500/20 text-purple-400' :
                            t.category === Category.INCOME ? 'bg-emerald-500/10 border-emerald-500/20 text-emerald-400' :
                            t.category === Category.SUBSCRIPTION ? 'bg-cyan-500/10 border-cyan-500/20 text-cyan-400' :
                            'bg-slate-800/50 border-slate-700 text-slate-400'
                        }`}>
                            <Tag className="w-3 h-3" />
                            {t.category}
                        </span>
                        {t.accountId !== 'manual' && (
                             <span className="inline-flex items-center gap-1.5 px-2 py-0.5 rounded-md text-[10px] font-bold text-slate-500 border border-white/5 bg-slate-900/50">
                                <Wallet className="w-3 h-3" />
                                {getAccountName(t.accountId)}
                            </span>
                        )}
                   </div>
                </div>

                <div className="hidden md:flex col-span-3 order-4 justify-end items-center gap-4">
                     <span className={`text-base font-bold tracking-tight ${t.type === TransactionType.INCOME ? 'text-emerald-400 drop-shadow-[0_0_8px_rgba(16,185,129,0.3)]' : 'text-white'}`}>
                        {t.type === TransactionType.INCOME ? '+' : ''}
                        {formatCurrency(t.amount)}
                    </span>
                    {onDelete && (
                      <button 
                        onClick={(e) => { e.stopPropagation(); onDelete(t.id); }}
                        className="p-2 text-slate-600 hover:text-rose-500 hover:bg-rose-500/10 rounded-lg transition-all opacity-0 group-hover:opacity-100 translate-x-2 group-hover:translate-x-0"
                        title="Delete"
                      >
                        <Trash2 className="w-4 h-4" />
                      </button>
                    )}
                </div>
            </div>
          ))}

          {filtered.length === 0 && (
              <div className="glass-card rounded-3xl p-16 flex flex-col items-center justify-center text-center">
                  <div className="w-20 h-20 rounded-full bg-slate-800/50 flex items-center justify-center mb-6 shadow-inner ring-1 ring-white/5">
                    <Search className="w-8 h-8 text-slate-600" />
                  </div>
                  <h3 className="text-xl font-bold text-white mb-2">No transactions found</h3>
                  <p className="text-slate-400 max-w-xs">We couldn't find any transactions matching your filters.</p>
              </div>
          )}
      </div>

      {isAddModalOpen && onAdd && (
        <AddTransactionModal 
            onClose={() => setIsAddModalOpen(false)} 
            onAdd={onAdd}
            accounts={accounts}
            onNavigateToAccounts={onNavigateToAccounts}
            userPlan={userPlan}
            formatCurrency={formatCurrency}
            scanUsage={scanUsage}
            onIncrementScan={onIncrementScan}
        />
      )}
    </div>
  );
};

const AddTransactionModal: React.FC<{ 
    onClose: () => void; 
    onAdd: (t: Transaction) => void;
    accounts: Account[];
    onNavigateToAccounts?: () => void;
    userPlan?: UserPlan;
    formatCurrency: (amount: number) => string;
    scanUsage: number;
    onIncrementScan?: () => void;
}> = ({ onClose, onAdd, accounts, onNavigateToAccounts, userPlan, formatCurrency, scanUsage, onIncrementScan }) => {
    const [type, setType] = useState<TransactionType>(TransactionType.EXPENSE);
    const [merchant, setMerchant] = useState('');
    const [amount, setAmount] = useState('');
    const [category, setCategory] = useState<Category | ''>('');
    const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
    const [selectedAccountId, setSelectedAccountId] = useState<string>('');
    const [notes, setNotes] = useState('');
    const [isAutoCategorizing, setIsAutoCategorizing] = useState(false);
    const [isScanning, setIsScanning] = useState(false);
    const [scanError, setScanError] = useState<string | null>(null);
    const fileInputRef = useRef<HTMLInputElement>(null);

    // Limit Logic
    const isUltra = userPlan === 'ultra';
    const isPro = userPlan === 'pro';

    // Starter (Free): 1, Pro: 50, Elite (Ultra): Unlimited
    const scanLimit = isUltra ? Infinity : isPro ? 50 : 1;
    const canScan = scanUsage < scanLimit;
    const scanLimitReached = !canScan;

    // Categories filtered by type
    const expenseCategories = [
        Category.HOUSING, Category.FOOD, Category.TRANSPORT, Category.ENTERTAINMENT, 
        Category.SHOPPING, Category.UTILITIES, Category.HEALTH, Category.SUBSCRIPTION, 
        Category.EDUCATION, Category.TRAVEL, Category.PETS, Category.KIDS, 
        Category.GIFTS, Category.SERVICES, Category.OTHER
    ];
    const incomeCategories = [Category.INCOME, Category.INVESTMENT, Category.OTHER];

    const hasAccounts = accounts.length > 0;
    const canAddExpense = type === TransactionType.INCOME || hasAccounts;

    const handleMerchantBlur = async () => {
        if (!merchant || isAutoCategorizing || (userPlan !== 'pro' && userPlan !== 'ultra') || category) return;

        setIsAutoCategorizing(true);
        try {
            const predictedCategory = await categorizeTransaction(merchant, parseFloat(amount) || 0);
            const isValidCategory = Object.values(Category).includes(predictedCategory as Category);
            if (isValidCategory) setCategory(predictedCategory as Category);
        } catch (error) {
            console.error("Auto-cat failed", error);
        } finally {
            setIsAutoCategorizing(false);
        }
    };

    const handleScanClick = () => {
        if (scanLimitReached) return;
        fileInputRef.current?.click();
    };

    const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;

        setIsScanning(true);
        setScanError(null);

        // Reset file input so user can select same file again if failed
        if (fileInputRef.current) fileInputRef.current.value = '';

        try {
            const reader = new FileReader();
            reader.readAsDataURL(file);
            reader.onload = async () => {
                const base64 = (reader.result as string).split(',')[1];
                const result = await parseReceiptImage(base64);

                if (result) {
                    setMerchant(result.merchant || 'Unknown Merchant');
                    setAmount(result.amount?.toString() || '');
                    if (result.date) setDate(result.date);
                    if (result.category && Object.values(Category).includes(result.category as Category)) {
                        setCategory(result.category as Category);
                    }
                    if (onIncrementScan) onIncrementScan();
                } else {
                    setScanError("Could not extract data. Please fill manually.");
                }
                setIsScanning(false);
            };
            reader.onerror = () => {
                setScanError("Failed to read image file.");
                setIsScanning(false);
            }
        } catch (err) {
            setScanError("AI Connection Failed.");
            setIsScanning(false);
        }
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (!merchant || !amount || !category) return;
        if (type === TransactionType.EXPENSE && !selectedAccountId) return;

        const newTx: Transaction = {
            id: Date.now().toString(),
            date,
            merchant,
            amount: parseFloat(amount),
            category: category as Category,
            type,
            accountId: selectedAccountId || 'manual',
            notes: notes 
        };
        onAdd(newTx);
        onClose();
    };

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/80 backdrop-blur-md animate-fade-in">
            <div className="bg-[#0f172a] border border-white/10 rounded-3xl w-full max-w-lg shadow-2xl overflow-hidden animate-slide-up relative ring-1 ring-white/5 flex flex-col max-h-[90vh]">
                <button onClick={onClose} className="absolute top-4 right-4 p-2 text-slate-400 hover:text-white z-10"><X className="w-6 h-6" /></button>

                <div className="p-8 border-b border-white/5 bg-gradient-to-r from-indigo-900/20 to-transparent flex-shrink-0">
                    <h3 className="text-2xl font-bold text-white flex items-center gap-2"><Plus className="w-6 h-6 text-indigo-400" /> New Transaction</h3>
                    <p className="text-slate-400 text-sm mt-1">Log your income or spending.</p>
                </div>

                <div className="overflow-y-auto p-8 custom-scrollbar">
                    {!canAddExpense ? (
                        <div className="text-center py-8">
                            <div className="w-16 h-16 bg-slate-800 rounded-full flex items-center justify-center mx-auto mb-4">
                                <Wallet className="w-8 h-8 text-slate-500" />
                            </div>
                            <h4 className="text-white font-bold text-lg mb-2">No Accounts Found</h4>
                            <p className="text-slate-400 text-sm mb-6">You need to add a savings or checking account before you can track expenses.</p>
                            <button 
                                onClick={() => { onClose(); if(onNavigateToAccounts) onNavigateToAccounts(); }}
                                className="px-6 py-3 bg-indigo-600 hover:bg-indigo-500 text-white font-bold rounded-xl transition-all"
                            >
                                Add Account
                            </button>
                        </div>
                    ) : (
                        <form onSubmit={handleSubmit} className="space-y-6">

                            {/* AI Receipt Scanner Button */}
                            <div className="relative">
                                <input type="file" accept="image/*" ref={fileInputRef} onChange={handleFileChange} hidden />
                                <button 
                                    type="button" 
                                    onClick={handleScanClick}
                                    disabled={scanLimitReached || isScanning}
                                    className={`w-full py-3 rounded-xl border-2 border-dashed transition-all group relative overflow-hidden ${
                                        isScanning ? 'border-indigo-500 bg-indigo-500/10 cursor-wait' :
                                        scanLimitReached 
                                            ? 'border-slate-700 bg-slate-800/30 text-slate-500 cursor-not-allowed' 
                                            : 'border-slate-600 bg-slate-800/50 hover:border-indigo-500 hover:bg-indigo-500/10 text-slate-300 hover:text-white'
                                    }`}
                                >
                                    {isScanning ? (
                                        <div className="flex items-center justify-center gap-2 text-indigo-400">
                                            <Loader2 className="w-5 h-5 animate-spin" />
                                            <span className="text-sm font-bold animate-pulse">Extracting Data...</span>
                                        </div>
                                    ) : (
                                        <div className="flex items-center justify-center gap-2">
                                            {scanLimitReached ? <AlertCircle className="w-5 h-5" /> : <Camera className="w-5 h-5" />}
                                            <span className="text-sm font-bold">
                                                {scanLimitReached ? "Scan Limit Reached" : "Scan Receipt with AI"}
                                            </span>
                                        </div>
                                    )}
                                    {/* Scan beam animation */}
                                    {isScanning && (
                                        <div className="absolute top-0 left-0 w-full h-full bg-gradient-to-b from-transparent via-indigo-500/20 to-transparent animate-[slideUp_1.5s_infinite]"></div>
                                    )}
                                </button>
                                {scanLimitReached && !isUltra && (
                                    <p className="text-[10px] text-center mt-1 text-slate-500">
                                        Limit reached. Upgrade for more scans.
                                    </p>
                                )}
                                {scanError && (
                                    <div className="mt-2 text-xs text-rose-400 bg-rose-500/10 p-2 rounded-lg border border-rose-500/20 flex items-center gap-2">
                                        <AlertCircle className="w-3 h-3 shrink-0" /> {scanError}
                                    </div>
                                )}
                            </div>

                            {/* Improved Sliding Toggle UI */}
                            <div className="relative flex bg-slate-950 rounded-2xl p-1.5 border border-white/10 cursor-pointer h-14 shadow-inner">
                                <div 
                                    className={`absolute top-1.5 bottom-1.5 rounded-xl shadow-lg transition-all duration-300 ease-spring ${
                                        type === TransactionType.EXPENSE 
                                            ? 'left-1.5 w-[calc(50%-6px)] bg-gradient-to-br from-rose-500 to-red-600 border border-rose-400/30' 
                                            : 'left-[calc(50%+3px)] w-[calc(50%-6px)] bg-gradient-to-br from-emerald-500 to-green-600 border border-emerald-400/30'
                                    }`}
                                >
                                    {/* Inner glow effect for active pill */}
                                    <div className="absolute inset-0 bg-white/10 rounded-xl opacity-50"></div>
                                </div>

                                <button 
                                    type="button" 
                                    onClick={() => { setType(TransactionType.EXPENSE); setCategory(''); }}
                                    className={`relative z-10 flex-1 flex items-center justify-center gap-2 text-sm font-bold transition-colors duration-300 ${type === TransactionType.EXPENSE ? 'text-white' : 'text-slate-500 hover:text-slate-300'}`}
                                >
                                    <ArrowDown className={`w-4 h-4 ${type === TransactionType.EXPENSE ? 'animate-bounce' : ''}`} /> 
                                    Expense
                                </button>
                                <button 
                                    type="button" 
                                    onClick={() => { setType(TransactionType.INCOME); setCategory(''); }}
                                    className={`relative z-10 flex-1 flex items-center justify-center gap-2 text-sm font-bold transition-colors duration-300 ${type === TransactionType.INCOME ? 'text-white' : 'text-slate-500 hover:text-slate-300'}`}
                                >
                                    <ArrowUp className={`w-4 h-4 ${type === TransactionType.INCOME ? 'animate-bounce' : ''}`} /> 
                                    Income
                                </button>
                            </div>

                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <label className="text-xs font-bold text-slate-400 uppercase tracking-wider">Amount</label>
                                    <div className="relative mt-2">
                                        <DollarSign className="absolute left-3.5 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500" />
                                        <input 
                                            required 
                                            type="number" 
                                            step="0.01" 
                                            value={amount} 
                                            onChange={e => setAmount(e.target.value)} 
                                            className="w-full bg-slate-950/50 border border-white/10 rounded-xl p-3.5 pl-9 text-white focus:border-indigo-500 focus:outline-none focus:ring-4 focus:ring-indigo-500/10 transition-all placeholder:text-slate-600 font-mono text-lg" 
                                            placeholder="0.00" 
                                        />
                                    </div>
                                </div>
                                <div>
                                    <label className="text-xs font-bold text-slate-400 uppercase tracking-wider">Date</label>
                                    <input 
                                        required 
                                        type="date" 
                                        value={date} 
                                        onChange={e => setDate(e.target.value)} 
                                        className="w-full bg-slate-950/50 border border-white/10 rounded-xl p-3.5 text-white mt-2 focus:border-indigo-500 focus:outline-none focus:ring-4 focus:ring-indigo-500/10 transition-all [color-scheme:dark]" 
                                    />
                                </div>
                            </div>

                            <div>
                                <label className="text-xs font-bold text-slate-400 uppercase tracking-wider flex justify-between items-center">
                                    Merchant / Source
                                    {isAutoCategorizing && <span className="text-indigo-400 flex items-center gap-1 text-[10px] animate-pulse"><Sparkles className="w-3 h-3" /> AI Autofilling...</span>}
                                </label>
                                <input 
                                    required 
                                    type="text" 
                                    value={merchant} 
                                    onChange={e => setMerchant(e.target.value)}
                                    onBlur={handleMerchantBlur}
                                    className="w-full bg-slate-950/50 border border-white/10 rounded-xl p-3.5 text-white mt-2 focus:border-indigo-500 focus:outline-none focus:ring-4 focus:ring-indigo-500/10 transition-all placeholder:text-slate-600" 
                                    placeholder={type === TransactionType.INCOME ? "e.g. Salary, Freelance" : "e.g. Starbucks, Uber"}
                                />
                            </div>

                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                <div>
                                    <label className="text-xs font-bold text-slate-400 uppercase tracking-wider">Category</label>
                                    <select 
                                        required 
                                        value={category} 
                                        onChange={e => setCategory(e.target.value as Category)} 
                                        className="w-full bg-slate-950/50 border border-white/10 rounded-xl p-3.5 text-white mt-2 focus:border-indigo-500 focus:outline-none focus:ring-4 focus:ring-indigo-500/10 transition-all appearance-none cursor-pointer"
                                    >
                                        <option value="" disabled>Select...</option>
                                        {type === TransactionType.INCOME 
                                            ? incomeCategories.map(c => <option key={c} value={c}>{c}</option>)
                                            : expenseCategories.map(c => <option key={c} value={c}>{c}</option>)
                                        }
                                    </select>
                                </div>

                                <div>
                                    <label className="text-xs font-bold text-slate-400 uppercase tracking-wider">
                                        {type === TransactionType.INCOME ? 'Deposit To' : 'Payment Method'}
                                    </label>
                                    <div className="relative mt-2">
                                        <Wallet className="absolute left-3.5 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500 pointer-events-none" />
                                        <select
                                            required={type === TransactionType.EXPENSE}
                                            value={selectedAccountId}
                                            onChange={(e) => setSelectedAccountId(e.target.value)}
                                            className="w-full bg-slate-950/50 border border-white/10 rounded-xl p-3.5 pl-10 text-white focus:border-indigo-500 focus:outline-none focus:ring-4 focus:ring-indigo-500/10 transition-all appearance-none cursor-pointer"
                                        >
                                            <option value="" disabled>Select Account</option>
                                            {accounts.map(acc => (
                                                <option key={acc.id} value={acc.id}>{acc.name} ({formatCurrency(acc.balance)})</option>
                                            ))}
                                        </select>
                                    </div>
                                </div>
                            </div>

                            <div>
                                <label className="text-xs font-bold text-slate-400 uppercase tracking-wider flex items-center gap-2">
                                    Notes / Context <span className="text-[10px] text-slate-600 font-normal lowercase">(how you lost money)</span>
                                </label>
                                <div className="relative mt-2">
                                    <FileText className="absolute left-3.5 top-3.5 w-4 h-4 text-slate-500" />
                                    <textarea
                                        value={notes}
                                        onChange={(e) => setNotes(e.target.value)}
                                        className="w-full bg-slate-950/50 border border-white/10 rounded-xl p-3.5 pl-10 text-white focus:border-indigo-500 focus:outline-none focus:ring-4 focus:ring-indigo-500/10 transition-all placeholder:text-slate-600 min-h-[100px] resize-none"
                                        placeholder="e.g. Impulse buy, forgot to cancel subscription..."
                                    />
                                </div>
                            </div>

                            <button type="submit" className="w-full py-4 bg-indigo-600 hover:bg-indigo-500 text-white font-bold rounded-xl shadow-lg shadow-indigo-500/20 active:scale-95 transition-all flex items-center justify-center gap-2">
                                <Check className="w-5 h-5" /> Save Transaction
                            </button>
                        </form>
                    )}
                </div>
            </div>
        </div>
    );
};

export default Transactions;

import React, { useState, useEffect, useRef } from 'react';
import { User, Mail, Save, Download, Trash2, Camera, RefreshCw, ZoomIn, FileJson, UserCircle, Upload, Move, Sparkles, Lock, AlertTriangle, XCircle, Image as ImageIcon, Heart, Terminal, Crown, CreditCard, Zap } from 'lucide-react';
import { UserPlan, Language, Currency, ToastMessage, BotMode } from '../types';

interface SettingsProps {
  userName: string;
  userEmail: string;
  userAvatar: string;
  userAvatarZoom: number;
  userAvatarPos: { x: number; y: number };
  userBorder: string; 
  userBackground: string; 
  onUpdateBackground: (bg: string) => void;
  userPlan: UserPlan;
  onUpdateProfile: (name: string, email: string, avatar: string, zoom: number, pos: { x: number; y: number }, border: string) => void;
  addToast: (message: string, type?: ToastMessage['type']) => void;
  onExportData: () => void;
  onImportData: (file: File) => void;
  onClearData: () => void;
  language: Language;
  onUpdateLanguage: (lang: Language) => void;
  currency: Currency;
  onUpdateCurrency: (curr: Currency) => void;
  botMode: BotMode;
  onUpdateBotMode: (mode: BotMode) => void;
  onDowngrade?: () => void;
}

const AVATAR_PRESETS = [
  'bg-gradient-to-br from-indigo-500 to-purple-500',
  'bg-gradient-to-br from-emerald-400 to-cyan-500',
  'bg-gradient-to-br from-rose-500 to-orange-400',
  'bg-gradient-to-br from-amber-400 to-yellow-600',
  'bg-gradient-to-br from-blue-600 to-indigo-700',
  'bg-gradient-to-br from-slate-600 to-slate-800',
];

const BORDER_STYLES = [
  { id: 'default', label: 'Default', class: 'ring-1 ring-white/20' },
  { id: 'gold', label: 'Gold', class: 'ring-2 ring-amber-400 shadow-[0_0_15px_rgba(251,191,36,0.6)]' },
  { id: 'rainbow', label: 'Rainbow', class: 'ring-4 ring-transparent bg-gradient-to-tr from-rose-500 via-yellow-500 to-cyan-500 bg-[length:400%_400%] animate-gradient-xy p-[2px]' },
  { id: 'neon', label: 'Neon', class: 'ring-2 ring-cyan-400 shadow-[0_0_15px_rgba(34,211,238,0.6)]' },
  { id: 'plasma', label: 'Plasma', class: 'ring-2 ring-fuchsia-500 shadow-[0_0_15px_rgba(217,70,239,0.6)]' },
];

const Settings: React.FC<SettingsProps> = ({ 
  userName, 
  userEmail, 
  userAvatar, 
  userAvatarZoom, 
  userAvatarPos,
  userBorder,
  userBackground,
  onUpdateBackground,
  userPlan, 
  onUpdateProfile, 
  addToast,
  onExportData, 
  onImportData, 
  onClearData, 
  language, 
  onUpdateLanguage, 
  currency, 
  onUpdateCurrency,
  botMode,
  onUpdateBotMode,
  onDowngrade
}) => {
  const [name, setName] = useState(userName);
  const [email, setEmail] = useState(userEmail);
  const [avatar, setAvatar] = useState(userAvatar);
  const [zoom, setZoom] = useState(userAvatarZoom);
  const [pos, setPos] = useState(userAvatarPos);
  const [border, setBorder] = useState(userBorder);
  const [isSaving, setIsSaving] = useState(false);
  const [isDragging, setIsDragging] = useState(false);
  const [showResetConfirm, setShowResetConfirm] = useState(false);
  const [showDowngradeConfirm, setShowDowngradeConfirm] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const bgInputRef = useRef<HTMLInputElement>(null);
  const dragRef = useRef<{ startX: number; startY: number; startPosX: number; startPosY: number } | null>(null);
  const isPro = userPlan === 'pro' || userPlan === 'ultra';
  const isElite = userPlan === 'ultra';

  useEffect(() => {
    setName(userName);
    setEmail(userEmail);
    setAvatar(userAvatar);
    setZoom(userAvatarZoom);
    setPos(userAvatarPos);
    setBorder(userBorder);
  }, [userName, userEmail, userAvatar, userAvatarZoom, userAvatarPos, userBorder]);

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    setIsSaving(true);
    setTimeout(() => {
      onUpdateProfile(name, email, avatar, zoom, pos, border);
      setIsSaving(false);
      addToast('Profile Saved: Your identity and avatar are updated.', 'success');
    }, 800);
  };

  // Image Compressor to prevent localStorage crashes
  const compressImage = (file: File): Promise<string> => {
      return new Promise((resolve) => {
          const reader = new FileReader();
          reader.readAsDataURL(file);
          reader.onload = (e) => {
              const img = new Image();
              img.src = e.target?.result as string;
              img.onload = () => {
                  const canvas = document.createElement('canvas');
                  const MAX_WIDTH = 300; // Resize to reasonable avatar size
                  const scale = MAX_WIDTH / img.width;
                  canvas.width = MAX_WIDTH;
                  canvas.height = img.height * scale;

                  const ctx = canvas.getContext('2d');
                  if (ctx) {
                      ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
                      // High compression for storage
                      resolve(canvas.toDataURL('image/jpeg', 0.7)); 
                  } else {
                      // Fallback if canvas context fails
                      resolve(img.src);
                  }
              }
          }
      });
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      try {
          const compressed = await compressImage(file);
          setAvatar(compressed);
          setZoom(1);
          setPos({ x: 0, y: 0 });
      } catch (err) {
          addToast('Failed to process image. Try a smaller file.', 'error');
      }
    }
  };

  const handleBackgroundChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (file) {
          // No compression for background needed yet as it's less frequent, but careful with size
          const reader = new FileReader();
          reader.onloadend = () => {
              const result = reader.result as string;
              onUpdateBackground(result);
              addToast('Dashboard background updated.', 'success');
          };
          reader.readAsDataURL(file);
      }
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    if (!isImageAvatar) return;
    setIsDragging(true);
    dragRef.current = {
      startX: e.clientX,
      startY: e.clientY,
      startPosX: pos.x,
      startPosY: pos.y
    };
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isDragging || !dragRef.current) return;

    // Zoom sensitivity should decrease as zoom increases to prevent hyper-fast movement
    const sensitivity = 0.5 / zoom;
    const dx = (e.clientX - dragRef.current.startX) * sensitivity;
    const dy = (e.clientY - dragRef.current.startY) * sensitivity;

    setPos({
      x: Math.max(-100, Math.min(100, dragRef.current.startPosX + dx)),
      y: Math.max(-100, Math.min(100, dragRef.current.startPosY + dy))
    });
  };

  const handleMouseUp = () => {
    setIsDragging(false);
    dragRef.current = null;
  };

  const handleImportFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      onImportData(file);
    }
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const isImageAvatar = avatar.includes('http') || avatar.startsWith('data:');

  const getBorderClasses = (styleId: string) => {
     const style = BORDER_STYLES.find(s => s.id === styleId);
     return style ? style.class : BORDER_STYLES[0].class;
  };

  return (
    <div className="animate-slide-up pb-10 max-w-5xl mx-auto" onMouseUp={handleMouseUp} onMouseLeave={handleMouseUp}>
      <div className="mb-8">
        <h2 className="text-3xl font-bold text-white tracking-tight">Settings</h2>
        <p className="text-slate-400 mt-2 font-medium">Manage your profile and system preferences.</p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">

        {/* Left Column: Profile Card */}
        <div className="lg:col-span-1 space-y-6">
            <div className="glass-card p-8 rounded-[2rem] text-center border border-white/5 relative overflow-hidden">
                <div className="absolute top-0 left-0 w-full h-32 bg-gradient-to-b from-indigo-500/10 to-transparent pointer-events-none"></div>

                <div className="relative inline-block mb-6 group select-none">
                    <div 
                      onMouseDown={handleMouseDown}
                      onMouseMove={handleMouseMove}
                      className={`w-32 h-32 rounded-full flex items-center justify-center shadow-2xl transition-all duration-300 ${!isImageAvatar ? avatar : ''} overflow-hidden bg-slate-800 ${isImageAvatar ? 'cursor-grab active:cursor-grabbing' : ''} ${getBorderClasses(border)}`}
                    >
                         {isImageAvatar ? (
                             <img 
                                src={avatar} 
                                alt="Profile" 
                                className="w-full h-full object-cover transition-transform duration-100 pointer-events-none" 
                                style={{ 
                                  transform: `scale(${zoom}) translate(${pos.x}px, ${pos.y}px)`,
                                  filter: isDragging ? 'brightness(1.1)' : 'none'
                                }}
                             />
                         ) : (
                             <User className="w-12 h-12 text-white/80" />
                         )}
                         {isImageAvatar && zoom > 1 && (
                            <div className="absolute inset-0 bg-white/5 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity">
                                <Move className="w-6 h-6 text-white drop-shadow-lg" />
                            </div>
                         )}
                    </div>
                </div>

                <h3 className="text-xl font-bold text-white">{name}</h3>
                <p className="text-slate-400 text-sm mb-4">{email}</p>

                <div className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-bold uppercase tracking-wider ${isElite ? 'bg-purple-500/10 text-purple-400 border border-purple-500/20' : isPro ? 'bg-amber-500/10 text-amber-400 border-amber-500/20' : 'bg-slate-700/50 text-slate-300 border border-white/5'}`}>
                    {isElite ? 'Elite' : isPro ? 'Nova Pro' : 'Free Plan'}
                </div>
            </div>

            <div className="glass-card p-6 rounded-[2rem] border border-white/5">
                <h4 className="text-sm font-bold text-white mb-4">Identity Style</h4>
                <div className="grid grid-cols-4 gap-3 mb-6">
                    {AVATAR_PRESETS.map((preset, idx) => (
                        <button
                            key={idx}
                            onClick={() => { setAvatar(preset); setZoom(1); setPos({x:0, y:0}); }}
                            className={`w-12 h-12 rounded-full ${preset} hover:scale-110 transition-transform ring-2 ring-offset-2 ring-offset-slate-900 ${avatar === preset ? 'ring-white' : 'ring-transparent'}`}
                        />
                    ))}
                </div>

                {/* Pro Border Selection */}
                <div className="pt-4 border-t border-white/5">
                    <div className="flex justify-between items-center mb-3">
                        <h4 className="text-sm font-bold text-white flex items-center gap-1.5">
                            Elite Aesthetics 
                            {!isElite && <Lock className="w-3 h-3 text-slate-500" />}
                        </h4>
                        {isElite && <Crown className="w-3 h-3 text-purple-400" />}
                    </div>

                    <div className={`grid grid-cols-5 gap-2 ${!isElite ? 'opacity-50 pointer-events-none grayscale' : ''}`}>
                        {BORDER_STYLES.map((style) => (
                            <button
                                key={style.id}
                                onClick={() => setBorder(style.id)}
                                title={style.label}
                                className={`w-8 h-8 rounded-full bg-slate-800 transition-all ${getBorderClasses(style.id)} ${border === style.id ? 'scale-110' : 'hover:scale-105 opacity-80'}`}
                            >
                            </button>
                        ))}
                    </div>
                    {!isElite && <p className="text-[10px] text-slate-500 mt-2 font-medium">Upgrade to Elite to unlock custom borders.</p>}
                </div>

                <div className="space-y-4 pt-4 border-t border-white/5 mt-4">
                    {isImageAvatar && (
                        <div className="space-y-4">
                            <div className="space-y-2">
                                <div className="flex justify-between items-center text-xs font-bold text-slate-400 uppercase tracking-wider">
                                    <span className="flex items-center gap-1"><ZoomIn className="w-3 h-3" /> Magnitude</span>
                                    <span className="text-white">{(zoom * 100).toFixed(0)}%</span>
                                </div>
                                <input 
                                    type="range" 
                                    min="1" 
                                    max="3" 
                                    step="0.05" 
                                    value={zoom}
                                    onChange={(e) => setZoom(parseFloat(e.target.value))}
                                    className="w-full h-2 bg-slate-800 rounded-lg appearance-none cursor-pointer accent-indigo-500 hover:accent-indigo-400"
                                />
                            </div>
                            <div className="p-3 bg-indigo-500/10 rounded-xl border border-indigo-500/20 text-[10px] text-indigo-200 leading-relaxed font-bold uppercase tracking-tight">
                                <Move className="w-3 h-3 inline mr-1 mb-0.5" /> 
                                Drag photo within frame to adjust alignment.
                            </div>
                        </div>
                    )}

                    <div>
                        <p className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-2">Deploy Identity Plate</p>
                        <div className="relative group">
                            <input 
                                type="file" 
                                accept="image/*"
                                onChange={handleFileChange}
                                className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10"
                            />
                            <button className="w-full py-2.5 bg-slate-800 hover:bg-slate-700 text-slate-300 rounded-xl text-sm font-bold border border-white/5 transition-all flex items-center justify-center gap-2 group-hover:text-white">
                                <Upload className="w-4 h-4" /> Upload Custom Photo
                            </button>
                        </div>
                    </div>
                </div>
            </div>
        </div>

        {/* Right Column: Forms & Settings */}
        <div className="lg:col-span-2 space-y-8">
            <form onSubmit={handleSave} className="glass-card p-8 rounded-[2rem] border border-white/5 relative overflow-hidden">
                 <div className="flex justify-between items-center mb-6">
                    <h3 className="text-xl font-bold text-white flex items-center gap-2">
                        <UserCircle className="w-5 h-5 text-indigo-400" />
                        Identity Matrix
                    </h3>
                    <button 
                        type="submit"
                        disabled={isSaving}
                        className="px-5 py-2 bg-indigo-600 hover:bg-indigo-500 text-white rounded-xl text-sm font-bold shadow-lg shadow-indigo-500/20 active:scale-95 transition-all flex items-center gap-2 disabled:opacity-70"
                    >
                        {isSaving ? <RefreshCw className="w-4 h-4 animate-spin" /> : <Save className="w-4 h-4" />}
                        {isSaving ? 'Processing...' : 'Save Profile & Avatar'}
                    </button>
                 </div>

                 <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div>
                        <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-2 block">Pilot Name</label>
                        <div className="relative">
                            <User className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500" />
                            <input 
                                type="text" 
                                value={name}
                                onChange={(e) => setName(e.target.value)}
                                className="w-full bg-slate-950/50 border border-white/10 rounded-xl py-3 pl-10 pr-4 text-white focus:border-indigo-500 focus:outline-none focus:ring-4 focus:ring-indigo-500/10 transition-all placeholder:text-slate-600 font-medium"
                            />
                        </div>
                    </div>
                    <div>
                        <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-2 block">Pilot Email</label>
                        <div className="relative">
                            <Mail className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500" />
                            <input 
                                type="email" 
                                value={email}
                                onChange={(e) => setEmail(e.target.value)}
                                className="w-full bg-slate-950/50 border border-white/10 rounded-xl py-3 pl-10 pr-4 text-white focus:border-indigo-500 focus:outline-none focus:ring-4 focus:ring-indigo-500/10 transition-all placeholder:text-slate-600 font-medium"
                            />
                        </div>
                    </div>
                 </div>
            </form>

            {/* Plan Management Section */}
            {(isPro || isElite) && (
                <div className="glass-card p-8 rounded-[2rem] border border-white/5 bg-slate-900/40">
                    <h3 className="text-xl font-bold text-white mb-6 flex items-center gap-2">
                        <CreditCard className="w-5 h-5 text-amber-400" />
                        Subscription Management
                    </h3>
                    <div className="flex flex-col md:flex-row items-center justify-between p-6 bg-slate-950/50 rounded-2xl border border-white/5 gap-4">
                        <div className="flex items-center gap-4">
                            <div className={`w-12 h-12 rounded-xl flex items-center justify-center ${isElite ? 'bg-purple-900/30 text-purple-400' : 'bg-amber-900/30 text-amber-400'}`}>
                                {isElite ? <Crown className="w-6 h-6" /> : <Zap className="w-6 h-6" />}
                            </div>
                            <div>
                                <h4 className="font-bold text-white text-base">Active Plan: {isElite ? 'Elite System' : 'Pro System'}</h4>
                                <p className="text-xs text-slate-400 mt-1">Next billing date: {new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toLocaleDateString()}</p>
                            </div>
                        </div>
                        <button 
                            onClick={() => setShowDowngradeConfirm(true)}
                            className="px-4 py-2 rounded-xl bg-slate-800 hover:bg-slate-700 text-slate-300 font-bold text-xs border border-white/10 transition-colors"
                        >
                            Cancel Subscription
                        </button>
                    </div>
                </div>
            )}

            <div className="glass-card p-8 rounded-[2rem] border border-white/5">
                 <h3 className="text-xl font-bold text-white mb-6 flex items-center gap-2">
                    <RefreshCw className="w-5 h-5 text-emerald-400" />
                    Protocol Preferences
                </h3>

                <div className="space-y-4">
                     <div className="flex items-center justify-between p-4 bg-slate-900/50 rounded-2xl border border-white/5">
                         <div className="flex items-center gap-4">
                             <div className="w-10 h-10 rounded-full bg-slate-800 flex items-center justify-center">
                                 <RefreshCw className="w-5 h-5 text-blue-400" />
                             </div>
                             <div>
                                 <h4 className="font-bold text-white text-sm">Interface Language</h4>
                                 <p className="text-xs text-slate-400 font-medium">Global localization setting.</p>
                             </div>
                         </div>
                         <div className="flex bg-slate-950 rounded-lg p-1 border border-white/10">
                             <button onClick={() => onUpdateLanguage('en')} className={`px-3 py-1.5 text-xs font-bold rounded-md transition-all ${language === 'en' ? 'bg-indigo-600 text-white shadow-sm' : 'text-slate-500 hover:text-slate-300'}`}>English</button>
                             <button onClick={() => onUpdateLanguage('vi')} className={`px-3 py-1.5 text-xs font-bold rounded-md transition-all ${language === 'vi' ? 'bg-indigo-600 text-white shadow-sm' : 'text-slate-500 hover:text-slate-300'}`}>Vietnam</button>
                         </div>
                    </div>

                    <div className="flex items-center justify-between p-4 bg-slate-900/50 rounded-2xl border border-white/5">
                         <div className="flex items-center gap-4">
                             <div className="w-10 h-10 rounded-full bg-slate-800 flex items-center justify-center">
                                 <Camera className="w-5 h-5 text-emerald-400" />
                             </div>
                             <div>
                                 <h4 className="font-bold text-white text-sm">Default Currency</h4>
                                 <p className="text-xs text-slate-400 font-medium">Reformat all monetary projections.</p>
                             </div>
                         </div>
                         <select 
                            value={currency} 
                            onChange={(e) => onUpdateCurrency(e.target.value as Currency)}
                            className="bg-slate-950 border border-white/10 rounded-lg text-xs font-bold text-white px-3 py-2 focus:outline-none focus:border-indigo-500 cursor-pointer"
                        >
                             <option value="USD">USD ($)</option>
                             <option value="EUR">EUR (€)</option>
                             <option value="GBP">GBP (£)</option>
                             <option value="JPY">JPY (¥)</option>
                             <option value="VND">VND (₫)</option>
                         </select>
                    </div>
                </div>
            </div>

            {/* Explanation Style Section */}
            <div className="glass-card p-8 rounded-[2rem] border border-white/5">
                 <h3 className="text-xl font-bold text-white mb-6 flex items-center gap-2">
                    <Sparkles className="w-5 h-5 text-purple-400" />
                    Explanation Style
                </h3>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <button 
                        onClick={() => onUpdateBotMode('ruthless')}
                        className={`p-5 rounded-2xl border transition-all text-left flex flex-col gap-3 group relative overflow-hidden ${botMode === 'ruthless' ? 'bg-slate-800 border-indigo-500 ring-1 ring-indigo-500/50' : 'bg-slate-900/50 border-white/5 hover:border-white/20'}`}
                    >
                        <div className="flex justify-between items-start w-full">
                            <div className="p-2 bg-slate-950 rounded-lg border border-white/10"><Terminal className="w-5 h-5 text-slate-400" /></div>
                            {botMode === 'ruthless' && <div className="w-3 h-3 bg-indigo-500 rounded-full shadow-[0_0_10px_#6366f1]"></div>}
                        </div>
                        <div>
                            <h4 className={`text-sm font-bold mb-1 ${botMode === 'ruthless' ? 'text-white' : 'text-slate-300'}`}>Analytical (Default)</h4>
                            <p className="text-[11px] text-slate-500 leading-relaxed font-medium">Cold, efficient system messages. Exact numbers and unavoidable consequences. No emotion.</p>
                        </div>
                    </button>

                    <button 
                        onClick={() => onUpdateBotMode('supportive')}
                        className={`p-5 rounded-2xl border transition-all text-left flex flex-col gap-3 group relative overflow-hidden ${botMode === 'supportive' ? 'bg-indigo-900/20 border-indigo-400 ring-1 ring-indigo-400/50' : 'bg-slate-900/50 border-white/5 hover:border-white/20'}`}
                    >
                        <div className="flex justify-between items-start w-full">
                            <div className="p-2 bg-slate-950 rounded-lg border border-white/10"><Heart className="w-5 h-5 text-pink-400" /></div>
                            {botMode === 'supportive' && <div className="w-3 h-3 bg-pink-500 rounded-full shadow-[0_0_10px_#ec4899]"></div>}
                        </div>
                        <div>
                            <h4 className={`text-sm font-bold mb-1 ${botMode === 'supportive' ? 'text-white' : 'text-slate-300'}`}>Supportive</h4>
                            <p className="text-[11px] text-slate-500 leading-relaxed font-medium">Warmer phrasing of the same hard facts. Gentle delivery without softening the financial reality.</p>
                        </div>
                    </button>
                </div>
