export default Settings;

import React, { useState, useEffect, useMemo } from 'react';
import { Transaction, Budget, UserPlan, TransactionType, Category } from '../types';
import { Zap, X, AlertOctagon, CheckSquare, ArrowRight, ShieldAlert, TrendingUp } from 'lucide-react';

interface FloatingAssistantProps {
  transactions: Transaction[];
  budgets: Budget[];
  userPlan: UserPlan;
  onOpenChat: (initialMessage?: string) => void;
  isVisible: boolean;
}

interface FinancialAlert {
  id: string;
  type: 'violation' | 'irreversible' | 'prediction';
  riskScore: number; // 0-100
  title: string;
  message: string;
  amount: number;
  actions: string[];
  contextPayload: string;
}

const FloatingAssistant: React.FC<FloatingAssistantProps> = ({ transactions, budgets, userPlan, onOpenChat, isVisible }) => {
  const [activeAlert, setActiveAlert] = useState<FinancialAlert | null>(null);
  const [panelMode, setPanelMode] = useState<'none' | 'inline' | 'diagnostic'>('none');
  const [isHovered, setIsHovered] = useState(false);

  // --- Strict Event-Driven Risk Engine ---
  useEffect(() => {
    const evaluateRisk = () => {
      const now = new Date();
      const currentMonth = now.getMonth();
      const currentYear = now.getFullYear();

      let highestRiskAlert: FinancialAlert | null = null;

      // 1. EVENT: Budget Violations (Compound Severity with Monthly Reset)
      budgets.forEach(b => {
        // Filter: Current Month Only (Implicit Decay at month boundary)
        const relevantTx = transactions.filter(t => 
            t.category === b.category && 
            t.type === TransactionType.EXPENSE && 
            new Date(t.date).getMonth() === currentMonth &&
            new Date(t.date).getFullYear() === currentYear
        );

        const spent = relevantTx.reduce((acc, t) => acc + t.amount, 0);

        if (spent > b.limit) {
          const overspend = spent - b.limit;
          const ratio = overspend / b.limit; // e.g. 0.5 for 50% over
          const txCount = relevantTx.length;

          // RISK FORMULA:
          // Severity: 40 points per 100% overspend. (e.g. 10% = 4pts, 50% = 20pts)
          const severityScore = Math.min(60, ratio * 40);

          // Habit: Starts impacting after 3rd transaction in category. +5 pts per repeat.
          const habitScore = Math.max(0, txCount - 3) * 5; 

          // Total Budget Risk: Capped at 95.
          const totalRisk = Math.min(95, severityScore + habitScore);

          if (!highestRiskAlert || totalRisk > highestRiskAlert.riskScore) {
            highestRiskAlert = {
              id: `budget_${b.category}`,
              type: 'violation',
              riskScore: totalRisk,
              title: 'Budget Boundary Crossed',
              message: `${b.category} limit exceeded by $${overspend.toFixed(0)}.`,
              amount: overspend,
              actions: [
                `Cease ${b.category} spending immediately`,
                `Cover $${overspend.toFixed(0)} gap from savings`,
                `Review ${txCount} transactions this month`
              ],
              contextPayload: `SYSTEM_INTERRUPT: BUDGET_VIOLATION. Category: ${b.category}. Limit: ${b.limit}. Spent: ${spent}. Over: ${overspend}. TxCount: ${txCount}. Risk_Score: ${totalRisk}.`
            };
          }
        }
      });

      // 2. EVENT: Irreversibility / Lock-in (Time-Clamped)
      // Checks for subscriptions renewal within < 48 hours.
      // Logic runs only if existing alert is not Critical (100).
      if (!highestRiskAlert || highestRiskAlert.riskScore < 95) {
          const upcomingSub = transactions.find(t => {
            const tDate = new Date(t.date);
            const isSub = t.category === Category.SUBSCRIPTION || t.category === Category.UTILITIES;

            // Normalize dates to ignore time for day comparison
            const tDay = new Date(now.getFullYear(), now.getMonth(), tDate.getDate()).getTime();
            const nowDay = new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime();

            // Check if date is today or tomorrow (and not in past)
            const diffTime = tDate.getTime() - now.getTime(); // Milliseconds
            const diffHours = diffTime / (1000 * 60 * 60);

            // Look ahead 48 hours, strictly future
            return isSub && diffHours > 0 && diffHours <= 48;
          });

          if (upcomingSub) {
              const subDate = new Date(upcomingSub.date);
              const hoursUntil = Math.max(0, (subDate.getTime() - now.getTime()) / (1000 * 60 * 60));

              // RISK FORMULA:
              // Base Cap: Irreversibility alone cannot exceed 60 (Diagnostic).
              // Time Factor: (48 - hours) * 1.25. 
              // Example: 48h left = 0 risk. 24h left = 30 risk. 0h left = 60 risk.
              const timeRisk = Math.min(60, Math.max(0, (48 - hoursUntil) * 1.25));

              // Compounding Factor: High Value > $100 adds +15 (Pushing to Critical 75 if imminent).
              const amountRisk = upcomingSub.amount > 100 ? 15 : 0;

              const totalRisk = timeRisk + amountRisk;

              if (totalRisk > 20 && (!highestRiskAlert || totalRisk > highestRiskAlert.riskScore)) {
                  highestRiskAlert = {
                      id: `sub_${upcomingSub.id}`,
                      type: 'irreversible',
                      riskScore: totalRisk,
                      title: 'Auto-Renewal Lock-in',
                      message: `${upcomingSub.merchant} executes in ~${hoursUntil.toFixed(1)}h. Irreversible.`,
                      amount: upcomingSub.amount,
                      actions: [
                          `Cancel at source immediately`,
                          `Confirm liquidity > $${upcomingSub.amount}`,
                          `Authorize payment explicitly`
                      ],
                      contextPayload: `SYSTEM_INTERRUPT: IRREVERSIBLE_EVENT. Type: Subscription Renewal. Merchant: ${upcomingSub.merchant}. Amount: ${upcomingSub.amount}. Hours_Remaining: ${hoursUntil.toFixed(1)}. Risk_Score: ${totalRisk}.`
                  };
              }
          }
      }

      // 3. EVENT: Elite Prediction (Runway Collapse)
      // Strictly gated for Elite users.
      if (userPlan === 'ultra' && (!highestRiskAlert || highestRiskAlert.riskScore < 90)) {
          const expenses = transactions.filter(t => t.type === TransactionType.EXPENSE && new Date(t.date).getMonth() === currentMonth);
          const income = transactions.filter(t => t.type === TransactionType.INCOME && new Date(t.date).getMonth() === currentMonth)
                                     .reduce((acc, t) => acc + t.amount, 0);

          if (income > 0) {
              const totalSpent = expenses.reduce((acc, t) => acc + t.amount, 0);
              const daysPassed = Math.max(1, now.getDate());
              const dailyBurn = totalSpent / daysPassed;

              if (totalSpent < income && dailyBurn > 0) {
                  const remainingBudget = income - totalSpent;
                  const daysRunway = remainingBudget / dailyBurn;

                  // RISK FORMULA:
                  // < 3 Days: Critical (95)
                  // < 7 Days: Diagnostic (60)
                  // Else: 0
                  let risk = 0;
                  if (daysRunway < 3) risk = 95;
                  else if (daysRunway < 7) risk = 60;

                  if (risk > 0) {
                      highestRiskAlert = {
                          id: 'pred_runway',
                          type: 'prediction',
                          riskScore: risk,
                          title: 'Cashflow Collapse',
                          message: `Runway depletion in ${daysRunway.toFixed(1)} days.`,
                          amount: 0, 
                          actions: [
                              `Freeze discretionary spending`,
                              `Transfer emergency liquidity`,
                              `Audit fixed burn rate`
                          ],
                          contextPayload: `SYSTEM_INTERRUPT: PREDICTIVE_RISK. Metric: Runway. Days_Remaining: ${daysRunway.toFixed(1)}. Status: CRITICAL. Risk_Score: ${risk}.`
                      };
                  }
              }
          }
      }

      setActiveAlert(highestRiskAlert);
    };

    evaluateRisk();
  }, [transactions, budgets, userPlan]); 

  // --- Interaction Router ---
  const handleInteraction = () => {
      if (!activeAlert) return;

      // ROUTING LOGIC
      // 1. Critical (>= 70): Force Redirect.
      if (activeAlert.riskScore >= 70) {
          onOpenChat(activeAlert.contextPayload);
          setPanelMode('none');
          return;
      }

      // 2. Diagnostic (40-69): Open Modal.
      if (activeAlert.riskScore >= 40) {
          setPanelMode(prev => prev === 'diagnostic' ? 'none' : 'diagnostic');
          return;
      }

      // 3. Inline (< 40): Toggle Popover.
      setPanelMode(prev => prev === 'inline' ? 'none' : 'inline');
  };

  const handleManualRedirect = () => {
      if (activeAlert) {
          onOpenChat(activeAlert.contextPayload);
          setPanelMode('none');
      }
  };

  // Visual Silence: If no alert, strictly render null.
  if (!activeAlert) return null;
  if (!isVisible && !activeAlert) return null;

  // Visuals based on Risk
  const isCritical = activeAlert.riskScore >= 70;
  const isDiagnostic = activeAlert.riskScore >= 40 && activeAlert.riskScore < 70;

  const getGlowColor = () => {
      if (isCritical) return 'shadow-rose-500/50 border-rose-500 animate-pulse';
      if (isDiagnostic) return 'shadow-amber-500/40 border-amber-500';
      return 'shadow-cyan-500/30 border-cyan-500'; 
  };

  return (
    <div className={`fixed bottom-24 md:bottom-6 right-6 z-[60] flex flex-col items-end gap-4 transition-opacity duration-300 ${!isVisible ? 'opacity-0 pointer-events-none' : 'opacity-100'}`}>

        {/* --- ROUTE 1: INLINE PANEL (< 40) --- */}
        {panelMode === 'inline' && activeAlert && (
            <div className="bg-slate-900/95 border border-cyan-500/30 p-4 rounded-2xl shadow-2xl backdrop-blur-xl w-64 animate-slide-up origin-bottom-right mb-2">
                <div className="flex items-start justify-between mb-3 border-b border-white/5 pb-2">
                    <h4 className="text-cyan-400 font-bold text-xs uppercase tracking-wider flex items-center gap-1.5">
                        <Zap className="w-3 h-3" /> {activeAlert.title}
                    </h4>
                    <button onClick={() => setPanelMode('none')} className="text-slate-500 hover:text-white"><X className="w-3 h-3" /></button>
                </div>
                <p className="text-slate-300 text-xs mb-3 font-medium">{activeAlert.message}</p>
                <div className="space-y-2">
                    {activeAlert.actions.map((action, i) => (
                        <div key={i} className="flex gap-2 items-start text-[10px] text-slate-400">
                            <CheckSquare className="w-3 h-3 text-cyan-500 shrink-0 mt-0.5" />
                            <span>{action}</span>
                        </div>
                    ))}
                </div>
            </div>
        )}

        {/* --- ROUTE 2: DIAGNOSTIC PANEL (40-69) --- */}
        {panelMode === 'diagnostic' && activeAlert && (
            <div className="bg-[#0f172a] border border-amber-500/30 p-6 rounded-[1.5rem] shadow-2xl w-80 animate-slide-up origin-bottom-right mb-2 ring-1 ring-amber-500/20">
                <div className="flex items-center gap-3 mb-4">
                    <div className="w-10 h-10 rounded-xl bg-amber-500/10 flex items-center justify-center border border-amber-500/20">
                        <AlertOctagon className="w-6 h-6 text-amber-500" />
                    </div>
                    <div>
                        <h4 className="text-white font-bold text-sm">Diagnostic Alert</h4>
                        <div className="flex items-center gap-2 mt-0.5">
                            <span className="h-1.5 w-16 bg-slate-800 rounded-full overflow-hidden">
                                <div className="h-full bg-amber-500" style={{ width: `${activeAlert.riskScore}%` }}></div>
                            </span>
                            <span className="text-[10px] text-amber-500 font-bold">{activeAlert.riskScore}/100 Risk</span>
                        </div>
                    </div>
                </div>

                <div className="bg-slate-900/50 rounded-xl p-3 mb-4 border border-white/5">
                    <p className="text-slate-200 text-xs font-medium leading-relaxed">{activeAlert.message}</p>
                    <div className="mt-2 text-[10px] text-slate-500 font-mono">IMPACT: ${activeAlert.amount.toFixed(2)}</div>
                </div>

                <div className="space-y-2 mb-5">
                    <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Recommended Actions</p>
                    {activeAlert.actions.slice(0, 2).map((action, i) => (
                        <div key={i} className="flex items-center gap-2 text-xs text-slate-400">
                            <div className="w-1.5 h-1.5 rounded-full bg-amber-500/50"></div>
                            {action}
                        </div>
                    ))}
                </div>

                <div className="grid grid-cols-2 gap-3">
                    <button onClick={() => setPanelMode('none')} className="py-2.5 rounded-lg text-xs font-bold text-slate-400 hover:text-white hover:bg-white/5 transition-colors">Dismiss</button>
                    <button 
                        onClick={handleManualRedirect}
                        className="py-2.5 rounded-lg bg-amber-600 hover:bg-amber-500 text-white text-xs font-bold shadow-lg shadow-amber-500/20 flex items-center justify-center gap-2"
                    >
                        Resolve with Coach <ArrowRight className="w-3 h-3" />
                    </button>
                </div>
            </div>
        )}

        {/* --- SYSTEM TRIGGER (ROBOT) --- */}
        {activeAlert && activeAlert.riskScore > 0 && (
            <>
                {/* Context Bubble for High/Medium Risk */}
                {!panelMode.match(/inline|diagnostic/) && activeAlert.riskScore >= 40 && (
                    <div 
                        onClick={handleInteraction}
                        className={`cursor-pointer px-4 py-2 rounded-xl backdrop-blur-xl border text-xs font-bold shadow-xl animate-slide-up hover:scale-105 transition-transform flex items-center gap-2
                        ${isCritical ? 'bg-rose-950/90 border-rose-500 text-white' : 'bg-amber-950/90 border-amber-500 text-amber-100'}`}
                    >
                        {isCritical ? <ShieldAlert className="w-4 h-4 animate-pulse" /> : <TrendingUp className="w-4 h-4" />}
                        {activeAlert.title}
                        {isCritical && <span className="ml-1 text-[9px] bg-white/20 px-1.5 py-0.5 rounded uppercase">Critical</span>}
                    </div>
                )}

                <button 
                    onClick={handleInteraction}
                    onMouseEnter={() => setIsHovered(true)}
                    onMouseLeave={() => setIsHovered(false)}
                    className={`relative w-16 h-16 group transition-all duration-300 ${isCritical ? 'animate-shake' : ''}`}
                >
                    {/* Status Indicator / Antenna */}
                    <div className="absolute -top-3 left-1/2 -translate-x-1/2 w-1 h-3 bg-slate-600 z-0 group-hover:-top-4 transition-all"></div>
                    <div className={`absolute -top-4 left-1/2 -translate-x-1/2 w-2.5 h-2.5 rounded-full z-10 transition-colors duration-300 ${isCritical ? 'bg-rose-500 animate-ping' : isDiagnostic ? 'bg-amber-500 animate-pulse' : 'bg-cyan-500'}`}></div>

                    {/* Main Unit */}
                    <div className={`w-16 h-16 rounded-2xl bg-[#0b1121] border-2 relative z-10 overflow-hidden shadow-2xl flex flex-col items-center justify-center transition-all duration-300 ${getGlowColor()}`}>

                        {/* Scanlines */}
                        <div className="absolute inset-0 bg-[linear-gradient(rgba(18,16,16,0)_50%,rgba(0,0,0,0.25)_50%),linear-gradient(90deg,rgba(255,0,0,0.06),rgba(0,255,0,0.02),rgba(0,0,255,0.06))] z-20 bg-[length:100%_2px,3px_100%] pointer-events-none opacity-20"></div>

                        {/* Eyes */}
                        <div className="relative z-30 flex gap-2 items-center">
                            <div className={`w-3 h-4 rounded-sm transition-all duration-300 ${isCritical ? 'bg-rose-500 shadow-[0_0_10px_#f43f5e] scale-110' : isDiagnostic ? 'bg-amber-500 shadow-[0_0_8px_#f59e0b]' : 'bg-cyan-400 shadow-[0_0_8px_#22d3ee]'}`}></div>
                            <div className={`w-3 h-4 rounded-sm transition-all duration-300 ${isCritical ? 'bg-rose-500 shadow-[0_0_10px_#f43f5e] scale-110' : isDiagnostic ? 'bg-amber-500 shadow-[0_0_8px_#f59e0b]' : 'bg-cyan-400 shadow-[0_0_8px_#22d3ee]'}`}></div>
                        </div>

                        {/* Mouth / Data Processor */}
                        <div className="relative z-30 mt-2 w-8 h-1 rounded-full bg-slate-800 overflow-hidden">
                            <div className={`h-full w-full ${isCritical ? 'bg-rose-600 animate-shimmer-fast' : isDiagnostic ? 'bg-amber-500' : 'bg-cyan-500'}`}></div>
                        </div>
                    </div>
                </button>
            </>
        )}

        <style>{`
            @keyframes shake { 0%, 100% { transform: translateX(0); } 25% { transform: translateX(-3px) rotate(-5deg); } 75% { transform: translateX(3px) rotate(5deg); } }
            .animate-shake { animation: shake 0.4s infinite; }
        `}</style>
    </div>
  );
};

export default FloatingAssistant;

import React, { useState, useEffect, useRef } from 'react';
import { User, Mail, Save, Download, Trash2, Camera, RefreshCw, ZoomIn, FileJson, UserCircle, Upload, Move, Sparkles, Lock, AlertTriangle, XCircle, Image as ImageIcon, Heart, Terminal, Crown, CreditCard, Zap } from 'lucide-react';
import { UserPlan, Language, Currency, ToastMessage, BotMode } from '../types';

interface SettingsProps {
  userName: string;
  userEmail: string;
  userAvatar: string;
  userAvatarZoom: number;
  userAvatarPos: { x: number; y: number };
  userBorder: string; 
  userBackground: string; 
  onUpdateBackground: (bg: string) => void;
  userPlan: UserPlan;
  onUpdateProfile: (name: string, email: string, avatar: string, zoom: number, pos: { x: number; y: number }, border: string) => void;
  addToast: (message: string, type?: ToastMessage['type']) => void;
  onExportData: () => void;
  onImportData: (file: File) => void;
  onClearData: () => void;
  language: Language;
  onUpdateLanguage: (lang: Language) => void;
  currency: Currency;
  onUpdateCurrency: (curr: Currency) => void;
  botMode: BotMode;
  onUpdateBotMode: (mode: BotMode) => void;
  onDowngrade?: () => void;
}

const AVATAR_PRESETS = [
  'bg-gradient-to-br from-indigo-500 to-purple-500',
  'bg-gradient-to-br from-emerald-400 to-cyan-500',
  'bg-gradient-to-br from-rose-500 to-orange-400',
  'bg-gradient-to-br from-amber-400 to-yellow-600',
  'bg-gradient-to-br from-blue-600 to-indigo-700',
  'bg-gradient-to-br from-slate-600 to-slate-800',
];

const BORDER_STYLES = [
  { id: 'default', label: 'Default', class: 'ring-1 ring-white/20' },
  { id: 'gold', label: 'Gold', class: 'ring-2 ring-amber-400 shadow-[0_0_15px_rgba(251,191,36,0.6)]' },
  { id: 'rainbow', label: 'Rainbow', class: 'ring-4 ring-transparent bg-gradient-to-tr from-rose-500 via-yellow-500 to-cyan-500 bg-[length:400%_400%] animate-gradient-xy p-[2px]' },
  { id: 'neon', label: 'Neon', class: 'ring-2 ring-cyan-400 shadow-[0_0_15px_rgba(34,211,238,0.6)]' },
  { id: 'plasma', label: 'Plasma', class: 'ring-2 ring-fuchsia-500 shadow-[0_0_15px_rgba(217,70,239,0.6)]' },
];

const Settings: React.FC<SettingsProps> = ({ 
  userName, 
  userEmail, 
  userAvatar, 
  userAvatarZoom, 
  userAvatarPos,
  userBorder,
  userBackground,
  onUpdateBackground,
  userPlan, 
  onUpdateProfile, 
  addToast,
  onExportData, 
  onImportData, 
  onClearData, 
  language, 
  onUpdateLanguage, 
  currency, 
  onUpdateCurrency,
  botMode,
  onUpdateBotMode,
  onDowngrade
}) => {
  const [name, setName] = useState(userName);
  const [email, setEmail] = useState(userEmail);
  const [avatar, setAvatar] = useState(userAvatar);
  const [zoom, setZoom] = useState(userAvatarZoom);
  const [pos, setPos] = useState(userAvatarPos);
  const [border, setBorder] = useState(userBorder);
  const [isSaving, setIsSaving] = useState(false);
  const [isDragging, setIsDragging] = useState(false);
  const [showResetConfirm, setShowResetConfirm] = useState(false);
  const [showDowngradeConfirm, setShowDowngradeConfirm] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const bgInputRef = useRef<HTMLInputElement>(null);
  const dragRef = useRef<{ startX: number; startY: number; startPosX: number; startPosY: number } | null>(null);
  const isPro = userPlan === 'pro' || userPlan === 'ultra';
  const isElite = userPlan === 'ultra';

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    setIsSaving(true);
    // Data Integrity: Save first, then visual feedback
    onUpdateProfile(name, email, avatar, zoom, pos, border);

    setTimeout(() => {
      setIsSaving(false);
      addToast('Profile Saved: Your identity and avatar are updated.', 'success');
    }, 800);
  };

  // Image Compressor to prevent localStorage crashes
  const compressImage = (file: File): Promise<string> => {
      return new Promise((resolve) => {
          const reader = new FileReader();
          reader.readAsDataURL(file);
          reader.onload = (e) => {
              const img = new Image();
              img.src = e.target?.result as string;
              img.onload = () => {
                  const canvas = document.createElement('canvas');
                  const MAX_WIDTH = 300; // Resize to reasonable avatar size
                  const scale = MAX_WIDTH / img.width;
                  canvas.width = MAX_WIDTH;
                  canvas.height = img.height * scale;

                  const ctx = canvas.getContext('2d');
                  if (ctx) {
                      ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
                      // High compression for storage
                      resolve(canvas.toDataURL('image/jpeg', 0.7)); 
                  } else {
                      // Fallback if canvas context fails
                      resolve(img.src);
                  }
              }
          }
      });
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      try {
          const compressed = await compressImage(file);
          setAvatar(compressed);
          setZoom(1);
          setPos({ x: 0, y: 0 });
      } catch (err) {
          addToast('Failed to process image. Try a smaller file.', 'error');
      }
    }
  };

  const handleBackgroundChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (file) {
          // No compression for background needed yet as it's less frequent, but careful with size
          const reader = new FileReader();
          reader.onloadend = () => {
              const result = reader.result as string;
              onUpdateBackground(result);
              addToast('Dashboard background updated.', 'success');
          };
          reader.readAsDataURL(file);
      }
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    if (!isImageAvatar) return;
    setIsDragging(true);
    dragRef.current = {
      startX: e.clientX,
      startY: e.clientY,
      startPosX: pos.x,
      startPosY: pos.y
    };
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isDragging || !dragRef.current) return;

    // Zoom sensitivity should decrease as zoom increases to prevent hyper-fast movement
    const sensitivity = 0.5 / zoom;
    const dx = (e.clientX - dragRef.current.startX) * sensitivity;
    const dy = (e.clientY - dragRef.current.startY) * sensitivity;

    setPos({
      x: Math.max(-100, Math.min(100, dragRef.current.startPosX + dx)),
      y: Math.max(-100, Math.min(100, dragRef.current.startPosY + dy))
    });
  };

  const handleMouseUp = () => {
    setIsDragging(false);
    dragRef.current = null;
  };

  const handleImportFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      onImportData(file);
    }
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const isImageAvatar = avatar.includes('http') || avatar.startsWith('data:');

  const getBorderClasses = (styleId: string) => {
     const style = BORDER_STYLES.find(s => s.id === styleId);
     return style ? style.class : BORDER_STYLES[0].class;
  };

  return (
    <div className="animate-slide-up pb-10 max-w-5xl mx-auto" onMouseUp={handleMouseUp} onMouseLeave={handleMouseUp}>
      <div className="mb-8">
        <h2 className="text-3xl font-bold text-white tracking-tight">Settings</h2>
        <p className="text-slate-400 mt-2 font-medium">Manage your profile and system preferences.</p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">

        {/* Left Column: Profile Card */}
        <div className="lg:col-span-1 space-y-6">
            <div className="glass-card p-8 rounded-[2rem] text-center border border-white/5 relative overflow-hidden">
                <div className="absolute top-0 left-0 w-full h-32 bg-gradient-to-b from-indigo-500/10 to-transparent pointer-events-none"></div>

                <div className="relative inline-block mb-6 group select-none">
                    <div 
                      onMouseDown={handleMouseDown}
                      onMouseMove={handleMouseMove}
                      className={`w-32 h-32 rounded-full flex items-center justify-center shadow-2xl transition-all duration-300 ${!isImageAvatar ? avatar : ''} overflow-hidden bg-slate-800 ${isImageAvatar ? 'cursor-grab active:cursor-grabbing' : ''} ${getBorderClasses(border)}`}
                    >
                         {isImageAvatar ? (
                             <img 
                                src={avatar} 
                                alt="Profile" 
                                className="w-full h-full object-cover transition-transform duration-100 pointer-events-none" 
                                style={{ 
                                  transform: `scale(${zoom}) translate(${pos.x}px, ${pos.y}px)`,
                                  filter: isDragging ? 'brightness(1.1)' : 'none'
                                }}
                             />
                         ) : (
                             <User className="w-12 h-12 text-white/80" />
                         )}
                         {isImageAvatar && zoom > 1 && (
                            <div className="absolute inset-0 bg-white/5 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity">
                                <Move className="w-6 h-6 text-white drop-shadow-lg" />
                            </div>
                         )}
                    </div>
                </div>

                <h3 className="text-xl font-bold text-white">{name}</h3>
                <p className="text-slate-400 text-sm mb-4">{email}</p>

                <div className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-bold uppercase tracking-wider ${isElite ? 'bg-purple-500/10 text-purple-400 border border-purple-500/20' : isPro ? 'bg-amber-500/10 text-amber-400 border-amber-500/20' : 'bg-slate-700/50 text-slate-300 border border-white/5'}`}>
                    {isElite ? 'Elite' : isPro ? 'Nova Pro' : 'Free Plan'}
                </div>
            </div>

            <div className="glass-card p-6 rounded-[2rem] border border-white/5">
                <h4 className="text-sm font-bold text-white mb-4">Identity Style</h4>
                <div className="grid grid-cols-4 gap-3 mb-6">
                    {AVATAR_PRESETS.map((preset, idx) => (
                        <button
                            key={idx}
                            onClick={() => { setAvatar(preset); setZoom(1); setPos({x:0, y:0}); }}
                            className={`w-12 h-12 rounded-full ${preset} hover:scale-110 transition-transform ring-2 ring-offset-2 ring-offset-slate-900 ${avatar === preset ? 'ring-white' : 'ring-transparent'}`}
                        />
                    ))}
                </div>

                {/* Pro Border Selection */}
                <div className="pt-4 border-t border-white/5">
                    <div className="flex justify-between items-center mb-3">
                        <h4 className="text-sm font-bold text-white flex items-center gap-1.5">
                            Elite Aesthetics 
                            {!isElite && <Lock className="w-3 h-3 text-slate-500" />}
                        </h4>
                        {isElite && <Crown className="w-3 h-3 text-purple-400" />}
                    </div>

                    <div className={`grid grid-cols-5 gap-2 ${!isElite ? 'opacity-50 pointer-events-none grayscale' : ''}`}>
                        {BORDER_STYLES.map((style) => (
                            <button
                                key={style.id}
                                onClick={() => setBorder(style.id)}
                                title={style.label}
                                className={`w-8 h-8 rounded-full bg-slate-800 transition-all ${getBorderClasses(style.id)} ${border === style.id ? 'scale-110' : 'hover:scale-105 opacity-80'}`}
                            >
                            </button>
                        ))}
                    </div>
                    {!isElite && <p className="text-[10px] text-slate-500 mt-2 font-medium">Upgrade to Elite to unlock custom borders.</p>}
                </div>

                <div className="space-y-4 pt-4 border-t border-white/5 mt-4">
                    {isImageAvatar && (
                        <div className="space-y-4">
                            <div className="space-y-2">
                                <div className="flex justify-between items-center text-xs font-bold text-slate-400 uppercase tracking-wider">
                                    <span className="flex items-center gap-1"><ZoomIn className="w-3 h-3" /> Magnitude</span>
                                    <span className="text-white">{(zoom * 100).toFixed(0)}%</span>
                                </div>
                                <input 
                                    type="range" 
                                    min="1" 
                                    max="3" 
                                    step="0.05" 
                                    value={zoom}
                                    onChange={(e) => setZoom(parseFloat(e.target.value))}
                                    className="w-full h-2 bg-slate-800 rounded-lg appearance-none cursor-pointer accent-indigo-500 hover:accent-indigo-400"
                                />
                            </div>
                            <div className="p-3 bg-indigo-500/10 rounded-xl border border-indigo-500/20 text-[10px] text-indigo-200 leading-relaxed font-bold uppercase tracking-tight">
                                <Move className="w-3 h-3 inline mr-1 mb-0.5" /> 
                                Drag photo within frame to adjust alignment.
                            </div>
                        </div>
                    )}

                    <div>
                        <p className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-2">Deploy Identity Plate</p>
                        <div className="relative group">
                            <input 
                                type="file" 
                                accept="image/*"
                                onChange={handleFileChange}
                                className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10"
                            />
                            <button className="w-full py-2.5 bg-slate-800 hover:bg-slate-700 text-slate-300 rounded-xl text-sm font-bold border border-white/5 transition-all flex items-center justify-center gap-2 group-hover:text-white">
                                <Upload className="w-4 h-4" /> Upload Custom Photo
                            </button>
                        </div>
                    </div>
                </div>
            </div>
        </div>

        {/* Right Column: Forms & Settings */}
        <div className="lg:col-span-2 space-y-8">
            <form onSubmit={handleSave} className="glass-card p-8 rounded-[2rem] border border-white/5 relative overflow-hidden">
                 <div className="flex justify-between items-center mb-6">
                    <h3 className="text-xl font-bold text-white flex items-center gap-2">
                        <UserCircle className="w-5 h-5 text-indigo-400" />
                        Identity Matrix
                    </h3>
                    <button 
                        type="submit"
                        disabled={isSaving}
                        className="px-5 py-2 bg-indigo-600 hover:bg-indigo-500 text-white rounded-xl text-sm font-bold shadow-lg shadow-indigo-500/20 active:scale-95 transition-all flex items-center gap-2 disabled:opacity-70"
                    >
                        {isSaving ? <RefreshCw className="w-4 h-4 animate-spin" /> : <Save className="w-4 h-4" />}
                        {isSaving ? 'Processing...' : 'Save Profile & Avatar'}
                    </button>
                 </div>

                 <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div>
                        <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-2 block">Pilot Name</label>
                        <div className="relative">
                            <User className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500" />
                            <input 
                                type="text" 
                                value={name}
                                onChange={(e) => setName(e.target.value)}
                                className="w-full bg-slate-950/50 border border-white/10 rounded-xl py-3 pl-10 pr-4 text-white focus:border-indigo-500 focus:outline-none focus:ring-4 focus:ring-indigo-500/10 transition-all placeholder:text-slate-600 font-medium"
                            />
                        </div>
                    </div>
                    <div>
                        <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-2 block">Pilot Email</label>
                        <div className="relative">
                            <Mail className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500" />
                            <input 
                                type="email" 
                                value={email}
                                onChange={(e) => setEmail(e.target.value)}
                                className="w-full bg-slate-950/50 border border-white/10 rounded-xl py-3 pl-10 pr-4 text-white focus:border-indigo-500 focus:outline-none focus:ring-4 focus:ring-indigo-500/10 transition-all placeholder:text-slate-600 font-medium"
                            />
