                             <XCircle className="w-3 h-3" /> Remove Custom
                         </button>
                     )}
                 </div>

                 <div className={`p-6 bg-slate-900/50 rounded-2xl border border-white/5 relative overflow-hidden ${!isPro ? 'opacity-50 pointer-events-none' : ''}`}>
