                    transactions={transactions} 
                    accounts={accounts}
                    onDelete={(id) => setTransactions(prev => prev.filter(t => t.id !== id))}
                    onAdd={(t) => { setTransactions(prev => [t, ...prev]); addToast('Transaction added', 'success'); }}
                    formatCurrency={formatCurrency}
                    onNavigateToAccounts={() => setActiveTab('accounts')}
                    userPlan={userPlan}
                    scanUsage={scanUsage}
                    onIncrementScan={() => setScanUsage(prev => prev + 1)}
                    currency={currency}
                />
            )}

            {activeTab === 'accounts' && (
                <Accounts 
                    accounts={accounts} 
                    budgets={budgets} 
                    transactions={transactions} 
                    userPlan={userPlan}
                    onAdd={(acc) => { setAccounts(prev => [...prev, acc]); addToast('Account connected', 'success'); }}
                    onUpdate={(acc) => { setAccounts(prev => prev.map(a => a.id === acc.id ? acc : a)); addToast('Account updated', 'success'); }}
                    onDelete={(id) => { 
                        // Migration Logic: Remove account, keep transactions (set to 'manual')
                        setAccounts(prev => prev.filter(a => a.id !== id));
                        setTransactions(prev => prev.map(t => t.accountId === id ? { ...t, accountId: 'manual' } : t));
                        addToast('Account removed (history preserved)', 'info'); 
                    }}
                    formatCurrency={formatCurrency}
                    userName={userName}
                    userAvatar={userAvatar}
                    userAvatarZoom={userAvatarZoom}
                    userAvatarPos={userAvatarPos}
                    userBorder={userBorder}
                    onNavigate={setActiveTab}
                />
            )}

            {activeTab === 'insights' && (
                <Insights 
                    transactions={transactions} 
                    userPlan={userPlan} 
                    onUpgradeClick={() => setActiveTab('plans')}
                    formatCurrency={formatCurrency}
                    insightUsage={insightUsage}
                    onIncrementUsage={() => setInsightUsage(prev => prev + 1)}
                    onApplyBudgets={(newBudgets) => {
                         const existingCats = new Set(budgets.map(b => b.category));
                         const toAdd = newBudgets.filter(b => !existingCats.has(b.category));
                         setBudgets(prev => [...prev, ...toAdd]);
                         addToast(`Applied ${toAdd.length} new budget limits`, 'success');
                    }}
                    initialPrompt={pendingChatQuery}
                    onPromptHandled={() => setPendingChatQuery(null)}
                    botMode={botMode}
                />
            )}

            {activeTab === 'goals' && (
                <Goals 
                    goals={goals} 
                    budgets={budgets} 
                    transactions={transactions}
                    onAddGoal={(g) => { setGoals(prev => [...prev, g]); addToast('Goal created', 'success'); }}
                    onUpdateGoal={(g) => { setGoals(prev => prev.map(goal => goal.id === g.id ? g : goal)); addToast('Goal updated', 'success'); }}
                    onAddBudget={(b) => { setBudgets(prev => [...prev, b]); addToast('Budget limit set', 'success'); }}
                    onDeleteBudget={(id) => { setBudgets(prev => prev.filter(b => b.id !== id)); addToast('Budget removed', 'info'); }}
                    formatCurrency={formatCurrency} 
                />
            )}

            {/* Plans Tab: Explicitly hidden via conditional rendering if user is Ultra */}
            {activeTab === 'plans' && userPlan !== 'ultra' && (
                <Plans 
                    currentPlan={userPlan} 
                    onUpgrade={(plan) => { setUserPlan(plan); addToast(`Welcome to ${plan.charAt(0).toUpperCase() + plan.slice(1)}`, 'success'); }}
                    onDowngrade={() => { setUserPlan('free'); addToast('Plan downgraded to Free', 'info'); }}
                />
            )}

            {activeTab === 'settings' && (
                <Settings 
                    userName={userName}
                    userEmail={userEmail}
                    userAvatar={userAvatar}
                    userAvatarZoom={userAvatarZoom}
                    userAvatarPos={userAvatarPos}
                    userBorder={userBorder}
                    userBackground={userBackground}
                    onUpdateBackground={setUserBackground}
                    userPlan={userPlan}
                    onUpdateProfile={handleUpdateProfile}
                    addToast={addToast}
                    onExportData={handleExportData}
                    onImportData={handleImportData}
                    onClearData={handleClearData}
                    language={language}
                    onUpdateLanguage={setLanguage}
                    currency={currency}
                    onUpdateCurrency={setCurrency}
                    botMode={botMode}
                    onUpdateBotMode={setBotMode}
                    onDowngrade={() => { setUserPlan('free'); addToast('Plan downgraded to Free', 'info'); }}
                />
            )}
        </div>
      </main>

      <ToastContainer toasts={toasts} onRemove={removeToast} />
    </div>
  );
};

export default App;

