                    onDelete={(id) => { 
                        // Migration Logic: Remove account, keep transactions (set to 'manual')
                        setAccounts(prev => prev.filter(a => a.id !== id));
                        setTransactions(prev => prev.map(t => t.accountId === id ? { ...t, accountId: 'manual' } : t));
