                         setBudgets(prev => [...prev, ...toAdd]);
                         addToast(`Applied ${toAdd.length} new budget limits`, 'success');
                    }}
                    initialPrompt={pendingChatQuery}
                    onPromptHandled={() => setPendingChatQuery(null)}
                    botMode={botMode}
                />
            )}

            {activeTab === 'goals' && (
                <Goals 
                    goals={goals} 
                    budgets={budgets} 
                    transactions={transactions}
                    onAddGoal={(g) => { setGoals(prev => [...prev, g]); addToast('Goal created', 'success'); }}
