import { GoogleGenAI, Type, Schema } from "@google/genai";
import { Transaction, AIAnalysisResponse, BotMode, Category } from '../types';

let lastCallTime = 0;
const MIN_INTERVAL_MS = 2000;
const apiKey = process.env.API_KEY;

const ai = apiKey ? new GoogleGenAI({ apiKey }) : null;

const checkRateLimit = () => {
  const now = Date.now();
  if (now - lastCallTime < MIN_INTERVAL_MS) {
    throw new Error("System cooling down. Please wait.");
  }
  lastCallTime = now;
};

const cleanJsonResponse = (text: string) => {
  return text.replace(/```json/g, '').replace(/```/g, '').trim();
};

export const analyzeFinancialData = async (transactions: Transaction[]): Promise<AIAnalysisResponse | null> => {
  if (!ai) return null;

  try {
    checkRateLimit();
    const recentTxs = transactions.slice(0, 50);
    const dataString = JSON.stringify(recentTxs);

    const prompt = `
    Act as a strict but helpful financial wellness coach named Nova. Analyze these transactions.
    1. Identify critical spending anomalies.
    2. Suggest specific budget limits.
    3. Predict total spending for next month.
    4. Assign a risk score (0-100).
    Return strict JSON matching the schema.`;

    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Data: ${dataString}. ${prompt}`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            insights: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  title: { type: Type.STRING },
                  description: { type: Type.STRING },
                  type: { type: Type.STRING, enum: ['success', 'warning', 'info', 'critical'] },
                  actionable: { type: Type.BOOLEAN },
                  metric: { type: Type.STRING }
                }
              }
            },
            budget_suggestions: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  category: { type: Type.STRING },
                  current_spend: { type: Type.NUMBER },
                  suggested_limit: { type: Type.NUMBER },
                  reason: { type: Type.STRING }
                }
              }
            },
            predicted_spend_next_month: { type: Type.NUMBER },
            risk_score: { type: Type.NUMBER }
          }
        }
      }
    });

    if (response.text) {
      return JSON.parse(cleanJsonResponse(response.text)) as AIAnalysisResponse;
    }
    return null;
  } catch (error) {
    return null;
  }
};

export const categorizeTransaction = async (merchant: string, amount: number): Promise<string> => {
  if (!ai) return 'Other';
  try {
    checkRateLimit();
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Categorize "${merchant}" ($${amount}). 
      Exact string only: 'Housing', 'Food & Dining', 'Transportation', 'Entertainment', 'Shopping', 'Utilities', 'Health', 'Subscription', 'Education', 'Travel', 'Pets', 'Kids', 'Gifts', 'Services', 'Investment', 'Other'.`,
    });
    return response.text?.trim() || 'Other';
  } catch (e) {
    return 'Other';
  }
};

export const chatWithFinancialCoach = async (message: string, context: Transaction[], mode: BotMode = 'ruthless'): Promise<string> => {
  if (!ai) return "AI System Offline.";

  const dataSummary = JSON.stringify(context.slice(0, 20));
  const instructions = mode === 'ruthless' 
    ? "STYLE: Cold, Analytical System Message. State violations with exact numbers. NO emojis. NO sympathy."
    : "STYLE: Supportive Translation Layer. Present hard facts warmly but accurately. MAX one emoji.";

  try {
    checkRateLimit();
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `System: You are Nova. Style: ${instructions} Context: ${dataSummary}. User: ${message}`,
    });
    return response.text || "System error.";
  } catch (error) {
    return "Connection throttle. Wait 2s.";
  }
};

export const parseReceiptImage = async (base64Image: string): Promise<{ merchant: string; date: string; amount: number; category: string } | null> => {
  if (!ai) return null;
  try {
    checkRateLimit();
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: {
        parts: [
          { inlineData: { mimeType: 'image/jpeg', data: base64Image } },
          { text: "Extract merchant, date (YYYY-MM-DD), total amount, and category. Return strictly JSON." }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            merchant: { type: Type.STRING },
            date: { type: Type.STRING },
            amount: { type: Type.NUMBER },
            category: { type: Type.STRING }
          }
        }
      }
    });
    return response.text ? JSON.parse(cleanJsonResponse(response.text)) : null;
  } catch (error) {
    return null;
  }
};

export const generateNegotiationScript = async (merchant: string, amount: number): Promise<string> => {
  if (!ai) return "Offline.";
  try {
    checkRateLimit();
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Write a strictly factual retention/discount script for "${merchant}" currently costing $${amount}/month. No greetings.`,
    });
    return response.text?.trim() || "Error.";
  } catch (error) {
    return "Throttle.";
  }
};

import React, { useMemo, useState } from 'react';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import { Account, Transaction, TransactionType, Category, UserPlan } from '../types';
import { ArrowUpRight, DollarSign, Activity, Layers, Flame, TrendingUp, MoreHorizontal, ArrowRight, Wallet, PlusCircle, CreditCard, Target, ChevronRight, Quote, Landmark, Zap, Radio, RefreshCw, Repeat, Check, MessageCircle, Handshake, Copy, AlertCircle, X, Loader2 } from 'lucide-react';
import { generateNegotiationScript } from '../services/geminiService';

interface DashboardProps {
  accounts: Account[];
  transactions: Transaction[];
  onNavigate: (tab: string) => void;
  onAddAccount?: () => void;
  onAddTransaction?: () => void;
  onAddGoal?: () => void;
  formatCurrency: (amount: number) => string;
  onBatchCategoryUpdate?: (merchant: string, category: Category) => void; 
  userPlan?: UserPlan;
  onAskCoach?: (message: string) => void;
  negotiationUsage: number;
  onIncrementNegotiation: () => void;
}

const COLORS = ['#6366f1', '#ec4899', '#10b981', '#f59e0b', '#8b5cf6', '#3b82f6'];

const QUOTES = [
  { text: "Do not save what is left after spending, but spend what is left after saving.", author: "Warren Buffett" },
  { text: "A budget is telling your money where to go instead of wondering where it went.", author: "Dave Ramsey" },
  { text: "It's not your salary that makes you rich, it's your spending habits.", author: "Charles A. Jaffe" },
  { text: "The art is not in making money, but in keeping it.", author: "Proverb" },
];

const Dashboard: React.FC<DashboardProps> = ({ accounts, transactions, onNavigate, onAddAccount, onAddTransaction, onAddGoal, formatCurrency, onBatchCategoryUpdate, userPlan, onAskCoach, negotiationUsage, onIncrementNegotiation }) => {
  const hasData = accounts.length > 0 || transactions.length > 0;
  const randomQuote = useMemo(() => QUOTES[Math.floor(Math.random() * QUOTES.length)], []);
  const netWorth = useMemo(() => accounts.reduce((acc, curr) => acc + curr.balance, 0), [accounts]);

  const [isNegotiating, setIsNegotiating] = useState(false);
  const [script, setScript] = useState<string | null>(null);
  const [scriptMerchant, setScriptMerchant] = useState('');
  const [showNegotiationModal, setShowNegotiationModal] = useState(false);
  const [copySuccess, setCopySuccess] = useState(false);

  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const currentMonth = today.getMonth();
  const currentYear = today.getFullYear();

  const monthlySpending = useMemo(() => {
    return transactions
      .filter(t => {
        const d = new Date(t.date);
        return t.type === TransactionType.EXPENSE && d.getMonth() === currentMonth && d.getFullYear() === currentYear;
      })
      .reduce((acc, curr) => acc + curr.amount, 0);
  }, [transactions, currentMonth, currentYear]);

  const monthlyIncome = useMemo(() => {
    return transactions
      .filter(t => {
        const d = new Date(t.date);
        return t.type === TransactionType.INCOME && d.getMonth() === currentMonth && d.getFullYear() === currentYear;
      })
      .reduce((acc, curr) => acc + curr.amount, 0);
  }, [transactions, currentMonth, currentYear]);

  const burnRate = monthlySpending / Math.max(today.getDate(), 1);

  const recurringData = useMemo(() => {
      const merchantMap = new Map<string, { count: number; total: number; amounts: number[]; displayNames: string[]; categories: Set<Category>; }>();
      transactions.filter(t => t.type === TransactionType.EXPENSE).forEach(t => {
            const normalizedKey = t.merchant.toLowerCase().trim();
            const existing = merchantMap.get(normalizedKey) || { count: 0, total: 0, amounts: [], displayNames: [], categories: new Set() };
            existing.count++;
            existing.total += t.amount;
            existing.amounts.push(t.amount);
            existing.displayNames.push(t.merchant);
            existing.categories.add(t.category);
            merchantMap.set(normalizedKey, existing);
        });

      const recurringItems: { merchant: string; avgCost: number; isSubscription: boolean }[] = [];
      let totalMonthlyFixed = 0;
      merchantMap.forEach((data, key) => {
          const avg = data.total / data.count;
          const isExplicitSubscription = data.categories.has(Category.SUBSCRIPTION);
          const isConsistent = data.amounts.every(a => Math.abs(a - avg) / avg < 0.25);
          if (isExplicitSubscription || (data.count > 1 && isConsistent)) {
              const bestName = data.displayNames[0];
              recurringItems.push({ merchant: bestName, avgCost: avg, isSubscription: isExplicitSubscription });
              totalMonthlyFixed += avg;
          }
      });
      return { items: recurringItems.sort((a,b) => b.avgCost - a.avgCost), total: totalMonthlyFixed };
  }, [transactions]);

  const spendingData = useMemo(() => {
    const dataPoints: { date: string, actual: number | null, predicted: number | null, timestamp: number }[] = [];
    const expenseMap = new Map<string, number>();
    transactions.filter(t => t.type === TransactionType.EXPENSE).forEach(t => {
        const d = new Date(t.date);
        d.setHours(0, 0, 0, 0);
        const key = d.toDateString();
        expenseMap.set(key, (expenseMap.get(key) || 0) + t.amount);
      });

    for (let i = 0; i <= 30; i++) {
        const d = new Date(today);
        d.setDate(today.getDate() - (30 - i));
        d.setHours(0, 0, 0, 0);
        dataPoints.push({
            date: d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }),
            actual: expenseMap.get(d.toDateString()) || 0,
            predicted: null,
            timestamp: d.getTime()
        });
    }

    const lastActual = dataPoints[dataPoints.length - 1];
    lastActual.predicted = lastActual.actual;

    for (let i = 1; i <= 7; i++) {
        const d = new Date(today);
        d.setDate(today.getDate() + i);
        d.setHours(0, 0, 0, 0);
        dataPoints.push({
            date: d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }),
            actual: null,
            predicted: burnRate * (1 + (Math.sin(i) * 0.05)),
            timestamp: d.getTime()
        });
    }
    return dataPoints;
  }, [transactions, burnRate]);

  const handleNegotiateClick = async (merchant: string, amount: number) => {
      const limit = userPlan === 'ultra' ? Infinity : userPlan === 'pro' ? 5 : 1;
      if (negotiationUsage >= limit) {
          onNavigate('plans');
          return; 
      }
      setIsNegotiating(true);
      setScriptMerchant(merchant);
      setScript(null);
      setShowNegotiationModal(true);
      const generatedScript = await generateNegotiationScript(merchant, amount);
      setScript(generatedScript);
      setIsNegotiating(false);
      onIncrementNegotiation();
  };

  if (!hasData) {
     return (
        <div className="flex flex-col items-center justify-center w-full min-h-full py-12 animate-fade-in text-center relative">
            <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[600px] h-[600px] bg-indigo-500/10 rounded-full blur-[120px] pointer-events-none animate-pulse-slow"></div>
            <div className="max-w-4xl mx-auto mb-12 relative z-10">
                <div className="flex justify-center mb-8">
                    <div className="w-14 h-14 rounded-2xl bg-gradient-to-tr from-amber-400 to-orange-500 flex items-center justify-center shadow-[0_0_30px_rgba(251,191,36,0.3)] rotate-3">
                        <Quote className="w-7 h-7 text-white fill-current" />
                    </div>
                </div>
                <h1 className="text-3xl md:text-4xl font-bold text-white tracking-tight mb-4 leading-tight px-4">"{randomQuote.text}"</h1>
                <p className="text-lg text-slate-400 font-medium italic tracking-wide">— {randomQuote.author}</p>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6 w-full max-w-5xl relative z-10 px-4">
                 <button onClick={onAddAccount} className="group glass-card p-8 rounded-[2rem] text-left border border-white/5 hover:border-indigo-500/30 transition-all hover:-translate-y-2 hover:shadow-2xl">
                    <div className="w-14 h-14 rounded-2xl bg-indigo-500/10 flex items-center justify-center mb-6 group-hover:bg-indigo-500 group-hover:text-white transition-colors text-indigo-400 shadow-inner"><Landmark className="w-7 h-7" /></div>
                    <h3 className="text-xl font-bold text-white mb-2">Connect Accounts</h3>
