                       </div>
                       <div className="flex items-center gap-2">
                           <span className="text-sm font-bold text-white">{formatCurrency(item.avgCost)}</span>
                           {item.isSubscription && (
                               <button onClick={() => handleNegotiateClick(item.merchant, item.avgCost)} className="p-1.5 bg-emerald-500/10 text-emerald-400 rounded-lg hover:bg-emerald-500/20 shadow-inner"><Handshake className="w-3 h-3" /></button>
                           )}
                       </div>
                   </div>
               ))}
           </div>
        </div>
      </div>

      {showNegotiationModal && (
          <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/80 backdrop-blur-md animate-fade-in">
              <div className="bg-[#0f172a] border border-white/10 rounded-3xl w-full max-w-lg shadow-2xl overflow-hidden animate-slide-up relative">
                  <div className="p-6 border-b border-white/5 flex justify-between items-center bg-slate-900/50">
                      <h3 className="text-lg font-bold text-white uppercase tracking-widest">Negotiation Script: {scriptMerchant}</h3>
                      <button onClick={() => setShowNegotiationModal(false)} className="text-slate-500 hover:text-white"><X className="w-5 h-5" /></button>
                  </div>
                  <div className="p-8">
                      {isNegotiating ? <div className="flex flex-col items-center gap-4 py-8"><Loader2 className="w-10 h-10 animate-spin text-indigo-500" /><p className="text-xs font-black text-indigo-400 uppercase">Generating script...</p></div> : 
                      <div className="bg-slate-950 p-6 rounded-2xl text-sm font-mono text-slate-300 leading-relaxed relative border border-white/5">
                        {script}
                        <button onClick={() => {navigator.clipboard.writeText(script!); setCopySuccess(true); setTimeout(()=>setCopySuccess(false),2000)}} className="absolute top-3 right-3 p-2 bg-indigo-600/20 text-indigo-400 rounded-xl hover:bg-indigo-600 hover:text-white transition-all">
                            {copySuccess ? <Check className="w-4 h-4" /> : <Copy className="w-4 h-4" />}
                        </button>
                      </div>}
                  </div>
              </div>
          </div>
      )}
    </div>
  );
};

