const AddTransactionModal: React.FC<{ 
    onClose: () => void; 
    onAdd: (t: Transaction) => void;
    accounts: Account[];
    onNavigateToAccounts?: () => void;
    userPlan?: UserPlan;
    formatCurrency: (amount: number) => string;
    scanUsage: number;
    onIncrementScan?: () => void;
    currency: Currency;
}> = ({ onClose, onAdd, accounts, onNavigateToAccounts, userPlan, formatCurrency, scanUsage, onIncrementScan, currency }) => {
    const [type, setType] = useState<TransactionType>(TransactionType.EXPENSE);
    const [merchant, setMerchant] = useState('');
    const [amount, setAmount] = useState('');
    const [category, setCategory] = useState<Category | ''>('');
    const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
    const [selectedAccountId, setSelectedAccountId] = useState<string>(accounts[0]?.id || '');
    const [notes, setNotes] = useState('');
    const [isAutoCategorizing, setIsAutoCategorizing] = useState(false);
    const [isScanning, setIsScanning] = useState(false);
    const [scanError, setScanError] = useState<string | null>(null);
    const fileInputRef = useRef<HTMLInputElement>(null);

    const isUltra = userPlan === 'ultra';
    const isPro = userPlan === 'pro';
    const scanLimit = isUltra ? Infinity : isPro ? 50 : 1;
    const canScan = scanUsage < scanLimit;

    const expenseCategories = Object.values(Category).filter(c => c !== Category.INCOME && c !== Category.INVESTMENT);
    const incomeCategories = [Category.INCOME, Category.INVESTMENT, Category.OTHER];

    const compressImage = (file: File): Promise<string> => {
        return new Promise((resolve, reject) => {
            const reader = new FileReader();
            reader.readAsDataURL(file);
            reader.onload = (e) => {
                const img = new Image();
                img.src = e.target?.result as string;
                img.onload = () => {
                    const canvas = document.createElement('canvas');
                    const MAX_WIDTH = 800;
                    let width = img.width;
                    let height = img.height;
                    if (width > MAX_WIDTH) { height *= MAX_WIDTH / width; width = MAX_WIDTH; }
                    canvas.width = width;
                    canvas.height = height;
                    const ctx = canvas.getContext('2d');
                    if (ctx) {
                        ctx.drawImage(img, 0, 0, width, height);
                        resolve(canvas.toDataURL('image/jpeg', 0.7).split(',')[1]); 
                    } else { reject(new Error("Canvas failure")); }
                }
            };
        });
    };

    const handleMerchantBlur = async () => {
        if (!merchant || isAutoCategorizing || !isPro || category) return;
        setIsAutoCategorizing(true);
        try {
            const predicted = await categorizeTransaction(merchant, parseFloat(amount) || 0);
            if (Object.values(Category).includes(predicted as Category)) setCategory(predicted as Category);
        } finally { setIsAutoCategorizing(false); }
    };

    const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;
        setIsScanning(true);
        setScanError(null);
        try {
            const base64 = await compressImage(file);
            const result = await parseReceiptImage(base64);
            if (result) {
                setMerchant(result.merchant || '');
                setAmount(result.amount?.toString() || '');
                if (result.date) setDate(result.date);
                if (onIncrementScan) onIncrementScan();
            } else { setScanError("AI could not parse receipt. Entry required manually."); }
        } catch (err) { setScanError("Scanning protocol failure."); } finally { setIsScanning(false); }
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (!merchant || !amount || !category) return;
        if (type === TransactionType.EXPENSE && !selectedAccountId) return;
        const newTx: Transaction = {
            id: Date.now().toString(),
            date,
            merchant,
            amount: parseFloat(amount),
            category: category as Category,
            type,
            accountId: selectedAccountId || 'manual',
            notes
        };
        onAdd(newTx);
        onClose();
    };

    return (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/80 backdrop-blur-md animate-fade-in">
            <div className="bg-[#0f172a] border border-white/10 rounded-3xl w-full max-w-lg shadow-2xl overflow-hidden animate-slide-up flex flex-col max-h-[90vh]">
                <button onClick={onClose} className="absolute top-4 right-4 p-2 text-slate-400 hover:text-white z-10"><X className="w-6 h-6" /></button>
                <div className="p-8 border-b border-white/5 bg-gradient-to-r from-indigo-900/20 to-transparent">
                    <h3 className="text-2xl font-black text-white uppercase tracking-tighter">Log Financial Event</h3>
                    <p className="text-slate-500 text-[10px] font-bold uppercase tracking-[0.2em] mt-1">Archive spent or earned capital nodes.</p>
                </div>
                <div className="overflow-y-auto p-8 custom-scrollbar">
                    <form onSubmit={handleSubmit} className="space-y-6">
                        <div className="relative">
                            <input type="file" accept="image/*" ref={fileInputRef} onChange={handleFileChange} hidden />
                            <button 
                                type="button" 
                                onClick={() => fileInputRef.current?.click()}
                                disabled={!canScan || isScanning}
                                className={`w-full py-4 rounded-xl border-2 border-dashed transition-all flex items-center justify-center gap-3 ${isScanning ? 'border-indigo-500 bg-indigo-500/10' : !canScan ? 'opacity-50 grayscale cursor-not-allowed' : 'border-slate-700 bg-slate-800/30 hover:border-indigo-500 hover:text-white text-slate-400'}`}
                            >
                                {isScanning ? <Loader2 className="w-5 h-5 animate-spin text-indigo-400" /> : <Camera className="w-5 h-5" />}
                                <span className="text-xs font-black uppercase tracking-widest">{isScanning ? "Processing Optical Data..." : !canScan ? "Optical Limit Reached" : "Extract via Optical Scan"}</span>
                            </button>
                        </div>

                        <div className="relative flex bg-slate-950 rounded-2xl p-1.5 border border-white/10 h-14">
                            <div className={`absolute top-1.5 bottom-1.5 rounded-xl shadow-lg transition-all duration-300 ${type === TransactionType.EXPENSE ? 'left-1.5 w-[calc(50%-6px)] bg-rose-600' : 'left-[calc(50%+3px)] w-[calc(50%-6px)] bg-emerald-600'}`}></div>
                            <button type="button" onClick={() => setType(TransactionType.EXPENSE)} className={`relative z-10 flex-1 text-xs font-black uppercase tracking-widest ${type === TransactionType.EXPENSE ? 'text-white' : 'text-slate-500'}`}>Expense</button>
                            <button type="button" onClick={() => setType(TransactionType.INCOME)} className={`relative z-10 flex-1 text-xs font-black uppercase tracking-widest ${type === TransactionType.INCOME ? 'text-white' : 'text-slate-500'}`}>Income</button>
                        </div>

                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Magnitude</label>
                                <div className="relative mt-2">
                                    <DollarSign className="absolute left-3.5 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500" />
                                    <input required type="number" step="0.01" value={amount} onChange={e => setAmount(e.target.value)} className="w-full bg-slate-950/50 border border-white/10 rounded-xl p-3.5 pl-9 text-white focus:border-indigo-500 focus:outline-none font-mono text-lg" placeholder="0.00" />
                                </div>
                            </div>
                            <div>
                                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Timestamp</label>
                                <input required type="date" value={date} onChange={e => setDate(e.target.value)} className="w-full bg-slate-950/50 border border-white/10 rounded-xl p-3.5 text-white mt-2 focus:border-indigo-500 focus:outline-none text-sm [color-scheme:dark]" />
                            </div>
                        </div>

                        <div>
                            <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Merchant / Source</label>
                            <input required type="text" value={merchant} onChange={e => setMerchant(e.target.value)} onBlur={handleMerchantBlur} className="w-full bg-slate-950/50 border border-white/10 rounded-xl p-3.5 text-white mt-2 focus:border-indigo-500 focus:outline-none text-sm" placeholder="Starbucks, Apple, Salary..." />
                        </div>

                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Category</label>
                                <select required value={category} onChange={e => setCategory(e.target.value as Category)} className="w-full bg-slate-950/50 border border-white/10 rounded-xl p-3.5 text-white mt-2 focus:border-indigo-500 focus:outline-none text-xs appearance-none cursor-pointer">
                                    <option value="" disabled>Select Vector</option>
                                    {(type === TransactionType.INCOME ? incomeCategories : expenseCategories).map(c => <option key={c} value={c}>{c}</option>)}
                                </select>
                            </div>
                            <div>
                                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Linked Node</label>
                                <select value={selectedAccountId} onChange={(e) => setSelectedAccountId(e.target.value)} className="w-full bg-slate-950/50 border border-white/10 rounded-xl p-3.5 text-white mt-2 focus:border-indigo-500 focus:outline-none text-xs appearance-none cursor-pointer">
                                    <option value="manual">Manual / Cash</option>
                                    {accounts.map(acc => <option key={acc.id} value={acc.id}>{acc.name}</option>)}
                                </select>
                            </div>
                        </div>

                        <button type="submit" className="w-full py-4 bg-indigo-600 hover:bg-indigo-500 text-white font-black text-sm uppercase tracking-[0.2em] rounded-xl shadow-lg active:scale-95 transition-all">Synchronize Entry</button>
                    </form>
                </div>
            </div>
        </div>
    );
};

export default Transactions;

import React, { useState, useEffect, useCallback } from 'react';
import { Account, Budget, Goal, Transaction, UserPlan, ToastMessage, BotMode, Currency, Language, TransactionType } from './types';
import { ACCOUNTS, INITIAL_TRANSACTIONS, INITIAL_BUDGETS, INITIAL_GOALS, NAV_ITEMS, TRANSLATIONS } from './constants';
import Dashboard from './components/Dashboard';
import Transactions from './components/Transactions';
import Accounts from './components/Accounts';
import Insights from './components/Insights';
import Goals from './components/Goals';
import Plans from './components/Plans';
import Settings from './components/Settings';
import LandingPage from './components/LandingPage';
import ToastContainer from './components/Toast';
import FloatingAssistant from './components/FloatingAssistant';
import { Sparkles, LogOut, MessageCircle, Zap, Crown, AlertTriangle } from 'lucide-react';

// Hard-Token Protocol: Usage is now lifetime, not monthly.
const getLifetimeUsage = (key: string) => {
    try {
        const count = localStorage.getItem(key);
        return count ? parseInt(count) : 0;
    } catch (e) {
        return 0;
    }
};

const safeSetItem = (key: string, value: string) => {
    try {
        localStorage.setItem(key, value);
    } catch (e) {
        console.warn(`Storage quota exceeded for ${key}`);
    }
};

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');

  const [accounts, setAccounts] = useState<Account[]>(() => {
      const saved = localStorage.getItem('nova_accounts');
      return saved ? JSON.parse(saved) : ACCOUNTS;
  });
  const [transactions, setTransactions] = useState<Transaction[]>(() => {
      const saved = localStorage.getItem('nova_transactions');
      return saved ? JSON.parse(saved) : INITIAL_TRANSACTIONS;
  });
  const [budgets, setBudgets] = useState<Budget[]>(() => {
      const saved = localStorage.getItem('nova_budgets');
      return saved ? JSON.parse(saved) : INITIAL_BUDGETS;
  });
  const [goals, setGoals] = useState<Goal[]>(() => {
      const saved = localStorage.getItem('nova_goals');
      return saved ? JSON.parse(saved) : INITIAL_GOALS;
  });

  const [userPlan, setUserPlan] = useState<UserPlan>(() => localStorage.getItem('nova_user_plan') as UserPlan || 'free');

  // Usage tracking - Now strictly numerical (Lifetime)
  const [insightUsage, setInsightUsage] = useState(() => getLifetimeUsage('nova_insight_usage_lifetime'));
  const [scanUsage, setScanUsage] = useState(() => getLifetimeUsage('nova_scan_usage_lifetime'));
  const [negotiationUsage, setNegotiationUsage] = useState(() => getLifetimeUsage('nova_negotiation_usage_lifetime'));

  const [isLoggedIn, setIsLoggedIn] = useState(() => localStorage.getItem('nova_auth_token') !== null);
  const [toasts, setToasts] = useState<ToastMessage[]>([]);
  const [botMode, setBotMode] = useState<BotMode>(() => (localStorage.getItem('nova_bot_mode') as BotMode) || 'ruthless');
  const [pendingChatQuery, setPendingChatQuery] = useState<string | null>(null);

  const [userName, setUserName] = useState(() => localStorage.getItem('nova_user_name') || 'Pilot');
  const [userEmail, setUserEmail] = useState(() => localStorage.getItem('nova_user_email') || 'pilot@nova.io');
  const [userAvatar, setUserAvatar] = useState(() => localStorage.getItem('nova_user_avatar') || '');
  const [userAvatarZoom, setUserAvatarZoom] = useState(1);
  const [userAvatarPos, setUserAvatarPos] = useState({ x: 0, y: 0 });
  const [userBorder, setUserBorder] = useState('default');
  const [userBackground, setUserBackground] = useState(() => localStorage.getItem('nova_user_bg') || '');

  const [currency, setCurrency] = useState<Currency>(() => (localStorage.getItem('nova_currency') as Currency) || 'USD');
  const [language, setLanguage] = useState<Language>(() => (localStorage.getItem('nova_language') as Language) || 'en');

  // Persistence
  useEffect(() => safeSetItem('nova_accounts', JSON.stringify(accounts)), [accounts]);
  useEffect(() => safeSetItem('nova_transactions', JSON.stringify(transactions)), [transactions]);
  useEffect(() => safeSetItem('nova_budgets', JSON.stringify(budgets)), [budgets]);
  useEffect(() => safeSetItem('nova_goals', JSON.stringify(goals)), [goals]);
  useEffect(() => safeSetItem('nova_user_plan', userPlan), [userPlan]);
  useEffect(() => safeSetItem('nova_currency', currency), [currency]);
  useEffect(() => safeSetItem('nova_language', language), [language]);
  useEffect(() => safeSetItem('nova_bot_mode', botMode), [botMode]);
  useEffect(() => safeSetItem('nova_user_bg', userBackground), [userBackground]);

  // Save Lifetime Usage
  useEffect(() => safeSetItem('nova_insight_usage_lifetime', insightUsage.toString()), [insightUsage]);
  useEffect(() => safeSetItem('nova_scan_usage_lifetime', scanUsage.toString()), [scanUsage]);
  useEffect(() => safeSetItem('nova_negotiation_usage_lifetime', negotiationUsage.toString()), [negotiationUsage]);

  const addToast = useCallback((message: string, type: 'success' | 'error' | 'info' = 'info') => {
    setToasts(prev => [...prev, { id: Date.now().toString(), message, type }]);
  }, []);

  const removeToast = (id: string) => {
    setToasts(prev => prev.filter(t => t.id !== id));
  };

  const formatCurrency = (amount: number) => {
    const isNoDecimal = currency === 'VND' || currency === 'JPY';
    return new Intl.NumberFormat(language === 'vi' ? 'vi-VN' : 'en-US', { 
        style: 'currency', 
        currency: currency,
        minimumFractionDigits: isNoDecimal ? 0 : 2,
        maximumFractionDigits: isNoDecimal ? 0 : 2,
    }).format(amount);
  };

  const reconcileBalance = (tx: Transaction, direction: 'add' | 'delete') => {
      if (tx.accountId === 'manual') return;
      setAccounts(prev => prev.map(acc => {
          if (acc.id === tx.accountId) {
              const isIncome = tx.type === TransactionType.INCOME;
              let change = tx.amount;
              if (direction === 'add') {
                  change = isIncome ? change : -change;
              } else {
                  change = isIncome ? -change : change;
              }
              return { ...acc, balance: acc.balance + change };
          }
          return acc;
      }));
  };

  const handleAddTransaction = (t: Transaction) => {
      setTransactions(prev => [t, ...prev]);
      reconcileBalance(t, 'add');
      addToast('Entry archived. Balance synchronized.', 'success');
  };

  const handleDeleteTransaction = (id: string) => {
      const tx = transactions.find(t => t.id === id);
      if (tx) {
          reconcileBalance(tx, 'delete');
          setTransactions(prev => prev.filter(t => t.id !== id));
          addToast('Entry purged. Balance reconciled.', 'info');
      }
  };

  const handleLogin = (name: string) => {
    setIsLoggedIn(true);
    setUserName(name);
    localStorage.setItem('nova_user_name', name);
  };

  const handleLogout = () => {
    localStorage.removeItem('nova_auth_token');
    setIsLoggedIn(false);
  };

  const handleUpdateProfile = (name: string, email: string, avatar: string, zoom: number, pos: { x: number; y: number }, border: string) => {
      setUserName(name);
      localStorage.setItem('nova_user_name', name);
      setUserEmail(email);
      localStorage.setItem('nova_user_email', email);
      setUserAvatar(avatar);
      safeSetItem('nova_user_avatar', avatar);
      setUserAvatarZoom(zoom);
      setUserAvatarPos(pos);
      setUserBorder(border);
  };

  const handleClearData = () => {
      localStorage.clear();
      window.location.reload();
  };

  const handleImportData = (file: File) => {
      const reader = new FileReader();
      reader.onload = (e) => {
          try {
              const data = JSON.parse(e.target?.result as string);
              if (data.accounts) setAccounts(data.accounts);
              if (data.transactions) setTransactions(data.transactions);
              if (data.budgets) setBudgets(data.budgets);
              if (data.goals) setGoals(data.goals);
              addToast('Vault protocol restored.', 'success');
          } catch (err) {
              addToast('Failed to parse data capsule.', 'error');
          }
      };
      reader.readAsText(file);
  };

  const handleExportData = () => {
      const data = { accounts, transactions, budgets, goals, userPlan };
      const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `nova_backup_${new Date().toISOString().split('T')[0]}.json`;
      a.click();
  };

  const handleAskCoach = (msg: string) => {
      setPendingChatQuery(msg);
      setActiveTab('insights');
  };

  const branding = (userPlan === 'ultra' ? {
      icon: <Crown className="w-6 h-6 text-white" />,
      bg: 'bg-gradient-to-tr from-indigo-600 via-purple-600 to-indigo-600',
      label: 'ELITE SYSTEM',
      shadow: 'shadow-indigo-500/40'
  } : userPlan === 'pro' ? {
      icon: <Zap className="w-6 h-6 text-white" />,
      bg: 'bg-gradient-to-tr from-amber-500 to-orange-500',
      label: 'PRO SYSTEM',
      shadow: 'shadow-amber-500/40'
  } : {
      icon: <Sparkles className="w-6 h-6 text-white" />,
      bg: 'bg-gradient-to-tr from-indigo-600 to-violet-600',
      label: 'CORE SYSTEM',
      shadow: 'shadow-indigo-500/20'
  });

  const isApiConfigured = !!process.env.API_KEY;

  if (!isLoggedIn) {
    return <LandingPage onLoginSuccess={handleLogin} />;
  }

  return (
    <div className="flex h-screen bg-[#020617] text-slate-100 font-sans selection:bg-indigo-500/30 overflow-hidden relative">
      {!isApiConfigured && (
          <div className="fixed top-0 left-0 w-full bg-rose-600 text-white text-[10px] font-black py-2 px-4 text-center z-[100] flex items-center justify-center gap-2 shadow-lg uppercase tracking-widest">
              <AlertTriangle className="w-4 h-4" />
              AI Core Offline: Missing API Key. Manual tracking active.
          </div>
      )}

      {userBackground && (
          <div className="absolute inset-0 z-0">
               <img src={userBackground} alt="bg" className="w-full h-full object-cover opacity-40 blur-sm" />
               <div className="absolute inset-0 bg-[#020617]/70"></div>
          </div>
      )}

      {!userBackground && (
          <div className="fixed inset-0 z-0 pointer-events-none bg-[radial-gradient(at_0%_0%,hsla(253,16%,7%,1)_0,transparent_50%),radial-gradient(at_50%_0%,hsla(225,39%,30%,0.3)_0,transparent_50%),radial-gradient(at_100%_0%,hsla(339,49%,30%,0.3)_0,transparent_50%)]">
             <div className="absolute top-[-10%] left-[-10%] w-[50%] h-[50%] bg-indigo-900/10 rounded-full blur-[120px] animate-pulse-slow"></div>
             <div className="absolute bottom-[-10%] right-[-10%] w-[50%] h-[50%] bg-purple-900/10 rounded-full blur-[120px] animate-pulse-slow" style={{ animationDelay: '1s' }}></div>
          </div>
      )}

      <FloatingAssistant 
          transactions={transactions}
          budgets={budgets}
          userPlan={userPlan}
          isVisible={activeTab !== 'insights'}
          onOpenChat={handleAskCoach}
      />

      <aside className="hidden md:flex flex-col w-64 p-4 z-20 bg-slate-950/40 backdrop-blur-md border-r border-white/5 relative">
        <div className="flex items-center gap-3 px-4 py-3 mb-8">
            <div className={`w-10 h-10 rounded-xl flex items-center justify-center shadow-lg ring-1 ring-white/10 ${branding.bg} ${branding.shadow}`}>
                {branding.icon}
            </div>
            <div>
                <h1 className="text-xl font-bold tracking-tight text-white">Nova AI</h1>
                <p className={`text-[10px] font-bold uppercase tracking-wider ${userPlan === 'ultra' ? 'text-purple-400' : userPlan === 'pro' ? 'text-amber-400' : 'text-slate-500'}`}>
                    {branding.label}
                </p>
            </div>
        </div>

        <nav className="flex-1 space-y-1">
            {NAV_ITEMS.filter(item => !(userPlan === 'ultra' && item.id === 'plans')).map((item) => {
                const isActive = activeTab === item.id;
                const label = TRANSLATIONS[language]?.[item.id as keyof typeof TRANSLATIONS['en']] || item.label;
                return (
                    <button
                        key={item.id}
                        onClick={() => setActiveTab(item.id)}
                        className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold transition-all duration-300 group ${isActive ? 'bg-indigo-600/10 text-indigo-400 shadow-[0_0_20px_rgba(99,102,241,0.15)] ring-1 ring-indigo-500/20' : 'text-slate-400 hover:text-white hover:bg-white/5'}`}
                    >
                        <item.icon className={`w-5 h-5 transition-colors ${isActive ? 'text-indigo-400' : 'text-slate-500 group-hover:text-white'}`} />
                        {label}
                    </button>
                );
            })}
        </nav>

        <div className="mt-auto pt-6 border-t border-white/5">
             <button onClick={() => setActiveTab('settings')} className="w-full text-left px-4 py-4 rounded-2xl bg-slate-900/50 border border-white/5 flex items-center gap-3 mb-4 hover:bg-slate-800 transition-colors group">
                 <div className="w-10 h-10 rounded-full bg-indigo-500 flex items-center justify-center text-white overflow-hidden relative border border-white/10 shadow-inner">
                     {userAvatar ? (
                         <img src={userAvatar} className="w-full h-full object-cover" alt="User" style={{ transform: `scale(${userAvatarZoom}) translate(${userAvatarPos.x}px, ${userAvatarPos.y}px)` }} />
                     ) : (
                         <span className="font-bold text-lg">{userName.charAt(0)}</span>
                     )}
                 </div>
                 <div className="overflow-hidden">
                     <h4 className="font-bold text-white text-sm truncate group-hover:text-indigo-400 transition-colors">{userName}</h4>
                     <p className="text-[10px] text-slate-500 truncate font-bold uppercase tracking-widest">{userPlan} tier</p>
                 </div>
             </button>
             <button onClick={handleLogout} className="w-full flex items-center gap-2 px-4 py-2 text-xs font-bold text-slate-500 hover:text-rose-400 transition-colors uppercase tracking-widest">
                 <LogOut className="w-4 h-4" /> {TRANSLATIONS[language]?.signOut || 'Sign Out'}
             </button>
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 z-10 relative overflow-hidden">
        <div className="flex-1 overflow-y-auto p-4 md:p-8 pb-24 md:pb-8 custom-scrollbar">
            {activeTab === 'dashboard' && (
                <Dashboard 
                    accounts={accounts} 
                    transactions={transactions} 
                    onNavigate={setActiveTab} 
                    onAddAccount={() => setActiveTab('accounts')}
                    onAddTransaction={() => setActiveTab('transactions')}
                    onAddGoal={() => setActiveTab('goals')}
                    formatCurrency={formatCurrency}
                    userPlan={userPlan}
                    onAskCoach={handleAskCoach}
                    negotiationUsage={negotiationUsage}
                    onIncrementNegotiation={() => setNegotiationUsage(prev => prev + 1)}
                />
            )}

            {activeTab === 'transactions' && (
                <Transactions 
                    transactions={transactions} 
                    accounts={accounts}
                    onDelete={handleDeleteTransaction}
                    onAdd={handleAddTransaction}
                    formatCurrency={formatCurrency}
                    onNavigateToAccounts={() => setActiveTab('accounts')}
                    userPlan={userPlan}
                    scanUsage={scanUsage}
                    onIncrementScan={() => setScanUsage(prev => prev + 1)}
                    currency={currency}
                />
            )}

            {activeTab === 'accounts' && (
                <Accounts 
                    accounts={accounts} 
                    budgets={budgets} 
                    transactions={transactions} 
                    userPlan={userPlan}
                    onAdd={(acc) => { setAccounts(prev => [...prev, acc]); addToast('Account bridged.', 'success'); }}
                    onUpdate={(acc) => { setAccounts(prev => prev.map(a => a.id === acc.id ? acc : a)); addToast('Account updated.', 'success'); }}
                    onDelete={(id) => { 
                        setAccounts(prev => prev.filter(a => a.id !== id));
                        setTransactions(prev => prev.map(t => t.accountId === id ? { ...t, accountId: 'manual' } : t));
                        addToast('Account disconnected. History preserved.', 'info'); 
                    }}
                    formatCurrency={formatCurrency}
                    userName={userName}
                    userAvatar={userAvatar}
                    userAvatarZoom={userAvatarZoom}
                    userAvatarPos={userAvatarPos}
                    userBorder={userBorder}
                    onNavigate={setActiveTab}
                />
            )}

            {activeTab === 'insights' && (
                <Insights 
                    transactions={transactions} 
                    userPlan={userPlan} 
                    onUpgradeClick={() => setActiveTab('plans')}
                    formatCurrency={formatCurrency}
                    insightUsage={insightUsage}
                    onIncrementUsage={() => setInsightUsage(prev => prev + 1)}
                    onApplyBudgets={(newBudgets) => {
                         const existingCats = new Set(budgets.map(b => b.category));
                         const toAdd = newBudgets.filter(b => !existingCats.has(b.category));
                         setBudgets(prev => [...prev, ...toAdd]);
                         addToast(`Applied ${toAdd.length} AI limits.`, 'success');
                    }}
                    initialPrompt={pendingChatQuery}
                    onPromptHandled={() => setPendingChatQuery(null)}
                    botMode={botMode}
                />
            )}

            {activeTab === 'goals' && (
                <Goals 
                    goals={goals} 
                    budgets={budgets} 
                    transactions={transactions}
                    onAddGoal={(g) => { setGoals(prev => [...prev, g]); addToast('Goal deployed.', 'success'); }}
                    onUpdateGoal={(g) => { setGoals(prev => prev.map(goal => goal.id === g.id ? g : goal)); addToast('Goal updated.', 'success'); }}
                    onAddBudget={(b) => { setBudgets(prev => [...prev, b]); addToast('Limit set.', 'success'); }}
                    onDeleteBudget={(id) => { setBudgets(prev => prev.filter(b => b.id !== id)); addToast('Limit removed.', 'info'); }}
                    formatCurrency={formatCurrency} 
                />
            )}

            {activeTab === 'plans' && userPlan !== 'ultra' && (
                <Plans 
                    currentPlan={userPlan} 
                    onUpgrade={(plan) => { setUserPlan(plan); addToast(`Plan upgraded to ${plan.toUpperCase()}.`, 'success'); }}
                    onDowngrade={() => { setUserPlan('free'); addToast('Plan reset to Starter.', 'info'); }}
                />
            )}

            {activeTab === 'settings' && (
                <Settings 
                    userName={userName}
                    userEmail={userEmail}
                    userAvatar={userAvatar}
                    userAvatarZoom={userAvatarZoom}
                    userAvatarPos={userAvatarPos}
                    userBorder={userBorder}
                    userBackground={userBackground}
                    onUpdateBackground={setUserBackground}
                    userPlan={userPlan}
                    onUpdateProfile={handleUpdateProfile}
                    addToast={addToast}
                    onExportData={handleExportData}
                    onImportData={handleImportData}
                    onClearData={handleClearData}
                    language={language}
                    onUpdateLanguage={setLanguage}
                    currency={currency}
                    onUpdateCurrency={setCurrency}
                    botMode={botMode}
                    onUpdateBotMode={setBotMode}
                    onDowngrade={() => { setUserPlan('free'); addToast('Plan downgraded.', 'info'); }}
                />
            )}
        </div>
      </main>

      <ToastContainer toasts={toasts} onRemove={removeToast} />
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { Transaction, AIAnalysisResponse, ChatMessage, UserPlan, TransactionType, Budget, BotMode } from '../types';
import { analyzeFinancialData, chatWithFinancialCoach } from '../services/geminiService';
import { RefreshCcw, CheckCircle, AlertTriangle, ShieldAlert, Info, TrendingUp, Bot, User, BrainCircuit, Lightbulb, Send, Lock, Sparkles, RefreshCw, Flame, ArrowRight, Zap } from 'lucide-react';

interface InsightsProps {
  transactions: Transaction[];
  userPlan: UserPlan;
  onUpgradeClick: () => void;
  formatCurrency: (amount: number) => string;
  initialPrompt?: string | null; 
  onPromptHandled?: () => void; 
  onApplyBudgets?: (budgets: Budget[]) => void; 
  insightUsage: number; 
  onIncrementUsage: () => void; 
  botMode: BotMode; 
}

const Insights: React.FC<InsightsProps> = ({ transactions, userPlan, onUpgradeClick, formatCurrency, initialPrompt, onPromptHandled, onApplyBudgets, insightUsage, onIncrementUsage, botMode }) => {
  const [analysis, setAnalysis] = useState<AIAnalysisResponse | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [chatInput, setChatInput] = useState('');
  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([
    { id: '1', role: 'assistant', content: 'Identity confirmed. I am Nova. Analyze your spending or ask for strategic direction. Remember: AI compute tokens are limited per your tier.', timestamp: new Date() }
  ]);
  const [chatLoading, setChatLoading] = useState(false);
  const chatEndRef = useRef<HTMLDivElement>(null);

  // Hard-Token Limits (Lifetime)
  const FREE_LIMIT = 1;
  const PRO_LIMIT = 3;
  const ELITE_LIMIT = 5;

  const currentLimit = userPlan === 'ultra' ? ELITE_LIMIT : userPlan === 'pro' ? PRO_LIMIT : FREE_LIMIT;
  const isLocked = insightUsage >= currentLimit;

  const burnoutData = useMemo(() => {
    const expenseMap = new Map<string, number>();
    transactions
        .filter(t => t.type === TransactionType.EXPENSE)
        .forEach(t => {
            expenseMap.set(t.category, (expenseMap.get(t.category) || 0) + t.amount);
        });

    let maxCat = '';
    let maxAmount = 0;
    expenseMap.forEach((val, key) => {
        if (val > maxAmount) {
            maxAmount = val;
            maxCat = key;
        }
    });
    return { category: maxCat, amount: maxAmount };
  }, [transactions]);

  const runAnalysis = async () => {
    if (isLocked) return;
    setLoading(true);
    setError(null);
    onIncrementUsage();
    try {
      const result = await analyzeFinancialData(transactions);
      if (result) setAnalysis(result);
      else setError("Analysis core busy.");
    } catch (e) {
      setError("Compute connection severed.");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [chatHistory, chatLoading]);

  useEffect(() => {
      if (!isLocked && initialPrompt && !chatLoading) {
          handleSendMessage(null, initialPrompt);
          if (onPromptHandled) onPromptHandled();
      }
  }, [initialPrompt, isLocked]);

  const handleSendMessage = async (e: React.FormEvent | null, promptOverride?: string) => {
    if (e) e.preventDefault();
    const content = promptOverride || chatInput;
    if (!content.trim() || isLocked) return;

    onIncrementUsage();
    const userMsg: ChatMessage = { id: Date.now().toString(), role: 'user', content: content, timestamp: new Date() };
    setChatHistory(prev => [...prev, userMsg]);
    setChatInput('');
    setChatLoading(true);

    const responseText = await chatWithFinancialCoach(userMsg.content, transactions, botMode);
    const aiMsg: ChatMessage = { id: (Date.now() + 1).toString(), role: 'assistant', content: responseText, timestamp: new Date() };
    setChatHistory(prev => [...prev, aiMsg]);
    setChatLoading(false);
  };

  const getColorClass = (type: string) => {
    switch (type) {
        case 'success': return 'bg-emerald-500/10 border-emerald-500/20 text-emerald-100';
        case 'warning': return 'bg-amber-500/10 border-amber-500/20 text-amber-100';
        case 'critical': return 'bg-rose-500/10 border-rose-500/20 text-rose-100';
        default: return 'bg-blue-500/10 border-blue-500/20 text-blue-100';
    }
  };

  return (
    <div className="relative h-[calc(100vh-8rem)]">
      {isLocked && (
        <div className="absolute inset-0 z-50 flex items-center justify-center bg-slate-950/80 backdrop-blur-xl rounded-[2rem] border border-white/10">
            <div className="text-center p-8 max-w-md animate-slide-up">
                <div className="w-20 h-20 rounded-3xl bg-slate-800 flex items-center justify-center mx-auto mb-6 shadow-2xl border border-white/10"><Lock className="w-10 h-10 text-slate-500" /></div>
                <h2 className="text-3xl font-bold text-white mb-3">Tokens Exhausted</h2>
                <p className="text-slate-400 mb-8 leading-relaxed font-medium">
                    Your lifetime AI allocation for the <b>{userPlan.toUpperCase()}</b> tier has been reached ({currentLimit}/{currentLimit}).
                </p>
                {userPlan !== 'ultra' && (
                    <button onClick={onUpgradeClick} className="w-full py-4 bg-indigo-600 text-white font-black rounded-xl shadow-xl active:scale-95 transition-all flex items-center justify-center gap-2 group uppercase tracking-[0.2em] text-xs">
                        <Sparkles className="w-5 h-5" /> Expand Allocation
                    </button>
                )}
            </div>
        </div>
      )}

      <div className={`grid grid-cols-1 lg:grid-cols-3 gap-8 pb-10 h-full transition-all duration-500 ${isLocked ? 'blur-md opacity-50 pointer-events-none overflow-hidden' : ''}`}>
        <div className="lg:col-span-2 overflow-y-auto custom-scrollbar space-y-8 pr-2">
            <div className="flex justify-between items-center bg-slate-900/60 p-8 rounded-3xl border border-white/10 backdrop-blur-md">
                <div>
                    <h2 className="text-2xl font-bold text-white flex items-center gap-3"><BrainCircuit className="w-8 h-8 text-indigo-400" />Financial Wellness</h2>
                    <div className="mt-3 inline-flex items-center gap-2 px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest bg-slate-800 border border-white/10 text-slate-400">
                         {userPlan.toUpperCase()} LIFETIME TOKENS: {insightUsage}/{currentLimit}
                    </div>
                </div>
                <button onClick={runAnalysis} disabled={loading} className="p-4 bg-slate-800/80 hover:bg-indigo-600 rounded-2xl transition-all border border-white/10 group shadow-lg active:scale-95"><RefreshCcw className={`w-5 h-5 text-slate-300 group-hover:text-white ${loading ? 'animate-spin' : ''}`} /></button>
            </div>

            {loading && <div className="h-48 glass-card rounded-3xl animate-pulse bg-slate-800/30"></div>}

            {analysis && !loading && (
            <div className="animate-fade-in space-y-8">
                <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                    <div className="glass-card p-6 rounded-3xl border border-white/10">
                        <h3 className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-4">Risk Matrix</h3>
                        <div className="text-4xl font-black text-white">{analysis.risk_score}</div>
                    </div>
                    <div className="glass-card p-6 rounded-3xl border border-white/10">
                         <h3 className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-4">Trajectory</h3>
                         <div className="text-4xl font-black text-white">{formatCurrency(analysis.predicted_spend_next_month).replace(/\.00$/, '')}</div>
                    </div>
                    <div className="glass-card p-6 rounded-3xl border border-white/10 bg-rose-500/5">
                        <h3 className="text-[10px] font-bold text-rose-400 uppercase tracking-widest mb-4">Burnout</h3>
                        <div className="text-xl font-bold text-white truncate">{burnoutData.category}</div>
                    </div>
                </div>

                <div className="space-y-4">
                    {analysis.insights.map((insight, idx) => (
                        <div key={idx} className={`p-6 rounded-2xl border flex gap-5 ${getColorClass(insight.type)}`}>
                            <div>
                                <h4 className="font-bold text-base mb-1">{insight.title}</h4>
                                <p className="text-sm opacity-80 leading-relaxed">{insight.description}</p>
                            </div>
                        </div>
                    ))}
                </div>
            </div>
            )}
        </div>

        <div className="glass-card rounded-[2rem] border border-white/10 flex flex-col h-full overflow-hidden shadow-2xl relative">
            <div className="p-5 border-b border-white/5 bg-slate-950/40 backdrop-blur-xl flex items-center justify-between">
                <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded-xl bg-indigo-600 flex items-center justify-center shadow-lg"><Bot className="w-6 h-6 text-white" /></div>
                    <div>
                        <h3 className="font-bold text-white text-sm tracking-tight">Nova Assistant</h3>
                        <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">Token Logic Enabled</p>
                    </div>
                </div>
            </div>

            <div className="flex-1 overflow-y-auto p-5 space-y-6 custom-scrollbar bg-slate-950/20">
                {chatHistory.map((msg) => (
                    <div key={msg.id} className={`flex gap-3 ${msg.role === 'user' ? 'flex-row-reverse' : 'flex-row'} animate-slide-up`}>
                        <div className={`max-w-[80%] p-4 text-sm leading-relaxed ${msg.role === 'user' ? 'bg-indigo-600 text-white rounded-2xl rounded-tr-sm shadow-indigo-500/20' : 'bg-slate-800 text-slate-200 rounded-2xl rounded-tl-sm border border-white/5'}`}>{msg.content}</div>
                    </div>
                ))}
                {chatLoading && <div className="text-xs text-slate-500 animate-pulse"> Nova is thinking...</div>}
                <div ref={chatEndRef} />
            </div>

            <div className="p-5 border-t border-white/5 bg-slate-900/60">
                <form onSubmit={(e) => handleSendMessage(e)} className="relative">
                    <input type="text" value={chatInput} onChange={(e) => setChatInput(e.target.value)} placeholder="Enter command..." className="w-full bg-slate-950 border border-white/10 text-white text-sm rounded-xl px-5 py-4 focus:outline-none focus:border-indigo-500 transition-all shadow-inner" />
                    <button type="submit" disabled={!chatInput.trim() || chatLoading} className="absolute right-2 top-1/2 -translate-y-1/2 p-2.5 bg-indigo-600 hover:bg-indigo-500 rounded-lg text-white disabled:opacity-50"><Send className="w-4 h-4" /></button>
                </form>
            </div>
        </div>
      </div>
    </div>
  );
};

export default Insights;

import React, { useState, useRef, useEffect } from 'react';
import { Transaction, TransactionType, Category, Account, UserPlan, Currency } from '../types';
import { Search, ArrowUpCircle, ArrowDownCircle, Filter, Calendar, Trash2, Tag, Plus, X, Check, DollarSign, Wallet, FileText, Sparkles, Loader2, StickyNote, ArrowUp, ArrowDown, Camera, AlertCircle, ScanLine } from 'lucide-react';
import { categorizeTransaction, parseReceiptImage } from '../services/geminiService';

interface TransactionsProps {
  transactions: Transaction[];
  accounts?: Account[]; 
  onDelete?: (id: string) => void;
  onAdd?: (transaction: Transaction) => void;
  formatCurrency: (amount: number) => string;
  onNavigateToAccounts?: () => void;
  userPlan?: UserPlan;
  scanUsage?: number;
  onIncrementScan?: () => void;
  currency?: Currency;
}

const Transactions: React.FC<TransactionsProps> = ({ transactions, accounts = [], onDelete, onAdd, formatCurrency, onNavigateToAccounts, userPlan, scanUsage = 0, onIncrementScan, currency = 'USD' }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [debouncedSearchTerm, setDebouncedSearchTerm] = useState('');
  const [filterType, setFilterType] = useState<TransactionType | 'ALL'>('ALL');
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);

  useEffect(() => {
    const handler = setTimeout(() => {
      setDebouncedSearchTerm(searchTerm);
    }, 300);
    return () => clearTimeout(handler);
  }, [searchTerm]);

  const filtered = transactions.filter(t => {
    const matchesSearch = t.merchant.toLowerCase().includes(debouncedSearchTerm.toLowerCase()) || 
                          t.category.toLowerCase().includes(debouncedSearchTerm.toLowerCase()) ||
                          (t.notes && t.notes.toLowerCase().includes(debouncedSearchTerm.toLowerCase()));
    const matchesType = filterType === 'ALL' || t.type === filterType;
    return matchesSearch && matchesType;
  });

  const getAccountName = (id: string) => {
    const acc = accounts.find(a => a.id === id);
    if (!acc && id === 'manual') return 'Cash / Manual';
    return acc ? acc.name : 'Unknown Account';
  };

  return (
    <div className="flex flex-col h-full animate-slide-up space-y-6 relative">
      <div className="glass-card p-4 rounded-3xl flex flex-col md:flex-row justify-between items-center gap-4">
          <div className="flex items-center gap-4 w-full md:w-auto px-2">
              <h2 className="text-lg font-bold text-white">Recent Activity</h2>
              <span className="px-3 py-1 rounded-full bg-slate-800/60 border border-white/10 text-xs font-bold text-indigo-300 shadow-inner">{filtered.length}</span>
          </div>

          <div className="flex flex-col md:flex-row gap-3 w-full md:w-auto">
            <div className="relative group flex-1 md:flex-initial">
              <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500 group-focus-within:text-indigo-400 transition-colors" />
              <input
                type="text"
                placeholder="Search ledger..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full bg-slate-950/50 border border-white/10 rounded-2xl pl-10 pr-4 py-3 text-sm text-white focus:outline-none focus:border-indigo-500/50 transition-all md:w-64 placeholder:text-slate-600 shadow-inner"
              />
            </div>

            <div className="flex gap-3">
                <div className="relative">
                    <select
                    value={filterType}
                    onChange={(e) => setFilterType(e.target.value as any)}
                    className="appearance-none bg-slate-950/50 border border-white/10 rounded-2xl pl-4 pr-10 py-3 text-sm text-white focus:outline-none focus:border-indigo-500/50 hover:bg-slate-900/80 transition-all cursor-pointer shadow-inner font-medium h-full"
                    >
                    <option value="ALL">All Types</option>
                    <option value={TransactionType.INCOME}>Income</option>
                    <option value={TransactionType.EXPENSE}>Expense</option>
                    </select>
                    <Filter className="absolute right-3.5 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-slate-500 pointer-events-none" />
                </div>

                <button 
                    onClick={() => setIsAddModalOpen(true)}
                    className="bg-indigo-600 hover:bg-indigo-500 text-white px-4 py-3 rounded-2xl font-bold text-sm shadow-lg shadow-indigo-500/20 active:scale-95 transition-all flex items-center gap-2"
                >
                    <Plus className="w-4 h-4" /> <span className="hidden md:inline">Log Event</span>
                </button>
            </div>
          </div>
      </div>

      <div className="flex-1 overflow-auto custom-scrollbar space-y-3 pb-4">
          <div className="hidden md:grid grid-cols-12 px-6 py-2 text-[10px] font-black text-slate-500 uppercase tracking-[0.2em]">
              <div className="col-span-2">Timestamp</div>
              <div className="col-span-4">Node / Merchant</div>
              <div className="col-span-3">Vector / Account</div>
              <div className="col-span-3 text-right">Delta</div>
          </div>

          {filtered.map(t => (
            <div 
                key={t.id} 
                className="group glass-card rounded-2xl p-4 md:px-6 md:py-4 flex flex-col md:grid md:grid-cols-12 items-center gap-4 transition-all duration-300 hover:bg-slate-800/40 hover:border-indigo-500/20"
            >
                <div className="w-full md:col-span-2 flex items-center gap-3 text-slate-400 order-2 md:order-1 justify-between md:justify-start">
                    <div className="flex items-center gap-2">
                         <div className="p-2 rounded-lg bg-slate-800/50 border border-white/5">
                            <Calendar className="w-4 h-4 opacity-70" />
                         </div>
                         <span className="text-xs font-bold uppercase tracking-tight">{new Date(t.date).toLocaleDateString('en-US', { month: 'short', day: 'numeric' })}</span>
                    </div>
                     <span className={`md:hidden text-lg font-black tracking-tighter ${t.type === TransactionType.INCOME ? 'text-emerald-400' : 'text-white'}`}>
                        {t.type === TransactionType.INCOME ? '+' : ''}
                        {formatCurrency(t.amount)}
                     </span>
                </div>

                <div className="w-full md:col-span-4 flex items-center gap-4 order-1 md:order-2">
                     <div className={`p-2.5 rounded-full border border-white/5 shadow-sm shrink-0 transition-colors ${t.type === TransactionType.INCOME ? 'bg-emerald-500/10' : 'bg-rose-500/10'}`}>
                        {t.type === TransactionType.INCOME ? 
                        <ArrowUpCircle className="w-5 h-5 text-emerald-500" /> : 
                        <ArrowDownCircle className="w-5 h-5 text-rose-500" />
                        }
                    </div>
                    <div className="min-w-0">
                        <span className="block text-base font-bold text-slate-100 group-hover:text-white truncate capitalize">{t.merchant}</span>
                        {t.notes && (
                            <div className="flex items-center gap-1 mt-0.5">
                                <StickyNote className="w-3 h-3 text-slate-600" />
                                <span className="text-[10px] text-slate-500 truncate max-w-[200px]">{t.notes}</span>
                            </div>
                        )}
                    </div>
                </div>

                <div className="hidden md:block col-span-3 order-3">
                   <div className="flex flex-col gap-1.5 items-start">
                        <span className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-[10px] font-black uppercase border shadow-sm backdrop-blur-md ${
                            t.category === Category.FOOD ? 'bg-orange-500/10 border-orange-500/20 text-orange-400' :
                            t.category === Category.SHOPPING ? 'bg-blue-500/10 border-blue-500/20 text-blue-400' :
                            t.category === Category.TRANSPORT ? 'bg-purple-500/10 border-purple-500/20 text-purple-400' :
                            t.category === Category.INCOME ? 'bg-emerald-500/10 border-emerald-500/20 text-emerald-400' :
                            t.category === Category.SUBSCRIPTION ? 'bg-cyan-500/10 border-cyan-500/20 text-cyan-400' :
                            'bg-slate-800/50 border-slate-700 text-slate-400'
                        }`}>
                            {t.category}
                        </span>
                        <span className="inline-flex items-center gap-1.5 px-2 py-0.5 rounded-md text-[9px] font-black text-slate-500 border border-white/5 bg-slate-900/50 uppercase tracking-widest">
                            <Wallet className="w-2.5 h-2.5" />
                            {getAccountName(t.accountId)}
                        </span>
                   </div>
                </div>

                <div className="hidden md:flex col-span-3 order-4 justify-end items-center gap-4">
                     <span className={`text-xl font-black tracking-tighter ${t.type === TransactionType.INCOME ? 'text-emerald-400 drop-shadow-[0_0_8px_rgba(16,185,129,0.3)]' : 'text-white'}`}>
                        {t.type === TransactionType.INCOME ? '+' : ''}
                        {formatCurrency(t.amount)}
                    </span>
                    {onDelete && (
                      <button 
                        onClick={(e) => { e.stopPropagation(); onDelete(t.id); }}
                        className="p-2 text-slate-600 hover:text-rose-500 hover:bg-rose-500/10 rounded-lg transition-all opacity-0 group-hover:opacity-100 translate-x-2 group-hover:translate-x-0"
                      >
                        <Trash2 className="w-4 h-4" />
                      </button>
                    )}
                </div>
            </div>
          ))}

          {filtered.length === 0 && (
              <div className="glass-card rounded-3xl p-20 flex flex-col items-center justify-center text-center opacity-60">
                  <Search className="w-12 h-12 text-slate-700 mb-4" />
                  <h3 className="text-lg font-bold text-white mb-2 uppercase tracking-widest">No entries found</h3>
                  <p className="text-slate-500 text-xs font-medium">Clear search or filters to restore visibility.</p>
              </div>
          )}
      </div>

      {isAddModalOpen && onAdd && (
        <AddTransactionModal 
            onClose={() => setIsAddModalOpen(false)} 
            onAdd={onAdd}
            accounts={accounts}
            onNavigateToAccounts={onNavigateToAccounts}
            userPlan={userPlan}
            formatCurrency={formatCurrency}
            scanUsage={scanUsage}
            onIncrementScan={onIncrementScan}
            currency={currency}
        />
      )}
    </div>
  );
};

const AddTransactionModal: React.FC<{ 
    onClose: () => void; 
    onAdd: (t: Transaction) => void;
    accounts: Account[];
    onNavigateToAccounts?: () => void;
    userPlan?: UserPlan;
    formatCurrency: (amount: number) => string;
    scanUsage: number;
    onIncrementScan?: () => void;
    currency: Currency;
}> = ({ onClose, onAdd, accounts, onNavigateToAccounts, userPlan, formatCurrency, scanUsage, onIncrementScan, currency }) => {
    const [type, setType] = useState<TransactionType>(TransactionType.EXPENSE);
    const [merchant, setMerchant] = useState('');
    const [amount, setAmount] = useState('');
    const [category, setCategory] = useState<Category | ''>('');
    const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
    const [selectedAccountId, setSelectedAccountId] = useState<string>(accounts[0]?.id || '');
    const [notes, setNotes] = useState('');
    const [isAutoCategorizing, setIsAutoCategorizing] = useState(false);
    const [isScanning, setIsScanning] = useState(false);
    const [scanError, setScanError] = useState<string | null>(null);
    const fileInputRef = useRef<HTMLInputElement>(null);

    // Hard-token Limit for Scans (Lifetime)
    const scanLimit = userPlan === 'ultra' ? 150 : userPlan === 'pro' ? 50 : 1;
    const canScan = scanUsage < scanLimit;

    const expenseCategories = Object.values(Category).filter(c => c !== Category.INCOME && c !== Category.INVESTMENT);
    const incomeCategories = [Category.INCOME, Category.INVESTMENT, Category.OTHER];

    const compressImage = (file: File): Promise<string> => {
        return new Promise((resolve, reject) => {
            const reader = new FileReader();
            reader.readAsDataURL(file);
            reader.onload = (e) => {
                const img = new Image();
                img.src = e.target?.result as string;
                img.onload = () => {
                    const canvas = document.createElement('canvas');
                    const MAX_WIDTH = 800;
                    let width = img.width;
                    let height = img.height;
                    if (width > MAX_WIDTH) { height *= MAX_WIDTH / width; width = MAX_WIDTH; }
                    canvas.width = width;
                    canvas.height = height;
                    const ctx = canvas.getContext('2d');
                    if (ctx) {
                        ctx.drawImage(img, 0, 0, width, height);
                        resolve(canvas.toDataURL('image/jpeg', 0.7).split(',')[1]); 
                    } else { reject(new Error("Canvas failure")); }
                }
            };
        });
    };

    const handleMerchantBlur = async () => {
        if (!merchant || isAutoCategorizing || userPlan === 'free' || category) return;
        setIsAutoCategorizing(true);
        try {
            const predicted = await categorizeTransaction(merchant, parseFloat(amount) || 0);
            if (Object.values(Category).includes(predicted as Category)) setCategory(predicted as Category);
        } finally { setIsAutoCategorizing(false); }
    };

    const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;
        setIsScanning(true);
        setScanError(null);
        try {
            const base64 = await compressImage(file);
            const result = await parseReceiptImage(base64);
            if (result) {
                setMerchant(result.merchant || '');
                setAmount(result.amount?.toString() || '');
                if (result.date) setDate(result.date);
                if (onIncrementScan) onIncrementScan();
            } else { setScanError("AI could not parse receipt."); }
        } catch (err) { setScanError("Scanning protocol failure."); } finally { setIsScanning(false); }
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (!merchant || !amount || !category) return;
        const newTx: Transaction = {
            id: Date.now().toString(),
            date,
            merchant,
            amount: parseFloat(amount),
            category: category as Category,
            type,
            accountId: selectedAccountId || 'manual',
            notes
        };
        onAdd(newTx);
        onClose();
    };

    return (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/80 backdrop-blur-md animate-fade-in">
            <div className="bg-[#0f172a] border border-white/10 rounded-3xl w-full max-w-lg shadow-2xl overflow-hidden animate-slide-up flex flex-col max-h-[90vh]">
                <button onClick={onClose} className="absolute top-4 right-4 p-2 text-slate-400 hover:text-white z-10"><X className="w-6 h-6" /></button>
                <div className="p-8 border-b border-white/5">
                    <h3 className="text-2xl font-black text-white uppercase tracking-tighter">Log Financial Event</h3>
                    <p className="text-slate-500 text-[10px] font-bold uppercase tracking-[0.2em] mt-1">Optical Credits: {scanUsage}/{scanLimit}</p>
                </div>
                <div className="overflow-y-auto p-8 custom-scrollbar">
                    <form onSubmit={handleSubmit} className="space-y-6">
                        <div className="relative">
                            <input type="file" accept="image/*" ref={fileInputRef} onChange={handleFileChange} hidden />
                            <button 
                                type="button" 
                                onClick={() => fileInputRef.current?.click()}
                                disabled={!canScan || isScanning}
                                className={`w-full py-4 rounded-xl border-2 border-dashed transition-all flex items-center justify-center gap-3 ${isScanning ? 'border-indigo-500 bg-indigo-500/10' : !canScan ? 'opacity-50 grayscale cursor-not-allowed' : 'border-slate-700 bg-slate-800/30 hover:border-indigo-500 hover:text-white text-slate-400'}`}
                            >
                                {isScanning ? <Loader2 className="w-5 h-5 animate-spin text-indigo-400" /> : <Camera className="w-5 h-5" />}
                                <span className="text-xs font-black uppercase tracking-widest">{isScanning ? "Processing..." : !canScan ? "Lifetime Scan Credits Exhausted" : "AI Receipt Extraction"}</span>
                            </button>
                        </div>

                        <div className="relative flex bg-slate-950 rounded-2xl p-1.5 border border-white/10 h-14">
                            <div className={`absolute top-1.5 bottom-1.5 rounded-xl shadow-lg transition-all duration-300 ${type === TransactionType.EXPENSE ? 'left-1.5 w-[calc(50%-6px)] bg-rose-600' : 'left-[calc(50%+3px)] w-[calc(50%-6px)] bg-emerald-600'}`}></div>
                            <button type="button" onClick={() => setType(TransactionType.EXPENSE)} className={`relative z-10 flex-1 text-xs font-black uppercase tracking-widest ${type === TransactionType.EXPENSE ? 'text-white' : 'text-slate-500'}`}>Expense</button>
                            <button type="button" onClick={() => setType(TransactionType.INCOME)} className={`relative z-10 flex-1 text-xs font-black uppercase tracking-widest ${type === TransactionType.INCOME ? 'text-white' : 'text-slate-500'}`}>Income</button>
                        </div>

                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Magnitude</label>
                                <input required type="number" step="0.01" value={amount} onChange={e => setAmount(e.target.value)} className="w-full bg-slate-950 border border-white/10 rounded-xl p-3.5 text-white focus:border-indigo-500 focus:outline-none" placeholder="0.00" />
                            </div>
                            <div>
                                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Timestamp</label>
                                <input required type="date" value={date} onChange={e => setDate(e.target.value)} className="w-full bg-slate-950 border border-white/10 rounded-xl p-3.5 text-white focus:border-indigo-500 focus:outline-none [color-scheme:dark]" />
                            </div>
                        </div>

                        <div>
                            <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Merchant / Source</label>
                            <input required type="text" value={merchant} onChange={e => setMerchant(e.target.value)} onBlur={handleMerchantBlur} className="w-full bg-slate-950 border border-white/10 rounded-xl p-3.5 text-white focus:border-indigo-500 focus:outline-none" placeholder="e.g. Amazon" />
                        </div>

                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Category</label>
                                <select required value={category} onChange={e => setCategory(e.target.value as Category)} className="w-full bg-slate-950 border border-white/10 rounded-xl p-3.5 text-white text-xs appearance-none cursor-pointer">
                                    <option value="" disabled>Select Category</option>
                                    {(type === TransactionType.INCOME ? incomeCategories : expenseCategories).map(c => <option key={c} value={c}>{c}</option>)}
                                </select>
                            </div>
                            <div>
                                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Node</label>
                                <select value={selectedAccountId} onChange={(e) => setSelectedAccountId(e.target.value)} className="w-full bg-slate-950 border border-white/10 rounded-xl p-3.5 text-white text-xs appearance-none cursor-pointer">
                                    <option value="manual">Manual / Cash</option>
                                    {accounts.map(acc => <option key={acc.id} value={acc.id}>{acc.name}</option>)}
                                </select>
                            </div>
                        </div>

                        <button type="submit" className="w-full py-4 bg-indigo-600 hover:bg-indigo-500 text-white font-black text-sm uppercase tracking-[0.2em] rounded-xl shadow-lg active:scale-95 transition-all">Synchronize Entry</button>
                    </form>
                </div>
            </div>
        </div>
    );
};

export default Transactions;

import React, { useState, useEffect, useCallback } from 'react';
import { Account, Budget, Goal, Transaction, UserPlan, ToastMessage, BotMode, Currency, Language, TransactionType } from './types';
import { ACCOUNTS, INITIAL_TRANSACTIONS, INITIAL_BUDGETS, INITIAL_GOALS, NAV_ITEMS, TRANSLATIONS } from './constants';
import Dashboard from './components/Dashboard';
import Transactions from './components/Transactions';
import Accounts from './components/Accounts';
import Insights from './components/Insights';
import Goals from './components/Goals';
import Plans from './components/Plans';
import Settings from './components/Settings';
import LandingPage from './components/LandingPage';
import ToastContainer from './components/Toast';
import FloatingAssistant from './components/FloatingAssistant';
import { Sparkles, LogOut, MessageCircle, Zap, Crown, AlertTriangle } from 'lucide-react';

const getLifetimeUsage = (key: string) => {
    try {
        const count = localStorage.getItem(key);
        return count ? parseInt(count) : 0;
    } catch (e) {
        return 0;
    }
};

const safeSetItem = (key: string, value: string) => {
    try {
        localStorage.setItem(key, value);
    } catch (e) {
        console.warn(`Storage quota exceeded for ${key}`);
    }
};

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');

  const [accounts, setAccounts] = useState<Account[]>(() => {
      const saved = localStorage.getItem('nova_accounts');
      return saved ? JSON.parse(saved) : ACCOUNTS;
  });
  const [transactions, setTransactions] = useState<Transaction[]>(() => {
      const saved = localStorage.getItem('nova_transactions');
      return saved ? JSON.parse(saved) : INITIAL_TRANSACTIONS;
  });
  const [budgets, setBudgets] = useState<Budget[]>(() => {
      const saved = localStorage.getItem('nova_budgets');
      return saved ? JSON.parse(saved) : INITIAL_BUDGETS;
  });
  const [goals, setGoals] = useState<Goal[]>(() => {
      const saved = localStorage.getItem('nova_goals');
      return saved ? JSON.parse(saved) : INITIAL_GOALS;
  });

  const [userPlan, setUserPlan] = useState<UserPlan>(() => localStorage.getItem('nova_user_plan') as UserPlan || 'free');
  const [insightUsage, setInsightUsage] = useState(() => getLifetimeUsage('nova_insight_usage_lifetime'));
  const [scanUsage, setScanUsage] = useState(() => getLifetimeUsage('nova_scan_usage_lifetime'));
  const [negotiationUsage, setNegotiationUsage] = useState(() => getLifetimeUsage('nova_negotiation_usage_lifetime'));

  const [isLoggedIn, setIsLoggedIn] = useState(() => localStorage.getItem('nova_auth_token') !== null);
  const [toasts, setToasts] = useState<ToastMessage[]>([]);
  const [botMode, setBotMode] = useState<BotMode>(() => (localStorage.getItem('nova_bot_mode') as BotMode) || 'ruthless');
  const [pendingChatQuery, setPendingChatQuery] = useState<string | null>(null);

  const [userName, setUserName] = useState(() => localStorage.getItem('nova_user_name') || 'Pilot');
  const [userEmail, setUserEmail] = useState(() => localStorage.getItem('nova_user_email') || 'pilot@nova.io');
  const [userAvatar, setUserAvatar] = useState(() => localStorage.getItem('nova_user_avatar') || '');
  const [userAvatarZoom, setUserAvatarZoom] = useState(1);
  const [userAvatarPos, setUserAvatarPos] = useState({ x: 0, y: 0 });
  const [userBorder, setUserBorder] = useState('default');
  const [userBackground, setUserBackground] = useState(() => localStorage.getItem('nova_user_bg') || '');

  const [currency, setCurrency] = useState<Currency>(() => (localStorage.getItem('nova_currency') as Currency) || 'USD');
  const [language, setLanguage] = useState<Language>(() => (localStorage.getItem('nova_language') as Language) || 'en');

  // Persistence
  useEffect(() => safeSetItem('nova_accounts', JSON.stringify(accounts)), [accounts]);
  useEffect(() => safeSetItem('nova_transactions', JSON.stringify(transactions)), [transactions]);
  useEffect(() => safeSetItem('nova_budgets', JSON.stringify(budgets)), [budgets]);
  useEffect(() => safeSetItem('nova_goals', JSON.stringify(goals)), [goals]);
  useEffect(() => safeSetItem('nova_user_plan', userPlan), [userPlan]);
  useEffect(() => safeSetItem('nova_currency', currency), [currency]);
  useEffect(() => safeSetItem('nova_language', language), [language]);
  useEffect(() => safeSetItem('nova_bot_mode', botMode), [botMode]);
  useEffect(() => safeSetItem('nova_user_bg', userBackground), [userBackground]);

  useEffect(() => safeSetItem('nova_insight_usage_lifetime', insightUsage.toString()), [insightUsage]);
  useEffect(() => safeSetItem('nova_scan_usage_lifetime', scanUsage.toString()), [scanUsage]);
  useEffect(() => safeSetItem('nova_negotiation_usage_lifetime', negotiationUsage.toString()), [negotiationUsage]);

  const addToast = useCallback((message: string, type: 'success' | 'error' | 'info' = 'info') => {
    setToasts(prev => [...prev, { id: Date.now().toString(), message, type }]);
  }, []);

  const removeToast = (id: string) => {
    setToasts(prev => prev.filter(t => t.id !== id));
  };

  const formatCurrency = (amount: number) => {
    const isNoDecimal = currency === 'VND' || currency === 'JPY';
    return new Intl.NumberFormat(language === 'vi' ? 'vi-VN' : 'en-US', { 
        style: 'currency', 
        currency: currency,
        minimumFractionDigits: isNoDecimal ? 0 : 2,
        maximumFractionDigits: isNoDecimal ? 0 : 2,
    }).format(amount);
  };

  const reconcileBalance = (tx: Transaction, direction: 'add' | 'delete') => {
      if (tx.accountId === 'manual') return;
      setAccounts(prev => prev.map(acc => {
          if (acc.id === tx.accountId) {
              const isIncome = tx.type === TransactionType.INCOME;
              let change = tx.amount;
              if (direction === 'add') {
                  change = isIncome ? change : -change;
              } else {
                  change = isIncome ? -change : change;
              }
              return { ...acc, balance: acc.balance + change };
          }
          return acc;
      }));
  };

  const handleAddTransaction = (t: Transaction) => {
      setTransactions(prev => [t, ...prev]);
      reconcileBalance(t, 'add');
      addToast('Entry archived. Balance synchronized.', 'success');
  };

  const handleDeleteTransaction = (id: string) => {
      const tx = transactions.find(t => t.id === id);
      if (tx) {
          reconcileBalance(tx, 'delete');
          setTransactions(prev => prev.filter(t => t.id !== id));
          addToast('Entry purged. Balance reconciled.', 'info');
      }
  };

  const handleLogin = (name: string) => {
    setIsLoggedIn(true);
    setUserName(name);
    localStorage.setItem('nova_user_name', name);
  };

  const handleLogout = () => {
    localStorage.removeItem('nova_auth_token');
    setIsLoggedIn(false);
  };

  const handleUpdateProfile = (name: string, email: string, avatar: string, zoom: number, pos: { x: number; y: number }, border: string) => {
      setUserName(name);
      localStorage.setItem('nova_user_name', name);
      setUserEmail(email);
      localStorage.setItem('nova_user_email', email);
      setUserAvatar(avatar);
      safeSetItem('nova_user_avatar', avatar);
      setUserAvatarZoom(zoom);
      setUserAvatarPos(pos);
      setUserBorder(border);
  };

  const handleClearData = () => {
      localStorage.clear();
      window.location.reload();
  };

  const handleImportData = (file: File) => {
      const reader = new FileReader();
      reader.onload = (e) => {
          try {
              const data = JSON.parse(e.target?.result as string);
              if (data.accounts) setAccounts(data.accounts);
              if (data.transactions) setTransactions(data.transactions);
              if (data.budgets) setBudgets(data.budgets);
              if (data.goals) setGoals(data.goals);
              addToast('Vault protocol restored.', 'success');
          } catch (err) {
              addToast('Failed to parse data capsule.', 'error');
          }
      };
      reader.readAsText(file);
  };

  const handleExportData = () => {
      const data = { accounts, transactions, budgets, goals, userPlan };
      const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `nova_backup_${new Date().toISOString().split('T')[0]}.json`;
      a.click();
  };

  const handleAskCoach = (msg: string) => {
      setPendingChatQuery(msg);
      setActiveTab('insights');
  };

  const branding = (userPlan === 'ultra' ? {
      icon: <Crown className="w-6 h-6 text-white" />,
      bg: 'bg-gradient-to-tr from-indigo-600 via-purple-600 to-indigo-600',
      label: 'ELITE SYSTEM',
      shadow: 'shadow-indigo-500/40'
  } : userPlan === 'pro' ? {
      icon: <Zap className="w-6 h-6 text-white" />,
      bg: 'bg-gradient-to-tr from-amber-500 to-orange-500',
      label: 'PRO SYSTEM',
      shadow: 'shadow-amber-500/40'
  } : {
      icon: <Sparkles className="w-6 h-6 text-white" />,
      bg: 'bg-gradient-to-tr from-indigo-600 to-violet-600',
      label: 'CORE SYSTEM',
      shadow: 'shadow-indigo-500/20'
  });

  const isApiConfigured = !!process.env.API_KEY;

  if (!isLoggedIn) {
    return <LandingPage onLoginSuccess={handleLogin} />;
  }

  return (
    <div className="flex h-screen bg-[#020617] text-slate-100 font-sans selection:bg-indigo-500/30 overflow-hidden relative">
      {!isApiConfigured && (
          <div className="fixed top-0 left-0 w-full bg-rose-600 text-white text-[10px] font-black py-2 px-4 text-center z-[100] flex items-center justify-center gap-2 shadow-lg uppercase tracking-widest">
              <AlertTriangle className="w-4 h-4" />
              AI Core Offline: Missing API Key. Manual tracking active.
          </div>
      )}

      {userBackground && (
          <div className="absolute inset-0 z-0">
               <img src={userBackground} alt="bg" className="w-full h-full object-cover opacity-40 blur-sm" />
               <div className="absolute inset-0 bg-[#020617]/70"></div>
          </div>
      )}

      {!userBackground && (
          <div className="fixed inset-0 z-0 pointer-events-none bg-[radial-gradient(at_0%_0%,hsla(253,16%,7%,1)_0,transparent_50%),radial-gradient(at_50%_0%,hsla(225,39%,30%,0.3)_0,transparent_50%),radial-gradient(at_100%_0%,hsla(339,49%,30%,0.3)_0,transparent_50%)]">
             <div className="absolute top-[-10%] left-[-10%] w-[50%] h-[50%] bg-indigo-900/10 rounded-full blur-[120px] animate-pulse-slow"></div>
             <div className="absolute bottom-[-10%] right-[-10%] w-[50%] h-[50%] bg-purple-900/10 rounded-full blur-[120px] animate-pulse-slow" style={{ animationDelay: '1s' }}></div>
          </div>
      )}

      <FloatingAssistant 
          transactions={transactions}
          budgets={budgets}
          userPlan={userPlan}
          isVisible={activeTab !== 'insights'}
          onOpenChat={handleAskCoach}
      />

      <aside className="hidden md:flex flex-col w-64 p-4 z-20 bg-slate-950/40 backdrop-blur-md border-r border-white/5 relative">
        <div className="flex items-center gap-3 px-4 py-3 mb-8">
            <div className={`w-10 h-10 rounded-xl flex items-center justify-center shadow-lg ring-1 ring-white/10 ${branding.bg} ${branding.shadow}`}>
                {branding.icon}
            </div>
            <div>
                <h1 className="text-xl font-bold tracking-tight text-white">Nova AI</h1>
                <p className={`text-[10px] font-bold uppercase tracking-wider ${userPlan === 'ultra' ? 'text-purple-400' : userPlan === 'pro' ? 'text-amber-400' : 'text-slate-500'}`}>
                    {branding.label}
                </p>
            </div>
        </div>

        <nav className="flex-1 space-y-1">
            {NAV_ITEMS.map((item) => {
                const isActive = activeTab === item.id;
                const label = TRANSLATIONS[language]?.[item.id as keyof typeof TRANSLATIONS['en']] || item.label;
                return (
                    <button
                        key={item.id}
                        onClick={() => setActiveTab(item.id)}
                        className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold transition-all duration-300 group ${isActive ? 'bg-indigo-600/10 text-indigo-400 shadow-[0_0_20px_rgba(99,102,241,0.15)] ring-1 ring-indigo-500/20' : 'text-slate-400 hover:text-white hover:bg-white/5'}`}
                    >
                        <item.icon className={`w-5 h-5 transition-colors ${isActive ? 'text-indigo-400' : 'text-slate-500 group-hover:text-white'}`} />
                        {label}
                    </button>
                );
            })}
        </nav>

        <div className="mt-auto pt-6 border-t border-white/5">
             <button onClick={() => setActiveTab('settings')} className="w-full text-left px-4 py-4 rounded-2xl bg-slate-900/50 border border-white/5 flex items-center gap-3 mb-4 hover:bg-slate-800 transition-colors group">
                 <div className="w-10 h-10 rounded-full bg-indigo-500 flex items-center justify-center text-white overflow-hidden relative border border-white/10 shadow-inner">
                     {userAvatar ? (
                         <img src={userAvatar} className="w-full h-full object-cover" alt="User" style={{ transform: `scale(${userAvatarZoom}) translate(${userAvatarPos.x}px, ${userAvatarPos.y}px)` }} />
                     ) : (
                         <span className="font-bold text-lg">{userName.charAt(0)}</span>
                     )}
                 </div>
                 <div className="overflow-hidden">
                     <h4 className="font-bold text-white text-sm truncate group-hover:text-indigo-400 transition-colors">{userName}</h4>
                     <p className="text-[10px] text-slate-500 truncate font-bold uppercase tracking-widest">{userPlan} tier</p>
                 </div>
             </button>
             <button onClick={handleLogout} className="w-full flex items-center gap-2 px-4 py-2 text-xs font-bold text-slate-500 hover:text-rose-400 transition-colors uppercase tracking-widest">
                 <LogOut className="w-4 h-4" /> {TRANSLATIONS[language]?.signOut || 'Sign Out'}
             </button>
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 z-10 relative overflow-hidden">
        <div className="flex-1 overflow-y-auto p-4 md:p-8 pb-24 md:pb-8 custom-scrollbar">
            {activeTab === 'dashboard' && (
                <Dashboard 
                    accounts={accounts} 
                    transactions={transactions} 
                    onNavigate={setActiveTab} 
                    onAddAccount={() => setActiveTab('accounts')}
                    onAddTransaction={() => setActiveTab('transactions')}
                    onAddGoal={() => setActiveTab('goals')}
                    formatCurrency={formatCurrency}
                    userPlan={userPlan}
                    onAskCoach={handleAskCoach}
                    negotiationUsage={negotiationUsage}
                    onIncrementNegotiation={() => setNegotiationUsage(prev => prev + 1)}
                />
            )}

            {activeTab === 'transactions' && (
                <Transactions 
                    transactions={transactions} 
                    accounts={accounts}
                    onDelete={handleDeleteTransaction}
                    onAdd={handleAddTransaction}
                    formatCurrency={formatCurrency}
                    onNavigateToAccounts={() => setActiveTab('accounts')}
                    userPlan={userPlan}
                    scanUsage={scanUsage}
                    onIncrementScan={() => setScanUsage(prev => prev + 1)}
                    currency={currency}
                />
            )}

            {activeTab === 'accounts' && (
                <Accounts 
                    accounts={accounts} 
                    budgets={budgets} 
                    transactions={transactions} 
                    userPlan={userPlan}
                    onAdd={(acc) => { setAccounts(prev => [...prev, acc]); addToast('Account bridged.', 'success'); }}
                    onUpdate={(acc) => { setAccounts(prev => prev.map(a => a.id === acc.id ? acc : a)); addToast('Account updated.', 'success'); }}
                    onDelete={(id) => { 
                        setAccounts(prev => prev.filter(a => a.id !== id));
                        setTransactions(prev => prev.map(t => t.accountId === id ? { ...t, accountId: 'manual' } : t));
                        addToast('Account disconnected. History preserved.', 'info'); 
                    }}
                    formatCurrency={formatCurrency}
                    userName={userName}
                    userAvatar={userAvatar}
                    userAvatarZoom={userAvatarZoom}
                    userAvatarPos={userAvatarPos}
                    userBorder={userBorder}
                    onNavigate={setActiveTab}
                />
            )}

            {activeTab === 'insights' && (
                <Insights 
                    transactions={transactions} 
                    userPlan={userPlan} 
                    onUpgradeClick={() => setActiveTab('plans')}
                    formatCurrency={formatCurrency}
                    insightUsage={insightUsage}
                    onIncrementUsage={() => setInsightUsage(prev => prev + 1)}
                    onApplyBudgets={(newBudgets) => {
                         const existingCats = new Set(budgets.map(b => b.category));
                         const toAdd = newBudgets.filter(b => !existingCats.has(b.category));
                         setBudgets(prev => [...prev, ...toAdd]);
                         addToast(`Applied ${toAdd.length} AI limits.`, 'success');
                    }}
                    initialPrompt={pendingChatQuery}
                    onPromptHandled={() => setPendingChatQuery(null)}
                    botMode={botMode}
                />
            )}

            {activeTab === 'goals' && (
                <Goals 
                    goals={goals} 
                    budgets={budgets} 
                    transactions={transactions}
                    onAddGoal={(g) => { setGoals(prev => [...prev, g]); addToast('Goal deployed.', 'success'); }}
                    onUpdateGoal={(g) => { setGoals(prev => prev.map(goal => goal.id === g.id ? g : goal)); addToast('Goal updated.', 'success'); }}
                    onAddBudget={(b) => { setBudgets(prev => [...prev, b]); addToast('Limit set.', 'success'); }}
                    onDeleteBudget={(id) => { setBudgets(prev => prev.filter(b => b.id !== id)); addToast('Limit removed.', 'info'); }}
                    formatCurrency={formatCurrency} 
                />
            )}

            {activeTab === 'plans' && (
                <Plans 
                    currentPlan={userPlan} 
                    onUpgrade={(plan) => { setUserPlan(plan); addToast(`Plan upgraded to ${plan.toUpperCase()}.`, 'success'); }}
                    onDowngrade={() => { setUserPlan('free'); addToast('Plan reset to Starter.', 'info'); }}
                    onNavigateDashboard={() => setActiveTab('dashboard')}
                />
            )}

            {activeTab === 'settings' && (
                <Settings 
                    userName={userName}
                    userEmail={userEmail}
                    userAvatar={userAvatar}
                    userAvatarZoom={userAvatarZoom}
                    userAvatarPos={userAvatarPos}
                    userBorder={userBorder}
                    userBackground={userBackground}
                    onUpdateBackground={setUserBackground}
                    userPlan={userPlan}
                    onUpdateProfile={handleUpdateProfile}
                    addToast={addToast}
                    onExportData={handleExportData}
                    onImportData={handleImportData}
                    onClearData={handleClearData}
                    language={language}
                    onUpdateLanguage={setLanguage}
                    currency={currency}
                    onUpdateCurrency={setCurrency}
                    botMode={botMode}
                    onUpdateBotMode={setBotMode}
                    onDowngrade={() => { setUserPlan('free'); addToast('Plan downgraded.', 'info'); }}
                />
            )}
        </div>
      </main>

      <ToastContainer toasts={toasts} onRemove={removeToast} />
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { UserPlan } from '../types';
import { Check, Star, Zap, Shield, Sparkles, CreditCard, Lock, X, Loader2, Smartphone, BrainCircuit, Target, BarChart3, PartyPopper, AlertTriangle, Crown, Infinity } from 'lucide-react';
import confetti from 'canvas-confetti';

interface PlansProps {
  currentPlan: UserPlan;
  onUpgrade: (plan: UserPlan) => void;
  onDowngrade: () => void;
  onNavigateDashboard?: () => void;
}

const Plans: React.FC<PlansProps> = ({ currentPlan, onUpgrade, onDowngrade, onNavigateDashboard }) => {
  const [isCheckoutOpen, setIsCheckoutOpen] = useState(false);
  const [selectedPlan, setSelectedPlan] = useState<UserPlan | null>(null);
  const [isDowngradeOpen, setIsDowngradeOpen] = useState(false);
  const [showCelebration, setShowCelebration] = useState(false);

  const eliteStars = useMemo(() => {
    return Array.from({ length: 70 }).map((_, i) => ({
      id: i,
      top: `${Math.random() * 100}%`,
      left: `${Math.random() * 100}%`,
      size: Math.random() < 0.2 ? '3px' : Math.random() < 0.5 ? '2px' : '1px',
      delay: `${Math.random() * 5}s`,
      duration: `${Math.random() * 3 + 2}s`,
      opacity: Math.random() * 0.5 + 0.3
    }));
  }, []);

  const handleUpgradeClick = (plan: UserPlan) => {
    setSelectedPlan(plan);
    setIsCheckoutOpen(true);
  };

  const handleConfirmUpgrade = () => {
    if (selectedPlan) {
        onUpgrade(selectedPlan);
        setIsCheckoutOpen(false);
        setShowCelebration(true);
        confetti({
            particleCount: 150,
            spread: 70,
            origin: { y: 0.6 },
            colors: selectedPlan === 'ultra' ? ['#6366f1', '#ec4899', '#8b5cf6'] : ['#f59e0b', '#fbbf24', '#ffffff']
        });
    }
  };

  const handleDowngradeClick = () => {
      setIsDowngradeOpen(true);
  };

  const handleConfirmDowngrade = () => {
      onDowngrade();
      setIsDowngradeOpen(false);
  };

  const isPaid = currentPlan === 'pro' || currentPlan === 'ultra';
  const isElite = currentPlan === 'ultra';

  return (
    <div className="animate-slide-up pb-10">
      <div className="text-center max-w-2xl mx-auto mb-12">
