      <div className={`grid grid-cols-1 ${isElite ? 'max-w-xl' : isPaid ? 'md:grid-cols-2 max-w-4xl' : 'md:grid-cols-3 max-w-6xl'} gap-6 mx-auto`}>

        {/* Starter Plan */}
        {!isPaid && (
