        {!isElite && (
            <div className={`glass-card p-6 rounded-[2.5rem] relative flex flex-col border transition-transform duration-300 ${currentPlan === 'pro' ? 'border-amber-500/50 bg-amber-500/5' : 'border-amber-500/30 overflow-hidden group hover:scale-[1.02]'}`}>
                <div className="absolute inset-0 bg-gradient-to-b from-amber-500/5 to-transparent pointer-events-none"></div>
                <div className="mb-6 relative z-10">
                    <h3 className="text-lg font-bold text-white mb-2">Pro System</h3>
                    <div className="flex items-baseline gap-1">
                    <span className="text-3xl font-bold text-white">$15.99</span>
                    <span className="text-slate-500 font-medium">/mo</span>
                    </div>
                </div>

                <div className="space-y-3 mb-8 flex-1 relative z-10">
                    <FeatureItem text="AI Financial Coach (3 Tokens)" icon={<Zap className="w-3.5 h-3.5 text-amber-400" />} />
                    <FeatureItem text="50 AI Receipt Scans" />
                </div>

                <button 
                    onClick={() => handleUpgradeClick('pro')}
                    disabled={currentPlan === 'pro'}
                    className="w-full py-4 rounded-xl font-black text-sm text-white bg-gradient-to-r from-amber-500 to-orange-500 shadow-[0_0_20px_rgba(251,191,36,0.3)] disabled:opacity-50 transition-all active:scale-95"
                >
                    {currentPlan === 'pro' ? 'System Active' : 'Upgrade to Pro'}
