        {/* Elite Plan */}
        <div className={`relative p-8 rounded-[2.5rem] flex flex-col overflow-hidden transition-all duration-500 border border-indigo-500/50 bg-[#020617] mx-auto w-full ${isElite ? 'shadow-[0_0_80px_rgba(99,102,241,0.3)] ring-2 ring-indigo-500' : 'group hover:scale-[1.02]'}`}>
          <style>{`@keyframes simple-twinkle { 0%, 100% { opacity: 0.2; transform: scale(0.8); } 50% { opacity: 1; transform: scale(1.2); } }`}</style>
          <div className="absolute inset-0 pointer-events-none">
              {eliteStars.map((star) => (
                  <div key={star.id} className="absolute bg-white rounded-full" style={{ top: star.top, left: star.left, width: star.size, height: star.size, opacity: star.opacity, animation: `simple-twinkle ${star.duration} ease-in-out infinite`, animationDelay: star.delay }} />
