      </div>

      {isCheckoutOpen && selectedPlan && (
        <CheckoutModal plan={selectedPlan} onClose={() => setIsCheckoutOpen(false)} onConfirm={handleConfirmUpgrade} />
      )}

      {isDowngradeOpen && (
        <DeactivateModal onClose={() => setIsDowngradeOpen(false)} onConfirm={handleConfirmDowngrade} />
      )}

      {showCelebration && (
        <CelebrationModal onClose={() => { setShowCelebration(false); if(onNavigateDashboard) onNavigateDashboard(); }} />
      )}
    </div>
  );
};

