        <p className="text-slate-400 mb-8 font-medium">Your account has been elevated to the next tier. All operational limits have been updated.</p>
        <button onClick={onClose} className="w-full py-4 bg-white text-slate-900 font-black rounded-2xl shadow-xl active:scale-95 transition-all">Initialize Dash</button>
      </div>
    </div>
  );
};

const CheckoutModal: React.FC<{ plan: UserPlan, onClose: () => void; onConfirm: () => void }> = ({ plan, onClose, onConfirm }) => {
    const [isProcessing, setIsProcessing] = useState(false);
    const price = plan === 'ultra' ? '$79.00' : '$15.99';
    return (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-black/80 backdrop-blur-md animate-fade-in">
             <div className="bg-[#0f172a] w-full max-w-sm rounded-3xl border border-white/10 shadow-2xl overflow-hidden animate-slide-up p-8">
                 <h2 className="text-xl font-bold text-white mb-6">Confirm Checkout</h2>
