const CheckoutModal: React.FC<{ plan: UserPlan, onClose: () => void; onConfirm: () => void }> = ({ plan, onClose, onConfirm }) => {
    const [isProcessing, setIsProcessing] = useState(false);
    const [card, setCard] = useState('');
    const [expiry, setExpiry] = useState('');
    const [cvc, setCvc] = useState('');
    const [error, setError] = useState('');

    const price = plan === 'ultra' ? '$79.00' : '$15.99';

    const validate = () => {
        if (card.replace(/\s/g, '').length !== 16) return "Invalid Card: Must be 16 digits.";
        if (!/^\d{2}\/\d{2}$/.test(expiry)) return "Invalid Expiry: Use MM/YY.";
        if (cvc.length !== 3) return "Invalid CVC: Must be 3 digits.";
        return null;
    };

    const handlePay = (e: React.FormEvent) => {
        e.preventDefault();
        const err = validate();
        if (err) {
            setError(err);
            return;
        }
        setError('');
        setIsProcessing(true);
        setTimeout(() => {
            setIsProcessing(false);
            onConfirm();
        }, 2000);
    };

    return (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-black/80 backdrop-blur-md animate-fade-in">
             <div className="bg-[#0f172a] w-full max-w-sm rounded-3xl border border-white/10 shadow-2xl overflow-hidden animate-slide-up">
                 <div className="p-8 pb-0 flex justify-between items-center">
                    <h2 className="text-xl font-bold text-white tracking-tight">Authorize Deployment</h2>
                    <button onClick={onClose} className="p-2 text-slate-500 hover:text-white"><X className="w-5 h-5" /></button>
                 </div>
                 <form onSubmit={handlePay} className="p-8 space-y-6">
                    <div className="bg-slate-900/50 p-4 rounded-2xl border border-white/5">
                        <div className="flex justify-between text-xs text-slate-400 font-bold uppercase tracking-widest mb-1"><span>{plan.toUpperCase()} System</span><span>{price}</span></div>
                        <div className="text-[10px] text-slate-600 uppercase font-black">Next Billing Cycle: 30 Days</div>
                    </div>

                    <div className="space-y-4">
                        <div className="relative">
                            <input required value={card} onChange={e => setCard(e.target.value.replace(/[^\d]/g, '').substring(0, 16))} placeholder="Card Number" className="w-full bg-slate-950 border border-white/10 rounded-xl p-3 text-white focus:border-indigo-500 font-mono transition-all" />
                            <CreditCard className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-700" />
                        </div>
                        <div className="grid grid-cols-2 gap-4">
                            <input required value={expiry} onChange={e => setExpiry(e.target.value)} placeholder="MM/YY" className="w-full bg-slate-950 border border-white/10 rounded-xl p-3 text-white focus:border-indigo-500 font-mono text-center" />
                            <input required value={cvc} onChange={e => setCvc(e.target.value.replace(/[^\d]/g, '').substring(0, 3))} placeholder="CVC" className="w-full bg-slate-950 border border-white/10 rounded-xl p-3 text-white focus:border-indigo-500 font-mono text-center" />
                        </div>
                    </div>

                    {error && <div className="text-rose-400 text-[10px] font-bold uppercase tracking-widest flex items-center gap-2"><AlertTriangle className="w-3 h-3" /> {error}</div>}

                    <button disabled={isProcessing} className="w-full py-4 bg-indigo-600 hover:bg-indigo-500 text-white font-bold rounded-xl shadow-lg active:scale-95 transition-all flex items-center justify-center gap-2">
                        {isProcessing ? <Loader2 className="w-5 h-5 animate-spin" /> : <><Lock className="w-4 h-4" /> Finalize Purchase</>}
                    </button>
                    <p className="text-center text-[10px] text-slate-600 font-medium">Encrypted via Stripe Secure Core</p>
                 </form>
             </div>
        </div>
    );
};

