        </nav>

        <div className="mt-auto pt-6 border-t border-white/5">
             <button onClick={() => setActiveTab('settings')} className="w-full text-left px-4 py-4 rounded-2xl bg-slate-900/50 border border-white/5 flex items-center gap-3 mb-4 hover:bg-slate-800 transition-colors group">
                 <div className="w-10 h-10 rounded-full bg-indigo-500 flex items-center justify-center text-white overflow-hidden relative border border-white/10 shadow-inner">
                     {userAvatar ? (
                         <img src={userAvatar} className="w-full h-full object-cover" alt="User" style={{ transform: `scale(${userAvatarZoom}) translate(${userAvatarPos.x}px, ${userAvatarPos.y}px)` }} />
                     ) : (
                         <span className="font-bold text-lg">{userName.charAt(0)}</span>
                     )}
                 </div>
                 <div className="overflow-hidden">
                     <h4 className="font-bold text-white text-sm truncate group-hover:text-indigo-400 transition-colors">{userName}</h4>
                     <p className="text-[10px] text-slate-500 truncate font-bold uppercase tracking-widest">{userPlan} tier</p>
                 </div>
             </button>
             <button onClick={handleLogout} className="w-full flex items-center gap-2 px-4 py-2 text-xs font-bold text-slate-500 hover:text-rose-400 transition-colors uppercase tracking-widest">
                 <LogOut className="w-4 h-4" /> {TRANSLATIONS[language]?.signOut || 'Sign Out'}
             </button>
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 z-10 relative overflow-hidden">
        <div className="flex-1 overflow-y-auto p-4 md:p-8 pb-24 md:pb-8 custom-scrollbar">
            {activeTab === 'dashboard' && (
                <Dashboard 
                    accounts={accounts} 
                    transactions={transactions} 
                    onNavigate={setActiveTab} 
                    onAddAccount={() => setActiveTab('accounts')}
                    onAddTransaction={() => setActiveTab('transactions')}
                    onAddGoal={() => setActiveTab('goals')}
                    formatCurrency={formatCurrency}
                    userPlan={userPlan}
                    onAskCoach={handleAskCoach}
                    negotiationUsage={negotiationUsage}
                    onIncrementNegotiation={() => setNegotiationUsage(prev => prev + 1)}
                />
            )}

            {activeTab === 'transactions' && (
                <Transactions 
                    transactions={transactions} 
                    accounts={accounts}
                    onDelete={handleDeleteTransaction}
                    onAdd={handleAddTransaction}
                    formatCurrency={formatCurrency}
                    onNavigateToAccounts={() => setActiveTab('accounts')}
                    userPlan={userPlan}
                    scanUsage={scanUsage}
                    onIncrementScan={() => setScanUsage(prev => prev + 1)}
                    currency={currency}
                />
            )}

            {activeTab === 'accounts' && (
                <Accounts 
                    accounts={accounts} 
                    budgets={budgets} 
                    transactions={transactions} 
                    userPlan={userPlan}
                    onAdd={(acc) => { setAccounts(prev => [...prev, acc]); addToast('Account bridged.', 'success'); }}
                    onUpdate={(acc) => { setAccounts(prev => prev.map(a => a.id === acc.id ? acc : a)); addToast('Account updated.', 'success'); }}
                    onDelete={(id) => { 
                        setAccounts(prev => prev.filter(a => a.id !== id));
                        setTransactions(prev => prev.map(t => t.accountId === id ? { ...t, accountId: 'manual' } : t));
                        addToast('Account disconnected. History preserved.', 'info'); 
                    }}
                    formatCurrency={formatCurrency}
                    userName={userName}
                    userAvatar={userAvatar}
                    userAvatarZoom={userAvatarZoom}
                    userAvatarPos={userAvatarPos}
                    userBorder={userBorder}
                    onNavigate={setActiveTab}
                />
            )}

            {activeTab === 'insights' && (
                <Insights 
                    transactions={transactions} 
                    userPlan={userPlan} 
                    onUpgradeClick={() => setActiveTab('plans')}
                    formatCurrency={formatCurrency}
                    insightUsage={insightUsage}
                    onIncrementUsage={() => setInsightUsage(prev => prev + 1)}
                    onApplyBudgets={(newBudgets) => {
                         const existingCats = new Set(budgets.map(b => b.category));
                         const toAdd = newBudgets.filter(b => !existingCats.has(b.category));
                         setBudgets(prev => [...prev, ...toAdd]);
                         addToast(`Applied ${toAdd.length} AI limits.`, 'success');
                    }}
                    initialPrompt={pendingChatQuery}
                    onPromptHandled={() => setPendingChatQuery(null)}
                    botMode={botMode}
                />
            )}

            {activeTab === 'goals' && (
                <Goals 
                    goals={goals} 
                    budgets={budgets} 
                    transactions={transactions}
                    onAddGoal={(g) => { setGoals(prev => [...prev, g]); addToast('Goal deployed.', 'success'); }}
                    onUpdateGoal={(g) => { setGoals(prev => prev.map(goal => goal.id === g.id ? g : goal)); addToast('Goal updated.', 'success'); }}
                    onAddBudget={(b) => { setBudgets(prev => [...prev, b]); addToast('Limit set.', 'success'); }}
                    onDeleteBudget={(id) => { setBudgets(prev => prev.filter(b => b.id !== id)); addToast('Limit removed.', 'info'); }}
                    formatCurrency={formatCurrency} 
                />
            )}

            {activeTab === 'plans' && (
                <Plans 
                    currentPlan={userPlan} 
                    onUpgrade={(plan) => { setUserPlan(plan); addToast(`Plan upgraded to ${plan.toUpperCase()}.`, 'success'); }}
                    onDowngrade={() => { setUserPlan('free'); addToast('Plan reset to Starter.', 'info'); }}
                    onNavigateDashboard={() => setActiveTab('dashboard')}
                />
            )}

            {activeTab === 'settings' && (
                <Settings 
                    userName={userName}
                    userEmail={userEmail}
                    userAvatar={userAvatar}
                    userAvatarZoom={userAvatarZoom}
                    userAvatarPos={userAvatarPos}
                    userBorder={userBorder}
                    userBackground={userBackground}
                    onUpdateBackground={setUserBackground}
                    userPlan={userPlan}
                    onUpdateProfile={handleUpdateProfile}
                    addToast={addToast}
                    onExportData={handleExportData}
                    onImportData={handleImportData}
                    onClearData={handleClearData}
                    language={language}
                    onUpdateLanguage={setLanguage}
                    currency={currency}
                    onUpdateCurrency={setCurrency}
                    botMode={botMode}
                    onUpdateBotMode={setBotMode}
                    onDowngrade={() => { setUserPlan('free'); addToast('Plan downgraded.', 'info'); }}
                />
            )}
        </div>
      </main>

      <ToastContainer toasts={toasts} onRemove={removeToast} />
    </div>
  );
};

