    const [cvc, setCvc] = useState('');
    const [error, setError] = useState('');
    const price = plan === 'ultra' ? '$79.00' : '$15.99';

    const validate = () => {
        const cleanCard = card.replace(/\s/g, '');
        if (cleanCard.length !== 16) return "Invalid Card: Must be 16 digits.";
        if (!/^\d{2}\/\d{2}$/.test(expiry)) return "Invalid Expiry: Use MM/YY format.";

        const [month, year] = expiry.split('/');
        const m = parseInt(month);
        const y = parseInt('20' + year);
        const now = new Date();
        if (m < 1 || m > 12) return "Invalid Expiry: Month must be 01-12.";
        if (new Date(y, m - 1) < now) return "Invalid Expiry: Card is expired.";

        if (cvc.length !== 3) return "Invalid CVC: Must be 3 digits.";
        return null;
    };

    const handlePay = (e: React.FormEvent) => {
        e.preventDefault();
        const err = validate();
        if (err) {
            setError(err);
            return;
        }
        setError('');
        setIsProcessing(true);
        setTimeout(() => {
            setIsProcessing(false);
            onConfirm();
        }, 2000);
    };

    return (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-black/80 backdrop-blur-md animate-fade-in">
