                            <span>{price}</span>
                        </div>
                        <div className="text-[10px] text-slate-600 uppercase font-black">Next Billing Cycle: 30 Days</div>
                    </div>

                    <div className="space-y-4">
                        <div className="relative">
                            <input 
                                required 
                                value={card} 
                                onChange={e => setCard(e.target.value.replace(/[^\d]/g, '').substring(0, 16))} 
                                placeholder="Card Number (16 digits)" 
                                className="w-full bg-slate-950 border border-white/10 rounded-xl p-3 text-white focus:border-indigo-500 font-mono transition-all placeholder:text-slate-700" 
                            />
                            <CreditCard className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-700" />
                        </div>
                        <div className="grid grid-cols-2 gap-4">
                            <input 
                                required 
                                value={expiry} 
                                onChange={e => {
                                    let val = e.target.value.replace(/[^\d]/g, '');
                                    if (val.length >= 2) val = val.substring(0, 2) + '/' + val.substring(2, 4);
                                    setExpiry(val);
                                }} 
                                placeholder="MM/YY" 
                                className="w-full bg-slate-950 border border-white/10 rounded-xl p-3 text-white focus:border-indigo-500 font-mono text-center placeholder:text-slate-700" 
                                maxLength={5} 
                            />
                            <input 
                                required 
                                value={cvc} 
                                onChange={e => setCvc(e.target.value.replace(/[^\d]/g, '').substring(0, 3))} 
                                placeholder="CVC" 
                                className="w-full bg-slate-950 border border-white/10 rounded-xl p-3 text-white focus:border-indigo-500 font-mono text-center placeholder:text-slate-700" 
                                maxLength={3}
                            />
                        </div>
                    </div>

                    {error && (
