                    <div className="flex items-center justify-center gap-2 text-[10px] text-slate-600 font-medium">
                        <Lock className="w-3 h-3" /> Encrypted via Stripe Secure Core
                    </div>
                 </form>
             </div>
        </div>
    );
};

