const CheckoutModal: React.FC<{ plan: UserPlan, onClose: () => void; onConfirm: () => void }> = ({ plan, onClose, onConfirm }) => {
    const [isProcessing, setIsProcessing] = useState(false);
    const [card, setCard] = useState('');
    const [expiry, setExpiry] = useState('');
    const [cvc, setCvc] = useState('');
    const [error, setError] = useState('');
    const [cardBrand, setCardBrand] = useState<'visa' | 'mastercard' | 'amex' | 'unknown'>('unknown');

    const price = plan === 'ultra' ? '$79.00' : '$15.99';

    useEffect(() => {
        const clean = card.replace(/\s/g, '');
        if (clean.startsWith('4')) setCardBrand('visa');
        else if (clean.startsWith('5') || clean.startsWith('2')) setCardBrand('mastercard');
        else if (clean.startsWith('3')) setCardBrand('amex');
        else setCardBrand('unknown');
    }, [card]);

    const formatCardNumber = (val: string) => {
        const clean = val.replace(/[^\d]/g, '').substring(0, 16);
        return clean.replace(/(.{4})/g, '$1 ').trim();
    };

    const validate = () => {
        const cleanCard = card.replace(/\s/g, '');
        if (cleanCard.length !== 16 && cleanCard.length !== 15) return "Invalid Card Length.";
        if (!/^\d{2}\/\d{2}$/.test(expiry)) return "Use MM/YY format.";

        const [month, year] = expiry.split('/');
        const m = parseInt(month);
        const y = parseInt('20' + year);
        const now = new Date();
        if (m < 1 || m > 12) return "Invalid Month.";
        if (new Date(y, m - 1) < now) return "Card Expired.";
        if (cvc.length < 3) return "CVC too short.";
        return null;
    };

    const handlePay = (e: React.FormEvent) => {
        e.preventDefault();
        const err = validate();
        if (err) {
            setError(err);
            return;
        }
        setError('');
        setIsProcessing(true);
        setTimeout(() => {
            setIsProcessing(false);
            onConfirm();
        }, 2500);
    };

    return (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-black/90 backdrop-blur-xl animate-fade-in">
             <div className="bg-[#020617] w-full max-w-4xl rounded-[2.5rem] border border-white/10 shadow-[0_50px_100px_-20px_rgba(0,0,0,0.8)] overflow-hidden animate-slide-up flex flex-col md:flex-row relative">
                 <button onClick={onClose} className="absolute top-6 right-6 p-2 text-slate-500 hover:text-white transition-colors z-30 bg-slate-900/50 rounded-full"><X className="w-5 h-5" /></button>

                 {/* Visual Preview Side */}
