const CheckoutModal: React.FC<{ plan: UserPlan, onClose: () => void; onConfirm: () => void }> = ({ plan, onClose, onConfirm }) => {
    const [isProcessing, setIsProcessing] = useState(false);
    const [card, setCard] = useState('');
    const [expiry, setExpiry] = useState('');
    const [cvc, setCvc] = useState('');
    const [error, setError] = useState('');
    const [cardBrand, setCardBrand] = useState<'visa' | 'mastercard' | 'amex' | 'unknown'>('unknown');

    const price = plan === 'ultra' ? '$79.00' : '$15.99';

    useEffect(() => {
        const clean = card.replace(/\s/g, '');
        if (clean.startsWith('4')) setCardBrand('visa');
        else if (clean.startsWith('5') || clean.startsWith('2')) setCardBrand('mastercard');
        else if (clean.startsWith('3')) setCardBrand('amex');
        else setCardBrand('unknown');
    }, [card]);

    const formatCardNumber = (val: string) => {
        const clean = val.replace(/[^\d]/g, '').substring(0, 16);
        return clean.replace(/(.{4})/g, '$1 ').trim();
    };

    const luhnCheck = (num: string) => {
      let arr = (num + '')
        .split('')
        .reverse()
        .map(x => parseInt(x));
      let lastDigit = arr.splice(0, 1)[0];
      let sum = arr.reduce((acc, val, i) => (i % 2 !== 0 ? acc + val : acc + ((val * 2) % 9 || (val * 2 === 9 ? 9 : 0))), 0);
      sum += lastDigit;
      return sum % 10 === 0;
    };

    const validate = () => {
        const cleanCard = card.replace(/\s/g, '');

        // Security Check 1: Length and Mod10 Checksum (Luhn Algorithm)
        if (cleanCard.length < 15) return "Card number too short.";
        if (!luhnCheck(cleanCard)) return "Invalid Card: Checksum Failed.";

        // Security Check 2: Expiry Formatting & Logic
        if (!/^\d{2}\/\d{2}$/.test(expiry)) return "Use MM/YY format.";
        const [month, year] = expiry.split('/');
        const m = parseInt(month);
        const y = parseInt('20' + year);
        const now = new Date();
        const expiryDate = new Date(y, m, 0); // End of month
        if (m < 1 || m > 12) return "Invalid Month (01-12).";
        if (expiryDate < now) return "Card has expired.";

        // Security Check 3: CVC Length based on brand
        const expectedCvcLength = cardBrand === 'amex' ? 4 : 3;
        if (cvc.length !== expectedCvcLength) return `CVC must be ${expectedCvcLength} digits for ${cardBrand === 'unknown' ? 'this card' : cardBrand.toUpperCase()}.`;
        if (!/^\d+$/.test(cvc)) return "CVC must be numeric.";

        return null;
    };

    const handlePay = (e: React.FormEvent) => {
        e.preventDefault();
        const err = validate();
        if (err) {
            setError(err);
            return;
        }
        setError('');
        setIsProcessing(true);
        setTimeout(() => {
            setIsProcessing(false);
            onConfirm();
        }, 2500);
    };

