                                <span className="text-[8px] font-black text-white/40 tracking-widest uppercase">Nova Core</span>
                                {cardBrand === 'visa' && <span className="text-white italic font-black text-xl tracking-tighter">VISA</span>}
                                {cardBrand === 'mastercard' && (
