const CheckoutModal: React.FC<{ plan: UserPlan, onClose: () => void; onConfirm: () => void }> = ({ plan, onClose, onConfirm }) => {
    const [isProcessing, setIsProcessing] = useState(false);
    const [processStep, setProcessStep] = useState<string>('');
    const [card, setCard] = useState('');
    const [expiry, setExpiry] = useState('');
    const [cvc, setCvc] = useState('');
    const [error, setError] = useState('');
    const [isShake, setIsShake] = useState(false);
    const [cardBrand, setCardBrand] = useState<'visa' | 'mastercard' | 'amex' | 'unknown'>('unknown');

    const price = plan === 'ultra' ? '$79.00' : '$15.99';

    useEffect(() => {
        const clean = card.replace(/\s/g, '');
        if (clean.startsWith('4')) setCardBrand('visa');
        else if (clean.startsWith('5') || clean.startsWith('2')) setCardBrand('mastercard');
        else if (clean.startsWith('3')) setCardBrand('amex');
        else setCardBrand('unknown');
    }, [card]);

    const formatCardNumber = (val: string) => {
        const clean = val.replace(/[^\d]/g, '').substring(0, 16);
        return clean.replace(/(.{4})/g, '$1 ').trim();
    };

    /**
     * Stricter Luhn Algorithm with guard against common patterns
     */
    const luhnCheck = (num: string) => {
        if (!num || num.length < 15) return false;

        // Guard against all zeros or repeating digits that might pass in loose implementations
        if (/^(\d)\1+$/.test(num)) return false; 

        let sum = 0;
        let shouldDouble = false;
        for (let i = num.length - 1; i >= 0; i--) {
            let digit = parseInt(num.charAt(i));
            if (shouldDouble) {
                if ((digit *= 2) > 9) digit -= 9;
            }
            sum += digit;
            shouldDouble = !shouldDouble;
        }
        return (sum % 10) === 0;
    };

    const validate = () => {
        const cleanCard = card.replace(/\s/g, '');

        // 1. Core Card Number Check
        if (cleanCard.length < 15) return "IDENTITY REJECTED: Card number too short.";
        if (!luhnCheck(cleanCard)) return "SECURITY ALERT: Checksum Mismatch. Random digits detected.";

        // 2. Specific Brand Lengths
        if (cardBrand === 'amex' && cleanCard.length !== 15) return "AMEX UPLINK: Exactly 15 digits required.";
        if ((cardBrand === 'visa' || cardBrand === 'mastercard') && cleanCard.length !== 16) return "GLOBAL NODE: Exactly 16 digits required.";

        // 3. Expiry Validation
        if (!/^\d{2}\/\d{2}$/.test(expiry)) return "FORMAT ERROR: Use MM/YY.";
        const [month, year] = expiry.split('/');
        const m = parseInt(month);
        const y = parseInt('20' + year);
        const now = new Date();
        const expiryDate = new Date(y, m, 0); 
        if (m < 1 || m > 12) return "NODE ERROR: Invalid Expiry Month.";
        if (expiryDate < now) return "ACCESS DENIED: Credentials Expired.";

        // 4. CVC Integrity
        const expectedCvcLength = cardBrand === 'amex' ? 4 : 3;
        if (cvc.length !== expectedCvcLength) return `AUTHORIZATION FAILED: ${cardBrand.toUpperCase()} CVC must be ${expectedCvcLength} digits.`;
        if (!/^\d+$/.test(cvc)) return "LOGIC ERROR: Non-numeric CVC characters.";

        return null;
    };

    const triggerShake = () => {
        setIsShake(true);
        setTimeout(() => setIsShake(false), 500);
    };

    const handlePay = (e: React.FormEvent) => {
        e.preventDefault();
        const err = validate();
        if (err) {
            setError(err);
            triggerShake();
            return;
        }

        setError('');
        setIsProcessing(true);

        // Premium Engagement: Sequential Handshake Logic
        const steps = [
            "Encrypting Session...",
            "Routing through Nova Bank Node...",
            "Verifying Luhn Checksum...",
            "Establishing Secure Tunnel...",
            "Identity Authorized."
        ];

        let stepIdx = 0;
        const interval = setInterval(() => {
            if (stepIdx < steps.length) {
                setProcessStep(steps[stepIdx]);
                stepIdx++;
            } else {
                clearInterval(interval);
                onConfirm();
            }
        }, 700);
    };

    return (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-black/95 backdrop-blur-3xl animate-fade-in">
             <style>{`
                @keyframes shake {
                    0%, 100% { transform: translateX(0); }
                    25% { transform: translateX(-12px); }
                    75% { transform: translateX(12px); }
                }
                .animate-shake { animation: shake 0.2s ease-in-out 0s 2; }

                @keyframes scanner {
                    0% { top: -10%; opacity: 0; }
                    20% { opacity: 1; }
                    80% { opacity: 1; }
                    100% { top: 110%; opacity: 0; }
                }
                .scanner-line {
                    height: 3px;
                    background: linear-gradient(to right, transparent, #6366f1, #818cf8, #6366f1, transparent);
                    position: absolute;
                    width: 100%;
                    z-index: 20;
                    animation: scanner 2.5s ease-in-out infinite;
                    box-shadow: 0 0 20px 2px #6366f1;
                }
             `}</style>

             <div className={`bg-[#020617] w-full max-w-4xl rounded-[3rem] border border-white/10 shadow-[0_50px_100px_-20px_rgba(0,0,0,0.8)] overflow-hidden animate-slide-up flex flex-col md:flex-row relative ${isShake ? 'animate-shake' : ''}`}>
                 <button onClick={onClose} className="absolute top-6 right-6 p-2 text-slate-500 hover:text-white transition-colors z-40 bg-slate-900/50 rounded-full border border-white/5"><X className="w-5 h-5" /></button>

                 {/* Visual Preview Side - "Masterclass" Style */}
                 <div className="w-full md:w-1/2 p-10 bg-gradient-to-br from-[#0a0a0c] via-[#111115] to-[#020204] flex flex-col justify-center items-center relative overflow-hidden border-b md:border-b-0 md:border-r border-white/5">
                    <div className="absolute inset-0 bg-[radial-gradient(circle_at_top_right,rgba(99,102,241,0.1),transparent_60%)]"></div>
                    <div className="absolute inset-0 bg-[url('https://www.transparenttextures.com/patterns/carbon-fibre.png')] opacity-10 pointer-events-none"></div>

                    {/* Dynamic Virtual Card - Highly Polished */}
                    <div className={`w-full max-w-[340px] aspect-[1.58/1] rounded-[1.25rem] relative p-8 flex flex-col justify-between overflow-hidden shadow-2xl transition-all duration-700 transform ${isProcessing ? 'scale-90 brightness-110 shadow-[0_0_60px_rgba(99,102,241,0.3)] rotate-1' : 'hover:scale-[1.03]'} ${
                        cardBrand === 'amex' ? 'bg-gradient-to-br from-[#065f46] to-[#064e3b]' : 
                        cardBrand === 'visa' ? 'bg-gradient-to-br from-[#1e3a8a] to-[#172554]' : 
                        cardBrand === 'mastercard' ? 'bg-gradient-to-br from-[#27272a] to-[#09090b]' : 
                        'bg-gradient-to-br from-[#18181b] to-[#09090b] border border-white/10'
                    }`}>
                        {isProcessing && <div className="scanner-line"></div>}
                        <div className="absolute top-0 right-0 w-48 h-48 bg-white/5 rounded-full -mr-16 -mt-16 blur-3xl"></div>

                        <div className="flex justify-between items-start relative z-10">
                            <div className="w-14 h-10 bg-gradient-to-br from-amber-500 via-amber-200 to-amber-500 rounded-lg shadow-inner flex flex-col justify-center px-1 border border-amber-400/30">
                                <div className="h-[1px] bg-slate-900/20 my-0.5"></div>
                                <div className="h-[1px] bg-slate-900/20 my-0.5"></div>
                                <div className="h-[1px] bg-slate-900/20 my-0.5"></div>
                            </div>
                            <div className="flex flex-col items-end">
                                <span className="text-[10px] font-black text-white/30 tracking-[0.4em] uppercase mb-1">Elite Node</span>
                                {cardBrand === 'visa' && <span className="text-white italic font-black text-3xl tracking-tighter drop-shadow-md">VISA</span>}
                                {cardBrand === 'mastercard' && (
                                    <div className="flex -space-x-3">
                                        <div className="w-9 h-9 rounded-full bg-rose-500/90 shadow-lg border border-white/10"></div>
                                        <div className="w-9 h-9 rounded-full bg-amber-500/90 shadow-lg border border-white/10"></div>
                                    </div>
                                )}
                                {cardBrand === 'amex' && <span className="text-white font-black text-lg border-2 border-white/40 px-3 py-0.5 italic rounded-md shadow-lg">AMEX</span>}
                                {cardBrand === 'unknown' && <CreditCard className="w-8 h-8 text-white/10" />}
                            </div>
                        </div>

                        <div className="relative z-10">
                            <div className={`text-2xl font-mono text-white tracking-[0.25em] mb-6 drop-shadow-[0_4px_8px_rgba(0,0,0,0.8)] transition-all ${isProcessing ? 'blur-[1.5px] scale-105' : ''}`}>
                                {card || '•••• •••• •••• ••••'}
                            </div>
                            <div className="flex justify-between items-end">
                                <div className="flex flex-col">
                                    <span className="text-[8px] font-black text-white/30 uppercase tracking-[0.3em] mb-1">Authorized Pilot</span>
                                    <span className="text-sm font-black text-white uppercase tracking-widest truncate max-w-[150px] drop-shadow-sm">ID: SYSTEM_AUTH</span>
                                </div>
                                <div className="flex flex-col items-end">
                                    <span className="text-[8px] font-black text-white/30 uppercase tracking-[0.3em] mb-1">Deployment Cycle</span>
                                    <span className="text-sm font-black text-white font-mono drop-shadow-sm">{expiry || 'MM/YY'}</span>
                                </div>
                            </div>
                        </div>
                    </div>

                    <div className="mt-12 text-center space-y-6 relative z-10">
                        <div className={`inline-flex items-center gap-2.5 px-5 py-2.5 rounded-full border text-[12px] font-black tracking-[0.25em] uppercase transition-all duration-500 ${isProcessing ? 'bg-indigo-600 text-white shadow-[0_0_30px_rgba(99,102,241,0.6)] border-indigo-400' : 'bg-emerald-500/10 border-emerald-500/20 text-emerald-400 animate-pulse'}`}>
                            {isProcessing ? <><Loader2 className="w-4 h-4 animate-spin" /> {processStep}</> : <><ShieldCheck className="w-4 h-4" /> Secure Tunnel Active</>}
                        </div>
                        <p className="text-slate-500 text-[11px] max-w-[280px] leading-relaxed font-bold uppercase tracking-wider">Synchronizing Premium Logic Tier: <span className="text-white">{plan.toUpperCase()}</span></p>
                    </div>
                 </div>

                 {/* Form Side */}
                 <div className="flex-1 p-10 flex flex-col bg-[#050508]">
                    <div className="mb-10">
                        <div className="flex items-center gap-4 mb-2">
                            <div className="w-10 h-10 rounded-xl bg-indigo-500/10 border border-indigo-500/20 flex items-center justify-center">
                                <Fingerprint className="w-6 h-6 text-indigo-500" />
                            </div>
                            <h2 className="text-2xl font-black text-white tracking-tight uppercase">Authorize Deployment</h2>
                        </div>
                        <p className="text-slate-600 text-[10px] font-black tracking-[0.3em] uppercase ml-1">Establish Encrypted Data Uplink</p>
                    </div>

                    <form onSubmit={handlePay} className="space-y-6 flex-1">
                        <div className="bg-slate-900/40 p-6 rounded-[2.5rem] border border-white/5 flex justify-between items-center group hover:bg-slate-900/60 transition-all cursor-default">
                            <div className="space-y-1">
                                <div className="text-[10px] text-slate-500 font-black uppercase tracking-[0.3em]">Protocol Node</div>
                                <div className="text-xl font-black text-white">{plan.toUpperCase()} <span className="text-indigo-500">SYSTEM</span></div>
                            </div>
                            <div className="text-right space-y-1">
                                <div className="text-[10px] text-slate-500 font-black uppercase tracking-[0.3em]">Monthly Burn</div>
                                <div className="text-3xl font-black text-white tracking-tighter">{price}</div>
                            </div>
                        </div>

                        <div className="space-y-6">
                            <div className="space-y-2.5">
                                <label className="text-[10px] font-black text-slate-500 uppercase tracking-[0.3em] ml-1">Card Access Code</label>
                                <div className="relative group">
                                    <input 
                                        required 
                                        autoFocus
                                        value={card} 
                                        onChange={e => setCard(formatCardNumber(e.target.value))} 
                                        placeholder="0000 0000 0000 0000" 
                                        className="w-full bg-[#020205] border border-white/10 rounded-2xl p-5 text-white focus:border-indigo-500 focus:ring-4 focus:ring-indigo-500/10 font-mono transition-all placeholder:text-slate-900 text-xl shadow-inner" 
                                    />
                                    <div className="absolute right-5 top-1/2 -translate-y-1/2 flex items-center gap-3">
                                        {cardBrand !== 'unknown' && (
                                            <span className="text-[10px] font-black text-white bg-indigo-600 px-3 py-1.5 rounded-lg shadow-xl uppercase tracking-widest animate-fade-in border border-white/10">
                                                {cardBrand} Detected
                                            </span>
                                        )}
                                        <Lock className="w-5 h-5 text-slate-800" />
                                    </div>
                                </div>
                            </div>

                            <div className="grid grid-cols-2 gap-6">
                                <div className="space-y-2.5">
                                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-[0.3em] ml-1">Uplink Expiry</label>
                                    <input 
                                        required 
                                        value={expiry} 
                                        onChange={e => {
                                            let val = e.target.value.replace(/[^\d]/g, '');
                                            if (val.length >= 2) val = val.substring(0, 2) + '/' + val.substring(2, 4);
                                            setExpiry(val);
                                        }} 
                                        placeholder="MM/YY" 
                                        className="w-full bg-[#020205] border border-white/10 rounded-2xl p-5 text-white focus:border-indigo-500 focus:ring-4 focus:ring-indigo-500/10 font-mono text-center placeholder:text-slate-900 text-lg shadow-inner" 
                                        maxLength={5} 
                                    />
                                </div>
                                <div className="space-y-2.5">
                                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-[0.3em] ml-1">Secure Token (CVC)</label>
                                    <input 
                                        required 
                                        value={cvc} 
                                        onChange={e => setCvc(e.target.value.replace(/[^\d]/g, '').substring(0, cardBrand === 'amex' ? 4 : 3))} 
                                        placeholder={cardBrand === 'amex' ? "••••" : "•••"} 
                                        className="w-full bg-[#020205] border border-white/10 rounded-2xl p-5 text-white focus:border-indigo-500 focus:ring-4 focus:ring-indigo-500/10 font-mono text-center placeholder:text-slate-900 text-lg shadow-inner" 
                                        maxLength={cardBrand === 'amex' ? 4 : 3}
                                    />
                                </div>
                            </div>
                        </div>

                        {error && (
                            <div className="bg-rose-500/10 border border-rose-500/20 text-rose-400 p-5 rounded-2xl text-[11px] font-black uppercase tracking-[0.2em] flex items-center gap-4 animate-fade-in shadow-[0_0_30px_rgba(244,63,94,0.1)]">
                                <ShieldX className="w-6 h-6 shrink-0" /> {error}
                            </div>
                        )}

                        <button 
                            disabled={isProcessing} 
                            className="w-full py-6 bg-indigo-600 hover:bg-indigo-500 text-white font-black text-base uppercase tracking-[0.4em] rounded-[2rem] shadow-2xl active:scale-95 transition-all flex items-center justify-center gap-5 disabled:opacity-70 mt-auto relative overflow-hidden group/btn"
                        >
                            {isProcessing ? (
                                <><Loader2 className="w-6 h-6 animate-spin" /> ESTABLISHING UPLINK...</>
                            ) : (
                                <span className="relative z-10 flex items-center gap-5">
                                    Finalize Deployment <ArrowRight className="w-7 h-7 group-hover/btn:translate-x-3 transition-transform" />
