                                {cardBrand === 'amex' && <span className="text-white font-black text-lg border-2 border-white/40 px-3 py-0.5 italic rounded-md shadow-lg">AMEX</span>}
                                {cardBrand === 'unknown' && <CreditCard className="w-8 h-8 text-white/10" />}
                            </div>
                        </div>
                        <div className="relative z-10">
                            <div className={`text-2xl font-mono text-white tracking-[0.25em] mb-6 drop-shadow-[0_4px_8px_rgba(0,0,0,0.8)] transition-all ${isProcessing ? 'blur-[1.5px] scale-105' : ''}`}>{card || '•••• •••• •••• ••••'}</div>
                            <div className="flex justify-between items-end"><div className="flex flex-col"><span className="text-[8px] font-black text-white/30 uppercase tracking-[0.3em] mb-1">Authorized Pilot</span><span className="text-sm font-black text-white uppercase tracking-widest truncate max-w-[150px] drop-shadow-sm">ID: SYSTEM_AUTH</span></div><div className="flex flex-col items-end"><span className="text-[8px] font-black text-white/30 uppercase tracking-[0.3em] mb-1">Deployment Cycle</span><span className="text-sm font-black text-white font-mono drop-shadow-sm">{expiry || 'MM/YY'}</span></div></div>
