                        <div className="space-y-6">
                            <div className="space-y-2.5"><label className="text-[10px] font-black text-slate-500 uppercase tracking-[0.3em] ml-1">Card Access Code</label><div className="relative group"><input required autoFocus value={card} onChange={e => setCard(formatCardNumber(e.target.value))} placeholder="0000 0000 0000 0000" className="w-full bg-[#020205] border border-white/10 rounded-2xl p-5 text-white focus:border-indigo-500 focus:ring-4 focus:ring-indigo-500/10 font-mono transition-all placeholder:text-slate-900 text-xl shadow-inner" /><div className="absolute right-5 top-1/2 -translate-y-1/2 flex items-center gap-3">{cardBrand !== 'unknown' && <span className="text-[10px] font-black text-white bg-indigo-600 px-3 py-1.5 rounded-lg shadow-xl uppercase tracking-widest animate-fade-in border border-white/10">{cardBrand} Detected</span>}<Lock className="w-5 h-5 text-slate-800" /></div></div></div>
