import React, { useState, useEffect, useMemo } from 'react';
import { Transaction, Budget, UserPlan, TransactionType, BotMode, Category } from '../types';
import { Zap, X, AlertOctagon, ArrowRight, ShieldAlert, TrendingUp, Info, Activity, ShieldCheck, Flame, Loader2, MessageCircle } from 'lucide-react';

interface FloatingAssistantProps {
  transactions: Transaction[];
  budgets: Budget[];
  userPlan: UserPlan;
  botMode: BotMode;
  onOpenChat: (initialMessage?: string) => void;
  isVisible: boolean;
  insightUsage: number;
}

interface FinancialAlert {
  id: string;
  type: 'overspend' | 'spike' | 'leak' | 'subscription' | 'forecast';
  riskScore: number;
  title: string;
  message: string;
  contextPayload: string;
}

const FloatingAssistant: React.FC<FloatingAssistantProps> = ({ transactions, budgets, userPlan, botMode, onOpenChat, isVisible, insightUsage }) => {
  const [activeAlert, setActiveAlert] = useState<FinancialAlert | null>(null);
  const [showConfirmation, setShowConfirmation] = useState(false);
  const [isDismissed, setIsDismissed] = useState(false);

  // Local-First Sentinel Logic (0 API COST)
  useEffect(() => {
    if (transactions.length < 5 || isDismissed) return;

    const evaluateSentinelProtocol = () => {
      const now = new Date();
      let highestRisk: FinancialAlert | null = null;

      // 1. Budget Breach Detection
      budgets.forEach(b => {
        const spent = transactions.filter(t => 
            t.category === b.category && 
            t.type === TransactionType.EXPENSE && 
            new Date(t.date).getMonth() === now.getMonth()
        ).reduce((acc, t) => acc + t.amount, 0);

        if (spent > b.limit) {
          const risk = 85;
          if (!highestRisk || risk > highestRisk.riskScore) {
            highestRisk = {
              id: `budget_${b.id}`,
              type: 'overspend',
              riskScore: risk,
              title: botMode === 'ruthless' ? 'Budget Boundary Breached' : 'Spending Alert',
              message: botMode === 'ruthless' 
                ? `System detected overspend in ${b.category}. Capital leak identified.` 
                : `You've spent a bit more on ${b.category} than planned.`,
              contextPayload: `SYSTEM_INTERRUPT: BUDGET_VIOLATION in ${b.category}. Current: ${spent}, Limit: ${b.limit}. Resolve now.`
            };
          }
        }
      });

      // 2. Bill Spike Detection (Heuristic: >30% historical average)
      const merchants = Array.from(new Set(transactions.map(t => t.merchant)));
      merchants.forEach(m => {
          const history = transactions.filter(t => t.merchant === m && t.type === TransactionType.EXPENSE).sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime());
          if (history.length >= 2) {
              const latest = history[0].amount;
              const prev = history[1].amount;
              if (latest > prev * 1.3 && latest > 50) {
                  const risk = 70;
                  if (!highestRisk || risk > highestRisk.riskScore) {
                      highestRisk = {
                          id: `spike_${m}`,
                          type: 'spike',
                          riskScore: risk,
                          title: 'Anomalous Transaction',
                          message: `${m} charge is ${Math.round((latest/prev - 1) * 100)}% higher than previous logic cycle.`,
                          contextPayload: `SYSTEM_INTERRUPT: BILL_SPIKE for ${m}. Latest: ${latest}, Previous: ${prev}. Investigate for errors.`
                      };
                  }
              }
          }
      });

      // 3. Leak Detector (Frequent small transactions)
      const categories = Object.values(Category);
      categories.forEach(c => {
          const monthTxs = transactions.filter(t => t.category === c && t.type === TransactionType.EXPENSE && new Date(t.date).getMonth() === now.getMonth());
          const smallTxs = monthTxs.filter(t => t.amount < 15);
          if (smallTxs.length >= 4) {
              const risk = 60;
              if (!highestRisk || risk > highestRisk.riskScore) {
                  highestRisk = {
                      id: `leak_${c}`,
                      type: 'leak',
                      riskScore: risk,
                      title: 'Capital Leakage',
                      message: `Multiple small-value nodes in ${c} detected. Total leakage: ${smallTxs.reduce((a,b) => a + b.amount, 0)}.`,
                      contextPayload: `SYSTEM_INTERRUPT: LEAK_DETECTOR in ${c}. ${smallTxs.length} small transactions found. Optimize cash flow.`
                  };
              }
          }
      });

      // 4. Irreversibility: Subscription Renewal Detection
      const subs = transactions.filter(t => t.category === Category.SUBSCRIPTION);
      subs.forEach(s => {
          const d = new Date(s.date);
          const nextRenew = new Date(d);
          nextRenew.setMonth(nextRenew.getMonth() + 1);
          const diffDays = Math.ceil((nextRenew.getTime() - now.getTime()) / (1000 * 60 * 60 * 24));
          if (diffDays <= 3 && diffDays > 0) {
              const risk = 95;
              if (!highestRisk || risk > highestRisk.riskScore) {
                  highestRisk = {
                      id: `sub_${s.id}`,
                      type: 'subscription',
                      riskScore: risk,
                      title: 'Irreversible Event Pending',
                      message: `${s.merchant} renewal in ${diffDays} days. Action required to terminate.`,
                      contextPayload: `SYSTEM_INTERRUPT: SUBSCRIPTION_RENEWAL. ${s.merchant} renewing in ${diffDays} days. Verify utility.`
                  };
              }
          }
      });

      setActiveAlert(highestRisk);
    };

    evaluateSentinelProtocol();
  }, [transactions, budgets, isDismissed, botMode]);

  const handleResolveRequest = () => {
    setShowConfirmation(true);
  };

  const handleConfirmAction = () => {
    if (activeAlert) {
      onOpenChat(activeAlert.contextPayload);
    }
    setShowConfirmation(false);
  };

  if (!activeAlert || !isVisible) return null;

  const isCritical = activeAlert.riskScore >= 70;
  const isElite = userPlan === 'ultra';

  return (
    <div className="fixed bottom-24 md:bottom-8 right-8 z-[100] flex flex-col items-end gap-4 animate-fade-in group/assistant">

        {/* The Diagnostic Panel */}
        <div className={`glass-card p-6 rounded-[2rem] border-2 shadow-2xl w-72 mb-2 transition-all duration-500 overflow-hidden relative ${isCritical ? 'border-rose-500/30' : 'border-indigo-500/30'} ${showConfirmation ? 'scale-105' : ''}`}>
             {!showConfirmation ? (
                 <div className="animate-slide-up">
                    <div className="flex justify-between items-center mb-4">
                        <div className={`px-2 py-0.5 rounded-full text-[8px] font-black uppercase tracking-[0.2em] border ${isCritical ? 'bg-rose-500/20 border-rose-500/30 text-rose-400' : 'bg-indigo-500/20 border-indigo-500/30 text-indigo-400'}`}>
                           {isCritical ? 'Priority 0' : 'Observation'}
                        </div>
                        <button onClick={() => { setActiveAlert(null); setIsDismissed(true); }} className="p-1 hover:bg-white/5 rounded-full"><X className="w-3.5 h-3.5 text-slate-500" /></button>
                    </div>
                    <h4 className="text-sm font-black text-white mb-2 leading-tight uppercase tracking-tight">{activeAlert.title}</h4>
                    <p className="text-[11px] text-slate-400 mb-6 leading-relaxed font-medium">{activeAlert.message}</p>
                    <button 
                        onClick={handleResolveRequest}
                        className={`w-full py-3 rounded-xl text-[10px] font-black uppercase tracking-[0.2em] transition-all flex items-center justify-center gap-2 group/btn active:scale-95 ${isCritical ? 'bg-rose-600 hover:bg-rose-500 text-white shadow-lg shadow-rose-900/20' : 'bg-indigo-600 hover:bg-indigo-500 text-white shadow-lg shadow-indigo-900/20'}`}
                    >
                        {botMode === 'ruthless' ? 'Initialize Diagnostic' : 'Help me resolve this'}
                        <ArrowRight className="w-3.5 h-3.5 group-hover/btn:translate-x-1 transition-transform" />
                    </button>
                 </div>
             ) : (
                 <div className="animate-fade-in text-center py-2">
                    <div className="w-10 h-10 bg-indigo-500/20 rounded-xl flex items-center justify-center mx-auto mb-4 border border-indigo-500/30">
                        <Activity className="w-5 h-5 text-indigo-400 animate-pulse" />
                    </div>
                    <h4 className="text-xs font-black text-white mb-2 uppercase tracking-tight">Confirm Action</h4>
                    <p className="text-[10px] text-slate-500 mb-6 font-bold uppercase leading-relaxed px-2">
                        This will use <span className="text-white">1 AI Action</span> for a full neural advisory session.
                    </p>
                    <div className="flex flex-col gap-2">
                        <button onClick={handleConfirmAction} className="w-full py-3 bg-white text-slate-900 text-[10px] font-black uppercase tracking-widest rounded-xl hover:scale-105 active:scale-95 transition-all">Authorize Credit</button>
                        <button onClick={() => setShowConfirmation(false)} className="w-full py-2 text-slate-500 text-[9px] font-black uppercase tracking-widest hover:text-white transition-colors">Cancel</button>
                    </div>
                 </div>
             )}
        </div>

        {/* The Hub Icon */}
        <button 
            onClick={handleResolveRequest}
            className={`w-16 h-16 rounded-[1.5rem] bg-[#020617] border-2 flex items-center justify-center shadow-2xl transition-all relative z-10 active:scale-90 group-hover/assistant:scale-105 ${isCritical ? 'border-rose-500 shadow-[0_0_30px_rgba(244,63,94,0.3)]' : 'border-indigo-500 shadow-[0_0_30px_rgba(99,102,241,0.3)]'}`}
        >
            <div className={`absolute -top-1 -right-1 w-5 h-5 rounded-full flex items-center justify-center text-[8px] font-black text-white shadow-lg z-20 ${isCritical ? 'bg-rose-600 animate-bounce' : 'bg-indigo-600'}`}>!</div>
            <div className="absolute inset-0 bg-gradient-to-br from-white/5 to-transparent rounded-[1.5rem]"></div>
            <Zap className={`w-8 h-8 transition-all duration-500 ${isCritical ? 'text-rose-500 animate-pulse' : 'text-indigo-400 group-hover/assistant:text-white group-hover/assistant:rotate-12'}`} />

            {/* Spinning Ring */}
            <div className={`absolute inset-0 border-2 rounded-[1.5rem] opacity-30 ${isCritical ? 'border-rose-500 animate-[spin_4s_linear_infinite]' : 'border-indigo-500 animate-[spin_8s_linear_infinite]'}`}></div>
        </button>
    </div>
  );
};

