                        {formatCurrency(t.amount)}
                     </span>
                </div>

                <div className="w-full md:col-span-4 flex items-center gap-4 order-1 md:order-2">
                     <div className={`p-2.5 rounded-full border border-white/5 shrink-0 ${t.type === TransactionType.INCOME ? 'bg-emerald-500/10' : 'bg-rose-500/10'}`}>
                        {t.type === TransactionType.INCOME ? <ArrowUpCircle className="w-5 h-5 text-emerald-500" /> : <ArrowDownCircle className="w-5 h-5 text-rose-500" />}
