          ))}
      </div>

      {isAddModalOpen && onAdd && (
        <AddTransactionModal onClose={() => setIsAddModalOpen(false)} onAdd={onAdd} accounts={accounts} onNavigateToAccounts={onNavigateToAccounts} userPlan={userPlan} formatCurrency={formatCurrency} scanUsage={scanUsage} onIncrementScan={onIncrementScan} currency={currency} />
      )}
    </div>
  );
};

const AddTransactionModal: React.FC<{ onClose: () => void; onAdd: (t: Transaction) => void; accounts: Account[]; onNavigateToAccounts?: () => void; userPlan?: UserPlan; formatCurrency: (amount: number) => string; scanUsage: number; onIncrementScan?: () => void; currency: Currency; }> = ({ onClose, onAdd, accounts, onNavigateToAccounts, userPlan, formatCurrency, scanUsage, onIncrementScan, currency }) => {
    const [type, setType] = useState<TransactionType>(TransactionType.EXPENSE);
    const [merchant, setMerchant] = useState('');
    const [amount, setAmount] = useState('');
    const [category, setCategory] = useState<Category | ''>('');
    const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
    const [selectedAccountId, setSelectedAccountId] = useState<string>(accounts[0]?.id || '');
    const [notes, setNotes] = useState('');
    const [isScanning, setIsScanning] = useState(false);
    const fileInputRef = useRef<HTMLInputElement>(null);

    const isUltra = userPlan === 'ultra';
    const isPro = userPlan === 'pro';
    const scanLimit = isUltra ? 1500 : isPro ? 50 : 3;
    const canScan = scanUsage < scanLimit;

    const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;
        setIsScanning(true);
        try {
            const reader = new FileReader();
            reader.readAsDataURL(file);
            reader.onload = async (ev) => {
                const base64 = (ev.target?.result as string).split(',')[1];
                const result = await parseReceiptImage(base64);
                if (result) {
                    setMerchant(result.merchant || '');
                    setAmount(result.amount?.toString() || '');
                    if (result.date) setDate(result.date);
                    if (onIncrementScan) onIncrementScan();
                }
            };
        } finally { setIsScanning(false); }
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (!merchant || !amount || !category) return;
        onAdd({ id: Date.now().toString(), date, merchant, amount: parseFloat(amount), category: category as Category, type, accountId: selectedAccountId || 'manual', notes });
        onClose();
    };

    return (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/80 backdrop-blur-md animate-fade-in">
            <div className="bg-[#0f172a] border border-white/10 rounded-3xl w-full max-w-lg shadow-2xl overflow-hidden animate-slide-up flex flex-col max-h-[90vh]">
                <div className="p-8 border-b border-white/5"><h3 className="text-2xl font-black text-white uppercase tracking-tighter">Log Transaction</h3></div>
                <div className="overflow-y-auto p-8 space-y-6">
                    <div className="relative"><input type="file" accept="image/*" ref={fileInputRef} onChange={handleFileChange} hidden /><button type="button" onClick={() => fileInputRef.current?.click()} disabled={!canScan || isScanning} className={`w-full py-4 rounded-xl border-2 border-dashed transition-all flex items-center justify-center gap-3 ${!canScan ? 'opacity-50 grayscale cursor-not-allowed' : 'border-slate-700 bg-slate-800/30 hover:border-indigo-500'}`}>{isScanning ? <Loader2 className="w-5 h-5 animate-spin" /> : <Camera className="w-5 h-5" />}<span className="text-xs font-black uppercase tracking-widest">{isScanning ? "Scanning..." : !canScan ? "Limit Reached" : "Scan Receipt"}</span></button></div>
                    <form onSubmit={handleSubmit} className="space-y-6">
                        <div className="grid grid-cols-2 gap-4">
                            <div><label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Amount</label><input required type="number" step="0.01" value={amount} onChange={e => setAmount(e.target.value)} className="w-full bg-slate-950 border border-white/10 rounded-xl p-3.5 text-white mt-2" placeholder="0.00" /></div>
                            <div><label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Date</label><input required type="date" value={date} onChange={e => setDate(e.target.value)} className="w-full bg-slate-950 border border-white/10 rounded-xl p-3.5 text-white mt-2 [color-scheme:dark]" /></div>
                        </div>
                        <div><label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Merchant</label><input required type="text" value={merchant} onChange={e => setMerchant(e.target.value)} className="w-full bg-slate-950 border border-white/10 rounded-xl p-3.5 text-white mt-2" placeholder="Starbucks, Apple..." /></div>
                        <div><label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Category</label><select required value={category} onChange={e => setCategory(e.target.value as Category)} className="w-full bg-slate-950 border border-white/10 rounded-xl p-3.5 text-white mt-2">{Object.values(Category).map(c => <option key={c} value={c}>{c}</option>)}</select></div>
                        <button type="submit" className="w-full py-4 bg-indigo-600 hover:bg-indigo-500 text-white font-black text-sm uppercase tracking-[0.2em] rounded-xl transition-all">Archive Entry</button>
                    </form>
                </div>
            </div>
        </div>
    );
};

