            <div className="text-3xl font-bold text-rose-400">{formatCurrency(monthlySpending)}</div>
        </div>
        <div className="glass-card p-6 rounded-3xl border border-white/5">
            <h4 className="text-xs font-bold text-slate-500 uppercase tracking-widest mb-4">Monthly Income</h4>
            <div className="text-3xl font-bold text-emerald-400">{formatCurrency(monthlyIncome)}</div>
        </div>
        <div className="glass-card p-6 rounded-3xl border border-white/5">
