    const [cardBrand, setCardBrand] = useState<'visa' | 'mastercard' | 'amex' | 'unknown'>('unknown');

    const price = plan === 'ultra' ? '$79.00' : '$15.99';

    useEffect(() => {
        const clean = card.replace(/\s/g, '');
        if (clean.startsWith('4')) setCardBrand('visa');
        else if (clean.startsWith('5') || clean.startsWith('2')) setCardBrand('mastercard');
        else if (clean.startsWith('3')) setCardBrand('amex');
        else setCardBrand('unknown');
    }, [card]);

    const formatCardNumber = (val: string) => {
        const clean = val.replace(/[^\d]/g, '').substring(0, 16);
        return clean.replace(/(.{4})/g, '$1 ').trim();
    };

    /**
     * Bulletproof Luhn Algorithm (Mod 10 Check)
     */
    const luhnCheck = (num: string) => {
        let sum = 0;
        let shouldDouble = false;
        // loop through values from right to left
        for (let i = num.length - 1; i >= 0; i--) {
            let digit = parseInt(num.charAt(i));

            if (shouldDouble) {
                if ((digit *= 2) > 9) digit -= 9;
            }

            sum += digit;
            shouldDouble = !shouldDouble;
        }
        return (sum % 10) === 0;
    };

    const validate = () => {
        const cleanCard = card.replace(/\s/g, '');

        // 1. Structural Validation
        if (cleanCard.length < 15) return "Card number too short.";

        // 2. Brand-Specific Length Enforcement
        if (cardBrand === 'amex' && cleanCard.length !== 15) return "Amex requires exactly 15 digits.";
        if ((cardBrand === 'visa' || cardBrand === 'mastercard') && cleanCard.length !== 16) return "Card requires exactly 16 digits.";

        // 3. Algorithmic Validation (Luhn)
        if (!luhnCheck(cleanCard)) return "Invalid Card: Security Checksum Failed.";

        // 4. Expiry Logic
        if (!/^\d{2}\/\d{2}$/.test(expiry)) return "Use MM/YY format.";
        const [month, year] = expiry.split('/');
        const m = parseInt(month);
        const y = parseInt('20' + year);
        const now = new Date();
        const expiryDate = new Date(y, m, 0); // Last day of that month
