import React, { useState, useEffect, useCallback } from 'react';
import { Account, Budget, Goal, Transaction, UserPlan, ToastMessage, BotMode, Currency, Language, TransactionType } from './types';
import { ACCOUNTS, INITIAL_TRANSACTIONS, INITIAL_BUDGETS, INITIAL_GOALS, NAV_ITEMS, TRANSLATIONS } from './constants';
import Dashboard from './components/Dashboard';
import Transactions from './components/Transactions';
import Accounts from './components/Accounts';
import Insights from './components/Insights';
import Goals from './components/Goals';
import Plans from './components/Plans';
import Settings from './components/Settings';
import LandingPage from './components/LandingPage';
import ToastContainer from './components/Toast';
import FloatingAssistant from './components/FloatingAssistant';
import { Sparkles, LogOut, MessageCircle, Zap, Crown, AlertTriangle } from 'lucide-react';

const getMonthlyUsage = (key: string) => {
    try {
        const item = localStorage.getItem(key);
        if (!item) return 0;
        const parsed = JSON.parse(item);
        const now = new Date();
        if (parsed.month !== now.getMonth() || parsed.year !== now.getFullYear()) {
            return 0;
        }
        return parsed.count || 0;
    } catch (e) {
        return 0;
    }
};

const safeSetItem = (key: string, value: string) => {
    try {
        localStorage.setItem(key, value);
    } catch (e) {
        console.warn(`Storage quota exceeded for ${key}`);
    }
};

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');

  const [accounts, setAccounts] = useState<Account[]>(() => {
      const saved = localStorage.getItem('nova_accounts');
      return saved ? JSON.parse(saved) : ACCOUNTS;
  });
  const [transactions, setTransactions] = useState<Transaction[]>(() => {
      const saved = localStorage.getItem('nova_transactions');
      return saved ? JSON.parse(saved) : INITIAL_TRANSACTIONS;
  });
  const [budgets, setBudgets] = useState<Budget[]>(() => {
      const saved = localStorage.getItem('nova_budgets');
      return saved ? JSON.parse(saved) : INITIAL_BUDGETS;
  });
  const [goals, setGoals] = useState<Goal[]>(() => {
      const saved = localStorage.getItem('nova_goals');
      return saved ? JSON.parse(saved) : INITIAL_GOALS;
  });

  const [userPlan, setUserPlan] = useState<UserPlan>(() => localStorage.getItem('nova_user_plan') as UserPlan || 'free');
  const [insightUsage, setInsightUsage] = useState(() => getMonthlyUsage('nova_insight_usage'));
  const [scanUsage, setScanUsage] = useState(() => getMonthlyUsage('nova_scan_usage'));
  const [negotiationUsage, setNegotiationUsage] = useState(() => getMonthlyUsage('nova_negotiation_usage'));

  const [isLoggedIn, setIsLoggedIn] = useState(() => localStorage.getItem('nova_auth_token') !== null);
  const [toasts, setToasts] = useState<ToastMessage[]>([]);
  const [botMode, setBotMode] = useState<BotMode>(() => (localStorage.getItem('nova_bot_mode') as BotMode) || 'ruthless');
  const [pendingChatQuery, setPendingChatQuery] = useState<string | null>(null);

  const [userName, setUserName] = useState(() => localStorage.getItem('nova_user_name') || 'Pilot');
  const [userEmail, setUserEmail] = useState(() => localStorage.getItem('nova_user_email') || 'pilot@nova.io');
  const [userAvatar, setUserAvatar] = useState(() => localStorage.getItem('nova_user_avatar') || '');
  const [userAvatarZoom, setUserAvatarZoom] = useState(1);
  const [userAvatarPos, setUserAvatarPos] = useState({ x: 0, y: 0 });
  const [userBorder, setUserBorder] = useState('default');
  const [userBackground, setUserBackground] = useState(() => localStorage.getItem('nova_user_bg') || '');

  const [currency, setCurrency] = useState<Currency>(() => (localStorage.getItem('nova_currency') as Currency) || 'USD');
  const [language, setLanguage] = useState<Language>(() => (localStorage.getItem('nova_language') as Language) || 'en');

  // Persistence
  useEffect(() => safeSetItem('nova_accounts', JSON.stringify(accounts)), [accounts]);
  useEffect(() => safeSetItem('nova_transactions', JSON.stringify(transactions)), [transactions]);
  useEffect(() => safeSetItem('nova_budgets', JSON.stringify(budgets)), [budgets]);
  useEffect(() => safeSetItem('nova_goals', JSON.stringify(goals)), [goals]);
  useEffect(() => safeSetItem('nova_user_plan', userPlan), [userPlan]);
  useEffect(() => safeSetItem('nova_currency', currency), [currency]);
  useEffect(() => safeSetItem('nova_language', language), [language]);
  useEffect(() => safeSetItem('nova_bot_mode', botMode), [botMode]);

  useEffect(() => {
      const now = new Date();
      const meta = { month: now.getMonth(), year: now.getFullYear(), count: insightUsage };
      safeSetItem('nova_insight_usage', JSON.stringify(meta));
  }, [insightUsage]);

  useEffect(() => {
      const now = new Date();
      const meta = { month: now.getMonth(), year: now.getFullYear(), count: scanUsage };
      safeSetItem('nova_scan_usage', JSON.stringify(meta));
  }, [scanUsage]);

  useEffect(() => {
      const now = new Date();
      const meta = { month: now.getMonth(), year: now.getFullYear(), count: negotiationUsage };
      safeSetItem('nova_negotiation_usage', JSON.stringify(meta));
  }, [negotiationUsage]);

  useEffect(() => safeSetItem('nova_user_bg', userBackground), [userBackground]);

  const addToast = useCallback((message: string, type: 'success' | 'error' | 'info' = 'info') => {
    setToasts(prev => [...prev, { id: Date.now().toString(), message, type }]);
  }, []);

  const removeToast = (id: string) => {
    setToasts(prev => prev.filter(t => t.id !== id));
  };

  const formatCurrency = (amount: number) => {
    const isNoDecimal = currency === 'VND' || currency === 'JPY';
    return new Intl.NumberFormat(language === 'vi' ? 'vi-VN' : 'en-US', { 
        style: 'currency', 
        currency: currency,
        minimumFractionDigits: isNoDecimal ? 0 : 2,
        maximumFractionDigits: isNoDecimal ? 0 : 2,
    }).format(amount);
  };

  const reconcileBalance = (tx: Transaction, direction: 'add' | 'delete') => {
      if (tx.accountId === 'manual') return;
      setAccounts(prev => prev.map(acc => {
          if (acc.id === tx.accountId) {
              const isIncome = tx.type === TransactionType.INCOME;
              let change = tx.amount;
              if (direction === 'add') {
                  change = isIncome ? change : -change;
              } else {
                  change = isIncome ? -change : change;
              }
              return { ...acc, balance: acc.balance + change };
          }
          return acc;
      }));
  };

  const handleAddTransaction = (t: Transaction) => {
      setTransactions(prev => [t, ...prev]);
      reconcileBalance(t, 'add');
      addToast('Entry archived. Balance synchronized.', 'success');
  };

  const handleDeleteTransaction = (id: string) => {
      const tx = transactions.find(t => t.id === id);
      if (tx) {
          reconcileBalance(tx, 'delete');
          setTransactions(prev => prev.filter(t => t.id !== id));
          addToast('Entry purged. Balance reconciled.', 'info');
      }
  };

  const handleLogin = (name: string) => {
    setIsLoggedIn(true);
    setUserName(name);
    localStorage.setItem('nova_user_name', name);
  };

  const handleLogout = () => {
    localStorage.removeItem('nova_auth_token');
    setIsLoggedIn(false);
  };

  const handleUpdateProfile = (name: string, email: string, avatar: string, zoom: number, pos: { x: number; y: number }, border: string) => {
      setUserName(name);
      localStorage.setItem('nova_user_name', name);
      setUserEmail(email);
      localStorage.setItem('nova_user_email', email);
      setUserAvatar(avatar);
      safeSetItem('nova_user_avatar', avatar);
      setUserAvatarZoom(zoom);
      setUserAvatarPos(pos);
      setUserBorder(border);
  };

  const handleAskCoach = (msg: string) => {
      setPendingChatQuery(msg);
      setActiveTab('insights');
  };

  const handleExportData = () => {
    const data = {
      accounts,
      transactions,
      budgets,
      goals,
      userPlan,
      insightUsage,
      scanUsage,
      negotiationUsage,
      userName,
      userEmail,
      userAvatar,
      userAvatarZoom,
      userAvatarPos,
      userBorder,
      userBackground,
      currency,
      language,
      botMode,
    };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `nova_backup_${new Date().toISOString().split('T')[0]}.json`;
    link.click();
    addToast('Vault exported successfully.', 'success');
  };

  const handleImportData = (file: File) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = JSON.parse(e.target?.result as string);
        if (data.accounts) setAccounts(data.accounts);
        if (data.transactions) setTransactions(data.transactions);
        if (data.budgets) setBudgets(data.budgets);
        if (data.goals) setGoals(data.goals);
        if (data.userPlan) setUserPlan(data.userPlan);
        if (data.userName) setUserName(data.userName);
        if (data.userEmail) setUserEmail(data.userEmail);
        if (data.userAvatar) setUserAvatar(data.userAvatar);
        if (data.currency) setCurrency(data.currency);
        if (data.language) setLanguage(data.language);
        if (data.botMode) setBotMode(data.botMode);
        addToast('Vault restored successfully.', 'success');
      } catch (err) {
        addToast('Failed to parse backup file.', 'error');
      }
    };
    reader.readAsText(file);
  };

  const handleClearData = () => {
    setAccounts(ACCOUNTS);
    setTransactions(INITIAL_TRANSACTIONS);
    setBudgets(INITIAL_BUDGETS);
    setGoals(INITIAL_GOALS);
    setUserPlan('free');
    setInsightUsage(0);
    setScanUsage(0);
    setNegotiationUsage(0);
    setBotMode('ruthless');
    setUserName('Pilot');
    setUserEmail('pilot@nova.io');
    setUserAvatar('');
    setUserBackground('');
    setCurrency('USD');
    setLanguage('en');
    localStorage.clear();
    addToast('All data cleared.', 'info');
  };

  const branding = (userPlan === 'ultra' ? {
      icon: <Crown className="w-6 h-6 text-white" />,
      bg: 'bg-gradient-to-tr from-indigo-600 via-purple-600 to-indigo-600',
      label: 'ELITE SYSTEM',
      shadow: 'shadow-indigo-500/40'
  } : userPlan === 'pro' ? {
      icon: <Zap className="w-6 h-6 text-white" />,
      bg: 'bg-gradient-to-tr from-amber-500 to-orange-500',
      label: 'PRO SYSTEM',
      shadow: 'shadow-amber-500/40'
  } : {
      icon: <Sparkles className="w-6 h-6 text-white" />,
      bg: 'bg-gradient-to-tr from-indigo-600 to-violet-600',
      label: 'CORE SYSTEM',
      shadow: 'shadow-indigo-500/20'
  });

  const isApiConfigured = !!process.env.API_KEY;

  if (!isLoggedIn) {
    return <LandingPage onLoginSuccess={handleLogin} />;
  }

  return (
    <div className="flex h-screen bg-[#020617] text-slate-100 font-sans selection:bg-indigo-500/30 overflow-hidden relative">
      {!isApiConfigured && (
          <div className="fixed top-0 left-0 w-full bg-rose-600 text-white text-[10px] font-black py-2 px-4 text-center z-[110] flex items-center justify-center gap-2 shadow-lg uppercase tracking-widest">
              <AlertTriangle className="w-4 h-4" />
              AI Core Offline: Missing API Key. Manual tracking active.
          </div>
      )}

      {userBackground && (
          <div className="absolute inset-0 z-0">
               <img src={userBackground} alt="bg" className="w-full h-full object-cover opacity-40 blur-sm" />
               <div className="absolute inset-0 bg-[#020617]/70"></div>
          </div>
      )}

      {!userBackground && (
          <div className="fixed inset-0 z-0 pointer-events-none bg-[radial-gradient(at_0%_0%,hsla(253,16%,7%,1)_0,transparent_50%),radial-gradient(at_50%_0%,hsla(225,39%,30%,0.3)_0,transparent_50%),radial-gradient(at_100%_0%,hsla(339,49%,30%,0.3)_0,transparent_50%)]">
             <div className="absolute top-[-10%] left-[-10%] w-[50%] h-[50%] bg-indigo-900/10 rounded-full blur-[120px] animate-pulse-slow"></div>
             <div className="absolute bottom-[-10%] right-[-10%] w-[50%] h-[50%] bg-purple-900/10 rounded-full blur-[120px] animate-pulse-slow" style={{ animationDelay: '1s' }}></div>
          </div>
      )}

      <FloatingAssistant 
          transactions={transactions}
          budgets={budgets}
          userPlan={userPlan}
          botMode={botMode}
          isVisible={activeTab !== 'insights'}
          onOpenChat={handleAskCoach}
          insightUsage={insightUsage}
      />

      <aside className="hidden md:flex flex-col w-64 p-4 z-20 bg-slate-950/40 backdrop-blur-md border-r border-white/5 relative">
        <div className="flex items-center gap-3 px-4 py-3 mb-8">
            <div className={`w-10 h-10 rounded-xl flex items-center justify-center shadow-lg ring-1 ring-white/10 ${branding.bg} ${branding.shadow}`}>
                {branding.icon}
            </div>
            <div>
                <h1 className="text-xl font-bold tracking-tight text-white">Nova AI</h1>
                <p className={`text-[10px] font-bold uppercase tracking-wider ${userPlan === 'ultra' ? 'text-purple-400' : userPlan === 'pro' ? 'text-amber-400' : 'text-slate-500'}`}>
                    {branding.label}
                </p>
            </div>
        </div>
        <nav className="flex-1 space-y-1">
            {NAV_ITEMS.map((item) => {
                const isActive = activeTab === item.id;
                const label = TRANSLATIONS[language]?.[item.id as keyof typeof TRANSLATIONS['en']] || item.label;
                return (
                    <button
                        key={item.id}
                        onClick={() => setActiveTab(item.id)}
                        className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold transition-all duration-300 group ${isActive ? 'bg-indigo-600/10 text-indigo-400 shadow-[0_0_20px_rgba(99,102,241,0.15)] ring-1 ring-indigo-500/20' : 'text-slate-400 hover:text-white hover:bg-white/5'}`}
                    >
                        <item.icon className={`w-5 h-5 transition-colors ${isActive ? 'text-indigo-400' : 'text-slate-500 group-hover:text-white'}`} />
                        {label}
                    </button>
                );
            })}
        </nav>
        <div className="mt-auto pt-6 border-t border-white/5">
             <button onClick={() => setActiveTab('settings')} className="w-full text-left px-4 py-4 rounded-2xl bg-slate-900/50 border border-white/5 flex items-center gap-3 mb-4 hover:bg-slate-800 transition-colors group">
                 <div className="w-10 h-10 rounded-full bg-indigo-500 flex items-center justify-center text-white overflow-hidden relative border border-white/10 shadow-inner">
                     {userAvatar ? (
                         <img src={userAvatar} className="w-full h-full object-cover" alt="User" style={{ transform: `scale(${userAvatarZoom}) translate(${userAvatarPos.x}px, ${userAvatarPos.y}px)` }} />
                     ) : (
                         <span className="font-bold text-lg">{userName.charAt(0)}</span>
                     )}
                 </div>
                 <div className="overflow-hidden">
                     <h4 className="font-bold text-white text-sm truncate group-hover:text-indigo-400 transition-colors">{userName}</h4>
                     <p className="text-[10px] text-slate-500 truncate font-bold uppercase tracking-widest">{userPlan} tier</p>
                 </div>
             </button>
             <button onClick={handleLogout} className="w-full flex items-center gap-2 px-4 py-2 text-xs font-bold text-slate-500 hover:text-rose-400 transition-colors uppercase tracking-widest">
                 <LogOut className="w-4 h-4" /> {TRANSLATIONS[language]?.signOut || 'Sign Out'}
             </button>
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 z-10 relative overflow-hidden">
        <div className="flex-1 overflow-y-auto p-4 md:p-8 pb-24 md:pb-8 custom-scrollbar">
            {activeTab === 'dashboard' && <Dashboard accounts={accounts} transactions={transactions} onNavigate={setActiveTab} onAddAccount={() => setActiveTab('accounts')} onAddTransaction={() => setActiveTab('transactions')} onAddGoal={() => setActiveTab('goals')} formatCurrency={formatCurrency} userPlan={userPlan} onAskCoach={handleAskCoach} negotiationUsage={negotiationUsage} onIncrementNegotiation={() => setNegotiationUsage(prev => prev + 1)} />}
            {activeTab === 'transactions' && <Transactions transactions={transactions} accounts={accounts} onDelete={handleDeleteTransaction} onAdd={handleAddTransaction} formatCurrency={formatCurrency} onNavigateToAccounts={() => setActiveTab('accounts')} userPlan={userPlan} scanUsage={scanUsage} onIncrementScan={() => setScanUsage(prev => prev + 1)} currency={currency} />}
            {activeTab === 'accounts' && <Accounts accounts={accounts} budgets={budgets} transactions={transactions} userPlan={userPlan} onAdd={(acc) => { setAccounts(prev => [...prev, acc]); addToast('Account bridged.', 'success'); }} onUpdate={(acc) => { setAccounts(prev => prev.map(a => a.id === acc.id ? acc : a)); addToast('Account updated.', 'success'); }} onDelete={(id) => { setAccounts(prev => prev.filter(a => a.id !== id)); setTransactions(prev => prev.map(t => t.accountId === id ? { ...t, accountId: 'manual' } : t)); addToast('Account disconnected. History preserved.', 'info'); }} formatCurrency={formatCurrency} userName={userName} userAvatar={userAvatar} userAvatarZoom={userAvatarZoom} userAvatarPos={userAvatarPos} userBorder={userBorder} onNavigate={setActiveTab} />}
            {activeTab === 'insights' && <Insights transactions={transactions} userPlan={userPlan} onUpgradeClick={() => setActiveTab('plans')} formatCurrency={formatCurrency} insightUsage={insightUsage} onIncrementUsage={() => setInsightUsage(prev => prev + 1)} onApplyBudgets={(newBudgets) => { const existingCats = new Set(budgets.map(b => b.category)); const toAdd = newBudgets.filter(b => !existingCats.has(b.category)); setBudgets(prev => [...prev, ...toAdd]); addToast(`Applied ${toAdd.length} AI limits.`, 'success'); }} initialPrompt={pendingChatQuery} onPromptHandled={() => setPendingChatQuery(null)} botMode={botMode} />}
            {activeTab === 'goals' && <Goals goals={goals} budgets={budgets} transactions={transactions} onAddGoal={(g) => { setGoals(prev => [...prev, g]); addToast('Goal deployed.', 'success'); }} onUpdateGoal={(g) => { setGoals(prev => prev.map(goal => goal.id === g.id ? g : goal)); addToast('Goal updated.', 'success'); }} onAddBudget={(b) => { setBudgets(prev => [...prev, b]); addToast('Limit set.', 'success'); }} onDeleteBudget={(id) => { setBudgets(prev => prev.filter(b => b.id !== id)); addToast('Limit removed.', 'info'); }} formatCurrency={formatCurrency} />}
            {activeTab === 'plans' && <Plans currentPlan={userPlan} onUpgrade={(plan) => { setUserPlan(plan); addToast(`Plan upgraded to ${plan.toUpperCase()}.`, 'success'); }} onDowngrade={() => { setUserPlan('free'); addToast('Plan reset to Starter.', 'info'); }} onNavigateDashboard={() => setActiveTab('dashboard')} />}
            {activeTab === 'settings' && <Settings userName={userName} userEmail={userEmail} userAvatar={userAvatar} userAvatarZoom={userAvatarZoom} userAvatarPos={userAvatarPos} userBorder={userBorder} userBackground={userBackground} onUpdateBackground={setUserBackground} userPlan={userPlan} onUpdateProfile={handleUpdateProfile} addToast={addToast} onExportData={handleExportData} onImportData={handleImportData} onClearData={handleClearData} language={language} onUpdateLanguage={setLanguage} currency={currency} onUpdateCurrency={setCurrency} botMode={botMode} onUpdateBotMode={setBotMode} onDowngrade={() => { setUserPlan('free'); addToast('Plan downgraded.', 'info'); }} />}
        </div>
      </main>
      <ToastContainer toasts={toasts} onRemove={removeToast} />
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { Transaction, AIAnalysisResponse, ChatMessage, UserPlan, TransactionType, Budget, BotMode } from '../types';
import { analyzeFinancialData, chatWithFinancialCoach } from '../services/geminiService';
import { RefreshCcw, CheckCircle, AlertTriangle, ShieldAlert, Info, TrendingUp, Bot, User, BrainCircuit, Lightbulb, Send, Lock, Sparkles, RefreshCw, Flame, ArrowRight, Zap, Crown } from 'lucide-react';

interface InsightsProps {
  transactions: Transaction[];
  userPlan: UserPlan;
  onUpgradeClick: () => void;
  formatCurrency: (amount: number) => string;
  initialPrompt?: string | null; 
  onPromptHandled?: () => void; 
  onApplyBudgets?: (budgets: Budget[]) => void; 
  insightUsage: number; 
  onIncrementUsage: () => void; 
  botMode: BotMode; 
}

const Insights: React.FC<InsightsProps> = ({ transactions, userPlan, onUpgradeClick, formatCurrency, initialPrompt, onPromptHandled, onApplyBudgets, insightUsage, onIncrementUsage, botMode }) => {
  const [analysis, setAnalysis] = useState<AIAnalysisResponse | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [chatInput, setChatInput] = useState('');
  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([
    { id: '1', role: 'assistant', content: 'Hello! I\'m Nova. I\'ve analyzed your recent spending patterns. Ask me anything—should you buy that coffee? How is your debt looking?', timestamp: new Date() }
  ]);
  const [chatLoading, setChatLoading] = useState(false);
  const chatEndRef = useRef<HTMLDivElement>(null);

  const isUltra = userPlan === 'ultra';
  const isPro = userPlan === 'pro';

  // Industrial Grade Limits
  const FREE_LIMIT = 3;
  const PRO_LIMIT = 50;
  const ULTRA_LIMIT = 1500;

  const currentLimit = isUltra ? ULTRA_LIMIT : isPro ? PRO_LIMIT : FREE_LIMIT;
  const isLocked = insightUsage >= currentLimit;

  const burnoutData = useMemo(() => {
    const expenseMap = new Map<string, number>();
    transactions
        .filter(t => t.type === TransactionType.EXPENSE)
        .forEach(t => {
            expenseMap.set(t.category, (expenseMap.get(t.category) || 0) + t.amount);
        });

    let maxCat = '';
    let maxAmount = 0;
    expenseMap.forEach((val, key) => {
        if (val > maxAmount) {
            maxAmount = val;
            maxCat = key;
        }
    });
    return { category: maxCat, amount: maxAmount };
  }, [transactions]);

  const runAnalysis = async () => {
    if (isLocked) return;
    setLoading(true);
    setError(null);
    onIncrementUsage();
    try {
      const result = await analyzeFinancialData(transactions);
      if (result) {
        setAnalysis(result);
      } else {
        setError("Coach is analyzing other portfolios. Try again.");
      }
    } catch (e) {
      setError("Unable to connect to financial brain.");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if ((isPro || isUltra) && !analysis && !isLocked) runAnalysis();
  }, [isPro, isUltra]);

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [chatHistory, chatLoading]);

  useEffect(() => {
      if (!isLocked && initialPrompt && !chatLoading) {
          handleSendMessage(null, initialPrompt);
          if (onPromptHandled) onPromptHandled();
      }
  }, [initialPrompt, isLocked]);

  const handleSendMessage = async (e: React.FormEvent | null, promptOverride?: string) => {
    if (e) e.preventDefault();
    const content = promptOverride || chatInput;
    if (!content.trim() || isLocked) return;

    onIncrementUsage();
    const userMsg: ChatMessage = { id: Date.now().toString(), role: 'user', content: content, timestamp: new Date() };
    setChatHistory(prev => [...prev, userMsg]);
    setChatInput('');
    setChatLoading(true);

    const responseText = await chatWithFinancialCoach(userMsg.content, transactions, botMode);
    const aiMsg: ChatMessage = { id: (Date.now() + 1).toString(), role: 'assistant', content: responseText, timestamp: new Date() };
    setChatHistory(prev => [...prev, aiMsg]);
    setChatLoading(false);
  };

  const handleAutoTune = () => {
      if (!analysis || !onApplyBudgets) return;
      const newBudgets: Budget[] = analysis.budget_suggestions.map(bs => ({
          id: `ai_${Date.now()}_${bs.category}`,
          category: bs.category as any,
          limit: bs.suggested_limit
      }));
      onApplyBudgets(newBudgets);
  };

  const getColorClass = (type: string) => {
    switch (type) {
        case 'success': return 'bg-emerald-500/10 border-emerald-500/20 text-emerald-100 shadow-[0_4px_20px_rgba(16,185,129,0.1)]';
        case 'warning': return 'bg-amber-500/10 border-amber-500/20 text-amber-100 shadow-[0_4px_20px_rgba(245,158,11,0.1)]';
        case 'critical': return 'bg-rose-500/10 border-rose-500/20 text-rose-100 shadow-[0_4px_20px_rgba(244,63,94,0.1)]';
        default: return 'bg-blue-500/10 border-blue-500/20 text-blue-100 shadow-[0_4px_20px_rgba(59,130,246,0.1)]';
    }
  };

  const getIconForType = (type: string) => {
      switch (type) {
        case 'success': return <CheckCircle className="w-5 h-5 text-emerald-400" />;
        case 'warning': return <AlertTriangle className="w-5 h-5 text-amber-400" />;
        case 'critical': return <ShieldAlert className="w-5 h-5 text-rose-400" />;
        default: return <Info className="w-5 h-5 text-blue-400" />;
      }
    };

  return (
    <div className="relative h-[calc(100vh-8rem)]">
      {isLocked && (
        <div className="absolute inset-0 z-50 flex items-center justify-center bg-slate-950/60 backdrop-blur-xl rounded-[2rem] border border-white/10 transform scale-105 transition-transform duration-500">
            <div className="text-center p-8 max-w-md animate-slide-up">
                <div className="w-20 h-20 rounded-3xl bg-gradient-to-tr from-indigo-500 to-purple-500 flex items-center justify-center mx-auto mb-6 shadow-2xl shadow-indigo-500/40"><Lock className="w-10 h-10 text-white" /></div>
                <h2 className="text-3xl font-bold text-white mb-3">Limit Reached</h2>
                <p className="text-slate-400 mb-8 leading-relaxed">
                    You've hit your monthly cap of {currentLimit} interactions for your {userPlan.toUpperCase()} plan. Upgrade or manage your plan to continue using the AI Coach.
                </p>
                {!isUltra && (
                    <button onClick={onUpgradeClick} className="w-full py-4 bg-white text-indigo-900 font-bold rounded-xl shadow-xl hover:scale-[1.02] active:scale-95 transition-all flex items-center justify-center gap-2 group"><Sparkles className="w-5 h-5 text-indigo-600 group-hover:rotate-12 transition-transform" />Upgrade Plan</button>
                )}
            </div>
        </div>
      )}

      <div className={`grid grid-cols-1 lg:grid-cols-3 gap-8 pb-10 h-full transition-all duration-500 ${isLocked ? 'blur-md opacity-50 pointer-events-none select-none overflow-hidden' : ''}`}>
        <div className="lg:col-span-2 overflow-y-auto custom-scrollbar space-y-8 pr-2">
            <div className="flex justify-between items-center bg-gradient-to-r from-indigo-900/60 via-slate-900/60 to-slate-900/60 p-8 rounded-3xl border border-white/10 backdrop-blur-md shadow-2xl relative overflow-hidden group">
                <div className="absolute inset-0 bg-gradient-to-r from-indigo-500/10 to-transparent opacity-0 group-hover:opacity-100 transition-opacity"></div>
                <div className="relative z-10">
                    <h2 className="text-2xl font-bold text-white flex items-center gap-3"><BrainCircuit className="w-8 h-8 text-indigo-400" />Financial Wellness</h2>
                    <p className="text-slate-400 text-sm mt-2 ml-11 max-w-md font-medium">Real-time AI analysis of your spending habits and risk profile.</p>
                    <div className={`mt-3 ml-11 inline-flex items-center gap-2 px-3 py-1 rounded-full text-[10px] font-bold uppercase tracking-widest border ${isUltra ? 'bg-indigo-500/10 border-indigo-500/20 text-indigo-400' : isPro ? 'bg-amber-500/10 border-amber-500/20 text-amber-400' : 'bg-slate-700/50 border-white/10 text-slate-400'}`}>
                         {isUltra ? <Crown className="w-3 h-3" /> : isPro ? <Zap className="w-3 h-3" /> : null}
                         {userPlan.toUpperCase()} Usage: {insightUsage}/{currentLimit} Used
                    </div>
                </div>
                <button onClick={runAnalysis} disabled={loading} className="p-3.5 bg-slate-800/80 hover:bg-indigo-600 rounded-2xl transition-all border border-white/10 group shadow-lg active:scale-95 relative z-10"><RefreshCcw className={`w-5 h-5 text-slate-300 group-hover:text-white transition-colors ${loading ? 'animate-spin' : ''}`} /></button>
            </div>

            {loading && (
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6 animate-pulse">
                    <div className="h-48 glass-card rounded-3xl bg-slate-800/30"></div>
                    <div className="h-48 glass-card rounded-3xl bg-slate-800/30"></div>
                    <div className="h-64 md:col-span-2 glass-card rounded-3xl bg-slate-800/30"></div>
                </div>
            )}

            {analysis && !loading && (
            <div className="animate-fade-in space-y-8">
                <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                    <div className="glass-card p-6 rounded-3xl relative overflow-hidden group border-indigo-500/10 hover:border-indigo-500/30 transition-all hover:shadow-[0_0_40px_rgba(79,70,229,0.15)]">
                        <h3 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-4">Risk Matrix</h3>
                        <div className="flex items-center gap-4">
                            <div className="relative w-16 h-16 flex items-center justify-center shrink-0">
                                <svg className="w-full h-full transform -rotate-90 filter drop-shadow-md">
                                    <circle cx="32" cy="32" r="28" stroke="currentColor" strokeWidth="6" fill="transparent" className="text-slate-800/50" />
                                    <circle cx="32" cy="32" r="28" stroke="currentColor" strokeWidth="6" fill="transparent" className={`${analysis.risk_score > 50 ? 'text-rose-500' : 'text-emerald-500'} transition-all duration-1000 ease-out`} strokeDasharray={175.9} strokeDashoffset={175.9 - (175.9 * analysis.risk_score) / 100} strokeLinecap="round" />
                                </svg>
                                <span className="absolute text-lg font-bold text-white tracking-tighter">{Math.round(analysis.risk_score)}</span>
                            </div>
                            <div className="flex-1 min-w-0">
                                <h4 className={`text-lg font-bold ${analysis.risk_score > 50 ? 'text-rose-400' : 'text-emerald-400'} mb-1`}>{analysis.risk_score > 50 ? 'Critical' : 'Stable'}</h4>
                                <p className="text-[10px] text-slate-400 font-medium">System Health</p>
                            </div>
                        </div>
                    </div>

                    <div className="glass-card p-6 rounded-3xl relative overflow-hidden border-indigo-500/10 hover:border-indigo-500/30 transition-all group">
                         <h3 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-4">Trajectory (30d)</h3>
                         <div className="text-3xl font-bold text-white tracking-tight">{formatCurrency(analysis.predicted_spend_next_month).replace(/\.00$/, '')}</div>
                         <p className="text-[10px] text-slate-500 mt-2 font-medium flex items-center gap-1.5"><TrendingUp className="w-3 h-3 text-indigo-400" /> Forecasted Burn</p>
                    </div>

                    <div className="glass-card p-6 rounded-3xl relative overflow-hidden border-rose-500/10 hover:border-rose-500/30 transition-all group bg-rose-500/5">
                        <div className="absolute top-0 right-0 w-32 h-32 bg-rose-500/10 rounded-full blur-2xl -mr-8 -mt-8 pointer-events-none"></div>
                        <h3 className="text-[10px] font-bold text-rose-300 uppercase tracking-widest mb-4 flex items-center gap-1.5"><Flame className="w-3 h-3 text-rose-500" /> Burnout Alert</h3>
                        <div className="text-xl font-bold text-white tracking-tight truncate">{burnoutData.category || 'N/A'}</div>
                        <p className="text-[10px] text-slate-400 mt-1 font-medium">{formatCurrency(burnoutData.amount)} consumed</p>
                    </div>
                </div>

                <div>
                    <h3 className="text-lg font-bold text-white mb-5 px-1 flex items-center gap-2"><Lightbulb className="w-5 h-5 text-amber-400" />Strategic Insights</h3>
                    <div className="grid grid-cols-1 gap-4">
                        {analysis.insights.map((insight, idx) => (
                            <div key={idx} className={`p-6 rounded-2xl border flex gap-5 backdrop-blur-md transition-all hover:translate-x-1 hover:shadow-lg ${getColorClass(insight.type)}`}>
                                <div className="mt-0.5 shrink-0 bg-white/10 p-2.5 rounded-xl h-fit ring-1 ring-white/10 shadow-sm">{getIconForType(insight.type)}</div>
                                <div>
                                    <h4 className="font-bold text-base mb-1.5">{insight.title}</h4>
                                    <p className="text-sm opacity-90 leading-relaxed font-medium">{insight.description}</p>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>

                <div>
                    <div className="flex items-center justify-between mb-5 px-1">
                        <h3 className="text-lg font-bold text-white flex items-center gap-2"><TrendingUp className="w-5 h-5 text-indigo-400" />Optimization Opportunities</h3>
                        {analysis.budget_suggestions.length > 0 && onApplyBudgets && (
                            <button onClick={handleAutoTune} className="text-xs font-bold text-indigo-300 bg-indigo-500/20 hover:bg-indigo-500/30 border border-indigo-500/30 px-3 py-1.5 rounded-lg transition-all flex items-center gap-1.5 active:scale-95"><Sparkles className="w-3 h-3" /> Auto-Tune Limits</button>
                        )}
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
                        {analysis.budget_suggestions.map((budget, idx) => (
                            <div key={idx} className="bg-slate-900/40 p-6 rounded-3xl border border-white/5 hover:border-indigo-500/30 transition-all hover:shadow-[0_4px_25px_rgba(99,102,241,0.15)] group relative overflow-hidden">
                                <div className="flex justify-between mb-4 relative z-10">
                                    <span className="text-xs font-bold text-indigo-200 bg-indigo-500/20 px-3 py-1 rounded-lg uppercase tracking-wide border border-indigo-500/20">{budget.category}</span>
                                    <span className="text-xs text-rose-300 font-bold bg-rose-500/20 px-3 py-1 rounded-lg border border-rose-500/20">{formatCurrency(Math.max(0, budget.current_spend - budget.suggested_limit))} cut needed</span>
                                </div>
                                <p className="text-slate-300 text-sm mb-6 line-clamp-2 font-medium relative z-10">"{budget.reason}"</p>
                                <div className="space-y-2 relative z-10">
                                    <div className="flex justify-between text-[10px] text-slate-400 font-bold uppercase tracking-wider"><span>Target Limit</span><span>Current</span></div>
                                    <div className="w-full bg-slate-800 h-2.5 rounded-full overflow-hidden flex border border-white/5">
