import React, { useState, useRef, useEffect } from 'react';
import { Transaction, TransactionType, Category, Account, UserPlan, Currency } from '../types';
import { Search, ArrowUpCircle, ArrowDownCircle, Filter, Calendar, Trash2, Tag, Plus, X, Check, DollarSign, Wallet, FileText, Sparkles, Loader2, StickyNote, ArrowUp, ArrowDown, Camera, AlertCircle, ScanLine } from 'lucide-react';
import { categorizeTransaction, parseReceiptImage } from '../services/geminiService';

interface TransactionsProps {
  transactions: Transaction[];
  accounts?: Account[]; 
  onDelete?: (id: string) => void;
  onAdd?: (transaction: Transaction) => void;
  formatCurrency: (amount: number) => string;
  onNavigateToAccounts?: () => void;
