import { Microscope, Play, RefreshCw, Zap, TrendingUp, DollarSign, ShoppingCart, ArrowUpRight, ArrowDownRight, Target, Lock, Sparkles, ChevronRight } from 'lucide-react';

interface SandboxProps {
  transactions: Transaction[];
  goals: Goal[];
  formatCurrency: (amount: number) => string;
  userPlan: UserPlan;
  onUpgradeClick: () => void;
}

const ScenarioSandbox: React.FC<SandboxProps> = ({ transactions, goals, formatCurrency, userPlan, onUpgradeClick }) => {
  const [params, setParams] = useState({
    monthlyExtraSpend: 0,
    oneTimePurchase: 0,
    extraIncome: 0,
    selectedGoalId: goals[0]?.id || null,
  });

  const isElite = userPlan === 'ultra';

  // Simulation Logic
  const simData = useMemo(() => {
    const dataPoints: any[] = [];
    const now = new Date();

    // Baseline: Historical monthly burn
    const monthlyExpenses = transactions
      .filter(t => t.type === TransactionType.EXPENSE && new Date(t.date).getMonth() === now.getMonth())
      .reduce((acc, curr) => acc + curr.amount, 0);

    let currentBalance = 10000; // Mock current liquidity for simulation
    let simBalance = 10000;

    for (let i = 0; i <= 6; i++) {
        const month = new Date(now.getFullYear(), now.getMonth() + i, 1);
        const label = month.toLocaleDateString('en-US', { month: 'short' });

        // Baseline calc
        const baselineNet = (monthlyExpenses * 0.8) - monthlyExpenses; // Simplified burn
        currentBalance += baselineNet;

        // Simulation calc
        const simNet = (monthlyExpenses * 0.8) + params.extraIncome - (monthlyExpenses + params.monthlyExtraSpend);
        const oneTimeCost = i === 0 ? params.oneTimePurchase : 0;
        simBalance += (simNet - oneTimeCost);

        dataPoints.push({
            name: label,
            Baseline: Math.max(0, currentBalance),
            Simulation: Math.max(0, simBalance),
        });
    }
    return dataPoints;
  }, [transactions, params]);

  const selectedGoal = goals.find(g => g.id === params.selectedGoalId);

  const impact = useMemo(() => {
    if (!selectedGoal) return null;
    const remaining = selectedGoal.targetAmount - selectedGoal.currentAmount;
    const standardSavings = 500; // Mock
    const simSavings = standardSavings + params.extraIncome - params.monthlyExtraSpend;

    const standardMonths = remaining / standardSavings;
    const simMonths = remaining / Math.max(1, simSavings);

    const diff = simMonths - standardMonths;
    return {
        days: Math.abs(Math.round(diff * 30)),
        direction: diff > 0 ? 'delay' : 'acceleration',
        months: Math.abs(diff).toFixed(1)
    };
  }, [selectedGoal, params]);

  if (userPlan === 'free') {
      return (
          <div className="h-[calc(100vh-12rem)] flex items-center justify-center">
              <div className="glass-card max-w-md p-10 rounded-[3rem] text-center border border-indigo-500/20">
                  <div className="w-20 h-20 bg-gradient-to-tr from-indigo-500 to-purple-600 rounded-[2rem] flex items-center justify-center mx-auto mb-8 shadow-2xl">
                      <Lock className="w-10 h-10 text-white" />
                  </div>
                  <h3 className="text-2xl font-black text-white mb-4">Neural Sandbox Locked</h3>
                  <p className="text-slate-400 mb-8 font-medium">Predictive simulations require a Pro or Elite uplink. Unlock the Sandbox to project your trajectory.</p>
                  <button onClick={onUpgradeClick} className="w-full py-4 bg-white text-slate-950 font-black rounded-2xl hover:scale-105 active:scale-95 transition-all shadow-xl flex items-center justify-center gap-2">
                      <Zap className="w-5 h-5 fill-indigo-600 text-indigo-600" /> Upgrade Now
                  </button>
              </div>
          </div>
      );
  }

  return (
    <div className="animate-slide-up pb-20 space-y-10">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-end gap-6">
        <div>
          <h2 className="text-3xl font-black text-white tracking-tighter flex items-center gap-3">
             <Microscope className="w-8 h-8 text-indigo-400" />
             Predictive Sandbox
          </h2>
          <p className="text-slate-400 mt-2 font-medium">Simulate financial choices to see their multi-month impact.</p>
        </div>
        <div className="flex gap-3">
             <button 
                onClick={() => setParams({ monthlyExtraSpend: 0, oneTimePurchase: 0, extraIncome: 0, selectedGoalId: goals[0]?.id || null })}
                className="px-4 py-2 bg-slate-900 border border-white/5 text-slate-400 rounded-xl text-xs font-bold hover:text-white transition-all flex items-center gap-2"
             >
                <RefreshCw className="w-4 h-4" /> Reset Sim
             </button>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-10">

        {/* Sliders / Input Side */}
        <div className="space-y-6">
            <div className="glass-card p-8 rounded-[2.5rem] border border-white/10 relative overflow-hidden">
                <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-indigo-500 to-purple-500 opacity-50"></div>
                <h3 className="text-sm font-black text-slate-400 uppercase tracking-[0.2em] mb-8">Simulation Vectors</h3>

                <div className="space-y-10">
                    <SliderInput 
                        label="Monthly Extra Burn" 
                        icon={<TrendingUp className="w-4 h-4 text-rose-400" />}
                        value={params.monthlyExtraSpend}
                        max={5000}
                        step={50}
                        onChange={(v) => setParams(p => ({ ...p, monthlyExtraSpend: v }))}
                        format={formatCurrency}
                    />
                    <SliderInput 
                        label="One-time Acquisition" 
                        icon={<ShoppingCart className="w-4 h-4 text-amber-400" />}
                        value={params.oneTimePurchase}
                        max={10000}
                        step={100}
                        onChange={(v) => setParams(p => ({ ...p, oneTimePurchase: v }))}
                        format={formatCurrency}
                    />
                    <SliderInput 
                        label="Revenue Boost" 
                        icon={<DollarSign className="w-4 h-4 text-emerald-400" />}
                        value={params.extraIncome}
                        max={5000}
                        step={50}
                        onChange={(v) => setParams(p => ({ ...p, extraIncome: v }))}
                        format={formatCurrency}
                    />
                </div>
            </div>

            <div className="glass-card p-8 rounded-[2.5rem] border border-white/10">
                <h3 className="text-sm font-black text-slate-400 uppercase tracking-[0.2em] mb-6">Target Objective</h3>
                <div className="space-y-3">
                    {goals.length === 0 ? (
                        <p className="text-xs text-slate-500 italic">No goals deployed to track impact.</p>
                    ) : (
                        goals.map(goal => (
                            <button 
                                key={goal.id}
                                onClick={() => setParams(p => ({ ...p, selectedGoalId: goal.id }))}
                                className={`w-full p-4 rounded-2xl border transition-all text-left flex items-center gap-4 ${params.selectedGoalId === goal.id ? 'bg-indigo-600/10 border-indigo-500 shadow-[0_0_15px_rgba(99,102,241,0.2)]' : 'bg-slate-950/40 border-white/5 hover:border-white/10'}`}
                            >
                                <div className={`w-10 h-10 rounded-xl bg-gradient-to-tr ${goal.color} flex items-center justify-center shrink-0`}>
                                    <Target className="w-5 h-5 text-white" />
                                </div>
                                <div className="min-w-0">
                                    <h4 className="text-sm font-bold text-white truncate">{goal.name}</h4>
                                    <p className="text-[10px] text-slate-500 font-bold uppercase">{formatCurrency(goal.targetAmount)} Target</p>
                                </div>
                            </button>
                        ))
                    )}
                </div>
            </div>
        </div>

        {/* Projection Side */}
        <div className="lg:col-span-2 space-y-8">
            <div className="glass-card p-8 rounded-[3rem] border border-white/10 relative overflow-hidden bg-slate-950/20 backdrop-blur-3xl min-h-[500px]">
                <div className="flex justify-between items-start mb-10">
                    <div>
                        <h3 className="text-xl font-black text-white flex items-center gap-3">
                            <Zap className="w-6 h-6 text-indigo-400" />
                            Trajectory Forecast
                        </h3>
                        <p className="text-xs text-slate-500 font-medium mt-1 uppercase tracking-widest">6-Month Liquidity Projection</p>
                    </div>
                    <div className="flex gap-4">
                        <div className="flex items-center gap-2">
                            <div className="w-3 h-1 bg-slate-700 rounded-full"></div>
                            <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Baseline</span>
                        </div>
                        <div className="flex items-center gap-2">
                            <div className="w-3 h-1 bg-indigo-500 rounded-full shadow-[0_0_10px_#6366f1]"></div>
                            <span className="text-[10px] font-black text-indigo-400 uppercase tracking-widest">Simulation</span>
                        </div>
                    </div>
                </div>

                <div className="h-[300px] w-full">
                    <ResponsiveContainer width="100%" height="100%">
                        <AreaChart data={simData}>
                            <defs>
                                <linearGradient id="simGrad" x1="0" y1="0" x2="0" y2="1">
                                    <stop offset="5%" stopColor="#6366f1" stopOpacity={0.3}/>
                                    <stop offset="95%" stopColor="#6366f1" stopOpacity={0}/>
                                </linearGradient>
                            </defs>
                            <CartesianGrid strokeDasharray="3 3" stroke="#1e293b" vertical={false} />
                            <XAxis dataKey="name" stroke="#64748b" fontSize={11} tickLine={false} axisLine={false} />
                            <YAxis hide />
                            <Tooltip 
                                contentStyle={{ backgroundColor: '#020617', border: '1px solid rgba(255,255,255,0.1)', borderRadius: '16px' }}
                                itemStyle={{ fontWeight: 'bold' }}
                            />
                            <Area type="monotone" dataKey="Baseline" stroke="#334155" strokeWidth={3} fill="transparent" animationDuration={800} />
                            <Area type="monotone" dataKey="Simulation" stroke="#6366f1" strokeWidth={4} fill="url(#simGrad)" animationDuration={1200} />
                        </AreaChart>
                    </ResponsiveContainer>
                </div>

                {impact && selectedGoal && (
                    <div className="mt-8 grid grid-cols-1 md:grid-cols-2 gap-6 animate-slide-up">
                        <div className="p-6 bg-slate-900/60 rounded-3xl border border-white/5 flex items-center gap-5">
                            <div className={`p-4 rounded-2xl ${impact.direction === 'delay' ? 'bg-rose-500/10 text-rose-400' : 'bg-emerald-500/10 text-emerald-400'}`}>
                                {impact.direction === 'delay' ? <ArrowDownRight className="w-6 h-6" /> : <ArrowUpRight className="w-6 h-6" />}
                            </div>
                            <div>
                                <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Timeline Shift</h4>
                                <div className={`text-xl font-black ${impact.direction === 'delay' ? 'text-rose-400' : 'text-emerald-400'}`}>
                                    {impact.direction === 'delay' ? '+' : '-'}{impact.months} Months
                                </div>
                                <p className="text-[10px] text-slate-600 font-medium">Shift for {selectedGoal.name}</p>
                            </div>
                        </div>

                        <div className="p-6 bg-indigo-600/10 rounded-3xl border border-indigo-500/20 flex items-center gap-5 relative overflow-hidden">
                            <div className="absolute top-0 right-0 p-2"><Sparkles className="w-4 h-4 text-indigo-400 animate-pulse" /></div>
                            <div className="p-4 rounded-2xl bg-indigo-500/20 text-indigo-400">
                                <ChevronRight className="w-6 h-6" />
                            </div>
                            <div>
                                <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Efficiency Delta</h4>
                                <div className="text-xl font-black text-white">
                                    {params.extraIncome > params.monthlyExtraSpend ? 'Optimized' : 'High Burn'}
                                </div>
                                <p className="text-[10px] text-slate-600 font-medium">Neural efficiency rating</p>
                            </div>
                        </div>
                    </div>
                )}
            </div>

            <div className="p-8 bg-gradient-to-r from-amber-500/10 to-transparent border border-amber-500/20 rounded-[2.5rem] flex items-start gap-6 group hover:bg-amber-500/20 transition-all">
                <div className="p-4 bg-amber-500 rounded-2xl shadow-[0_0_20px_rgba(245,158,11,0.4)] group-hover:scale-110 transition-transform">
                    <Target className="w-8 h-8 text-white" />
                </div>
                <div>
                    <h3 className="text-lg font-black text-white">Scenario Insight</h3>
                    <p className="text-sm text-slate-400 leading-relaxed font-medium mt-1">
                        {impact?.direction === 'delay' 
                          ? `This path delays your ${selectedGoal?.name} goal by approximately ${impact.days} days. Consider reducing variable burn to stabilize trajectory.`
                          : `Positive efficiency! You are accelerating your ${selectedGoal?.name} goal. Current configuration will reach target ${impact?.months} months early.`}
                    </p>
                </div>
            </div>
        </div>
      </div>
    </div>
  );
};

const SliderInput: React.FC<{ label: string, icon: React.ReactNode, value: number, max: number, step: number, onChange: (v: number) => void, format: (n: number) => string }> = ({ label, icon, value, max, step, onChange, format }) => (
    <div className="space-y-4">
        <div className="flex justify-between items-center">
            <div className="flex items-center gap-2">
                <span className="p-1.5 bg-slate-800 rounded-lg border border-white/5">{icon}</span>
                <span className="text-xs font-bold text-slate-300">{label}</span>
            </div>
            <span className="text-sm font-black text-white">{format(value)}</span>
        </div>
        <input 
            type="range" 
            min="0" 
            max={max} 
            step={step} 
            value={value}
            onChange={(e) => onChange(parseFloat(e.target.value))}
            className="w-full h-1.5 bg-slate-800 rounded-lg appearance-none cursor-pointer accent-indigo-500 hover:accent-indigo-400"
        />
    </div>
);

export default ScenarioSandbox;

import React, { useMemo, useState } from 'react';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import { Account, Transaction, TransactionType, Category, UserPlan } from '../types';
// Fixed: Added missing 'Sparkles' import from lucide-react
import { ArrowUpRight, DollarSign, Activity, Layers, Flame, TrendingUp, MoreHorizontal, ArrowRight, Wallet, PlusCircle, CreditCard, Target, ChevronRight, Quote, Landmark, Zap, Radio, RefreshCw, Repeat, Check, MessageCircle, Handshake, Copy, AlertCircle, X, Loader2, Tag, Microscope, Search, Volume2, Palette, Sparkles } from 'lucide-react';
import { generateNegotiationScript } from '../services/geminiService';

interface DashboardProps {
  accounts: Account[];
  transactions: Transaction[];
  onNavigate: (tab: string) => void;
  onAddAccount?: () => void;
  onAddTransaction?: () => void;
  onAddGoal?: () => void;
  formatCurrency: (amount: number) => string;
  userPlan?: UserPlan;
  onAskCoach?: (message: string) => void;
  negotiationUsage: number;
  onIncrementNegotiation: () => void;
}

const QUOTES = [
  { text: "Do not save what is left after spending, but spend what is left after saving.", author: "Warren Buffett" },
  { text: "A budget is telling your money where to go instead of wondering where it went.", author: "Dave Ramsey" },
  { text: "It's not your salary that makes you rich, it's your spending habits.", author: "Charles A. Jaffe" },
  { text: "The art is not in making money, but in keeping it.", author: "Proverb" },
];

const Dashboard: React.FC<DashboardProps> = ({ accounts, transactions, onNavigate, onAddAccount, onAddTransaction, onAddGoal, formatCurrency, userPlan, onAskCoach, negotiationUsage, onIncrementNegotiation }) => {
  const hasData = accounts.length > 0 || transactions.length > 0;
  const randomQuote = useMemo(() => QUOTES[Math.floor(Math.random() * QUOTES.length)], []);
  const netWorth = useMemo(() => accounts.reduce((acc, curr) => acc + curr.balance, 0), [accounts]);

  const [isNegotiating, setIsNegotiating] = useState(false);
  const [script, setScript] = useState<string | null>(null);
  const [scriptMerchant, setScriptMerchant] = useState('');
  const [showNegotiationModal, setShowNegotiationModal] = useState(false);
  const [copySuccess, setCopySuccess] = useState(false);

  const today = new Date();
  today.setHours(0, 0, 0, 0);

  const monthlySpending = useMemo(() => {
    return transactions
      .filter(t => {
        const d = new Date(t.date);
        return t.type === TransactionType.EXPENSE && d.getMonth() === today.getMonth() && d.getFullYear() === today.getFullYear();
      })
      .reduce((acc, curr) => acc + curr.amount, 0);
  }, [transactions]);

  const monthlyIncome = useMemo(() => {
    return transactions
      .filter(t => {
        const d = new Date(t.date);
        return t.type === TransactionType.INCOME && d.getMonth() === today.getMonth() && d.getFullYear() === today.getFullYear();
      })
      .reduce((acc, curr) => acc + curr.amount, 0);
  }, [transactions]);

  const burnRate = monthlySpending / Math.max(today.getDate(), 1);

  const recurringData = useMemo(() => {
      const merchantMap = new Map<string, { count: number; total: number; amounts: number[]; categories: Set<Category>; }>();
      transactions.filter(t => t.type === TransactionType.EXPENSE).forEach(t => {
            const key = t.merchant.toLowerCase().trim();
            const existing = merchantMap.get(key) || { count: 0, total: 0, amounts: [], categories: new Set() };
            existing.count++;
            existing.total += t.amount;
            existing.amounts.push(t.amount);
            existing.categories.add(t.category);
            merchantMap.set(key, existing);
        });

      const items: { merchant: string; avgCost: number; isSubscription: boolean }[] = [];
      merchantMap.forEach((data, key) => {
          const avg = data.total / data.count;
          const isConsistent = data.amounts.every(a => Math.abs(a - avg) / avg < 0.25);
          if (data.categories.has(Category.SUBSCRIPTION) || (data.count > 1 && isConsistent)) {
              items.push({ merchant: key, avgCost: avg, isSubscription: data.categories.has(Category.SUBSCRIPTION) });
          }
      });
      return items.sort((a,b) => b.avgCost - a.avgCost);
  }, [transactions]);

  const spendingData = useMemo(() => {
    const dataPoints: { date: string, actual: number | null, predicted: number | null }[] = [];
    const expenseMap = new Map<string, number>();

    transactions.filter(t => t.type === TransactionType.EXPENSE).forEach(t => {
        const d = new Date(t.date);
        d.setHours(0, 0, 0, 0);
        const key = d.toDateString();
        expenseMap.set(key, (expenseMap.get(key) || 0) + t.amount);
    });

    for (let i = 0; i <= 30; i++) {
        const d = new Date(today);
        d.setDate(today.getDate() - (30 - i));
        d.setHours(0, 0, 0, 0);
        dataPoints.push({
            date: d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }),
            actual: expenseMap.get(d.toDateString()) || 0,
            predicted: null
        });
    }

    const last = dataPoints[dataPoints.length - 1];
    last.predicted = last.actual;

    for (let i = 1; i <= 7; i++) {
        const d = new Date(today);
        d.setDate(today.getDate() + i);
        dataPoints.push({
            date: d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }),
            actual: null,
            predicted: burnRate * (1 + (Math.sin(i) * 0.1))
        });
    }
    return dataPoints;
  }, [transactions, burnRate]);

  const handleNegotiateClick = async (merchant: string, amount: number) => {
      const limit = userPlan === 'ultra' ? Infinity : userPlan === 'pro' ? 5 : 3;
      if (negotiationUsage >= limit) {
          onNavigate('plans');
          return; 
      }
      setIsNegotiating(true);
      setScriptMerchant(merchant);
      setShowNegotiationModal(true);
      const generated = await generateNegotiationScript(merchant, amount);
      setScript(generated);
      setIsNegotiating(false);
      onIncrementNegotiation();
  };

  const handleCopyScript = () => {
      if (script) {
          navigator.clipboard.writeText(script);
          setCopySuccess(true);
          setTimeout(() => setCopySuccess(false), 2000);
      }
  };

  if (!hasData) {
     return (
        <div className="flex flex-col items-center justify-center w-full min-h-full py-12 animate-fade-in text-center relative overflow-hidden">
            <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[600px] h-[600px] bg-indigo-500/10 rounded-full blur-[120px] pointer-events-none animate-pulse-slow"></div>
            <div className="max-w-4xl mx-auto mb-12 relative z-10">
                <div className="flex justify-center mb-8">
                    <div className="w-14 h-14 rounded-2xl bg-gradient-to-tr from-amber-400 to-orange-500 flex items-center justify-center shadow-[0_0_30px_rgba(251,191,36,0.3)] rotate-3">
                        <Quote className="w-7 h-7 text-white fill-current" />
                    </div>
                </div>
                <h1 className="text-3xl md:text-4xl font-bold text-white tracking-tight mb-4 px-4">"{randomQuote.text}"</h1>
                <p className="text-lg text-slate-400 font-medium italic tracking-wide">— {randomQuote.author}</p>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6 w-full max-w-5xl relative z-10 px-4">
                 <button onClick={onAddAccount} className="group glass-card p-8 rounded-[2rem] text-left border border-white/5 hover:border-indigo-500/30 transition-all hover:-translate-y-2">
                    <div className="w-14 h-14 rounded-2xl bg-indigo-500/10 flex items-center justify-center mb-6 group-hover:bg-indigo-500 group-hover:text-white transition-colors text-indigo-400 shadow-inner"><Landmark className="w-7 h-7" /></div>
                    <h3 className="text-xl font-bold text-white mb-2">Connect Accounts</h3>
                    <p className="text-slate-400 text-sm leading-relaxed">Bridge your banks or add manual accounts to finalize your net worth profile.</p>
                 </button>
                 <button onClick={onAddTransaction} className="group glass-card p-8 rounded-[2rem] text-left border border-white/5 hover:border-emerald-500/30 transition-all hover:-translate-y-2">
                    <div className="w-14 h-14 rounded-2xl bg-emerald-500/10 flex items-center justify-center mb-6 group-hover:bg-emerald-500 group-hover:text-white transition-colors text-emerald-400 shadow-inner"><PlusCircle className="w-7 h-7" /></div>
                    <h3 className="text-xl font-bold text-white mb-2">Log Activity</h3>
                    <p className="text-slate-400 text-sm leading-relaxed">Archive your daily spending to calibrate the AI predictive core.</p>
                 </button>
                 <button onClick={onAddGoal} className="group glass-card p-8 rounded-[2rem] text-left border border-white/5 hover:border-rose-500/30 transition-all hover:-translate-y-2">
                    <div className="w-14 h-14 rounded-2xl bg-rose-500/10 flex items-center justify-center mb-6 group-hover:bg-rose-500 group-hover:text-white transition-colors text-rose-400 shadow-inner"><Target className="w-7 h-7" /></div>
                    <h3 className="text-xl font-bold text-white mb-2">Deploy Goals</h3>
                    <p className="text-slate-400 text-sm leading-relaxed">Establish savings targets and let the AI optimize your trajectory.</p>
                 </button>
            </div>
        </div>
     );
  }

  return (
    <div className="space-y-8 animate-slide-up pb-10">
      <div className="flex flex-col md:flex-row justify-between items-end gap-4">
        <div>
          <h2 className="text-3xl font-bold text-white tracking-tight">System Dashboard</h2>
          <p className="text-slate-400 mt-2 font-medium">Real-time telemetry for your financial ecosystem.</p>
        </div>
        <div className="flex gap-3">
             <div className="px-4 py-2 bg-slate-900/50 rounded-xl border border-white/5 flex flex-col">
                 <span className="text-[8px] font-black text-slate-500 uppercase tracking-widest">Global Status</span>
                 <div className="flex items-center gap-2">
                    <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></div>
                    <span className="text-xs font-bold text-white">All Nodes Active</span>
                 </div>
             </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard title="Net Worth" value={formatCurrency(netWorth)} icon={<Wallet className="w-5 h-5 text-indigo-400" />} change="+2.4%" positive />
        <StatCard title="Monthly Spend" value={formatCurrency(monthlySpending)} icon={<CreditCard className="w-5 h-5 text-rose-400" />} change="-12%" positive />
        <StatCard title="Burn Rate / Day" value={formatCurrency(burnRate)} icon={<Flame className="w-5 h-5 text-amber-400" />} change="Stable" />
