import React, { useState, useEffect, useMemo } from 'react';
// Fixed: Added BotMode to imports
import { Transaction, Budget, UserPlan, TransactionType, Category, BotMode } from '../types';
import { Zap, X, AlertOctagon, CheckSquare, ArrowRight, ShieldAlert, TrendingUp } from 'lucide-react';

interface FloatingAssistantProps {
  transactions: Transaction[];
  budgets: Budget[];
  userPlan: UserPlan;
  // Fixed: Added botMode and insightUsage to FloatingAssistantProps
  botMode: BotMode;
  onOpenChat: (initialMessage?: string) => void;
  isVisible: boolean;
  insightUsage: number;
}

interface FinancialAlert {
  id: string;
  type: 'violation' | 'irreversible' | 'prediction';
  riskScore: number;
  title: string;
  message: string;
  amount: number;
  actions: string[];
  contextPayload: string;
}

// Fixed: Added botMode and insightUsage to component props
const FloatingAssistant: React.FC<FloatingAssistantProps> = ({ transactions, budgets, userPlan, botMode, onOpenChat, isVisible, insightUsage }) => {
  const [activeAlert, setActiveAlert] = useState<FinancialAlert | null>(null);
  const [panelMode, setPanelMode] = useState<'none' | 'inline' | 'diagnostic'>('none');

  useEffect(() => {
    const evaluateRisk = () => {
      const now = new Date();
      let highestRiskAlert: FinancialAlert | null = null;

      budgets.forEach(b => {
        const spent = transactions.filter(t => 
            t.category === b.category && 
            t.type === TransactionType.EXPENSE && 
            new Date(t.date).getMonth() === now.getMonth()
        ).reduce((acc, t) => acc + t.amount, 0);

        if (spent > b.limit) {
          const over = spent - b.limit;
          const risk = Math.min(95, (over / b.limit) * 40 + 20);
          if (!highestRiskAlert || risk > highestRiskAlert.riskScore) {
            highestRiskAlert = {
              id: `b_${b.id}`,
              type: 'violation',
              riskScore: risk,
              title: 'Boundary Alert',
              message: `${b.category} limit exceeded.`,
              amount: over,
              actions: ['Pause spending', 'Audit ledger'],
              contextPayload: `BUDGET_VIOLATION: ${b.category}.`
            };
          }
        }
      });

      setActiveAlert(highestRiskAlert);
    };
    evaluateRisk();
  }, [transactions, budgets]);

  const handleInteraction = () => {
      if (!activeAlert) return;
      if (activeAlert.riskScore >= 70) {
          onOpenChat(activeAlert.contextPayload);
          return;
      }
      setPanelMode(prev => prev === 'none' ? 'diagnostic' : 'none');
  };

  if (!activeAlert || !isVisible) return null;

  const isCritical = activeAlert.riskScore >= 70;

  return (
    <div className={`fixed bottom-24 md:bottom-6 right-6 z-40 flex flex-col items-end gap-3 transition-all animate-fade-in`}>
        {panelMode !== 'none' && (
            <div className="bg-[#0f172a] border border-white/10 p-5 rounded-2xl shadow-2xl w-64 mb-2 animate-slide-up backdrop-blur-md">
                <div className="flex justify-between items-center mb-3">
                    <h4 className="text-xs font-bold text-white uppercase tracking-widest">{activeAlert.title}</h4>
                    <button onClick={() => setPanelMode('none')}><X className="w-3 h-3 text-slate-500" /></button>
                </div>
                <p className="text-[11px] text-slate-400 mb-4">{activeAlert.message}</p>
                <button onClick={() => onOpenChat(activeAlert.contextPayload)} className="w-full py-2 bg-indigo-600 text-[10px] font-black uppercase tracking-widest text-white rounded-lg">Resolve with Coach</button>
            </div>
        )}

        <button 
            onClick={handleInteraction}
            className={`w-14 h-14 rounded-2xl bg-slate-950 border-2 flex items-center justify-center shadow-2xl transition-all active:scale-90 ${isCritical ? 'border-rose-500 shadow-rose-500/20' : 'border-indigo-500 shadow-indigo-500/20'}`}
        >
            <div className={`w-2 h-2 rounded-full absolute top-2 right-2 ${isCritical ? 'bg-rose-500 animate-ping' : 'bg-indigo-500'}`}></div>
            <Zap className={`w-6 h-6 ${isCritical ? 'text-rose-500 animate-pulse' : 'text-indigo-400'}`} />
        </button>
    </div>
  );
};

export default FloatingAssistant;

