                            <div className="flex justify-between items-end">
                                <div className="flex flex-col"><span className="text-[8px] font-black text-white/40 uppercase tracking-widest mb-1">Authorized User</span><span className="text-xs font-black text-white uppercase tracking-wider truncate max-w-[140px]">SECURE SESSION</span></div>
