                            </div>
                        </div>
                    </div>
                    <div className="mt-10 text-center space-y-5 relative z-10">
                        <div className={`inline-flex items-center gap-2 px-4 py-2 rounded-full border text-[11px] font-black tracking-widest uppercase transition-all duration-500 ${isProcessing ? 'bg-indigo-500 text-white shadow-[0_0_20px_rgba(99,102,241,0.5)] border-indigo-400' : 'bg-emerald-500/10 border-emerald-500/20 text-emerald-400 animate-pulse'}`}>
                            {isProcessing ? <><Loader2 className="w-3.5 h-3.5 animate-spin" /> Performing Handshake</> : <><ShieldCheck className="w-3.5 h-3.5" /> Secure Tunnel Active</>}
                        </div>
                        <p className="text-slate-500 text-xs max-w-[260px] leading-relaxed font-medium">Synchronizing <span className="text-white font-bold">{plan.toUpperCase()}</span> logic to your primary financial cluster.</p>
                    </div>
                 </div>

                 <div className="flex-1 p-10 flex flex-col">
                    <div className="mb-10">
                        <div className="flex items-center gap-3 mb-1"><Fingerprint className="w-6 h-6 text-indigo-500" /><h2 className="text-2xl font-black text-white tracking-tight uppercase">Authorize Deployment</h2></div>
                        <p className="text-slate-500 text-xs font-bold tracking-widest uppercase opacity-70">Establish premium data uplink.</p>
                    </div>
                    <form onSubmit={handlePay} className="space-y-6 flex-1">
                        <div className="bg-slate-900/40 p-6 rounded-[2rem] border border-white/5 flex justify-between items-center group transition-all">
                            <div className="space-y-1"><div className="text-[10px] text-slate-500 font-black uppercase tracking-widest">Subscription Node</div><div className="text-lg font-black text-white">{plan.toUpperCase()} <span className="text-indigo-500">TIER</span></div></div>
                            <div className="text-right space-y-1"><div className="text-[10px] text-slate-500 font-black uppercase tracking-widest">Magnitude</div><div className="text-2xl font-black text-white tracking-tighter">{price}</div></div>
                        </div>
                        <div className="space-y-5">
                            <div className="space-y-2">
                                <label className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] ml-1">Card Cluster Number</label>
