                                    <div className="absolute right-4 top-1/2 -translate-y-1/2 flex items-center gap-2">
                                        {cardBrand !== 'unknown' && <span className="text-[9px] font-black text-white bg-indigo-600 px-2 py-1 rounded shadow-lg uppercase tracking-widest">{cardBrand}</span>}
                                        <Lock className="w-4 h-4 text-slate-800" />
                                    </div>
                                </div>
                            </div>
                            <div className="grid grid-cols-2 gap-5">
                                <div className="space-y-2"><label className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] ml-1">Validity Cycle</label><input required value={expiry} onChange={e => {let val = e.target.value.replace(/[^\d]/g, ''); if (val.length >= 2) val = val.substring(0, 2) + '/' + val.substring(2, 4); setExpiry(val);}} placeholder="MM/YY" className="w-full bg-slate-950 border border-white/10 rounded-2xl p-4 text-white focus:border-indigo-500 focus:ring-4 focus:ring-indigo-500/10 font-mono text-center placeholder:text-slate-900 text-lg shadow-inner" maxLength={5} /></div>
                                <div className="space-y-2"><label className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] ml-1">Secure CVC</label><input required value={cvc} onChange={e => setCvc(e.target.value.replace(/[^\d]/g, '').substring(0, cardBrand === 'amex' ? 4 : 3))} placeholder={cardBrand === 'amex' ? "••••" : "•••"} className="w-full bg-slate-950 border border-white/10 rounded-2xl p-4 text-white focus:border-indigo-500 focus:ring-4 focus:ring-indigo-500/10 font-mono text-center placeholder:text-slate-900 text-lg shadow-inner" maxLength={cardBrand === 'amex' ? 4 : 3} /></div>
                            </div>
