                        {error && <div className="bg-rose-500/10 border border-rose-500/20 text-rose-400 p-4 rounded-2xl text-[10px] font-black uppercase tracking-[0.15em] flex items-center gap-3 animate-fade-in"><ShieldX className="w-5 h-5 shrink-0" /> {error}</div>}
