                            <div className="p-5 bg-slate-950/50 rounded-2xl border border-white/5"><div className="text-[8px] font-black text-slate-600 uppercase mb-1">Total Impact (6mo)</div><div className="text-lg font-black text-white">{formatCurrency((params.extraIncome - params.monthlyExtraSpend) * 6 - params.oneTimePurchase)}</div></div>
                        </div>
                    )}
