export default Dashboard;

import React, { useState, useMemo, useEffect } from 'react';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Line } from 'recharts';
import { Transaction, Goal, TransactionType, UserPlan } from '../types';
import { Microscope, Play, RefreshCw, Zap, TrendingUp, DollarSign, ShoppingCart, ArrowUpRight, ArrowDownRight, Target, Lock, Sparkles, ChevronRight, AlertTriangle, ShieldAlert, BrainCircuit, Activity, Loader2, Cpu, Eye, EyeOff, Info } from 'lucide-react';
import { parseSimulationQuery } from '../services/geminiService';

interface SandboxProps {
  transactions: Transaction[];
  goals: Goal[];
  formatCurrency: (amount: number) => string;
  userPlan: UserPlan;
  onUpgradeClick: () => void;
  insightUsage: number;
  onIncrementUsage: (amount?: number) => void;
}

const ScenarioSandbox: React.FC<SandboxProps> = ({ transactions, goals, formatCurrency, userPlan, onUpgradeClick, insightUsage, onIncrementUsage }) => {
  const [params, setParams] = useState({
    monthlyExtraSpend: 0,
    oneTimePurchase: 0,
    extraIncome: 0,
    selectedGoalId: goals[0]?.id || null,
    buyItemName: '',
  });

  const [showGhost, setShowGhost] = useState(() => localStorage.getItem('nova_sim_ghost') === 'true');
  const [ghostRate, setGhostRate] = useState(7);
  const [isExecuting, setIsExecuting] = useState(false);
  const [activeAnalysisTab, setActiveAnalysisTab] = useState<'risk' | 'forecast' | 'logic'>('risk');

  useEffect(() => {
      localStorage.setItem('nova_sim_ghost', showGhost.toString());
  }, [showGhost]);

  const isElite = userPlan === 'ultra';

  // Real Simulation Engine
  const simData = useMemo(() => {
    const dataPoints: any[] = [];
    const now = new Date();

    const monthlyExpenses = transactions
      .filter(t => t.type === TransactionType.EXPENSE && new Date(t.date).getMonth() === now.getMonth())
      .reduce((acc, curr) => acc + curr.amount, 0);

    const monthlyIncome = transactions
      .filter(t => t.type === TransactionType.INCOME && new Date(t.date).getMonth() === now.getMonth())
      .reduce((acc, curr) => acc + curr.amount, 0);

    const baseSavingsRate = Math.max(0, monthlyIncome - monthlyExpenses);

    let currentBalance = 15000; 
    let simBalance = 15000;
    let ghostBalance = 15000;

    const monthlyGhostRate = (ghostRate / 100) / 12;

    for (let i = 0; i <= 6; i++) {
        const month = new Date(now.getFullYear(), now.getMonth() + i, 1);
        const label = month.toLocaleDateString('en-US', { month: 'short' });

        // Baseline calc
        currentBalance += baseSavingsRate;

        // Simulation calc
        const oneTimeCost = i === 0 ? params.oneTimePurchase : 0;
        const simulatedMonthlyNet = baseSavingsRate + params.extraIncome - params.monthlyExtraSpend;
        simBalance += (simulatedMonthlyNet - oneTimeCost);

        // Ghost Trajectory (Elite Only): Potential if oneTimePurchase was invested instead
        if (i === 0) {
            ghostBalance += simulatedMonthlyNet; // No oneTimeCost deduction
        } else {
            ghostBalance = (ghostBalance + simulatedMonthlyNet) * (1 + monthlyGhostRate);
        }

        dataPoints.push({
            name: label,
            Baseline: Math.max(0, currentBalance),
            Simulation: Math.max(0, simBalance),
            Ghost: isElite && showGhost ? Math.max(0, ghostBalance) : null
        });
    }
    return dataPoints;
  }, [transactions, params, isElite, showGhost, ghostRate]);

  const selectedGoal = goals.find(g => g.id === params.selectedGoalId);

  const neuralMetrics = useMemo(() => {
    if (!selectedGoal) return null;
    const remaining = selectedGoal.targetAmount - selectedGoal.currentAmount;

    const now = new Date();
    const monthlyExpenses = transactions
      .filter(t => t.type === TransactionType.EXPENSE && new Date(t.date).getMonth() === now.getMonth())
      .reduce((acc, curr) => acc + curr.amount, 0);
    const monthlyIncome = transactions
      .filter(t => t.type === TransactionType.INCOME && new Date(t.date).getMonth() === now.getMonth())
      .reduce((acc, curr) => acc + curr.amount, 0);

    const standardMonthlySavings = Math.max(1, monthlyIncome - monthlyExpenses);
    const simMonthlySavings = Math.max(1, standardMonthlySavings + params.extraIncome - params.monthlyExtraSpend);

    const baseMonths = remaining / standardMonthlySavings;
    const simMonths = (remaining + params.oneTimePurchase) / simMonthlySavings;

    const diff = simMonths - baseMonths;
    const riskLevel = params.monthlyExtraSpend > standardMonthlySavings ? 'critical' : params.oneTimePurchase > 5000 ? 'warning' : 'stable';

    return {
        days: Math.abs(Math.round(diff * 30.44)),
        direction: diff > 0 ? 'delay' : 'acceleration',
        months: Math.abs(diff).toFixed(1),
        risk: riskLevel,
        efficiency: ((simMonthlySavings / standardMonthlySavings) * 100).toFixed(0)
    };
  }, [selectedGoal, params, transactions]);

  const handleExecuteAIsim = async () => {
    if (!isElite || !params.buyItemName.trim()) return;
    setIsExecuting(true);
    try {
        const result = await parseSimulationQuery(params.buyItemName);
        if (result) {
            setParams(p => ({
                ...p,
                oneTimePurchase: result.oneTimeTotal,
                monthlyExtraSpend: result.monthlyRecurringTotal
            }));
            onIncrementUsage(10); 
        }
    } finally {
        setIsExecuting(false);
    }
  };

  if (userPlan === 'free') {
      return (
          <div className="h-[calc(100vh-12rem)] flex items-center justify-center">
              <div className="glass-card max-w-md p-10 rounded-[3rem] text-center border border-indigo-500/20">
                  <div className="w-20 h-20 bg-gradient-to-tr from-indigo-500 to-purple-600 rounded-[2rem] flex items-center justify-center mx-auto mb-8 shadow-2xl">
                      <Lock className="w-10 h-10 text-white" />
                  </div>
                  <h3 className="text-2xl font-black text-white mb-4">Neural Sandbox Locked</h3>
                  <p className="text-slate-400 mb-8 font-medium">Predictive simulations require a Pro or Elite uplink. Unlock the Sandbox to project your trajectory.</p>
                  <button onClick={onUpgradeClick} className="w-full py-4 bg-white text-slate-950 font-black rounded-2xl hover:scale-105 active:scale-95 transition-all shadow-xl flex items-center justify-center gap-2">
                      <Zap className="w-5 h-5 fill-indigo-600 text-indigo-600" /> Upgrade Now
                  </button>
              </div>
          </div>
      );
  }

  return (
    <div className="animate-slide-up pb-20 space-y-10">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-end gap-6">
        <div>
          <div className="flex items-center gap-3 mb-2">
            <h2 className="text-3xl font-black text-white tracking-tighter flex items-center gap-3">
               <Microscope className="w-8 h-8 text-indigo-400" />
               Predictive Sandbox
            </h2>
            <span className="px-2 py-0.5 rounded bg-indigo-500/20 text-indigo-400 text-[10px] font-black tracking-widest border border-indigo-500/30">BETA</span>
          </div>
          <p className="text-slate-400 font-medium">Simulate financial choices to see their multi-month impact.</p>
        </div>
        <div className="flex gap-3">
             {isElite && (
                 <button 
                    onClick={() => setShowGhost(!showGhost)}
                    className={`px-4 py-2 rounded-xl text-xs font-black uppercase tracking-widest transition-all flex items-center gap-2 border ${showGhost ? 'bg-indigo-500/20 border-indigo-400 text-indigo-400 shadow-[0_0_15px_rgba(99,102,241,0.2)]' : 'bg-slate-900 border-white/5 text-slate-500 hover:text-white'}`}
                 >
                    {showGhost ? <Eye className="w-4 h-4" /> : <EyeOff className="w-4 h-4" />}
                    Opportunity Potential
                 </button>
             )}
             <button 
                onClick={() => setParams({ monthlyExtraSpend: 0, oneTimePurchase: 0, extraIncome: 0, selectedGoalId: goals[0]?.id || null, buyItemName: '' })}
                className="px-4 py-2 bg-slate-900 border border-white/5 text-slate-400 rounded-xl text-xs font-bold hover:text-white transition-all flex items-center gap-2"
             >
                <RefreshCw className="w-4 h-4" /> Reset Sim
             </button>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-10">

        <div className="space-y-6">
            <div className="glass-card p-8 rounded-[2.5rem] border border-white/10 relative overflow-hidden">
                <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-indigo-500 to-purple-500 opacity-50"></div>
                <h3 className="text-sm font-black text-slate-400 uppercase tracking-[0.2em] mb-8">Simulation Vectors</h3>

                <div className="space-y-8">
                    <div className="space-y-3">
                        <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest block">Intent: "What if I buy..."</label>
                        <div className="relative group">
                            <input 
                                type="text" 
                                placeholder={isElite ? "e.g. MacBook (1200) and Pizza (20)" : "MacBook Pro, Car, Rolex..."}
                                value={params.buyItemName}
                                onChange={(e) => setParams(p => ({ ...p, buyItemName: e.target.value }))}
                                className={`w-full bg-slate-950/50 border rounded-xl p-3 text-white text-sm focus:border-indigo-500 outline-none transition-all placeholder:text-slate-800 ${isElite ? 'border-indigo-500/30 pr-24' : 'border-white/10'}`}
                            />
                            {isElite && (
                                <button 
                                    onClick={handleExecuteAIsim}
                                    disabled={isExecuting || !params.buyItemName}
                                    className="absolute right-1.5 top-1.5 bottom-1.5 px-3 bg-indigo-600 hover:bg-indigo-500 text-white rounded-lg text-[10px] font-black uppercase tracking-widest shadow-lg transition-all disabled:opacity-50 flex items-center gap-2"
                                >
                                    {isExecuting ? <Loader2 className="w-3 h-3 animate-spin" /> : <Play className="w-3 h-3 fill-current" />}
                                    Execute
                                </button>
                            )}
                        </div>
                        {isElite && (
                            <div className="flex items-center gap-1.5 px-2">
                                <Cpu className="w-3 h-3 text-indigo-400" />
                                <span className="text-[9px] text-slate-500 font-bold uppercase tracking-widest">Burns 10 Credits per simulation</span>
                            </div>
                        )}
                    </div>

                    <SliderInput 
                        label="One-time Acquisition" 
                        icon={<ShoppingCart className="w-4 h-4 text-amber-400" />}
                        value={params.oneTimePurchase}
                        max={15000}
                        step={100}
                        onChange={(v) => setParams(p => ({ ...p, oneTimePurchase: v }))}
                        format={formatCurrency}
                    />

                    <SliderInput 
                        label="Monthly Extra Burn" 
                        icon={<TrendingUp className="w-4 h-4 text-rose-400" />}
                        value={params.monthlyExtraSpend}
                        max={3000}
                        step={50}
                        onChange={(v) => setParams(p => ({ ...p, monthlyExtraSpend: v }))}
                        format={formatCurrency}
                    />

                    <SliderInput 
                        label="Revenue Boost" 
                        icon={<DollarSign className="w-4 h-4 text-emerald-400" />}
                        value={params.extraIncome}
                        max={5000}
                        step={50}
                        onChange={(v) => setParams(p => ({ ...p, extraIncome: v }))}
                        format={formatCurrency}
                    />
                </div>
            </div>

            {isElite && showGhost && (
                <div className="glass-card p-8 rounded-[2.5rem] border border-indigo-500/30 bg-indigo-500/5 animate-fade-in">
                    <div className="flex justify-between items-center mb-6">
                        <h3 className="text-sm font-black text-indigo-400 uppercase tracking-[0.2em]">Ghost Parameters</h3>
                        <Info className="w-4 h-4 text-indigo-500/50" />
                    </div>
                    <SliderInput 
                        label="Assumption Rate" 
                        icon={<TrendingUp className="w-4 h-4 text-indigo-400" />}
                        value={ghostRate}
                        max={10}
                        min={4}
                        step={0.5}
                        onChange={(v) => setGhostRate(v)}
                        format={(v) => `${v}% APR`}
                    />
                    <p className="text-[9px] text-slate-500 mt-6 font-bold uppercase leading-relaxed">
                        The ghost line visualizes the compounding potential of capital if redirected to high-yield assets instead of the simulated purchase.
                    </p>
                </div>
            )}

            <div className="glass-card p-8 rounded-[2.5rem] border border-white/10">
                <h3 className="text-sm font-black text-slate-400 uppercase tracking-[0.2em] mb-6">Target Objective</h3>
                <div className="space-y-3 max-h-60 overflow-y-auto custom-scrollbar pr-2">
                    {goals.length === 0 ? (
                        <p className="text-xs text-slate-500 italic">No goals deployed to track impact.</p>
                    ) : (
                        goals.map(goal => (
                            <button 
                                key={goal.id}
                                onClick={() => setParams(p => ({ ...p, selectedGoalId: goal.id }))}
                                className={`w-full p-4 rounded-2xl border transition-all text-left flex items-center gap-4 ${params.selectedGoalId === goal.id ? 'bg-indigo-600/10 border-indigo-500 shadow-[0_0_15px_rgba(99,102,241,0.2)]' : 'bg-slate-950/40 border-white/5 hover:border-white/10'}`}
                            >
                                <div className={`w-10 h-10 rounded-xl bg-gradient-to-tr ${goal.color} flex items-center justify-center shrink-0`}><Target className="w-5 h-5 text-white" /></div>
                                <div className="min-w-0">
                                    <h4 className="text-sm font-bold text-white truncate">{goal.name}</h4>
                                    <p className="text-[10px] text-slate-500 font-bold uppercase">{formatCurrency(goal.targetAmount)} Target</p>
                                </div>
                            </button>
                        ))
                    )}
                </div>
            </div>
        </div>

        <div className="lg:col-span-2 space-y-8">
            <div className="glass-card p-8 rounded-[3rem] border border-white/10 relative overflow-hidden bg-slate-950/20 backdrop-blur-3xl min-h-[500px]">
                <div className="flex justify-between items-start mb-10">
                    <div>
                        <h3 className="text-xl font-black text-white flex items-center gap-3"><Zap className="w-6 h-6 text-indigo-400" />Trajectory Forecast</h3>
                        <p className="text-xs text-slate-500 font-medium mt-1 uppercase tracking-widest">6-Month Liquidity Projection</p>
                    </div>
                    <div className="flex flex-wrap gap-4 justify-end">
                        <div className="flex items-center gap-2"><div className="w-3 h-1 bg-slate-700 rounded-full"></div><span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Baseline</span></div>
                        <div className="flex items-center gap-2"><div className="w-3 h-1 bg-indigo-500 rounded-full shadow-[0_0_10px_#6366f1]"></div><span className="text-[10px] font-black text-indigo-400 uppercase tracking-widest">Simulation</span></div>
                        {isElite && showGhost && (
                             <div className="flex items-center gap-2"><div className="w-3 h-1 border-t-2 border-dashed border-indigo-300 rounded-full opacity-40"></div><span className="text-[10px] font-black text-indigo-200/40 uppercase tracking-widest">Ghost ({ghostRate}%)</span></div>
                        )}
                    </div>
                </div>

                <div className="h-[280px] w-full">
                    <ResponsiveContainer width="100%" height="100%">
                        <AreaChart data={simData}>
                            <defs>
                                <linearGradient id="simGrad" x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor="#6366f1" stopOpacity={0.3}/><stop offset="95%" stopColor="#6366f1" stopOpacity={0}/></linearGradient>
                            </defs>
                            <CartesianGrid strokeDasharray="3 3" stroke="#1e293b" vertical={false} />
                            <XAxis dataKey="name" stroke="#64748b" fontSize={11} tickLine={false} axisLine={false} />
                            <YAxis hide />
                            <Tooltip contentStyle={{ backgroundColor: '#020617', border: '1px solid rgba(255,255,255,0.1)', borderRadius: '16px' }} itemStyle={{ fontWeight: 'bold' }} />
                            <Area type="monotone" dataKey="Baseline" stroke="#334155" strokeWidth={3} fill="transparent" animationDuration={800} />
                            <Area type="monotone" dataKey="Simulation" stroke="#6366f1" strokeWidth={4} fill="url(#simGrad)" animationDuration={1200} />
                            {isElite && showGhost && (
                                <Area type="monotone" dataKey="Ghost" stroke="#a5b4fc" strokeWidth={2} strokeDasharray="5 5" fill="transparent" strokeOpacity={0.4} animationDuration={1500} />
                            )}
                        </AreaChart>
                    </ResponsiveContainer>
                </div>

                {neuralMetrics && (
                    <div className="mt-8 grid grid-cols-1 md:grid-cols-2 gap-6 animate-slide-up">
                        <div className={`p-6 rounded-3xl border flex items-center gap-5 transition-all ${neuralMetrics.direction === 'delay' ? 'bg-rose-500/10 border-rose-500/20 shadow-[0_0_30px_rgba(244,63,94,0.1)]' : 'bg-emerald-500/10 border-emerald-500/20 shadow-[0_0_30px_rgba(16,185,129,0.1)]'}`}>
                            <div className={`p-4 rounded-2xl ${neuralMetrics.direction === 'delay' ? 'bg-rose-500/20 text-rose-400' : 'bg-emerald-500/20 text-emerald-400'}`}>
                                {neuralMetrics.direction === 'delay' ? <ArrowDownRight className="w-6 h-6" /> : <ArrowUpRight className="w-6 h-6" />}
                            </div>
                            <div>
                                <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Timeline Shift</h4>
                                <div className={`text-xl font-black ${neuralMetrics.direction === 'delay' ? 'text-rose-400' : 'text-emerald-400'}`}>
                                    {neuralMetrics.direction === 'delay' ? '+' : '-'}{neuralMetrics.months} Months
                                </div>
                                <p className="text-[10px] text-slate-600 font-medium">Goal Impact Analysis</p>
                            </div>
                        </div>

                        <div className="p-6 bg-slate-900/60 rounded-3xl border border-white/5 flex items-center gap-5">
                            <div className="p-4 rounded-2xl bg-indigo-500/20 text-indigo-400"><Activity className="w-6 h-6" /></div>
                            <div>
                                <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Neural Efficiency</h4>
                                <div className="text-xl font-black text-white">{neuralMetrics.efficiency}%</div>
                                <p className="text-[10px] text-slate-600 font-medium">Capital Utilization Ratio</p>
                            </div>
                        </div>
                    </div>
                )}
            </div>

            <div className="glass-card p-8 rounded-[2.5rem] border border-white/10">
                <div className="flex gap-6 mb-8 border-b border-white/5">
                    <button onClick={() => setActiveAnalysisTab('risk')} className={`pb-4 text-xs font-black uppercase tracking-widest transition-all ${activeAnalysisTab === 'risk' ? 'text-indigo-400 border-b-2 border-indigo-400' : 'text-slate-500 hover:text-slate-300'}`}>Neural Risk Audit</button>
                    <button onClick={() => setActiveAnalysisTab('logic')} className={`pb-4 text-xs font-black uppercase tracking-widest transition-all ${activeAnalysisTab === 'logic' ? 'text-indigo-400 border-b-2 border-indigo-400' : 'text-slate-500 hover:text-slate-300'}`}>Sim Logic</button>
                </div>

                <div className="animate-fade-in">
                    {activeAnalysisTab === 'risk' && (
                        <div className="space-y-6">
                            <div className="flex items-start gap-5">
                                <div className={`p-4 rounded-2xl shrink-0 ${neuralMetrics?.risk === 'critical' ? 'bg-rose-500 shadow-[0_0_20px_rgba(244,63,94,0.4)]' : neuralMetrics?.risk === 'warning' ? 'bg-amber-500 shadow-[0_0_20px_rgba(245,158,11,0.4)]' : 'bg-emerald-500 shadow-[0_0_20px_rgba(16,185,129,0.4)]'}`}>
                                    <ShieldAlert className="w-8 h-8 text-white" />
                                </div>
                                <div>
                                    <h3 className="text-lg font-black text-white mb-2 uppercase tracking-tight">Threat Assessment</h3>
                                    <p className="text-slate-400 text-sm leading-relaxed font-medium">
                                        {neuralMetrics?.risk === 'critical' ? `DANGER: Your simulated burn rate exceeds your baseline savings protocol. You will exhaust liquidity within 4 months if this path is taken.` : 
                                         neuralMetrics?.risk === 'warning' ? `ALERT: Large acquisition detected (${params.buyItemName || 'Manual Purchase'}). While sustainable, this will significantly delay your saving objectives.` : 
                                         `STABLE: Current simulation parameters maintain a healthy capital buffer. Efficiency is optimized for objective completion.`}
                                    </p>
                                </div>
                            </div>
                            <div className="p-4 bg-indigo-500/5 rounded-2xl border border-indigo-500/10 flex items-center gap-3">
                                <BrainCircuit className="w-5 h-5 text-indigo-400 shrink-0" />
                                <p className="text-[10px] text-indigo-200/60 font-bold uppercase tracking-wider">Prediction: Buying {params.buyItemName || 'unplanned items'} today is calculated to have a 78% correlation with missed targets next quarter.</p>
                            </div>
                        </div>
                    )}
                    {activeAnalysisTab === 'logic' && (
                        <div className="grid grid-cols-2 gap-4">
                            <div className="p-5 bg-slate-950/50 rounded-2xl border border-white/5"><div className="text-[8px] font-black text-slate-600 uppercase mb-1">Delta Monthly</div><div className="text-lg font-black text-white">{formatCurrency(params.extraIncome - params.monthlyExtraSpend)}</div></div>
