            {activeTab === 'transactions' && <Transactions transactions={transactions} accounts={accounts} onDelete={handleDeleteTransaction} onAdd={handleAddTransaction} formatCurrency={formatCurrency} onNavigateToAccounts={() => setActiveTab('accounts')} userPlan={userPlan} scanUsage={scanUsage} onIncrementScan={() => setScanUsage(prev => prev + 1)} currency={currency} />}
            {activeTab === 'accounts' && <Accounts accounts={accounts} budgets={budgets} transactions={transactions} userPlan={userPlan} onAdd={(acc) => { setAccounts(prev => [...prev, acc]); addToast('Account bridged.', 'success'); }} onUpdate={(acc) => { setAccounts(prev => prev.map(a => a.id === acc.id ? acc : a)); addToast('Account updated.', 'success'); }} onDelete={(id) => { setAccounts(prev => prev.filter(a => a.id !== id)); setTransactions(prev => prev.map(t => t.accountId === id ? { ...t, accountId: 'manual' } : t)); addToast('Account disconnected. History preserved.', 'info'); }} formatCurrency={formatCurrency} userName={userName} userAvatar={userAvatar} userAvatarZoom={userAvatarZoom} userAvatarPos={userAvatarPos} userBorder={userBorder} onNavigate={setActiveTab} />}
            {activeTab === 'insights' && <Insights transactions={transactions} userPlan={userPlan} onUpgradeClick={() => setActiveTab('plans')} formatCurrency={formatCurrency} insightUsage={insightUsage} onIncrementUsage={(val) => setInsightUsage(prev => prev + (val || 1))} onApplyBudgets={(newBudgets) => { const existingCats = new Set(budgets.map(b => b.category)); const toAdd = newBudgets.filter(b => !existingCats.has(b.category)); setBudgets(prev => [...prev, ...toAdd]); addToast(`Applied ${toAdd.length} AI limits.`, 'success'); }} initialPrompt={pendingChatQuery} onPromptHandled={() => setPendingChatQuery(null)} botMode={botMode} />}
            {activeTab === 'sandbox' && <ScenarioSandbox transactions={transactions} goals={goals} formatCurrency={formatCurrency} userPlan={userPlan} onUpgradeClick={() => setActiveTab('plans')} insightUsage={insightUsage} onIncrementUsage={(val) => setInsightUsage(prev => prev + (val || 1))} />}
            {activeTab === 'goals' && <Goals goals={goals} budgets={budgets} transactions={transactions} onAddGoal={(g) => { setGoals(prev => [...prev, g]); addToast('Goal deployed.', 'success'); }} onUpdateGoal={(g) => { setGoals(prev => prev.map(goal => goal.id === g.id ? g : goal)); addToast('Goal updated.', 'success'); }} onAddBudget={(b) => { setBudgets(prev => [...prev, b]); addToast('Limit set.', 'success'); }} onDeleteBudget={(id) => { setBudgets(prev => prev.filter(b => b.id !== id)); addToast('Limit removed.', 'info'); }} formatCurrency={formatCurrency} />}
            {activeTab === 'plans' && <Plans currentPlan={userPlan} onUpgrade={(plan) => { setUserPlan(plan); addToast(`Plan upgraded to ${plan.toUpperCase()}.`, 'success'); }} onDowngrade={() => { setUserPlan('free'); addToast('Plan reset to Starter.', 'info'); }} onNavigateDashboard={() => setActiveTab('dashboard')} />}
            {activeTab === 'upcoming' && <UpcomingFeatures />}
            {activeTab === 'settings' && <Settings userName={userName} userEmail={userEmail} userAvatar={userAvatar} userAvatarZoom={userAvatarZoom} userAvatarPos={userAvatarPos} userBorder={userBorder} userBackground={userBackground} onUpdateBackground={setUserBackground} userPlan={userPlan} onUpdateProfile={handleUpdateProfile} addToast={addToast} onExportData={handleExportData} onImportData={handleImportData} onClearData={handleClearData} language={language} onUpdateLanguage={setLanguage} currency={currency} onUpdateCurrency={setCurrency} botMode={botMode} onUpdateBotMode={setBotMode} onDowngrade={() => { setUserPlan('free'); addToast('Plan downgraded.', 'info'); }} />}
        </div>
      </main>

      {isLogoutModalOpen && (
          <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/95 backdrop-blur-2xl animate-fade-in">
              <div className="bg-[#0f172a] border border-rose-500/30 rounded-[3rem] w-full max-w-sm shadow-[0_0_100px_rgba(244,63,94,0.2)] overflow-hidden animate-slide-up relative text-center p-10">
                  <div className="w-20 h-20 bg-rose-500/20 rounded-[2rem] flex items-center justify-center mx-auto mb-8 border border-rose-500/30">
                      <ShieldX className="w-10 h-10 text-rose-500" />
                  </div>
                  <h3 className="text-2xl font-black text-white mb-3 uppercase tracking-tighter">Terminate Protocol?</h3>
                  <p className="text-slate-400 text-sm mb-10 leading-relaxed">Disconnecting the vault will restrict AI logic and local archival syncing. Are you sure you want to end this session?</p>
                  <div className="space-y-4">
                      <button onClick={confirmLogout} className="w-full py-4 bg-rose-600 hover:bg-rose-500 text-white font-black rounded-2xl shadow-xl transition-all active:scale-95 flex items-center justify-center gap-3 group">
                         End Session <ArrowRight className="w-5 h-5 group-hover:translate-x-1 transition-transform" />
                      </button>
                      <button onClick={() => setIsLogoutModalOpen(false)} className="w-full py-4 bg-slate-900/50 text-slate-400 font-bold rounded-2xl border border-white/5 hover:text-white transition-all">
                         Stay Connected
                      </button>
                  </div>
              </div>
          </div>
      )}

      <ToastContainer toasts={toasts} onRemove={removeToast} />
    </div>
  );
};

export default App;

import React, { useMemo, useState } from 'react';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import { Account, Transaction, TransactionType, Category, UserPlan, Goal } from '../types';
import { ArrowUpRight, DollarSign, Activity, Layers, Flame, TrendingUp, MoreHorizontal, ArrowRight, Wallet, PlusCircle, CreditCard, Target, ChevronRight, Quote, Landmark, Zap, Radio, RefreshCw, Repeat, Check, MessageCircle, Handshake, Copy, AlertCircle, X, Loader2, Tag, Microscope, Search, Volume2, Palette, Sparkles, Activity as ActivityIcon, ShieldCheck, Heart, Brain } from 'lucide-react';
import { generateNegotiationScript } from '../services/geminiService';

interface DashboardProps {
  accounts: Account[];
  transactions: Transaction[];
  goals: Goal[];
  onNavigate: (tab: string) => void;
  onAddAccount?: () => void;
  onAddTransaction?: () => void;
  onAddGoal?: () => void;
  formatCurrency: (amount: number) => string;
  userPlan?: UserPlan;
  onAskCoach?: (message: string) => void;
  negotiationUsage: number;
  onIncrementNegotiation: () => void;
}

const QUOTES = [
  { text: "Do not save what is left after spending, but spend what is left after saving.", author: "Warren Buffett" },
  { text: "A budget is telling your money where to go instead of wondering where it went.", author: "Dave Ramsey" },
  { text: "It's not your salary that makes you rich, it's your spending habits.", author: "Charles A. Jaffe" },
  { text: "The art is not in making money, but in keeping it.", author: "Proverb" },
];

const Dashboard: React.FC<DashboardProps> = ({ accounts, transactions, goals, onNavigate, onAddAccount, onAddTransaction, onAddGoal, formatCurrency, userPlan, onAskCoach, negotiationUsage, onIncrementNegotiation }) => {
  const hasData = accounts.length > 0 || transactions.length > 0;
  const randomQuote = useMemo(() => QUOTES[Math.floor(Math.random() * QUOTES.length)], []);
  const netWorth = useMemo(() => accounts.reduce((acc, curr) => acc + curr.balance, 0), [accounts]);

  const [isNegotiating, setIsNegotiating] = useState(false);
  const [script, setScript] = useState<string | null>(null);
  const [scriptMerchant, setScriptMerchant] = useState('');
  const [showNegotiationModal, setShowNegotiationModal] = useState(false);
  const [copySuccess, setCopySuccess] = useState(false);

  const today = new Date();
  today.setHours(0, 0, 0, 0);

  const monthlySpending = useMemo(() => {
    return transactions
      .filter(t => {
        const d = new Date(t.date);
        return t.type === TransactionType.EXPENSE && d.getMonth() === today.getMonth() && d.getFullYear() === today.getFullYear();
      })
      .reduce((acc, curr) => acc + curr.amount, 0);
  }, [transactions, today]);

  const monthlyIncome = useMemo(() => {
    return transactions
      .filter(t => {
        const d = new Date(t.date);
        return t.type === TransactionType.INCOME && d.getMonth() === today.getMonth() && d.getFullYear() === today.getFullYear();
      })
      .reduce((acc, curr) => acc + curr.amount, 0);
  }, [transactions, today]);

  const healthScore = useMemo(() => {
    if (!hasData) return 0;
    const savings = Math.max(0, monthlyIncome - monthlySpending);
    const goalMonthlyTarget = goals.reduce((acc, g) => {
        const remaining = g.targetAmount - g.currentAmount;
        if (remaining <= 0) return acc;
        const deadline = new Date(g.deadline);
        const monthsLeft = Math.max(1, (deadline.getTime() - today.getTime()) / (1000 * 60 * 60 * 24 * 30.44));
        return acc + (remaining / monthsLeft);
    }, 0);

    const targetBase = Math.max(goalMonthlyTarget, monthlyIncome * 0.2);
    if (targetBase === 0) return savings > 0 ? 80 : 50;

    return Math.min(100, Math.max(0, (savings / targetBase) * 100));
  }, [monthlyIncome, monthlySpending, goals, hasData, today]);

  const burnRate = monthlySpending / Math.max(today.getDate(), 1);

  const recurringData = useMemo(() => {
      const merchantMap = new Map<string, { count: number; total: number; amounts: number[]; categories: Set<Category>; }>();
      transactions.filter(t => t.type === TransactionType.EXPENSE).forEach(t => {
            const key = t.merchant.toLowerCase().trim();
            const existing = merchantMap.get(key) || { count: 0, total: 0, amounts: [], categories: new Set() };
            existing.count++;
            existing.total += t.amount;
            existing.amounts.push(t.amount);
            existing.categories.add(t.category);
            merchantMap.set(key, existing);
        });

      const items: { merchant: string; avgCost: number; isSubscription: boolean }[] = [];
      merchantMap.forEach((data, key) => {
          const avg = data.total / data.count;
          const isConsistent = data.amounts.every(a => Math.abs(a - avg) / (avg || 1) < 0.25);
          if (data.categories.has(Category.SUBSCRIPTION) || (data.count > 1 && isConsistent)) {
              items.push({ merchant: key, avgCost: avg, isSubscription: data.categories.has(Category.SUBSCRIPTION) });
          }
      });
      return items.sort((a,b) => b.avgCost - a.avgCost);
  }, [transactions]);

  const spendingData = useMemo(() => {
    const dataPoints: { date: string, actual: number | null, predicted: number | null }[] = [];
    const expenseMap = new Map<string, number>();

    transactions.filter(t => t.type === TransactionType.EXPENSE).forEach(t => {
        const d = new Date(t.date);
        d.setHours(0, 0, 0, 0);
        const key = d.toDateString();
        expenseMap.set(key, (expenseMap.get(key) || 0) + t.amount);
    });

    for (let i = 0; i <= 30; i++) {
        const d = new Date(today);
        d.setDate(today.getDate() - (30 - i));
        d.setHours(0, 0, 0, 0);
        dataPoints.push({
            date: d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }),
            actual: expenseMap.get(d.toDateString()) || 0,
            predicted: null
        });
    }

    const last = dataPoints[dataPoints.length - 1];
    last.predicted = last.actual;

    for (let i = 1; i <= 7; i++) {
        const d = new Date(today);
        d.setDate(today.getDate() + i);
        dataPoints.push({
            date: d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }),
            actual: null,
            predicted: burnRate * (1 + (Math.sin(i) * 0.1))
        });
    }
    return dataPoints;
  }, [transactions, burnRate, today]);

  const handleNegotiateClick = async (merchant: string, amount: number) => {
      const limit = userPlan === 'ultra' ? Infinity : userPlan === 'pro' ? 5 : 3;
      if (negotiationUsage >= limit) {
          onNavigate('plans');
          return; 
      }
      setIsNegotiating(true);
      setScriptMerchant(merchant);
      setShowNegotiationModal(true);
      const generated = await generateNegotiationScript(merchant, amount);
      setScript(generated);
      setIsNegotiating(false);
      onIncrementNegotiation();
  };

  const RoadmapSection = (
      <div className="glass-card p-10 rounded-[3rem] border border-indigo-500/20 bg-indigo-950/10 overflow-hidden relative group mt-12">
          <div className="absolute top-0 right-0 w-96 h-96 bg-indigo-500/5 blur-[100px] -mr-20 -mt-20 group-hover:opacity-100 transition-opacity"></div>
          <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-10 gap-6">
              <div>
                  <h3 className="text-2xl font-black text-white flex items-center gap-3"><Sparkles className="w-8 h-8 text-indigo-400" /> Nova Strategic Roadmap</h3>
                  <p className="text-slate-400 mt-2 font-medium">Upcoming Tier-1 protocols being developed in Nova Labs.</p>
              </div>
              <button onClick={() => onNavigate('upcoming')} className="px-5 py-2 bg-indigo-600 hover:bg-indigo-500 text-white rounded-full text-[10px] font-black uppercase tracking-widest transition-all shadow-lg active:scale-95 animate-pulse border border-indigo-400/30">Explore All Specs</button>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
              <RoadmapItem icon={<Volume2 className="w-6 h-6" />} title="Hands-Free" desc="Real-time voice logging via Gemini Live." tag="Q4 24" />
              <RoadmapItem icon={<ShieldCheck className="w-6 h-6" />} title="Anomaly Detect" desc="Identify spending spikes before they hit goals." tag="Dev" />
              <RoadmapItem icon={<Palette className="w-6 h-6" />} title="Haptic UI" desc="Elite 3D tilt effects and GPU shaders." tag="In Design" />
              <RoadmapItem icon={<Layers className="w-6 h-6" />} title="Bridge" desc="Multi-bank neural synchronization." tag="Planning" />
          </div>
      </div>
  );

  const handleCopyScript = () => {
      if (script) {
          navigator.clipboard.writeText(script);
          setCopySuccess(true);
          setTimeout(() => setCopySuccess(false), 2000);
      }
  };

  if (!hasData) {
     return (
        <div className="flex flex-col items-center justify-center w-full min-h-full py-12 animate-fade-in text-center relative overflow-hidden">
            <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[600px] h-[600px] bg-indigo-500/10 rounded-full blur-[120px] pointer-events-none animate-pulse-slow"></div>
            <div className="max-w-4xl mx-auto mb-12 relative z-10">
                <div className="flex justify-center mb-8">
                    <div className="w-14 h-14 rounded-2xl bg-gradient-to-tr from-amber-400 to-orange-500 flex items-center justify-center shadow-[0_0_30px_rgba(251,191,36,0.3)] rotate-3">
                        <Quote className="w-7 h-7 text-white fill-current" />
                    </div>
                </div>
                <h1 className="text-3xl md:text-4xl font-bold text-white tracking-tight mb-4 px-4">"{randomQuote.text}"</h1>
                <p className="text-lg text-slate-400 font-medium italic tracking-wide">— {randomQuote.author}</p>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6 w-full max-w-5xl relative z-10 px-4">
                 <button onClick={onAddAccount} className="group glass-card p-8 rounded-[2rem] text-left border border-white/5 hover:border-indigo-500/30 transition-all hover:-translate-y-2">
                    <div className="w-14 h-14 rounded-2xl bg-indigo-500/10 flex items-center justify-center mb-6 group-hover:bg-indigo-500 group-hover:text-white transition-colors text-indigo-400 shadow-inner"><Landmark className="w-7 h-7" /></div>
                    <h3 className="text-xl font-bold text-white mb-2">Connect Accounts</h3>
                    <p className="text-slate-400 text-sm leading-relaxed">Bridge your banks or add manual accounts to finalize your net worth profile.</p>
                 </button>
                 <button onClick={onAddTransaction} className="group glass-card p-8 rounded-[2rem] text-left border border-white/5 hover:border-emerald-500/30 transition-all hover:-translate-y-2">
                    <div className="w-14 h-14 rounded-2xl bg-emerald-500/10 flex items-center justify-center mb-6 group-hover:bg-emerald-500 group-hover:text-white transition-colors text-emerald-400 shadow-inner"><PlusCircle className="w-7 h-7" /></div>
                    <h3 className="text-xl font-bold text-white mb-2">Log Activity</h3>
                    <p className="text-slate-400 text-sm leading-relaxed">Archive your daily spending to calibrate the AI predictive core.</p>
                 </button>
                 <button onClick={onAddGoal} className="group glass-card p-8 rounded-[2rem] text-left border border-white/5 hover:border-rose-500/30 transition-all hover:-translate-y-2">
                    <div className="w-14 h-14 rounded-2xl bg-rose-500/10 flex items-center justify-center mb-6 group-hover:bg-rose-500 group-hover:text-white transition-colors text-rose-400 shadow-inner"><Target className="w-7 h-7" /></div>
                    <h3 className="text-xl font-bold text-white mb-2">Deploy Goals</h3>
                    <p className="text-slate-400 text-sm leading-relaxed">Establish savings targets and let the AI optimize your trajectory.</p>
                 </button>
            </div>
            <div className="w-full max-w-5xl mt-12 px-4">{RoadmapSection}</div>
        </div>
     );
  }

  return (
    <div className="space-y-8 animate-slide-up pb-10">
      <div className="glass-card p-8 rounded-[3rem] border border-white/10 relative overflow-hidden bg-gradient-to-br from-slate-900/50 via-slate-900/50 to-indigo-900/10">
          <div className="absolute top-0 right-0 w-64 h-64 bg-indigo-500/5 blur-[80px] -mr-20 -mt-20"></div>
          <div className="flex flex-col md:flex-row items-center gap-10">
              <div className="relative w-40 h-40 flex items-center justify-center shrink-0">
                  <svg className="w-full h-full transform -rotate-90">
                      <circle cx="80" cy="80" r="70" stroke="currentColor" strokeWidth="8" fill="transparent" className="text-slate-800" />
                      <circle 
                        cx="80" cy="80" r="70" stroke="currentColor" strokeWidth="10" fill="transparent" 
                        className={`transition-all duration-1000 ease-out ${healthScore > 75 ? 'text-emerald-500' : healthScore > 40 ? 'text-amber-500' : 'text-rose-500'}`} 
                        strokeDasharray={440} 
                        strokeDashoffset={440 - (440 * healthScore) / 100} 
                        strokeLinecap="round" 
                        style={{ filter: `drop-shadow(0 0 8px currentColor)`}}
                      />
                  </svg>
                  <div className="absolute text-center">
                      <div className="text-4xl font-black text-white tracking-tighter">{Math.round(healthScore)}</div>
                      <div className="text-[8px] font-black text-slate-500 uppercase tracking-widest mt-1">Health Index</div>
                  </div>
              </div>
              <div className="flex-1 text-center md:text-left">
                  <div className="flex items-center justify-center md:justify-start gap-3 mb-2">
                    <h2 className="text-3xl font-black text-white uppercase tracking-tight">Neural Health Status</h2>
                    <span className={`px-3 py-0.5 rounded-full text-[10px] font-black uppercase tracking-widest border ${healthScore > 75 ? 'bg-emerald-500/10 border-emerald-500/30 text-emerald-400' : 'bg-rose-500/10 border-rose-500/30 text-rose-400 animate-pulse'}`}>
                        {healthScore > 75 ? 'Optimal Flow' : healthScore > 40 ? 'Stable Core' : 'Critical Burn'}
                    </span>
                  </div>
                  <p className="text-slate-400 text-sm font-medium leading-relaxed max-w-xl">
                      {healthScore > 75 ? "Your capital allocation logic is superior. Monthly savings exceed active targets and baseline requirements." : 
                       healthScore > 40 ? "Your system is functional. Capital is reaching targets, but efficiency gaps exist in non-essential sectors." : 
                       "WARNING: Excessive burn rate detected. Local computation indicates high correlation with goal failure if trajectory is not corrected."}
                  </p>
                  <div className="flex flex-wrap justify-center md:justify-start gap-4 mt-6">
                      <div className="flex items-center gap-2 bg-white/5 border border-white/10 px-3 py-1.5 rounded-xl">
                          <Brain className="w-3.5 h-3.5 text-indigo-400" />
                          <span className="text-[10px] font-black text-slate-300 uppercase tracking-widest">100% Local Logic</span>
                      </div>
                      <div className="flex items-center gap-2 bg-white/5 border border-white/10 px-3 py-1.5 rounded-xl">
                          <ActivityIcon className="w-3.5 h-3.5 text-emerald-400" />
                          <span className="text-[10px] font-black text-slate-300 uppercase tracking-widest">Real-time Telemetry</span>
                      </div>
                  </div>
              </div>
          </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard title="Net Worth" value={formatCurrency(netWorth)} icon={<Wallet className="w-5 h-5 text-indigo-400" />} change="+2.4%" positive />
        <StatCard title="Monthly Spend" value={formatCurrency(monthlySpending)} icon={<CreditCard className="w-5 h-5 text-rose-400" />} change="-12%" positive />
        <StatCard title="Burn Rate / Day" value={formatCurrency(burnRate)} icon={<Flame className="w-5 h-5 text-amber-400" />} change="Stable" />
        <StatCard title="Predicted Spend" value={formatCurrency(burnRate * 30)} icon={<TrendingUp className="w-5 h-5 text-emerald-400" />} change="Neural Forecast" />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 glass-card p-8 rounded-[2.5rem] border border-white/10 relative overflow-hidden shadow-2xl">
            <div className="flex justify-between items-center mb-10">
                <h3 className="text-xl font-bold text-white flex items-center gap-3"><Activity className="w-6 h-6 text-indigo-400" />Expenditure Vector</h3>
                <div className="flex gap-2">
                    <span className="flex items-center gap-1.5 px-3 py-1 rounded-full bg-indigo-500/10 text-indigo-400 text-[10px] font-black border border-indigo-500/20">ACTUAL</span>
                    <span className="flex items-center gap-1.5 px-3 py-1 rounded-full bg-pink-500/10 text-pink-400 text-[10px] font-black border border-pink-500/20">PREDICTED</span>
                </div>
            </div>
            <div className="h-80 w-full">
                <ResponsiveContainer width="100%" height="100%">
                    <AreaChart data={spendingData}>
                        <defs>
                            <linearGradient id="colorActual" x1="0" y1="0" x2="0" y2="1">
                                <stop offset="5%" stopColor="#6366f1" stopOpacity={0.3}/>
                                <stop offset="95%" stopColor="#6366f1" stopOpacity={0}/>
                            </linearGradient>
                            <linearGradient id="colorPredicted" x1="0" y1="0" x2="0" y2="1">
                                <stop offset="5%" stopColor="#ec4899" stopOpacity={0.2}/>
                                <stop offset="95%" stopColor="#ec4899" stopOpacity={0}/>
                            </linearGradient>
                        </defs>
                        <CartesianGrid strokeDasharray="3 3" stroke="#1e293b" vertical={false} />
                        <XAxis dataKey="date" stroke="#64748b" fontSize={11} tickLine={false} axisLine={false} />
                        <YAxis stroke="#64748b" fontSize={11} tickLine={false} axisLine={false} hide />
                        <Tooltip 
                            contentStyle={{ backgroundColor: '#0f172a', border: '1px solid rgba(255,255,255,0.1)', borderRadius: '12px' }}
                            itemStyle={{ color: '#fff', fontSize: '12px', fontWeight: 'bold' }}
                        />
                        <Area type="monotone" dataKey="actual" stroke="#6366f1" strokeWidth={4} fillOpacity={1} fill="url(#colorActual)" animationDuration={1500} />
                        <Area type="monotone" dataKey="predicted" stroke="#ec4899" strokeWidth={3} strokeDasharray="6 6" fillOpacity={1} fill="url(#colorPredicted)" animationDuration={1500} />
                    </AreaChart>
                </ResponsiveContainer>
            </div>
        </div>

        <div className="glass-card p-8 rounded-[2.5rem] border border-white/10 shadow-2xl flex flex-col">
            <h3 className="text-xl font-bold text-white mb-6 flex items-center gap-3"><Repeat className="w-6 h-6 text-emerald-400" />Subscription Shield</h3>
            <div className="space-y-4 flex-1 overflow-y-auto custom-scrollbar pr-2">
                {recurringData.length > 0 ? recurringData.map((item, idx) => (
                    <div key={idx} className="p-4 bg-slate-950/50 rounded-2xl border border-white/5 group/item transition-all hover:bg-slate-900/80 hover:border-emerald-500/30">
                        <div className="flex justify-between items-start mb-3">
                            <div className="flex items-center gap-3">
                                <div className="w-10 h-10 rounded-xl bg-slate-800 flex items-center justify-center border border-white/5"><Radio className="w-5 h-5 text-emerald-400" /></div>
                                <div>
                                    <h4 className="text-sm font-bold text-white capitalize">{item.merchant}</h4>
