                                    <div key={i} className="flex justify-between items-center group/sink">
                                        <div className="flex items-center gap-2">
                                            <div className="w-1 h-4 bg-indigo-500/40 rounded-full group-hover/sink:h-6 transition-all duration-300"></div>
                                            <span className="text-[10px] font-bold text-slate-400 uppercase tracking-wider">{cat}</span>
                                        </div>
                                        <span className="text-xs font-black text-white">{formatCurrency(amount)}</span>
                                    </div>
                                ))}
                           </div>
                      </div>

                      {/* Bottom Sink (Savings/Yield) */}
