                      </div>
                  </div>
              </div>
          </div>

          <div className="mt-20 w-full max-w-3xl grid grid-cols-2 md:grid-cols-4 gap-4">
               <TopologyStat label="Logic Verified" icon={<Check className="w-4 h-4 text-emerald-500" />} />
               <TopologyStat label="Paths Calibrated" icon={<Check className="w-4 h-4 text-emerald-500" />} />
               <TopologyStat label="Yield Optimized" icon={<Check className="w-4 h-4 text-emerald-500" />} />
               <TopologyStat label="Sync Balanced" icon={<Check className="w-4 h-4 text-emerald-500" />} />
          </div>
      </div>

      {!isElite && (
          <div className="p-8 bg-indigo-600/10 border border-indigo-500/20 rounded-[2rem] flex flex-col md:flex-row items-center justify-between gap-6">
              <div className="flex items-center gap-4">
