                           <Zap className="w-6 h-6 text-indigo-400 mx-auto mb-3" />
                           <h5 className="text-[9px] font-black text-indigo-400 uppercase tracking-widest mb-1">Yield Buffer / Savings</h5>
                           <div className="text-2xl font-black text-white tracking-tighter">{formatCurrency(flowData.savings)}</div>
