import React, { useState, useMemo } from 'react';
import { Account, Budget, Transaction, TransactionType, UserPlan } from '../types';
import { Plus, Wallet, CreditCard, Landmark, TrendingUp, Edit2, Trash2, XCircle, DollarSign, AlertCircle, User as UserIcon, ArrowRightCircle, Tag } from 'lucide-react';

interface AccountsProps {
  accounts: Account[];
  budgets: Budget[];
  transactions: Transaction[];
  userPlan: UserPlan;
  onAdd: (account: Account) => void;
  onUpdate: (account: Account) => void;
  onDelete: (id: string) => void;
  formatCurrency: (amount: number) => string | React.ReactNode;
  userName: string;
  userAvatar: string;
  userAvatarZoom: number;
  userAvatarPos: { x: number; y: number };
  userBorder: string; 
  onNavigate: (tab: string) => void; 
}

const Accounts: React.FC<AccountsProps> = ({ 
  accounts, 
  budgets, 
  transactions, 
  userPlan, 
  onAdd, 
  onUpdate, 
  onDelete, 
  formatCurrency,
  userName,
  userAvatar,
  userAvatarZoom,
  userAvatarPos,
  userBorder,
  onNavigate
