  const currentMonth = today.getMonth();
  const currentYear = today.getFullYear();
  const daysInMonth = new Date(currentYear, currentMonth + 1, 0).getDate();

  const monthlySpending = useMemo(() => {
    return transactions
      .filter(t => {
        const d = new Date(t.date);
        return t.type === TransactionType.EXPENSE && d.getMonth() === currentMonth && d.getFullYear() === currentYear;
      })
      .reduce((acc, curr) => acc + curr.amount, 0);
  }, [transactions, currentMonth, currentYear]);

  const burnRate = monthlySpending / Math.max(today.getDate(), 1);

  const recurringData = useMemo(() => {
      const merchantMap = new Map<string, { count: number; total: number; amounts: number[]; categories: Set<Category>; }>();
      transactions.filter(t => t.type === TransactionType.EXPENSE).forEach(t => {
            const key = t.merchant.toLowerCase().trim();
            const existing = merchantMap.get(key) || { count: 0, total: 0, amounts: [], categories: new Set() };
            existing.count++;
            existing.total += t.amount;
            existing.amounts.push(t.amount);
            existing.categories.add(t.category);
            merchantMap.set(key, existing);
        });

      const items: { merchant: string; avgCost: number; isSubscription: boolean }[] = [];
      merchantMap.forEach((data, key) => {
          const avg = data.total / data.count;
          const isConsistent = data.amounts.every(a => Math.abs(a - avg) / (avg || 1) < 0.25);
          if (data.categories.has(Category.SUBSCRIPTION) || (data.count > 1 && isConsistent)) {
              items.push({ merchant: key, avgCost: avg, isSubscription: data.categories.has(Category.SUBSCRIPTION) });
          }
      });
      return items.sort((a,b) => b.avgCost - a.avgCost);
  }, [transactions]);

  const spendingData = useMemo(() => {
    const dataPoints: { date: string, actual: number | null, predicted: number | null }[] = [];
    const expenseMap = new Map<string, number>();

    transactions.filter(t => t.type === TransactionType.EXPENSE).forEach(t => {
        const d = new Date(t.date);
        d.setHours(0, 0, 0, 0);
        const key = d.toDateString();
        expenseMap.set(key, (expenseMap.get(key) || 0) + t.amount);
    });

    for (let i = 0; i <= 30; i++) {
        const d = new Date(today);
        d.setDate(today.getDate() - (30 - i));
        d.setHours(0, 0, 0, 0);
        dataPoints.push({
            date: d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }),
            actual: expenseMap.get(d.toDateString()) || 0,
            predicted: null
        });
    }

    const last = dataPoints[dataPoints.length - 1];
    last.predicted = last.actual;

    for (let i = 1; i <= 7; i++) {
        const d = new Date(today);
        d.setDate(today.getDate() + i);
        dataPoints.push({
            date: d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }),
            actual: null,
            predicted: burnRate * (1 + (Math.sin(i) * 0.1))
        });
    }
    return dataPoints;
  }, [transactions, burnRate, today]);

  const handleNegotiateClick = async (merchant: string, amount: number) => {
      const limit = userPlan === 'ultra' ? Infinity : userPlan === 'pro' ? 5 : 3;
      if (negotiationUsage >= limit) {
          onNavigate('plans');
          return; 
      }
      setIsNegotiating(true);
      setScriptMerchant(merchant);
      setShowNegotiationModal(true);
      const generated = await generateNegotiationScript(merchant, amount);
      setScript(generated);
      setIsNegotiating(false);
      onIncrementNegotiation();
  };

  const handleCopyScript = () => {
      if (script) {
          navigator.clipboard.writeText(script);
          setCopySuccess(true);
          setTimeout(() => setCopySuccess(false), 2000);
      }
  };

  if (!hasData) {
     return (
        <div className="flex flex-col items-center justify-center w-full min-h-full py-12 animate-fade-in text-center relative overflow-hidden">
            <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[600px] h-[600px] bg-indigo-500/10 rounded-full blur-[120px] pointer-events-none animate-pulse-slow"></div>
            <div className="max-w-4xl mx-auto mb-12 relative z-10">
                <div className="flex justify-center mb-8">
                    <div className="w-14 h-14 rounded-2xl bg-gradient-to-tr from-amber-400 to-orange-500 flex items-center justify-center shadow-[0_0_30px_rgba(251,191,36,0.3)] rotate-3">
                        <Quote className="w-7 h-7 text-white fill-current" />
                    </div>
                </div>
                <h1 className="text-3xl md:text-4xl font-bold text-white tracking-tight mb-4 px-4">"{randomQuote.text}"</h1>
                <p className="text-lg text-slate-400 font-medium italic tracking-wide">— {randomQuote.author}</p>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6 w-full max-w-5xl relative z-10 px-4">
                 <button onClick={onAddAccount} className="group glass-card p-8 rounded-[2rem] text-left border border-white/5 hover:border-indigo-500/30 transition-all hover:-translate-y-2">
                    <div className="w-14 h-14 rounded-2xl bg-indigo-500/10 flex items-center justify-center mb-6 group-hover:bg-indigo-500 group-hover:text-white transition-colors text-indigo-400 shadow-inner"><Landmark className="w-7 h-7" /></div>
                    <h3 className="text-xl font-bold text-white mb-2">Connect Accounts</h3>
                    <p className="text-slate-400 text-sm leading-relaxed">Bridge your banks or add manual accounts to finalize your net worth profile.</p>
                 </button>
                 <button onClick={onAddTransaction} className="group glass-card p-8 rounded-[2rem] text-left border border-white/5 hover:border-emerald-500/30 transition-all hover:-translate-y-2">
                    <div className="w-14 h-14 rounded-2xl bg-emerald-500/10 flex items-center justify-center mb-6 group-hover:bg-emerald-500 group-hover:text-white transition-colors text-emerald-400 shadow-inner"><PlusCircle className="w-7 h-7" /></div>
                    <h3 className="text-xl font-bold text-white mb-2">Log Activity</h3>
                    <p className="text-slate-400 text-sm leading-relaxed">Archive your daily spending to calibrate the AI predictive core.</p>
                 </button>
                 <button onClick={onAddGoal} className="group glass-card p-8 rounded-[2rem] text-left border border-white/5 hover:border-rose-500/30 transition-all hover:-translate-y-2">
                    <div className="w-14 h-14 rounded-2xl bg-rose-500/10 flex items-center justify-center mb-6 group-hover:bg-rose-500 group-hover:text-white transition-colors text-rose-400 shadow-inner"><Target className="w-7 h-7" /></div>
                    <h3 className="text-xl font-bold text-white mb-2">Deploy Goals</h3>
                    <p className="text-slate-400 text-sm leading-relaxed">Establish savings targets and let the AI optimize your trajectory.</p>
                 </button>
            </div>
        </div>
     );
  }

  return (
    <div className="space-y-8 animate-slide-up pb-10">

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard title="Net Worth" value={formatCurrency(netWorth)} icon={<Wallet className="w-5 h-5 text-indigo-400" />} change="+2.4%" positive />
        <StatCard title="Monthly Spend" value={formatCurrency(monthlySpending)} icon={<CreditCard className="w-5 h-5 text-rose-400" />} change="-12%" positive />
        <StatCard title="Burn Rate / Day" value={formatCurrency(burnRate)} icon={<Flame className="w-5 h-5 text-amber-400" />} change="Stable" />
        <StatCard title="Predicted Spend" value={formatCurrency(burnRate * daysInMonth)} icon={<TrendingUp className="w-5 h-5 text-emerald-400" />} change="Linear Forecast" />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 glass-card p-8 rounded-[2.5rem] border border-white/10 relative overflow-hidden shadow-2xl">
            <div className="flex justify-between items-center mb-10">
                <h3 className="text-xl font-bold text-white flex items-center gap-3"><Activity className="w-6 h-6 text-indigo-400" />Expenditure Vector</h3>
                <div className="flex gap-2">
                    <span className="flex items-center gap-1.5 px-3 py-1 rounded-full bg-indigo-500/10 text-indigo-400 text-[10px] font-black border border-indigo-500/20">ACTUAL</span>
                    <span className="flex items-center gap-1.5 px-3 py-1 rounded-full bg-pink-500/10 text-pink-400 text-[10px] font-black border border-pink-500/20">PREDICTED</span>
                </div>
            </div>
            <div className="h-80 w-full">
                <ResponsiveContainer width="100%" height="100%">
                    <AreaChart data={spendingData}>
                        <defs>
                            <linearGradient id="colorActual" x1="0" y1="0" x2="0" y2="1">
                                <stop offset="5%" stopColor="#6366f1" stopOpacity={0.3}/>
                                <stop offset="95%" stopColor="#6366f1" stopOpacity={0}/>
                            </linearGradient>
                            <linearGradient id="colorPredicted" x1="0" y1="0" x2="0" y2="1">
                                <stop offset="5%" stopColor="#ec4899" stopOpacity={0.2}/>
                                <stop offset="95%" stopColor="#ec4899" stopOpacity={0}/>
                            </linearGradient>
                        </defs>
                        <CartesianGrid strokeDasharray="3 3" stroke="#1e293b" vertical={false} />
                        <XAxis dataKey="date" stroke="#64748b" fontSize={11} tickLine={false} axisLine={false} />
                        <YAxis stroke="#64748b" fontSize={11} tickLine={false} axisLine={false} hide />
                        <Tooltip 
                            contentStyle={{ backgroundColor: '#0f172a', border: '1px solid rgba(255,255,255,0.1)', borderRadius: '12px' }}
                            itemStyle={{ color: '#fff', fontSize: '12px', fontWeight: 'bold' }}
                        />
                        <Area type="monotone" dataKey="actual" stroke="#6366f1" strokeWidth={4} fillOpacity={1} fill="url(#colorActual)" animationDuration={1500} />
                        <Area type="monotone" dataKey="predicted" stroke="#ec4899" strokeWidth={3} strokeDasharray="6 6" fillOpacity={1} fill="url(#colorPredicted)" animationDuration={1500} />
                    </AreaChart>
                </ResponsiveContainer>
            </div>
        </div>

        <div className="glass-card p-8 rounded-[2.5rem] border border-white/10 shadow-2xl flex flex-col">
            <h3 className="text-xl font-bold text-white mb-6 flex items-center gap-3"><Repeat className="w-6 h-6 text-emerald-400" />Subscription Shield</h3>
            <div className="space-y-4 flex-1 overflow-y-auto custom-scrollbar pr-2">
                {recurringData.length > 0 ? recurringData.map((item, idx) => (
                    <div key={idx} className="p-4 bg-slate-950/50 rounded-2xl border border-white/5 group/item transition-all hover:bg-slate-900/80 hover:border-emerald-500/30">
                        <div className="flex justify-between items-start mb-3">
                            <div className="flex items-center gap-3">
                                <div className="w-10 h-10 rounded-xl bg-slate-800 flex items-center justify-center border border-white/5"><Radio className="w-5 h-5 text-emerald-400" /></div>
                                <div>
                                    <h4 className="text-sm font-bold text-white capitalize">{item.merchant}</h4>
                                    <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">{item.isSubscription ? 'Subscription' : 'Recurring'}</p>
                                </div>
                            </div>
                            <div className="text-right">
                                <div className="text-sm font-bold text-white">{formatCurrency(item.avgCost)}</div>
                                <p className="text-[9px] text-slate-500 font-medium">Monthly Burn</p>
                            </div>
                        </div>
                        <button 
                            onClick={() => handleNegotiateClick(item.merchant, item.avgCost)}
                            className="w-full py-2.5 bg-indigo-600/10 hover:bg-indigo-600 text-indigo-400 hover:text-white rounded-xl text-[10px] font-black uppercase tracking-[0.2em] transition-all flex items-center justify-center gap-2 group/btn"
                        >
                            <Handshake className="w-3.5 h-3.5" /> Optimize Rate
                        </button>
                    </div>
                )) : (
                    <div className="flex flex-col items-center justify-center h-full text-center opacity-40">
                        <ActivityIcon className="w-12 h-12 mb-4" />
                        <p className="text-sm font-medium">Zero recurring patterns identified in current data set.</p>
                    </div>
                )}
            </div>
        </div>
      </div>

      {showNegotiationModal && (
          <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-black/95 backdrop-blur-2xl animate-fade-in">
              <div className="bg-[#020617] border border-white/10 rounded-[3rem] w-full max-w-xl shadow-2xl overflow-hidden animate-slide-up relative">
                  <button onClick={() => setShowNegotiationModal(false)} className="absolute top-6 right-6 p-2 text-slate-500 hover:text-white z-10"><X className="w-6 h-6" /></button>
                  <div className="p-10 border-b border-white/5 bg-gradient-to-br from-indigo-900/20 to-transparent">
                      <div className="w-16 h-16 bg-indigo-600 rounded-2xl flex items-center justify-center mb-6 shadow-xl"><Zap className="w-8 h-8 text-white fill-white" /></div>
                      <h3 className="text-3xl font-black text-white uppercase tracking-tighter">AI Negotiation Uplink</h3>
                      <p className="text-slate-400 text-sm mt-1 font-medium italic">Logic generated for {scriptMerchant}</p>
                  </div>
                  <div className="p-10">
                      {isNegotiating ? (
                          <div className="py-12 flex flex-col items-center justify-center gap-6">
                              <Loader2 className="w-12 h-12 text-indigo-500 animate-spin" />
                              <p className="text-indigo-400 font-bold uppercase tracking-[0.3em] text-xs animate-pulse">Running counter-offer logic...</p>
                          </div>
                      ) : (
                          <div className="animate-fade-in">
                               <div className="relative group">
                                    <div className="absolute inset-0 bg-indigo-500/5 rounded-2xl -m-2 opacity-0 group-hover:opacity-100 transition-opacity"></div>
                                    <div className="bg-slate-900/50 rounded-2xl p-6 border border-white/5 text-slate-200 font-medium leading-relaxed italic text-sm mb-8 max-h-60 overflow-y-auto custom-scrollbar relative z-10">
                                        "{script}"
                                    </div>
                               </div>
                               <div className="flex gap-4">
                                    <button 
                                        onClick={handleCopyScript}
                                        className="flex-1 py-4 bg-indigo-600 hover:bg-indigo-500 text-white font-black uppercase tracking-[0.2em] text-xs rounded-2xl transition-all shadow-xl flex items-center justify-center gap-3 active:scale-95"
                                    >
                                        {copySuccess ? <Check className="w-5 h-5" /> : <Copy className="w-5 h-5" />}
                                        {copySuccess ? 'Copied to Buffer' : 'Copy Script'}
                                    </button>
                               </div>
                               <div className="mt-8 p-4 bg-amber-500/5 rounded-2xl border border-amber-500/10 flex items-start gap-4">
                                   <AlertCircle className="w-5 h-5 text-amber-500 shrink-0 mt-0.5" />
                                   <p className="text-[10px] text-amber-200/60 leading-relaxed font-bold uppercase tracking-wider">
                                       AI Tip: Send this script to {scriptMerchant} support via live chat. This approach has a 65% higher success rate for price reductions.
                                   </p>
                               </div>
                          </div>
                      )}
                  </div>
              </div>
          </div>
      )}
    </div>
  );
};

const StatCard: React.FC<{ title: string, value: string | React.ReactNode, icon: React.ReactNode, change?: string, positive?: boolean }> = ({ title, value, icon, change, positive }) => (
    <div className="glass-card p-6 rounded-3xl border border-white/10 group hover:border-indigo-500/30 transition-all hover:-translate-y-1 relative overflow-hidden">
        <div className="absolute top-0 right-0 w-24 h-24 bg-gradient-to-br from-white/5 to-transparent rounded-full -mr-12 -mt-12 transition-opacity group-hover:opacity-20"></div>
        <div className="flex justify-between items-center mb-6">
            <div className="p-3 bg-slate-800 rounded-2xl border border-white/5 group-hover:bg-indigo-500 transition-colors group-hover:text-white">{icon}</div>
            {change && (
                <span className={`text-[10px] font-black px-2 py-1 rounded-lg ${positive ? 'bg-emerald-500/10 text-emerald-400' : 'bg-indigo-500/10 text-indigo-400'}`}>
                    {change}
                </span>
            )}
        </div>
        <div className="space-y-1">
            <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest">{title}</h4>
            <div className="text-2xl font-black text-white tracking-tight">{value}</div>
        </div>
    </div>
);

export default Dashboard;

import React, { useEffect, useState, useMemo } from 'react';
import { Target, Trophy, Plane, Home, TrendingUp, Plus, DollarSign, Laptop, Check, Star, XCircle, Wallet, Gift, AlertCircle, PieChart, Trash2 } from 'lucide-react';
import { Goal, Budget, Transaction, TransactionType, Category } from '../types';
import confetti from 'canvas-confetti';

interface GoalsProps {
  goals?: Goal[];
  budgets?: Budget[];
  transactions?: Transaction[];
  onAddGoal?: (goal: Goal) => void;
  onUpdateGoal?: (goal: Goal) => void;
  onAddBudget?: (budget: Budget) => void;
  onDeleteBudget?: (id: string) => void;
  formatCurrency: (amount: number) => string | React.ReactNode;
}

const Goals: React.FC<GoalsProps> = ({ goals = [], budgets = [], transactions = [], onAddGoal, onUpdateGoal, onAddBudget, onDeleteBudget, formatCurrency }) => {
    const [isAddGoalModalOpen, setIsAddGoalModalOpen] = useState(false);
    const [isAddBudgetModalOpen, setIsAddBudgetModalOpen] = useState(false);
    const [selectedGoal, setSelectedGoal] = useState<Goal | null>(null);
    const [depositAmount, setDepositAmount] = useState('');
    const [streak, setStreak] = useState(0);

    useEffect(() => {
        const lastVisit = localStorage.getItem('nova_last_visit');
        const currentStreak = parseInt(localStorage.getItem('nova_streak') || '0');
        const today = new Date().toDateString();

        if (lastVisit !== today) {
            const yesterday = new Date();
            yesterday.setDate(yesterday.getDate() - 1);
            if (lastVisit === yesterday.toDateString()) {
                const newStreak = currentStreak + 1;
                setStreak(newStreak);
                localStorage.setItem('nova_streak', newStreak.toString());
            } else {
                setStreak(1);
                localStorage.setItem('nova_streak', '1');
            }
            localStorage.setItem('nova_last_visit', today);
        } else {
            setStreak(currentStreak || 1);
        }
    }, []);

    const handleDeposit = (e: React.FormEvent) => {
        e.preventDefault();
        if (!selectedGoal || !depositAmount) return;

        const amount = parseFloat(depositAmount);
        const newAmount = selectedGoal.currentAmount + amount;

        const updatedGoal = { ...selectedGoal, currentAmount: newAmount };
        if (onUpdateGoal) onUpdateGoal(updatedGoal);

        if (newAmount >= selectedGoal.targetAmount && selectedGoal.currentAmount < selectedGoal.targetAmount) {
             confetti({
                particleCount: 150,
                spread: 100,
                origin: { y: 0.6 },
                colors: ['#6366f1', '#ec4899', '#10b981', '#fbbf24']
            });
        }
        setSelectedGoal(null);
        setDepositAmount('');
    };

    return (
        <div className="space-y-12 animate-fade-in pb-10">
            <div><h2 className="text-3xl font-bold text-white tracking-tight">Goals & Budgets</h2><p className="text-slate-400 mt-2 font-medium max-w-lg">Manage your monthly limits and save for your biggest dreams.</p></div>

            <div className="relative bg-gradient-to-br from-indigo-900 to-violet-900 p-8 rounded-[2rem] shadow-2xl overflow-hidden group hover:scale-[1.01] transition-all duration-500 border border-white/10">
                <div className="absolute top-0 right-0 w-80 h-80 bg-gradient-to-br from-indigo-500/20 via-purple-500/20 to-transparent rounded-full blur-3xl -mr-20 -mt-20 group-hover:opacity-100 transition-opacity"></div>
                <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-full h-full bg-[radial-gradient(ellipse_at_center,_var(--tw-gradient-stops))] from-amber-500/10 via-transparent to-transparent opacity-50 pointer-events-none"></div>
                <div className="relative z-10 flex flex-col md:flex-row items-center gap-6 text-center md:text-left">
                    <div className="w-20 h-20 bg-gradient-to-tr from-amber-400 to-orange-500 rounded-3xl flex items-center justify-center shadow-[0_0_30px_rgba(251,191,36,0.4)] ring-4 ring-white/10 rotate-3 group-hover:rotate-6 transition-transform duration-500"><Trophy className="w-10 h-10 text-white drop-shadow-md" /></div>
                    <div className="flex-1">
                        <div className="flex items-center justify-center md:justify-start gap-3 mb-1"><h3 className="text-2xl font-extrabold text-white tracking-tight">{streak} Day Streak!</h3><span className="text-2xl animate-bounce filter drop-shadow-lg">🔥</span></div>
                        <p className="text-indigo-100 text-sm leading-relaxed font-medium max-w-xl opacity-90">Consistency compounds! You've checked in <span className="text-amber-300 font-bold">{streak} days in a row</span>.</p>
                    </div>
                </div>
            </div>

            <div>
                <div className="flex justify-between items-center mb-6"><h3 className="text-xl font-bold text-white flex items-center gap-2"><PieChart className="w-5 h-5 text-indigo-400" />Monthly Limits</h3><button onClick={() => setIsAddBudgetModalOpen(true)} className="px-4 py-2 bg-slate-800 hover:bg-slate-700 text-white rounded-xl text-sm font-bold border border-white/10 transition-colors flex items-center gap-2"><Plus className="w-4 h-4" /> Set Limit</button></div>
                {budgets.length === 0 ? (
                    <div className="glass-card p-10 rounded-3xl text-center border-dashed border-2 border-slate-700"><div className="w-16 h-16 rounded-full bg-slate-800/50 flex items-center justify-center mx-auto mb-4"><Wallet className="w-8 h-8 text-slate-500" /></div><h4 className="text-lg font-bold text-white mb-2">No active budgets</h4><p className="text-slate-400 text-sm max-w-sm mx-auto mb-6">Take control of your spending by setting limits for categories like Food or Shopping.</p><button onClick={() => setIsAddBudgetModalOpen(true)} className="text-indigo-400 hover:text-indigo-300 font-bold text-sm">Create your first budget &rarr;</button></div>
                ) : (
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                        {budgets.map((budget) => (<BudgetCard key={budget.id} budget={budget} transactions={transactions} onDelete={onDeleteBudget} formatCurrency={formatCurrency} />))}
                    </div>
                )}
            </div>

            <div className="h-px bg-white/5 w-full"></div>

            <div>
                <div className="flex justify-between items-center mb-6"><h3 className="text-xl font-bold text-white flex items-center gap-2"><Target className="w-5 h-5 text-emerald-400" />Savings Targets</h3><button onClick={() => setIsAddGoalModalOpen(true)} className="px-4 py-2 bg-slate-800 hover:bg-slate-700 text-white rounded-xl text-sm font-bold border border-white/10 transition-colors flex items-center gap-2"><Plus className="w-4 h-4" /> New Goal</button></div>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                    {goals.map((goal) => {
                        const progress = Math.min((goal.currentAmount / goal.targetAmount) * 100, 100);
                        const isCompleted = progress >= 100;
                        return (
                            <div key={goal.id} onClick={() => setSelectedGoal(goal)} className={`group glass-card p-7 rounded-[2rem] transition-all duration-300 hover:-translate-y-2 shadow-xl relative overflow-hidden cursor-pointer ${isCompleted ? 'border-amber-400/30 shadow-[0_0_50px_rgba(251,191,36,0.15)]' : 'border-white/5 hover:border-white/20'}`}>
                                <div className={`absolute top-0 right-0 w-48 h-48 bg-gradient-to-br ${goal.color} opacity-10 blur-[60px] rounded-full -mr-10 -mt-10 group-hover:opacity-25 transition-opacity duration-500`}></div>
                                {isCompleted && <div className="absolute inset-0 bg-gradient-to-br from-amber-500/10 to-transparent pointer-events-none"></div>}
                                <div className="flex justify-between items-start mb-8 relative z-10">
                                    <div className={`p-4 rounded-2xl bg-gradient-to-br ${goal.color} shadow-lg shadow-black/20 text-white ring-1 ring-white/20 transform group-hover:scale-110 transition-transform duration-300`}>
