import React, { useMemo, useState } from 'react';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import { Account, Transaction, TransactionType, Category, UserPlan, Goal } from '../types';
import { Activity, Flame, TrendingUp, Wallet, PlusCircle, CreditCard, Target, Quote, Landmark, Zap, Radio, Repeat, Check, Handshake, Copy, AlertCircle, X, Loader2, Sparkles, ArrowUpRight, ArrowDownRight, LayoutGrid } from 'lucide-react';
import { generateNegotiationScript } from '../services/geminiService';

interface DashboardProps {
  accounts: Account[];
  transactions: Transaction[];
  goals: Goal[];
  onNavigate: (tab: string) => void;
  onAddAccount?: () => void;
  onAddTransaction?: () => void;
  onAddGoal?: () => void;
  formatCurrency: (amount: number) => string | React.ReactNode;
  userPlan?: UserPlan;
  onAskCoach?: (message: string) => void;
  negotiationUsage: number;
  onIncrementNegotiation: () => void;
}

const QUOTES = [
  { text: "Do not save what is left after spending, but spend what is left after saving.", author: "Warren Buffett" },
  { text: "A budget is telling your money where to go instead of wondering where it went.", author: "Dave Ramsey" },
  { text: "It's not your salary that makes you rich, it's your spending habits.", author: "Charles A. Jaffe" },
];

const Dashboard: React.FC<DashboardProps> = ({ accounts, transactions, goals, onNavigate, onAddAccount, onAddTransaction, onAddGoal, formatCurrency, userPlan, onAskCoach, negotiationUsage, onIncrementNegotiation }) => {
  const hasData = accounts.length > 0 || transactions.length > 0;
  const randomQuote = useMemo(() => QUOTES[Math.floor(Math.random() * QUOTES.length)], []);
  const netWorth = useMemo(() => accounts.reduce((acc, curr) => acc + curr.balance, 0), [accounts]);

  const [isNegotiating, setIsNegotiating] = useState(false);
  const [script, setScript] = useState<string | null>(null);
  const [scriptMerchant, setScriptMerchant] = useState('');
  const [showNegotiationModal, setShowNegotiationModal] = useState(false);
  const [copySuccess, setCopySuccess] = useState(false);

  // Time Logic
  const today = new Date();
  const currentMonth = today.getMonth();
  const currentYear = today.getFullYear();
  const currentDay = today.getDate();
  const daysInMonth = new Date(currentYear, currentMonth + 1, 0).getDate();

  const prevMonthDate = new Date(currentYear, currentMonth - 1, 1);
  const prevMonth = prevMonthDate.getMonth();
  const prevMonthYear = prevMonthDate.getFullYear();
  const daysInPrevMonth = new Date(prevMonthYear, prevMonth + 1, 0).getDate();

  // Statistics Calculations
  const stats = useMemo(() => {
    // 1. Monthly Spend (Current vs Prev MTD)
    const currentMTDTransactions = transactions.filter(t => {
      const d = new Date(t.date);
      return t.type === TransactionType.EXPENSE && d.getMonth() === currentMonth && d.getFullYear() === currentYear;
    });
    const currentMTDSpend = currentMTDTransactions.reduce((acc, t) => acc + t.amount, 0);

    const prevMTDTransactions = transactions.filter(t => {
      const d = new Date(t.date);
      return t.type === TransactionType.EXPENSE && d.getMonth() === prevMonth && d.getFullYear() === prevMonthYear && d.getDate() <= currentDay;
    });
    const prevMTDSpend = prevMTDTransactions.reduce((acc, t) => acc + t.amount, 0);
    const spendChange = prevMTDSpend > 0 ? ((currentMTDSpend - prevMTDSpend) / prevMTDSpend) * 100 : 0;

    // 2. Net Worth Change (MTD Delta)
    const mtdDelta = transactions
      .filter(t => {
        const d = new Date(t.date);
        return d.getMonth() === currentMonth && d.getFullYear() === currentYear;
      })
      .reduce((acc, t) => acc + (t.type === TransactionType.INCOME ? t.amount : -t.amount), 0);
    const startingNetWorth = netWorth - mtdDelta;
    const netWorthChange = startingNetWorth !== 0 ? (mtdDelta / Math.abs(startingNetWorth)) * 100 : 0;

    // 3. Burn Rate (Avg daily spend)
    const dailyAvgCurrent = currentMTDSpend / Math.max(currentDay, 1);
    const prevMonthFullTransactions = transactions.filter(t => {
      const d = new Date(t.date);
      return t.type === TransactionType.EXPENSE && d.getMonth() === prevMonth && d.getFullYear() === prevMonthYear;
    });
    const prevFullSpend = prevMonthFullTransactions.reduce((acc, t) => acc + t.amount, 0);
    const dailyAvgPrev = prevFullSpend / Math.max(daysInPrevMonth, 1);
    const burnChange = dailyAvgPrev > 0 ? ((dailyAvgCurrent - dailyAvgPrev) / dailyAvgPrev) * 100 : 0;

    // 4. Predicted vs Prev Full
    const predictedSpend = dailyAvgCurrent * daysInMonth;
    const predictChange = prevFullSpend > 0 ? ((predictedSpend - prevFullSpend) / prevFullSpend) * 100 : 0;

    return {
      mtdSpend: currentMTDSpend,
      spendChange,
      netWorthChange,
      burnRate: dailyAvgCurrent,
      burnChange,
      predictedSpend,
      predictChange,
      prevFullSpend
    };
  }, [transactions, currentMonth, currentYear, prevMonth, prevMonthYear, currentDay, netWorth, daysInMonth, daysInPrevMonth]);

  const recurringData = useMemo(() => {
      const merchantMap = new Map<string, { count: number; total: number; amounts: number[]; categories: Set<Category>; }>();
      transactions.filter(t => t.type === TransactionType.EXPENSE).forEach(t => {
            const key = t.merchant.toLowerCase().trim();
            const existing = merchantMap.get(key) || { count: 0, total: 0, amounts: [], categories: new Set() };
            existing.count++;
            existing.total += t.amount;
            existing.amounts.push(t.amount);
            existing.categories.add(t.category);
            merchantMap.set(key, existing);
        });

      const items: { merchant: string; avgCost: number; isSubscription: boolean }[] = [];
      merchantMap.forEach((data, key) => {
          const avg = data.total / data.count;
          const isConsistent = data.amounts.every(a => Math.abs(a - avg) / (avg || 1) < 0.25);
          if (data.categories.has(Category.SUBSCRIPTION) || (data.count > 1 && isConsistent)) {
              items.push({ merchant: key, avgCost: avg, isSubscription: data.categories.has(Category.SUBSCRIPTION) });
          }
      });
      return items.sort((a,b) => b.avgCost - a.avgCost).slice(0, 4);
  }, [transactions]);

  const spendingData = useMemo(() => {
    const dataPoints: { date: string, actual: number | null, predicted: number | null }[] = [];
    const expenseMap = new Map<string, number>();

    transactions.filter(t => t.type === TransactionType.EXPENSE).forEach(t => {
        const d = new Date(t.date);
        d.setHours(0, 0, 0, 0);
        const key = d.toDateString();
        expenseMap.set(key, (expenseMap.get(key) || 0) + t.amount);
    });

    for (let i = 0; i <= 30; i++) {
        const d = new Date(today);
        d.setDate(today.getDate() - (30 - i));
        d.setHours(0, 0, 0, 0);
        dataPoints.push({
            date: d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }),
            actual: expenseMap.get(d.toDateString()) || 0,
            predicted: null
        });
    }

    const last = dataPoints[dataPoints.length - 1];
    last.predicted = last.actual;

    for (let i = 1; i <= 7; i++) {
        const d = new Date(today);
        d.setDate(today.getDate() + i);
        dataPoints.push({
            date: d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }),
            actual: null,
            predicted: stats.burnRate * (1 + (Math.sin(i) * 0.1))
        });
    }
    return dataPoints;
  }, [transactions, stats.burnRate, today]);

  const handleNegotiateClick = async (merchant: string, amount: number) => {
      const limit = userPlan === 'ultra' ? Infinity : userPlan === 'pro' ? 5 : 3;
      if (negotiationUsage >= limit) {
          onNavigate('plans');
          return; 
      }
      setIsNegotiating(true);
      setScriptMerchant(merchant);
      setShowNegotiationModal(true);
      const generated = await generateNegotiationScript(merchant, amount);
      setScript(generated);
      setIsNegotiating(false);
      onIncrementNegotiation();
  };

  const handleCopyScript = () => {
      if (script) {
          navigator.clipboard.writeText(script);
          setCopySuccess(true);
          setTimeout(() => setCopySuccess(false), 2000);
      }
  };

  if (!hasData) {
     return (
        <div className="flex flex-col items-center justify-center w-full min-h-full py-12 animate-fade-in text-center relative overflow-hidden">
            <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[600px] h-[600px] bg-indigo-500/10 rounded-full blur-[120px] pointer-events-none animate-pulse-slow"></div>
            <div className="max-w-4xl mx-auto mb-12 relative z-10">
                <h1 className="text-4xl md:text-5xl font-black text-white tracking-tighter mb-4 px-4 uppercase">Initialize Terminal</h1>
                <p className="text-lg text-slate-400 font-medium tracking-wide">"{randomQuote.text}" — {randomQuote.author}</p>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6 w-full max-w-5xl relative z-10 px-4">
                 <button onClick={onAddAccount} className="group bg-slate-900 border border-white/5 p-10 rounded-[3rem] text-left hover:border-indigo-500/30 transition-all hover:-translate-y-1 shadow-2xl">
                    <div className="w-14 h-14 rounded-2xl bg-indigo-500/10 flex items-center justify-center mb-8 group-hover:scale-110 transition-transform text-indigo-400"><Landmark className="w-7 h-7" /></div>
                    <h3 className="text-xl font-bold text-white mb-3">Bridge Capital</h3>
                    <p className="text-slate-500 text-sm leading-relaxed">Securely connect your bank nodes or add manual ledgers.</p>
                 </button>
                 <button onClick={onAddTransaction} className="group bg-slate-900 border border-white/5 p-10 rounded-[3rem] text-left hover:border-emerald-500/30 transition-all hover:-translate-y-1 shadow-2xl">
                    <div className="w-14 h-14 rounded-2xl bg-emerald-500/10 flex items-center justify-center mb-8 group-hover:scale-110 transition-transform text-emerald-400"><PlusCircle className="w-7 h-7" /></div>
                    <h3 className="text-xl font-bold text-white mb-3">Sync Ledger</h3>
                    <p className="text-slate-500 text-sm leading-relaxed">Digitize receipts to calibrate the predictive engine.</p>
                 </button>
                 <button onClick={onAddGoal} className="group bg-slate-900 border border-white/5 p-10 rounded-[3rem] text-left hover:border-rose-500/30 transition-all hover:-translate-y-1 shadow-2xl">
                    <div className="w-14 h-14 rounded-2xl bg-rose-500/10 flex items-center justify-center mb-8 group-hover:scale-110 transition-transform text-rose-400"><Target className="w-7 h-7" /></div>
                    <h3 className="text-xl font-bold text-white mb-3">Set Trajectory</h3>
                    <p className="text-slate-500 text-sm leading-relaxed">Establish savings targets for the AI to optimize.</p>
                 </button>
            </div>
        </div>
     );
  }

  return (
    <div className="space-y-6 animate-slide-up pb-10">

      {/* Top Header Section */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 px-2">
          <div>
              <h2 className="text-3xl font-black text-white tracking-tighter uppercase">System Overview</h2>
              <p className="text-slate-500 text-sm font-medium tracking-wide">Real-time financial telemetry for {today.toLocaleDateString('en-US', { month: 'long', year: 'numeric' })}</p>
          </div>
          <div className="flex items-center gap-3">
               <div className="px-4 py-2 bg-slate-900/80 border border-white/5 rounded-xl flex items-center gap-2">
                   <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></div>
                   <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Logic: Operational</span>
               </div>
          </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard 
            title="Net Worth" 
            value={formatCurrency(netWorth)} 
            icon={<Wallet className="w-5 h-5 text-indigo-400" />} 
            change={stats.netWorthChange.toFixed(1) + '%'} 
            positive={stats.netWorthChange >= 0}
            subText="MTD Delta"
        />
        <StatCard 
            title="MTD Spending" 
            value={formatCurrency(stats.mtdSpend)} 
            icon={<CreditCard className="w-5 h-5 text-rose-400" />} 
            change={Math.abs(stats.spendChange).toFixed(1) + '%'} 
            positive={stats.spendChange <= 0} 
            subText="vs. Prev MTD"
        />
        <StatCard 
            title="Avg. Daily Burn" 
            value={formatCurrency(stats.burnRate)} 
            icon={<Flame className="w-5 h-5 text-amber-400" />} 
            change={Math.abs(stats.burnChange).toFixed(1) + '%'} 
            positive={stats.burnChange <= 0}
            subText="vs. Prev Month Avg"
        />
        <StatCard 
            title="Forecasted Spend" 
            value={formatCurrency(stats.predictedSpend)} 
            icon={<TrendingUp className="w-5 h-5 text-emerald-400" />} 
            change={Math.abs(stats.predictChange).toFixed(1) + '%'} 
            positive={stats.predictChange <= 0}
            subText="vs. Prev Total"
        />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Main Chart Section */}
        <div className="lg:col-span-2 bg-slate-900 border border-white/5 rounded-[2.5rem] p-8 shadow-2xl">
            <div className="flex justify-between items-center mb-10">
                <h3 className="text-lg font-bold text-white uppercase tracking-tighter flex items-center gap-3"><Activity className="w-6 h-6 text-indigo-400" />Expenditure Vector</h3>
                <div className="flex gap-4">
                    <div className="flex items-center gap-2"><div className="w-3 h-3 rounded-full bg-indigo-500"></div><span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Actual</span></div>
                    <div className="flex items-center gap-2"><div className="w-3 h-3 rounded-full bg-pink-500 opacity-50"></div><span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Predicted</span></div>
                </div>
            </div>
            <div className="h-80 w-full">
                <ResponsiveContainer width="100%" height="100%">
                    <AreaChart data={spendingData}>
                        <defs>
                            <linearGradient id="colorActual" x1="0" y1="0" x2="0" y2="1">
                                <stop offset="5%" stopColor="#6366f1" stopOpacity={0.2}/>
                                <stop offset="95%" stopColor="#6366f1" stopOpacity={0}/>
                            </linearGradient>
                            <linearGradient id="colorPredicted" x1="0" y1="0" x2="0" y2="1">
                                <stop offset="5%" stopColor="#ec4899" stopOpacity={0.1}/>
                                <stop offset="95%" stopColor="#ec4899" stopOpacity={0}/>
                            </linearGradient>
                        </defs>
                        <CartesianGrid strokeDasharray="3 3" stroke="#1e293b" vertical={false} />
                        <XAxis dataKey="date" stroke="#475569" fontSize={10} tickLine={false} axisLine={false} tick={{ fontWeight: 'bold' }} />
                        <YAxis stroke="#475569" fontSize={10} tickLine={false} axisLine={false} hide />
                        <Tooltip 
                            contentStyle={{ backgroundColor: '#0f172a', border: '1px solid rgba(255,255,255,0.05)', borderRadius: '12px', boxShadow: '0 10px 15px rgba(0,0,0,0.3)' }}
                            itemStyle={{ color: '#fff', fontSize: '11px', fontWeight: 'bold' }}
                        />
                        <Area type="monotone" dataKey="actual" stroke="#6366f1" strokeWidth={3} fillOpacity={1} fill="url(#colorActual)" animationDuration={1000} />
                        <Area type="monotone" dataKey="predicted" stroke="#ec4899" strokeWidth={2} strokeDasharray="5 5" fillOpacity={1} fill="url(#colorPredicted)" animationDuration={1200} />
                    </AreaChart>
                </ResponsiveContainer>
            </div>
        </div>

        {/* Subscription Feed */}
        <div className="bg-slate-900 border border-white/5 rounded-[2.5rem] p-8 shadow-2xl flex flex-col">
            <div className="flex justify-between items-center mb-8">
                <h3 className="text-lg font-bold text-white uppercase tracking-tighter flex items-center gap-3"><Repeat className="w-6 h-6 text-emerald-400" />Rate Shield</h3>
                <div className="w-8 h-8 rounded-full bg-emerald-500/10 flex items-center justify-center"><Zap className="w-4 h-4 text-emerald-500" /></div>
            </div>
            <div className="space-y-4 flex-1 overflow-y-auto custom-scrollbar pr-2">
                {recurringData.length > 0 ? recurringData.map((item, idx) => (
                    <div key={idx} className="p-5 bg-slate-950/40 rounded-3xl border border-white/5 hover:border-indigo-500/20 transition-all group">
                        <div className="flex justify-between items-start mb-4">
                            <div className="flex items-center gap-3">
                                <div className="w-10 h-10 rounded-xl bg-slate-800 flex items-center justify-center border border-white/5 group-hover:scale-110 transition-transform"><Radio className="w-5 h-5 text-emerald-400" /></div>
                                <div>
                                    <h4 className="text-xs font-black text-white uppercase truncate max-w-[100px]">{item.merchant}</h4>
                                    <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">{item.isSubscription ? 'Fixed' : 'Recurring'}</p>
                                </div>
                            </div>
                            <div className="text-right">
                                <div className="text-sm font-black text-white">{formatCurrency(item.avgCost)}</div>
                                <p className="text-[9px] text-slate-500 font-bold uppercase">Monthly</p>
                            </div>
                        </div>
                        <button 
                            onClick={() => handleNegotiateClick(item.merchant, item.avgCost)}
                            className="w-full py-2 bg-indigo-600/10 hover:bg-indigo-600 text-indigo-400 hover:text-white rounded-xl text-[9px] font-black uppercase tracking-widest transition-all flex items-center justify-center gap-2"
                        >
                            Negotiate Rate <Handshake className="w-3 h-3" />
                        </button>
                    </div>
                )) : (
                    <div className="flex flex-col items-center justify-center h-full text-center opacity-30 grayscale py-12">
                        <LayoutGrid className="w-12 h-12 mb-4" />
                        <p className="text-xs font-black uppercase tracking-widest">Scanning for patterns...</p>
                    </div>
                )}
            </div>
        </div>
      </div>

      {/* Intelligence Feed replaces Roadmap for professionalism */}
      <div className="bg-indigo-600 rounded-[2.5rem] p-8 shadow-2xl relative overflow-hidden group">
          <div className="absolute top-0 right-0 w-96 h-96 bg-white/10 blur-[120px] -mr-40 -mt-40"></div>
          <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 relative z-10">
              <div className="flex items-center gap-6">
                  <div className="w-16 h-16 rounded-3xl bg-white/10 backdrop-blur-xl flex items-center justify-center shadow-inner">
                      <Sparkles className="w-8 h-8 text-white" />
                  </div>
                  <div>
                      <h3 className="text-2xl font-black text-white uppercase tracking-tighter">System Intelligence</h3>
                      <p className="text-indigo-100/80 font-medium">Your portfolio is currently optimized at {((1 - stats.mtdSpend/netWorth) * 100 || 0).toFixed(0)}% efficiency.</p>
                  </div>
              </div>
              <div className="flex gap-4">
                  <button onClick={() => onNavigate('insights')} className="px-8 py-3 bg-white text-indigo-600 rounded-2xl text-[10px] font-black uppercase tracking-[0.2em] shadow-xl hover:scale-105 transition-all active:scale-95">Open Coach</button>
                  <button onClick={() => onNavigate('sandbox')} className="px-8 py-3 bg-indigo-500 text-white border border-indigo-400 rounded-2xl text-[10px] font-black uppercase tracking-[0.2em] shadow-xl hover:bg-indigo-400 transition-all active:scale-95">Run Sim</button>
              </div>
          </div>
      </div>

      {showNegotiationModal && (
          <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-black/95 backdrop-blur-2xl animate-fade-in">
              <div className="bg-[#020617] border border-white/10 rounded-[3rem] w-full max-w-xl shadow-2xl overflow-hidden animate-slide-up relative">
                  <button onClick={() => setShowNegotiationModal(false)} className="absolute top-6 right-6 p-2 text-slate-500 hover:text-white z-10"><X className="w-6 h-6" /></button>
                  <div className="p-10 border-b border-white/5 bg-slate-900/40">
                      <div className="w-16 h-16 bg-indigo-600 rounded-2xl flex items-center justify-center mb-6 shadow-xl"><Zap className="w-8 h-8 text-white fill-white" /></div>
                      <h3 className="text-3xl font-black text-white uppercase tracking-tighter">Arbitrage Uplink</h3>
                      <p className="text-slate-400 text-sm mt-1 font-medium">Auto-generated script for {scriptMerchant}</p>
                  </div>
                  <div className="p-10">
                      {isNegotiating ? (
                          <div className="py-12 flex flex-col items-center justify-center gap-6">
                              <Loader2 className="w-12 h-12 text-indigo-500 animate-spin" />
                              <p className="text-indigo-400 font-bold uppercase tracking-[0.3em] text-xs animate-pulse">Running analysis...</p>
                          </div>
                      ) : (
                          <div className="animate-fade-in">
                               <div className="bg-slate-900 rounded-3xl p-8 border border-white/5 text-slate-200 font-medium leading-relaxed italic text-sm mb-8 max-h-60 overflow-y-auto custom-scrollbar">
                                    "{script}"
                               </div>
                               <button 
                                    onClick={handleCopyScript}
                                    className="w-full py-5 bg-white text-indigo-950 font-black uppercase tracking-[0.2em] text-xs rounded-2xl transition-all shadow-xl flex items-center justify-center gap-3 active:scale-95"
                               >
                                    {copySuccess ? <Check className="w-5 h-5" /> : <Copy className="w-5 h-5" />}
                                    {copySuccess ? 'Buffer Sync Complete' : 'Copy to Clipboard'}
                               </button>
                          </div>
                      )}
                  </div>
              </div>
          </div>
      )}
    </div>
  );
};

const StatCard: React.FC<{ title: string, value: string | React.ReactNode, icon: React.ReactNode, change?: string, positive?: boolean, subText: string }> = ({ title, value, icon, change, positive, subText }) => (
    <div className="bg-slate-900 p-8 rounded-[2.5rem] border border-white/5 hover:border-indigo-500/20 transition-all shadow-xl group">
        <div className="flex justify-between items-start mb-6">
            <div className="p-3 bg-slate-800 rounded-2xl border border-white/5 text-slate-400 group-hover:text-indigo-400 transition-colors">{icon}</div>
            <div className="text-right">
                <div className={`flex items-center gap-1 text-[11px] font-black uppercase tracking-widest ${positive ? 'text-emerald-500' : 'text-rose-500'}`}>
                    {positive ? <ArrowUpRight className="w-3 h-3" /> : <ArrowDownRight className="w-3 h-3" />}
                    {change}
                </div>
                <p className="text-[9px] text-slate-500 font-bold uppercase tracking-widest mt-1">{subText}</p>
            </div>
        </div>
        <div className="space-y-1">
            <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em]">{title}</h4>
            <div className="text-2xl font-black text-white tracking-tighter">{value}</div>
        </div>
    </div>
);

export default Dashboard;

import React, { useMemo, useState } from 'react';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import { Account, Transaction, TransactionType, Category, UserPlan, Goal } from '../types';
import { Activity, Flame, TrendingUp, Wallet, PlusCircle, CreditCard, Target, Quote, Landmark, Zap, Radio, Repeat, Check, Handshake, Copy, AlertCircle, X, Loader2, Sparkles, ArrowUpRight, ArrowDownRight, LayoutGrid } from 'lucide-react';
import { generateNegotiationScript } from '../services/geminiService';

interface DashboardProps {
  accounts: Account[];
  transactions: Transaction[];
  goals: Goal[];
  onNavigate: (tab: string) => void;
  onAddAccount?: () => void;
  onAddTransaction?: () => void;
  onAddGoal?: () => void;
  formatCurrency: (amount: number) => string | React.ReactNode;
  userPlan?: UserPlan;
  onAskCoach?: (message: string) => void;
  negotiationUsage: number;
  onIncrementNegotiation: () => void;
}

const QUOTES = [
  { text: "Do not save what is left after spending, but spend what is left after saving.", author: "Warren Buffett" },
  { text: "A budget is telling your money where to go instead of wondering where it went.", author: "Dave Ramsey" },
  { text: "It's not your salary that makes you rich, it's your spending habits.", author: "Charles A. Jaffe" },
];

const Dashboard: React.FC<DashboardProps> = ({ accounts, transactions, goals, onNavigate, onAddAccount, onAddTransaction, onAddGoal, formatCurrency, userPlan, onAskCoach, negotiationUsage, onIncrementNegotiation }) => {
  const hasData = accounts.length > 0 || transactions.length > 0;
  const randomQuote = useMemo(() => QUOTES[Math.floor(Math.random() * QUOTES.length)], []);
  const netWorth = useMemo(() => accounts.reduce((acc, curr) => acc + curr.balance, 0), [accounts]);

  const [isNegotiating, setIsNegotiating] = useState(false);
  const [script, setScript] = useState<string | null>(null);
  const [scriptMerchant, setScriptMerchant] = useState('');
  const [showNegotiationModal, setShowNegotiationModal] = useState(false);
  const [copySuccess, setCopySuccess] = useState(false);

  // Time Precision Constants
  const today = new Date();
  const currentMonth = today.getMonth();
  const currentYear = today.getFullYear();
  const currentDay = today.getDate();
  const daysInMonth = new Date(currentYear, currentMonth + 1, 0).getDate();

  const prevMonthDate = new Date(currentYear, currentMonth - 1, 1);
  const prevMonth = prevMonthDate.getMonth();
  const prevMonthYear = prevMonthDate.getFullYear();
  const daysInPrevMonth = new Date(prevMonthYear, prevMonth + 1, 0).getDate();

  // Advanced Statistics Logic
  const stats = useMemo(() => {
    // 1. Monthly Spend (MTD vs Prev Month LFL)
    const currentMTDTransactions = transactions.filter(t => {
      const d = new Date(t.date);
      return t.type === TransactionType.EXPENSE && d.getMonth() === currentMonth && d.getFullYear() === currentYear;
    });
    const currentMTDSpend = currentMTDTransactions.reduce((acc, t) => acc + t.amount, 0);

    const prevMTDTransactions = transactions.filter(t => {
      const d = new Date(t.date);
      return t.type === TransactionType.EXPENSE && d.getMonth() === prevMonth && d.getFullYear() === prevMonthYear && d.getDate() <= currentDay;
    });
    const prevMTDSpend = prevMTDTransactions.reduce((acc, t) => acc + t.amount, 0);
    const spendChange = prevMTDSpend > 0 ? ((currentMTDSpend - prevMTDSpend) / prevMTDSpend) * 100 : 0;

    // 2. Net Worth Change (MTD Flow Delta)
    const mtdDelta = transactions
      .filter(t => {
        const d = new Date(t.date);
        return d.getMonth() === currentMonth && d.getFullYear() === currentYear;
      })
      .reduce((acc, t) => acc + (t.type === TransactionType.INCOME ? t.amount : -t.amount), 0);
    const startingNetWorth = netWorth - mtdDelta;
    const netWorthChange = startingNetWorth !== 0 ? (mtdDelta / Math.abs(startingNetWorth)) * 100 : 0;

    // 3. Burn Rate (Avg daily spend comparison)
    const dailyAvgCurrent = currentMTDSpend / Math.max(currentDay, 1);
    const prevMonthFullTransactions = transactions.filter(t => {
      const d = new Date(t.date);
      return t.type === TransactionType.EXPENSE && d.getMonth() === prevMonth && d.getFullYear() === prevMonthYear;
    });
    const prevFullSpend = prevMonthFullTransactions.reduce((acc, t) => acc + t.amount, 0);
    const dailyAvgPrev = prevFullSpend / Math.max(daysInPrevMonth, 1);
    const burnChange = dailyAvgPrev > 0 ? ((dailyAvgCurrent - dailyAvgPrev) / dailyAvgPrev) * 100 : 0;

    // 4. Forecasted vs Prev Full Month
    const predictedSpend = dailyAvgCurrent * daysInMonth;
    const predictChange = prevFullSpend > 0 ? ((predictedSpend - prevFullSpend) / prevFullSpend) * 100 : 0;

    return {
      mtdSpend: currentMTDSpend,
      spendChange,
      netWorthChange,
      burnRate: dailyAvgCurrent,
      burnChange,
      predictedSpend,
      predictChange
    };
  }, [transactions, currentMonth, currentYear, prevMonth, prevMonthYear, currentDay, netWorth, daysInMonth, daysInPrevMonth]);

  const recurringData = useMemo(() => {
      const merchantMap = new Map<string, { count: number; total: number; amounts: number[]; categories: Set<Category>; }>();
      transactions.filter(t => t.type === TransactionType.EXPENSE).forEach(t => {
            const key = t.merchant.toLowerCase().trim();
            const existing = merchantMap.get(key) || { count: 0, total: 0, amounts: [], categories: new Set() };
            existing.count++;
            existing.total += t.amount;
            existing.amounts.push(t.amount);
            existing.categories.add(t.category);
            merchantMap.set(key, existing);
        });

      const items: { merchant: string; avgCost: number; isSubscription: boolean }[] = [];
      merchantMap.forEach((data, key) => {
          const avg = data.total / data.count;
          const isConsistent = data.amounts.every(a => Math.abs(a - avg) / (avg || 1) < 0.25);
          if (data.categories.has(Category.SUBSCRIPTION) || (data.count > 1 && isConsistent)) {
              items.push({ merchant: key, avgCost: avg, isSubscription: data.categories.has(Category.SUBSCRIPTION) });
          }
      });
      return items.sort((a,b) => b.avgCost - a.avgCost).slice(0, 4);
  }, [transactions]);

  const spendingData = useMemo(() => {
    const dataPoints: { date: string, actual: number | null, predicted: number | null }[] = [];
    const expenseMap = new Map<string, number>();

    transactions.filter(t => t.type === TransactionType.EXPENSE).forEach(t => {
        const d = new Date(t.date);
        d.setHours(0, 0, 0, 0);
        const key = d.toDateString();
        expenseMap.set(key, (expenseMap.get(key) || 0) + t.amount);
    });

    for (let i = 0; i <= 30; i++) {
        const d = new Date(today);
        d.setDate(today.getDate() - (30 - i));
        d.setHours(0, 0, 0, 0);
        dataPoints.push({
            date: d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }),
            actual: expenseMap.get(d.toDateString()) || 0,
            predicted: null
        });
    }

    const last = dataPoints[dataPoints.length - 1];
    last.predicted = last.actual;

    for (let i = 1; i <= 7; i++) {
        const d = new Date(today);
        d.setDate(today.getDate() + i);
        dataPoints.push({
            date: d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }),
            actual: null,
            predicted: stats.burnRate * (1 + (Math.sin(i) * 0.1))
        });
    }
    return dataPoints;
  }, [transactions, stats.burnRate, today]);

  const handleNegotiateClick = async (merchant: string, amount: number) => {
      const limit = userPlan === 'ultra' ? Infinity : userPlan === 'pro' ? 5 : 3;
      if (negotiationUsage >= limit) {
          onNavigate('plans');
          return; 
      }
      setIsNegotiating(true);
      setScriptMerchant(merchant);
      setShowNegotiationModal(true);
      const generated = await generateNegotiationScript(merchant, amount);
      setScript(generated);
      setIsNegotiating(false);
      onIncrementNegotiation();
  };

  const handleCopyScript = () => {
      if (script) {
          navigator.clipboard.writeText(script);
          setCopySuccess(true);
          setTimeout(() => setCopySuccess(false), 2000);
      }
  };

  if (!hasData) {
     return (
        <div className="flex flex-col items-center justify-center w-full min-h-full py-12 animate-fade-in text-center relative overflow-hidden">
            <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[600px] h-[600px] bg-indigo-500/10 rounded-full blur-[120px] pointer-events-none animate-pulse-slow"></div>
            <div className="max-w-4xl mx-auto mb-12 relative z-10">
                <div className="flex justify-center mb-8">
                    <div className="w-14 h-14 rounded-2xl bg-slate-800 flex items-center justify-center shadow-2xl border border-white/10 rotate-3">
                        <Quote className="w-7 h-7 text-indigo-400 fill-current" />
                    </div>
                </div>
                <h1 className="text-3xl md:text-4xl font-bold text-white tracking-tight mb-4 px-4 uppercase">Initialize Terminal</h1>
                <p className="text-lg text-slate-400 font-medium italic tracking-wide">"{randomQuote.text}" — {randomQuote.author}</p>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6 w-full max-w-5xl relative z-10 px-4">
                 <button onClick={onAddAccount} className="group bg-slate-900 border border-white/5 p-10 rounded-[2.5rem] text-left hover:border-indigo-500/30 transition-all hover:-translate-y-1 shadow-2xl">
                    <div className="w-14 h-14 rounded-2xl bg-indigo-500/10 flex items-center justify-center mb-8 group-hover:scale-110 transition-transform text-indigo-400"><Landmark className="w-7 h-7" /></div>
                    <h3 className="text-xl font-bold text-white mb-3">Bridge Assets</h3>
                    <p className="text-slate-500 text-sm leading-relaxed">Securely link your bank nodes or add manual ledgers to start tracking.</p>
                 </button>
                 <button onClick={onAddTransaction} className="group bg-slate-900 border border-white/5 p-10 rounded-[2.5rem] text-left hover:border-emerald-500/30 transition-all hover:-translate-y-1 shadow-2xl">
                    <div className="w-14 h-14 rounded-2xl bg-emerald-500/10 flex items-center justify-center mb-8 group-hover:scale-110 transition-transform text-emerald-400"><PlusCircle className="w-7 h-7" /></div>
                    <h3 className="text-xl font-bold text-white mb-3">Sync Activity</h3>
                    <p className="text-slate-500 text-sm leading-relaxed">Archive your daily spending to calibrate the AI predictive engine.</p>
                 </button>
                 <button onClick={onAddGoal} className="group bg-slate-900 border border-white/5 p-10 rounded-[2.5rem] text-left hover:border-rose-500/30 transition-all hover:-translate-y-1 shadow-2xl">
                    <div className="w-14 h-14 rounded-2xl bg-rose-500/10 flex items-center justify-center mb-8 group-hover:scale-110 transition-transform text-rose-400"><Target className="w-7 h-7" /></div>
                    <h3 className="text-xl font-bold text-white mb-3">Set Objectives</h3>
                    <p className="text-slate-500 text-sm leading-relaxed">Establish savings targets and let Nova optimize your trajectory.</p>
                 </button>
            </div>
        </div>
     );
  }

  return (
    <div className="space-y-6 animate-slide-up pb-10">

      {/* Precision Header */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 px-2">
          <div>
              <h2 className="text-3xl font-black text-white tracking-tighter uppercase">Terminal Console</h2>
              <p className="text-slate-500 text-xs font-bold tracking-[0.2em] uppercase">Intelligence Node: {today.toLocaleDateString('en-US', { month: 'long', year: 'numeric' })}</p>
          </div>
          <div className="flex items-center gap-4">
               <div className="px-4 py-2 bg-slate-900 border border-white/5 rounded-xl flex items-center gap-3">
                   <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></div>
                   <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Logic Engine: Operational</span>
               </div>
          </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard 
            title="Net Worth" 
            value={formatCurrency(netWorth)} 
            icon={<Wallet className="w-5 h-5 text-indigo-400" />} 
            change={stats.netWorthChange.toFixed(1) + '%'} 
            positive={stats.netWorthChange >= 0}
            subText="MTD Delta"
        />
        <StatCard 
            title="Monthly Spend" 
            value={formatCurrency(stats.mtdSpend)} 
            icon={<CreditCard className="w-5 h-5 text-rose-400" />} 
            change={Math.abs(stats.spendChange).toFixed(1) + '%'} 
            positive={stats.spendChange <= 0} 
            subText="vs Prev MTD (LFL)"
        />
        <StatCard 
            title="Daily Burn" 
            value={formatCurrency(stats.burnRate)} 
            icon={<Flame className="w-5 h-5 text-amber-400" />} 
            change={Math.abs(stats.burnChange).toFixed(1) + '%'} 
            positive={stats.burnChange <= 0}
            subText="vs Prev Avg"
        />
        <StatCard 
            title="Month Forecast" 
            value={formatCurrency(stats.predictedSpend)} 
            icon={<TrendingUp className="w-5 h-5 text-emerald-400" />} 
            change={Math.abs(stats.predictChange).toFixed(1) + '%'} 
            positive={stats.predictChange <= 0}
            subText="vs Prev Total"
        />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Expenditure Analysis */}
        <div className="lg:col-span-2 bg-slate-900 border border-white/5 rounded-[2.5rem] p-8 shadow-2xl relative overflow-hidden">
            <div className="flex justify-between items-center mb-10">
                <h3 className="text-lg font-black text-white uppercase tracking-tighter flex items-center gap-3"><Activity className="w-6 h-6 text-indigo-400" />Expenditure Vector</h3>
                <div className="flex gap-4">
                    <div className="flex items-center gap-2">
                        <div className="w-2.5 h-2.5 rounded-full bg-indigo-500 shadow-[0_0_8px_#6366f1]"></div>
                        <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Actual</span>
                    </div>
                    <div className="flex items-center gap-2">
                        <div className="w-2.5 h-2.5 rounded-full bg-pink-500 opacity-50"></div>
                        <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Predicted</span>
                    </div>
                </div>
            </div>
            <div className="h-80 w-full">
                <ResponsiveContainer width="100%" height="100%">
                    <AreaChart data={spendingData}>
                        <defs>
                            <linearGradient id="colorActual" x1="0" y1="0" x2="0" y2="1">
                                <stop offset="5%" stopColor="#6366f1" stopOpacity={0.2}/>
                                <stop offset="95%" stopColor="#6366f1" stopOpacity={0}/>
                            </linearGradient>
                            <linearGradient id="colorPredicted" x1="0" y1="0" x2="0" y2="1">
                                <stop offset="5%" stopColor="#ec4899" stopOpacity={0.1}/>
