import React, { useMemo, useState } from 'react';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import { Account, Transaction, TransactionType, Category, UserPlan, Goal } from '../types';
import { Activity, Flame, TrendingUp, Wallet, PlusCircle, CreditCard, Target, Quote, Landmark, Zap, Radio, Repeat, Check, Handshake, Copy, X, Loader2, Sparkles, ArrowUpRight, ArrowDownRight, LayoutGrid } from 'lucide-react';
import { generateNegotiationScript } from '../services/geminiService';

interface DashboardProps {
  accounts: Account[];
  transactions: Transaction[];
  goals: Goal[];
  onNavigate: (tab: string) => void;
  onAddAccount?: () => void;
  onAddTransaction?: () => void;
  onAddGoal?: () => void;
  formatCurrency: (amount: number) => string | React.ReactNode;
  userPlan?: UserPlan;
  onAskCoach?: (message: string) => void;
  negotiationUsage: number;
  onIncrementNegotiation: () => void;
}

const QUOTES = [
  { text: "Do not save what is left after spending, but spend what is left after saving.", author: "Warren Buffett" },
  { text: "A budget is telling your money where to go instead of wondering where it went.", author: "Dave Ramsey" },
  { text: "It's not your salary that makes you rich, it's your spending habits.", author: "Charles A. Jaffe" },
];

const Dashboard: React.FC<DashboardProps> = ({ accounts, transactions, goals, onNavigate, onAddAccount, onAddTransaction, onAddGoal, formatCurrency, userPlan, onAskCoach, negotiationUsage, onIncrementNegotiation }) => {
  const hasData = accounts.length > 0 || transactions.length > 0;
  const randomQuote = useMemo(() => QUOTES[Math.floor(Math.random() * QUOTES.length)], []);
  const netWorth = useMemo(() => accounts.reduce((acc, curr) => acc + curr.balance, 0), [accounts]);

  const [isNegotiating, setIsNegotiating] = useState(false);
  const [script, setScript] = useState<string | null>(null);
  const [scriptMerchant, setScriptMerchant] = useState('');
  const [showNegotiationModal, setShowNegotiationModal] = useState(false);
  const [copySuccess, setCopySuccess] = useState(false);

  // Time & Comparison Logic
  const today = new Date();
  const currentMonth = today.getMonth();
  const currentYear = today.getFullYear();
  const currentDay = today.getDate();
  const daysInMonth = new Date(currentYear, currentMonth + 1, 0).getDate();

  const prevMonthDate = new Date(currentYear, currentMonth - 1, 1);
  const prevMonth = prevMonthDate.getMonth();
  const prevMonthYear = prevMonthDate.getFullYear();
  const daysInPrevMonth = new Date(prevMonthYear, prevMonth + 1, 0).getDate();

  // Advanced Statistics Logic
  const stats = useMemo(() => {
    // 1. Monthly Spend (MTD vs Prev Month Like-for-Like)
    const currentMTDExpenses = transactions.filter(t => {
      const d = new Date(t.date);
      return t.type === TransactionType.EXPENSE && d.getMonth() === currentMonth && d.getFullYear() === currentYear;
    });
    const currentMTDTotal = currentMTDExpenses.reduce((acc, t) => acc + t.amount, 0);

    const prevMTDExpenses = transactions.filter(t => {
      const d = new Date(t.date);
      return t.type === TransactionType.EXPENSE && d.getMonth() === prevMonth && d.getFullYear() === prevMonthYear && d.getDate() <= currentDay;
    });
    const prevMTDTotal = prevMTDExpenses.reduce((acc, t) => acc + t.amount, 0);
    const spendChange = prevMTDTotal > 0 ? ((currentMTDTotal - prevMTDTotal) / prevMTDTotal) * 100 : 0;

    // 2. Net Worth Change (MTD Flow)
    const mtdNetFlow = transactions
      .filter(t => {
        const d = new Date(t.date);
        return d.getMonth() === currentMonth && d.getFullYear() === currentYear;
      })
      .reduce((acc, t) => acc + (t.type === TransactionType.INCOME ? t.amount : -t.amount), 0);
    const monthStartNW = netWorth - mtdNetFlow;
    const nwChange = monthStartNW !== 0 ? (mtdNetFlow / Math.abs(monthStartNW)) * 100 : 0;

    // 3. Burn Rate (Avg daily current vs avg daily prev full month)
    const currentDailyAvg = currentMTDTotal / Math.max(currentDay, 1);
    const prevFullMonthExpenses = transactions.filter(t => {
      const d = new Date(t.date);
      return t.type === TransactionType.EXPENSE && d.getMonth() === prevMonth && d.getFullYear() === prevMonthYear;
    });
    const prevFullMonthTotal = prevFullMonthExpenses.reduce((acc, t) => acc + t.amount, 0);
    const prevDailyAvg = prevFullMonthTotal / Math.max(daysInPrevMonth, 1);
    const burnChange = prevDailyAvg > 0 ? ((currentDailyAvg - prevDailyAvg) / prevDailyAvg) * 100 : 0;

    // 4. Forecast
    const forecastedTotal = currentDailyAvg * daysInMonth;
    const forecastChange = prevFullMonthTotal > 0 ? ((forecastedTotal - prevFullMonthTotal) / prevFullMonthTotal) * 100 : 0;

    return {
      currentMTDTotal,
      spendChange,
      nwChange,
      currentDailyAvg,
      burnChange,
      forecastedTotal,
      forecastChange
    };
  }, [transactions, currentMonth, currentYear, prevMonth, prevMonthYear, currentDay, netWorth, daysInMonth, daysInPrevMonth]);

  const recurringData = useMemo(() => {
      const merchantMap = new Map<string, { count: number; total: number; amounts: number[]; categories: Set<Category>; }>();
      transactions.filter(t => t.type === TransactionType.EXPENSE).forEach(t => {
            const key = t.merchant.toLowerCase().trim();
            const existing = merchantMap.get(key) || { count: 0, total: 0, amounts: [], categories: new Set() };
            existing.count++;
            existing.total += t.amount;
            existing.amounts.push(t.amount);
            existing.categories.add(t.category);
            merchantMap.set(key, existing);
        });

      const items: { merchant: string; avgCost: number; isSubscription: boolean }[] = [];
      merchantMap.forEach((data, key) => {
          const avg = data.total / data.count;
          const isConsistent = data.amounts.every(a => Math.abs(a - avg) / (avg || 1) < 0.25);
          if (data.categories.has(Category.SUBSCRIPTION) || (data.count > 1 && isConsistent)) {
              items.push({ merchant: key, avgCost: avg, isSubscription: data.categories.has(Category.SUBSCRIPTION) });
          }
      });
      return items.sort((a,b) => b.avgCost - a.avgCost).slice(0, 4);
  }, [transactions]);

  const spendingData = useMemo(() => {
    const dataPoints: { date: string, actual: number | null, predicted: number | null }[] = [];
    const expenseMap = new Map<string, number>();

    transactions.filter(t => t.type === TransactionType.EXPENSE).forEach(t => {
        const d = new Date(t.date);
        d.setHours(0, 0, 0, 0);
        const key = d.toDateString();
        expenseMap.set(key, (expenseMap.get(key) || 0) + t.amount);
    });

    for (let i = 0; i <= 30; i++) {
        const d = new Date(today);
        d.setDate(today.getDate() - (30 - i));
        d.setHours(0, 0, 0, 0);
        dataPoints.push({
            date: d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }),
            actual: expenseMap.get(d.toDateString()) || 0,
            predicted: null
        });
    }

    const last = dataPoints[dataPoints.length - 1];
    last.predicted = last.actual;

    for (let i = 1; i <= 7; i++) {
        const d = new Date(today);
        d.setDate(today.getDate() + i);
        dataPoints.push({
            date: d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }),
            actual: null,
            predicted: stats.currentDailyAvg * (1 + (Math.sin(i) * 0.1))
        });
    }
    return dataPoints;
  }, [transactions, stats.currentDailyAvg, today]);

  const handleNegotiateClick = async (merchant: string, amount: number) => {
      const limit = userPlan === 'ultra' ? Infinity : userPlan === 'pro' ? 5 : 3;
      if (negotiationUsage >= limit) {
          onNavigate('plans');
          return; 
      }
      setIsNegotiating(true);
      setScriptMerchant(merchant);
      setShowNegotiationModal(true);
      const generated = await generateNegotiationScript(merchant, amount);
      setScript(generated);
      setIsNegotiating(false);
      onIncrementNegotiation();
  };

  const handleCopyScript = () => {
      if (script) {
          navigator.clipboard.writeText(script);
          setCopySuccess(true);
          setTimeout(() => setCopySuccess(false), 2000);
      }
  };

  // WELCOME DASHBOARD (UNCHANGED DESIGN)
  if (!hasData) {
     return (
        <div className="flex flex-col items-center justify-center w-full min-h-full py-12 animate-fade-in text-center relative overflow-hidden">
            <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[600px] h-[600px] bg-indigo-500/10 rounded-full blur-[120px] pointer-events-none animate-pulse-slow"></div>
            <div className="max-w-4xl mx-auto mb-12 relative z-10">
                <div className="flex justify-center mb-8">
                    <div className="w-14 h-14 rounded-2xl bg-slate-800 flex items-center justify-center shadow-2xl border border-white/10 rotate-3">
                        <Quote className="w-7 h-7 text-indigo-400 fill-current" />
                    </div>
                </div>
                <h1 className="text-3xl md:text-4xl font-bold text-white tracking-tight mb-4 px-4 uppercase">Initialize Terminal</h1>
                <p className="text-lg text-slate-400 font-medium italic tracking-wide">"{randomQuote.text}" — {randomQuote.author}</p>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6 w-full max-w-5xl relative z-10 px-4">
                 <button onClick={onAddAccount} className="group bg-slate-900 border border-white/5 p-10 rounded-[2.5rem] text-left hover:border-indigo-500/30 transition-all hover:-translate-y-1 shadow-2xl">
                    <div className="w-14 h-14 rounded-2xl bg-indigo-500/10 flex items-center justify-center mb-8 group-hover:scale-110 transition-transform text-indigo-400"><Landmark className="w-7 h-7" /></div>
                    <h3 className="text-xl font-bold text-white mb-3">Bridge Assets</h3>
                    <p className="text-slate-500 text-sm leading-relaxed">Securely link your bank nodes or add manual ledgers to start tracking.</p>
                 </button>
                 <button onClick={onAddTransaction} className="group bg-slate-900 border border-white/5 p-10 rounded-[2.5rem] text-left hover:border-emerald-500/30 transition-all hover:-translate-y-1 shadow-2xl">
                    <div className="w-14 h-14 rounded-2xl bg-emerald-500/10 flex items-center justify-center mb-8 group-hover:scale-110 transition-transform text-emerald-400"><PlusCircle className="w-7 h-7" /></div>
                    <h3 className="text-xl font-bold text-white mb-3">Sync Activity</h3>
                    <p className="text-slate-500 text-sm leading-relaxed">Archive your daily spending to calibrate the AI predictive engine.</p>
                 </button>
                 <button onClick={onAddGoal} className="group bg-slate-900 border border-white/5 p-10 rounded-[2.5rem] text-left hover:border-rose-500/30 transition-all hover:-translate-y-1 shadow-2xl">
                    <div className="w-14 h-14 rounded-2xl bg-rose-500/10 flex items-center justify-center mb-8 group-hover:scale-110 transition-transform text-rose-400"><Target className="w-7 h-7" /></div>
                    <h3 className="text-xl font-bold text-white mb-3">Set Objectives</h3>
                    <p className="text-slate-500 text-sm leading-relaxed">Establish savings targets and let Nova optimize your trajectory.</p>
                 </button>
            </div>
        </div>
     );
  }

  // Dashboard with Data
  return (
    <div className="space-y-6 animate-slide-up pb-10">

      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 animate-fade-in">
        <div>
          <h2 className="text-3xl font-bold text-white tracking-tight">Overview</h2>
          <p className="text-slate-400 mt-1 font-medium">Financial performance for {today.toLocaleDateString('en-US', { month: 'long', year: 'numeric' })}</p>
        </div>
      </div>

      {/* System Insights (Uplink Banner) moved to top below header */}
      <div className="bg-indigo-600 rounded-[2rem] p-8 shadow-2xl relative overflow-hidden group cursor-pointer animate-slide-up" style={{ animationDelay: '0.1s' }} onClick={() => onNavigate('insights')}>
          <div className="absolute top-0 right-0 w-64 h-64 bg-white/10 blur-[80px] -mr-20 -mt-20 group-hover:scale-110 transition-transform duration-700"></div>
          <div className="flex flex-col md:flex-row justify-between items-center gap-6 relative z-10">
              <div className="flex items-center gap-6">
                  <div className="w-16 h-16 rounded-2xl bg-white/20 backdrop-blur-xl flex items-center justify-center shadow-inner group-hover:rotate-6 transition-transform">
                      <Sparkles className="w-8 h-8 text-white" />
                  </div>
                  <div>
                      <h3 className="text-xl font-bold text-white">System Insights</h3>
                      <p className="text-indigo-100/80 font-medium">Nova has detected {recurringData.length} potential saving opportunities in your ledger.</p>
                  </div>
              </div>
              <button className="px-6 py-3 bg-white text-indigo-600 rounded-xl font-bold text-sm shadow-xl transition-all hover:scale-105 active:scale-95">Open Intelligence</button>
          </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard 
            title="Net Worth" 
            value={formatCurrency(netWorth)} 
            icon={<Wallet className="w-5 h-5 text-indigo-400" />} 
            change={stats.nwChange.toFixed(1) + '%'} 
            positive={stats.nwChange >= 0}
            delay="0.2s"
        />
        <StatCard 
            title="Monthly Spend" 
            value={formatCurrency(stats.currentMTDTotal)} 
            icon={<CreditCard className="w-5 h-5 text-rose-400" />} 
            change={Math.abs(stats.spendChange).toFixed(1) + '%'} 
            positive={stats.spendChange <= 0} 
            delay="0.3s"
        />
        <StatCard 
            title="Burn Rate/Day" 
            value={formatCurrency(stats.currentDailyAvg)} 
            icon={<Flame className="w-5 h-5 text-amber-400" />} 
            change={Math.abs(stats.burnChange).toFixed(1) + '%'} 
            positive={stats.burnChange <= 0}
            delay="0.4s"
        />
        <StatCard 
            title="Predicted Spend" 
            value={formatCurrency(stats.forecastedTotal)} 
            icon={<TrendingUp className="w-5 h-5 text-emerald-400" />} 
            change={Math.abs(stats.forecastChange).toFixed(1) + '%'} 
            positive={stats.forecastChange <= 0}
            delay="0.5s"
        />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-2 glass-card p-6 md:p-8 rounded-[2rem] border border-white/5 shadow-xl relative overflow-hidden animate-slide-up" style={{ animationDelay: '0.6s' }}>
            <div className="flex justify-between items-center mb-8">
                <h3 className="text-lg font-bold text-white flex items-center gap-2"><Activity className="w-5 h-5 text-indigo-400" />Spending Patterns</h3>
                <div className="flex gap-4 text-[10px] font-bold uppercase tracking-wider">
                    <div className="flex items-center gap-1.5"><div className="w-2.5 h-2.5 rounded-full bg-indigo-500"></div><span className="text-slate-400">Actual</span></div>
                    <div className="flex items-center gap-1.5"><div className="w-2.5 h-2.5 rounded-full bg-indigo-500 opacity-30 border border-dashed border-indigo-400"></div><span className="text-slate-400">Predicted</span></div>
                </div>
            </div>
            <div className="h-72 w-full">
                <ResponsiveContainer width="100%" height="100%">
                    <AreaChart data={spendingData}>
                        <defs>
                            <linearGradient id="colorActual" x1="0" y1="0" x2="0" y2="1">
                                <stop offset="5%" stopColor="#6366f1" stopOpacity={0.2}/>
                                <stop offset="95%" stopColor="#6366f1" stopOpacity={0}/>
                            </linearGradient>
                        </defs>
                        <CartesianGrid strokeDasharray="3 3" stroke="#1e293b" vertical={false} />
                        <XAxis dataKey="date" stroke="#475569" fontSize={10} tickLine={false} axisLine={false} />
                        <YAxis stroke="#475569" fontSize={10} tickLine={false} axisLine={false} hide />
                        <Tooltip 
                            contentStyle={{ backgroundColor: '#0f172a', border: '1px solid rgba(255,255,255,0.05)', borderRadius: '12px' }}
                            itemStyle={{ color: '#fff', fontSize: '12px' }}
                        />
                        <Area type="monotone" dataKey="actual" stroke="#6366f1" strokeWidth={3} fillOpacity={1} fill="url(#colorActual)" animationDuration={1500} />
                        <Area type="monotone" dataKey="predicted" stroke="#6366f1" strokeWidth={2} strokeDasharray="5 5" fillOpacity={0} animationDuration={1800} />
                    </AreaChart>
                </ResponsiveContainer>
            </div>
        </div>

        <div className="glass-card p-6 md:p-8 rounded-[2rem] border border-white/5 shadow-xl flex flex-col animate-slide-up" style={{ animationDelay: '0.7s' }}>
            <div className="flex justify-between items-center mb-6">
                <h3 className="text-lg font-bold text-white flex items-center gap-2"><Repeat className="w-5 h-5 text-emerald-400" />Recurring</h3>
                <Zap className="w-4 h-4 text-emerald-500/40" />
            </div>
            <div className="space-y-4 flex-1 overflow-y-auto custom-scrollbar pr-2">
                {recurringData.length > 0 ? recurringData.map((item, idx) => (
                    <div key={idx} className="p-4 bg-slate-800/40 rounded-2xl border border-white/5 hover:border-white/10 transition-all group animate-fade-in" style={{ animationDelay: `${0.8 + idx * 0.1}s` }}>
                        <div className="flex justify-between items-start mb-3">
                            <div className="flex items-center gap-3">
                                <div className="w-10 h-10 rounded-xl bg-slate-900 flex items-center justify-center text-emerald-400 border border-white/5"><Radio className="w-5 h-5" /></div>
                                <div>
                                    <h4 className="text-sm font-bold text-white capitalize truncate max-w-[100px]">{item.merchant}</h4>
                                    <p className="text-[10px] text-slate-500 font-bold uppercase tracking-wider">{item.isSubscription ? 'Subscription' : 'Consistent'}</p>
                                </div>
                            </div>
                            <div className="text-right">
                                <div className="text-sm font-bold text-white">{formatCurrency(item.avgCost)}</div>
                                <p className="text-[10px] text-slate-500 font-bold uppercase">Estimated</p>
                            </div>
                        </div>
                        <button 
                            onClick={() => handleNegotiateClick(item.merchant, item.avgCost)}
                            className="w-full py-2 bg-indigo-600/10 hover:bg-indigo-600 text-indigo-400 hover:text-white rounded-xl text-[10px] font-bold uppercase tracking-widest transition-all flex items-center justify-center gap-2"
                        >
                            Negotiate <Handshake className="w-3.5 h-3.5" />
                        </button>
                    </div>
                )) : (
                    <div className="flex flex-col items-center justify-center h-full text-center opacity-40 py-8">
                        <LayoutGrid className="w-10 h-10 mb-3" />
                        <p className="text-xs font-medium">No patterns detected yet.</p>
                    </div>
                )}
            </div>
        </div>
      </div>

      {showNegotiationModal && (
          <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-black/90 backdrop-blur-sm animate-fade-in">
              <div className="bg-[#0f172a] border border-white/10 rounded-3xl w-full max-w-lg shadow-2xl overflow-hidden animate-slide-up relative">
                  <button onClick={() => setShowNegotiationModal(false)} className="absolute top-4 right-4 p-2 text-slate-400 hover:text-white z-10"><X className="w-6 h-6" /></button>
                  <div className="p-8 border-b border-white/5 bg-slate-900/40">
                      <h3 className="text-xl font-bold text-white flex items-center gap-2"><Zap className="w-5 h-5 text-indigo-400" />Negotiation Uplink</h3>
                      <p className="text-slate-400 text-xs mt-1">Generated script for {scriptMerchant}</p>
                  </div>
                  <div className="p-8">
                      {isNegotiating ? (
                          <div className="py-10 flex flex-col items-center justify-center gap-4">
                              <Loader2 className="w-10 h-10 text-indigo-500 animate-spin" />
                              <p className="text-indigo-400 font-bold uppercase tracking-widest text-[10px] animate-pulse">Neural Scripting...</p>
                          </div>
                      ) : (
                          <div className="animate-fade-in">
                               <div className="bg-slate-950/80 rounded-2xl p-6 border border-white/5 text-slate-300 font-medium leading-relaxed italic text-sm mb-6 max-h-52 overflow-y-auto custom-scrollbar">
                                    "{script}"
                               </div>
                               <button 
                                    onClick={handleCopyScript}
                                    className="w-full py-4 bg-white text-indigo-950 font-bold text-sm rounded-xl transition-all shadow-xl flex items-center justify-center gap-2 active:scale-95"
                               >
                                    {copySuccess ? <Check className="w-5 h-5" /> : <Copy className="w-4 h-4" />}
                                    {copySuccess ? 'Copied' : 'Copy to Clipboard'}
                               </button>
                          </div>
                      )}
                  </div>
              </div>
          </div>
      )}
    </div>
  );
};

const StatCard: React.FC<{ title: string, value: string | React.ReactNode, icon: React.ReactNode, change?: string, positive?: boolean, delay: string }> = ({ title, value, icon, change, positive, delay }) => (
    <div className="glass-card p-6 rounded-[2rem] border border-white/5 hover:border-white/15 transition-all shadow-lg group animate-slide-up" style={{ animationDelay: delay }}>
        <div className="flex justify-between items-start mb-4">
            <div className="p-3 bg-slate-800 rounded-xl border border-white/5 text-slate-400 group-hover:text-indigo-400 transition-colors group-hover:scale-110 duration-300">{icon}</div>
            {change && (
                <div className={`flex items-center gap-1 text-[10px] font-bold uppercase tracking-wider ${positive ? 'text-emerald-500' : 'text-rose-500'}`}>
                    {positive ? <ArrowUpRight className="w-3 h-3" /> : <ArrowDownRight className="w-3 h-3" />}
                    {change}
                </div>
            )}
        </div>
        <h4 className="text-xs font-bold text-slate-500 uppercase tracking-widest mb-1">{title}</h4>
        <div className="text-2xl font-bold text-white tracking-tight">{value}</div>
    </div>
);

export default Dashboard;

import React, { useMemo, useState, useRef, useEffect } from 'react';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import { Account, Transaction, TransactionType, Category, UserPlan, Goal } from '../types';
import { Activity, Flame, TrendingUp, Wallet, PlusCircle, CreditCard, Target, Quote, Landmark, Zap, Radio, Repeat, Check, Handshake, Copy, X, Loader2, Sparkles, ArrowUpRight, ArrowDownRight, LayoutGrid } from 'lucide-react';
import { generateNegotiationScript } from '../services/geminiService';

interface DashboardProps {
  accounts: Account[];
  transactions: Transaction[];
  goals: Goal[];
  onNavigate: (tab: string) => void;
  onAddAccount?: () => void;
  onAddTransaction?: () => void;
  onAddGoal?: () => void;
  formatCurrency: (amount: number) => string | React.ReactNode;
  userPlan?: UserPlan;
  onAskCoach?: (message: string) => void;
  negotiationUsage: number;
  onIncrementNegotiation: () => void;
}

const QUOTES = [
  { text: "Do not save what is left after spending, but spend what is left after saving.", author: "Warren Buffett" },
  { text: "A budget is telling your money where to go instead of wondering where it went.", author: "Dave Ramsey" },
  { text: "It's not your salary that makes you rich, it's your spending habits.", author: "Charles A. Jaffe" },
];

const Dashboard: React.FC<DashboardProps> = ({ accounts, transactions, goals, onNavigate, onAddAccount, onAddTransaction, onAddGoal, formatCurrency, userPlan, onAskCoach, negotiationUsage, onIncrementNegotiation }) => {
  const hasData = accounts.length > 0 || transactions.length > 0;
  const randomQuote = useMemo(() => QUOTES[Math.floor(Math.random() * QUOTES.length)], []);
  const netWorth = useMemo(() => accounts.reduce((acc, curr) => acc + curr.balance, 0), [accounts]);

  const [isNegotiating, setIsNegotiating] = useState(false);
  const [script, setScript] = useState<string | null>(null);
  const [scriptMerchant, setScriptMerchant] = useState('');
  const [showNegotiationModal, setShowNegotiationModal] = useState(false);
  const [copySuccess, setCopySuccess] = useState(false);
  const dashboardRef = useRef<HTMLDivElement>(null);

  // Spotlight Effect Logic
  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      if (!dashboardRef.current) return;
      const cards = dashboardRef.current.getElementsByClassName('spotlight-card');
      for (const card of cards as any) {
        const rect = card.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const y = e.clientY - rect.top;
        card.style.setProperty('--mouse-x', `${x}px`);
        card.style.setProperty('--mouse-y', `${y}px`);
      }
    };
    window.addEventListener('mousemove', handleMouseMove);
    return () => window.removeEventListener('mousemove', handleMouseMove);
  }, [hasData]);

  // Time & Comparison Logic
  const today = new Date();
  const currentMonth = today.getMonth();
  const currentYear = today.getFullYear();
  const currentDay = today.getDate();
  const daysInMonth = new Date(currentYear, currentMonth + 1, 0).getDate();

  const prevMonthDate = new Date(currentYear, currentMonth - 1, 1);
  const prevMonth = prevMonthDate.getMonth();
  const prevMonthYear = prevMonthDate.getFullYear();
  const daysInPrevMonth = new Date(prevMonthYear, prevMonth + 1, 0).getDate();

  // Advanced Statistics Logic
  const stats = useMemo(() => {
    const currentMTDExpenses = transactions.filter(t => {
      const d = new Date(t.date);
      return t.type === TransactionType.EXPENSE && d.getMonth() === currentMonth && d.getFullYear() === currentYear;
    });
    const currentMTDTotal = currentMTDExpenses.reduce((acc, t) => acc + t.amount, 0);

    const prevMTDExpenses = transactions.filter(t => {
      const d = new Date(t.date);
      return t.type === TransactionType.EXPENSE && d.getMonth() === prevMonth && d.getFullYear() === prevMonthYear && d.getDate() <= currentDay;
    });
    const prevMTDTotal = prevMTDExpenses.reduce((acc, t) => acc + t.amount, 0);
    const spendChange = prevMTDTotal > 0 ? ((currentMTDTotal - prevMTDTotal) / prevMTDTotal) * 100 : 0;

    const mtdNetFlow = transactions
      .filter(t => {
        const d = new Date(t.date);
        return d.getMonth() === currentMonth && d.getFullYear() === currentYear;
      })
      .reduce((acc, t) => acc + (t.type === TransactionType.INCOME ? t.amount : -t.amount), 0);
    const monthStartNW = netWorth - mtdNetFlow;
    const nwChange = monthStartNW !== 0 ? (mtdNetFlow / Math.abs(monthStartNW)) * 100 : 0;

    const currentDailyAvg = currentMTDTotal / Math.max(currentDay, 1);
    const prevFullMonthExpenses = transactions.filter(t => {
      const d = new Date(t.date);
      return t.type === TransactionType.EXPENSE && d.getMonth() === prevMonth && d.getFullYear() === prevMonthYear;
    });
    const prevFullMonthTotal = prevFullMonthExpenses.reduce((acc, t) => acc + t.amount, 0);
    const prevDailyAvg = prevFullMonthTotal / Math.max(daysInPrevMonth, 1);
    const burnChange = prevDailyAvg > 0 ? ((currentDailyAvg - prevDailyAvg) / prevDailyAvg) * 100 : 0;

    const forecastedTotal = currentDailyAvg * daysInMonth;
    const forecastChange = prevFullMonthTotal > 0 ? ((forecastedTotal - prevFullMonthTotal) / prevFullMonthTotal) * 100 : 0;

    return {
      currentMTDTotal,
      spendChange,
      nwChange,
      currentDailyAvg,
      burnChange,
      forecastedTotal,
      forecastChange
    };
  }, [transactions, currentMonth, currentYear, prevMonth, prevMonthYear, currentDay, netWorth, daysInMonth, daysInPrevMonth]);

  // System Insight Logic (Real Findings)
  const systemInsight = useMemo(() => {
    if (transactions.length === 0) return "Awaiting transaction data for neural audit...";

    // Check for high spend categories
    const categoryTotals = transactions
        .filter(t => t.type === TransactionType.EXPENSE && new Date(t.date).getMonth() === currentMonth)
        .reduce((acc, t) => {
            acc[t.category] = (acc[t.category] || 0) + t.amount;
            return acc;
        }, {} as Record<string, number>);

    const topCategory = Object.entries(categoryTotals).sort((a,b) => b[1] - a[1])[0];

    if (stats.spendChange > 10) {
        return `Expense velocity is up ${stats.spendChange.toFixed(0)}% vs last month. Nova suggests an audit of ${topCategory ? topCategory[0] : 'recent'} spending.`;
    } else if (stats.spendChange < -5) {
        return `Exceptional efficiency! You are spending ${Math.abs(stats.spendChange).toFixed(0)}% less than last month. Savings buffer is expanding.`;
    } else if (netWorth > 10000 && stats.nwChange > 0) {
        return `Capital trajectory is positive. Consider deploying surplus to high-yield goals for 7-10% estimated ghost yield.`;
    }
    return `System running within normal parameters. Currently tracking ${transactions.length} active ledger nodes.`;
  }, [transactions, stats, currentMonth]);

  const recurringData = useMemo(() => {
      const merchantMap = new Map<string, { count: number; total: number; amounts: number[]; categories: Set<Category>; }>();
      transactions.filter(t => t.type === TransactionType.EXPENSE).forEach(t => {
            const key = t.merchant.toLowerCase().trim();
            const existing = merchantMap.get(key) || { count: 0, total: 0, amounts: [], categories: new Set() };
            existing.count++;
            existing.total += t.amount;
            existing.amounts.push(t.amount);
            existing.categories.add(t.category);
            merchantMap.set(key, existing);
        });

      const items: { merchant: string; avgCost: number; isSubscription: boolean }[] = [];
      merchantMap.forEach((data, key) => {
          const avg = data.total / data.count;
          const isConsistent = data.amounts.every(a => Math.abs(a - avg) / (avg || 1) < 0.25);
          if (data.categories.has(Category.SUBSCRIPTION) || (data.count > 1 && isConsistent)) {
              items.push({ merchant: key, avgCost: avg, isSubscription: data.categories.has(Category.SUBSCRIPTION) });
          }
      });
      return items.sort((a,b) => b.avgCost - a.avgCost).slice(0, 4);
  }, [transactions]);

  const spendingData = useMemo(() => {
    const dataPoints: { date: string, actual: number | null, predicted: number | null }[] = [];
    const expenseMap = new Map<string, number>();

    transactions.filter(t => t.type === TransactionType.EXPENSE).forEach(t => {
        const d = new Date(t.date);
        d.setHours(0, 0, 0, 0);
        const key = d.toDateString();
        expenseMap.set(key, (expenseMap.get(key) || 0) + t.amount);
    });

    for (let i = 0; i <= 30; i++) {
        const d = new Date(today);
        d.setDate(today.getDate() - (30 - i));
        d.setHours(0, 0, 0, 0);
        dataPoints.push({
            date: d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }),
            actual: expenseMap.get(d.toDateString()) || 0,
            predicted: null
        });
    }

    const last = dataPoints[dataPoints.length - 1];
    last.predicted = last.actual;

    for (let i = 1; i <= 7; i++) {
        const d = new Date(today);
        d.setDate(today.getDate() + i);
        dataPoints.push({
            date: d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }),
            actual: null,
            predicted: stats.currentDailyAvg * (1 + (Math.sin(i) * 0.1))
        });
    }
    return dataPoints;
  }, [transactions, stats.currentDailyAvg, today]);

  const handleNegotiateClick = async (merchant: string, amount: number) => {
      const limit = userPlan === 'ultra' ? Infinity : userPlan === 'pro' ? 5 : 3;
      if (negotiationUsage >= limit) {
          onNavigate('plans');
          return; 
      }
      setIsNegotiating(true);
      setScriptMerchant(merchant);
      setShowNegotiationModal(true);
      const generated = await generateNegotiationScript(merchant, amount);
      setScript(generated);
      setIsNegotiating(false);
      onIncrementNegotiation();
  };

  const handleCopyScript = () => {
      if (script) {
          navigator.clipboard.writeText(script);
          setCopySuccess(true);
          setTimeout(() => setCopySuccess(false), 2000);
      }
  };

  if (!hasData) {
     return (
        <div className="flex flex-col items-center justify-center w-full min-h-full py-12 animate-fade-in text-center relative overflow-hidden">
            <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[600px] h-[600px] bg-indigo-500/10 rounded-full blur-[120px] pointer-events-none animate-pulse-slow"></div>
            <div className="max-w-4xl mx-auto mb-12 relative z-10">
                <div className="flex justify-center mb-8">
                    <div className="w-14 h-14 rounded-2xl bg-slate-800 flex items-center justify-center shadow-2xl border border-white/10 rotate-3">
                        <Quote className="w-7 h-7 text-indigo-400 fill-current" />
                    </div>
                </div>
                <h1 className="text-3xl md:text-4xl font-bold text-white tracking-tight mb-4 px-4 uppercase">Initialize Terminal</h1>
                <p className="text-lg text-slate-400 font-medium italic tracking-wide">"{randomQuote.text}" — {randomQuote.author}</p>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6 w-full max-w-5xl relative z-10 px-4">
                 <button onClick={onAddAccount} className="group bg-slate-900 border border-white/5 p-10 rounded-[2.5rem] text-left hover:border-indigo-500/30 transition-all hover:-translate-y-1 shadow-2xl">
                    <div className="w-14 h-14 rounded-2xl bg-indigo-500/10 flex items-center justify-center mb-8 group-hover:scale-110 transition-transform text-indigo-400"><Landmark className="w-7 h-7" /></div>
                    <h3 className="text-xl font-bold text-white mb-3">Bridge Assets</h3>
                    <p className="text-slate-500 text-sm leading-relaxed">Securely link your bank nodes or add manual ledgers to start tracking.</p>
                 </button>
                 <button onClick={onAddTransaction} className="group bg-slate-900 border border-white/5 p-10 rounded-[2.5rem] text-left hover:border-emerald-500/30 transition-all hover:-translate-y-1 shadow-2xl">
                    <div className="w-14 h-14 rounded-2xl bg-emerald-500/10 flex items-center justify-center mb-8 group-hover:scale-110 transition-transform text-emerald-400"><PlusCircle className="w-7 h-7" /></div>
                    <h3 className="text-xl font-bold text-white mb-3">Sync Activity</h3>
                    <p className="text-slate-500 text-sm leading-relaxed">Archive your daily spending to calibrate the AI predictive engine.</p>
                 </button>
                 <button onClick={onAddGoal} className="group bg-slate-900 border border-white/5 p-10 rounded-[2.5rem] text-left hover:border-rose-500/30 transition-all hover:-translate-y-1 shadow-2xl">
                    <div className="w-14 h-14 rounded-2xl bg-rose-500/10 flex items-center justify-center mb-8 group-hover:scale-110 transition-transform text-rose-400"><Target className="w-7 h-7" /></div>
                    <h3 className="text-xl font-bold text-white mb-3">Set Objectives</h3>
                    <p className="text-slate-500 text-sm leading-relaxed">Establish savings targets and let Nova optimize your trajectory.</p>
                 </button>
            </div>
        </div>
     );
  }

  return (
    <div ref={dashboardRef} className="space-y-6 animate-slide-up pb-10">
      <style>{`
        .spotlight-card {
          position: relative;
          overflow: hidden;
        }
        .spotlight-card::before {
          content: "";
          position: absolute;
          inset: 0;
          background: radial-gradient(
            600px circle at var(--mouse-x, 0) var(--mouse-y, 0),
            rgba(99, 102, 241, 0.15),
            transparent 40%
          );
          z-index: 0;
          pointer-events: none;
        }
      `}</style>

      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 animate-fade-in">
        <div>
          <h2 className="text-3xl font-black text-white tracking-tight uppercase italic">Dashboard :: Alpha</h2>
          <p className="text-slate-400 mt-1 font-bold text-xs uppercase tracking-widest opacity-60">Financial performance for {today.toLocaleDateString('en-US', { month: 'long', year: 'numeric' })}</p>
        </div>
      </div>

      {/* Dynamic System Insights positioned exactly as requested */}
      <div 
        className="spotlight-card bg-[#020617] rounded-[2.5rem] p-8 md:p-10 shadow-2xl relative border border-white/10 group cursor-pointer animate-slide-up" 
        style={{ animationDelay: '0.1s' }} 
        onClick={() => onNavigate('insights')}
      >
          <div className="flex flex-col md:flex-row justify-between items-center gap-6 relative z-10">
              <div className="flex items-center gap-6">
                  <div className="w-20 h-20 rounded-3xl bg-indigo-600/10 border border-indigo-500/20 flex items-center justify-center shadow-inner group-hover:rotate-6 transition-transform duration-500">
                      <Sparkles className="w-10 h-10 text-indigo-400 animate-pulse" />
                  </div>
                  <div>
                      <h3 className="text-xl font-black text-white uppercase tracking-tighter">Neural System Insight</h3>
                      <p className="text-slate-400 font-medium leading-relaxed max-w-2xl mt-1">{systemInsight}</p>
                  </div>
              </div>
              <button className="px-8 py-4 bg-indigo-600 text-white rounded-2xl font-black text-[10px] uppercase tracking-[0.2em] shadow-xl transition-all hover:scale-105 active:scale-95 flex items-center gap-2">
                 Deep Audit <ArrowRight className="w-4 h-4" />
              </button>
          </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard 
            title="Net Worth" 
            value={formatCurrency(netWorth)} 
            icon={<Wallet className="w-5 h-5 text-indigo-400" />} 
            change={stats.nwChange.toFixed(1) + '%'} 
            positive={stats.nwChange >= 0}
            delay="0.2s"
        />
        <StatCard 
            title="Monthly Spend" 
            value={formatCurrency(stats.currentMTDTotal)} 
            icon={<CreditCard className="w-5 h-5 text-rose-400" />} 
            change={Math.abs(stats.spendChange).toFixed(1) + '%'} 
            positive={stats.spendChange <= 0} 
            delay="0.3s"
        />
        <StatCard 
            title="Burn Rate/Day" 
            value={formatCurrency(stats.currentDailyAvg)} 
            icon={<Flame className="w-5 h-5 text-amber-400" />} 
            change={Math.abs(stats.burnChange).toFixed(1) + '%'} 
            positive={stats.burnChange <= 0}
            delay="0.4s"
        />
        <StatCard 
            title="Predicted Spend" 
            value={formatCurrency(stats.forecastedTotal)} 
            icon={<TrendingUp className="w-5 h-5 text-emerald-400" />} 
            change={Math.abs(stats.forecastChange).toFixed(1) + '%'} 
            positive={stats.forecastChange <= 0}
            delay="0.5s"
        />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-2 spotlight-card glass-card p-6 md:p-8 rounded-[2rem] border border-white/5 shadow-xl animate-slide-up" style={{ animationDelay: '0.6s' }}>
            <div className="flex justify-between items-center mb-8 relative z-10">
                <h3 className="text-lg font-black text-white uppercase tracking-tighter flex items-center gap-3"><Activity className="w-6 h-6 text-indigo-400" />Expenditure Vector</h3>
                <div className="flex gap-4 text-[10px] font-black uppercase tracking-widest opacity-60">
                    <div className="flex items-center gap-1.5"><div className="w-2.5 h-2.5 rounded-full bg-indigo-500"></div><span>Actual</span></div>
                    <div className="flex items-center gap-1.5"><div className="w-2.5 h-2.5 rounded-full bg-slate-600"></div><span>Predicted</span></div>
                </div>
            </div>
            <div className="h-72 w-full relative z-10">
                <ResponsiveContainer width="100%" height="100%">
                    <AreaChart data={spendingData}>
                        <defs>
                            <linearGradient id="colorActual" x1="0" y1="0" x2="0" y2="1">
                                <stop offset="5%" stopColor="#6366f1" stopOpacity={0.2}/>
                                <stop offset="95%" stopColor="#6366f1" stopOpacity={0}/>
                            </linearGradient>
                        </defs>
                        <CartesianGrid strokeDasharray="3 3" stroke="#1e293b" vertical={false} />
                        <XAxis dataKey="date" stroke="#475569" fontSize={10} tickLine={false} axisLine={false} tick={{fontWeight:'bold'}} />
                        <YAxis stroke="#475569" fontSize={10} tickLine={false} axisLine={false} hide />
                        <Tooltip 
                            contentStyle={{ backgroundColor: '#020617', border: '1px solid rgba(255,255,255,0.05)', borderRadius: '12px', boxShadow: '0 10px 15px rgba(0,0,0,0.5)' }}
                            itemStyle={{ color: '#fff', fontSize: '12px', fontWeight: 'bold' }}
                        />
                        <Area type="monotone" dataKey="actual" stroke="#6366f1" strokeWidth={3} fillOpacity={1} fill="url(#colorActual)" animationDuration={1500} />
                        <Area type="monotone" dataKey="predicted" stroke="#475569" strokeWidth={2} strokeDasharray="5 5" fillOpacity={0} animationDuration={1800} />
                    </AreaChart>
                </ResponsiveContainer>
            </div>
        </div>

        <div className="spotlight-card glass-card p-6 md:p-8 rounded-[2rem] border border-white/5 shadow-xl flex flex-col animate-slide-up" style={{ animationDelay: '0.7s' }}>
            <div className="flex justify-between items-center mb-6 relative z-10">
                <h3 className="text-lg font-black text-white uppercase tracking-tighter flex items-center gap-3"><Repeat className="w-6 h-6 text-emerald-400" />Recurring Protocols</h3>
                <Zap className="w-4 h-4 text-emerald-500/40 animate-pulse" />
            </div>
            <div className="space-y-4 flex-1 overflow-y-auto custom-scrollbar pr-2 relative z-10">
                {recurringData.length > 0 ? recurringData.map((item, idx) => (
                    <div key={idx} className="p-4 bg-slate-900/60 rounded-2xl border border-white/5 hover:border-indigo-500/30 transition-all group animate-fade-in" style={{ animationDelay: `${0.8 + idx * 0.1}s` }}>
                        <div className="flex justify-between items-start mb-3">
                            <div className="flex items-center gap-3">
                                <div className="w-10 h-10 rounded-xl bg-slate-950 flex items-center justify-center text-emerald-400 border border-white/5 group-hover:scale-110 transition-transform"><Radio className="w-5 h-5" /></div>
                                <div>
                                    <h4 className="text-xs font-black text-white uppercase truncate max-w-[100px]">{item.merchant}</h4>
                                    <p className="text-[9px] text-slate-500 font-black uppercase tracking-widest">{item.isSubscription ? 'Static' : 'Dynamic'}</p>
                                </div>
                            </div>
                            <div className="text-right">
                                <div className="text-sm font-black text-white">{formatCurrency(item.avgCost)}</div>
                                <p className="text-[9px] text-slate-500 font-bold uppercase">Estimated</p>
                            </div>
                        </div>
                        <button 
                            onClick={() => handleNegotiateClick(item.merchant, item.avgCost)}
                            className="w-full py-2 bg-indigo-600/10 hover:bg-indigo-600 text-indigo-400 hover:text-white rounded-xl text-[9px] font-black uppercase tracking-widest transition-all flex items-center justify-center gap-2"
                        >
                            Optimize Node <Handshake className="w-3.5 h-3.5" />
                        </button>
                    </div>
                )) : (
                    <div className="flex flex-col items-center justify-center h-full text-center opacity-40 py-8">
                        <LayoutGrid className="w-10 h-10 mb-3" />
                        <p className="text-xs font-medium">Awaiting pattern detection...</p>
                    </div>
                )}
            </div>
        </div>
      </div>

      {showNegotiationModal && (
          <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-black/95 backdrop-blur-md animate-fade-in">
              <div className="bg-[#020617] border border-white/10 rounded-[3rem] w-full max-w-lg shadow-2xl overflow-hidden animate-slide-up relative">
                  <button onClick={() => setShowNegotiationModal(false)} className="absolute top-6 right-6 p-2 text-slate-400 hover:text-white z-10 bg-slate-900 rounded-full"><X className="w-5 h-5" /></button>
                  <div className="p-10 border-b border-white/5 bg-slate-900/40">
                      <h3 className="text-3xl font-black text-white flex items-center gap-3 uppercase tracking-tighter"><Zap className="w-8 h-8 text-indigo-400 fill-indigo-400" />Uplink Script</h3>
                      <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest mt-1">Optimization protocol for {scriptMerchant}</p>
                  </div>
                  <div className="p-10">
                      {isNegotiating ? (
                          <div className="py-10 flex flex-col items-center justify-center gap-6">
                              <Loader2 className="w-12 h-12 text-indigo-500 animate-spin" />
                              <p className="text-indigo-400 font-black uppercase tracking-[0.3em] text-xs animate-pulse">Running analysis...</p>
                          </div>
                      ) : (
                          <div className="animate-fade-in">
                               <div className="bg-slate-950/80 rounded-2xl p-8 border border-white/5 text-slate-300 font-bold leading-relaxed italic text-sm mb-8 max-h-52 overflow-y-auto custom-scrollbar shadow-inner">
                                    "{script}"
                               </div>
                               <button 
                                    onClick={handleCopyScript}
                                    className="w-full py-5 bg-white text-indigo-950 font-black uppercase tracking-[0.2em] text-xs rounded-2xl transition-all shadow-xl flex items-center justify-center gap-3 active:scale-95 hover:bg-indigo-50"
                               >
                                    {copySuccess ? <Check className="w-5 h-5" /> : <Copy className="w-5 h-5" />}
                                    {copySuccess ? 'Copied to Ledger' : 'Copy to Clipboard'}
                               </button>
                          </div>
                      )}
                  </div>
              </div>
          </div>
      )}
    </div>
  );
};

const StatCard: React.FC<{ title: string, value: string | React.ReactNode, icon: React.ReactNode, change?: string, positive?: boolean, delay: string }> = ({ title, value, icon, change, positive, delay }) => (
    <div className="spotlight-card glass-card p-8 rounded-[2.5rem] border border-white/5 hover:border-white/15 transition-all shadow-lg group animate-slide-up" style={{ animationDelay: delay }}>
        <div className="flex justify-between items-start mb-6 relative z-10">
            <div className="p-4 bg-slate-800 rounded-2xl border border-white/5 text-slate-400 group-hover:text-indigo-400 transition-colors group-hover:scale-110 duration-300 shadow-inner">{icon}</div>
            {change && (
                <div className={`flex items-center gap-1 text-[11px] font-black uppercase tracking-widest ${positive ? 'text-emerald-500' : 'text-rose-500'}`}>
                    {positive ? <ArrowUpRight className="w-4 h-4" /> : <ArrowDownRight className="w-4 h-4" />}
                    {change}
                </div>
            )}
        </div>
        <div className="relative z-10">
            <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-[0.3em] mb-1">{title}</h4>
            <div className="text-3xl font-black text-white tracking-tighter">{value}</div>
        </div>
    </div>
);

export default Dashboard;

import React, { useMemo, useState, useRef, useEffect } from 'react';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import { Account, Transaction, TransactionType, Category, UserPlan, Goal } from '../types';
import { Activity, Flame, TrendingUp, Wallet, PlusCircle, CreditCard, Target, Quote, Landmark, Zap, Radio, Repeat, Check, Handshake, Copy, X, Loader2, Sparkles, ArrowUpRight, ArrowDownRight, LayoutGrid, ArrowRight } from 'lucide-react';
import { generateNegotiationScript } from '../services/geminiService';

interface DashboardProps {
  accounts: Account[];
  transactions: Transaction[];
  goals: Goal[];
  onNavigate: (tab: string) => void;
  onAddAccount?: () => void;
  onAddTransaction?: () => void;
  onAddGoal?: () => void;
  formatCurrency: (amount: number) => string | React.ReactNode;
  userPlan?: UserPlan;
  onAskCoach?: (message: string) => void;
  negotiationUsage: number;
  onIncrementNegotiation: () => void;
}

const QUOTES = [
  { text: "Do not save what is left after spending, but spend what is left after saving.", author: "Warren Buffett" },
  { text: "A budget is telling your money where to go instead of wondering where it went.", author: "Dave Ramsey" },
  { text: "It's not your salary that makes you rich, it's your spending habits.", author: "Charles A. Jaffe" },
];

const Dashboard: React.FC<DashboardProps> = ({ accounts, transactions, goals, onNavigate, onAddAccount, onAddTransaction, onAddGoal, formatCurrency, userPlan, onAskCoach, negotiationUsage, onIncrementNegotiation }) => {
  const hasData = accounts.length > 0 || transactions.length > 0;
  const randomQuote = useMemo(() => QUOTES[Math.floor(Math.random() * QUOTES.length)], []);
  const netWorth = useMemo(() => accounts.reduce((acc, curr) => acc + curr.balance, 0), [accounts]);

  const [isNegotiating, setIsNegotiating] = useState(false);
  const [script, setScript] = useState<string | null>(null);
  const [scriptMerchant, setScriptMerchant] = useState('');
  const [showNegotiationModal, setShowNegotiationModal] = useState(false);
  const [copySuccess, setCopySuccess] = useState(false);
  const dashboardRef = useRef<HTMLDivElement>(null);

  // Spotlight Effect Logic
  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      if (!dashboardRef.current) return;
      const cards = dashboardRef.current.getElementsByClassName('spotlight-card');
      for (const card of cards as any) {
        const rect = card.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const y = e.clientY - rect.top;
        card.style.setProperty('--mouse-x', `${x}px`);
        card.style.setProperty('--mouse-y', `${y}px`);
      }
    };
    window.addEventListener('mousemove', handleMouseMove);
    return () => window.removeEventListener('mousemove', handleMouseMove);
  }, [hasData]);

  // Time & Comparison Logic
  const today = new Date();
  const currentMonth = today.getMonth();
  const currentYear = today.getFullYear();
  const currentDay = today.getDate();
  const daysInMonth = new Date(currentYear, currentMonth + 1, 0).getDate();

  const prevMonthDate = new Date(currentYear, currentMonth - 1, 1);
  const prevMonth = prevMonthDate.getMonth();
  const prevMonthYear = prevMonthDate.getFullYear();
  const daysInPrevMonth = new Date(prevMonthYear, prevMonth + 1, 0).getDate();

  // Advanced Statistics Logic
  const stats = useMemo(() => {
    const currentMTDExpenses = transactions.filter(t => {
      const d = new Date(t.date);
      return t.type === TransactionType.EXPENSE && d.getMonth() === currentMonth && d.getFullYear() === currentYear;
    });
    const currentMTDTotal = currentMTDExpenses.reduce((acc, t) => acc + t.amount, 0);

    const prevMTDExpenses = transactions.filter(t => {
      const d = new Date(t.date);
      return t.type === TransactionType.EXPENSE && d.getMonth() === prevMonth && d.getFullYear() === prevMonthYear && d.getDate() <= currentDay;
    });
    const prevMTDTotal = prevMTDExpenses.reduce((acc, t) => acc + t.amount, 0);
    const spendChange = prevMTDTotal > 0 ? ((currentMTDTotal - prevMTDTotal) / prevMTDTotal) * 100 : 0;

    const mtdNetFlow = transactions
      .filter(t => {
        const d = new Date(t.date);
        return d.getMonth() === currentMonth && d.getFullYear() === currentYear;
      })
      .reduce((acc, t) => acc + (t.type === TransactionType.INCOME ? t.amount : -t.amount), 0);
    const monthStartNW = netWorth - mtdNetFlow;
    const nwChange = monthStartNW !== 0 ? (mtdNetFlow / Math.abs(monthStartNW)) * 100 : 0;

    const currentDailyAvg = currentMTDTotal / Math.max(currentDay, 1);
    const prevFullMonthExpenses = transactions.filter(t => {
      const d = new Date(t.date);
      return t.type === TransactionType.EXPENSE && d.getMonth() === prevMonth && d.getFullYear() === prevMonthYear;
    });
    const prevFullMonthTotal = prevFullMonthExpenses.reduce((acc, t) => acc + t.amount, 0);
    const prevDailyAvg = prevFullMonthTotal / Math.max(daysInPrevMonth, 1);
    const burnChange = prevDailyAvg > 0 ? ((currentDailyAvg - prevDailyAvg) / prevDailyAvg) * 100 : 0;

    const forecastedTotal = currentDailyAvg * daysInMonth;
    const forecastChange = prevFullMonthTotal > 0 ? ((forecastedTotal - prevFullMonthTotal) / prevFullMonthTotal) * 100 : 0;

    return {
      currentMTDTotal,
      spendChange,
      nwChange,
      currentDailyAvg,
      burnChange,
      forecastedTotal,
      forecastChange
    };
  }, [transactions, currentMonth, currentYear, prevMonth, prevMonthYear, currentDay, netWorth, daysInMonth, daysInPrevMonth]);

  // System Insight Logic (Real Findings)
  const systemInsight = useMemo(() => {
    if (transactions.length === 0) return "Awaiting transaction data for neural audit...";

    // Check for high spend categories
    const categoryTotals = transactions
        .filter(t => t.type === TransactionType.EXPENSE && new Date(t.date).getMonth() === currentMonth)
        .reduce((acc, t) => {
            acc[t.category] = (acc[t.category] || 0) + t.amount;
            return acc;
        }, {} as Record<string, number>);

    // Fix: cast to number to resolve arithmetic operation type error on line 129 (left and right sides of subtraction)
    const topCategory = Object.entries(categoryTotals).sort((a,b) => (b[1] as number) - (a[1] as number))[0];

    if (stats.spendChange > 10) {
        return `Expense velocity is up ${stats.spendChange.toFixed(0)}% vs last month. Nova suggests an audit of ${topCategory ? topCategory[0] : 'recent'} spending.`;
    } else if (stats.spendChange < -5) {
        return `Exceptional efficiency! You are spending ${Math.abs(stats.spendChange).toFixed(0)}% less than last month. Savings buffer is expanding.`;
    } else if (netWorth > 10000 && stats.nwChange > 0) {
        return `Capital trajectory is positive. Consider deploying surplus to high-yield goals for 7-10% estimated ghost yield.`;
    }
    return `System running within normal parameters. Currently tracking ${transactions.length} active ledger nodes.`;
  }, [transactions, stats, currentMonth, netWorth]);

  const recurringData = useMemo(() => {
      const merchantMap = new Map<string, { count: number; total: number; amounts: number[]; categories: Set<Category>; }>();
      transactions.filter(t => t.type === TransactionType.EXPENSE).forEach(t => {
            const key = t.merchant.toLowerCase().trim();
            const existing = merchantMap.get(key) || { count: 0, total: 0, amounts: [], categories: new Set() };
            existing.count++;
            existing.total += t.amount;
            existing.amounts.push(t.amount);
            existing.categories.add(t.category);
            merchantMap.set(key, existing);
        });

      const items: { merchant: string; avgCost: number; isSubscription: boolean }[] = [];
      merchantMap.forEach((data, key) => {
          const avg = data.total / data.count;
          const isConsistent = data.amounts.every(a => Math.abs(a - avg) / (avg || 1) < 0.25);
          if (data.categories.has(Category.SUBSCRIPTION) || (data.count > 1 && isConsistent)) {
              items.push({ merchant: key, avgCost: avg, isSubscription: data.categories.has(Category.SUBSCRIPTION) });
          }
      });
      return items.sort((a,b) => b.avgCost - a.avgCost).slice(0, 4);
  }, [transactions]);

  const spendingData = useMemo(() => {
    const dataPoints: { date: string, actual: number | null, predicted: number | null }[] = [];
    const expenseMap = new Map<string, number>();

    transactions.filter(t => t.type === TransactionType.EXPENSE).forEach(t => {
        const d = new Date(t.date);
        d.setHours(0, 0, 0, 0);
        const key = d.toDateString();
        expenseMap.set(key, (expenseMap.get(key) || 0) + t.amount);
    });

    for (let i = 0; i <= 30; i++) {
        const d = new Date(today);
        d.setDate(today.getDate() - (30 - i));
        d.setHours(0, 0, 0, 0);
        dataPoints.push({
            date: d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }),
            actual: expenseMap.get(d.toDateString()) || 0,
            predicted: null
        });
    }

    const last = dataPoints[dataPoints.length - 1];
    last.predicted = last.actual;

    for (let i = 1; i <= 7; i++) {
        const d = new Date(today);
        d.setDate(today.getDate() + i);
        dataPoints.push({
            date: d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }),
            actual: null,
            predicted: stats.currentDailyAvg * (1 + (Math.sin(i) * 0.1))
        });
    }
    return dataPoints;
  }, [transactions, stats.currentDailyAvg, today]);

  const handleNegotiateClick = async (merchant: string, amount: number) => {
      const limit = userPlan === 'ultra' ? Infinity : userPlan === 'pro' ? 5 : 3;
      if (negotiationUsage >= limit) {
          onNavigate('plans');
          return; 
      }
      setIsNegotiating(true);
      setScriptMerchant(merchant);
      setShowNegotiationModal(true);
      const generated = await generateNegotiationScript(merchant, amount);
      setScript(generated);
      setIsNegotiating(false);
      onIncrementNegotiation();
  };

  const handleCopyScript = () => {
      if (script) {
          navigator.clipboard.writeText(script);
          setCopySuccess(true);
          setTimeout(() => setCopySuccess(false), 2000);
      }
  };

  if (!hasData) {
     return (
        <div className="flex flex-col items-center justify-center w-full min-h-full py-12 animate-fade-in text-center relative overflow-hidden">
            <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[600px] h-[600px] bg-indigo-500/10 rounded-full blur-[120px] pointer-events-none animate-pulse-slow"></div>
            <div className="max-w-4xl mx-auto mb-12 relative z-10">
                <div className="flex justify-center mb-8">
                    <div className="w-14 h-14 rounded-2xl bg-slate-800 flex items-center justify-center shadow-2xl border border-white/10 rotate-3">
                        <Quote className="w-7 h-7 text-indigo-400 fill-current" />
                    </div>
                </div>
                <h1 className="text-3xl md:text-4xl font-bold text-white tracking-tight mb-4 px-4 uppercase">Initialize Terminal</h1>
                <p className="text-lg text-slate-400 font-medium italic tracking-wide">"{randomQuote.text}" — {randomQuote.author}</p>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6 w-full max-w-5xl relative z-10 px-4">
                 <button onClick={onAddAccount} className="group bg-slate-900 border border-white/5 p-10 rounded-[2.5rem] text-left hover:border-indigo-500/30 transition-all hover:-translate-y-1 shadow-2xl">
                    <div className="w-14 h-14 rounded-2xl bg-indigo-500/10 flex items-center justify-center mb-8 group-hover:scale-110 transition-transform text-indigo-400"><Landmark className="w-7 h-7" /></div>
                    <h3 className="text-xl font-bold text-white mb-3">Bridge Assets</h3>
                    <p className="text-slate-500 text-sm leading-relaxed">Securely link your bank nodes or add manual ledgers to start tracking.</p>
                 </button>
                 <button onClick={onAddTransaction} className="group bg-slate-900 border border-white/5 p-10 rounded-[2.5rem] text-left hover:border-emerald-500/30 transition-all hover:-translate-y-1 shadow-2xl">
                    <div className="w-14 h-14 rounded-2xl bg-emerald-500/10 flex items-center justify-center mb-8 group-hover:scale-110 transition-transform text-emerald-400"><PlusCircle className="w-7 h-7" /></div>
                    <h3 className="text-xl font-bold text-white mb-3">Sync Activity</h3>
                    <p className="text-slate-500 text-sm leading-relaxed">Archive your daily spending to calibrate the AI predictive engine.</p>
                 </button>
                 <button onClick={onAddGoal} className="group bg-slate-900 border border-white/5 p-10 rounded-[2.5rem] text-left hover:border-rose-500/30 transition-all hover:-translate-y-1 shadow-2xl">
                    <div className="w-14 h-14 rounded-2xl bg-rose-500/10 flex items-center justify-center mb-8 group-hover:scale-110 transition-transform text-rose-400"><Target className="w-7 h-7" /></div>
                    <h3 className="text-xl font-bold text-white mb-3">Set Objectives</h3>
                    <p className="text-slate-500 text-sm leading-relaxed">Establish savings targets and let Nova optimize your trajectory.</p>
                 </button>
            </div>
        </div>
     );
  }

  return (
    <div ref={dashboardRef} className="space-y-6 animate-slide-up pb-10">
      <style>{`
        .spotlight-card {
          position: relative;
          overflow: hidden;
        }
        .spotlight-card::before {
          content: "";
          position: absolute;
          inset: 0;
          background: radial-gradient(
            600px circle at var(--mouse-x, 0) var(--mouse-y, 0),
            rgba(99, 102, 241, 0.15),
            transparent 40%
          );
          z-index: 0;
          pointer-events: none;
        }
      `}</style>

      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 animate-fade-in">
        <div>
          <h2 className="text-3xl font-black text-white tracking-tight uppercase italic">Dashboard :: Alpha</h2>
          <p className="text-slate-400 mt-1 font-bold text-xs uppercase tracking-widest opacity-60">Financial performance for {today.toLocaleDateString('en-US', { month: 'long', year: 'numeric' })}</p>
        </div>
      </div>

      {/* Dynamic System Insights positioned exactly as requested */}
      <div 
        className="spotlight-card bg-[#020617] rounded-[2.5rem] p-8 md:p-10 shadow-2xl relative border border-white/10 group cursor-pointer animate-slide-up" 
        style={{ animationDelay: '0.1s' }} 
        onClick={() => onNavigate('insights')}
      >
          <div className="flex flex-col md:flex-row justify-between items-center gap-6 relative z-10">
              <div className="flex items-center gap-6">
                  <div className="w-20 h-20 rounded-3xl bg-indigo-600/10 border border-indigo-500/20 flex items-center justify-center shadow-inner group-hover:rotate-6 transition-transform duration-500">
                      <Sparkles className="w-10 h-10 text-indigo-400 animate-pulse" />
                  </div>
                  <div>
                      <h3 className="text-xl font-black text-white uppercase tracking-tighter">Neural System Insight</h3>
                      <p className="text-slate-400 font-medium leading-relaxed max-w-2xl mt-1">{systemInsight}</p>
                  </div>
              </div>
              <button className="px-8 py-4 bg-indigo-600 text-white rounded-2xl font-black text-[10px] uppercase tracking-[0.2em] shadow-xl transition-all hover:scale-105 active:scale-95 flex items-center gap-2">
                 Deep Audit <ArrowRight className="w-4 h-4" />
              </button>
          </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard 
            title="Net Worth" 
            value={formatCurrency(netWorth)} 
            icon={<Wallet className="w-5 h-5 text-indigo-400" />} 
            change={stats.nwChange.toFixed(1) + '%'} 
            positive={stats.nwChange >= 0}
            delay="0.2s"
        />
        <StatCard 
            title="Monthly Spend" 
            value={formatCurrency(stats.currentMTDTotal)} 
            icon={<CreditCard className="w-5 h-5 text-rose-400" />} 
            change={Math.abs(stats.spendChange).toFixed(1) + '%'} 
            positive={stats.spendChange <= 0} 
            delay="0.3s"
        />
        <StatCard 
            title="Burn Rate/Day" 
            value={formatCurrency(stats.currentDailyAvg)} 
            icon={<Flame className="w-5 h-5 text-amber-400" />} 
            change={Math.abs(stats.burnChange).toFixed(1) + '%'} 
            positive={stats.burnChange <= 0}
            delay="0.4s"
        />
        <StatCard 
            title="Predicted Spend" 
            value={formatCurrency(stats.forecastedTotal)} 
            icon={<TrendingUp className="w-5 h-5 text-emerald-400" />} 
            change={Math.abs(stats.forecastChange).toFixed(1) + '%'} 
            positive={stats.forecastChange <= 0}
            delay="0.5s"
        />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-2 spotlight-card glass-card p-6 md:p-8 rounded-[2rem] border border-white/5 shadow-xl animate-slide-up" style={{ animationDelay: '0.6s' }}>
            <div className="flex justify-between items-center mb-8 relative z-10">
                <h3 className="text-lg font-black text-white uppercase tracking-tighter flex items-center gap-3"><Activity className="w-6 h-6 text-indigo-400" />Expenditure Vector</h3>
                <div className="flex gap-4 text-[10px] font-black uppercase tracking-widest opacity-60">
                    <div className="flex items-center gap-1.5"><div className="w-2.5 h-2.5 rounded-full bg-indigo-500"></div><span>Actual</span></div>
                    <div className="flex items-center gap-1.5"><div className="w-2.5 h-2.5 rounded-full bg-slate-600"></div><span>Predicted</span></div>
                </div>
            </div>
            <div className="h-72 w-full relative z-10">
                <ResponsiveContainer width="100%" height="100%">
                    <AreaChart data={spendingData}>
                        <defs>
                            <linearGradient id="colorActual" x1="0" y1="0" x2="0" y2="1">
                                <stop offset="5%" stopColor="#6366f1" stopOpacity={0.2}/>
                                <stop offset="95%" stopColor="#6366f1" stopOpacity={0}/>
                            </linearGradient>
                        </defs>
                        <CartesianGrid strokeDasharray="3 3" stroke="#1e293b" vertical={false} />
                        <XAxis dataKey="date" stroke="#475569" fontSize={10} tickLine={false} axisLine={false} tick={{fontWeight:'bold'}} />
                        <YAxis stroke="#475569" fontSize={10} tickLine={false} axisLine={false} hide />
                        <Tooltip 
                            contentStyle={{ backgroundColor: '#020617', border: '1px solid rgba(255,255,255,0.05)', borderRadius: '12px', boxShadow: '0 10px 15px rgba(0,0,0,0.5)' }}
                            itemStyle={{ color: '#fff', fontSize: '12px', fontWeight: 'bold' }}
                        />
                        <Area type="monotone" dataKey="actual" stroke="#6366f1" strokeWidth={3} fillOpacity={1} fill="url(#colorActual)" animationDuration={1500} />
                        <Area type="monotone" dataKey="predicted" stroke="#475569" strokeWidth={2} strokeDasharray="5 5" fillOpacity={0} animationDuration={1800} />
                    </AreaChart>
                </ResponsiveContainer>
            </div>
        </div>

        <div className="spotlight-card glass-card p-6 md:p-8 rounded-[2rem] border border-white/5 shadow-xl flex flex-col animate-slide-up" style={{ animationDelay: '0.7s' }}>
            <div className="flex justify-between items-center mb-6 relative z-10">
                <h3 className="text-lg font-black text-white uppercase tracking-tighter flex items-center gap-3"><Repeat className="w-6 h-6 text-emerald-400" />Recurring Protocols</h3>
                <Zap className="w-4 h-4 text-emerald-500/40 animate-pulse" />
            </div>
            <div className="space-y-4 flex-1 overflow-y-auto custom-scrollbar pr-2 relative z-10">
                {recurringData.length > 0 ? recurringData.map((item, idx) => (
                    <div key={idx} className="p-4 bg-slate-900/60 rounded-2xl border border-white/5 hover:border-indigo-500/30 transition-all group animate-fade-in" style={{ animationDelay: `${0.8 + idx * 0.1}s` }}>
                        <div className="flex justify-between items-start mb-3">
                            <div className="flex items-center gap-3">
                                <div className="w-10 h-10 rounded-xl bg-slate-950 flex items-center justify-center text-emerald-400 border border-white/5 group-hover:scale-110 transition-transform"><Radio className="w-5 h-5" /></div>
                                <div>
                                    <h4 className="text-xs font-black text-white uppercase truncate max-w-[100px]">{item.merchant}</h4>
                                    <p className="text-[9px] text-slate-500 font-black uppercase tracking-widest">{item.isSubscription ? 'Static' : 'Dynamic'}</p>
                                </div>
                            </div>
                            <div className="text-right">
                                <div className="text-sm font-black text-white">{formatCurrency(item.avgCost)}</div>
                                <p className="text-[9px] text-slate-500 font-bold uppercase">Estimated</p>
                            </div>
                        </div>
                        <button 
                            onClick={() => handleNegotiateClick(item.merchant, item.avgCost)}
                            className="w-full py-2 bg-indigo-600/10 hover:bg-indigo-600 text-indigo-400 hover:text-white rounded-xl text-[9px] font-black uppercase tracking-widest transition-all flex items-center justify-center gap-2"
                        >
                            Optimize Node <Handshake className="w-3.5 h-3.5" />
                        </button>
                    </div>
                )) : (
                    <div className="flex flex-col items-center justify-center h-full text-center opacity-40 py-8">
                        <LayoutGrid className="w-10 h-10 mb-3" />
                        <p className="text-xs font-medium">Awaiting pattern detection...</p>
                    </div>
                )}
            </div>
        </div>
      </div>

      {showNegotiationModal && (
          <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-black/95 backdrop-blur-md animate-fade-in">
              <div className="bg-[#020617] border border-white/10 rounded-[3rem] w-full max-w-lg shadow-2xl overflow-hidden animate-slide-up relative">
                  <button onClick={() => setShowNegotiationModal(false)} className="absolute top-6 right-6 p-2 text-slate-400 hover:text-white z-10 bg-slate-900 rounded-full"><X className="w-5 h-5" /></button>
                  <div className="p-10 border-b border-white/5 bg-slate-900/40">
                      <h3 className="text-3xl font-black text-white flex items-center gap-3 uppercase tracking-tighter"><Zap className="w-8 h-8 text-indigo-400 fill-indigo-400" />Uplink Script</h3>
                      <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest mt-1">Optimization protocol for {scriptMerchant}</p>
                  </div>
                  <div className="p-10">
                      {isNegotiating ? (
                          <div className="py-10 flex flex-col items-center justify-center gap-6">
                              <Loader2 className="w-12 h-12 text-indigo-500 animate-spin" />
                              <p className="text-indigo-400 font-black uppercase tracking-[0.3em] text-xs animate-pulse">Running analysis...</p>
                          </div>
                      ) : (
                          <div className="animate-fade-in">
                               <div className="bg-slate-950/80 rounded-2xl p-8 border border-white/5 text-slate-300 font-bold leading-relaxed italic text-sm mb-8 max-h-52 overflow-y-auto custom-scrollbar shadow-inner">
                                    "{script}"
                               </div>
                               <button 
                                    onClick={handleCopyScript}
                                    className="w-full py-5 bg-white text-indigo-950 font-black uppercase tracking-[0.2em] text-xs rounded-2xl transition-all shadow-xl flex items-center justify-center gap-3 active:scale-95 hover:bg-indigo-50"
                               >
                                    {copySuccess ? <Check className="w-5 h-5" /> : <Copy className="w-5 h-5" />}
                                    {copySuccess ? 'Copied to Ledger' : 'Copy to Clipboard'}
                               </button>
                          </div>
                      )}
                  </div>
              </div>
          </div>
      )}
    </div>
  );
};

const StatCard: React.FC<{ title: string, value: string | React.ReactNode, icon: React.ReactNode, change?: string, positive?: boolean, delay: string }> = ({ title, value, icon, change, positive, delay }) => (
    <div className="spotlight-card glass-card p-8 rounded-[2.5rem] border border-white/5 hover:border-white/15 transition-all shadow-lg group animate-slide-up" style={{ animationDelay: delay }}>
        <div className="flex justify-between items-start mb-6 relative z-10">
            <div className="p-4 bg-slate-800 rounded-2xl border border-white/5 text-slate-400 group-hover:text-indigo-400 transition-colors group-hover:scale-110 duration-300 shadow-inner">{icon}</div>
            {change && (
                <div className={`flex items-center gap-1 text-[11px] font-black uppercase tracking-widest ${positive ? 'text-emerald-500' : 'text-rose-500'}`}>
                    {positive ? <ArrowUpRight className="w-4 h-4" /> : <ArrowDownRight className="w-4 h-4" />}
                    {change}
                </div>
            )}
        </div>
        <div className="relative z-10">
            <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-[0.3em] mb-1">{title}</h4>
            <div className="text-3xl font-black text-white tracking-tighter">{value}</div>
        </div>
    </div>
);

export default Dashboard;

import React, { useMemo, useState, useRef, useEffect } from 'react';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import { Account, Transaction, TransactionType, Category, UserPlan, Goal } from '../types';
import { Activity, Flame, TrendingUp, Wallet, PlusCircle, CreditCard, Target, Quote, Landmark, Zap, Radio, Repeat, Check, Handshake, Copy, X, Loader2, Sparkles, ArrowUpRight, ArrowDownRight, LayoutGrid, ArrowRight } from 'lucide-react';
import { generateNegotiationScript } from '../services/geminiService';

interface DashboardProps {
  accounts: Account[];
  transactions: Transaction[];
  goals: Goal[];
  onNavigate: (tab: string) => void;
  onAddAccount?: () => void;
  onAddTransaction?: () => void;
  onAddGoal?: () => void;
  formatCurrency: (amount: number) => string | React.ReactNode;
  userPlan?: UserPlan;
  onAskCoach?: (message: string) => void;
  negotiationUsage: number;
  onIncrementNegotiation: () => void;
}

const QUOTES = [
  { text: "Do not save what is left after spending, but spend what is left after saving.", author: "Warren Buffett" },
  { text: "A budget is telling your money where to go instead of wondering where it went.", author: "Dave Ramsey" },
  { text: "It's not your salary that makes you rich, it's your spending habits.", author: "Charles A. Jaffe" },
];

const Dashboard: React.FC<DashboardProps> = ({ accounts, transactions, goals, onNavigate, onAddAccount, onAddTransaction, onAddGoal, formatCurrency, userPlan, onAskCoach, negotiationUsage, onIncrementNegotiation }) => {
  const hasData = accounts.length > 0 || transactions.length > 0;
  const randomQuote = useMemo(() => QUOTES[Math.floor(Math.random() * QUOTES.length)], []);
  const netWorth = useMemo(() => accounts.reduce((acc, curr) => acc + curr.balance, 0), [accounts]);

  const [isNegotiating, setIsNegotiating] = useState(false);
  const [script, setScript] = useState<string | null>(null);
  const [scriptMerchant, setScriptMerchant] = useState('');
  const [showNegotiationModal, setShowNegotiationModal] = useState(false);
  const [copySuccess, setCopySuccess] = useState(false);
  const dashboardRef = useRef<HTMLDivElement>(null);

  // Spotlight Effect Logic
  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      if (!dashboardRef.current) return;
      const cards = dashboardRef.current.getElementsByClassName('spotlight-card');
      for (const card of cards as any) {
        const rect = card.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const y = e.clientY - rect.top;
        card.style.setProperty('--mouse-x', `${x}px`);
        card.style.setProperty('--mouse-y', `${y}px`);
      }
    };
    window.addEventListener('mousemove', handleMouseMove);
    return () => window.removeEventListener('mousemove', handleMouseMove);
  }, [hasData]);

  // Time & Comparison Logic
  const today = new Date();
  const currentMonth = today.getMonth();
  const currentYear = today.getFullYear();
  const currentDay = today.getDate();
  const daysInMonth = new Date(currentYear, currentMonth + 1, 0).getDate();

  const prevMonthDate = new Date(currentYear, currentMonth - 1, 1);
  const prevMonth = prevMonthDate.getMonth();
  const prevMonthYear = prevMonthDate.getFullYear();
  const daysInPrevMonth = new Date(prevMonthYear, prevMonth + 1, 0).getDate();

  // Advanced Statistics Logic
  const stats = useMemo(() => {
    const currentMTDExpenses = transactions.filter(t => {
      const d = new Date(t.date);
      return t.type === TransactionType.EXPENSE && d.getMonth() === currentMonth && d.getFullYear() === currentYear;
    });
    const currentMTDTotal = currentMTDExpenses.reduce((acc, t) => acc + t.amount, 0);

    const prevMTDExpenses = transactions.filter(t => {
      const d = new Date(t.date);
      return t.type === TransactionType.EXPENSE && d.getMonth() === prevMonth && d.getFullYear() === prevMonthYear && d.getDate() <= currentDay;
    });
    const prevMTDTotal = prevMTDExpenses.reduce((acc, t) => acc + t.amount, 0);
    const spendChange = prevMTDTotal > 0 ? ((currentMTDTotal - prevMTDTotal) / prevMTDTotal) * 100 : 0;

    const mtdNetFlow = transactions
      .filter(t => {
        const d = new Date(t.date);
        return d.getMonth() === currentMonth && d.getFullYear() === currentYear;
      })
      .reduce((acc, t) => acc + (t.type === TransactionType.INCOME ? t.amount : -t.amount), 0);
    const monthStartNW = netWorth - mtdNetFlow;
    const nwChange = monthStartNW !== 0 ? (mtdNetFlow / Math.abs(monthStartNW)) * 100 : 0;

    const currentDailyAvg = currentMTDTotal / Math.max(currentDay, 1);
    const prevFullMonthExpenses = transactions.filter(t => {
      const d = new Date(t.date);
      return t.type === TransactionType.EXPENSE && d.getMonth() === prevMonth && d.getFullYear() === prevMonthYear;
    });
    const prevFullMonthTotal = prevFullMonthExpenses.reduce((acc, t) => acc + t.amount, 0);
    const prevDailyAvg = prevFullMonthTotal / Math.max(daysInPrevMonth, 1);
    const burnChange = prevDailyAvg > 0 ? ((currentDailyAvg - prevDailyAvg) / prevDailyAvg) * 100 : 0;

    const forecastedTotal = currentDailyAvg * daysInMonth;
    const forecastChange = prevFullMonthTotal > 0 ? ((forecastedTotal - prevFullMonthTotal) / prevFullMonthTotal) * 100 : 0;

    return {
      currentMTDTotal,
      spendChange,
      nwChange,
      currentDailyAvg,
      burnChange,
      forecastedTotal,
      forecastChange
    };
  }, [transactions, currentMonth, currentYear, prevMonth, prevMonthYear, currentDay, netWorth, daysInMonth, daysInPrevMonth]);

  // System Insight Logic (Real Findings)
  const systemInsight = useMemo(() => {
    if (transactions.length === 0) return "Awaiting transaction data for neural audit...";

    // Check for high spend categories
    const categoryTotals = transactions
        .filter(t => t.type === TransactionType.EXPENSE && new Date(t.date).getMonth() === currentMonth)
        .reduce((acc, t) => {
            acc[t.category] = (acc[t.category] || 0) + t.amount;
            return acc;
        }, {} as Record<string, number>);

    const topCategory = Object.entries(categoryTotals).sort((a,b) => (b[1] as number) - (a[1] as number))[0];

    if (stats.spendChange > 10) {
        return `Expense velocity is up ${stats.spendChange.toFixed(0)}% vs last month. Nova suggests an audit of ${topCategory ? topCategory[0] : 'recent'} spending.`;
    } else if (stats.spendChange < -5) {
        return `Exceptional efficiency! You are spending ${Math.abs(stats.spendChange).toFixed(0)}% less than last month. Savings buffer is expanding.`;
    } else if (netWorth > 10000 && stats.nwChange > 0) {
        return `Capital trajectory is positive. Consider deploying surplus to high-yield goals for 7-10% estimated ghost yield.`;
    }
    return `System running within normal parameters. Currently tracking ${transactions.length} active ledger nodes.`;
  }, [transactions, stats, currentMonth, netWorth]);

  const recurringData = useMemo(() => {
      const merchantMap = new Map<string, { count: number; total: number; amounts: number[]; categories: Set<Category>; }>();
      transactions.filter(t => t.type === TransactionType.EXPENSE).forEach(t => {
            const key = t.merchant.toLowerCase().trim();
            const existing = merchantMap.get(key) || { count: 0, total: 0, amounts: [], categories: new Set() };
            existing.count++;
            existing.total += t.amount;
            existing.amounts.push(t.amount);
            existing.categories.add(t.category);
            merchantMap.set(key, existing);
        });

      const items: { merchant: string; avgCost: number; isSubscription: boolean }[] = [];
      merchantMap.forEach((data, key) => {
          const avg = data.total / data.count;
          const isConsistent = data.amounts.every(a => Math.abs(a - avg) / (avg || 1) < 0.25);
          if (data.categories.has(Category.SUBSCRIPTION) || (data.count > 1 && isConsistent)) {
              items.push({ merchant: key, avgCost: avg, isSubscription: data.categories.has(Category.SUBSCRIPTION) });
          }
      });
      return items.sort((a,b) => b.avgCost - a.avgCost).slice(0, 4);
  }, [transactions]);

  const spendingData = useMemo(() => {
    const dataPoints: { date: string, actual: number | null, predicted: number | null }[] = [];
    const expenseMap = new Map<string, number>();

    transactions.filter(t => t.type === TransactionType.EXPENSE).forEach(t => {
        const d = new Date(t.date);
        d.setHours(0, 0, 0, 0);
        const key = d.toDateString();
        expenseMap.set(key, (expenseMap.get(key) || 0) + t.amount);
    });

    for (let i = 0; i <= 30; i++) {
        const d = new Date(today);
        d.setDate(today.getDate() - (30 - i));
        d.setHours(0, 0, 0, 0);
        dataPoints.push({
            date: d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }),
            actual: expenseMap.get(d.toDateString()) || 0,
            predicted: null
        });
    }

    const last = dataPoints[dataPoints.length - 1];
    last.predicted = last.actual;

    for (let i = 1; i <= 7; i++) {
        const d = new Date(today);
        d.setDate(today.getDate() + i);
        dataPoints.push({
            date: d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }),
            actual: null,
            predicted: stats.currentDailyAvg * (1 + (Math.sin(i) * 0.1))
        });
    }
    return dataPoints;
  }, [transactions, stats.currentDailyAvg, today]);

  const handleNegotiateClick = async (merchant: string, amount: number) => {
      const limit = userPlan === 'ultra' ? Infinity : userPlan === 'pro' ? 5 : 3;
      if (negotiationUsage >= limit) {
          onNavigate('plans');
          return; 
      }
      setIsNegotiating(true);
      setScriptMerchant(merchant);
      setShowNegotiationModal(true);
      const generated = await generateNegotiationScript(merchant, amount);
      setScript(generated);
      setIsNegotiating(false);
      onIncrementNegotiation();
  };

  const handleCopyScript = () => {
      if (script) {
          navigator.clipboard.writeText(script);
          setCopySuccess(true);
          setTimeout(() => setCopySuccess(false), 2000);
      }
  };

  if (!hasData) {
     return (
