        const item = localStorage.getItem(key);
        if (!item) return 0;
        const parsed = JSON.parse(item);
        const now = new Date();
        if (parsed.month !== now.getMonth() || parsed.year !== now.getFullYear()) {
            return 0;
        }
        return parsed.count || 0;
    } catch (e) {
        return 0;
    }
};

const safeSetItem = (key: string, value: string) => {
    try {
        localStorage.setItem(key, value);
    } catch (e) {
        console.warn(`Storage quota exceeded for ${key}`);
    }
};

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isPrivacyMode, setIsPrivacyMode] = useState(() => localStorage.getItem('nova_privacy_mode') === 'true');
  const [isPinMode, setIsPinMode] = useState(false);
  const [pinnedIds, setPinnedIds] = useState<string[]>(() => {
    const saved = localStorage.getItem('nova_pinned_ids');
    return saved ? JSON.parse(saved) : [];
  });

  const [accounts, setAccounts] = useState<Account[]>(() => {
      const saved = localStorage.getItem('nova_accounts');
      return saved ? JSON.parse(saved) : ACCOUNTS;
  });
  const [transactions, setTransactions] = useState<Transaction[]>(() => {
      const saved = localStorage.getItem('nova_transactions');
      return saved ? JSON.parse(saved) : INITIAL_TRANSACTIONS;
  });
  const [budgets, setBudgets] = useState<Budget[]>(() => {
      const saved = localStorage.getItem('nova_budgets');
      return saved ? JSON.parse(saved) : INITIAL_BUDGETS;
  });
  const [goals, setGoals] = useState<Goal[]>(() => {
      const saved = localStorage.getItem('nova_goals');
      return saved ? JSON.parse(saved) : INITIAL_GOALS;
  });

  const [userPlan, setUserPlan] = useState<UserPlan>(() => localStorage.getItem('nova_user_plan') as UserPlan || 'free');
  const [insightUsage, setInsightUsage] = useState(() => getMonthlyUsage('nova_insight_usage'));
  const [scanUsage, setScanUsage] = useState(() => getMonthlyUsage('nova_scan_usage'));
  const [negotiationUsage, setNegotiationUsage] = useState(() => getMonthlyUsage('nova_negotiation_usage'));

  const [isLoggedIn, setIsLoggedIn] = useState(() => localStorage.getItem('nova_auth_token') !== null);
  const [isLogoutModalOpen, setIsLogoutModalOpen] = useState(false);
  const [toasts, setToasts] = useState<ToastMessage[]>([]);
  const [botMode, setBotMode] = useState<BotMode>(() => (localStorage.getItem('nova_bot_mode') as BotMode) || 'ruthless');
  const [pendingChatQuery, setPendingChatQuery] = useState<string | null>(null);

  const [userName, setUserName] = useState(() => localStorage.getItem('nova_user_name') || 'Pilot');
  const [userEmail, setUserEmail] = useState(() => localStorage.getItem('nova_user_email') || 'pilot@nova.io');
  const [userAvatar, setUserAvatar] = useState(() => localStorage.getItem('nova_user_avatar') || '');
  const [userAvatarZoom, setUserAvatarZoom] = useState(1);
  const [userAvatarPos, setUserAvatarPos] = useState({ x: 0, y: 0 });
  const [userBorder, setUserBorder] = useState('default');
  const [userBackground, setUserBackground] = useState(() => localStorage.getItem('nova_user_bg') || '');

  const [currency, setCurrency] = useState<Currency>(() => (localStorage.getItem('nova_currency') as Currency) || 'USD');
  const [language, setLanguage] = useState<Language>(() => (localStorage.getItem('nova_language') as Language) || 'en');

  useEffect(() => safeSetItem('nova_accounts', JSON.stringify(accounts)), [accounts]);
  useEffect(() => safeSetItem('nova_transactions', JSON.stringify(transactions)), [transactions]);
  useEffect(() => safeSetItem('nova_budgets', JSON.stringify(budgets)), [budgets]);
  useEffect(() => safeSetItem('nova_goals', JSON.stringify(goals)), [goals]);
  useEffect(() => safeSetItem('nova_user_plan', userPlan), [userPlan]);
  useEffect(() => safeSetItem('nova_currency', currency), [currency]);
  useEffect(() => safeSetItem('nova_language', language), [language]);
  useEffect(() => safeSetItem('nova_bot_mode', botMode), [botMode]);
  useEffect(() => safeSetItem('nova_privacy_mode', isPrivacyMode.toString()), [isPrivacyMode]);
  useEffect(() => safeSetItem('nova_pinned_ids', JSON.stringify(pinnedIds)), [pinnedIds]);

  useEffect(() => {
      const now = new Date();
      const meta = { month: now.getMonth(), year: now.getFullYear(), count: insightUsage };
      safeSetItem('nova_insight_usage', JSON.stringify(meta));
  }, [insightUsage]);

  useEffect(() => {
      const now = new Date();
      const meta = { month: now.getMonth(), year: now.getFullYear(), count: scanUsage };
      safeSetItem('nova_scan_usage', JSON.stringify(meta));
  }, [scanUsage]);

  useEffect(() => {
      const now = new Date();
      const meta = { month: now.getMonth(), year: now.getFullYear(), count: negotiationUsage };
      safeSetItem('nova_negotiation_usage', JSON.stringify(meta));
  }, [negotiationUsage]);

  useEffect(() => safeSetItem('nova_user_bg', userBackground), [userBackground]);

  const addToast = useCallback((message: string, type: 'success' | 'error' | 'info' = 'info') => {
    setToasts(prev => [...prev, { id: Date.now().toString(), message, type }]);
  }, []);

  const handleToggleStealth = () => {
    if (userPlan !== 'ultra') {
        addToast('Stealth Protocol is an Elite-exclusive feature.', 'info');
        setActiveTab('plans');
        return;
    }
    setIsPrivacyMode(prev => !prev);
    addToast(`Stealth Protocol ${!isPrivacyMode ? 'Engaged' : 'Disengaged'}`, 'info');
  };

  // Shortcut Key Listener: Ctrl+I (Pin Mode), Esc (Exit Mode)
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
        // Toggle Pin Mode: Ctrl + I
        if (e.ctrlKey && e.key.toLowerCase() === 'i') {
            e.preventDefault();
            setIsPinMode(prev => !prev);
            if (!isPinMode) {
              addToast('Pin Selection Mode Engaged', 'info');
              // Auto-navigate to dashboard to facilitate pinning
              setActiveTab('dashboard');
            }
        }
        // Exit Mode: Esc
        if (e.key === 'Escape' && isPinMode) {
            setIsPinMode(false);
            addToast('Exited Pin Mode', 'info');
        }
        // Toggle Stealth: Shift + P
        if (e.shiftKey && e.key.toLowerCase() === 'p') {
            handleToggleStealth();
        }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isPinMode, userPlan, isPrivacyMode, addToast]);

  const removeToast = (id: string) => {
    setToasts(prev => prev.filter(t => t.id !== id));
  };

  const handleTogglePin = (id: string) => {
    setPinnedIds(prev => {
        if (prev.includes(id)) {
            return prev.filter(p => p !== id);
        }
        if (prev.length >= 3) {
            // Replace oldest if already 3
            addToast('Max 3 pins reached. Replacing oldest.', 'info');
            return [...prev.slice(1), id];
        }
        return [...prev, id];
    });
  };

  const formatCurrency = (amount: number) => {
    const isNoDecimal = currency === 'VND' || currency === 'JPY';
    const val = new Intl.NumberFormat(language === 'vi' ? 'vi-VN' : 'en-US', { 
        style: 'currency', 
        currency: currency,
        minimumFractionDigits: isNoDecimal ? 0 : 2,
        maximumFractionDigits: isNoDecimal ? 0 : 2,
    }).format(amount);

    if (isPrivacyMode && userPlan === 'ultra') {
        return (
            <span className="inline-flex items-center gap-0.5">
                {amount < 0 && <span className="text-rose-400 mr-0.5">-</span>}
                <span className="blur-md select-none opacity-40 cursor-default px-1 bg-white/5 rounded-md inline-block" title="Stealth Protocol Active">
                    {val.replace('-', '')}
                </span>
            </span>
        );
    }
    return val;
  };

  const reconcileBalance = (tx: Transaction, direction: 'add' | 'delete') => {
      if (tx.accountId === 'manual') return;
      setAccounts(prev => prev.map(acc => {
          if (acc.id === tx.accountId) {
              const isIncome = tx.type === TransactionType.INCOME;
              let change = tx.amount;
              if (direction === 'add') {
                  change = isIncome ? change : -change;
              } else {
                  change = isIncome ? -change : change;
              }
              return { ...acc, balance: acc.balance + change };
          }
          return acc;
      }));
  };

  const handleAddTransaction = (t: Transaction) => {
      setTransactions(prev => [t, ...prev]);
      reconcileBalance(t, 'add');
      addToast('Entry archived. Balance synchronized.', 'success');
  };

  const handleDeleteTransaction = (id: string) => {
      const tx = transactions.find(t => t.id === id);
      if (tx) {
          reconcileBalance(tx, 'delete');
          setTransactions(prev => prev.filter(t => t.id !== id));
          addToast('Entry purged. Balance reconciled.', 'info');
      }
  };

  const handleLogin = (name: string) => {
    setIsLoggedIn(true);
    setUserName(name);
    localStorage.setItem('nova_user_name', name);
  };

  const confirmLogout = () => {
    localStorage.removeItem('nova_auth_token');
    setIsLoggedIn(false);
    setIsLogoutModalOpen(false);
  };

  const handleUpdateProfile = (name: string, email: string, avatar: string, zoom: number, pos: { x: number; y: number }, border: string) => {
      setUserName(name);
      localStorage.setItem('nova_user_name', name);
      setUserEmail(email);
      localStorage.setItem('nova_user_email', email);
      setUserAvatar(avatar);
      safeSetItem('nova_user_avatar', avatar);
      setUserAvatarZoom(zoom);
      setUserAvatarPos(pos);
      setUserBorder(border);
  };

  const handleAskCoach = (msg: string) => {
      setPendingChatQuery(msg);
      setActiveTab('insights');
  };

  const handleExportData = () => {
    const data = { accounts, transactions, budgets, goals, userPlan, insightUsage, scanUsage, negotiationUsage, userName, userEmail, userAvatar, userAvatarZoom, userAvatarPos, userBorder, userBackground, currency, language, botMode };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `nova_backup_${new Date().toISOString().split('T')[0]}.json`;
    link.click();
    addToast('Vault exported successfully.', 'success');
  };

  const handleImportData = (file: File) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = JSON.parse(e.target?.result as string);
        if (data.accounts) setAccounts(data.accounts);
        if (data.transactions) setTransactions(data.transactions);
        if (data.budgets) setBudgets(data.budgets);
        if (data.goals) setGoals(data.goals);
        if (data.userPlan) setUserPlan(data.userPlan);
        if (data.userName) setUserName(data.userName);
        if (data.currency) setCurrency(data.currency);
        addToast('Vault restored successfully.', 'success');
      } catch (err) {
        addToast('Failed to parse backup file.', 'error');
      }
    };
    reader.readAsText(file);
  };

  const handleClearData = () => {
    setAccounts(ACCOUNTS); setTransactions(INITIAL_TRANSACTIONS); setBudgets(INITIAL_BUDGETS); setGoals(INITIAL_GOALS);
    setUserPlan('free'); setInsightUsage(0); setScanUsage(0); setNegotiationUsage(0); setBotMode('ruthless');
    setUserName('Pilot'); setUserEmail('pilot@nova.io'); setUserAvatar(''); setUserBackground('');
    setCurrency('USD'); setLanguage('en'); localStorage.clear(); addToast('All data cleared.', 'info');
  };

  const branding = (userPlan === 'ultra' ? {
      icon: <Crown className="w-6 h-6 text-white" />,
      bg: 'bg-gradient-to-tr from-indigo-600 via-purple-600 to-indigo-600',
      label: 'ELITE SYSTEM',
      shadow: 'shadow-indigo-500/40'
  } : userPlan === 'pro' ? {
      icon: <Zap className="w-6 h-6 text-white" />,
      bg: 'bg-gradient-to-tr from-amber-500 to-orange-500',
      label: 'PRO SYSTEM',
      shadow: 'shadow-amber-500/40'
  } : {
      icon: <Sparkles className="w-6 h-6 text-white" />,
      bg: 'bg-gradient-to-tr from-indigo-600 to-violet-600',
      label: 'CORE SYSTEM',
      shadow: 'shadow-indigo-500/20'
  });

  const isApiConfigured = !!process.env.API_KEY;

  if (!isLoggedIn) {
    return <LandingPage onLoginSuccess={handleLogin} />;
  }

  return (
    <div className={`flex h-screen bg-[#020617] text-slate-100 font-sans selection:bg-indigo-500/30 overflow-hidden relative ${isPinMode ? 'cursor-crosshair' : ''}`}>
      {!isApiConfigured && (
          <div className="fixed top-0 left-0 w-full bg-rose-600 text-white text-[10px] font-black py-2 px-4 text-center z-[110] flex items-center justify-center gap-2 shadow-lg uppercase tracking-widest">
              <AlertTriangle className="w-4 h-4" /> AI Core Offline: Missing API Key. Manual tracking active.
          </div>
      )}

      {userBackground && <div className="absolute inset-0 z-0"><img src={userBackground} alt="bg" className="w-full h-full object-cover opacity-40 blur-sm" /><div className="absolute inset-0 bg-[#020617]/70"></div></div>}

      {!userBackground && <div className="fixed inset-0 z-0 pointer-events-none bg-[radial-gradient(at_0%_0%,hsla(253,16%,7%,1)_0,transparent_50%),radial-gradient(at_50%_0%,hsla(225,39%,30%,0.3)_0,transparent_50%),radial-gradient(at_100%_0%,hsla(339,49%,30%,0.3)_0,transparent_50%)]"><div className="absolute top-[-10%] left-[-10%] w-[50%] h-[50%] bg-indigo-900/10 rounded-full blur-[120px] animate-pulse-slow"></div><div className="absolute bottom-[-10%] right-[-10%] w-[50%] h-[50%] bg-purple-900/10 rounded-full blur-[120px] animate-pulse-slow" style={{ animationDelay: '1s' }}></div></div>}

      <FloatingAssistant transactions={transactions} budgets={budgets} userPlan={userPlan} botMode={botMode} isVisible={activeTab !== 'insights'} onOpenChat={handleAskCoach} insightUsage={insightUsage} />

      <aside className="hidden md:flex flex-col w-64 p-4 pb-8 z-20 bg-slate-950/40 backdrop-blur-md border-r border-white/5 relative">
        <div className="flex items-center gap-3 px-4 py-3 mb-8 shrink-0">
            <div className={`w-10 h-10 rounded-xl flex items-center justify-center shadow-lg ring-1 ring-white/10 ${branding.bg} ${branding.shadow}`}>{branding.icon}</div>
            <div><h1 className="text-xl font-bold tracking-tight text-white">Nova AI</h1><p className={`text-[10px] font-bold uppercase tracking-wider ${userPlan === 'ultra' ? 'text-purple-400' : userPlan === 'pro' ? 'text-amber-400' : 'text-slate-500'}`}>{branding.label}</p></div>
        </div>
        <nav className="flex-1 space-y-1 overflow-y-auto custom-scrollbar pr-1">
            {NAV_ITEMS.map((item) => {
                const isActive = activeTab === item.id;
                const label = TRANSLATIONS[language]?.[item.id as keyof typeof TRANSLATIONS['en']] || item.label;
                return (
                    <button key={item.id} onClick={() => setActiveTab(item.id)} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold transition-all duration-300 group ${isActive ? 'bg-indigo-600/10 text-indigo-400 shadow-[0_0_20px_rgba(99,102,241,0.15)] ring-1 ring-indigo-500/20' : 'text-slate-400 hover:text-white hover:bg-white/5'}`}>
                        <item.icon className={`w-5 h-5 transition-colors ${isActive ? 'text-indigo-400' : 'text-slate-500 group-hover:text-white'}`} />{label}
                    </button>
                );
            })}
        </nav>
        <div className="mt-auto pt-6 border-t border-white/5 shrink-0">
             <button 
                onClick={handleToggleStealth} 
                className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all mb-2 ${isPrivacyMode && userPlan === 'ultra' ? 'bg-indigo-500/20 text-indigo-400 border border-indigo-500/30' : 'text-slate-500 hover:text-slate-300 hover:bg-white/5'}`}
                title="Toggle Stealth Protocol (Shift+P)"
             >
                {userPlan !== 'ultra' ? <Lock className="w-5 h-5 text-slate-700" /> : isPrivacyMode ? <EyeOff className="w-5 h-5" /> : <Shield className="w-5 h-5" />}
                {isPrivacyMode && userPlan === 'ultra' ? 'Stealth Engaged' : 'Stealth Protocol'}
             </button>

             <button onClick={() => setActiveTab('settings')} className="w-full text-left px-4 py-4 rounded-2xl bg-slate-900/50 border border-white/5 flex items-center gap-3 mb-4 hover:bg-slate-800 transition-colors group">
                 <div className="w-10 h-10 rounded-full bg-indigo-500 flex items-center justify-center text-white overflow-hidden relative border border-white/10 shadow-inner">{userAvatar ? <img src={userAvatar} className="w-full h-full object-cover" alt="User" style={{ transform: `scale(${userAvatarZoom}) translate(${userAvatarPos.x}px, ${userAvatarPos.y}px)` }} /> : <span className="font-bold text-lg">{userName.charAt(0)}</span>}</div>
                 <div className="overflow-hidden"><h4 className="font-bold text-white text-sm truncate group-hover:text-indigo-400 transition-colors">{userName}</h4><p className="text-[10px] text-slate-500 truncate font-bold uppercase tracking-widest">{userPlan} tier</p></div>
             </button>
             <button onClick={() => setIsLogoutModalOpen(true)} className="w-full flex items-center gap-2 px-4 py-2 mb-4 text-xs font-bold text-slate-500 hover:text-rose-400 transition-colors uppercase tracking-widest">
                 <LogOut className="w-4 h-4" /> {TRANSLATIONS[language]?.signOut || 'Sign Out'}
             </button>
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 z-10 relative overflow-hidden">
        {isPinMode && (
          <div className="absolute inset-0 z-[100] bg-black/40 backdrop-blur-[2px] pointer-events-none flex flex-col items-center justify-start pt-20">
              <div className="bg-indigo-600/90 text-white font-black text-xs uppercase tracking-[0.3em] px-8 py-4 rounded-2xl shadow-[0_0_50px_rgba(99,102,241,0.5)] border border-indigo-400/50 animate-pulse pointer-events-auto">
                  Pin Selection Mode Active :: Max 3 Nodes :: Esc to Exit
              </div>
          </div>
        )}

        <div className="flex-1 overflow-y-auto p-4 md:p-8 pb-24 md:pb-8 custom-scrollbar">
            {activeTab === 'dashboard' && <Dashboard accounts={accounts} transactions={transactions} goals={goals} onNavigate={setActiveTab} onAddAccount={() => setActiveTab('accounts')} onAddTransaction={() => setActiveTab('transactions')} onAddGoal={() => setActiveTab('goals')} formatCurrency={formatCurrency} userPlan={userPlan} onAskCoach={handleAskCoach} negotiationUsage={negotiationUsage} onIncrementNegotiation={() => setNegotiationUsage(prev => prev + 1)} isPinMode={isPinMode} pinnedIds={pinnedIds} onTogglePin={handleTogglePin} />}
            {activeTab === 'transactions' && <Transactions transactions={transactions} accounts={accounts} onDelete={handleDeleteTransaction} onAdd={handleAddTransaction} formatCurrency={formatCurrency} onNavigateToAccounts={() => setActiveTab('accounts')} userPlan={userPlan} scanUsage={scanUsage} onIncrementScan={() => setScanUsage(prev => prev + 1)} currency={currency} />}
            {activeTab === 'accounts' && <Accounts accounts={accounts} budgets={budgets} transactions={transactions} userPlan={userPlan} onAdd={(acc) => { setAccounts(prev => [...prev, acc]); addToast('Account bridged.', 'success'); }} onUpdate={(acc) => { setAccounts(prev => prev.map(a => a.id === acc.id ? acc : a)); addToast('Account updated.', 'success'); }} onDelete={(id) => { setAccounts(prev => prev.filter(a => a.id !== id)); setTransactions(prev => prev.map(t => t.accountId === id ? { ...t, accountId: 'manual' } : t)); addToast('Account disconnected. History preserved.', 'info'); }} formatCurrency={formatCurrency} userName={userName} userAvatar={userAvatar} userAvatarZoom={userAvatarZoom} userAvatarPos={userAvatarPos} userBorder={userBorder} onNavigate={setActiveTab} />}
            {activeTab === 'cashflow' && <CashflowBeta transactions={transactions} accounts={accounts} goals={goals} formatCurrency={formatCurrency} userPlan={userPlan} />}
            {activeTab === 'insights' && <Insights transactions={transactions} userPlan={userPlan} onUpgradeClick={() => setActiveTab('plans')} formatCurrency={formatCurrency} insightUsage={insightUsage} onIncrementUsage={(val) => setInsightUsage(prev => prev + (val || 1))} onApplyBudgets={(newBudgets) => { const existingCats = new Set(budgets.map(b => b.category)); const toAdd = newBudgets.filter(b => !existingCats.has(b.category)); setBudgets(prev => [...prev, ...toAdd]); addToast(`Applied ${toAdd.length} AI limits.`, 'success'); }} initialPrompt={pendingChatQuery} onPromptHandled={() => setPendingChatQuery(null)} botMode={botMode} />}
            {activeTab === 'sandbox' && <ScenarioSandbox transactions={transactions} goals={goals} formatCurrency={formatCurrency} userPlan={userPlan} onUpgradeClick={() => setActiveTab('plans')} insightUsage={insightUsage} onIncrementUsage={(val) => setInsightUsage(prev => prev + (val || 1))} />}
            {activeTab === 'goals' && <Goals goals={goals} budgets={budgets} transactions={transactions} onAddGoal={(g) => { setGoals(prev => [...prev, g]); addToast('Goal deployed.', 'success'); }} onUpdateGoal={(g) => { setGoals(prev => prev.map(goal => goal.id === g.id ? g : goal)); addToast('Goal updated.', 'success'); }} onAddBudget={(b) => { setBudgets(prev => [...prev, b]); addToast('Limit set.', 'success'); }} onDeleteBudget={(id) => { setBudgets(prev => prev.filter(b => b.id !== id)); addToast('Limit removed.', 'info'); }} formatCurrency={formatCurrency} />}
            {activeTab === 'plans' && <Plans currentPlan={userPlan} onUpgrade={(plan) => { setUserPlan(plan); addToast(`Plan upgraded to ${plan.toUpperCase()}.`, 'success'); }} onDowngrade={() => { setUserPlan('free'); addToast('Plan reset to Starter.', 'info'); }} onNavigateDashboard={() => setActiveTab('dashboard')} />}
            {activeTab === 'upcoming' && <UpcomingFeatures />}
            {activeTab === 'settings' && <Settings userName={userName} userEmail={userEmail} userAvatar={userAvatar} userAvatarZoom={userAvatarZoom} userAvatarPos={userAvatarPos} userBorder={userBorder} userBackground={userBackground} onUpdateBackground={setUserBackground} userPlan={userPlan} onUpdateProfile={handleUpdateProfile} addToast={addToast} onExportData={handleExportData} onImportData={handleImportData} onClearData={handleClearData} language={language} onUpdateLanguage={setLanguage} currency={currency} onUpdateCurrency={setCurrency} botMode={botMode} onUpdateBotMode={setBotMode} onDowngrade={() => { setUserPlan('free'); addToast('Plan downgraded.', 'info'); }} />}
        </div>
      </main>

      {isLogoutModalOpen && (
          <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/95 backdrop-blur-2xl animate-fade-in">
              <div className="bg-[#0f172a] border border-rose-500/30 rounded-[3rem] w-full max-sm shadow-[0_0_100px_rgba(244,63,94,0.2)] overflow-hidden animate-slide-up relative text-center p-10">
                  <div className="w-20 h-20 bg-rose-500/20 rounded-[2rem] flex items-center justify-center mx-auto mb-8 border border-rose-500/30">
                      <ShieldX className="w-10 h-10 text-rose-500" />
                  </div>
                  <h3 className="text-2xl font-black text-white mb-3 uppercase tracking-tighter">Terminate Protocol?</h3>
                  <p className="text-slate-400 text-sm mb-10 leading-relaxed">Disconnecting the vault will restrict AI logic and local archival syncing. Are you sure you want to end this session?</p>
                  <div className="space-y-4">
                      <button onClick={confirmLogout} className="w-full py-4 bg-rose-600 hover:bg-rose-500 text-white font-black rounded-2xl shadow-xl transition-all active:scale-95 flex items-center justify-center gap-3 group">
                         End Session <ArrowRight className="w-5 h-5 group-hover:translate-x-1 transition-transform" />
                      </button>
                      <button onClick={() => setIsLogoutModalOpen(false)} className="w-full py-4 bg-slate-900/50 text-slate-400 font-bold rounded-2xl border border-white/5 hover:text-white transition-all">
                         Stay Connected
                      </button>
                  </div>
              </div>
          </div>
      )}

      <ToastContainer toasts={toasts} onRemove={removeToast} />
    </div>
  );
};

export default App;

import React, { useMemo, useState, useRef, useEffect } from 'react';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import { Account, Transaction, TransactionType, Category, UserPlan, Goal } from '../types';
import { Activity, Flame, TrendingUp, Wallet, PlusCircle, CreditCard, Target, Quote, Landmark, Zap, Radio, Repeat, Check, Handshake, Copy, X, Loader2, Sparkles, ArrowUpRight, ArrowDownRight, LayoutGrid, ArrowRight, Pin } from 'lucide-react';
import { generateNegotiationScript } from '../services/geminiService';

interface DashboardProps {
  accounts: Account[];
  transactions: Transaction[];
  goals: Goal[];
  onNavigate: (tab: string) => void;
  onAddAccount?: () => void;
  onAddTransaction?: () => void;
  onAddGoal?: () => void;
  formatCurrency: (amount: number) => string | React.ReactNode;
  userPlan?: UserPlan;
  onAskCoach?: (message: string) => void;
  negotiationUsage: number;
  onIncrementNegotiation: () => void;
  isPinMode?: boolean;
  pinnedIds?: string[];
  onTogglePin?: (id: string) => void;
}

const QUOTES = [
  { text: "Do not save what is left after spending, but spend what is left after saving.", author: "Warren Buffett" },
  { text: "A budget is telling your money where to go instead of wondering where it went.", author: "Dave Ramsey" },
  { text: "It's not your salary that makes you rich, it's your spending habits.", author: "Charles A. Jaffe" },
];

const Dashboard: React.FC<DashboardProps> = ({ 
    accounts, 
    transactions, 
    goals, 
    onNavigate, 
    onAddAccount, 
    onAddTransaction, 
    onAddGoal, 
    formatCurrency, 
    userPlan, 
    onAskCoach, 
    negotiationUsage, 
    onIncrementNegotiation,
    isPinMode = false,
    pinnedIds = [],
    onTogglePin
}) => {
  const hasData = accounts.length > 0 || transactions.length > 0;
  const randomQuote = useMemo(() => QUOTES[Math.floor(Math.random() * QUOTES.length)], []);
  const netWorth = useMemo(() => accounts.reduce((acc, curr) => acc + curr.balance, 0), [accounts]);

  const [isNegotiating, setIsNegotiating] = useState(false);
  const [script, setScript] = useState<string | null>(null);
  const [scriptMerchant, setScriptMerchant] = useState('');
  const [showNegotiationModal, setShowNegotiationModal] = useState(false);
  const [copySuccess, setCopySuccess] = useState(false);
  const dashboardRef = useRef<HTMLDivElement>(null);

  // Spotlight Effect Logic
  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      if (!dashboardRef.current) return;
      const cards = dashboardRef.current.getElementsByClassName('spotlight-card');
      for (const card of cards as any) {
        const rect = card.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const y = e.clientY - rect.top;
        card.style.setProperty('--mouse-x', `${x}px`);
        card.style.setProperty('--mouse-y', `${y}px`);
      }
    };
    window.addEventListener('mousemove', handleMouseMove);
    return () => window.removeEventListener('mousemove', handleMouseMove);
  }, [hasData]);

  // Time & Comparison Logic
  const today = new Date();
  const currentMonth = today.getMonth();
  const currentYear = today.getFullYear();
  const currentDay = today.getDate();
  const daysInMonth = new Date(currentYear, currentMonth + 1, 0).getDate();

  const prevMonthDate = new Date(currentYear, currentMonth - 1, 1);
  const prevMonth = prevMonthDate.getMonth();
  const prevMonthYear = prevMonthDate.getFullYear();
  const daysInPrevMonth = new Date(prevMonthYear, prevMonth + 1, 0).getDate();

  // Advanced Statistics Logic
  const stats = useMemo(() => {
    const currentMTDExpenses = transactions.filter(t => {
      const d = new Date(t.date);
      return t.type === TransactionType.EXPENSE && d.getMonth() === currentMonth && d.getFullYear() === currentYear;
    });
    const currentMTDTotal = currentMTDExpenses.reduce((acc, t) => acc + t.amount, 0);

    const prevMTDExpenses = transactions.filter(t => {
      const d = new Date(t.date);
      return t.type === TransactionType.EXPENSE && d.getMonth() === prevMonth && d.getFullYear() === prevMonthYear && d.getDate() <= currentDay;
    });
    const prevMTDTotal = prevMTDExpenses.reduce((acc, t) => acc + t.amount, 0);
    const spendChange = prevMTDTotal > 0 ? ((currentMTDTotal - prevMTDTotal) / prevMTDTotal) * 100 : 0;

    const mtdNetFlow = transactions
      .filter(t => {
        const d = new Date(t.date);
        return d.getMonth() === currentMonth && d.getFullYear() === currentYear;
      })
      .reduce((acc, t) => acc + (t.type === TransactionType.INCOME ? t.amount : -t.amount), 0);
    const monthStartNW = netWorth - mtdNetFlow;
    const nwChange = monthStartNW !== 0 ? (mtdNetFlow / Math.abs(monthStartNW)) * 100 : 0;

    const currentDailyAvg = currentMTDTotal / Math.max(currentDay, 1);
    const prevFullMonthExpenses = transactions.filter(t => {
      const d = new Date(t.date);
      return t.type === TransactionType.EXPENSE && d.getMonth() === prevMonth && d.getFullYear() === prevMonthYear;
    });
    const prevFullMonthTotal = prevFullMonthExpenses.reduce((acc, t) => acc + t.amount, 0);
    const prevDailyAvg = prevFullMonthTotal / Math.max(daysInPrevMonth, 1);
    const burnChange = prevDailyAvg > 0 ? ((currentDailyAvg - prevDailyAvg) / prevDailyAvg) * 100 : 0;

    const forecastedTotal = currentDailyAvg * daysInMonth;
    const forecastChange = prevFullMonthTotal > 0 ? ((forecastedTotal - prevFullMonthTotal) / prevFullMonthTotal) * 100 : 0;

    return {
      currentMTDTotal,
      spendChange,
      nwChange,
      currentDailyAvg,
      burnChange,
      forecastedTotal,
      forecastChange
    };
  }, [transactions, currentMonth, currentYear, prevMonth, prevMonthYear, currentDay, netWorth, daysInMonth, daysInPrevMonth]);

  // System Insight Logic (Real Findings)
  const systemInsight = useMemo(() => {
    if (transactions.length === 0) return "Awaiting transaction data for neural audit...";

    // Check for high spend categories
    const categoryTotals = transactions
        .filter(t => t.type === TransactionType.EXPENSE && new Date(t.date).getMonth() === currentMonth)
        .reduce((acc, t) => {
            acc[t.category] = (acc[t.category] || 0) + t.amount;
            return acc;
        }, {} as Record<string, number>);

    const topCategory = Object.entries(categoryTotals).sort((a,b) => (b[1] as number) - (a[1] as number))[0];

    if (stats.spendChange > 10) {
        return `Expense velocity is up ${stats.spendChange.toFixed(0)}% vs last month. Nova suggests an audit of ${topCategory ? topCategory[0] : 'recent'} spending.`;
    } else if (stats.spendChange < -5) {
        return `Exceptional efficiency! You are spending ${Math.abs(stats.spendChange).toFixed(0)}% less than last month. Savings buffer is expanding.`;
    } else if (netWorth > 10000 && stats.nwChange > 0) {
        return `Capital trajectory is positive. Consider deploying surplus to high-yield goals for 7-10% estimated ghost yield.`;
    }
    return `System running within normal parameters. Currently tracking ${transactions.length} active ledger nodes.`;
  }, [transactions, stats, currentMonth, netWorth]);

  const recurringData = useMemo(() => {
      const merchantMap = new Map<string, { count: number; total: number; amounts: number[]; categories: Set<Category>; }>();
      transactions.filter(t => t.type === TransactionType.EXPENSE).forEach(t => {
            const key = t.merchant.toLowerCase().trim();
            const existing = merchantMap.get(key) || { count: 0, total: 0, amounts: [], categories: new Set() };
            existing.count++;
            existing.total += t.amount;
            existing.amounts.push(t.amount);
            existing.categories.add(t.category);
            merchantMap.set(key, existing);
        });

      const items: { merchant: string; avgCost: number; isSubscription: boolean }[] = [];
      merchantMap.forEach((data, key) => {
          const avg = data.total / data.count;
          const isConsistent = data.amounts.every(a => Math.abs(a - avg) / (avg || 1) < 0.25);
          if (data.categories.has(Category.SUBSCRIPTION) || (data.count > 1 && isConsistent)) {
              items.push({ merchant: key, avgCost: avg, isSubscription: data.categories.has(Category.SUBSCRIPTION) });
          }
      });
      return items.sort((a,b) => b.avgCost - a.avgCost).slice(0, 4);
  }, [transactions]);

  const spendingData = useMemo(() => {
    const dataPoints: { date: string, actual: number | null, predicted: number | null }[] = [];
    const expenseMap = new Map<string, number>();

    transactions.filter(t => t.type === TransactionType.EXPENSE).forEach(t => {
        const d = new Date(t.date);
        d.setHours(0, 0, 0, 0);
        const key = d.toDateString();
        expenseMap.set(key, (expenseMap.get(key) || 0) + t.amount);
    });

    for (let i = 0; i <= 30; i++) {
        const d = new Date(today);
        d.setDate(today.getDate() - (30 - i));
        d.setHours(0, 0, 0, 0);
        dataPoints.push({
            date: d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }),
            actual: expenseMap.get(d.toDateString()) || 0,
            predicted: null
        });
    }

    const last = dataPoints[dataPoints.length - 1];
    last.predicted = last.actual;

    for (let i = 1; i <= 7; i++) {
        const d = new Date(today);
        d.setDate(today.getDate() + i);
        d.setHours(0, 0, 0, 0);
        dataPoints.push({
            date: d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }),
            actual: null,
            predicted: stats.currentDailyAvg * (1 + (Math.sin(i) * 0.1))
        });
    }
    return dataPoints;
  }, [transactions, stats.currentDailyAvg, today]);

  const handleNegotiateClick = async (merchant: string, amount: number) => {
      const limit = userPlan === 'ultra' ? Infinity : userPlan === 'pro' ? 5 : 3;
      if (negotiationUsage >= limit) {
          onNavigate('plans');
          return; 
      }
      setIsNegotiating(true);
      setScriptMerchant(merchant);
      setShowNegotiationModal(true);
      const generated = await generateNegotiationScript(merchant, amount);
      setScript(generated);
      setIsNegotiating(false);
      onIncrementNegotiation();
  };

  const handleCopyScript = () => {
      if (script) {
          navigator.clipboard.writeText(script);
          setCopySuccess(true);
          setTimeout(() => setCopySuccess(false), 2000);
      }
  };

  if (!hasData) {
     return (
        <div className="flex flex-col items-center justify-center w-full min-h-full py-12 animate-fade-in text-center relative overflow-hidden">
            <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[600px] h-[600px] bg-indigo-500/10 rounded-full blur-[120px] pointer-events-none animate-pulse-slow"></div>
            <div className="max-w-4xl mx-auto mb-12 relative z-10">
                <div className="flex justify-center mb-8">
                    <div className="w-14 h-14 rounded-2xl bg-slate-800 flex items-center justify-center shadow-2xl border border-white/10 rotate-3">
                        <Quote className="w-7 h-7 text-indigo-400 fill-current" />
                    </div>
                </div>
                <h1 className="text-3xl md:text-4xl font-bold text-white tracking-tight mb-4 px-4 uppercase">Initialize Terminal</h1>
                <p className="text-lg text-slate-400 font-medium italic tracking-wide">"{randomQuote.text}" — {randomQuote.author}</p>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6 w-full max-w-5xl relative z-10 px-4">
                 <button onClick={onAddAccount} className="group bg-slate-900 border border-white/5 p-10 rounded-[2.5rem] text-left hover:border-indigo-500/30 transition-all hover:-translate-y-1 shadow-2xl">
                    <div className="w-14 h-14 rounded-2xl bg-indigo-500/10 flex items-center justify-center mb-8 group-hover:scale-110 transition-transform text-indigo-400"><Landmark className="w-7 h-7" /></div>
                    <h3 className="text-xl font-bold text-white mb-3">Bridge Assets</h3>
                    <p className="text-slate-500 text-sm leading-relaxed">Securely link your bank nodes or add manual ledgers to start tracking.</p>
                 </button>
                 <button onClick={onAddTransaction} className="group bg-slate-900 border border-white/5 p-10 rounded-[2.5rem] text-left hover:border-emerald-500/30 transition-all hover:-translate-y-1 shadow-2xl">
                    <div className="w-14 h-14 rounded-2xl bg-emerald-500/10 flex items-center justify-center mb-8 group-hover:scale-110 transition-transform text-emerald-400"><PlusCircle className="w-7 h-7" /></div>
                    <h3 className="text-xl font-bold text-white mb-3">Sync Activity</h3>
                    <p className="text-slate-500 text-sm leading-relaxed">Archive your daily spending to calibrate the AI predictive engine.</p>
                 </button>
                 <button onClick={onAddGoal} className="group bg-slate-900 border border-white/5 p-10 rounded-[2.5rem] text-left hover:border-rose-500/30 transition-all hover:-translate-y-1 shadow-2xl">
                    <div className="w-14 h-14 rounded-2xl bg-rose-500/10 flex items-center justify-center mb-8 group-hover:scale-110 transition-transform text-rose-400"><Target className="w-7 h-7" /></div>
                    <h3 className="text-xl font-bold text-white mb-3">Set Objectives</h3>
                    <p className="text-slate-500 text-sm leading-relaxed">Establish savings targets and let Nova optimize your trajectory.</p>
                 </button>
            </div>
        </div>
     );
  }

  const pinnedItems = pinnedIds.map(id => {
    switch (id) {
        case 'net-worth': return { id, label: 'Net Worth', value: formatCurrency(netWorth), icon: <Wallet className="w-4 h-4" /> };
        case 'monthly-spend': return { id, label: 'Spend', value: formatCurrency(stats.currentMTDTotal), icon: <CreditCard className="w-4 h-4" /> };
        case 'burn-rate': return { id, label: 'Daily Burn', value: formatCurrency(stats.currentDailyAvg), icon: <Flame className="w-4 h-4" /> };
        case 'predicted-spend': return { id, label: 'Predicted', value: formatCurrency(stats.forecastedTotal), icon: <TrendingUp className="w-4 h-4" /> };
        default: return null;
    }
  }).filter(Boolean);

  return (
    <div ref={dashboardRef} className="space-y-6 animate-slide-up pb-10">
      <style>{`
        .spotlight-card {
          position: relative;
          overflow: hidden;
        }
        .spotlight-card::before {
          content: "";
          position: absolute;
          inset: 0;
          background: radial-gradient(
            600px circle at var(--mouse-x, 0) var(--mouse-y, 0),
            rgba(99, 102, 241, 0.15),
            transparent 40%
          );
          z-index: 0;
          pointer-events: none;
        }
        .pin-mode-glow {
            box-shadow: 0 0 30px rgba(99, 102, 241, 0.4) !important;
            border-color: rgba(99, 102, 241, 0.6) !important;
            transform: scale(1.02);
            z-index: 101 !important;
        }
      `}</style>

      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 animate-fade-in">
        <div>
          <h2 className="text-3xl font-black text-white tracking-tight uppercase italic">Financial Command</h2>
          <p className="text-slate-400 mt-1 font-bold text-xs uppercase tracking-widest opacity-60">Financial performance for {today.toLocaleDateString('en-US', { month: 'long', year: 'numeric' })}</p>
        </div>
      </div>

      {/* Pinned Cluster Section */}
      {pinnedItems.length > 0 && (
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4 animate-slide-up">
              {pinnedItems.map((item: any, idx) => (
                  <div key={item.id} className="p-4 bg-indigo-600/10 border border-indigo-500/20 rounded-2xl flex items-center justify-between shadow-lg group hover:bg-indigo-600/20 transition-all animate-fade-in" style={{ animationDelay: `${idx * 0.1}s` }}>
                      <div className="flex items-center gap-3">
                          <div className="p-2 bg-indigo-600/20 rounded-xl text-indigo-400">{item.icon}</div>
                          <div>
                              <h4 className="text-[8px] font-black uppercase text-indigo-300 tracking-[0.2em]">{item.label}</h4>
                              <p className="text-sm font-black text-white tracking-tight">{item.value}</p>
                          </div>
                      </div>
                      <Pin className="w-3 h-3 text-indigo-500/40 fill-indigo-500/40" />
                  </div>
              ))}
          </div>
      )}

      {/* Dynamic System Insights positioned exactly as requested */}
      <div 
        onClick={() => isPinMode ? onTogglePin?.('insight') : onNavigate('insights')}
        className={`spotlight-card bg-[#020617] rounded-[2.5rem] p-8 md:p-10 shadow-2xl relative border border-white/10 group cursor-pointer animate-slide-up transition-all ${isPinMode ? 'hover:pin-mode-glow' : ''} ${pinnedIds.includes('insight') ? 'ring-2 ring-indigo-500/50' : ''}`} 
        style={{ animationDelay: '0.1s' }} 
      >
          {isPinMode && (
              <div className="absolute top-4 right-4 z-[105]">
                  <div className={`w-8 h-8 rounded-full flex items-center justify-center border transition-colors ${pinnedIds.includes('insight') ? 'bg-indigo-600 border-white text-white shadow-lg' : 'bg-slate-900 border-white/10 text-slate-600'}`}>
                      <Pin className="w-4 h-4" />
                  </div>
              </div>
          )}
          <div className="flex flex-col md:flex-row justify-between items-center gap-6 relative z-10">
              <div className="flex items-center gap-6">
                  <div className="w-20 h-20 rounded-3xl bg-indigo-600/10 border border-indigo-500/20 flex items-center justify-center shadow-inner group-hover:rotate-6 transition-transform duration-500">
                      <Sparkles className="w-10 h-10 text-indigo-400 animate-pulse" />
                  </div>
                  <div>
                      <h3 className="text-xl font-black text-white uppercase tracking-tighter">Neural System Insight</h3>
                      <p className="text-slate-400 font-medium leading-relaxed max-w-2xl mt-1">{systemInsight}</p>
                  </div>
              </div>
              {!isPinMode && (
                <button className="px-8 py-4 bg-indigo-600 text-white rounded-2xl font-black text-[10px] uppercase tracking-[0.2em] shadow-xl transition-all hover:scale-105 active:scale-95 flex items-center gap-2">
                    Deep Audit <ArrowRight className="w-4 h-4" />
                </button>
              )}
          </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard 
            id="net-worth"
            title="Net Worth" 
            value={formatCurrency(netWorth)} 
            icon={<Wallet className="w-5 h-5 text-indigo-400" />} 
            change={stats.nwChange.toFixed(1) + '%'} 
            positive={stats.nwChange >= 0}
            delay="0.2s"
            isPinMode={isPinMode}
            isPinned={pinnedIds.includes('net-worth')}
            onTogglePin={() => onTogglePin?.('net-worth')}
        />
        <StatCard 
            id="monthly-spend"
            title="Monthly Spend" 
            value={formatCurrency(stats.currentMTDTotal)} 
            icon={<CreditCard className="w-5 h-5 text-rose-400" />} 
            change={Math.abs(stats.spendChange).toFixed(1) + '%'} 
            positive={stats.spendChange <= 0} 
            delay="0.3s"
            isPinMode={isPinMode}
            isPinned={pinnedIds.includes('monthly-spend')}
            onTogglePin={() => onTogglePin?.('monthly-spend')}
        />
        <StatCard 
            id="burn-rate"
            title="Burn Rate/Day" 
            value={formatCurrency(stats.currentDailyAvg)} 
            icon={<Flame className="w-5 h-5 text-amber-400" />} 
            change={Math.abs(stats.burnChange).toFixed(1) + '%'} 
            positive={stats.burnChange <= 0}
            delay="0.4s"
            isPinMode={isPinMode}
            isPinned={pinnedIds.includes('burn-rate')}
            onTogglePin={() => onTogglePin?.('burn-rate')}
        />
        <StatCard 
            id="predicted-spend"
            title="Predicted Spend" 
            value={formatCurrency(stats.forecastedTotal)} 
            icon={<TrendingUp className="w-5 h-5 text-emerald-400" />} 
            change={Math.abs(stats.forecastChange).toFixed(1) + '%'} 
            positive={stats.forecastChange <= 0}
            delay="0.5s"
            isPinMode={isPinMode}
            isPinned={pinnedIds.includes('predicted-spend')}
            onTogglePin={() => onTogglePin?.('predicted-spend')}
        />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-2 spotlight-card glass-card p-6 md:p-8 rounded-[2rem] border border-white/5 shadow-xl animate-slide-up" style={{ animationDelay: '0.6s' }}>
            <div className="flex justify-between items-center mb-8 relative z-10">
                <h3 className="text-lg font-black text-white uppercase tracking-tighter flex items-center gap-3"><Activity className="w-6 h-6 text-indigo-400" />Expenditure Vector</h3>
                <div className="flex gap-4 text-[10px] font-black uppercase tracking-widest opacity-60">
                    <div className="flex items-center gap-1.5"><div className="w-2.5 h-2.5 rounded-full bg-indigo-500"></div><span>Actual</span></div>
                    <div className="flex items-center gap-1.5"><div className="w-2.5 h-2.5 rounded-full bg-slate-600"></div><span>Predicted</span></div>
                </div>
            </div>
            <div className="h-72 w-full relative z-10">
                <ResponsiveContainer width="100%" height="100%">
                    <AreaChart data={spendingData}>
                        <defs>
                            <linearGradient id="colorActual" x1="0" y1="0" x2="0" y2="1">
                                <stop offset="5%" stopColor="#6366f1" stopOpacity={0.2}/>
                                <stop offset="95%" stopColor="#6366f1" stopOpacity={0}/>
                            </linearGradient>
                        </defs>
                        <CartesianGrid strokeDasharray="3 3" stroke="#1e293b" vertical={false} />
                        <XAxis dataKey="date" stroke="#475569" fontSize={10} tickLine={false} axisLine={false} tick={{fontWeight:'bold'}} />
                        <YAxis stroke="#475569" fontSize={10} tickLine={false} axisLine={false} hide />
                        <Tooltip 
                            contentStyle={{ backgroundColor: '#020617', border: '1px solid rgba(255,255,255,0.05)', borderRadius: '12px', boxShadow: '0 10px 15px rgba(0,0,0,0.5)' }}
                            itemStyle={{ color: '#fff', fontSize: '12px', fontWeight: 'bold' }}
                        />
                        <Area type="monotone" dataKey="actual" stroke="#6366f1" strokeWidth={3} fillOpacity={1} fill="url(#colorActual)" animationDuration={1500} />
                        <Area type="monotone" dataKey="predicted" stroke="#475569" strokeWidth={2} strokeDasharray="5 5" fillOpacity={0} animationDuration={1800} />
                    </AreaChart>
                </ResponsiveContainer>
            </div>
        </div>

        <div className="spotlight-card glass-card p-6 md:p-8 rounded-[2rem] border border-white/5 shadow-xl flex flex-col animate-slide-up" style={{ animationDelay: '0.7s' }}>
            <div className="flex justify-between items-center mb-6 relative z-10">
                <h3 className="text-lg font-black text-white uppercase tracking-tighter flex items-center gap-3"><Repeat className="w-6 h-6 text-emerald-400" />Recurring Protocols</h3>
                <Zap className="w-4 h-4 text-emerald-500/40 animate-pulse" />
            </div>
            <div className="space-y-4 flex-1 overflow-y-auto custom-scrollbar pr-2 relative z-10">
                {recurringData.length > 0 ? recurringData.map((item, idx) => (
                    <div key={idx} className="p-4 bg-slate-900/60 rounded-2xl border border-white/5 hover:border-indigo-500/30 transition-all group animate-fade-in" style={{ animationDelay: `${0.8 + idx * 0.1}s` }}>
                        <div className="flex justify-between items-start mb-3">
                            <div className="flex items-center gap-3">
                                <div className="w-10 h-10 rounded-xl bg-slate-950 flex items-center justify-center text-emerald-400 border border-white/5 group-hover:scale-110 transition-transform"><Radio className="w-5 h-5" /></div>
                                <div>
                                    <h4 className="text-xs font-black text-white uppercase truncate max-w-[100px]">{item.merchant}</h4>
                                    <p className="text-[9px] text-slate-500 font-black uppercase tracking-widest">{item.isSubscription ? 'Static' : 'Dynamic'}</p>
                                </div>
                            </div>
                            <div className="text-right">
                                <div className="text-sm font-black text-white">{formatCurrency(item.avgCost)}</div>
                                <p className="text-[9px] text-slate-500 font-bold uppercase">Estimated</p>
                            </div>
                        </div>
                        <button 
                            onClick={() => handleNegotiateClick(item.merchant, item.avgCost)}
