import { GoogleGenAI, Type } from "@google/genai";
import { Transaction, AIAnalysisResponse, BotMode, Category, ChatMessage, FinancialSnapshot, SuggestedAction } from '../types';

let lastCallTime = 0;
const MIN_INTERVAL_MS = 1500; // Efficient throttle
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const checkRateLimit = () => {
  const now = Date.now();
  if (now - lastCallTime < MIN_INTERVAL_MS) {
    throw new Error("Cooling down. Please wait a moment.");
  }
  lastCallTime = now;
};

const cleanJsonResponse = (text: string) => {
  return text.replace(/```json/g, '').replace(/```/g, '').trim();
};

export const analyzeFinancialData = async (transactions: Transaction[]): Promise<AIAnalysisResponse | null> => {
  try {
    checkRateLimit();
    const recentTxs = transactions.slice(0, 50);
    const dataString = JSON.stringify(recentTxs);

    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Data: ${dataString}. You are Nova, a strict but effective financial coach. 
      Analyze the spend. Return JSON: {insights: [{title, description, type: 'success'|'warning'|'critical'}], budget_suggestions: [{category, current_spend, suggested_limit, reason}], predicted_spend_next_month, risk_score: 0-100}`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            insights: { type: Type.ARRAY, items: { type: Type.OBJECT, properties: { title: { type: Type.STRING }, description: { type: Type.STRING }, type: { type: Type.STRING } } } },
            budget_suggestions: { type: Type.ARRAY, items: { type: Type.OBJECT, properties: { category: { type: Type.STRING }, current_spend: { type: Type.NUMBER }, suggested_limit: { type: Type.NUMBER }, reason: { type: Type.STRING } } } },
            predicted_spend_next_month: { type: Type.NUMBER },
            risk_score: { type: Type.NUMBER }
          }
        }
      }
    });

    if (response.text) {
      return JSON.parse(cleanJsonResponse(response.text)) as AIAnalysisResponse;
    }
    return null;
  } catch (error) {
    console.error("AI Analysis Failed", error);
    return null;
  }
};

export const parseSimulationQuery = async (query: string): Promise<{ oneTimeTotal: number, monthlyRecurringTotal: number, parsedDescription: string } | null> => {
  try {
    checkRateLimit();
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Parse this spending simulation intent: "${query}". 
      Extract the total "oneTimeTotal" (large one-off buys) and "monthlyRecurringTotal" (subscriptions/recurring bills). 
      If no price is mentioned for an item, estimate a reasonable market price.
      Return JSON only: {oneTimeTotal: number, monthlyRecurringTotal: number, parsedDescription: string}`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            oneTimeTotal: { type: Type.NUMBER },
            monthlyRecurringTotal: { type: Type.NUMBER },
            parsedDescription: { type: Type.STRING }
          }
        }
      }
    });
    return response.text ? JSON.parse(cleanJsonResponse(response.text)) : null;
  } catch (error) {
    console.error("Sim Parse Failed", error);
    return null;
  }
};

export const categorizeTransaction = async (merchant: string, amount: number): Promise<string> => {
  try {
    checkRateLimit();
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Categorize "${merchant}" ($${amount}). Return only the category name from standard finance categories.`,
    });
    return response.text?.trim() || 'Other';
  } catch (e) {
    return 'Other';
  }
};

export const chatWithFinancialCoach = async (
  currentMessage: string,
  history: ChatMessage[],
  snapshot: FinancialSnapshot,
  mode: BotMode = 'ruthless'
): Promise<{ message: string; sentiment: 'info' | 'warning' | 'critical'; suggestedActions: SuggestedAction[] }> => {
  checkRateLimit();

  // Create a condensed history context (last 5 messages)
  const historyText = history
    .slice(-5)
    .map(m => `${m.role.toUpperCase()}: ${m.content}`)
    .join('\n');

  const systemInstruction = mode === 'ruthless'
    ? "You are a hedge fund risk manager. Be concise. Highlight variance. Do not use pleasantries. Focus on the numbers. If spending is high, be critical."
    : "You are a financial wellness counselor. Use encouraging language. Focus on progress and constructive advice. Be supportive but realistic.";

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `
        Financial Snapshot: ${JSON.stringify(snapshot)}

        Recent Conversation:
        ${historyText}

        User's New Question: ${currentMessage}

        Based on the snapshot and history, answer the question.
        Return JSON with:
        - message: The answer string.
        - sentiment: 'info' (neutral), 'warning' (caution), or 'critical' (danger).
        - suggestedActions: Array of relevant UI actions (optional).
      `,
      config: {
        systemInstruction,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            message: { type: Type.STRING },
            sentiment: { type: Type.STRING, enum: ["info", "warning", "critical"] },
            suggestedActions: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  label: { type: Type.STRING },
                  actionId: { type: Type.STRING },
                  payload: { type: Type.STRING },
                }
              }
            }
          }
        }
      }
    });

    if (response.text) {
        return JSON.parse(cleanJsonResponse(response.text));
    }
    throw new Error("No response generated");
  } catch (error) {
    console.error("Coach Chat Error", error);
    return {
        message: "I'm currently unable to process your financial data due to a connection issue.",
        sentiment: "critical",
        suggestedActions: []
    };
  }
};

export const parseReceiptImage = async (base64Image: string): Promise<{ merchant: string; date: string; amount: number; category: string } | null> => {
  try {
    checkRateLimit();
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview", 
      contents: {
        parts: [
          { inlineData: { mimeType: 'image/jpeg', data: base64Image } },
          { text: "Extract merchant, total amount (number), date (YYYY-MM-DD), and category. Return strictly JSON." }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            merchant: { type: Type.STRING },
            amount: { type: Type.NUMBER },
            date: { type: Type.STRING },
            category: { type: Type.STRING }
          }
        }
      }
    });
    return response.text ? JSON.parse(cleanJsonResponse(response.text)) : null;
  } catch (error) {
    return null;
  }
};

export const generateNegotiationScript = async (merchant: string, amount: number): Promise<string> => {
  try {
    checkRateLimit();
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Write a copy-paste script to negotiate a lower monthly bill for ${merchant} (Current: $${amount}). No greetings, just the body text.`,
    });
    return response.text?.trim() || "Unable to generate script.";
  } catch (error) {
    return "System busy.";
  }
};

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { Transaction, AIAnalysisResponse, ChatMessage, UserPlan, TransactionType, Budget, BotMode, Category, Goal, FinancialSnapshot } from '../types';
import { analyzeFinancialData, chatWithFinancialCoach } from '../services/geminiService';
import { RefreshCcw, CheckCircle, AlertTriangle, ShieldAlert, Info, TrendingUp, Bot, User, BrainCircuit, Lightbulb, Send, Lock, Sparkles, RefreshCw, Flame, ArrowRight, Zap, Crown, TrendingDown, ShoppingCart, Wallet, Terminal, Activity, MousePointerClick } from 'lucide-react';

interface InsightsProps {
  transactions: Transaction[];
  goals: Goal[];
  budgets: Budget[];
  userPlan: UserPlan;
  onUpgradeClick: () => void;
  formatCurrency: (amount: number) => string;
  initialPrompt?: string | null; 
  onPromptHandled?: () => void; 
  onApplyBudgets?: (budgets: Budget[]) => void; 
  insightUsage: number; 
  onIncrementUsage: () => void; 
  botMode: BotMode; 
}

const Insights: React.FC<InsightsProps> = ({ transactions, goals, budgets, userPlan, onUpgradeClick, formatCurrency, initialPrompt, onPromptHandled, onApplyBudgets, insightUsage, onIncrementUsage, botMode }) => {
  const [analysis, setAnalysis] = useState<AIAnalysisResponse | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [chatInput, setChatInput] = useState('');
  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([
    { 
        id: '1', 
        role: 'assistant', 
        content: botMode === 'ruthless' 
            ? 'System initialized. Ready to audit your spending vectors.' 
            : 'Hello! I\'m ready to help you optimize your financial wellness. What\'s on your mind?', 
        timestamp: new Date(),
        sentiment: 'info'
    }
  ]);
  const [chatLoading, setChatLoading] = useState(false);
  const chatEndRef = useRef<HTMLDivElement>(null);

  const isUltra = userPlan === 'ultra';
  const isPro = userPlan === 'pro';

  // Industrial Grade Limits
  const FREE_LIMIT = 3;
  const PRO_LIMIT = 50;
  const ULTRA_LIMIT = 1500;

  const currentLimit = isUltra ? ULTRA_LIMIT : isPro ? PRO_LIMIT : FREE_LIMIT;
  const isLocked = insightUsage >= currentLimit;

  // Manual Trigger Logic - Removed useEffect for auto-run
  const runAnalysis = async () => {
    if (isLocked) return;
    setLoading(true);
    setError(null);
    onIncrementUsage();
    try {
      const result = await analyzeFinancialData(transactions);
      if (result) {
        setAnalysis(result);
      } else {
        setError("Coach is analyzing other portfolios. Try again.");
      }
    } catch (e) {
      setError("Unable to connect to financial brain.");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [chatHistory, chatLoading]);

  useEffect(() => {
      if (!isLocked && initialPrompt && !chatLoading) {
          handleSendMessage(null, initialPrompt);
          if (onPromptHandled) onPromptHandled();
      }
  }, [initialPrompt, isLocked]);

  const handleSendMessage = async (e: React.FormEvent | null, promptOverride?: string) => {
    if (e) e.preventDefault();
    const content = promptOverride || chatInput;
    if (!content.trim() || isLocked) return;

    onIncrementUsage();
    const userMsg: ChatMessage = { id: Date.now().toString(), role: 'user', content: content, timestamp: new Date() };
    setChatHistory(prev => [...prev, userMsg]);
    setChatInput('');
    setChatLoading(true);

    // Build Financial Snapshot (Client-Side)
    const now = new Date();
    const currentMonthTxs = transactions.filter(t => new Date(t.date).getMonth() === now.getMonth());
    const income = currentMonthTxs.filter(t => t.type === TransactionType.INCOME).reduce((sum, t) => sum + t.amount, 0);
    const expense = currentMonthTxs.filter(t => t.type === TransactionType.EXPENSE).reduce((sum, t) => sum + t.amount, 0);

    // Calculate top category
    const catMap: Record<string, number> = {};
    currentMonthTxs.filter(t => t.type === TransactionType.EXPENSE).forEach(t => { catMap[t.category] = (catMap[t.category] || 0) + t.amount; });
    const topCat = Object.entries(catMap).sort((a,b) => b[1] - a[1])[0];

    const snapshot: FinancialSnapshot = {
        currentMonthMetrics: {
            income,
            expense,
            savingsRate: income > 0 ? (income - expense) / income : 0,
            topExpenseCategory: topCat ? topCat[0] : 'None'
        },
        recentTransactions: transactions.slice(0, 10), // Limit to 10 for tokens
        activeGoals: goals,
        budgets: budgets
    };

    const response = await chatWithFinancialCoach(userMsg.content, chatHistory, snapshot, botMode);

    const aiMsg: ChatMessage = { 
        id: (Date.now() + 1).toString(), 
        role: 'assistant', 
        content: response.message, 
        timestamp: new Date(),
        sentiment: response.sentiment as any,
        suggestedActions: response.suggestedActions
    };

    setChatHistory(prev => [...prev, aiMsg]);
    setChatLoading(false);
  };

  const handleAutoTune = () => {
      if (!analysis || !onApplyBudgets) return;
      const newBudgets: Budget[] = analysis.budget_suggestions.map(bs => ({
          id: `ai_${Date.now()}_${bs.category}`,
          category: bs.category as any,
          limit: bs.suggested_limit
      }));
      onApplyBudgets(newBudgets);
  };

  const getColorClass = (type: string) => {
    switch (type) {
        case 'success': return 'bg-emerald-500/10 border-emerald-500/20 text-emerald-100';
        case 'warning': return 'bg-amber-500/10 border-amber-500/20 text-amber-100';
        case 'critical': return 'bg-rose-500/10 border-rose-500/20 text-rose-100';
        default: return 'bg-blue-500/10 border-blue-500/20 text-blue-100';
    }
  };

  const getChatBubbleStyle = (role: string, sentiment?: string) => {
      if (role === 'user') return 'bg-indigo-600 text-white border-indigo-500/50';

      switch (sentiment) {
          case 'critical': return 'bg-rose-950/40 border-rose-500/30 text-rose-100';
          case 'warning': return 'bg-amber-950/40 border-amber-500/30 text-amber-100';
          default: return 'bg-slate-800/80 border-white/10 text-slate-200';
      }
  };

  return (
    <div className="relative h-[calc(100vh-8rem)]">
      {isLocked && (
        <div className="absolute inset-0 z-50 flex items-center justify-center bg-slate-950/60 backdrop-blur-xl rounded-[2rem] border border-white/10 transform scale-105 transition-transform duration-500">
            <div className="text-center p-8 max-w-md animate-slide-up">
                <div className="w-20 h-20 rounded-3xl bg-gradient-to-tr from-indigo-500 to-purple-500 flex items-center justify-center mx-auto mb-6 shadow-2xl shadow-indigo-500/40"><Lock className="w-10 h-10 text-white" /></div>
                <h2 className="text-3xl font-bold text-white mb-3">Limit Reached</h2>
                <p className="text-slate-400 mb-8 leading-relaxed">
                    You've hit your monthly cap of {currentLimit} interactions for your {userPlan.toUpperCase()} plan. Upgrade or manage your plan to continue using the AI Coach.
                </p>
                {!isUltra && (
                    <button onClick={onUpgradeClick} className="w-full py-4 bg-white text-indigo-900 font-bold rounded-xl shadow-xl hover:scale-[1.02] active:scale-95 transition-all flex items-center justify-center gap-2 group"><Sparkles className="w-5 h-5 text-indigo-600 group-hover:rotate-12 transition-transform" />Upgrade Plan</button>
                )}
            </div>
        </div>
      )}

      <div className={`grid grid-cols-1 lg:grid-cols-3 gap-8 pb-10 h-full transition-all duration-500 ${isLocked ? 'blur-md opacity-50 pointer-events-none select-none overflow-hidden' : ''}`}>
        <div className="lg:col-span-2 overflow-y-auto custom-scrollbar space-y-8 pr-2">

            {/* Manual Trigger Header */}
            <div className="bg-gradient-to-r from-slate-900 via-slate-900/80 to-indigo-900/20 p-8 rounded-[2.5rem] border border-white/10 shadow-2xl relative overflow-hidden group">
                <div className="flex justify-between items-start relative z-10">
                    <div>
                        <h2 className="text-2xl font-black text-white flex items-center gap-3"><BrainCircuit className="w-8 h-8 text-indigo-400" />Command Center</h2>
                        <p className="text-slate-400 text-sm mt-2 max-w-md font-medium">Initiate deep neural scans or query the agent directly.</p>
                        <div className={`mt-4 inline-flex items-center gap-2 px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest border ${isUltra ? 'bg-indigo-500/10 border-indigo-500/20 text-indigo-400' : isPro ? 'bg-amber-500/10 border-amber-500/20 text-amber-400' : 'bg-slate-700/50 border-white/10 text-slate-400'}`}>
                            {isUltra ? <Crown className="w-3 h-3" /> : isPro ? <Zap className="w-3 h-3" /> : null}
                            Tokens: {insightUsage}/{currentLimit}
                        </div>
                    </div>
                    <button 
                        onClick={runAnalysis} 
                        disabled={loading} 
                        className="flex flex-col items-center justify-center w-24 h-24 bg-slate-800 hover:bg-indigo-600 rounded-3xl border border-white/10 transition-all group shadow-xl active:scale-95"
                    >
