            <div className="flex-1 overflow-y-auto p-5 space-y-6 custom-scrollbar bg-slate-950/20">
                {chatHistory.map((msg) => (
                    <div key={msg.id} className={`flex gap-3 ${msg.role === 'user' ? 'flex-row-reverse' : 'flex-row'} animate-slide-up`}>
                        <div className={`w-8 h-8 rounded-full flex items-center justify-center shrink-0 border border-white/10 shadow-sm ${msg.role === 'user' ? 'bg-slate-800' : botMode === 'ruthless' ? 'bg-slate-700' : 'bg-gradient-to-tr from-indigo-500 to-purple-500'}`}>
