import { GoogleGenAI, Type } from "@google/genai";
import { Transaction, AIAnalysisResponse, BotMode, Category, ChatMessage, FinancialSnapshot, SuggestedAction } from '../types';

let lastCallTime = 0;
const MIN_INTERVAL_MS = 1500; // Efficient throttle
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const checkRateLimit = () => {
  const now = Date.now();
  if (now - lastCallTime < MIN_INTERVAL_MS) {
    throw new Error("Cooling down. Please wait a moment.");
  }
  lastCallTime = now;
};

const cleanJsonResponse = (text: string) => {
  return text.replace(/```json/g, '').replace(/```/g, '').trim();
};

export const analyzeFinancialData = async (transactions: Transaction[]): Promise<AIAnalysisResponse | null> => {
  try {
    checkRateLimit();
    const recentTxs = transactions.slice(0, 50);
    const dataString = JSON.stringify(recentTxs);

    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Data: ${dataString}. You are Nova, a strict but effective financial coach. 
      Analyze the spend. Return JSON: {insights: [{title, description, type: 'success'|'warning'|'critical'}], budget_suggestions: [{category, current_spend, suggested_limit, reason}], predicted_spend_next_month, risk_score: 0-100}`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            insights: { type: Type.ARRAY, items: { type: Type.OBJECT, properties: { title: { type: Type.STRING }, description: { type: Type.STRING }, type: { type: Type.STRING } } } },
            budget_suggestions: { type: Type.ARRAY, items: { type: Type.OBJECT, properties: { category: { type: Type.STRING }, current_spend: { type: Type.NUMBER }, suggested_limit: { type: Type.NUMBER }, reason: { type: Type.STRING } } } },
            predicted_spend_next_month: { type: Type.NUMBER },
            risk_score: { type: Type.NUMBER }
          }
        }
      }
    });

    if (response.text) {
      return JSON.parse(cleanJsonResponse(response.text)) as AIAnalysisResponse;
    }
    return null;
  } catch (error) {
    console.error("AI Analysis Failed", error);
    return null;
  }
};

export const parseSimulationQuery = async (query: string): Promise<{ oneTimeTotal: number, monthlyRecurringTotal: number, parsedDescription: string } | null> => {
  try {
    checkRateLimit();
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Parse this spending simulation intent: "${query}". 
      Extract the total "oneTimeTotal" (large one-off buys) and "monthlyRecurringTotal" (subscriptions/recurring bills). 
      If no price is mentioned for an item, estimate a reasonable market price.
      Return JSON only: {oneTimeTotal: number, monthlyRecurringTotal: number, parsedDescription: string}`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            oneTimeTotal: { type: Type.NUMBER },
            monthlyRecurringTotal: { type: Type.NUMBER },
            parsedDescription: { type: Type.STRING }
          }
        }
      }
    });
    return response.text ? JSON.parse(cleanJsonResponse(response.text)) : null;
  } catch (error) {
    console.error("Sim Parse Failed", error);
    return null;
  }
};

export const categorizeTransaction = async (merchant: string, amount: number): Promise<string> => {
  try {
    checkRateLimit();
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Categorize "${merchant}" ($${amount}). Return only the category name from standard finance categories.`,
    });
    return response.text?.trim() || 'Other';
  } catch (e) {
    return 'Other';
  }
};

export const chatWithFinancialCoach = async (
  currentMessage: string,
  history: ChatMessage[],
  snapshot: FinancialSnapshot,
  mode: BotMode = 'ruthless'
): Promise<{ message: string; sentiment: 'info' | 'warning' | 'critical'; suggestedActions: SuggestedAction[] }> => {
  checkRateLimit();

  // Create a condensed history context (last 5 messages)
  const historyText = history
    .slice(-5)
    .map(m => `${m.role.toUpperCase()}: ${m.content}`)
    .join('\n');

  const systemInstruction = mode === 'ruthless'
    ? "You are a hedge fund risk manager. Be concise. Highlight variance. Do not use pleasantries. Focus on the numbers. If spending is high, be critical."
    : "You are a financial wellness counselor. Use encouraging language. Focus on progress and constructive advice. Be supportive but realistic.";

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `
        Financial Snapshot: ${JSON.stringify(snapshot)}

        Recent Conversation:
        ${historyText}

        User's New Question: ${currentMessage}

        Based on the snapshot and history, answer the question.
        Return JSON with:
        - message: The answer string.
        - sentiment: 'info' (neutral), 'warning' (caution), or 'critical' (danger).
        - suggestedActions: Array of relevant UI actions (optional). Examples: Set Budget, View Transactions.
      `,
      config: {
        systemInstruction,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            message: { type: Type.STRING },
            sentiment: { type: Type.STRING, enum: ["info", "warning", "critical"] },
            suggestedActions: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  label: { type: Type.STRING },
                  actionId: { type: Type.STRING },
                  payload: { type: Type.STRING },
                }
              }
            }
          }
        }
      }
    });

    if (response.text) {
        return JSON.parse(cleanJsonResponse(response.text));
    }
    throw new Error("No response generated");
  } catch (error) {
    console.error("Coach Chat Error", error);
    return {
        message: "I'm currently unable to process your financial data due to a connection issue.",
        sentiment: "critical",
        suggestedActions: []
    };
  }
};

