  const [onboardingComplete, setOnboardingComplete] = useState(() => localStorage.getItem('nova_onboarding_complete') === 'true');
  const [spendingLimit, setSpendingLimit] = useState<number>(() => parseFloat(localStorage.getItem('nova_spending_limit') || '1000'));
  const [spendingPeriod, setSpendingPeriod] = useState<SpendingPeriod>(() => (localStorage.getItem('nova_spending_period') as SpendingPeriod) || 'monthly');

  // Pin System State
  const [pinnedIds, setPinnedIds] = useState<string[]>(() => {
    try {
        const saved = localStorage.getItem('nova_pinned_ids');
        return saved ? JSON.parse(saved) : []; 
    } catch { return []; }
  });

  const [featureUsage, setFeatureUsage] = useState<Record<string, number>>(() => {
      try {
          const saved = localStorage.getItem('nova_feature_usage');
          return saved ? JSON.parse(saved) : {};
      } catch { return {}; }
  });

  const [accounts, setAccounts] = useState<Account[]>(() => {
      const saved = localStorage.getItem('nova_accounts');
      return saved ? JSON.parse(saved) : ACCOUNTS;
  });
  const [transactions, setTransactions] = useState<Transaction[]>(() => {
      const saved = localStorage.getItem('nova_transactions');
      return saved ? JSON.parse(saved) : INITIAL_TRANSACTIONS;
  });
  const [budgets, setBudgets] = useState<Budget[]>(() => {
      const saved = localStorage.getItem('nova_budgets');
      return saved ? JSON.parse(saved) : INITIAL_BUDGETS;
  });
  const [goals, setGoals] = useState<Goal[]>(() => {
      const saved = localStorage.getItem('nova_goals');
      return saved ? JSON.parse(saved) : INITIAL_GOALS;
  });

  const [userPlan, setUserPlan] = useState<UserPlan>(() => localStorage.getItem('nova_user_plan') as UserPlan || 'free');
  const [insightUsage, setInsightUsage] = useState(() => getMonthlyUsage('nova_insight_usage'));
  const [scanUsage, setScanUsage] = useState(() => getMonthlyUsage('nova_scan_usage'));
  const [negotiationUsage, setNegotiationUsage] = useState(() => getMonthlyUsage('nova_negotiation_usage'));

  const [isLoggedIn, setIsLoggedIn] = useState(() => localStorage.getItem('nova_auth_token') !== null);
  const [isLogoutModalOpen, setIsLogoutModalOpen] = useState(false);
  const [toasts, setToasts] = useState<ToastMessage[]>([]);
  const [botMode, setBotMode] = useState<BotMode>(() => (localStorage.getItem('nova_bot_mode') as BotMode) || 'ruthless');
  const [pendingChatQuery, setPendingChatQuery] = useState<string | null>(null);

  const [userName, setUserName] = useState(() => localStorage.getItem('nova_user_name') || 'Pilot');
  const [userEmail, setUserEmail] = useState(() => localStorage.getItem('nova_user_email') || 'pilot@nova.io');
  const [userAvatar, setUserAvatar] = useState(() => localStorage.getItem('nova_user_avatar') || '');
  const [userAvatarZoom, setUserAvatarZoom] = useState(1);
  const [userAvatarPos, setUserAvatarPos] = useState({ x: 0, y: 0 });
  const [userBorder, setUserBorder] = useState('default');
  const [userBackground, setUserBackground] = useState(() => localStorage.getItem('nova_user_bg') || '');

  const [currency, setCurrency] = useState<Currency>(() => (localStorage.getItem('nova_currency') as Currency) || 'USD');
  const [language, setLanguage] = useState<Language>(() => (localStorage.getItem('nova_language') as Language) || 'en');

  // Persistence Effects
  useEffect(() => safeSetItem('nova_accounts', JSON.stringify(accounts)), [accounts]);
  useEffect(() => safeSetItem('nova_transactions', JSON.stringify(transactions)), [transactions]);
  useEffect(() => safeSetItem('nova_budgets', JSON.stringify(budgets)), [budgets]);
  useEffect(() => safeSetItem('nova_goals', JSON.stringify(goals)), [goals]);
  useEffect(() => safeSetItem('nova_user_plan', userPlan), [userPlan]);
  useEffect(() => safeSetItem('nova_currency', currency), [currency]);
  useEffect(() => safeSetItem('nova_language', language), [language]);
  useEffect(() => safeSetItem('nova_bot_mode', botMode), [botMode]);
  useEffect(() => safeSetItem('nova_privacy_mode', isPrivacyMode.toString()), [isPrivacyMode]);
  useEffect(() => safeSetItem('nova_pinned_ids', JSON.stringify(pinnedIds)), [pinnedIds]);
  useEffect(() => safeSetItem('nova_feature_usage', JSON.stringify(featureUsage)), [featureUsage]);
  useEffect(() => safeSetItem('nova_user_bg', userBackground), [userBackground]);
  useEffect(() => safeSetItem('nova_spending_limit', spendingLimit.toString()), [spendingLimit]);
  useEffect(() => safeSetItem('nova_spending_period', spendingPeriod), [spendingPeriod]);
  useEffect(() => safeSetItem('nova_onboarding_complete', onboardingComplete.toString()), [onboardingComplete]);

  // Spending Enforcement Calculation (Zero AI, Pure Math)
  const spendingStatus: { currentSpend: number; status: SpendingStatus } = useMemo(() => {
      const now = new Date();
      let startDate = new Date();

      if (spendingPeriod === 'weekly') {
          // Set to previous Sunday (or today if Sunday)
          const day = now.getDay();
          const diff = now.getDate() - day;
          startDate = new Date(now.setDate(diff));
          startDate.setHours(0, 0, 0, 0);
      } else {
          // Set to 1st of current month
          startDate = new Date(now.getFullYear(), now.getMonth(), 1);
      }

      const currentSpend = transactions
          .filter(t => t.type === TransactionType.EXPENSE && new Date(t.date) >= startDate)
          .reduce((acc, t) => acc + t.amount, 0);

      const status = evaluateSpending(currentSpend, spendingLimit);
      return { currentSpend, status };
  }, [transactions, spendingPeriod, spendingLimit]);

  // Usage counters
  useEffect(() => {
      const now = new Date();
      const meta = { month: now.getMonth(), year: now.getFullYear(), count: insightUsage };
      safeSetItem('nova_insight_usage', JSON.stringify(meta));
  }, [insightUsage]);

  useEffect(() => {
      const now = new Date();
      const meta = { month: now.getMonth(), year: now.getFullYear(), count: scanUsage };
      safeSetItem('nova_scan_usage', JSON.stringify(meta));
  }, [scanUsage]);

  useEffect(() => {
      const now = new Date();
      const meta = { month: now.getMonth(), year: now.getFullYear(), count: negotiationUsage };
      safeSetItem('nova_negotiation_usage', JSON.stringify(meta));
  }, [negotiationUsage]);

  const addToast = useCallback((message: string, type: 'success' | 'error' | 'info' = 'info') => {
    setToasts(prev => [...prev, { id: Date.now().toString(), message, type }]);
  }, []);

  const trackFeatureUsage = useCallback((featureId: string) => {
      setFeatureUsage(prev => ({
          ...prev,
          [featureId]: (prev[featureId] || 0) + 1
      }));
  }, []);

  // Auto-Pin Heuristic
  useEffect(() => {
      if (!isLoggedIn) return;
      const hasAutoPinned = localStorage.getItem('nova_has_auto_pinned');
      if (hasAutoPinned) return;

      const totalActions = (Object.values(featureUsage) as number[]).reduce((a, b) => a + b, 0);
      if (totalActions > 10) {
          const sorted = Object.entries(featureUsage)
              .filter(([key]) => PINNABLE_FEATURES.includes(key))
              .sort((a, b) => (b[1] as number) - (a[1] as number))
              .map(([key]) => key)
              .slice(0, 2); 

          if (sorted.length > 0) {
              setPinnedIds(sorted);
              addToast(`System optimization complete. Top ${sorted.length} modules pinned.`, 'info');
              localStorage.setItem('nova_has_auto_pinned', 'true');
          }
      }
  }, [featureUsage, isLoggedIn, addToast]);

  const handleTogglePin = (id: string) => {
    setPinnedIds(prev => {
        if (prev.includes(id)) {
            return prev.filter(p => p !== id);
        }
        const limit = userPlan === 'ultra' ? 5 : userPlan === 'pro' ? 3 : 1;
        if (prev.length >= limit) {
            addToast(`Slot Limit Reached (${limit}). Unpin a module to replace.`, 'error');
            return prev;
        }
        return [...prev, id];
    });
  };

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
        const isModI = (e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'i';
        if (isModI) {
            e.preventDefault();
            setIsPinMode(prev => {
                const newVal = !prev;
                addToast(newVal ? 'Pin Configuration Mode: ACTIVE' : 'Pin Configuration Mode: END', 'info');
                if (newVal) setActiveTab('dashboard');
                return newVal;
            });
        }
        if (e.key === 'Escape' && isPinMode) {
            setIsPinMode(false);
            addToast('Pin Configuration Mode: END', 'info');
        }
        if (e.shiftKey && e.key.toLowerCase() === 'p') {
            handleToggleStealth();
        }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isPinMode, userPlan, isPrivacyMode, addToast]);

  const handleToggleStealth = () => {
    if (userPlan !== 'ultra') {
        addToast('Stealth Protocol is an Elite-exclusive feature.', 'info');
        setActiveTab('plans');
        return;
    }
    setIsPrivacyMode(prev => !prev);
    addToast(`Stealth Protocol ${!isPrivacyMode ? 'Engaged' : 'Disengaged'}`, 'info');
  };

  const removeToast = (id: string) => {
    setToasts(prev => prev.filter(t => t.id !== id));
  };

  const formatCurrency = (amount: number) => {
    const val = new Intl.NumberFormat(language === 'vi' ? 'vi-VN' : 'en-US', { 
        style: 'currency', currency: currency,
    }).format(amount);

    if (isPrivacyMode && userPlan === 'ultra') {
        return <span className="blur-md opacity-50 bg-white/5 px-1 rounded-md">{val.replace('-', '')}</span>;
    }
    return val;
  };

  const reconcileBalance = (tx: Transaction, direction: 'add' | 'delete') => {
      if (tx.accountId === 'manual') return;
      setAccounts(prev => prev.map(acc => {
          if (acc.id === tx.accountId) {
              const isIncome = tx.type === TransactionType.INCOME;
              let change = tx.amount;
              if (direction === 'add') change = isIncome ? change : -change;
              else change = isIncome ? -change : change;
              return { ...acc, balance: acc.balance + change };
          }
          return acc;
      }));
  };

  const handleAddTransaction = (t: Transaction) => {
      setTransactions(prev => [t, ...prev]);
      reconcileBalance(t, 'add');
      addToast('Transaction recorded.', 'success');
  };

  const handleDeleteTransaction = (id: string) => {
      const tx = transactions.find(t => t.id === id);
      if (tx) {
          reconcileBalance(tx, 'delete');
          setTransactions(prev => prev.filter(t => t.id !== id));
          addToast('Transaction purged.', 'info');
      }
  };

  const handleLogin = (name: string) => {
    setIsLoggedIn(true);
    setUserName(name);
    localStorage.setItem('nova_user_name', name);
  };

  const confirmLogout = () => {
    localStorage.removeItem('nova_auth_token');
    localStorage.removeItem('nova_vault_key'); // Clear vault key on logout for security
    setIsLoggedIn(false);
    setIsLogoutModalOpen(false);
  };

  const handleAskCoach = (message?: string) => {
    if (message) {
      setPendingChatQuery(message);
    }
    setActiveTab('insights');
  };

  const handleOnboardingComplete = (lang: Language, per: SpendingPeriod, lim: number) => {
      setLanguage(lang);
      setSpendingPeriod(per);
      setSpendingLimit(lim);
      setOnboardingComplete(true);
      addToast('System Initialized. Spending parameters locked.', 'success');
  };

  const branding = useMemo(() => {
    switch (userPlan) {
      case 'ultra':
        return {
          bg: 'bg-gradient-to-tr from-indigo-600 to-purple-600',
          shadow: 'shadow-indigo-500/40',
          icon: <Sparkles className="w-6 h-6 text-white" />,
          label: 'Elite Terminal'
        };
      case 'pro':
        return {
          bg: 'bg-gradient-to-tr from-amber-400 to-orange-500',
          shadow: 'shadow-amber-500/40',
          icon: <Zap className="w-6 h-6 text-white" />,
          label: 'Pro Uplink'
        };
      default:
        return {
          bg: 'bg-slate-800',
          shadow: 'shadow-black/20',
          icon: <Shield className="w-6 h-6 text-slate-400" />,
          label: 'Free Tier'
        };
    }
  }, [userPlan]);

  if (!isLoggedIn) return <LandingPage onLoginSuccess={handleLogin} />;

  if (!onboardingComplete) return <OnboardingModal onComplete={handleOnboardingComplete} />;

  return (
    <div className={`flex h-screen bg-[#020617] text-slate-100 font-sans selection:bg-indigo-500/30 overflow-hidden relative ${isPinMode ? 'cursor-default' : ''}`}>
      <FloatingAssistant transactions={transactions} budgets={budgets} userPlan={userPlan} botMode={botMode} isVisible={activeTab !== 'insights'} onOpenChat={handleAskCoach} insightUsage={insightUsage} />

      <aside className="hidden md:flex flex-col w-64 p-4 pb-8 z-20 bg-slate-950/40 backdrop-blur-md border-r border-white/5 relative">
        <div className="flex items-center gap-3 px-4 py-3 mb-8 shrink-0">
            <div className={`w-10 h-10 rounded-xl flex items-center justify-center shadow-lg ring-1 ring-white/10 ${branding.bg} ${branding.shadow}`}>{branding.icon}</div>
            <div><h1 className="text-xl font-bold tracking-tight text-white">Nova AI</h1><p className={`text-[10px] font-bold uppercase tracking-wider ${userPlan === 'ultra' ? 'text-purple-400' : userPlan === 'pro' ? 'text-amber-400' : 'text-slate-500'}`}>{branding.label}</p></div>
        </div>
        <nav className="flex-1 space-y-1 overflow-y-auto custom-scrollbar pr-1">
            {NAV_ITEMS.map((item) => {
                const isActive = activeTab === item.id;
                const label = TRANSLATIONS[language]?.[item.id as keyof typeof TRANSLATIONS['en']] || item.label;
                return (
                    <button key={item.id} onClick={() => setActiveTab(item.id)} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold transition-all duration-300 group ${isActive ? 'bg-indigo-600/10 text-indigo-400 shadow-[0_0_20px_rgba(99,102,241,0.15)] ring-1 ring-indigo-500/20' : 'text-slate-400 hover:text-white hover:bg-white/5'}`}>
                        <item.icon className={`w-5 h-5 transition-colors ${isActive ? 'text-indigo-400' : 'text-slate-500 group-hover:text-white'}`} />{label}
                    </button>
                );
            })}
        </nav>
        <div className="mt-auto pt-6 border-t border-white/5 shrink-0">
             <button onClick={handleToggleStealth} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all mb-2 ${isPrivacyMode && userPlan === 'ultra' ? 'bg-indigo-500/20 text-indigo-400 border border-indigo-500/30' : 'text-slate-500 hover:text-slate-300 hover:bg-white/5'}`}>
                {isPrivacyMode ? <EyeOff className="w-5 h-5" /> : <Shield className="w-5 h-5" />} {isPrivacyMode ? 'Stealth Engaged' : 'Stealth Protocol'}
             </button>
             <button onClick={() => setActiveTab('settings')} className="w-full text-left px-4 py-4 rounded-2xl bg-slate-900/50 border border-white/5 flex items-center gap-3 mb-4 hover:bg-slate-800 transition-colors group">
                 <div className="w-10 h-10 rounded-full bg-indigo-500 flex items-center justify-center text-white overflow-hidden relative border border-white/10 shadow-inner">{userAvatar ? <img src={userAvatar} className="w-full h-full object-cover" alt="User" /> : <span className="font-bold text-lg">{userName.charAt(0)}</span>}</div>
                 <div className="overflow-hidden"><h4 className="font-bold text-white text-sm truncate group-hover:text-indigo-400 transition-colors">{userName}</h4><p className="text-[10px] text-slate-500 truncate font-bold uppercase tracking-widest">{userPlan} tier</p></div>
             </button>
             <button onClick={() => setIsLogoutModalOpen(true)} className="w-full flex items-center gap-2 px-4 py-2 mb-4 text-xs font-bold text-slate-500 hover:text-rose-400 transition-colors uppercase tracking-widest"><LogOut className="w-4 h-4" /> Sign Out</button>
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 z-10 relative overflow-hidden">
        {isPinMode && (
          <div className="absolute inset-0 z-[100] bg-black/40 backdrop-blur-[2px] pointer-events-none flex flex-col items-center justify-start pt-20">
              <div className="bg-indigo-600/90 text-white font-black text-xs uppercase tracking-[0.3em] px-8 py-4 rounded-2xl shadow-[0_0_50px_rgba(99,102,241,0.5)] border border-indigo-400/50 animate-pulse pointer-events-auto">
                  Pin Mode Active :: Select Priority Nodes :: Esc to Exit
              </div>
          </div>
        )}

        <div className="flex-1 overflow-y-auto p-4 md:p-8 pb-24 md:pb-8 custom-scrollbar">
            {activeTab === 'dashboard' && <Dashboard accounts={accounts} transactions={transactions} goals={goals} budgets={budgets} onNavigate={setActiveTab} onAddAccount={() => setActiveTab('accounts')} onAddTransaction={() => setActiveTab('transactions')} onAddGoal={() => setActiveTab('goals')} formatCurrency={formatCurrency} userPlan={userPlan} onAskCoach={handleAskCoach} negotiationUsage={negotiationUsage} onIncrementNegotiation={() => setNegotiationUsage(prev => prev + 1)} isPinMode={isPinMode} pinnedIds={pinnedIds} onTogglePin={handleTogglePin} trackEvent={trackFeatureUsage} insightUsage={insightUsage} spendingStatus={spendingStatus.status} currentPeriodSpend={spendingStatus.currentSpend} spendingLimit={spendingLimit} spendingPeriod={spendingPeriod} />}
            {activeTab === 'transactions' && <Transactions transactions={transactions} accounts={accounts} onDelete={handleDeleteTransaction} onAdd={handleAddTransaction} formatCurrency={formatCurrency} onNavigateToAccounts={() => setActiveTab('accounts')} userPlan={userPlan} scanUsage={scanUsage} onIncrementScan={() => setScanUsage(prev => prev + 1)} currency={currency} />}
            {activeTab === 'accounts' && <Accounts accounts={accounts} budgets={budgets} transactions={transactions} userPlan={userPlan} onAdd={(acc) => { setAccounts(prev => [...prev, acc]); addToast('Account linked.', 'success'); }} onUpdate={(acc) => { setAccounts(prev => prev.map(a => a.id === acc.id ? acc : a)); addToast('Account updated.', 'success'); }} onDelete={(id) => { setAccounts(prev => prev.filter(a => a.id !== id)); setTransactions(prev => prev.map(t => t.accountId === id ? { ...t, accountId: 'manual' } : t)); addToast('Account removed.', 'info'); }} formatCurrency={formatCurrency} userName={userName} userAvatar={userAvatar} userAvatarZoom={userAvatarZoom} userAvatarPos={userAvatarPos} userBorder={userBorder} onNavigate={setActiveTab} />}
            {activeTab === 'cashflow' && <CashflowBeta transactions={transactions} accounts={accounts} goals={goals} formatCurrency={formatCurrency} userPlan={userPlan} />}
            {activeTab === 'insights' && <Insights transactions={transactions} goals={goals} budgets={budgets} userPlan={userPlan} onUpgradeClick={() => setActiveTab('plans')} formatCurrency={formatCurrency} insightUsage={insightUsage} onIncrementUsage={() => setInsightUsage(prev => prev + 1)} onApplyBudgets={(newBudgets) => { const existingCats = new Set(budgets.map(b => b.category)); const toAdd = newBudgets.filter(b => !existingCats.has(b.category)); setBudgets(prev => [...prev, ...toAdd]); addToast(`Applied ${toAdd.length} AI limits.`, 'success'); }} initialPrompt={pendingChatQuery} onPromptHandled={() => setPendingChatQuery(null)} botMode={botMode} />}
            {activeTab === 'sandbox' && <ScenarioSandbox transactions={transactions} goals={goals} formatCurrency={formatCurrency} userPlan={userPlan} onUpgradeClick={() => setActiveTab('plans')} insightUsage={insightUsage} onIncrementUsage={(val) => setInsightUsage(prev => prev + (val || 1))} />}
            {activeTab === 'goals' && <Goals goals={goals} budgets={budgets} transactions={transactions} onAddGoal={(g) => { setGoals(prev => [...prev, g]); addToast('Goal deployed.', 'success'); }} onUpdateGoal={(g) => { setGoals(prev => prev.map(goal => goal.id === g.id ? g : goal)); addToast('Goal updated.', 'success'); }} onAddBudget={(b) => { setBudgets(prev => [...prev, b]); addToast('Limit set.', 'success'); }} onDeleteBudget={(id) => { setBudgets(prev => prev.filter(b => b.id !== id)); addToast('Limit removed.', 'info'); }} formatCurrency={formatCurrency} />}
            {activeTab === 'plans' && <Plans currentPlan={userPlan} onUpgrade={(plan) => { setUserPlan(plan); addToast(`Plan upgraded.`, 'success'); }} onDowngrade={() => { setUserPlan('free'); addToast('Plan reset.', 'info'); }} onNavigateDashboard={() => setActiveTab('dashboard')} />}
            {activeTab === 'upcoming' && <UpcomingFeatures />}
            {activeTab === 'settings' && <Settings userName={userName} userEmail={userEmail} userAvatar={userAvatar} userAvatarZoom={userAvatarZoom} userAvatarPos={userAvatarPos} userBorder={userBorder} userBackground={userBackground} onUpdateBackground={setUserBackground} userPlan={userPlan} onUpdateProfile={(n, e, a, z, p, b) => { setUserName(n); setUserEmail(e); setUserAvatar(a); setUserAvatarZoom(z); setUserAvatarPos(p); setUserBorder(b); addToast('Profile updated.', 'success'); }} addToast={addToast} onExportData={() => addToast('Exporting...')} onImportData={() => addToast('Importing...')} onClearData={() => addToast('Clearing...')} language={language} onUpdateLanguage={setLanguage} currency={currency} onUpdateCurrency={setCurrency} botMode={botMode} onUpdateBotMode={setBotMode} spendingLimit={spendingLimit} onUpdateSpendingLimit={setSpendingLimit} spendingPeriod={spendingPeriod} onUpdateSpendingPeriod={setSpendingPeriod} />}
        </div>
      </main>

      {isLogoutModalOpen && (
          <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/95 backdrop-blur-2xl animate-fade-in">
              <div className="bg-[#0f172a] border border-rose-500/30 rounded-[3rem] w-full max-w-sm shadow-[0_0_100px_rgba(244,63,94,0.2)] p-10 text-center animate-slide-up relative">
                  <div className="w-20 h-20 bg-rose-500/20 rounded-[2rem] flex items-center justify-center mx-auto mb-8 border border-rose-500/30"><ShieldX className="w-10 h-10 text-rose-500" /></div>
                  <h3 className="text-2xl font-black text-white mb-3 uppercase tracking-tighter">Terminate?</h3>
                  <div className="space-y-4">
                      <button onClick={confirmLogout} className="w-full py-4 bg-rose-600 hover:bg-rose-500 text-white font-black rounded-2xl shadow-xl transition-all">Sign Out</button>
                      <button onClick={() => setIsLogoutModalOpen(false)} className="w-full py-4 bg-slate-900/50 text-slate-400 font-bold rounded-2xl border border-white/5 hover:text-white transition-all">Stay Connected</button>
                  </div>
              </div>
          </div>
      )}

      <ToastContainer toasts={toasts} onRemove={removeToast} />
    </div>
  );
};

export default App;

export enum TransactionType {
  INCOME = 'INCOME',
  EXPENSE = 'EXPENSE',
}

export enum Category {
  HOUSING = 'Housing',
  FOOD = 'Food & Dining',
  TRANSPORT = 'Transportation',
  ENTERTAINMENT = 'Entertainment',
  SHOPPING = 'Shopping',
  UTILITIES = 'Utilities',
  HEALTH = 'Health',
  SUBSCRIPTION = 'Subscription',
  EDUCATION = 'Education',
  TRAVEL = 'Travel',
  PETS = 'Pets',
  KIDS = 'Kids',
  GIFTS = 'Gifts',
  SERVICES = 'Services',
  INCOME = 'Income',
  INVESTMENT = 'Investment',
  OTHER = 'Other'
}

export interface Transaction {
  id: string;
  date: string;
  merchant: string;
  amount: number;
  category: Category;
  type: TransactionType;
  accountId: string;
  notes?: string; 
}

export interface Account {
  id: string;
  name: string;
  nickname?: string; 
  type: 'Checking' | 'Savings' | 'Credit Card' | 'Investment' | 'Profile'; 
  balance: number;
  institution: string;
  color: string;
}

export interface FinancialInsight {
  title: string;
  description: string;
  type: 'success' | 'warning' | 'info' | 'critical';
  actionable?: boolean;
  metric?: string;
}

export interface BudgetSuggestion {
  category: string;
  current_spend: number;
  suggested_limit: number;
  reason: string;
}

export interface AIAnalysisResponse {
  insights: FinancialInsight[];
  budget_suggestions: BudgetSuggestion[];
  predicted_spend_next_month: number;
  risk_score: number; 
}

export interface SuggestedAction {
  label: string;
  actionId: string;
  payload?: string;
}

export interface ChatMessage {
  id: string;
  role: 'user' | 'assistant';
  content: string;
  timestamp: Date;
  sentiment?: 'info' | 'warning' | 'critical' | 'success';
  suggestedActions?: SuggestedAction[];
}

export interface Goal {
  id: string;
  name: string;
