export const chatWithFinancialCoach = async (
  currentMessage: string,
  history: ChatMessage[],
  snapshot: FinancialSnapshot,
  mode: BotMode = 'ruthless'
): Promise<{ message: string; sentiment: 'info' | 'warning' | 'critical'; suggestedActions: SuggestedAction[] }> => {
  checkRateLimit();

  // Create a condensed history context (last 5 messages) to save tokens
  const historyText = history
    .slice(-5)
    .map(m => `${m.role.toUpperCase()}: ${m.content}`)
    .join('\n');

  const persona = mode === 'ruthless'
    ? "You are a hedge fund risk manager. Be concise. Highlight variance. Do not use pleasantries. Focus on numbers. If spending is high, be critical."
    : "You are a financial wellness counselor. Use encouraging language. Focus on progress and constructive advice. Be supportive but realistic.";

  const systemInstruction = `${persona}
  You are Nova, an embedded financial AI.
  You have access to a 'FinancialSnapshot' of the user.
  Analyze the snapshot to answer the user's question.

  IMPORTANT: Return structured JSON.
  - 'sentiment': 'info' (neutral), 'warning' (caution), or 'critical' (danger).
  - 'suggestedActions': Array of 1-3 actions. 
    - Use actionId 'navigate_dashboard', 'navigate_transactions', 'navigate_goals', 'navigate_budget' to navigate.
    - Use actionId 'chat_prompt' for follow-up questions (payload = question text).
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `
        Financial Snapshot: ${JSON.stringify(snapshot)}

        Recent Conversation:
        ${historyText}

        User's New Question: ${currentMessage}
      `,
      config: {
        systemInstruction,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            message: { type: Type.STRING },
            sentiment: { type: Type.STRING, enum: ["info", "warning", "critical", "success"] },
            suggestedActions: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  label: { type: Type.STRING },
                  actionId: { type: Type.STRING },
                  payload: { type: Type.STRING },
                }
              }
            }
          }
        }
      }
    });

    if (response.text) {
        return JSON.parse(cleanJsonResponse(response.text));
    }
    throw new Error("No response generated");
  } catch (error) {
    console.error("Coach Chat Error", error);
    return {
        message: "I'm currently unable to process your financial data due to a connection issue.",
        sentiment: "critical",
        suggestedActions: []
    };
  }
};

export const parseReceiptImage = async (base64Image: string): Promise<{ merchant: string; date: string; amount: number; category: string } | null> => {
  try {
    checkRateLimit();
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview", 
      contents: {
        parts: [
          { inlineData: { mimeType: 'image/jpeg', data: base64Image } },
          { text: "Extract merchant, total amount (number), date (YYYY-MM-DD), and category. Return strictly JSON." }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            merchant: { type: Type.STRING },
            amount: { type: Type.NUMBER },
            date: { type: Type.STRING },
            category: { type: Type.STRING }
          }
        }
      }
    });
    return response.text ? JSON.parse(cleanJsonResponse(response.text)) : null;
  } catch (error) {
    return null;
  }
};

export const generateNegotiationScript = async (merchant: string, amount: number): Promise<string> => {
  try {
    checkRateLimit();
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Write a copy-paste script to negotiate a lower monthly bill for ${merchant} (Current: $${amount}). No greetings, just the body text.`,
    });
    return response.text?.trim() || "Unable to generate script.";
  } catch (error) {
    return "System busy.";
  }
};

import React, { useMemo, useState, useRef, useEffect } from 'react';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import { Account, Transaction, TransactionType, Category, UserPlan, Goal, Budget, SpendingStatus, SpendingPeriod } from '../types';
import { Activity, Flame, TrendingUp, Wallet, PlusCircle, CreditCard, Target, Quote, Landmark, Zap, Radio, Repeat, Check, Handshake, Copy, X, Loader2, Sparkles, ArrowUpRight, ArrowDownRight, LayoutGrid, ArrowRight, Pin, Square, CheckSquare, Microscope, PieChart, ShieldAlert, BrainCircuit, GripVertical, AlertTriangle } from 'lucide-react';
