export const chatWithFinancialCoach = async (
  currentMessage: string,
  history: ChatMessage[],
  snapshot: FinancialSnapshot,
  mode: BotMode = 'ruthless'
): Promise<{ message: string; sentiment: 'info' | 'warning' | 'critical'; suggestedActions: SuggestedAction[] }> => {
  checkRateLimit();

  // Create a condensed history context (last 5 messages) to save tokens
  const historyText = history
    .slice(-5)
    .map(m => `${m.role.toUpperCase()}: ${m.content}`)
    .join('\n');

  const persona = mode === 'ruthless'
    ? "You are a hedge fund risk manager. Be concise. Highlight variance. Do not use pleasantries. Focus on numbers. If spending is high, be critical."
    : "You are a financial wellness counselor. Use encouraging language. Focus on progress and constructive advice. Be supportive but realistic.";

  const systemInstruction = `${persona}
  You are Nova, an embedded financial AI.
  You have access to a 'FinancialSnapshot' of the user.
  Analyze the snapshot to answer the user's question.

  IMPORTANT: Return structured JSON.
  - 'sentiment': 'info' (neutral), 'warning' (caution), or 'critical' (danger).
  - 'suggestedActions': Array of 1-3 actions. 
    - Use actionId 'navigate_dashboard', 'navigate_transactions', 'navigate_goals', 'navigate_budget' to navigate.
    - Use actionId 'chat_prompt' for follow-up questions (payload = question text).
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `
        Financial Snapshot: ${JSON.stringify(snapshot)}

        Recent Conversation:
        ${historyText}

        User's New Question: ${currentMessage}
      `,
      config: {
        systemInstruction,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            message: { type: Type.STRING },
            sentiment: { type: Type.STRING, enum: ["info", "warning", "critical", "success"] },
            suggestedActions: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  label: { type: Type.STRING },
                  actionId: { type: Type.STRING },
                  payload: { type: Type.STRING },
                }
              }
            }
          }
        }
      }
    });

    if (response.text) {
        return JSON.parse(cleanJsonResponse(response.text));
    }
    throw new Error("No response generated");
  } catch (error) {
    console.error("Coach Chat Error", error);
    return {
        message: "I'm currently unable to process your financial data due to a connection issue.",
        sentiment: "critical",
        suggestedActions: []
    };
  }
};

