        }
        .pin-active .pin-mode-overlay { opacity: 1; pointer-events: auto; }
        .pin-active .pinnable-item { z-index: 60; position: relative; transform: scale(1.02); box-shadow: 0 0 30px rgba(99, 102, 241, 0.3); border-color: rgba(99, 102, 241, 0.5); cursor: pointer; }
      `}</style>

      <div className={`transition-all duration-500 ${isPinMode ? 'pin-active' : ''}`}>

          <div className="flex justify-between items-center relative z-40 mb-6">
            <div>
              <h2 className="text-3xl font-black text-white tracking-tighter uppercase italic">Control Room</h2>
              {!isPinMode && <p className="text-slate-400 text-xs font-bold uppercase tracking-widest mt-1">Financial performance for {today.toLocaleDateString('en-US', { month: 'long', year: 'numeric' })}</p>}
            </div>
          </div>

          {/* PINNED CLUSTER */}
          {pinnedIds.length > 0 && !isPinMode && (
              <div className="grid grid-cols-2 md:grid-cols-5 gap-3 mb-8 animate-slide-up">
                  {pinnedIds.map(id => {
                      const mod = pinnableModules.find(m => m.id === id);
                      if (!mod) return null;
                      return (
                          <div key={id} onClick={mod.onClick} className="bg-slate-900 border border-white/10 rounded-2xl p-4 flex flex-col justify-between hover:bg-slate-800 transition-all cursor-pointer group hover:border-white/20 h-full">
                              <div className="flex justify-between items-start mb-2">
                                  <div className={`p-2 rounded-lg ${mod.color} bg-opacity-20`}>{mod.icon}</div>
                                  <Pin className="w-3 h-3 text-indigo-400 fill-indigo-400 opacity-50" />
                              </div>
                              <div>
                                  <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest truncate">{mod.title}</h4>
                                  <p className="text-sm font-bold text-white truncate group-hover:text-indigo-400 transition-colors">{mod.value}</p>
                              </div>
                          </div>
                      );
                  })}
              </div>
          )}

          {/* SYSTEM MODULES (Pinnable Grid) */}
          <div className="relative group/pin-container">
              {isPinMode && <div className="pin-mode-overlay"></div>}

              <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8 relative">
                  {pinnableModules.map((mod) => {
                      const isPinned = pinnedIds.includes(mod.id);
                      return (
                          <div 
                            key={mod.id}
                            onMouseMove={handleCardMouseMove}
                            onClick={() => {
                                if (isPinMode && onTogglePin) {
                                    onTogglePin(mod.id);
                                } else if (!isPinMode) {
                                    trackEvent?.(mod.id);
                                    mod.onClick();
                                }
                            }}
                            style={{ '--spotlight-color': mod.spotlight } as React.CSSProperties}
                            className={`pinnable-item spotlight-card glass-card p-6 rounded-[2rem] border border-white/5 flex items-center gap-5 cursor-pointer h-full ${isPinMode ? 'hover:bg-slate-900' : ''}`}
                          >
                              <div className={`w-14 h-14 rounded-2xl flex items-center justify-center shadow-lg ${mod.color} relative z-10`}>{mod.icon}</div>
                              <div className="flex-1 min-w-0 relative z-10">
                                  <h4 className="text-xs font-black text-slate-400 uppercase tracking-widest">{mod.title}</h4>
                                  <div className="text-lg font-bold text-white tracking-tight truncate">{mod.value}</div>
                                  <p className="text-[10px] text-slate-500 font-medium truncate">{mod.subtext}</p>
                              </div>
                              {isPinMode && (
                                  <div className={`w-8 h-8 rounded-lg border-2 flex items-center justify-center transition-all relative z-10 ${isPinned ? 'bg-indigo-600 border-indigo-600' : 'border-white/20 bg-slate-950'}`}>
                                      {isPinned && <Check className="w-5 h-5 text-white" />}
                                  </div>
                              )}
                          </div>
                      );
                  })}
              </div>
          </div>

          {/* Standard Stats (Always Visible) */}
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 relative z-10">
            <StatCard 
                title="Net Worth" 
                value={formatCurrency(netWorth)} 
                icon={<Wallet className="w-5 h-5 text-indigo-400" />} 
                change={stats.nwChange.toFixed(1) + '%'} 
                positive={stats.nwChange >= 0} 
                delay="0s" 
                spotlightColor="rgba(99, 102, 241, 0.3)" // Indigo
                onMouseMove={handleCardMouseMove}
            />

            {/* ENFORCEMENT CARD REPLACES MONTHLY SPEND CARD */}
            <div 
                className={`spotlight-card glass-card p-8 rounded-[2.5rem] border transition-all shadow-lg group animate-slide-up ${spendingStatus?.colorClass || 'border-white/5'}`} 
                style={{ '--spotlight-color': getSpotlightColorForStatus(spendingStatus?.status || 'normal'), animationDelay: '0.1s' } as React.CSSProperties}
                onMouseMove={handleCardMouseMove}
            >
                <div className="flex justify-between items-start mb-6 relative z-10">
                    <div className="p-4 bg-slate-800 rounded-2xl border border-white/5 text-slate-400 shadow-inner">
                        {spendingStatus?.status === 'violation' ? <ShieldAlert className="w-5 h-5 text-rose-500" /> : spendingStatus?.status === 'warning' ? <AlertTriangle className="w-5 h-5 text-amber-400" /> : <CreditCard className="w-5 h-5 text-emerald-400" />}
                    </div>
                    <div className="text-right">
                        <div className="text-[9px] font-black uppercase tracking-widest text-slate-500 mb-1">{spendingPeriod} Limit</div>
                        <div className="text-xs font-bold text-white">{formatCurrency(spendingLimit || 0)}</div>
                    </div>
                </div>
                <div className="relative z-10">
                    <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-[0.3em] mb-1">Period Spend</h4>
                    <div className="text-3xl font-black text-white tracking-tighter">{formatCurrency(currentPeriodSpend)}</div>
                    <div className={`mt-2 text-[9px] font-black uppercase tracking-widest px-2 py-1 rounded w-fit ${spendingStatus?.status === 'violation' ? 'bg-rose-500 text-white' : spendingStatus?.status === 'warning' ? 'bg-amber-500 text-slate-900' : 'bg-emerald-500/20 text-emerald-400'}`}>
                        {spendingStatus?.message || 'Nominal'}
                    </div>
                </div>
            </div>

            <StatCard 
                title="Burn Rate/Day" 
                value={formatCurrency(stats.currentDailyAvg)} 
                icon={<Flame className="w-5 h-5 text-amber-400" />} 
                change={Math.abs(stats.burnChange).toFixed(1) + '%'} 
                positive={stats.burnChange <= 0} 
                delay="0.2s" 
                spotlightColor="rgba(245, 158, 11, 0.3)" // Amber
                onMouseMove={handleCardMouseMove}
            />
            <StatCard 
                title="Predicted Spend" 
                value={formatCurrency(stats.forecastedTotal)} 
                icon={<TrendingUp className="w-5 h-5 text-emerald-400" />} 
                change={Math.abs(stats.forecastChange).toFixed(1) + '%'} 
                positive={stats.forecastChange <= 0} 
                delay="0.3s"
                spotlightColor="rgba(16, 185, 129, 0.3)" // Emerald
                onMouseMove={handleCardMouseMove}
            />
          </div>

          <div 
            className="mt-8 spotlight-card glass-card p-8 md:p-10 rounded-[2.5rem] border border-white/5 animate-slide-up relative z-10"
            style={{ '--spotlight-color': 'rgba(99, 102, 241, 0.15)' } as React.CSSProperties}
            onMouseMove={handleCardMouseMove}
          >
              <h3 className="text-xl font-black text-white uppercase tracking-tight flex items-center gap-3 mb-10 relative z-10"><Activity className="w-7 h-7 text-indigo-400" />Expenditure Flux</h3>
              <div className="h-72 w-full relative z-10">
                  <ResponsiveContainer width="100%" height="100%">
                      <AreaChart data={[] /* Data populated in real app */}>
                          <CartesianGrid strokeDasharray="3 3" stroke="#1e293b" vertical={false} />
                          <XAxis hide />
                          <YAxis hide />
                          <Area type="monotone" dataKey="actual" stroke="#6366f1" strokeWidth={4} fill="url(#fluxGrad)" />
                      </AreaChart>
                  </ResponsiveContainer>
                  <div className="flex flex-col items-center justify-center h-full opacity-40 text-slate-500 font-bold uppercase tracking-widest text-xs absolute inset-0">Awaiting Transaction Stream...</div>
              </div>
          </div>
      </div>

      {showAnalysisConfirm && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm animate-fade-in">
            <div className="bg-slate-900 border border-white/10 rounded-3xl w-full max-w-md p-8 shadow-2xl animate-slide-up relative">
                <button onClick={() => setShowAnalysisConfirm(false)} className="absolute top-6 right-6 text-slate-500 hover:text-white transition-colors"><X className="w-6 h-6" /></button>
                <div className="flex items-center gap-4 mb-6">
                    <div className="w-14 h-14 rounded-2xl bg-indigo-500/20 flex items-center justify-center border border-indigo-500/30">
                        <BrainCircuit className="w-8 h-8 text-indigo-400" />
                    </div>
                    <div>
                        <h3 className="text-2xl font-black text-white tracking-tight">Neural Analysis</h3>
                        <p className="text-indigo-400 text-xs font-bold uppercase tracking-widest">Confirmation Required</p>
                    </div>
                </div>
                <p className="text-slate-300 text-base mb-8 leading-relaxed font-medium">
                    Scanning system alerts requires deep neural processing. This action will consume <span className="text-white font-bold bg-white/10 px-2 py-0.5 rounded">1 Analysis Token</span> from your monthly quota.
                </p>
                <div className="flex gap-4">
                    <button 
                        onClick={() => setShowAnalysisConfirm(false)}
                        className="flex-1 py-4 rounded-2xl bg-slate-800 text-slate-300 font-bold text-sm uppercase tracking-wider hover:bg-slate-700 transition-colors border border-white/5"
                    >
                        Cancel
                    </button>
                    <button 
                        onClick={() => {
                            setShowAnalysisConfirm(false);
                            onAskCoach?.('Show my active alerts');
                        }}
                        className="flex-1 py-4 rounded-2xl bg-indigo-600 text-white font-bold text-sm uppercase tracking-wider hover:bg-indigo-500 transition-all shadow-xl shadow-indigo-500/20 hover:scale-[1.02] active:scale-95"
                    >
                        Confirm Scan
                    </button>
                </div>
            </div>
        </div>
      )}
    </div>
  );
};

const StatCard: React.FC<{ 
    title: string, 
    value: string | React.ReactNode, 
    icon: React.ReactNode, 
    change?: string, 
    positive?: boolean, 
    delay: string,
    spotlightColor: string,
    onMouseMove: (e: React.MouseEvent<HTMLDivElement>) => void
}> = ({ title, value, icon, change, positive, delay, spotlightColor, onMouseMove }) => (
    <div 
        className="spotlight-card glass-card p-8 rounded-[2.5rem] border border-white/5 animate-slide-up h-full" 
        style={{ animationDelay: delay, '--spotlight-color': spotlightColor } as React.CSSProperties}
        onMouseMove={onMouseMove}
    >
        <div className="flex justify-between items-start mb-6 relative z-10">
            <div className="p-4 bg-slate-800 rounded-2xl border border-white/5 text-slate-400 group-hover:text-indigo-400 transition-colors shadow-inner">{icon}</div>
            {change && (
                <div className={`flex items-center gap-1 text-[11px] font-black uppercase tracking-widest ${positive ? 'text-emerald-500' : 'text-rose-500'}`}>
                    {positive ? <ArrowUpRight className="w-4 h-4" /> : <ArrowDownRight className="w-4 h-4" />}
                    {change}
                </div>
            )}
        </div>
        <div className="relative z-10">
            <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-[0.3em] mb-1">{title}</h4>
            <div className="text-3xl font-black text-white tracking-tighter">{value}</div>
        </div>
    </div>
);

export default Dashboard;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { Transaction, AIAnalysisResponse, ChatMessage, UserPlan, TransactionType, Budget, BotMode, Category, Goal, FinancialSnapshot, SuggestedAction, GoalProposal } from '../types';
import { analyzeFinancialData, chatWithFinancialCoach } from '../services/geminiService';
import { RefreshCcw, CheckCircle, AlertTriangle, ShieldAlert, Info, TrendingUp, Bot, User, BrainCircuit, Lightbulb, Send, Lock, Sparkles, RefreshCw, Flame, ArrowRight, Zap, Crown, TrendingDown, ShoppingCart, Wallet, Terminal, Activity, MousePointerClick, ChevronRight, Check, X, EyeOff, Target } from 'lucide-react';

interface InsightsProps {
  transactions: Transaction[];
  goals: Goal[];
  budgets: Budget[];
  userPlan: UserPlan;
  onUpgradeClick: () => void;
  formatCurrency: (amount: number) => string;
  initialPrompt?: string | null; 
  onPromptHandled?: () => void; 
  onApplyBudgets?: (budgets: Budget[]) => void; 
  insightUsage: number; 
  onIncrementUsage: () => void; 
  botMode: BotMode;
  onNavigate: (tab: string) => void;
  onAddGoal?: (goal: Goal) => void;
}

const Insights: React.FC<InsightsProps> = ({ transactions, goals, budgets, userPlan, onUpgradeClick, formatCurrency, initialPrompt, onPromptHandled, onApplyBudgets, insightUsage, onIncrementUsage, botMode, onNavigate, onAddGoal }) => {
  const [analysis, setAnalysis] = useState<AIAnalysisResponse | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [chatInput, setChatInput] = useState('');
  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([
    { 
        id: '1', 
        role: 'assistant', 
        content: botMode === 'ruthless' 
            ? 'System initialized. Ready to audit your spending vectors.' 
            : 'Hello! I\'m ready to help you optimize your financial wellness. What\'s on your mind?', 
        timestamp: new Date(),
        sentiment: 'info'
    }
  ]);
  const [chatLoading, setChatLoading] = useState(false);
  const [showRejectModal, setShowRejectModal] = useState<GoalProposal | null>(null);
  const [rejectionReason, setRejectionReason] = useState('');

  const chatEndRef = useRef<HTMLDivElement>(null);

  const isUltra = userPlan === 'ultra';
  const isElite = isUltra;
  const isPro = userPlan === 'pro';

  // Industrial Grade Limits
  const FREE_LIMIT = 3;
  const PRO_LIMIT = 50;
  const ULTRA_LIMIT = 1500;

  const currentLimit = isUltra ? ULTRA_LIMIT : isPro ? PRO_LIMIT : FREE_LIMIT;
  const isLocked = insightUsage >= currentLimit;

  // Logic Variables for UI (Raw Math)
  const burnoutData = useMemo(() => {
    const expenseMap = new Map<string, number>();
    transactions
        .filter(t => t.type === TransactionType.EXPENSE)
        .forEach(t => {
            expenseMap.set(t.category, (expenseMap.get(t.category) || 0) + t.amount);
        });

    let maxCat = '';
    let maxAmount = 0;
    expenseMap.forEach((val, key) => {
        if (val > maxAmount) {
            maxAmount = val;
            maxCat = key;
        }
    });
    return { category: maxCat, amount: maxAmount };
  }, [transactions]);

  const leakageData = useMemo(() => {
    const expenses = transactions.filter(t => t.type === TransactionType.EXPENSE);
    const totalExpense = expenses.reduce((acc, t) => acc + t.amount, 0);

    // Group by Category
    const catMap: Record<string, number> = {};
    expenses.forEach(t => {
        catMap[t.category] = (catMap[t.category] || 0) + t.amount;
    });

    const sortedCats = Object.entries(catMap).sort((a, b) => b[1] - a[1]);
    const topLeak = sortedCats[0] || ['None', 0];

    // "Impulse" or Discretionary - rough heuristic
    const discretionaryCats = [Category.SHOPPING, Category.ENTERTAINMENT, Category.FOOD, Category.SUBSCRIPTION];
    const discretionaryTotal = expenses
        .filter(t => discretionaryCats.includes(t.category))
        .reduce((acc, t) => acc + t.amount, 0);

    return {
        topCategory: topLeak[0],
        topAmount: topLeak[1],
        discretionaryTotal,
        totalExpense
    };
  }, [transactions]);

  // Manual Trigger Logic - Removed useEffect for auto-run
  const runAnalysis = async () => {
    if (isLocked) return;
    setLoading(true);
    setError(null);
    onIncrementUsage();
    try {
      const result = await analyzeFinancialData(transactions, userPlan);

      // Filter out recent rejections (7-day cooldown)
      if (result && result.goal_proposals) {
          const rejectedRaw = localStorage.getItem('nova_rejected_proposals');
          const rejectedList: {id: string, type: string, timestamp: number}[] = rejectedRaw ? JSON.parse(rejectedRaw) : [];
          const sevenDaysMs = 7 * 24 * 60 * 60 * 1000;

          result.goal_proposals = result.goal_proposals.filter(p => {
              const rejection = rejectedList.find(r => r.id === p.id || (r.type === p.type && p.title.includes(r.id))); // Heuristic matching
              if (!rejection) return true;
              return (Date.now() - rejection.timestamp) > sevenDaysMs;
          });
      }

      if (result) {
        setAnalysis(result);
      } else {
        setError("Coach is analyzing other portfolios. Try again.");
      }
    } catch (e) {
      setError("Unable to connect to financial brain.");
    } finally {
      setLoading(false);
    }
  };

  const handleAcceptProposal = (proposal: GoalProposal) => {
      if (proposal.type === 'goal' && onAddGoal) {
          onAddGoal({
              id: Date.now().toString(),
              name: proposal.title,
              targetAmount: proposal.target_amount,
              currentAmount: 0,
              deadline: proposal.deadline || new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
              icon: 'star',
              color: 'from-emerald-500 to-teal-500'
          });
      } else if (proposal.type === 'budget' && onApplyBudgets) {
          onApplyBudgets([{
              id: `ai_${Date.now()}`,
              category: (proposal.category as Category) || Category.OTHER,
              limit: proposal.target_amount
          }]);
      }

      // Remove from view
      if (analysis) {
          setAnalysis({
              ...analysis,
              goal_proposals: analysis.goal_proposals.filter(p => p.id !== proposal.id)
          });
      }
  };

  const handleRejectProposal = () => {
      if (!showRejectModal) return;

      const rejectedRaw = localStorage.getItem('nova_rejected_proposals');
      const rejectedList = rejectedRaw ? JSON.parse(rejectedRaw) : [];
      rejectedList.push({
          id: showRejectModal.id, // Or a simplified ID to track category/type
          type: showRejectModal.type,
          title: showRejectModal.title, // Use title for loose matching on re-proposal
          timestamp: Date.now(),
          reason: rejectionReason
      });
      localStorage.setItem('nova_rejected_proposals', JSON.stringify(rejectedList));

      // Remove from view
      if (analysis) {
          setAnalysis({
              ...analysis,
              goal_proposals: analysis.goal_proposals.filter(p => p.id !== showRejectModal.id)
          });
      }

      setShowRejectModal(null);
      setRejectionReason('');
  };

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [chatHistory, chatLoading]);

  useEffect(() => {
      if (!isLocked && initialPrompt && !chatLoading) {
          handleSendMessage(null, initialPrompt);
          if (onPromptHandled) onPromptHandled();
      }
  }, [initialPrompt, isLocked]);

  const handleSendMessage = async (e: React.FormEvent | null, promptOverride?: string) => {
    if (e) e.preventDefault();
    const content = promptOverride || chatInput;
    if (!content.trim() || isLocked) return;

    onIncrementUsage();
    const userMsg: ChatMessage = { id: Date.now().toString(), role: 'user', content: content, timestamp: new Date() };
    setChatHistory(prev => [...prev, userMsg]);
    setChatInput('');
    setChatLoading(true);

    // Build Financial Snapshot (Client-Side Logic)
    const now = new Date();
    const currentMonthTxs = transactions.filter(t => new Date(t.date).getMonth() === now.getMonth());
    const income = currentMonthTxs.filter(t => t.type === TransactionType.INCOME).reduce((sum, t) => sum + t.amount, 0);
    const expense = currentMonthTxs.filter(t => t.type === TransactionType.EXPENSE).reduce((sum, t) => sum + t.amount, 0);

    // Calculate top category
    const catMap: Record<string, number> = {};
    currentMonthTxs.filter(t => t.type === TransactionType.EXPENSE).forEach(t => { catMap[t.category] = (catMap[t.category] || 0) + t.amount; });
    const topCat = Object.entries(catMap).sort((a,b) => b[1] - a[1])[0];

    const snapshot: FinancialSnapshot = {
        currentMonthMetrics: {
            income,
            expense,
            savingsRate: income > 0 ? (income - expense) / income : 0,
            topExpenseCategory: topCat ? topCat[0] : 'None'
        },
        recentTransactions: transactions.slice(0, 10), // Context-Aware Agent (Limited to 10)
        activeGoals: goals,
        budgets: budgets
    };

    const response = await chatWithFinancialCoach(userMsg.content, chatHistory, snapshot, botMode);

    const aiMsg: ChatMessage = { 
        id: (Date.now() + 1).toString(), 
        role: 'assistant', 
        content: response.message, 
        timestamp: new Date(),
        sentiment: response.sentiment as any,
        suggestedActions: response.suggestedActions
    };

    setChatHistory(prev => [...prev, aiMsg]);
    setChatLoading(false);
  };

  const handleActionClick = (action: SuggestedAction) => {
      if (action.actionId.startsWith('navigate_')) {
          const tab = action.actionId.replace('navigate_', '');
          onNavigate(tab);
      } else {
          // Assume it's a chat prompt or generic ID
          handleSendMessage(null, action.payload || action.label);
      }
  };

  const handleAutoTune = () => {
      if (!analysis || !onApplyBudgets) return;
      const newBudgets: Budget[] = analysis.budget_suggestions.map(bs => ({
          id: `ai_${Date.now()}_${bs.category}`,
          category: bs.category as any,
          limit: bs.suggested_limit
      }));
      onApplyBudgets(newBudgets);
  };

  const getColorClass = (type: string) => {
    switch (type) {
        case 'success': return 'bg-emerald-500/10 border-emerald-500/20 text-emerald-100 shadow-[0_4px_20px_rgba(16,185,129,0.1)]';
        case 'warning': return 'bg-amber-500/10 border-amber-500/20 text-amber-100 shadow-[0_4px_20px_rgba(245,158,11,0.1)]';
        case 'critical': return 'bg-rose-500/10 border-rose-500/20 text-rose-100 shadow-[0_4px_20px_rgba(244,63,94,0.1)]';
        default: return 'bg-blue-500/10 border-blue-500/20 text-blue-100 shadow-[0_4px_20px_rgba(59,130,246,0.1)]';
    }
  };

  const getIconForType = (type: string) => {
      switch (type) {
        case 'success': return <CheckCircle className="w-5 h-5 text-emerald-400" />;
        case 'warning': return <AlertTriangle className="w-5 h-5 text-amber-400" />;
        case 'critical': return <ShieldAlert className="w-5 h-5 text-rose-400" />;
        default: return <Info className="w-5 h-5 text-blue-400" />;
      }
    };

  const getChatBubbleStyle = (role: string, sentiment?: string) => {
      if (role === 'user') return 'bg-indigo-600 text-white border-indigo-500/50';

      switch (sentiment) {
          case 'critical': return 'bg-rose-950/40 border-rose-500/30 text-rose-100 shadow-[0_0_15px_rgba(244,63,94,0.2)]';
          case 'warning': return 'bg-amber-950/40 border-amber-500/30 text-amber-100 shadow-[0_0_15px_rgba(245,158,11,0.2)]';
          case 'success': return 'bg-emerald-950/40 border-emerald-500/30 text-emerald-100 shadow-[0_0_15px_rgba(16,185,129,0.2)]';
          default: return 'bg-slate-800/80 border-white/10 text-slate-200';
      }
  };

  return (
    <div className="relative h-[calc(100vh-8rem)]">
      {isLocked && (
        <div className="absolute inset-0 z-50 flex items-center justify-center bg-slate-950/60 backdrop-blur-xl rounded-[2rem] border border-white/10 transform scale-105 transition-transform duration-500">
            <div className="text-center p-8 max-w-md animate-slide-up">
                <div className="w-20 h-20 rounded-3xl bg-gradient-to-tr from-indigo-500 to-purple-500 flex items-center justify-center mx-auto mb-6 shadow-2xl shadow-indigo-500/40"><Lock className="w-10 h-10 text-white" /></div>
                <h2 className="text-3xl font-bold text-white mb-3">Limit Reached</h2>
                <p className="text-slate-400 mb-8 leading-relaxed">
                    You've hit your monthly cap of {currentLimit} interactions for your {userPlan.toUpperCase()} plan. Upgrade or manage your plan to continue using the AI Coach.
                </p>
                {!isUltra && (
