import React, { useMemo, useState, useRef, useEffect } from 'react';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, PieChart, Pie, Cell } from 'recharts';
import { Account, Transaction, TransactionType, Category, UserPlan, Goal, Budget, SpendingStatus, SpendingPeriod } from '../types';
import { Activity, Flame, TrendingUp, Wallet, PlusCircle, CreditCard, Target, Quote, Landmark, Zap, Radio, Repeat, Check, Handshake, Copy, X, Loader2, Sparkles, ArrowUpRight, ArrowDownRight, LayoutGrid, ArrowRight, Pin, Square, CheckSquare, Microscope, PieChart as PieChartIcon, ShieldAlert, BrainCircuit, GripVertical, AlertTriangle, Layers, Circle } from 'lucide-react';
import { generateNegotiationScript } from '../services/geminiService';

interface DashboardProps {
  accounts: Account[];
  transactions: Transaction[];
  goals: Goal[];
  budgets: Budget[];
  onNavigate: (tab: string) => void;
  onAddAccount?: () => void;
  onAddTransaction?: () => void;
  onAddGoal?: () => void;
  formatCurrency: (amount: number) => string | React.ReactNode;
  userPlan?: UserPlan;
  onAskCoach?: (message: string) => void;
  negotiationUsage: number;
  onIncrementNegotiation: () => void;
  isPinMode?: boolean;
  pinnedIds?: string[];
  onTogglePin?: (id: string) => void;
  trackEvent?: (id: string) => void;
  insightUsage?: number;
  // New enforcement props
  spendingStatus?: SpendingStatus;
  currentPeriodSpend?: number;
  spendingLimit?: number;
  spendingPeriod?: SpendingPeriod;
}

const QUOTES = [
  { text: "Do not save what is left after spending, but spend what is left after saving.", author: "Warren Buffett" },
  { text: "A budget is telling your money where to go instead of wondering where it went.", author: "Dave Ramsey" },
  { text: "It's not your salary that makes you rich, it's your spending habits.", author: "Charles A. Jaffe" },
];

const COLORS = ['#6366f1', '#f43f5e', '#f59e0b', '#10b981', '#8b5cf6', '#06b6d4', '#ec4899', '#64748b'];

const Dashboard: React.FC<DashboardProps> = ({ 
    accounts, 
    transactions, 
    goals, 
    budgets,
    onNavigate, 
    onAddAccount, 
    onAddTransaction, 
    onAddGoal, 
    formatCurrency, 
    userPlan, 
    onAskCoach, 
    negotiationUsage, 
    onIncrementNegotiation,
    isPinMode = false,
    pinnedIds = [],
    onTogglePin,
    trackEvent,
    insightUsage = 0,
    spendingStatus,
    currentPeriodSpend = 0,
    spendingLimit = 1000,
    spendingPeriod = 'monthly'
}) => {
  const hasData = accounts.length > 0 || transactions.length > 0;
  const randomQuote = useMemo(() => QUOTES[Math.floor(Math.random() * QUOTES.length)], []);
  const netWorth = useMemo(() => accounts.reduce((acc, curr) => acc + curr.balance, 0), [accounts]);

  const [isNegotiating, setIsNegotiating] = useState(false);
  const [script, setScript] = useState<string | null>(null);
  const [scriptMerchant, setScriptMerchant] = useState('');
  const [showNegotiationModal, setShowNegotiationModal] = useState(false);
  const [copySuccess, setCopySuccess] = useState(false);
  const [showAnalysisConfirm, setShowAnalysisConfirm] = useState(false);

  const today = new Date();
  const currentMonth = today.getMonth();
  const currentYear = today.getFullYear();
  const currentDay = today.getDate();
  const daysInMonth = new Date(currentYear, currentMonth + 1, 0).getDate();

  const stats = useMemo(() => {
    const currentMTDExpenses = transactions.filter(t => {
      const d = new Date(t.date);
      return t.type === TransactionType.EXPENSE && d.getMonth() === currentMonth && d.getFullYear() === currentYear;
    });
    const currentMTDTotal = currentMTDExpenses.reduce((acc, t) => acc + t.amount, 0);

    const prevMonthDate = new Date(currentYear, currentMonth - 1, 1);
    const prevMonth = prevMonthDate.getMonth();
    const prevMonthYear = prevMonthDate.getFullYear();

    const prevMTDExpenses = transactions.filter(t => {
      const d = new Date(t.date);
      return t.type === TransactionType.EXPENSE && d.getMonth() === prevMonth && d.getFullYear() === prevMonthYear && d.getDate() <= currentDay;
    });
    const prevMTDTotal = prevMTDExpenses.reduce((acc, t) => acc + t.amount, 0);
    const spendChange = prevMTDTotal > 0 ? ((currentMTDTotal - prevMTDTotal) / prevMTDTotal) * 100 : 0;

    const mtdNetFlow = transactions
      .filter(t => {
        const d = new Date(t.date);
        return d.getMonth() === currentMonth && d.getFullYear() === currentYear;
      })
      .reduce((acc, t) => acc + (t.type === TransactionType.INCOME ? t.amount : -t.amount), 0);
    const monthStartNW = netWorth - mtdNetFlow;
    const nwChange = monthStartNW !== 0 ? (mtdNetFlow / Math.abs(monthStartNW)) * 100 : 0;

    const currentDailyAvg = currentMTDTotal / Math.max(currentDay, 1);
    const forecastedTotal = currentDailyAvg * daysInMonth;

    return { currentMTDTotal, spendChange, nwChange, currentDailyAvg, forecastedTotal };
  }, [transactions, currentMonth, currentYear, currentDay, netWorth, daysInMonth]);

  // Data for Expenditure Topology (Pie Chart)
  const expenditureData = useMemo(() => {
    const expenses = transactions.filter(t => 
        t.type === TransactionType.EXPENSE && 
        new Date(t.date).getMonth() === currentMonth &&
        new Date(t.date).getFullYear() === currentYear
    );

    const total = expenses.reduce((acc, t) => acc + t.amount, 0);

    const catMap: Record<string, number> = {};

    expenses.forEach(t => {
        catMap[t.category] = (catMap[t.category] || 0) + t.amount;
    });

    const chartData = Object.entries(catMap)
        .map(([name, value]) => ({ name, value }))
        .sort((a, b) => b.value - a.value);

    const topCategories = chartData
        .slice(0, 4)
        .map((item) => ({ ...item, percent: total > 0 ? (item.value / total) * 100 : 0 }));

    return { chartData, topCategories, total };
  }, [transactions, currentMonth, currentYear]);

  const pinnableModules = useMemo(() => {
      // 1. Budget Monitor (Breaches)
      const overBudgetCount = budgets.filter(b => {
          const spent = transactions.filter(t => t.category === b.category && t.type === TransactionType.EXPENSE && new Date(t.date).getMonth() === currentMonth).reduce((acc, t) => acc + t.amount, 0);
          return spent > b.limit;
      }).length;

      // 2. Goal Vector (Global Spending Limit Utilization)
      const budgetUtilization = spendingLimit > 0 ? (currentPeriodSpend / spendingLimit) * 100 : 0;

      const budgetDetails = budgets.map(b => {
          const spent = transactions
            .filter(t => t.category === b.category && t.type === TransactionType.EXPENSE && new Date(t.date).getMonth() === currentMonth)
            .reduce((acc, t) => acc + t.amount, 0);
          return { 
              name: b.category, 
              limit: b.limit, 
              spent, 
              percent: b.limit > 0 ? (spent / b.limit) * 100 : 0 
          };
      }).sort((a, b) => b.percent - a.percent).slice(0, 4);

      // 3. System Alerts
      const alertsCount = overBudgetCount + (stats.spendChange > 10 ? 1 : 0);

      // 4. Token Logic (Remaining)
      const limit = userPlan === 'ultra' ? 1500 : userPlan === 'pro' ? 50 : 3;
      const remaining = Math.max(0, limit - (insightUsage || 0));

      return [
          {
              id: 'budget-monitor',
              title: 'Budget Integrity',
              icon: <PieChartIcon className="w-5 h-5 text-white" />,
              value: overBudgetCount > 0 ? `${overBudgetCount} Breaches` : 'Secure',
              subtext: overBudgetCount > 0 ? 'Immediate audit required' : 'All limits respected',
              color: overBudgetCount > 0 ? 'bg-rose-600' : 'bg-emerald-600',
              spotlight: overBudgetCount > 0 ? 'rgba(244, 63, 94, 0.4)' : 'rgba(16, 185, 129, 0.4)',
              onClick: () => onNavigate('goals')
          },
          {
              id: 'sandbox-link',
              title: 'Sim Sandbox',
              icon: <Microscope className="w-5 h-5 text-white" />,
              value: 'Predictive Core',
              subtext: 'Run ghost scenarios',
              color: 'bg-indigo-600',
              spotlight: 'rgba(99, 102, 241, 0.4)',
              onClick: () => onNavigate('sandbox')
          },
          {
              id: 'goal-tracker',
              title: 'Goal Vector',
              icon: <Target className="w-5 h-5 text-white" />,
              value: spendingLimit > 0 ? formatCurrency(spendingLimit) : 'No Limit',
              subtext: spendingLimit > 0 ? `${budgetUtilization.toFixed(0)}% of Global Limit` : 'Define spending limit',
              color: budgetUtilization > 100 ? 'bg-red-700' : 'bg-rose-600', 
              spotlight: 'rgba(225, 29, 72, 0.4)', 
              progress: budgetUtilization,
              details: budgetDetails, 
              span: 'md:col-start-3 md:row-span-2',
              onClick: () => onNavigate('goals')
          },
          {
              id: 'system-alerts',
              title: 'System Alerts',
              icon: <ShieldAlert className="w-5 h-5 text-white" />,
              value: alertsCount > 0 ? `${alertsCount} Active` : 'Nominal',
              subtext: alertsCount > 0 ? 'Review diagnostic' : 'Systems nominal',
              color: alertsCount > 0 ? 'bg-orange-600' : 'bg-slate-600',
              spotlight: alertsCount > 0 ? 'rgba(234, 88, 12, 0.4)' : 'rgba(148, 163, 184, 0.4)',
              onClick: () => setShowAnalysisConfirm(true)
          },
          {
              id: 'neural-quota',
              title: 'Neural Capacity',
              icon: <BrainCircuit className="w-5 h-5 text-white" />,
              value: `${remaining} Remaining`,
              subtext: `Monthly Cap: ${limit}`,
              color: remaining === 0 ? 'bg-rose-600' : remaining < 10 ? 'bg-amber-600' : 'bg-purple-600',
              spotlight: 'rgba(168, 85, 247, 0.4)',
              onClick: () => onNavigate('plans')
          }
      ];
  }, [budgets, transactions, goals, stats, insightUsage, onNavigate, onAskCoach, currentMonth, userPlan, spendingLimit, currentPeriodSpend]);

  const getSpotlightColorForStatus = (status: string) => {
      switch (status) {
          case 'violation': return 'rgba(244, 63, 94, 0.3)'; // Red
          case 'warning': return 'rgba(245, 158, 11, 0.3)'; // Amber
          default: return 'rgba(16, 185, 129, 0.3)'; // Emerald
      }
  };

  const handleCardMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
      const rect = e.currentTarget.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;
      e.currentTarget.style.setProperty('--mouse-x', `${x}px`);
      e.currentTarget.style.setProperty('--mouse-y', `${y}px`);
  };

  if (!hasData) return (
    <div className="flex flex-col items-center justify-center min-h-[70vh] text-center animate-fade-in relative px-6">
        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-96 h-96 bg-indigo-600/10 rounded-full blur-[100px] pointer-events-none"></div>
        <div className="w-20 h-20 bg-slate-900 border border-white/10 rounded-3xl flex items-center justify-center mb-8 rotate-6 shadow-2xl relative z-10"><Quote className="w-10 h-10 text-indigo-400" /></div>
        <h1 className="text-4xl font-black text-white mb-4 uppercase tracking-tighter italic relative z-10">Vault Initializing...</h1>
        <p className="text-slate-400 max-w-md italic mb-12 relative z-10">"{randomQuote.text}" — {randomQuote.author}</p>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6 w-full max-w-4xl relative z-10">
             <button onClick={onAddAccount} className="p-8 bg-slate-900/60 backdrop-blur-xl border border-white/5 rounded-[2.5rem] hover:border-indigo-500 transition-all text-left shadow-xl hover:-translate-y-1 group"><Landmark className="w-8 h-8 text-indigo-400 mb-6 group-hover:scale-110 transition-transform" /><h3 className="text-xl font-bold text-white mb-2">Sync Nodes</h3><p className="text-slate-500 text-sm">Link bank or manual ledgers.</p></button>
             <button onClick={onAddTransaction} className="p-8 bg-slate-900/60 backdrop-blur-xl border border-white/5 rounded-[2.5rem] hover:border-indigo-500 transition-all text-left shadow-xl hover:-translate-y-1 group"><PlusCircle className="w-8 h-8 text-indigo-400 mb-6 group-hover:scale-110 transition-transform" /><h3 className="text-xl font-bold text-white mb-2">Record Spend</h3><p className="text-slate-500 text-sm">Archive current activity.</p></button>
             <button onClick={onAddGoal} className="p-8 bg-slate-900/60 backdrop-blur-xl border border-white/5 rounded-[2.5rem] hover:border-indigo-500 transition-all text-left shadow-xl hover:-translate-y-1 group"><Target className="w-8 h-8 text-indigo-400 mb-6 group-hover:scale-110 transition-transform" /><h3 className="text-xl font-bold text-white mb-2">Set Objectives</h3><p className="text-slate-500 text-sm">Deploy capital milestones.</p></button>
        </div>
    </div>
  );

  return (
    <div className="space-y-6 pb-10 relative">
      <style>{`
        .spotlight-card { 
            position: relative; 
            overflow: hidden; 
            transition: transform 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94), box-shadow 0.3s ease;
            --mouse-x: -100px;
            --mouse-y: -100px;
            --spotlight-color: rgba(255, 255, 255, 0.1);
        }
        .spotlight-card::before { 
            content: ""; 
            position: absolute; 
            inset: 0; 
            background: radial-gradient(500px circle at var(--mouse-x) var(--mouse-y), var(--spotlight-color), transparent 40%); 
            z-index: 0; 
            pointer-events: none; 
            opacity: 0;
            transition: opacity 0.3s ease;
        }
        .spotlight-card:hover::before {
            opacity: 1;
        }
        .spotlight-card:hover {
            transform: translateY(-2px);
            box-shadow: 0 10px 40px -10px rgba(0,0,0,0.5);
        }
        .pin-mode-overlay {
            position: absolute; inset: -20px; background: rgba(2, 6, 23, 0.85); backdrop-filter: blur(4px); z-index: 50; border-radius: 2rem; pointer-events: none; opacity: 0; transition: opacity 0.3s;
        }
        .pin-active .pin-mode-overlay { opacity: 1; pointer-events: auto; }
        .pin-active .pinnable-item { z-index: 60; position: relative; transform: scale(1.02); box-shadow: 0 0 30px rgba(99, 102, 241, 0.3); border-color: rgba(99, 102, 241, 0.5); cursor: pointer; }
      `}</style>

      <div className={`transition-all duration-500 ${isPinMode ? 'pin-active' : ''}`}>

          <div className="flex justify-between items-center relative z-40 mb-6">
            <div>
              <h2 className="text-3xl font-black text-white tracking-tighter uppercase italic">Control Room</h2>
              {!isPinMode && <p className="text-slate-400 text-xs font-bold uppercase tracking-widest mt-1">Financial performance for {today.toLocaleDateString('en-US', { month: 'long', year: 'numeric' })}</p>}
            </div>
          </div>

          {/* PINNED CLUSTER */}
          {pinnedIds.length > 0 && !isPinMode && (
              <div className="grid grid-cols-2 md:grid-cols-5 gap-3 mb-8 animate-slide-up">
                  {pinnedIds.map(id => {
                      const mod = pinnableModules.find(m => m.id === id);
                      if (!mod) return null;
                      return (
                          <div key={id} onClick={mod.onClick} className="bg-slate-900 border border-white/10 rounded-2xl p-4 flex flex-col justify-between hover:bg-slate-800 transition-all cursor-pointer group hover:border-white/20 h-full">
                              <div className="flex justify-between items-start mb-2">
                                  <div className={`p-2 rounded-lg ${mod.color} bg-opacity-20`}>{mod.icon}</div>
                                  <Pin className="w-3 h-3 text-indigo-400 fill-indigo-400 opacity-50" />
                              </div>
                              <div>
                                  <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest truncate">{mod.title}</h4>
                                  <p className="text-sm font-bold text-white truncate group-hover:text-indigo-400 transition-colors">{mod.value}</p>
                              </div>
                          </div>
                      );
                  })}
              </div>
          )}

          {/* SYSTEM MODULES (Pinnable Grid) */}
          <div className="relative group/pin-container">
              {isPinMode && <div className="pin-mode-overlay"></div>}

              <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8 relative auto-rows-fr">
                  {pinnableModules.map((mod) => {
                      const isPinned = pinnedIds.includes(mod.id);
                      const spanClass = mod.id === 'goal-tracker' ? mod.span : '';
                      const isGoalTracker = mod.id === 'goal-tracker';

                      return (
                          <div 
                            key={mod.id}
                            onMouseMove={handleCardMouseMove}
                            onClick={() => {
                                if (isPinMode && onTogglePin) {
                                    onTogglePin(mod.id);
                                } else if (!isPinMode) {
                                    trackEvent?.(mod.id);
                                    mod.onClick();
                                }
                            }}
                            style={{ '--spotlight-color': mod.spotlight } as React.CSSProperties}
                            className={`pinnable-item spotlight-card glass-card p-6 rounded-[2rem] border border-white/5 flex flex-col ${isGoalTracker ? 'justify-start gap-6' : 'justify-between gap-5'} cursor-pointer h-full ${spanClass} ${isPinMode ? 'hover:bg-slate-900' : ''}`}
                          >
                              <div className="flex items-start justify-between w-full relative z-10">
                                  <div className={`w-14 h-14 rounded-2xl flex items-center justify-center shadow-lg ${mod.color} shrink-0`}>{mod.icon}</div>
                                  {isPinMode && (
                                      <div className={`w-8 h-8 rounded-lg border-2 flex items-center justify-center transition-all ${isPinned ? 'bg-indigo-600 border-indigo-600' : 'border-white/20 bg-slate-950'}`}>
                                          {isPinned && <Check className="w-5 h-5 text-white" />}
                                      </div>
                                  )}
                              </div>

                              <div className={`flex-1 min-w-0 relative z-10 flex flex-col ${isGoalTracker ? 'justify-start pt-2' : 'justify-end'}`}>
                                  <h4 className="text-xs font-black text-slate-400 uppercase tracking-widest mb-1">{mod.title}</h4>
                                  <div className="text-2xl font-bold text-white tracking-tight truncate">{mod.value}</div>
                                  <p className="text-[10px] text-slate-500 font-medium truncate mt-1">
                                      {mod.subtext}
                                  </p>

                                  {/* Progress bar visual for Goal Vector */}
                                  {isGoalTracker && (mod as any).progress !== undefined && (
                                      <div className="mt-8">
                                          <div className="flex justify-between text-[10px] font-bold text-slate-500 mb-2 uppercase tracking-wider">
                                              <span>Global Limit Usage</span>
                                              <span>{(mod as any).progress.toFixed(0)}%</span>
                                          </div>
                                          <div className="w-full h-2 bg-slate-800 rounded-full overflow-hidden border border-white/5">
                                              <div 
                                                  className={`h-full transition-all duration-1000 ease-out ${(mod as any).progress > 100 ? 'bg-red-500' : (mod as any).progress > 80 ? 'bg-orange-500' : 'bg-rose-500'}`} 
                                                  style={{ width: `${Math.min((mod as any).progress, 100)}%` }}
                                              ></div>
                                          </div>
                                      </div>
                                  )}

                                  {/* Detailed List of Budgets for Goal Vector */}
                                  {isGoalTracker && (mod as any).details && (mod as any).details.length > 0 && (
                                      <div className="mt-6 space-y-3 flex-1 overflow-hidden">
                                          <div className="h-px bg-white/5 w-full mb-4"></div>
                                          {(mod as any).details.map((b: any, i: number) => (
                                              <div key={i} className="group/item">
                                                  <div className="flex justify-between text-[10px] font-bold text-slate-400 mb-1">
                                                      <span className="text-white">{b.name}</span>
                                                      <span>{formatCurrency(b.spent)} / {formatCurrency(b.limit)}</span>
                                                  </div>
                                                  <div className="w-full h-1 bg-slate-800 rounded-full overflow-hidden">
                                                      <div 
                                                          className={`h-full rounded-full ${b.percent > 100 ? 'bg-red-500' : b.percent > 80 ? 'bg-orange-500' : 'bg-rose-500'}`} 
                                                          style={{ width: `${Math.min(b.percent, 100)}%` }}
                                                      ></div>
                                                  </div>
                                              </div>
                                          ))}
                                      </div>
                                  )}
                              </div>
                          </div>
                      );
                  })}
              </div>
          </div>

          {/* Standard Stats (Always Visible) */}
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 relative z-10">
            <StatCard 
                title="Net Worth" 
                value={formatCurrency(netWorth)} 
                icon={<Wallet className="w-5 h-5 text-indigo-400" />} 
                change={stats.nwChange.toFixed(1) + '%'} 
                positive={stats.nwChange >= 0} 
                delay="0s" 
                spotlightColor="rgba(99, 102, 241, 0.3)" // Indigo
                onMouseMove={handleCardMouseMove}
            />

            <div 
                className={`spotlight-card glass-card p-8 rounded-[2.5rem] border transition-all shadow-lg group animate-slide-up ${spendingStatus?.colorClass || 'border-white/5'}`} 
                style={{ '--spotlight-color': getSpotlightColorForStatus(spendingStatus?.status || 'normal'), animationDelay: '0.1s' } as React.CSSProperties}
                onMouseMove={handleCardMouseMove}
            >
                <div className="flex justify-between items-start mb-6 relative z-10">
                    <div className="p-4 bg-slate-800 rounded-2xl border border-white/5 text-slate-400 shadow-inner">
                        {spendingStatus?.status === 'violation' ? <ShieldAlert className="w-5 h-5 text-rose-500" /> : spendingStatus?.status === 'warning' ? <AlertTriangle className="w-5 h-5 text-amber-400" /> : <CreditCard className="w-5 h-5 text-emerald-400" />}
                    </div>
                    <div className="text-right">
                        <div className="text-[9px] font-black uppercase tracking-widest text-slate-500 mb-1">{spendingPeriod} Limit</div>
                        <div className="text-xs font-bold text-white">{formatCurrency(spendingLimit || 0)}</div>
                    </div>
                </div>
                <div className="relative z-10">
                    <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-[0.3em] mb-1">Period Spend</h4>
                    <div className="text-3xl font-black text-white tracking-tighter">{formatCurrency(currentPeriodSpend)}</div>
                    <div className={`mt-2 text-[9px] font-black uppercase tracking-widest px-2 py-1 rounded w-fit ${spendingStatus?.status === 'violation' ? 'bg-rose-500 text-white' : spendingStatus?.status === 'warning' ? 'bg-amber-500 text-slate-900' : 'bg-emerald-500/20 text-emerald-400'}`}>
                        {spendingStatus?.message || 'Nominal'}
                    </div>
                </div>
            </div>

            <StatCard 
                title="Burn Rate/Day" 
                value={formatCurrency(stats.currentDailyAvg)} 
                icon={<Flame className="w-5 h-5 text-amber-400" />} 
                change={Math.abs(stats.burnChange).toFixed(1) + '%'} 
                positive={stats.burnChange <= 0} 
                delay="0.2s" 
                spotlightColor="rgba(245, 158, 11, 0.3)" // Amber
                onMouseMove={handleCardMouseMove}
            />
            <StatCard 
                title="Predicted Spend" 
                value={formatCurrency(stats.forecastedTotal)} 
                icon={<TrendingUp className="w-5 h-5 text-emerald-400" />} 
                change={Math.abs(stats.forecastChange).toFixed(1) + '%'} 
                positive={stats.forecastChange <= 0} 
                delay="0.3s"
                spotlightColor="rgba(16, 185, 129, 0.3)" // Emerald
                onMouseMove={handleCardMouseMove}
            />
          </div>

          <div 
            className="mt-8 spotlight-card glass-card p-8 md:p-10 rounded-[2.5rem] border border-white/5 animate-slide-up relative z-10"
            style={{ '--spotlight-color': 'rgba(99, 102, 241, 0.15)' } as React.CSSProperties}
            onMouseMove={handleCardMouseMove}
          >
              <h3 className="text-xl font-black text-white uppercase tracking-tight flex items-center gap-3 mb-10 relative z-10"><Layers className="w-7 h-7 text-indigo-400" />Expenditure Topology</h3>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-8 items-center relative z-10">
                  <div className="flex justify-center relative h-64">
                      {expenditureData.total > 0 ? (
                          <ResponsiveContainer width="100%" height="100%">
                              <PieChart>
                                  <Pie
                                      data={expenditureData.chartData}
                                      cx="50%"
                                      cy="50%"
                                      innerRadius={60}
                                      outerRadius={80}
                                      paddingAngle={5}
                                      dataKey="value"
                                      stroke="none"
                                  >
                                      {expenditureData.chartData.map((entry, index) => (
                                          <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                                      ))}
                                  </Pie>
                                  <Tooltip 
                                      contentStyle={{ backgroundColor: '#0f172a', borderColor: '#1e293b', borderRadius: '12px', fontSize: '12px' }}
                                      itemStyle={{ color: '#fff', fontWeight: 'bold' }}
                                      formatter={(value: number) => formatCurrency(value)}
                                  />
                                  <text x="50%" y="50%" textAnchor="middle" dominantBaseline="middle" className="fill-white font-black" style={{ fontSize: '18px', fontWeight: 900 }}>
                                      {formatCurrency(expenditureData.total)}
                                  </text>
                                  <text x="50%" y="50%" dy={20} textAnchor="middle" dominantBaseline="middle" className="fill-slate-500 text-[10px] font-bold uppercase tracking-widest">
                                      Total
                                  </text>
                              </PieChart>
                          </ResponsiveContainer>
                      ) : (
                          <div className="relative w-48 h-48 rounded-full border-4 border-slate-800 border-dashed flex flex-col items-center justify-center opacity-50">
                              <span className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">No Data</span>
                              <span className="text-[9px] text-slate-600 font-medium">Add transactions</span>
                          </div>
                      )}
                  </div>

                  <div className="space-y-6">
                      <h4 className="text-xs font-black text-slate-500 uppercase tracking-[0.2em] mb-4">Primary Drain Vectors</h4>
                      <div className="space-y-4">
                          {expenditureData.topCategories.map((cat, i) => (
                              <div key={i} className="group/item">
                                  <div className="flex justify-between items-end mb-2">
                                      <div className="flex items-center gap-3">
                                          <div className={`w-8 h-8 rounded-lg flex items-center justify-center text-xs font-bold`} style={{ backgroundColor: `${COLORS[i % COLORS.length]}20`, color: COLORS[i % COLORS.length], borderColor: `${COLORS[i % COLORS.length]}40`, borderWidth: '1px' }}>
                                              {i + 1}
                                          </div>
                                          <div>
                                              <div className="text-white font-bold text-sm">{cat.name}</div>
                                              <div className="text-[10px] text-slate-500 font-medium">{cat.percent.toFixed(1)}% of total</div>
                                          </div>
                                      </div>
                                      <div className="text-right">
                                          <div className="text-white font-bold">{formatCurrency(cat.value)}</div>
                                      </div>
                                  </div>
                                  <div className="w-full h-1.5 bg-slate-800 rounded-full overflow-hidden">
                                      <div 
                                          className="h-full rounded-full transition-all duration-1000" 
                                          style={{ width: `${cat.percent}%`, backgroundColor: COLORS[i % COLORS.length] }}
                                      ></div>
                                  </div>
                              </div>
                          ))}
                          {expenditureData.topCategories.length === 0 && (
                              <div className="text-center py-8 text-slate-500 text-xs italic">
                                  No expenditure data available for topology mapping.
                              </div>
                          )}
                      </div>
                  </div>
              </div>
          </div>
      </div>

      {showAnalysisConfirm && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm animate-fade-in">
            <div className="bg-slate-900 border border-white/10 rounded-3xl w-full max-w-md p-8 shadow-2xl animate-slide-up relative">
                <button onClick={() => setShowAnalysisConfirm(false)} className="absolute top-6 right-6 text-slate-500 hover:text-white transition-colors"><X className="w-6 h-6" /></button>
                <div className="flex items-center gap-4 mb-6">
                    <div className="w-14 h-14 rounded-2xl bg-indigo-500/20 flex items-center justify-center border border-indigo-500/30">
                        <BrainCircuit className="w-8 h-8 text-indigo-400" />
                    </div>
                    <div>
                        <h3 className="text-2xl font-black text-white tracking-tight">Neural Analysis</h3>
                        <p className="text-indigo-400 text-xs font-bold uppercase tracking-widest">Confirmation Required</p>
                    </div>
                </div>
                <p className="text-slate-300 text-base mb-8 leading-relaxed font-medium">
                    Scanning system alerts requires deep neural processing. This action will consume <span className="text-white font-bold bg-white/10 px-2 py-0.5 rounded">1 Analysis Token</span> from your monthly quota.
                </p>
                <div className="flex gap-4">
                    <button 
                        onClick={() => setShowAnalysisConfirm(false)}
                        className="flex-1 py-4 rounded-2xl bg-slate-800 text-slate-300 font-bold text-sm uppercase tracking-wider hover:bg-slate-700 transition-colors border border-white/5"
                    >
                        Cancel
                    </button>
                    <button 
                        onClick={() => {
                            setShowAnalysisConfirm(false);
                            onAskCoach?.('Show my active alerts');
                        }}
                        className="flex-1 py-4 rounded-2xl bg-indigo-600 text-white font-bold text-sm uppercase tracking-wider hover:bg-indigo-500 transition-all shadow-xl shadow-indigo-500/20 hover:scale-[1.02] active:scale-95"
                    >
                        Confirm Scan
                    </button>
                </div>
            </div>
        </div>
      )}
    </div>
  );
};

const StatCard: React.FC<{ 
    title: string, 
    value: string | React.ReactNode, 
    icon: React.ReactNode, 
    change?: string, 
    positive?: boolean, 
    delay: string,
    spotlightColor: string,
    onMouseMove: (e: React.MouseEvent<HTMLDivElement>) => void
}> = ({ title, value, icon, change, positive, delay, spotlightColor, onMouseMove }) => (
    <div 
        className="spotlight-card glass-card p-8 rounded-[2.5rem] border border-white/5 animate-slide-up h-full" 
        style={{ animationDelay: delay, '--spotlight-color': spotlightColor } as React.CSSProperties}
        onMouseMove={onMouseMove}
    >
        <div className="flex justify-between items-start mb-6 relative z-10">
            <div className="p-4 bg-slate-800 rounded-2xl border border-white/5 text-slate-400 group-hover:text-indigo-400 transition-colors shadow-inner">{icon}</div>
            {change && (
                <div className={`flex items-center gap-1 text-[11px] font-black uppercase tracking-widest ${positive ? 'text-emerald-500' : 'text-rose-500'}`}>
                    {positive ? <ArrowUpRight className="w-4 h-4" /> : <ArrowDownRight className="w-4 h-4" />}
                    {change}
                </div>
            )}
        </div>
        <div className="relative z-10">
            <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-[0.3em] mb-1">{title}</h4>
            <div className="text-3xl font-black text-white tracking-tighter">{value}</div>
        </div>
    </div>
);

export default Dashboard;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { Transaction, AIAnalysisResponse, ChatMessage, UserPlan, TransactionType, Budget, BotMode, Category, Goal, FinancialSnapshot, SuggestedAction, GoalProposal } from '../types';
import { analyzeFinancialData, chatWithFinancialCoach } from '../services/geminiService';
import { RefreshCcw, CheckCircle, AlertTriangle, ShieldAlert, Info, TrendingUp, Bot, User, BrainCircuit, Lightbulb, Send, Lock, Sparkles, RefreshCw, Flame, ArrowRight, Zap, Crown, TrendingDown, ShoppingCart, Wallet, Terminal, Activity, MousePointerClick, ChevronRight, Check, X, EyeOff, Target } from 'lucide-react';

interface InsightsProps {
  transactions: Transaction[];
  goals: Goal[];
  budgets: Budget[];
  userPlan: UserPlan;
  onUpgradeClick: () => void;
  formatCurrency: (amount: number) => string;
  initialPrompt?: string | null; 
  onPromptHandled?: () => void; 
  onApplyBudgets?: (budgets: Budget[]) => void; 
  insightUsage: number; 
  onIncrementUsage: () => void; 
  botMode: BotMode;
  onNavigate: (tab: string) => void;
  onAddGoal?: (goal: Goal) => void;
}

const Insights: React.FC<InsightsProps> = ({ transactions, goals, budgets, userPlan, onUpgradeClick, formatCurrency, initialPrompt, onPromptHandled, onApplyBudgets, insightUsage, onIncrementUsage, botMode, onNavigate, onAddGoal }) => {
  const [analysis, setAnalysis] = useState<AIAnalysisResponse | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [chatInput, setChatInput] = useState('');
  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([
    { 
        id: '1', 
        role: 'assistant', 
        content: botMode === 'ruthless' 
            ? 'System initialized. Ready to audit your spending vectors.' 
            : 'Hello! I\'m ready to help you optimize your financial wellness. What\'s on your mind?', 
        timestamp: new Date(),
        sentiment: 'info'
    }
  ]);
  const [chatLoading, setChatLoading] = useState(false);
  const [showRejectModal, setShowRejectModal] = useState<GoalProposal | null>(null);
  const [rejectionReason, setRejectionReason] = useState('');

  const chatEndRef = useRef<HTMLDivElement>(null);

  const isUltra = userPlan === 'ultra';
  const isElite = isUltra;
  const isPro = userPlan === 'pro';

  // Industrial Grade Limits
  const FREE_LIMIT = 3;
  const PRO_LIMIT = 50;
  const ULTRA_LIMIT = 1500;

  const currentLimit = isUltra ? ULTRA_LIMIT : isPro ? PRO_LIMIT : FREE_LIMIT;
  const isLocked = insightUsage >= currentLimit;

  // Logic Variables for UI (Raw Math)
  const burnoutData = useMemo(() => {
    const expenseMap = new Map<string, number>();
    transactions
        .filter(t => t.type === TransactionType.EXPENSE)
        .forEach(t => {
            expenseMap.set(t.category, (expenseMap.get(t.category) || 0) + t.amount);
        });

    let maxCat = '';
    let maxAmount = 0;
    expenseMap.forEach((val, key) => {
        if (val > maxAmount) {
            maxAmount = val;
            maxCat = key;
        }
    });
    return { category: maxCat, amount: maxAmount };
  }, [transactions]);

  const leakageData = useMemo(() => {
    const expenses = transactions.filter(t => t.type === TransactionType.EXPENSE);
    const totalExpense = expenses.reduce((acc, t) => acc + t.amount, 0);

    // Group by Category
    const catMap: Record<string, number> = {};
    expenses.forEach(t => {
        catMap[t.category] = (catMap[t.category] || 0) + t.amount;
    });

    const sortedCats = Object.entries(catMap).sort((a, b) => b[1] - a[1]);
    const topLeak = sortedCats[0] || ['None', 0];

    // "Impulse" or Discretionary - rough heuristic
    const discretionaryCats = [Category.SHOPPING, Category.ENTERTAINMENT, Category.FOOD, Category.SUBSCRIPTION];
    const discretionaryTotal = expenses
        .filter(t => discretionaryCats.includes(t.category))
        .reduce((acc, t) => acc + t.amount, 0);

    return {
        topCategory: topLeak[0],
        topAmount: topLeak[1],
        discretionaryTotal,
        totalExpense
    };
  }, [transactions]);

  // Manual Trigger Logic - Removed useEffect for auto-run
  const runAnalysis = async () => {
    if (isLocked) return;
    setLoading(true);
    setError(null);
    onIncrementUsage();
    try {
      const result = await analyzeFinancialData(transactions, userPlan);

      // Filter out recent rejections (7-day cooldown)
      if (result && result.goal_proposals) {
          const rejectedRaw = localStorage.getItem('nova_rejected_proposals');
          const rejectedList: {id: string, type: string, timestamp: number}[] = rejectedRaw ? JSON.parse(rejectedRaw) : [];
          const sevenDaysMs = 7 * 24 * 60 * 60 * 1000;

          result.goal_proposals = result.goal_proposals.filter(p => {
              const rejection = rejectedList.find(r => r.id === p.id || (r.type === p.type && p.title.includes(r.id))); // Heuristic matching
              if (!rejection) return true;
              return (Date.now() - rejection.timestamp) > sevenDaysMs;
          });
      }

      if (result) {
        setAnalysis(result);
      } else {
        setError("Coach is analyzing other portfolios. Try again.");
      }
    } catch (e) {
      setError("Unable to connect to financial brain.");
    } finally {
      setLoading(false);
    }
  };

  const handleAcceptProposal = (proposal: GoalProposal) => {
      if (proposal.type === 'goal' && onAddGoal) {
          onAddGoal({
              id: Date.now().toString(),
              name: proposal.title,
              targetAmount: proposal.target_amount,
              currentAmount: 0,
              deadline: proposal.deadline || new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
              icon: 'star',
              color: 'from-emerald-500 to-teal-500'
          });
      } else if (proposal.type === 'budget' && onApplyBudgets) {
          onApplyBudgets([{
              id: `ai_${Date.now()}`,
              category: (proposal.category as Category) || Category.OTHER,
              limit: proposal.target_amount
          }]);
      }

      // Remove from view
      if (analysis) {
          setAnalysis({
              ...analysis,
              goal_proposals: analysis.goal_proposals.filter(p => p.id !== proposal.id)
          });
      }
  };

  const handleRejectProposal = () => {
      if (!showRejectModal) return;

      const rejectedRaw = localStorage.getItem('nova_rejected_proposals');
      const rejectedList = rejectedRaw ? JSON.parse(rejectedRaw) : [];
      rejectedList.push({
          id: showRejectModal.id, // Or a simplified ID to track category/type
          type: showRejectModal.type,
          title: showRejectModal.title, // Use title for loose matching on re-proposal
          timestamp: Date.now(),
          reason: rejectionReason
      });
      localStorage.setItem('nova_rejected_proposals', JSON.stringify(rejectedList));

      // Remove from view
      if (analysis) {
          setAnalysis({
              ...analysis,
              goal_proposals: analysis.goal_proposals.filter(p => p.id !== showRejectModal.id)
          });
      }

      setShowRejectModal(null);
      setRejectionReason('');
  };

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [chatHistory, chatLoading]);

  useEffect(() => {
      if (!isLocked && initialPrompt && !chatLoading) {
          handleSendMessage(null, initialPrompt);
          if (onPromptHandled) onPromptHandled();
      }
  }, [initialPrompt, isLocked]);

  const handleSendMessage = async (e: React.FormEvent | null, promptOverride?: string) => {
    if (e) e.preventDefault();
    const content = promptOverride || chatInput;
    if (!content.trim() || isLocked) return;

    onIncrementUsage();
    const userMsg: ChatMessage = { id: Date.now().toString(), role: 'user', content: content, timestamp: new Date() };
    setChatHistory(prev => [...prev, userMsg]);
    setChatInput('');
    setChatLoading(true);

    // Build Financial Snapshot (Client-Side Logic)
    const now = new Date();
    const currentMonthTxs = transactions.filter(t => new Date(t.date).getMonth() === now.getMonth());
    const income = currentMonthTxs.filter(t => t.type === TransactionType.INCOME).reduce((sum, t) => sum + t.amount, 0);
    const expense = currentMonthTxs.filter(t => t.type === TransactionType.EXPENSE).reduce((sum, t) => sum + t.amount, 0);

    // Calculate top category
    const catMap: Record<string, number> = {};
    currentMonthTxs.filter(t => t.type === TransactionType.EXPENSE).forEach(t => { catMap[t.category] = (catMap[t.category] || 0) + t.amount; });
    const topCat = Object.entries(catMap).sort((a,b) => b[1] - a[1])[0];

    const snapshot: FinancialSnapshot = {
        currentMonthMetrics: {
            income,
            expense,
            savingsRate: income > 0 ? (income - expense) / income : 0,
            topExpenseCategory: topCat ? topCat[0] : 'None'
        },
        recentTransactions: transactions.slice(0, 10), // Context-Aware Agent (Limited to 10)
        activeGoals: goals,
        budgets: budgets
    };

    const response = await chatWithFinancialCoach(userMsg.content, chatHistory, snapshot, botMode);

    const aiMsg: ChatMessage = { 
        id: (Date.now() + 1).toString(), 
        role: 'assistant', 
        content: response.message, 
        timestamp: new Date(),
        sentiment: response.sentiment as any,
        suggestedActions: response.suggestedActions
    };

    setChatHistory(prev => [...prev, aiMsg]);
    setChatLoading(false);
  };

  const handleActionClick = (action: SuggestedAction) => {
      if (action.actionId.startsWith('navigate_')) {
          const tab = action.actionId.replace('navigate_', '');
          onNavigate(tab);
      } else {
          // Assume it's a chat prompt or generic ID
          handleSendMessage(null, action.payload || action.label);
      }
  };

  const handleAutoTune = () => {
      if (!analysis || !onApplyBudgets) return;
      const newBudgets: Budget[] = analysis.budget_suggestions.map(bs => ({
          id: `ai_${Date.now()}_${bs.category}`,
          category: bs.category as any,
          limit: bs.suggested_limit
      }));
      onApplyBudgets(newBudgets);
  };

  const getColorClass = (type: string) => {
    switch (type) {
        case 'success': return 'bg-emerald-500/10 border-emerald-500/20 text-emerald-100 shadow-[0_4px_20px_rgba(16,185,129,0.1)]';
        case 'warning': return 'bg-amber-500/10 border-amber-500/20 text-amber-100 shadow-[0_4px_20px_rgba(245,158,11,0.1)]';
        case 'critical': return 'bg-rose-500/10 border-rose-500/20 text-rose-100 shadow-[0_4px_20px_rgba(244,63,94,0.1)]';
        default: return 'bg-blue-500/10 border-blue-500/20 text-blue-100 shadow-[0_4px_20px_rgba(59,130,246,0.1)]';
    }
  };

  const getIconForType = (type: string) => {
      switch (type) {
        case 'success': return <CheckCircle className="w-5 h-5 text-emerald-400" />;
        case 'warning': return <AlertTriangle className="w-5 h-5 text-amber-400" />;
        case 'critical': return <ShieldAlert className="w-5 h-5 text-rose-400" />;
        default: return <Info className="w-5 h-5 text-blue-400" />;
      }
    };

  const getChatBubbleStyle = (role: string, sentiment?: string) => {
      if (role === 'user') return 'bg-indigo-600 text-white border-indigo-500/50';

      switch (sentiment) {
          case 'critical': return 'bg-rose-950/40 border-rose-500/30 text-rose-100 shadow-[0_0_15px_rgba(244,63,94,0.2)]';
          case 'warning': return 'bg-amber-950/40 border-amber-500/30 text-amber-100 shadow-[0_0_15px_rgba(245,158,11,0.2)]';
          case 'success': return 'bg-emerald-950/40 border-emerald-500/30 text-emerald-100 shadow-[0_0_15px_rgba(16,185,129,0.2)]';
          default: return 'bg-slate-800/80 border-white/10 text-slate-200';
      }
  };

  return (
    <div className="relative h-[calc(100vh-8rem)]">
      {isLocked && (
        <div className="absolute inset-0 z-50 flex items-center justify-center bg-slate-950/60 backdrop-blur-xl rounded-[2rem] border border-white/10 transform scale-105 transition-transform duration-500">
            <div className="text-center p-8 max-w-md animate-slide-up">
                <div className="w-20 h-20 rounded-3xl bg-gradient-to-tr from-indigo-500 to-purple-500 flex items-center justify-center mx-auto mb-6 shadow-2xl shadow-indigo-500/40"><Lock className="w-10 h-10 text-white" /></div>
                <h2 className="text-3xl font-bold text-white mb-3">Limit Reached</h2>
                <p className="text-slate-400 mb-8 leading-relaxed">
                    You've hit your monthly cap of {currentLimit} interactions for your {userPlan.toUpperCase()} plan. Upgrade or manage your plan to continue using the AI Coach.
                </p>
                {!isUltra && (
                    <button onClick={onUpgradeClick} className="w-full py-4 bg-white text-indigo-900 font-bold rounded-xl shadow-xl hover:scale-[1.02] active:scale-95 transition-all flex items-center justify-center gap-2 group"><Sparkles className="w-5 h-5 text-indigo-600 group-hover:rotate-12 transition-transform" />Upgrade Plan</button>
                )}
            </div>
        </div>
      )}

      <div className={`grid grid-cols-1 lg:grid-cols-3 gap-8 pb-10 h-full transition-all duration-500 ${isLocked ? 'blur-md opacity-50 pointer-events-none select-none overflow-hidden' : ''}`}>
        <div className="lg:col-span-2 overflow-y-auto custom-scrollbar space-y-8 pr-2">

            {/* Manual Trigger Header */}
            <div className="bg-gradient-to-r from-slate-900 via-slate-900/80 to-indigo-900/20 p-8 rounded-[2.5rem] border border-white/10 shadow-2xl relative overflow-hidden group">
                <div className="flex justify-between items-start relative z-10">
                    <div>
                        <h2 className="text-2xl font-black text-white flex items-center gap-3"><BrainCircuit className="w-8 h-8 text-indigo-400" />Command Center</h2>
                        <p className="text-slate-400 text-sm mt-2 max-w-md font-medium">Initiate deep neural scans or query the agent directly.</p>
                        <div className={`mt-4 inline-flex items-center gap-2 px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest border ${isUltra ? 'bg-indigo-500/10 border-indigo-500/20 text-indigo-400' : isPro ? 'bg-amber-500/10 border-amber-500/20 text-amber-400' : 'bg-slate-700/50 border-white/10 text-slate-400'}`}>
                            {isUltra ? <Crown className="w-3 h-3" /> : isPro ? <Zap className="w-3 h-3" /> : null}
                            Tokens: {insightUsage}/{currentLimit}
                        </div>
                    </div>
                    <button 
                        onClick={runAnalysis} 
                        disabled={loading} 
                        className="flex flex-col items-center justify-center w-24 h-24 bg-slate-800 hover:bg-indigo-600 rounded-3xl border border-white/10 transition-all group shadow-xl active:scale-95"
                    >
                        <RefreshCcw className={`w-8 h-8 text-slate-300 group-hover:text-white mb-2 transition-colors ${loading ? 'animate-spin' : ''}`} />
                        <span className="text-[9px] font-black text-slate-400 group-hover:text-white uppercase tracking-widest">Scan</span>
                    </button>
                </div>
            </div>

            {loading && (
                <div className="flex flex-col items-center justify-center py-20 space-y-4">
                    <Activity className="w-12 h-12 text-indigo-500 animate-bounce" />
                    <p className="text-slate-400 text-xs font-bold uppercase tracking-widest animate-pulse">Running Neural Audit...</p>
                </div>
            )}

            {analysis && !loading && (
            <div className="animate-fade-in space-y-8">
                {/* 1. Risk & Forecast */}
                <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                    <div className="glass-card p-6 rounded-3xl relative overflow-hidden group border-indigo-500/10 hover:border-indigo-500/30 transition-all hover:shadow-[0_0_40px_rgba(79,70,229,0.15)]">
                        <h3 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-4">Risk Matrix</h3>
                        <div className="flex items-center gap-4">
                            <div className="relative w-16 h-16 flex items-center justify-center shrink-0">
                                <svg className="w-full h-full transform -rotate-90 filter drop-shadow-md" viewBox="0 0 64 64">
                                    <circle cx="32" cy="32" r="28" stroke="currentColor" strokeWidth="6" fill="transparent" className="text-slate-800/50" />
                                    <circle cx="32" cy="32" r="28" stroke="currentColor" strokeWidth="6" fill="transparent" className={`${analysis.risk_score > 50 ? 'text-rose-500' : 'text-emerald-500'} transition-all duration-1000 ease-out`} strokeDasharray={175.9} strokeDashoffset={175.9 - (175.9 * analysis.risk_score) / 100} strokeLinecap="round" />
                                </svg>
                                <span className="absolute text-lg font-bold text-white tracking-tighter">{Math.round(analysis.risk_score)}</span>
                            </div>
                            <div className="flex-1 min-w-0">
                                <h4 className={`text-lg font-bold ${analysis.risk_score > 50 ? 'text-rose-400' : 'text-emerald-400'} mb-1`}>{analysis.risk_score > 50 ? 'Critical' : 'Stable'}</h4>
                                <p className="text-[10px] text-slate-400 font-medium">System Health</p>
                            </div>
                        </div>
                    </div>

                    <div className="glass-card p-6 rounded-3xl relative overflow-hidden border-indigo-500/10 hover:border-indigo-500/30 transition-all group">
                         <h3 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-4">Trajectory (30d)</h3>
                         <div className="text-3xl font-bold text-white tracking-tight">{formatCurrency(analysis.predicted_spend_next_month).replace(/\.00$/, '')}</div>
                         <p className="text-[10px] text-slate-500 mt-2 font-medium flex items-center gap-1.5"><TrendingUp className="w-3 h-3 text-indigo-400" /> Forecasted Burn</p>
                    </div>

                    <div className="glass-card p-6 rounded-3xl relative overflow-hidden border-rose-500/10 hover:border-rose-500/30 transition-all group bg-rose-500/5">
                        <div className="absolute top-0 right-0 w-32 h-32 bg-rose-500/10 rounded-full blur-2xl -mr-8 -mt-8 pointer-events-none"></div>
                        <h3 className="text-[10px] font-bold text-rose-300 uppercase tracking-widest mb-4 flex items-center gap-1.5"><Flame className="w-3 h-3 text-rose-500" /> Burnout Alert</h3>
                        <div className="text-xl font-bold text-white tracking-tight truncate">{burnoutData.category || 'N/A'}</div>
                        <p className="text-[10px] text-slate-400 mt-1 font-medium">{formatCurrency(burnoutData.amount)} consumed</p>
                    </div>
                </div>

                {/* 2. Strategic Insights List */}
                <div>
                    <h3 className="text-lg font-bold text-white mb-5 px-1 flex items-center gap-2"><Lightbulb className="w-5 h-5 text-amber-400" />Strategic Insights</h3>
                    <div className="grid grid-cols-1 gap-4">
                        {analysis.insights.map((insight, idx) => (
                            <div key={idx} className={`p-6 rounded-2xl border flex gap-5 backdrop-blur-md transition-all hover:translate-x-1 hover:shadow-lg ${getColorClass(insight.type)}`}>
                                <div className="mt-0.5 shrink-0 bg-white/10 p-2.5 rounded-xl h-fit ring-1 ring-white/10 shadow-sm">{getIconForType(insight.type)}</div>
                                <div>
                                    <h4 className="font-bold text-base mb-1.5">{insight.title}</h4>
                                    <p className="text-sm opacity-90 leading-relaxed font-medium">{insight.description}</p>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>

                {/* 3. CAPITAL LEAKAGE ANALYSIS */}
                <div className="glass-card p-8 rounded-[2.5rem] border border-white/5 relative overflow-hidden">
                    <div className="absolute top-0 right-0 w-64 h-64 bg-rose-500/5 rounded-full blur-[80px] -mr-16 -mt-16 pointer-events-none"></div>
                    <h3 className="text-lg font-bold text-white mb-6 px-1 flex items-center gap-2">
                        <TrendingDown className="w-5 h-5 text-rose-400" />
                        Capital Leakage Detectors
                    </h3>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6 relative z-10">
                        <div className="bg-slate-900/50 p-5 rounded-2xl border border-white/5 flex items-center gap-4">
                            <div className="w-12 h-12 rounded-xl bg-rose-500/10 flex items-center justify-center shrink-0">
                                <AlertTriangle className="w-6 h-6 text-rose-400" />
                            </div>
                            <div>
                                <p className="text-[10px] text-slate-500 font-black uppercase tracking-widest mb-1">Primary Drain</p>
                                <div className="text-white font-bold text-lg">{leakageData.topCategory}</div>
                                <div className="text-rose-400 text-xs font-medium">{formatCurrency(leakageData.topAmount)} consumed</div>
                            </div>
                        </div>

                        <div className="bg-slate-900/50 p-5 rounded-2xl border border-white/5 flex items-center gap-4">
                            <div className="w-12 h-12 rounded-xl bg-amber-500/10 flex items-center justify-center shrink-0">
                                <ShoppingCart className="w-6 h-6 text-amber-400" />
                            </div>
                            <div>
                                <p className="text-[10px] text-slate-500 font-black uppercase tracking-widest mb-1">Discretionary Burn</p>
                                <div className="text-white font-bold text-lg">{formatCurrency(leakageData.discretionaryTotal)}</div>
                                <div className="text-amber-400 text-xs font-medium">{((leakageData.discretionaryTotal / (leakageData.totalExpense || 1)) * 100).toFixed(1)}% of total outflow</div>
                            </div>
                        </div>
                    </div>

                    <div className="mt-6 p-4 rounded-xl bg-indigo-500/5 border border-indigo-500/10 flex gap-3 items-start">
                        <Info className="w-4 h-4 text-indigo-400 mt-0.5 shrink-0" />
                        <p className="text-xs text-indigo-200/80 leading-relaxed">
                            <span className="font-bold text-indigo-300">Analysis:</span> Your spending pattern indicates a heavy skew towards {leakageData.topCategory}. 
                            Reducing this vector by 10% would reclaim {formatCurrency(leakageData.topAmount * 0.1)} monthly.
                        </p>
                    </div>
                </div>

                {/* 4. Optimization Opportunities */}
                <div>
                    <div className="flex items-center justify-between mb-5 px-1">
                        <h3 className="text-lg font-bold text-white flex items-center gap-2"><TrendingUp className="w-5 h-5 text-indigo-400" />Optimization Opportunities</h3>
                        {analysis.budget_suggestions.length > 0 && onApplyBudgets && (
                            <button onClick={handleAutoTune} className="text-xs font-bold text-indigo-300 bg-indigo-500/20 hover:bg-indigo-500/30 border border-indigo-500/30 px-3 py-1.5 rounded-lg transition-all flex items-center gap-1.5 active:scale-95"><Sparkles className="w-3 h-3" /> Auto-Tune Limits</button>
                        )}
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
                        {analysis.budget_suggestions.map((budget, idx) => (
                            <div key={idx} className="bg-slate-900/40 p-6 rounded-3xl border border-white/5 hover:border-indigo-500/30 transition-all hover:shadow-[0_4px_25px_rgba(99,102,241,0.15)] group relative overflow-hidden">
                                <div className="flex justify-between mb-4 relative z-10">
                                    <span className="text-xs font-bold text-indigo-200 bg-indigo-500/20 px-3 py-1 rounded-lg uppercase tracking-wide border border-indigo-500/20">{budget.category}</span>
                                    <span className="text-xs text-rose-300 font-bold bg-rose-500/20 px-3 py-1 rounded-lg border border-rose-500/20">{formatCurrency(Math.max(0, budget.current_spend - budget.suggested_limit))} cut needed</span>
                                </div>
                                <p className="text-slate-300 text-sm mb-6 line-clamp-2 font-medium relative z-10">"{budget.reason}"</p>
                                <div className="space-y-2 relative z-10">
                                    <div className="flex justify-between text-[10px] text-slate-400 font-bold uppercase tracking-wider"><span>Target Limit</span><span>Current</span></div>
                                    <div className="w-full bg-slate-800 h-2.5 rounded-full overflow-hidden flex border border-white/5">
                                        <div className="bg-indigo-500 h-full shadow-[0_0_15px_#6366f1]" style={{ width: `${Math.min(100, (budget.suggested_limit / budget.current_spend) * 100)}%` }}></div>
                                        <div className="bg-rose-500 h-full flex-1 opacity-80 striped-bg"></div>
                                    </div>
