interface BillNegotiatorProps {
  userPlan: UserPlan;
  onIncrementUsage: () => void;
  negotiationUsage: number;
}

const BillNegotiator: React.FC<BillNegotiatorProps> = ({ userPlan, onIncrementUsage, negotiationUsage }) => {
  const [merchant, setMerchant] = useState('');
  const [amount, setAmount] = useState('');
  const [serviceType, setServiceType] = useState('Internet');
  const [script, setScript] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [copied, setCopied] = useState(false);

  const isElite = userPlan === 'ultra';
  const isPro = userPlan === 'pro';

  // Usage Limits
  const limit = isElite ? 100 : isPro ? 20 : 3;
  const isLocked = negotiationUsage >= limit;

  const handleGenerate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!merchant || !amount || isLocked) return;

    setLoading(true);
    onIncrementUsage();

    // Slight delay for UX effect
    setTimeout(async () => {
        const generatedScript = await generateNegotiationScript(merchant, parseFloat(amount));
        setScript(generatedScript);
        setLoading(false);
    }, 800);
  };

  const handleCopy = () => {
    if (script) {
      navigator.clipboard.writeText(script);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    }
  };

  const PRESETS = [
      { id: 'internet', label: 'Internet / Cable', icon: Wifi, color: 'text-cyan-400 bg-cyan-500/10 border-cyan-500/20' },
