const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isPrivacyMode, setIsPrivacyMode] = useState(() => localStorage.getItem('nova_privacy_mode') === 'true');
  const [isPinMode, setIsPinMode] = useState(false);

  // Onboarding & Enforcement State
  const [onboardingComplete, setOnboardingComplete] = useState(() => localStorage.getItem('nova_onboarding_complete') === 'true');
  const [spendingLimit, setSpendingLimit] = useState<number>(() => parseFloat(localStorage.getItem('nova_spending_limit') || '1000'));
  const [spendingPeriod, setSpendingPeriod] = useState<SpendingPeriod>(() => (localStorage.getItem('nova_spending_period') as SpendingPeriod) || 'monthly');

  // Pin System State
  const [pinnedIds, setPinnedIds] = useState<string[]>(() => {
    try {
        const saved = localStorage.getItem('nova_pinned_ids');
        return saved ? JSON.parse(saved) : []; 
    } catch { return []; }
  });

  const [featureUsage, setFeatureUsage] = useState<Record<string, number>>(() => {
      try {
          const saved = localStorage.getItem('nova_feature_usage');
          return saved ? JSON.parse(saved) : {};
      } catch { return {}; }
  });

  const [accounts, setAccounts] = useState<Account[]>(() => {
      const saved = localStorage.getItem('nova_accounts');
      return saved ? JSON.parse(saved) : ACCOUNTS;
  });
  const [transactions, setTransactions] = useState<Transaction[]>(() => {
      const saved = localStorage.getItem('nova_transactions');
      return saved ? JSON.parse(saved) : INITIAL_TRANSACTIONS;
  });
  const [budgets, setBudgets] = useState<Budget[]>(() => {
      const saved = localStorage.getItem('nova_budgets');
      return saved ? JSON.parse(saved) : INITIAL_BUDGETS;
  });
  const [goals, setGoals] = useState<Goal[]>(() => {
      const saved = localStorage.getItem('nova_goals');
      return saved ? JSON.parse(saved) : INITIAL_GOALS;
  });

  const [userPlan, setUserPlan] = useState<UserPlan>(() => localStorage.getItem('nova_user_plan') as UserPlan || 'free');
  const [insightUsage, setInsightUsage] = useState(() => getMonthlyUsage('nova_insight_usage'));
  const [scanUsage, setScanUsage] = useState(() => getMonthlyUsage('nova_scan_usage'));
  const [negotiationUsage, setNegotiationUsage] = useState(() => getMonthlyUsage('nova_negotiation_usage'));

  const [isLoggedIn, setIsLoggedIn] = useState(() => localStorage.getItem('nova_auth_token') !== null);
  const [isLogoutModalOpen, setIsLogoutModalOpen] = useState(false);
  const [toasts, setToasts] = useState<ToastMessage[]>([]);
  const [botMode, setBotMode] = useState<BotMode>(() => (localStorage.getItem('nova_bot_mode') as BotMode) || 'ruthless');
  const [pendingChatQuery, setPendingChatQuery] = useState<string | null>(null);

  const [userName, setUserName] = useState(() => localStorage.getItem('nova_user_name') || 'Pilot');
  const [userEmail, setUserEmail] = useState(() => localStorage.getItem('nova_user_email') || 'pilot@nova.io');
  const [userAvatar, setUserAvatar] = useState(() => localStorage.getItem('nova_user_avatar') || '');
  const [userAvatarZoom, setUserAvatarZoom] = useState(1);
  const [userAvatarPos, setUserAvatarPos] = useState({ x: 0, y: 0 });
  const [userBorder, setUserBorder] = useState('default');
  const [userBackground, setUserBackground] = useState(() => localStorage.getItem('nova_user_bg') || '');

  const [currency, setCurrency] = useState<Currency>(() => (localStorage.getItem('nova_currency') as Currency) || 'USD');
  const [language, setLanguage] = useState<Language>(() => (localStorage.getItem('nova_language') as Language) || 'en');

  // Persistence Effects
  useEffect(() => safeSetItem('nova_accounts', JSON.stringify(accounts)), [accounts]);
  useEffect(() => safeSetItem('nova_transactions', JSON.stringify(transactions)), [transactions]);
  useEffect(() => safeSetItem('nova_budgets', JSON.stringify(budgets)), [budgets]);
  useEffect(() => safeSetItem('nova_goals', JSON.stringify(goals)), [goals]);
  useEffect(() => safeSetItem('nova_user_plan', userPlan), [userPlan]);
  useEffect(() => safeSetItem('nova_currency', currency), [currency]);
  useEffect(() => safeSetItem('nova_language', language), [language]);
  useEffect(() => safeSetItem('nova_bot_mode', botMode), [botMode]);
  useEffect(() => safeSetItem('nova_privacy_mode', isPrivacyMode.toString()), [isPrivacyMode]);
  useEffect(() => safeSetItem('nova_pinned_ids', JSON.stringify(pinnedIds)), [pinnedIds]);
  useEffect(() => safeSetItem('nova_feature_usage', JSON.stringify(featureUsage)), [featureUsage]);
  useEffect(() => safeSetItem('nova_user_bg', userBackground), [userBackground]);
  useEffect(() => safeSetItem('nova_spending_limit', spendingLimit.toString()), [spendingLimit]);
  useEffect(() => safeSetItem('nova_spending_period', spendingPeriod), [spendingPeriod]);
  useEffect(() => safeSetItem('nova_onboarding_complete', onboardingComplete.toString()), [onboardingComplete]);

  // Spending Enforcement Calculation (Zero AI, Pure Math)
  const spendingStatus: { currentSpend: number; status: SpendingStatus } = useMemo(() => {
      const now = new Date();
      let startDate = new Date();

      if (spendingPeriod === 'weekly') {
          // Set to previous Sunday (or today if Sunday)
          const day = now.getDay();
          const diff = now.getDate() - day;
          startDate = new Date(now.setDate(diff));
          startDate.setHours(0, 0, 0, 0);
      } else {
          // Set to 1st of current month
          startDate = new Date(now.getFullYear(), now.getMonth(), 1);
      }

      const currentSpend = transactions
          .filter(t => t.type === TransactionType.EXPENSE && new Date(t.date) >= startDate)
          .reduce((acc, t) => acc + t.amount, 0);

      const status = evaluateSpending(currentSpend, spendingLimit);
      return { currentSpend, status };
  }, [transactions, spendingPeriod, spendingLimit]);

  // Usage counters
  useEffect(() => {
      const now = new Date();
      const meta = { month: now.getMonth(), year: now.getFullYear(), count: insightUsage };
      safeSetItem('nova_insight_usage', JSON.stringify(meta));
  }, [insightUsage]);

  useEffect(() => {
      const now = new Date();
      const meta = { month: now.getMonth(), year: now.getFullYear(), count: scanUsage };
      safeSetItem('nova_scan_usage', JSON.stringify(meta));
  }, [scanUsage]);

  useEffect(() => {
      const now = new Date();
      const meta = { month: now.getMonth(), year: now.getFullYear(), count: negotiationUsage };
      safeSetItem('nova_negotiation_usage', JSON.stringify(meta));
  }, [negotiationUsage]);

  const addToast = useCallback((message: string, type: 'success' | 'error' | 'info' = 'info') => {
    setToasts(prev => [...prev, { id: Date.now().toString(), message, type }]);
  }, []);

  const trackFeatureUsage = useCallback((featureId: string) => {
      setFeatureUsage(prev => ({
          ...prev,
          [featureId]: (prev[featureId] || 0) + 1
      }));
  }, []);

  // Auto-Pin Heuristic
  useEffect(() => {
      if (!isLoggedIn) return;
      const hasAutoPinned = localStorage.getItem('nova_has_auto_pinned');
      if (hasAutoPinned) return;

      const totalActions = (Object.values(featureUsage) as number[]).reduce((a, b) => a + b, 0);
      if (totalActions > 10) {
          const sorted = Object.entries(featureUsage)
              .filter(([key]) => PINNABLE_FEATURES.includes(key))
              .sort((a, b) => (b[1] as number) - (a[1] as number))
              .map(([key]) => key)
              .slice(0, 2); 

          if (sorted.length > 0) {
              setPinnedIds(sorted);
              addToast(`System optimization complete. Top ${sorted.length} modules pinned.`, 'info');
              localStorage.setItem('nova_has_auto_pinned', 'true');
          }
      }
  }, [featureUsage, isLoggedIn, addToast]);

  const handleTogglePin = (id: string) => {
    setPinnedIds(prev => {
        if (prev.includes(id)) {
            return prev.filter(p => p !== id);
        }
        const limit = userPlan === 'ultra' ? 5 : userPlan === 'pro' ? 3 : 1;
        if (prev.length >= limit) {
            addToast(`Slot Limit Reached (${limit}). Unpin a module to replace.`, 'error');
            return prev;
        }
        return [...prev, id];
    });
  };

  const handleToggleStealth = useCallback(() => {
    if (userPlan !== 'ultra') {
        addToast('Stealth Protocol is an Elite-exclusive feature.', 'info');
        setActiveTab('plans');
        return;
    }
    setIsPrivacyMode(prev => !prev);
    addToast(`Stealth Protocol ${!isPrivacyMode ? 'Engaged' : 'Disengaged'}`, 'info');
  }, [userPlan, isPrivacyMode, addToast]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
        const isModI = (e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'i';
        if (isModI) {
            e.preventDefault();
            setIsPinMode(prev => {
                const newVal = !prev;
                addToast(newVal ? 'Pin Configuration Mode: ACTIVE' : 'Pin Configuration Mode: END', 'info');
                if (newVal) setActiveTab('dashboard');
                return newVal;
            });
        }
        if (e.key === 'Escape' && isPinMode) {
            setIsPinMode(false);
            addToast('Pin Configuration Mode: END', 'info');
        }
        if (e.shiftKey && e.key.toLowerCase() === 'p') {
            handleToggleStealth();
        }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isPinMode, handleToggleStealth, addToast]);

  const removeToast = (id: string) => {
    setToasts(prev => prev.filter(t => t.id !== id));
  };

  const formatCurrency = (amount: number) => {
    const val = new Intl.NumberFormat(language === 'vi' ? 'vi-VN' : 'en-US', { 
        style: 'currency', currency: currency,
    }).format(amount);

    if (isPrivacyMode && userPlan === 'ultra') {
        return <span className="blur-md opacity-50 bg-white/5 px-1 rounded-md">{val.replace('-', '')}</span>;
    }
    return val;
  };

  const reconcileBalance = (tx: Transaction, direction: 'add' | 'delete') => {
      if (tx.accountId === 'manual') return;
      setAccounts(prev => prev.map(acc => {
          if (acc.id === tx.accountId) {
              const isIncome = tx.type === TransactionType.INCOME;
              let change = tx.amount;
              if (direction === 'add') change = isIncome ? change : -change;
              else change = isIncome ? -change : change;
              return { ...acc, balance: acc.balance + change };
          }
          return acc;
      }));
  };

  const handleAddTransaction = (t: Transaction) => {
      setTransactions(prev => [t, ...prev]);
      reconcileBalance(t, 'add');
      addToast('Transaction recorded.', 'success');
  };

  const handleDeleteTransaction = (id: string) => {
      const tx = transactions.find(t => t.id === id);
      if (tx) {
          reconcileBalance(tx, 'delete');
          setTransactions(prev => prev.filter(t => t.id !== id));
          addToast('Transaction purged.', 'info');
      }
  };

  const handleLogin = (name: string) => {
    setIsLoggedIn(true);
    setUserName(name);
    localStorage.setItem('nova_user_name', name);
  };

  const confirmLogout = () => {
    localStorage.removeItem('nova_auth_token');
    setIsLoggedIn(false);
    setIsLogoutModalOpen(false);
  };

  const handleAskCoach = (message?: string) => {
    if (message) {
      setPendingChatQuery(message);
    }
    setActiveTab('insights');
  };

  const handleOnboardingComplete = (lang: Language, per: SpendingPeriod, lim: number) => {
      setLanguage(lang);
      setSpendingPeriod(per);
      setSpendingLimit(lim);
      setOnboardingComplete(true);
      addToast('System Initialized. Spending parameters locked.', 'success');
  };

  const branding = useMemo(() => {
    switch (userPlan) {
      case 'ultra':
        return {
          bg: 'bg-gradient-to-tr from-indigo-600 to-purple-600',
          shadow: 'shadow-indigo-500/40',
          icon: <Sparkles className="w-6 h-6 text-white" />,
          label: 'Elite Terminal'
        };
      case 'pro':
        return {
          bg: 'bg-gradient-to-tr from-amber-400 to-orange-500',
          shadow: 'shadow-amber-500/40',
          icon: <Zap className="w-6 h-6 text-white" />,
          label: 'Pro Uplink'
        };
      default:
        return {
          bg: 'bg-slate-800',
          shadow: 'shadow-black/20',
          icon: <Shield className="w-6 h-6 text-slate-400" />,
          label: 'Free Tier'
        };
    }
  }, [userPlan]);

  if (!isLoggedIn) return <LandingPage onLoginSuccess={handleLogin} />;

  if (!onboardingComplete) return <OnboardingModal onComplete={handleOnboardingComplete} />;

  return (
    <div className={`flex h-screen bg-[#020617] text-slate-100 font-sans selection:bg-indigo-500/30 overflow-hidden relative ${isPinMode ? 'cursor-default' : ''}`}>
      <FloatingAssistant transactions={transactions} budgets={budgets} userPlan={userPlan} botMode={botMode} isVisible={activeTab !== 'insights'} onOpenChat={handleAskCoach} insightUsage={insightUsage} />

      <aside className="hidden md:flex flex-col w-64 p-4 pb-8 z-20 bg-slate-950/40 backdrop-blur-md border-r border-white/5 relative">
        <div className="flex items-center gap-3 px-4 py-3 mb-8 shrink-0">
            <div className={`w-10 h-10 rounded-xl flex items-center justify-center shadow-lg ring-1 ring-white/10 ${branding.bg} ${branding.shadow}`}>{branding.icon}</div>
            <div><h1 className="text-xl font-bold tracking-tight text-white">Nova AI</h1><p className={`text-[10px] font-bold uppercase tracking-wider ${userPlan === 'ultra' ? 'text-purple-400' : userPlan === 'pro' ? 'text-amber-400' : 'text-slate-500'}`}>{branding.label}</p></div>
        </div>
        <nav className="flex-1 space-y-1 overflow-y-auto custom-scrollbar pr-1">
            {NAV_ITEMS.map((item) => {
                const isActive = activeTab === item.id;
                const label = TRANSLATIONS[language]?.[item.id as keyof typeof TRANSLATIONS['en']] || item.label;
                return (
                    <button key={item.id} onClick={() => setActiveTab(item.id)} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold transition-all duration-300 group ${isActive ? 'bg-indigo-600/10 text-indigo-400 shadow-[0_0_20px_rgba(99,102,241,0.15)] ring-1 ring-indigo-500/20' : 'text-slate-400 hover:text-white hover:bg-white/5'}`}>
                        <item.icon className={`w-5 h-5 transition-colors ${isActive ? 'text-indigo-400' : 'text-slate-500 group-hover:text-white'}`} />{label}
                    </button>
                );
            })}
        </nav>
        <div className="mt-auto pt-6 border-t border-white/5 shrink-0">
             <button onClick={handleToggleStealth} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all mb-2 ${isPrivacyMode && userPlan === 'ultra' ? 'bg-indigo-500/20 text-indigo-400 border border-indigo-500/30' : 'text-slate-500 hover:text-slate-300 hover:bg-white/5'}`}>
                {isPrivacyMode ? <EyeOff className="w-5 h-5" /> : <Shield className="w-5 h-5" />} {isPrivacyMode ? 'Stealth Engaged' : 'Stealth Protocol'}
             </button>
             <button onClick={() => setActiveTab('settings')} className="w-full text-left px-4 py-4 rounded-2xl bg-slate-900/50 border border-white/5 flex items-center gap-3 mb-4 hover:bg-slate-800 transition-colors group">
                 <div className="w-10 h-10 rounded-full bg-indigo-500 flex items-center justify-center text-white overflow-hidden relative border border-white/10 shadow-inner">{userAvatar ? <img src={userAvatar} className="w-full h-full object-cover" alt="User" /> : <span className="font-bold text-lg">{userName.charAt(0)}</span>}</div>
                 <div className="overflow-hidden"><h4 className="font-bold text-white text-sm truncate group-hover:text-indigo-400 transition-colors">{userName}</h4><p className="text-[10px] text-slate-500 truncate font-bold uppercase tracking-widest">{userPlan} tier</p></div>
             </button>
             <button onClick={() => setIsLogoutModalOpen(true)} className="w-full flex items-center gap-2 px-4 py-2 mb-4 text-xs font-bold text-slate-500 hover:text-rose-400 transition-colors uppercase tracking-widest"><LogOut className="w-4 h-4" /> Sign Out</button>
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 z-10 relative overflow-hidden">
        {isPinMode && (
          <div className="absolute inset-0 z-[100] bg-black/40 backdrop-blur-[2px] pointer-events-none flex flex-col items-center justify-start pt-20">
              <div className="bg-indigo-600/90 text-white font-black text-xs uppercase tracking-[0.3em] px-8 py-4 rounded-2xl shadow-[0_0_50px_rgba(99,102,241,0.5)] border border-indigo-400/50 animate-pulse pointer-events-auto">
                  Pin Mode Active :: Select Priority Nodes :: Esc to Exit
              </div>
          </div>
        )}

        <div className="flex-1 overflow-y-auto p-4 md:p-8 pb-24 md:pb-8 custom-scrollbar">
            {activeTab === 'dashboard' && <Dashboard accounts={accounts} transactions={transactions} goals={goals} budgets={budgets} onNavigate={setActiveTab} onAddAccount={() => setActiveTab('accounts')} onAddTransaction={() => setActiveTab('transactions')} onAddGoal={() => setActiveTab('goals')} formatCurrency={formatCurrency} userPlan={userPlan} onAskCoach={handleAskCoach} negotiationUsage={negotiationUsage} onIncrementNegotiation={() => setNegotiationUsage(prev => prev + 1)} isPinMode={isPinMode} pinnedIds={pinnedIds} onTogglePin={handleTogglePin} trackEvent={trackFeatureUsage} insightUsage={insightUsage} spendingStatus={spendingStatus.status} currentPeriodSpend={spendingStatus.currentSpend} spendingLimit={spendingLimit} spendingPeriod={spendingPeriod} />}
            {activeTab === 'transactions' && <Transactions transactions={transactions} accounts={accounts} onDelete={handleDeleteTransaction} onAdd={handleAddTransaction} formatCurrency={formatCurrency} onNavigateToAccounts={() => setActiveTab('accounts')} userPlan={userPlan} scanUsage={scanUsage} onIncrementScan={() => setScanUsage(prev => prev + 1)} currency={currency} />}
            {activeTab === 'accounts' && <Accounts accounts={accounts} budgets={budgets} transactions={transactions} userPlan={userPlan} onAdd={(acc) => { setAccounts(prev => [...prev, acc]); addToast('Account linked.', 'success'); }} onUpdate={(acc) => { setAccounts(prev => prev.map(a => a.id === acc.id ? acc : a)); addToast('Account updated.', 'success'); }} onDelete={(id) => { setAccounts(prev => prev.filter(a => a.id !== id)); setTransactions(prev => prev.map(t => t.accountId === id ? { ...t, accountId: 'manual' } : t)); addToast('Account removed.', 'info'); }} formatCurrency={formatCurrency} userName={userName} userAvatar={userAvatar} userAvatarZoom={userAvatarZoom} userAvatarPos={userAvatarPos} userBorder={userBorder} onNavigate={setActiveTab} />}
            {activeTab === 'negotiator' && <BillNegotiator userPlan={userPlan} onIncrementUsage={() => setNegotiationUsage(prev => prev + 1)} negotiationUsage={negotiationUsage} />}
            {activeTab === 'cashflow' && <CashflowBeta transactions={transactions} accounts={accounts} goals={goals} formatCurrency={formatCurrency} userPlan={userPlan} />}
            {activeTab === 'insights' && <Insights transactions={transactions} userPlan={userPlan} onUpgradeClick={() => setActiveTab('plans')} formatCurrency={formatCurrency} insightUsage={insightUsage} onIncrementUsage={() => setInsightUsage(prev => prev + 1)} onApplyBudgets={(newBudgets) => { const existingCats = new Set(budgets.map(b => b.category)); const toAdd = newBudgets.filter(b => !existingCats.has(b.category)); setBudgets(prev => [...prev, ...toAdd]); addToast(`Applied ${toAdd.length} AI limits.`, 'success'); }} initialPrompt={pendingChatQuery} onPromptHandled={() => setPendingChatQuery(null)} botMode={botMode} onNavigate={setActiveTab} onAddGoal={(g) => { setGoals(prev => [...prev, g]); addToast('Goal created from proposal.', 'success'); }} />}
            {activeTab === 'sandbox' && <ScenarioSandbox transactions={transactions} goals={goals} formatCurrency={formatCurrency} userPlan={userPlan} onUpgradeClick={() => setActiveTab('plans')} insightUsage={insightUsage} onIncrementUsage={(val) => setInsightUsage(prev => prev + (val || 1))} />}
            {activeTab === 'goals' && <Goals goals={goals} budgets={budgets} transactions={transactions} onAddGoal={(g) => { setGoals(prev => [...prev, g]); addToast('Goal deployed.', 'success'); }} onUpdateGoal={(g) => { setGoals(prev => prev.map(goal => goal.id === g.id ? g : goal)); addToast('Goal updated.', 'success'); }} onAddBudget={(b) => { setBudgets(prev => [...prev, b]); addToast('Limit set.', 'success'); }} onDeleteBudget={(id) => { setBudgets(prev => prev.filter(b => b.id !== id)); addToast('Limit removed.', 'info'); }} formatCurrency={formatCurrency} />}
            {activeTab === 'plans' && <Plans currentPlan={userPlan} onUpgrade={(plan) => { setUserPlan(plan); addToast(`Plan upgraded.`, 'success'); }} onDowngrade={() => { setUserPlan('free'); addToast('Plan reset.', 'info'); }} onNavigateDashboard={() => setActiveTab('dashboard')} />}
            {activeTab === 'upcoming' && <UpcomingFeatures />}
            {activeTab === 'settings' && <Settings userName={userName} userEmail={userEmail} userAvatar={userAvatar} userAvatarZoom={userAvatarZoom} userAvatarPos={userAvatarPos} userBorder={userBorder} userBackground={userBackground} onUpdateBackground={setUserBackground} userPlan={userPlan} onUpdateProfile={(n, e, a, z, p, b) => { setUserName(n); setUserEmail(e); setUserAvatar(a); setUserAvatarZoom(z); setUserAvatarPos(p); setUserBorder(b); addToast('Profile updated.', 'success'); }} addToast={addToast} onExportData={() => addToast('Exporting...')} onImportData={() => addToast('Importing...')} onClearData={() => addToast('Clearing...')} language={language} onUpdateLanguage={setLanguage} currency={currency} onUpdateCurrency={setCurrency} botMode={botMode} onUpdateBotMode={setBotMode} spendingLimit={spendingLimit} onUpdateSpendingLimit={setSpendingLimit} spendingPeriod={spendingPeriod} onUpdateSpendingPeriod={setSpendingPeriod} />}
        </div>
      </main>

      {isLogoutModalOpen && (
          <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/95 backdrop-blur-2xl animate-fade-in">
              <div className="bg-[#0f172a] border border-rose-500/30 rounded-[3rem] w-full max-w-sm shadow-[0_0_100px_rgba(244,63,94,0.2)] p-10 text-center animate-slide-up relative">
                  <div className="w-20 h-20 bg-rose-500/20 rounded-[2rem] flex items-center justify-center mx-auto mb-8 border border-rose-500/30"><ShieldX className="w-10 h-10 text-rose-500" /></div>
                  <h3 className="text-2xl font-black text-white mb-3 uppercase tracking-tighter">Terminate?</h3>
                  <div className="space-y-4">
                      <button onClick={confirmLogout} className="w-full py-4 bg-rose-600 hover:bg-rose-500 text-white font-black rounded-2xl shadow-xl transition-all">Sign Out</button>
                      <button onClick={() => setIsLogoutModalOpen(false)} className="w-full py-4 bg-slate-900/50 text-slate-400 font-bold rounded-2xl border border-white/5 hover:text-white transition-all">Stay Connected</button>
                  </div>
              </div>
          </div>
      )}

      <ToastContainer toasts={toasts} onRemove={removeToast} />
    </div>
  );
};

export default App;

import React, { useMemo, useState, useRef, useEffect } from 'react';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, PieChart, Pie, Cell } from 'recharts';
import { Account, Transaction, TransactionType, Category, UserPlan, Goal, Budget, SpendingStatus, SpendingPeriod } from '../types';
import { Activity, Flame, TrendingUp, Wallet, PlusCircle, CreditCard, Target, Quote, Landmark, Zap, Radio, Repeat, Check, Handshake, Copy, X, Loader2, Sparkles, ArrowUpRight, ArrowDownRight, LayoutGrid, ArrowRight, Pin, Square, CheckSquare, Microscope, PieChart as PieChartIcon, ShieldAlert, BrainCircuit, GripVertical, AlertTriangle, Layers, Circle } from 'lucide-react';
import { generateNegotiationScript } from '../services/geminiService';

interface DashboardProps {
  accounts: Account[];
  transactions: Transaction[];
  goals: Goal[];
  budgets: Budget[];
  onNavigate: (tab: string) => void;
  onAddAccount?: () => void;
  onAddTransaction?: () => void;
  onAddGoal?: () => void;
  formatCurrency: (amount: number) => string | React.ReactNode;
  userPlan?: UserPlan;
  onAskCoach?: (message: string) => void;
  negotiationUsage: number;
  onIncrementNegotiation: () => void;
  isPinMode?: boolean;
  pinnedIds?: string[];
  onTogglePin?: (id: string) => void;
  trackEvent?: (id: string) => void;
  insightUsage?: number;
  // New enforcement props
  spendingStatus?: SpendingStatus;
  currentPeriodSpend?: number;
  spendingLimit?: number;
  spendingPeriod?: SpendingPeriod;
}

const QUOTES = [
  { text: "Do not save what is left after spending, but spend what is left after saving.", author: "Warren Buffett" },
  { text: "A budget is telling your money where to go instead of wondering where it went.", author: "Dave Ramsey" },
  { text: "It's not your salary that makes you rich, it's your spending habits.", author: "Charles A. Jaffe" },
];

const COLORS = ['#6366f1', '#f43f5e', '#f59e0b', '#10b981', '#8b5cf6', '#06b6d4', '#ec4899', '#64748b'];

const Dashboard: React.FC<DashboardProps> = ({ 
    accounts, 
    transactions, 
    goals, 
    budgets,
    onNavigate, 
    onAddAccount, 
    onAddTransaction, 
    onAddGoal, 
    formatCurrency, 
    userPlan, 
    onAskCoach, 
    negotiationUsage, 
    onIncrementNegotiation,
    isPinMode = false,
    pinnedIds = [],
    onTogglePin,
    trackEvent,
    insightUsage = 0,
    spendingStatus,
    currentPeriodSpend = 0,
    spendingLimit = 1000,
    spendingPeriod = 'monthly'
}) => {
  const hasData = accounts.length > 0 || transactions.length > 0;
  const randomQuote = useMemo(() => QUOTES[Math.floor(Math.random() * QUOTES.length)], []);
  const netWorth = useMemo(() => accounts.reduce((acc, curr) => acc + curr.balance, 0), [accounts]);

  const [isNegotiating, setIsNegotiating] = useState(false);
  const [script, setScript] = useState<string | null>(null);
  const [scriptMerchant, setScriptMerchant] = useState('');
  const [showNegotiationModal, setShowNegotiationModal] = useState(false);
  const [copySuccess, setCopySuccess] = useState(false);
  const [showAnalysisConfirm, setShowAnalysisConfirm] = useState(false);

  const today = new Date();
  const currentMonth = today.getMonth();
  const currentYear = today.getFullYear();
  const currentDay = today.getDate();
  const daysInMonth = new Date(currentYear, currentMonth + 1, 0).getDate();

  const stats = useMemo(() => {
    const currentMTDExpenses = transactions.filter(t => {
      const d = new Date(t.date);
      return t.type === TransactionType.EXPENSE && d.getMonth() === currentMonth && d.getFullYear() === currentYear;
    });
    const currentMTDTotal = currentMTDExpenses.reduce((acc, t) => acc + t.amount, 0);

    const prevMonthDate = new Date(currentYear, currentMonth - 1, 1);
    const prevMonth = prevMonthDate.getMonth();
    const prevMonthYear = prevMonthDate.getFullYear();

    const prevMTDExpenses = transactions.filter(t => {
      const d = new Date(t.date);
      return t.type === TransactionType.EXPENSE && d.getMonth() === prevMonth && d.getFullYear() === prevMonthYear && d.getDate() <= currentDay;
    });
    const prevMTDTotal = prevMTDExpenses.reduce((acc, t) => acc + t.amount, 0);
    const spendChange = prevMTDTotal > 0 ? ((currentMTDTotal - prevMTDTotal) / prevMTDTotal) * 100 : 0;

    const mtdNetFlow = transactions
      .filter(t => {
        const d = new Date(t.date);
        return d.getMonth() === currentMonth && d.getFullYear() === currentYear;
      })
      .reduce((acc, t) => acc + (t.type === TransactionType.INCOME ? t.amount : -t.amount), 0);
    const monthStartNW = netWorth - mtdNetFlow;
    const nwChange = monthStartNW !== 0 ? (mtdNetFlow / Math.abs(monthStartNW)) * 100 : 0;

    const currentDailyAvg = currentMTDTotal / Math.max(currentDay, 1);
    const forecastedTotal = currentDailyAvg * daysInMonth;

    // Calculate previous month total to derive forecast change
    const prevMonthTotalExpenses = transactions.filter(t => {
      const d = new Date(t.date);
      return t.type === TransactionType.EXPENSE && d.getMonth() === prevMonth && d.getFullYear() === prevMonthYear;
    }).reduce((acc, t) => acc + t.amount, 0);

    // Burn rate change is effectively the change in daily spending intensity
    const burnChange = spendChange;

    // Forecast change compares predicted total vs last month actual total
    const forecastChange = prevMonthTotalExpenses > 0 ? ((forecastedTotal - prevMonthTotalExpenses) / prevMonthTotalExpenses) * 100 : 0;

    return { currentMTDTotal, spendChange, nwChange, currentDailyAvg, forecastedTotal, burnChange, forecastChange };
  }, [transactions, currentMonth, currentYear, currentDay, netWorth, daysInMonth]);

  // Data for Expenditure Topology (Pie Chart)
  const expenditureData = useMemo(() => {
    const expenses = transactions.filter(t => 
        t.type === TransactionType.EXPENSE && 
        new Date(t.date).getMonth() === currentMonth &&
        new Date(t.date).getFullYear() === currentYear
    );

    const total = expenses.reduce((acc, t) => acc + t.amount, 0);

    const catMap: Record<string, number> = {};

    expenses.forEach(t => {
        catMap[t.category] = (catMap[t.category] || 0) + t.amount;
    });

    const chartData = Object.entries(catMap)
        .map(([name, value]) => ({ name, value }))
        .sort((a, b) => b.value - a.value);

    const topCategories = chartData
        .slice(0, 4)
        .map((item) => ({ ...item, percent: total > 0 ? (item.value / total) * 100 : 0 }));

    return { chartData, topCategories, total };
  }, [transactions, currentMonth, currentYear]);

  const pinnableModules = useMemo(() => {
      // 1. Budget Monitor (Breaches)
      const overBudgetCount = budgets.filter(b => {
          const spent = transactions.filter(t => t.category === b.category && t.type === TransactionType.EXPENSE && new Date(t.date).getMonth() === currentMonth).reduce((acc, t) => acc + t.amount, 0);
          return spent > b.limit;
      }).length;

      // 2. Goal Vector (Global Spending Limit Utilization)
      const budgetUtilization = spendingLimit > 0 ? (currentPeriodSpend / spendingLimit) * 100 : 0;

      const budgetDetails = budgets.map(b => {
          const spent = transactions
            .filter(t => t.category === b.category && t.type === TransactionType.EXPENSE && new Date(t.date).getMonth() === currentMonth)
            .reduce((acc, t) => acc + t.amount, 0);
          return { 
              name: b.category, 
              limit: b.limit, 
              spent, 
              percent: b.limit > 0 ? (spent / b.limit) * 100 : 0 
          };
      }).sort((a, b) => b.percent - a.percent).slice(0, 4);

      // 3. System Alerts
      const alertsCount = overBudgetCount + (stats.spendChange > 10 ? 1 : 0);

      // 4. Token Logic (Remaining)
      const limit = userPlan === 'ultra' ? 1500 : userPlan === 'pro' ? 50 : 3;
      const remaining = Math.max(0, limit - (insightUsage || 0));

      return [
          {
              id: 'budget-monitor',
              title: 'Budget Integrity',
              icon: <PieChartIcon className="w-5 h-5 text-white" />,
              value: overBudgetCount > 0 ? `${overBudgetCount} Breaches` : 'Secure',
              subtext: overBudgetCount > 0 ? 'Immediate audit required' : 'All limits respected',
              color: overBudgetCount > 0 ? 'bg-rose-600' : 'bg-emerald-600',
              spotlight: overBudgetCount > 0 ? 'rgba(244, 63, 94, 0.4)' : 'rgba(16, 185, 129, 0.4)',
              onClick: () => onNavigate('goals')
          },
          {
              id: 'sandbox-link',
              title: 'Sim Sandbox',
              icon: <Microscope className="w-5 h-5 text-white" />,
              value: 'Predictive Core',
              subtext: 'Run ghost scenarios',
              color: 'bg-indigo-600',
              spotlight: 'rgba(99, 102, 241, 0.4)',
              onClick: () => onNavigate('sandbox')
          },
          {
              id: 'goal-tracker',
              title: 'Goal Vector',
              icon: <Target className="w-5 h-5 text-white" />,
              value: spendingLimit > 0 ? formatCurrency(spendingLimit) : 'No Limit',
              subtext: spendingLimit > 0 ? `${budgetUtilization.toFixed(0)}% of Global Limit` : 'Define spending limit',
              color: budgetUtilization > 100 ? 'bg-red-700' : 'bg-rose-600', 
              spotlight: 'rgba(225, 29, 72, 0.4)', 
              progress: budgetUtilization,
              details: budgetDetails, 
              span: 'md:col-start-3 md:row-span-2',
              onClick: () => onNavigate('goals')
          },
          {
              id: 'system-alerts',
              title: 'System Alerts',
              icon: <ShieldAlert className="w-5 h-5 text-white" />,
              value: alertsCount > 0 ? `${alertsCount} Active` : 'Nominal',
              subtext: alertsCount > 0 ? 'Review diagnostic' : 'Systems nominal',
              color: alertsCount > 0 ? 'bg-orange-600' : 'bg-slate-600',
              spotlight: alertsCount > 0 ? 'rgba(234, 88, 12, 0.4)' : 'rgba(148, 163, 184, 0.4)',
              onClick: () => setShowAnalysisConfirm(true)
          },
          {
              id: 'neural-quota',
              title: 'Neural Capacity',
              icon: <BrainCircuit className="w-5 h-5 text-white" />,
              value: `${remaining} Remaining`,
              subtext: `Monthly Cap: ${limit}`,
              color: remaining === 0 ? 'bg-rose-600' : remaining < 10 ? 'bg-amber-600' : 'bg-purple-600',
              spotlight: 'rgba(168, 85, 247, 0.4)',
              onClick: () => onNavigate('plans')
          }
      ];
  }, [budgets, transactions, goals, stats, insightUsage, onNavigate, onAskCoach, currentMonth, userPlan, spendingLimit, currentPeriodSpend]);

  const getSpotlightColorForStatus = (status: string) => {
      switch (status) {
          case 'violation': return 'rgba(244, 63, 94, 0.3)'; // Red
          case 'warning': return 'rgba(245, 158, 11, 0.3)'; // Amber
          default: return 'rgba(16, 185, 129, 0.3)'; // Emerald
      }
  };

  const handleCardMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
      const rect = e.currentTarget.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;
      e.currentTarget.style.setProperty('--mouse-x', `${x}px`);
      e.currentTarget.style.setProperty('--mouse-y', `${y}px`);
  };

  if (!hasData) return (
    <div className="flex flex-col items-center justify-center min-h-[70vh] text-center animate-fade-in relative px-6">
        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-96 h-96 bg-indigo-600/10 rounded-full blur-[100px] pointer-events-none"></div>
        <div className="w-20 h-20 bg-slate-900 border border-white/10 rounded-3xl flex items-center justify-center mb-8 rotate-6 shadow-2xl relative z-10"><Quote className="w-10 h-10 text-indigo-400" /></div>
        <h1 className="text-4xl font-black text-white mb-4 uppercase tracking-tighter italic relative z-10">Vault Initializing...</h1>
        <p className="text-slate-400 max-w-md italic mb-12 relative z-10">"{randomQuote.text}" — {randomQuote.author}</p>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6 w-full max-w-4xl relative z-10">
             <button onClick={onAddAccount} className="p-8 bg-slate-900/60 backdrop-blur-xl border border-white/5 rounded-[2.5rem] hover:border-indigo-500 transition-all text-left shadow-xl hover:-translate-y-1 group"><Landmark className="w-8 h-8 text-indigo-400 mb-6 group-hover:scale-110 transition-transform" /><h3 className="text-xl font-bold text-white mb-2">Sync Nodes</h3><p className="text-slate-500 text-sm">Link bank or manual ledgers.</p></button>
             <button onClick={onAddTransaction} className="p-8 bg-slate-900/60 backdrop-blur-xl border border-white/5 rounded-[2.5rem] hover:border-indigo-500 transition-all text-left shadow-xl hover:-translate-y-1 group"><PlusCircle className="w-8 h-8 text-indigo-400 mb-6 group-hover:scale-110 transition-transform" /><h3 className="text-xl font-bold text-white mb-2">Record Spend</h3><p className="text-slate-500 text-sm">Archive current activity.</p></button>
             <button onClick={onAddGoal} className="p-8 bg-slate-900/60 backdrop-blur-xl border border-white/5 rounded-[2.5rem] hover:border-indigo-500 transition-all text-left shadow-xl hover:-translate-y-1 group"><Target className="w-8 h-8 text-indigo-400 mb-6 group-hover:scale-110 transition-transform" /><h3 className="text-xl font-bold text-white mb-2">Set Objectives</h3><p className="text-slate-500 text-sm">Deploy capital milestones.</p></button>
        </div>
    </div>
  );

  return (
    <div className="space-y-6 pb-10 relative">
      <style>{`
        .spotlight-card { 
            position: relative; 
            overflow: hidden; 
            transition: transform 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94), box-shadow 0.3s ease;
            --mouse-x: -100px;
            --mouse-y: -100px;
            --spotlight-color: rgba(255, 255, 255, 0.1);
        }
        .spotlight-card::before { 
            content: ""; 
            position: absolute; 
            inset: 0; 
            background: radial-gradient(500px circle at var(--mouse-x) var(--mouse-y), var(--spotlight-color), transparent 40%); 
            z-index: 0; 
            pointer-events: none; 
            opacity: 0;
            transition: opacity 0.3s ease;
        }
        .spotlight-card:hover::before {
            opacity: 1;
        }
        .spotlight-card:hover {
            transform: translateY(-2px);
            box-shadow: 0 10px 40px -10px rgba(0,0,0,0.5);
        }
        .pin-mode-overlay {
            position: absolute; inset: -20px; background: rgba(2, 6, 23, 0.85); backdrop-filter: blur(4px); z-index: 50; border-radius: 2rem; pointer-events: none; opacity: 0; transition: opacity 0.3s;
        }
        .pin-active .pin-mode-overlay { opacity: 1; pointer-events: auto; }
        .pin-active .pinnable-item { z-index: 60; position: relative; transform: scale(1.02); box-shadow: 0 0 30px rgba(99, 102, 241, 0.3); border-color: rgba(99, 102, 241, 0.5); cursor: pointer; }
      `}</style>

      <div className={`transition-all duration-500 ${isPinMode ? 'pin-active' : ''}`}>

          <div className="flex justify-between items-center relative z-40 mb-6">
            <div>
              <h2 className="text-3xl font-black text-white tracking-tighter uppercase italic">Control Room</h2>
              {!isPinMode && <p className="text-slate-400 text-xs font-bold uppercase tracking-widest mt-1">Financial performance for {today.toLocaleDateString('en-US', { month: 'long', year: 'numeric' })}</p>}
            </div>
          </div>

          {/* PINNED CLUSTER */}
          {pinnedIds.length > 0 && !isPinMode && (
              <div className="grid grid-cols-2 md:grid-cols-5 gap-3 mb-8 animate-slide-up">
                  {pinnedIds.map(id => {
                      const mod = pinnableModules.find(m => m.id === id);
                      if (!mod) return null;
                      return (
                          <div key={id} onClick={mod.onClick} className="bg-slate-900 border border-white/10 rounded-2xl p-4 flex flex-col justify-between hover:bg-slate-800 transition-all cursor-pointer group hover:border-white/20 h-full">
                              <div className="flex justify-between items-start mb-2">
                                  <div className={`p-2 rounded-lg ${mod.color} bg-opacity-20`}>{mod.icon}</div>
                                  <Pin className="w-3 h-3 text-indigo-400 fill-indigo-400 opacity-50" />
                              </div>
                              <div>
                                  <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest truncate">{mod.title}</h4>
                                  <p className="text-sm font-bold text-white truncate group-hover:text-indigo-400 transition-colors">{mod.value}</p>
                              </div>
                          </div>
                      );
                  })}
              </div>
          )}

          {/* SYSTEM MODULES (Pinnable Grid) */}
          <div className="relative group/pin-container">
              {isPinMode && <div className="pin-mode-overlay"></div>}

              <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8 relative auto-rows-fr">
                  {pinnableModules.map((mod) => {
                      const isPinned = pinnedIds.includes(mod.id);
                      const spanClass = mod.id === 'goal-tracker' ? mod.span : '';
                      const isGoalTracker = mod.id === 'goal-tracker';

                      return (
                          <div 
                            key={mod.id}
                            onMouseMove={handleCardMouseMove}
                            onClick={() => {
                                if (isPinMode && onTogglePin) {
                                    onTogglePin(mod.id);
                                } else if (!isPinMode) {
                                    trackEvent?.(mod.id);
                                    mod.onClick();
                                }
                            }}
                            style={{ '--spotlight-color': mod.spotlight } as React.CSSProperties}
                            className={`pinnable-item spotlight-card glass-card p-6 rounded-[2rem] border border-white/5 flex flex-col ${isGoalTracker ? 'justify-start gap-6' : 'justify-between gap-5'} cursor-pointer h-full ${spanClass} ${isPinMode ? 'hover:bg-slate-900' : ''}`}
                          >
                              <div className="flex items-start justify-between w-full relative z-10">
                                  <div className={`w-14 h-14 rounded-2xl flex items-center justify-center shadow-lg ${mod.color} shrink-0`}>{mod.icon}</div>
                                  {isPinMode && (
                                      <div className={`w-8 h-8 rounded-lg border-2 flex items-center justify-center transition-all ${isPinned ? 'bg-indigo-600 border-indigo-600' : 'border-white/20 bg-slate-950'}`}>
                                          {isPinned && <Check className="w-5 h-5 text-white" />}
                                      </div>
                                  )}
                              </div>

                              <div className={`flex-1 min-w-0 relative z-10 flex flex-col ${isGoalTracker ? 'justify-start pt-2' : 'justify-end'}`}>
                                  <h4 className="text-xs font-black text-slate-400 uppercase tracking-widest mb-1">{mod.title}</h4>
                                  <div className="text-2xl font-bold text-white tracking-tight truncate">{mod.value}</div>
                                  <p className="text-[10px] text-slate-500 font-medium truncate mt-1">
                                      {mod.subtext}
                                  </p>

                                  {/* Progress bar visual for Goal Vector */}
                                  {isGoalTracker && (mod as any).progress !== undefined && (
                                      <div className="mt-8">
                                          <div className="flex justify-between text-[10px] font-bold text-slate-500 mb-2 uppercase tracking-wider">
                                              <span>Global Limit Usage</span>
                                              <span>{(mod as any).progress.toFixed(0)}%</span>
                                          </div>
                                          <div className="w-full h-2 bg-slate-800 rounded-full overflow-hidden border border-white/5">
                                              <div 
                                                  className={`h-full transition-all duration-1000 ease-out ${(mod as any).progress > 100 ? 'bg-red-500' : (mod as any).progress > 80 ? 'bg-orange-500' : 'bg-rose-500'}`} 
                                                  style={{ width: `${Math.min((mod as any).progress, 100)}%` }}
                                              ></div>
                                          </div>
                                      </div>
                                  )}

                                  {/* Detailed List of Budgets for Goal Vector */}
                                  {isGoalTracker && (mod as any).details && (mod as any).details.length > 0 && (
                                      <div className="mt-6 space-y-3 flex-1 overflow-hidden">
                                          <div className="h-px bg-white/5 w-full mb-4"></div>
                                          {(mod as any).details.map((b: any, i: number) => (
                                              <div key={i} className="group/item">
                                                  <div className="flex justify-between text-[10px] font-bold text-slate-400 mb-1">
                                                      <span className="text-white">{b.name}</span>
                                                      <span>{formatCurrency(b.spent)} / {formatCurrency(b.limit)}</span>
                                                  </div>
                                                  <div className="w-full h-1 bg-slate-800 rounded-full overflow-hidden">
                                                      <div 
                                                          className={`h-full rounded-full ${b.percent > 100 ? 'bg-red-500' : b.percent > 80 ? 'bg-orange-500' : 'bg-rose-500'}`} 
                                                          style={{ width: `${Math.min(b.percent, 100)}%` }}
                                                      ></div>
                                                  </div>
                                              </div>
                                          ))}
                                      </div>
                                  )}
                              </div>
                          </div>
                      );
                  })}
              </div>
          </div>

          {/* Standard Stats (Always Visible) */}
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 relative z-10">
            <StatCard 
                title="Net Worth" 
                value={formatCurrency(netWorth)} 
                icon={<Wallet className="w-5 h-5 text-indigo-400" />} 
                change={stats.nwChange.toFixed(1) + '%'} 
                positive={stats.nwChange >= 0} 
                delay="0s" 
                spotlightColor="rgba(99, 102, 241, 0.3)" // Indigo
                onMouseMove={handleCardMouseMove}
            />

            <div 
                className={`spotlight-card glass-card p-8 rounded-[2.5rem] border transition-all shadow-lg group animate-slide-up ${spendingStatus?.colorClass || 'border-white/5'}`} 
                style={{ '--spotlight-color': getSpotlightColorForStatus(spendingStatus?.status || 'normal'), animationDelay: '0.1s' } as React.CSSProperties}
                onMouseMove={handleCardMouseMove}
            >
                <div className="flex justify-between items-start mb-6 relative z-10">
                    <div className="p-4 bg-slate-800 rounded-2xl border border-white/5 text-slate-400 shadow-inner">
                        {spendingStatus?.status === 'violation' ? <ShieldAlert className="w-5 h-5 text-rose-500" /> : spendingStatus?.status === 'warning' ? <AlertTriangle className="w-5 h-5 text-amber-400" /> : <CreditCard className="w-5 h-5 text-emerald-400" />}
                    </div>
                    <div className="text-right">
                        <div className="text-[9px] font-black uppercase tracking-widest text-slate-500 mb-1">{spendingPeriod} Limit</div>
                        <div className="text-xs font-bold text-white">{formatCurrency(spendingLimit || 0)}</div>
                    </div>
                </div>
                <div className="relative z-10">
                    <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-[0.3em] mb-1">Period Spend</h4>
                    <div className="text-3xl font-black text-white tracking-tighter">{formatCurrency(currentPeriodSpend)}</div>
                    <div className={`mt-2 text-[9px] font-black uppercase tracking-widest px-2 py-1 rounded w-fit ${spendingStatus?.status === 'violation' ? 'bg-rose-500 text-white' : spendingStatus?.status === 'warning' ? 'bg-amber-500 text-slate-900' : 'bg-emerald-500/20 text-emerald-400'}`}>
                        {spendingStatus?.message || 'Nominal'}
                    </div>
                </div>
            </div>

            <StatCard 
                title="Burn Rate/Day" 
                value={formatCurrency(stats.currentDailyAvg)} 
                icon={<Flame className="w-5 h-5 text-amber-400" />} 
                change={Math.abs(stats.burnChange).toFixed(1) + '%'} 
                positive={stats.burnChange <= 0} 
                delay="0.2s" 
                spotlightColor="rgba(245, 158, 11, 0.3)" // Amber
                onMouseMove={handleCardMouseMove}
            />
            <StatCard 
                title="Predicted Spend" 
                value={formatCurrency(stats.forecastedTotal)} 
                icon={<TrendingUp className="w-5 h-5 text-emerald-400" />} 
                change={Math.abs(stats.forecastChange).toFixed(1) + '%'} 
                positive={stats.forecastChange <= 0} 
                delay="0.3s"
                spotlightColor="rgba(16, 185, 129, 0.3)" // Emerald
                onMouseMove={handleCardMouseMove}
            />
          </div>

          <div 
            className="mt-8 spotlight-card glass-card p-8 md:p-10 rounded-[2.5rem] border border-white/5 animate-slide-up relative z-10"
            style={{ '--spotlight-color': 'rgba(99, 102, 241, 0.15)' } as React.CSSProperties}
            onMouseMove={handleCardMouseMove}
          >
              <h3 className="text-xl font-black text-white uppercase tracking-tight flex items-center gap-3 mb-10 relative z-10"><Layers className="w-7 h-7 text-indigo-400" />Expenditure Topology</h3>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-8 items-center relative z-10">
                  <div className="flex justify-center relative h-64">
                      {expenditureData.total > 0 ? (
                          <ResponsiveContainer width="100%" height="100%">
                              <PieChart>
                                  <Pie
                                      data={expenditureData.chartData}
                                      cx="50%"
                                      cy="50%"
                                      innerRadius={60}
                                      outerRadius={80}
                                      paddingAngle={5}
                                      dataKey="value"
                                      stroke="none"
                                  >
                                      {expenditureData.chartData.map((entry, index) => (
                                          <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                                      ))}
                                  </Pie>
                                  <Tooltip 
                                      contentStyle={{ backgroundColor: '#0f172a', borderColor: '#1e293b', borderRadius: '12px', fontSize: '12px' }}
                                      itemStyle={{ color: '#fff', fontWeight: 'bold' }}
                                      formatter={(value: number) => formatCurrency(value)}
                                  />
                                  <text x="50%" y="50%" textAnchor="middle" dominantBaseline="middle" className="fill-white font-black" style={{ fontSize: '18px', fontWeight: 900 }}>
                                      {formatCurrency(expenditureData.total)}
                                  </text>
                                  <text x="50%" y="50%" dy={20} textAnchor="middle" dominantBaseline="middle" className="fill-slate-500 text-[10px] font-bold uppercase tracking-widest">
                                      Total
                                  </text>
                              </PieChart>
