// Batch Upload Implementation (Elite Only)
const BatchUploadModal: React.FC<{
    onClose: () => void;
    onAdd: (t: Transaction) => void;
    accounts: Account[];
    scanUsage: number;
    onIncrementScan?: () => void;
    formatCurrency: (amount: number) => string | React.ReactNode;
}> = ({ onClose, onAdd, accounts, scanUsage, onIncrementScan, formatCurrency }) => {
    const [files, setFiles] = useState<{ file: File; id: string; status: 'pending' | 'processing' | 'success' | 'error'; progress: number; result?: any; errorMsg?: string }[]>([]);
    const [isUploading, setIsUploading] = useState(false);
    const [selectedAccountId, setSelectedAccountId] = useState<string>(accounts[0]?.id || 'manual');
    const inputRef = useRef<HTMLInputElement>(null);

    const MAX_BATCH = 10;

    const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
        const selected = Array.from(e.target.files || []).slice(0, MAX_BATCH);
        const newFiles = selected.map(f => ({
            file: f,
            id: Math.random().toString(36).substr(2, 9),
            status: 'pending' as const,
            progress: 0
        }));
        setFiles(prev => [...prev, ...newFiles].slice(0, MAX_BATCH));
    };

    const processBatch = async () => {
        setIsUploading(true);
        // Process sequentially to respect throttling and count scans correctly
        for (let i = 0; i < files.length; i++) {
            const fItem = files[i];
            if (fItem.status !== 'pending') continue;

            setFiles(prev => prev.map(p => p.id === fItem.id ? { ...p, status: 'processing', progress: 30 } : p));

            try {
                const base64 = await compressImage(fItem.file);
                setFiles(prev => prev.map(p => p.id === fItem.id ? { ...p, progress: 60 } : p));

                const result = await parseReceiptImage(base64);
                if (result) {
                    const newTx: Transaction = {
                        id: Date.now().toString() + i,
                        date: result.date || new Date().toISOString().split('T')[0],
                        merchant: result.merchant || 'Unknown Merchant',
                        amount: result.amount || 0,
                        category: (result.category as Category) || Category.OTHER,
                        type: TransactionType.EXPENSE,
                        accountId: selectedAccountId,
                    };
                    onAdd(newTx);
                    if (onIncrementScan) onIncrementScan();
                    setFiles(prev => prev.map(p => p.id === fItem.id ? { ...p, status: 'success', progress: 100, result: newTx } : p));
                } else {
                    throw new Error("AI parsing failed");
                }
            } catch (err) {
                setFiles(prev => prev.map(p => p.id === fItem.id ? { ...p, status: 'error', progress: 100, errorMsg: "Extraction Failed" } : p));
            }
        }
        setIsUploading(false);
    };

    const compressImage = (file: File): Promise<string> => {
        return new Promise((resolve) => {
            const reader = new FileReader();
            reader.readAsDataURL(file);
            reader.onload = (e) => {
                const img = new Image();
                img.src = e.target?.result as string;
                img.onload = () => {
                    const canvas = document.createElement('canvas');
                    const MAX_WIDTH = 800;
                    let width = img.width;
                    let height = img.height;
                    if (width > MAX_WIDTH) { height *= MAX_WIDTH / width; width = MAX_WIDTH; }
                    canvas.width = width;
                    canvas.height = height;
                    const ctx = canvas.getContext('2d');
                    if (ctx) {
                        ctx.drawImage(img, 0, 0, width, height);
                        resolve(canvas.toDataURL('image/jpeg', 0.7).split(',')[1]);
                    }
                }
            };
        });
    };

    return (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-black/95 backdrop-blur-2xl animate-fade-in">
            <div className="bg-[#0f172a] border border-white/10 rounded-[3rem] w-full max-w-2xl shadow-2xl overflow-hidden animate-slide-up flex flex-col max-h-[85vh]">
                <button onClick={onClose} className="absolute top-6 right-6 p-2 text-slate-500 hover:text-white z-10"><X className="w-6 h-6" /></button>
                <div className="p-10 border-b border-white/5 bg-gradient-to-br from-indigo-900/20 to-transparent">
                    <div className="w-16 h-16 bg-indigo-600 rounded-2xl flex items-center justify-center mb-6 shadow-xl"><Layers className="w-8 h-8 text-white" /></div>
                    <h3 className="text-3xl font-black text-white uppercase tracking-tighter">Elite Batch Uplink</h3>
                    <p className="text-slate-400 text-sm mt-1 font-medium">Deploy multiple receipts to the ledger simultaneously.</p>
                </div>

                <div className="flex-1 overflow-y-auto p-10 custom-scrollbar space-y-8">
                    {files.length === 0 ? (
                        <div 
                            onClick={() => inputRef.current?.click()}
                            className="border-2 border-dashed border-slate-700 hover:border-indigo-500 bg-slate-900/50 rounded-[2rem] p-16 flex flex-col items-center justify-center gap-4 cursor-pointer transition-all group"
                        >
                            <div className="w-20 h-20 bg-slate-800 rounded-3xl flex items-center justify-center group-hover:scale-110 transition-transform"><FileUp className="w-10 h-10 text-slate-500 group-hover:text-indigo-400" /></div>
                            <div className="text-center">
                                <p className="text-white font-bold">Drop or click to select receipts</p>
                                <p className="text-slate-500 text-xs mt-1 uppercase tracking-widest font-black">Max 10 per batch</p>
                            </div>
                        </div>
                    ) : (
                        <div className="space-y-4">
                            {files.map(f => (
                                <div key={f.id} className="p-5 bg-slate-900/80 rounded-2xl border border-white/5 flex items-center gap-5 relative overflow-hidden group">
                                    {f.status === 'processing' && <div className="absolute bottom-0 left-0 h-1 bg-indigo-500 animate-shimmer" style={{ width: `${f.progress}%` }}></div>}
                                    <div className="w-12 h-12 rounded-xl bg-slate-800 flex items-center justify-center text-slate-500 group-hover:text-white shrink-0">
                                        {f.status === 'success' ? <Check className="w-6 h-6 text-emerald-400" /> : f.status === 'error' ? <AlertTriangle className="w-6 h-6 text-rose-400" /> : <FileText className="w-6 h-6" />}
                                    </div>
                                    <div className="flex-1 min-w-0">
                                        <div className="flex justify-between items-start">
                                            <h4 className="text-sm font-bold text-white truncate">{f.file.name}</h4>
                                            {f.status === 'success' && <span className="text-[10px] font-black text-emerald-400 uppercase">{formatCurrency(f.result.amount)}</span>}
                                        </div>
                                        <div className="flex items-center gap-3 mt-1">
                                            <span className={`text-[9px] font-black uppercase tracking-widest ${f.status === 'success' ? 'text-emerald-500' : f.status === 'error' ? 'text-rose-500' : 'text-slate-500'}`}>
                                                {f.status === 'pending' ? 'Ready to Sync' : f.status === 'processing' ? 'AI Neural Parse...' : f.status === 'success' ? 'Archived Successfully' : f.errorMsg}
                                            </span>
                                        </div>
                                    </div>
                                    {!isUploading && f.status === 'pending' && (
                                        <button onClick={() => setFiles(prev => prev.filter(p => p.id !== f.id))} className="p-2 text-slate-600 hover:text-rose-500"><X className="w-4 h-4" /></button>
                                    )}
                                </div>
                            ))}
                        </div>
                    )}

                    <div className="space-y-4">
                        <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Destination Node</label>
                        <select value={selectedAccountId} onChange={(e) => setSelectedAccountId(e.target.value)} className="w-full bg-slate-950 border border-white/10 rounded-xl p-4 text-white text-sm focus:border-indigo-500 appearance-none cursor-pointer">
                            {accounts.map(acc => <option key={acc.id} value={acc.id}>{acc.name}</option>)}
                            <option value="manual">Manual / Cash</option>
                        </select>
                    </div>

                    <div className="p-4 bg-indigo-500/5 rounded-2xl border border-indigo-500/10 flex items-center gap-4">
                        <div className="p-2 rounded-lg bg-indigo-500/10"><ScanLine className="w-5 h-5 text-indigo-400" /></div>
                        <div>
                            <p className="text-[10px] text-indigo-200/60 font-bold uppercase tracking-wider">Quota Telemetry</p>
                            <p className="text-xs text-white font-bold">{files.length} Scans Ready • {scanUsage} used this cycle</p>
                        </div>
                    </div>
                </div>

                <div className="p-10 border-t border-white/5 bg-slate-900/20 flex gap-4">
                    <input type="file" ref={inputRef} multiple accept="image/*" onChange={handleFileSelect} hidden />
                    <button 
                        onClick={onClose} 
                        className="flex-1 py-4 bg-slate-800 hover:bg-slate-700 text-slate-300 font-black uppercase text-xs tracking-widest rounded-2xl transition-all"
                    >
                        Abort
                    </button>
                    <button 
                        disabled={files.length === 0 || isUploading}
                        onClick={processBatch}
                        className="flex-[2] py-4 bg-indigo-600 hover:bg-indigo-500 disabled:opacity-50 text-white font-black uppercase text-xs tracking-widest rounded-2xl shadow-xl transition-all flex items-center justify-center gap-3"
                    >
                        {isUploading ? <><Loader2 className="w-4 h-4 animate-spin" /> Synchronizing...</> : <><Upload className="w-4 h-4" /> Start Sequential Sync</>}
                    </button>
                </div>
            </div>
        </div>
    );
};

const AddTransactionModal: React.FC<{ 
    onClose: () => void; 
    onAdd: (t: Transaction) => void;
    accounts: Account[];
    onNavigateToAccounts?: () => void;
    userPlan?: UserPlan;
    formatCurrency: (amount: number) => string | React.ReactNode;
    scanUsage: number;
    onIncrementScan?: () => void;
    currency: Currency;
}> = ({ onClose, onAdd, accounts, onNavigateToAccounts, userPlan, formatCurrency, scanUsage, onIncrementScan, currency }) => {
    const [type, setType] = useState<TransactionType>(TransactionType.EXPENSE);
    const [merchant, setMerchant] = useState('');
    const [amount, setAmount] = useState('');
    const [category, setCategory] = useState<Category | ''>('');
    const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
    const [selectedAccountId, setSelectedAccountId] = useState<string>(accounts[0]?.id || '');
    const [notes, setNotes] = useState('');
    const [isAutoCategorizing, setIsAutoCategorizing] = useState(false);
    const [isScanning, setIsScanning] = useState(false);
    const [scanError, setScanError] = useState<string | null>(null);
    const fileInputRef = useRef<HTMLInputElement>(null);

    const isUltra = userPlan === 'ultra';
    const isPro = userPlan === 'pro';
    const scanLimit = isUltra ? 1500 : isPro ? 50 : 3;
    const canScan = scanUsage < scanLimit;

    const expenseCategories = Object.values(Category).filter(c => c !== Category.INCOME && c !== Category.INVESTMENT);
    const incomeCategories = [Category.INCOME, Category.INVESTMENT, Category.OTHER];

    const compressImage = (file: File): Promise<string> => {
        return new Promise((resolve, reject) => {
            const reader = new FileReader();
            reader.readAsDataURL(file);
            reader.onload = (e) => {
                const img = new Image();
                img.src = e.target?.result as string;
                img.onload = () => {
                    const canvas = document.createElement('canvas');
                    const MAX_WIDTH = 800;
                    let width = img.width;
                    let height = img.height;
                    if (width > MAX_WIDTH) { height *= MAX_WIDTH / width; width = MAX_WIDTH; }
                    canvas.width = width;
                    canvas.height = height;
                    const ctx = canvas.getContext('2d');
                    if (ctx) {
                        ctx.drawImage(img, 0, 0, width, height);
                        resolve(canvas.toDataURL('image/jpeg', 0.7).split(',')[1]); 
                    } else { reject(new Error("Canvas failure")); }
                }
            };
        });
    };

    const handleMerchantBlur = async () => {
        if (!merchant || isAutoCategorizing || !isPro || category) return;
        setIsAutoCategorizing(true);
        try {
            const predicted = await categorizeTransaction(merchant, parseFloat(amount) || 0);
            if (Object.values(Category).includes(predicted as Category)) setCategory(predicted as Category);
        } finally { setIsAutoCategorizing(false); }
    };

    const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;
        setIsScanning(true);
        setScanError(null);
        try {
            const base64 = await compressImage(file);
            const result = await parseReceiptImage(base64);
            if (result) {
                setMerchant(result.merchant || '');
                setAmount(result.amount?.toString() || '');
                if (result.date) setDate(result.date);
                if (onIncrementScan) onIncrementScan();
            } else { setScanError("AI could not parse receipt. Entry required manually."); }
        } catch (err) { setScanError("Scanning protocol failure."); } finally { setIsScanning(false); }
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (!merchant || !amount || !category) return;
        if (type === TransactionType.EXPENSE && !selectedAccountId) return;
        const newTx: Transaction = {
            id: Date.now().toString(),
            date,
            merchant,
            amount: parseFloat(amount),
            category: category as Category,
            type,
            accountId: selectedAccountId || 'manual',
            notes
        };
        onAdd(newTx);
        onClose();
    };

    return (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/80 backdrop-blur-md animate-fade-in">
            <div className="bg-[#0f172a] border border-white/10 rounded-3xl w-full max-w-lg shadow-2xl overflow-hidden animate-slide-up flex flex-col max-h-[90vh]">
                <button onClick={onClose} className="absolute top-4 right-4 p-2 text-slate-400 hover:text-white z-10"><X className="w-6 h-6" /></button>
                <div className="p-8 border-b border-white/5 bg-gradient-to-r from-indigo-900/20 to-transparent">
                    <h3 className="text-2xl font-black text-white uppercase tracking-tighter">Log Financial Event</h3>
                    <p className="text-slate-500 text-[10px] font-bold uppercase tracking-[0.2em] mt-1">Archive spent or earned capital nodes.</p>
                </div>
                <div className="overflow-y-auto p-8 custom-scrollbar">
                    <form onSubmit={handleSubmit} className="space-y-6">
                        <div className="relative">
                            <input type="file" accept="image/*" ref={fileInputRef} onChange={handleFileChange} hidden />
                            <button 
                                type="button" 
                                onClick={() => fileInputRef.current?.click()}
                                disabled={!canScan || isScanning}
                                className={`w-full py-4 rounded-xl border-2 border-dashed transition-all flex items-center justify-center gap-3 ${isScanning ? 'border-indigo-500 bg-indigo-500/10' : !canScan ? 'opacity-50 grayscale cursor-not-allowed' : 'border-slate-700 bg-slate-800/30 hover:border-indigo-500 hover:text-white text-slate-400'}`}
                            >
                                {isScanning ? <Loader2 className="w-5 h-5 animate-spin text-indigo-400" /> : <Camera className="w-5 h-5" />}
                                <span className="text-xs font-black uppercase tracking-widest">{isScanning ? "Processing Optical Data..." : !canScan ? "Optical Limit Reached" : "Extract via Optical Scan"}</span>
                            </button>
                        </div>

                        <div className="relative flex bg-slate-950 rounded-2xl p-1.5 border border-white/10 h-14">
                            <div className={`absolute top-1.5 bottom-1.5 rounded-xl shadow-lg transition-all duration-300 ${type === TransactionType.EXPENSE ? 'left-1.5 w-[calc(50%-6px)] bg-rose-600' : 'left-[calc(50%+3px)] w-[calc(50%-6px)] bg-emerald-600'}`}></div>
                            <button type="button" onClick={() => setType(TransactionType.EXPENSE)} className={`relative z-10 flex-1 text-xs font-black uppercase tracking-widest ${type === TransactionType.EXPENSE ? 'text-white' : 'text-slate-500'}`}>Expense</button>
                            <button type="button" onClick={() => setType(TransactionType.INCOME)} className={`relative z-10 flex-1 text-xs font-black uppercase tracking-widest ${type === TransactionType.INCOME ? 'text-white' : 'text-slate-500'}`}>Income</button>
                        </div>

                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Magnitude</label>
                                <div className="relative mt-2">
                                    <DollarSign className="absolute left-3.5 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500" />
                                    <input required type="number" step="0.01" value={amount} onChange={e => setAmount(e.target.value)} className="w-full bg-slate-950/50 border border-white/10 rounded-xl p-3.5 pl-9 text-white focus:border-indigo-500 focus:outline-none font-mono text-lg" placeholder="0.00" />
                                </div>
                            </div>
                            <div>
                                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Timestamp</label>
                                <input required type="date" value={date} onChange={e => setDate(e.target.value)} className="w-full bg-slate-950/50 border border-white/10 rounded-xl p-3.5 text-white mt-2 focus:border-indigo-500 focus:outline-none text-sm [color-scheme:dark]" />
                            </div>
                        </div>

                        <div>
                            <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Merchant / Source</label>
                            <input required type="text" value={merchant} onChange={e => setMerchant(e.target.value)} onBlur={handleMerchantBlur} className="w-full bg-slate-950/50 border border-white/10 rounded-xl p-3.5 text-white mt-2 focus:border-indigo-500 focus:outline-none text-sm" placeholder="Starbucks, Apple, Salary..." />
                        </div>

                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Category</label>
                                <select required value={category} onChange={e => setCategory(e.target.value as Category)} className="w-full bg-slate-950/50 border border-white/10 rounded-xl p-3.5 text-white mt-2 focus:border-indigo-500 focus:outline-none focus:xs appearance-none cursor-pointer">
                                    <option value="" disabled>Select Vector</option>
                                    {(type === TransactionType.INCOME ? incomeCategories : expenseCategories).map(c => <option key={c} value={c}>{c}</option>)}
                                </select>
                            </div>
                            <div>
                                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Linked Node</label>
                                <select value={selectedAccountId} onChange={(e) => setSelectedAccountId(e.target.value)} className="w-full bg-slate-950/50 border border-white/10 rounded-xl p-3.5 text-white mt-2 focus:border-indigo-500 focus:outline-none text-xs appearance-none cursor-pointer">
                                    <option value="manual">Manual / Cash</option>
                                    {accounts.map(acc => <option key={acc.id} value={acc.id}>{acc.name}</option>)}
                                </select>
                            </div>
                        </div>

                        <button type="submit" className="w-full py-4 bg-indigo-600 hover:bg-indigo-500 text-white font-black text-sm uppercase tracking-[0.2em] rounded-xl shadow-lg active:scale-95 transition-all">Synchronize Entry</button>
                    </form>
                </div>
            </div>
        </div>
    );
};

export default Transactions;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { Transaction, AIAnalysisResponse, ChatMessage, UserPlan, TransactionType, Budget, BotMode, Category, Goal, FinancialSnapshot, SuggestedAction, GoalProposal } from '../types';
import { analyzeFinancialData, chatWithFinancialCoach } from '../services/geminiService';
import { RefreshCcw, CheckCircle, AlertTriangle, ShieldAlert, Info, TrendingUp, Bot, User, BrainCircuit, Lightbulb, Send, Lock, Sparkles, RefreshCw, Flame, ArrowRight, Zap, Crown, TrendingDown, ShoppingCart, Wallet, Terminal, Activity, MousePointerClick, ChevronRight, Check, X, EyeOff, Target } from 'lucide-react';

interface InsightsProps {
  transactions: Transaction[];
  goals: Goal[];
  budgets: Budget[];
  userPlan: UserPlan;
  onUpgradeClick: () => void;
  formatCurrency: (amount: number) => string | React.ReactNode;
  initialPrompt?: string | null; 
  onPromptHandled?: () => void; 
  onApplyBudgets?: (budgets: Budget[]) => void; 
  insightUsage: number; 
  onIncrementUsage: () => void; 
  botMode: BotMode;
  onNavigate: (tab: string) => void;
  onAddGoal?: (goal: Goal) => void;
}

const Insights: React.FC<InsightsProps> = ({ transactions, goals, budgets, userPlan, onUpgradeClick, formatCurrency, initialPrompt, onPromptHandled, onApplyBudgets, insightUsage, onIncrementUsage, botMode, onNavigate, onAddGoal }) => {
  const [analysis, setAnalysis] = useState<AIAnalysisResponse | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [chatInput, setChatInput] = useState('');
  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([
    { 
        id: '1', 
        role: 'assistant', 
        content: botMode === 'ruthless' 
            ? 'System initialized. Ready to audit your spending vectors.' 
            : 'Hello! I\'m ready to help you optimize your financial wellness. What\'s on your mind?', 
        timestamp: new Date(),
        sentiment: 'info'
    }
  ]);
  const [chatLoading, setChatLoading] = useState(false);
  const [showRejectModal, setShowRejectModal] = useState<GoalProposal | null>(null);
  const [rejectionReason, setRejectionReason] = useState('');

  const chatEndRef = useRef<HTMLDivElement>(null);

  const isUltra = userPlan === 'ultra';
  const isElite = isUltra;
  const isPro = userPlan === 'pro';

  // Industrial Grade Limits
  const FREE_LIMIT = 3;
  const PRO_LIMIT = 50;
  const ULTRA_LIMIT = 1500;

  const currentLimit = isUltra ? ULTRA_LIMIT : isPro ? PRO_LIMIT : FREE_LIMIT;
  const isLocked = insightUsage >= currentLimit;

  // Logic Variables for UI (Raw Math)
  const burnoutData = useMemo(() => {
    const expenseMap = new Map<string, number>();
    transactions
        .filter(t => t.type === TransactionType.EXPENSE)
        .forEach(t => {
            expenseMap.set(t.category, (expenseMap.get(t.category) || 0) + t.amount);
        });

    let maxCat = '';
    let maxAmount = 0;
    expenseMap.forEach((val, key) => {
        if (val > maxAmount) {
            maxAmount = val;
            maxCat = key;
        }
    });
    return { category: maxCat, amount: maxAmount };
  }, [transactions]);

  const leakageData = useMemo(() => {
    const expenses = transactions.filter(t => t.type === TransactionType.EXPENSE);
    const totalExpense = expenses.reduce((acc, t) => acc + t.amount, 0);

    // Group by Category
    const catMap: Record<string, number> = {};
    expenses.forEach(t => {
        catMap[t.category] = (catMap[t.category] || 0) + t.amount;
    });

    const sortedCats = Object.entries(catMap).sort((a, b) => b[1] - a[1]);
    const topLeak = sortedCats[0] || ['None', 0];

    // "Impulse" or Discretionary - rough heuristic
    const discretionaryCats = [Category.SHOPPING, Category.ENTERTAINMENT, Category.FOOD, Category.SUBSCRIPTION];
    const discretionaryTotal = expenses
        .filter(t => discretionaryCats.includes(t.category))
        .reduce((acc, t) => acc + t.amount, 0);

    return {
        topCategory: topLeak[0],
        topAmount: topLeak[1],
        discretionaryTotal,
        totalExpense
    };
  }, [transactions]);

  // Manual Trigger Logic - Removed useEffect for auto-run
  const runAnalysis = async () => {
    if (isLocked) return;
    setLoading(true);
    setError(null);
    onIncrementUsage();
    try {
      const result = await analyzeFinancialData(transactions, userPlan);

      // Filter out recent rejections (7-day cooldown)
      if (result && result.goal_proposals) {
          const rejectedRaw = localStorage.getItem('nova_rejected_proposals');
          const rejectedList: {id: string, type: string, timestamp: number}[] = rejectedRaw ? JSON.parse(rejectedRaw) : [];
          const sevenDaysMs = 7 * 24 * 60 * 60 * 1000;

          result.goal_proposals = result.goal_proposals.filter(p => {
              const rejection = rejectedList.find(r => r.id === p.id || (r.type === p.type && p.title.includes(r.id))); // Heuristic matching
              if (!rejection) return true;
              return (Date.now() - rejection.timestamp) > sevenDaysMs;
          });
      }

      if (result) {
        setAnalysis(result);
      } else {
        setError("Coach is analyzing other portfolios. Try again.");
      }
    } catch (e) {
      setError("Unable to connect to financial brain.");
    } finally {
      setLoading(false);
    }
  };

  const handleAcceptProposal = (proposal: GoalProposal) => {
      if (proposal.type === 'goal' && onAddGoal) {
          onAddGoal({
              id: Date.now().toString(),
              name: proposal.title,
              targetAmount: proposal.target_amount,
              currentAmount: 0,
              deadline: proposal.deadline || new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
              icon: 'star',
              color: 'from-emerald-500 to-teal-500'
          });
      } else if (proposal.type === 'budget' && onApplyBudgets) {
          onApplyBudgets([{
              id: `ai_${Date.now()}`,
              category: (proposal.category as Category) || Category.OTHER,
              limit: proposal.target_amount
          }]);
      }

      // Remove from view
      if (analysis) {
          setAnalysis({
              ...analysis,
              goal_proposals: analysis.goal_proposals.filter(p => p.id !== proposal.id)
          });
      }
  };

  const handleRejectProposal = () => {
      if (!showRejectModal) return;

      const rejectedRaw = localStorage.getItem('nova_rejected_proposals');
      const rejectedList = rejectedRaw ? JSON.parse(rejectedRaw) : [];
      rejectedList.push({
          id: showRejectModal.id, // Or a simplified ID to track category/type
          type: showRejectModal.type,
          title: showRejectModal.title, // Use title for loose matching on re-proposal
          timestamp: Date.now(),
          reason: rejectionReason
      });
      localStorage.setItem('nova_rejected_proposals', JSON.stringify(rejectedList));

      // Remove from view
      if (analysis) {
          setAnalysis({
              ...analysis,
              goal_proposals: analysis.goal_proposals.filter(p => p.id !== showRejectModal.id)
          });
      }

      setShowRejectModal(null);
      setRejectionReason('');
  };

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [chatHistory, chatLoading]);

  useEffect(() => {
      if (!isLocked && initialPrompt && !chatLoading) {
          handleSendMessage(null, initialPrompt);
          if (onPromptHandled) onPromptHandled();
      }
  }, [initialPrompt, isLocked]);

  const handleSendMessage = async (e: React.FormEvent | null, promptOverride?: string) => {
    if (e) e.preventDefault();
    const content = promptOverride || chatInput;
    if (!content.trim() || isLocked) return;

    onIncrementUsage();
    const userMsg: ChatMessage = { id: Date.now().toString(), role: 'user', content: content, timestamp: new Date() };
    setChatHistory(prev => [...prev, userMsg]);
    setChatInput('');
    setChatLoading(true);

    // Build Financial Snapshot (Client-Side Logic)
    const now = new Date();
    const currentMonthTxs = transactions.filter(t => new Date(t.date).getMonth() === now.getMonth());
    const income = currentMonthTxs.filter(t => t.type === TransactionType.INCOME).reduce((sum, t) => sum + t.amount, 0);
    const expense = currentMonthTxs.filter(t => t.type === TransactionType.EXPENSE).reduce((sum, t) => sum + t.amount, 0);

    // Calculate top category
    const catMap: Record<string, number> = {};
    currentMonthTxs.filter(t => t.type === TransactionType.EXPENSE).forEach(t => { catMap[t.category] = (catMap[t.category] || 0) + t.amount; });
    const topCat = Object.entries(catMap).sort((a,b) => b[1] - a[1])[0];

    const snapshot: FinancialSnapshot = {
        currentMonthMetrics: {
            income,
            expense,
            savingsRate: income > 0 ? (income - expense) / income : 0,
            topExpenseCategory: topCat ? topCat[0] : 'None'
        },
        recentTransactions: transactions.slice(0, 10), // Context-Aware Agent (Limited to 10)
        activeGoals: goals,
        budgets: budgets
    };

    const response = await chatWithFinancialCoach(userMsg.content, chatHistory, snapshot, botMode);

    const aiMsg: ChatMessage = { 
        id: (Date.now() + 1).toString(), 
        role: 'assistant', 
        content: response.message, 
        timestamp: new Date(),
        sentiment: response.sentiment as any,
        suggestedActions: response.suggestedActions
    };

    setChatHistory(prev => [...prev, aiMsg]);
    setChatLoading(false);
  };

  const handleActionClick = (action: SuggestedAction) => {
      if (action.actionId.startsWith('navigate_')) {
          const tab = action.actionId.replace('navigate_', '');
          onNavigate(tab);
      } else {
          // Assume it's a chat prompt or generic ID
          handleSendMessage(null, action.payload || action.label);
      }
  };

  const handleAutoTune = () => {
      if (!analysis || !onApplyBudgets) return;
      const newBudgets: Budget[] = analysis.budget_suggestions.map(bs => ({
          id: `ai_${Date.now()}_${bs.category}`,
          category: bs.category as any,
          limit: bs.suggested_limit
      }));
      onApplyBudgets(newBudgets);
  };

  const getColorClass = (type: string) => {
    switch (type) {
        case 'success': return 'bg-emerald-500/10 border-emerald-500/20 text-emerald-100 shadow-[0_4px_20px_rgba(16,185,129,0.1)]';
        case 'warning': return 'bg-amber-500/10 border-amber-500/20 text-amber-100 shadow-[0_4px_20px_rgba(245,158,11,0.1)]';
        case 'critical': return 'bg-rose-500/10 border-rose-500/20 text-rose-100 shadow-[0_4px_20px_rgba(244,63,94,0.1)]';
        default: return 'bg-blue-500/10 border-blue-500/20 text-blue-100 shadow-[0_4px_20px_rgba(59,130,246,0.1)]';
    }
  };

  const getIconForType = (type: string) => {
      switch (type) {
        case 'success': return <CheckCircle className="w-5 h-5 text-emerald-400" />;
        case 'warning': return <AlertTriangle className="w-5 h-5 text-amber-400" />;
        case 'critical': return <ShieldAlert className="w-5 h-5 text-rose-400" />;
        default: return <Info className="w-5 h-5 text-blue-400" />;
      }
    };

  const getChatBubbleStyle = (role: string, sentiment?: string) => {
      if (role === 'user') return 'bg-indigo-600 text-white border-indigo-500/50';

      switch (sentiment) {
          case 'critical': return 'bg-rose-950/40 border-rose-500/30 text-rose-100 shadow-[0_0_15px_rgba(244,63,94,0.2)]';
          case 'warning': return 'bg-amber-950/40 border-amber-500/30 text-amber-100 shadow-[0_0_15px_rgba(245,158,11,0.2)]';
          case 'success': return 'bg-emerald-950/40 border-emerald-500/30 text-emerald-100 shadow-[0_0_15px_rgba(16,185,129,0.2)]';
          default: return 'bg-slate-800/80 border-white/10 text-slate-200';
      }
  };

  return (
    <div className="relative h-[calc(100vh-8rem)]">
      {isLocked && (
        <div className="absolute inset-0 z-50 flex items-center justify-center bg-slate-950/60 backdrop-blur-xl rounded-[2rem] border border-white/10 transform scale-105 transition-transform duration-500">
            <div className="text-center p-8 max-w-md animate-slide-up">
                <div className="w-20 h-20 rounded-3xl bg-gradient-to-tr from-indigo-500 to-purple-500 flex items-center justify-center mx-auto mb-6 shadow-2xl shadow-indigo-500/40"><Lock className="w-10 h-10 text-white" /></div>
                <h2 className="text-3xl font-bold text-white mb-3">Limit Reached</h2>
                <p className="text-slate-400 mb-8 leading-relaxed">
                    You've hit your monthly cap of {currentLimit} interactions for your {userPlan.toUpperCase()} plan. Upgrade or manage your plan to continue using the AI Coach.
                </p>
                {!isUltra && (
                    <button onClick={onUpgradeClick} className="w-full py-4 bg-white text-indigo-900 font-bold rounded-xl shadow-xl hover:scale-[1.02] active:scale-95 transition-all flex items-center justify-center gap-2 group"><Sparkles className="w-5 h-5 text-indigo-600 group-hover:rotate-12 transition-transform" />Upgrade Plan</button>
                )}
            </div>
