                      <div className="text-center py-10 text-slate-500 text-xs font-medium italic">
                          No recurring vectors detected.
                      </div>
                  )}
              </div>

              <div className="absolute bottom-0 left-0 w-full p-6 bg-gradient-to-t from-[#0f172a] to-transparent">
                  <button 
                    onClick={() => setManualModalOpen(true)}
                    className="w-full py-3 bg-slate-800 hover:bg-slate-700 text-slate-300 font-bold text-xs uppercase tracking-widest rounded-xl transition-all flex items-center justify-center gap-2"
                  >
                      <Plus className="w-4 h-4" /> Add Missing Subscription
