                              <div className="flex-1">
                                  <h4 className="text-[10px] font-black text-indigo-300 uppercase tracking-widest mb-1">Neural Analysis</h4>
                                  <p className="text-sm text-slate-300 font-medium leading-relaxed">
                                      {aiInsight || "Analyzing vendor patterns and market rates..."}
