                                      </div>

                                      <div className="space-y-3">
                                          <div className="text-[10px] font-black text-slate-500 uppercase tracking-widest px-1">Cancellation Protocol</div>
                                          {[
                                              "Log in to account dashboard.",
                                              "Navigate to 'Billing' or 'Subscription' settings.",
                                              "Locate 'Cancel Membership' (often hidden at bottom).",
                                              "Decline retention offers unless > 30% off."
