                                              <div key={i} className="flex items-center gap-3 p-3 rounded-xl bg-slate-800/50 border border-white/5">
                                                  <div className="w-5 h-5 rounded-full bg-slate-700 flex items-center justify-center text-[10px] font-bold text-white shrink-0">{i + 1}</div>
                                                  <span className="text-sm text-slate-300 font-medium">{step}</span>
                                              </div>
                                          ))}
                                      </div>

                                      <button className="w-full py-4 bg-slate-100 hover:bg-white text-slate-900 font-black uppercase text-xs tracking-[0.2em] rounded-xl transition-all flex items-center justify-center gap-2 group">
                                          Open {selectedSub.merchant} Portal
