              ) : (
                  <div className="h-full min-h-[400px] flex flex-col items-center justify-center text-center p-10 border-2 border-dashed border-slate-800 rounded-[3rem] opacity-50">
                      <Search className="w-16 h-16 text-slate-600 mb-4" />
