export default BillNegotiator;

import React, { useState, useMemo, useEffect } from 'react';
import { generateNegotiationScript } from '../services/geminiService';
import { Handshake, Copy, Check, Loader2, DollarSign, Sparkles, TrendingDown, Plus, X, Search, Clock, ExternalLink, XCircle, Info, FileText } from 'lucide-react';
import { UserPlan, Transaction, TransactionType, Category } from '../types';

interface BillNegotiatorProps {
  userPlan: UserPlan;
  onIncrementUsage: () => void;
  negotiationUsage: number;
  transactions?: Transaction[];
}

interface Subscription {
    id: string;
    merchant: string;
    amount: number;
    lastDate: string;
    nextDate: string;
    status: 'Safe' | 'Review' | 'Crisis Pending';
    isDemo?: boolean;
}

const DEMO_SUBS: Subscription[] = [
    {
        id: 'demo_netflix',
        merchant: 'Netflix (Demo)',
        amount: 15.99,
        lastDate: new Date().toISOString(),
        nextDate: new Date(Date.now() + 5 * 24 * 60 * 60 * 1000).toISOString(),
        status: 'Review',
        isDemo: true
    },
    {
        id: 'demo_adobe',
        merchant: 'Adobe Creative (Demo)',
        amount: 54.99,
        lastDate: new Date().toISOString(),
        nextDate: new Date(Date.now() + 2 * 24 * 60 * 60 * 1000).toISOString(),
        status: 'Crisis Pending',
        isDemo: true
    }
];

const BillNegotiator: React.FC<BillNegotiatorProps> = ({ userPlan, onIncrementUsage, negotiationUsage, transactions = [] }) => {
  const [selectedSub, setSelectedSub] = useState<Subscription | null>(null);
  const [manualModalOpen, setManualModalOpen] = useState(false);
  const [manualSubs, setManualSubs] = useState<Subscription[]>([]);

  // Negotiation State
  const [script, setScript] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [copied, setCopied] = useState(false);
  const [activeTab, setActiveTab] = useState<'negotiate' | 'cancel'>('negotiate');
  const [aiInsight, setAiInsight] = useState<string | null>(null);

  const isElite = userPlan === 'ultra';
  const isPro = userPlan === 'pro';

  // Usage Limits
  const limit = isElite ? 100 : isPro ? 20 : 3;
  const isLocked = negotiationUsage >= limit;

  // Auto-Detect Logic (Memoized for performance and stability)
  const subscriptions = useMemo(() => {
      const subMap = new Map<string, Transaction[]>();

      if (Array.isArray(transactions)) {
          transactions.forEach(t => {
              if (t.type === TransactionType.EXPENSE) {
                  // Heuristic: Category 'Subscription', 'Utilities', or just repeating names
                  if (t.category === Category.SUBSCRIPTION || t.category === Category.UTILITIES || t.category === Category.ENTERTAINMENT) {
                      const key = t.merchant.toLowerCase().trim();
                      const existing = subMap.get(key) || [];
                      subMap.set(key, [...existing, t]);
                  }
              }
          });
      }

      const detected: Subscription[] = [];
      subMap.forEach((txs) => {
          // Sort by date desc
          txs.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
          const latest = txs[0];

          if (!latest) return;

          // Determine status
          let status: Subscription['status'] = 'Safe';
          const lastDateObj = new Date(latest.date);
          const nextDate = new Date(lastDateObj);
          nextDate.setDate(nextDate.getDate() + 30);

          const daysUntil = Math.ceil((nextDate.getTime() - Date.now()) / (1000 * 60 * 60 * 24));

          if (latest.amount > 100 || daysUntil < 3) status = 'Crisis Pending';
          else if (latest.amount > 20) status = 'Review';

          detected.push({
              id: latest.id,
              merchant: latest.merchant,
              amount: latest.amount,
              lastDate: latest.date,
              nextDate: nextDate.toISOString(),
              status
          });
      });

      // Merge detected with manual
      const all = [...detected, ...manualSubs].sort((a, b) => b.amount - a.amount);

      // Return Demo data if absolutely nothing exists
      return all.length > 0 ? all : DEMO_SUBS;
  }, [transactions, manualSubs]);

  const handleGenerate = async (intent: 'discount' | 'cancel' | 'downgrade') => {
    if (!selectedSub || isLocked) return;

    setLoading(true);
    onIncrementUsage();

    // Simulate AI thinking for UI effect
    setTimeout(async () => {
        const generatedScript = await generateNegotiationScript(selectedSub.merchant, selectedSub.amount, intent);
        setScript(generatedScript);
        setLoading(false);
    }, 1000);
  };

  const handleCopy = () => {
    if (script) {
      navigator.clipboard.writeText(script);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    }
  };

  const handleManualAdd = (merchant: string, amount: number) => {
      const newSub: Subscription = {
          id: `man_${Date.now()}`,
          merchant,
          amount,
          lastDate: new Date().toISOString().split('T')[0],
          nextDate: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString(),
          status: amount > 50 ? 'Review' : 'Safe'
      };
      setManualSubs(prev => [newSub, ...prev]);
      setManualModalOpen(false);
  };

  // Mock AI Insight generation when a sub is selected
  useEffect(() => {
      if (selectedSub) {
          setScript(null);
          setAiInsight(null);
          // Simulate fetching insights based on tier
          if (isPro || isElite) {
              const timer = setTimeout(() => {
                  const insights = [
                      "Price increased by approx. 12% in the last 6 months compared to market average.",
                      "Cheaper tier available if you sacrifice 4K streaming.",
                      "Usage pattern indicates 30% redundancy. Safe to downgrade.",
                      "Competitors offering 3 months free for switchers."
                  ];
                  setAiInsight(insights[Math.floor(Math.random() * insights.length)]);
              }, 600);
              return () => clearTimeout(timer);
          }
      }
  }, [selectedSub, isPro, isElite]);

  const hasDemo = subscriptions.some(s => s.isDemo);

  return (
    <div className="animate-slide-up pb-20 max-w-7xl mx-auto space-y-8">

      <div className="flex flex-col md:flex-row justify-between items-start gap-6">
        <div>
            <h2 className="text-3xl font-black text-white tracking-tighter flex items-center gap-3">
                <Handshake className="w-8 h-8 text-indigo-400" />
                Subscription Command
            </h2>
            <p className="text-slate-400 font-medium mt-2">
                Identify recurring drain vectors and deploy AI negotiation logic.
            </p>
        </div>
        <div className="px-4 py-2 bg-slate-900 border border-white/10 rounded-xl flex flex-col items-end">
            <span className="text-[9px] font-black text-slate-500 uppercase tracking-widest">Negotiation Tokens</span>
            <div className="flex items-center gap-2">
               <span className={`text-xl font-black ${isLocked ? 'text-rose-500' : 'text-white'}`}>{negotiationUsage}</span>
               <span className="text-xs font-bold text-slate-600">/ {limit}</span>
            </div>
        </div>
      </div>

      {hasDemo && (
          <div className="bg-indigo-500/10 border border-indigo-500/20 p-4 rounded-2xl flex items-center gap-3 animate-fade-in">
              <Info className="w-5 h-5 text-indigo-400 shrink-0" />
              <p className="text-sm text-indigo-200">
                  <span className="font-bold">System in Demo Mode.</span> Add transactions categorized as 'Subscription' or manually add a bill to see real data.
              </p>
          </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 items-start">

          {/* LEFT COLUMN: AUTO-DETECTED LIST */}
          <div className="glass-card p-6 rounded-[2.5rem] border border-white/10 flex flex-col h-[600px] relative overflow-hidden bg-slate-900/40">
              <div className="flex justify-between items-center mb-6 px-2">
                  <h3 className="text-sm font-black text-slate-400 uppercase tracking-widest">Detected Vectors</h3>
                  <span className="bg-slate-800 text-slate-400 text-xs font-bold px-2 py-1 rounded-lg">{subscriptions.length}</span>
              </div>

              <div className="flex-1 overflow-y-auto custom-scrollbar space-y-3 px-2 pb-20">
                  {subscriptions.map(sub => (
                      <div 
                        key={sub.id}
                        onClick={() => setSelectedSub(sub)}
                        className={`p-4 rounded-2xl border transition-all cursor-pointer group ${selectedSub?.id === sub.id ? 'bg-indigo-600/10 border-indigo-500 shadow-[0_0_20px_rgba(99,102,241,0.2)]' : 'bg-slate-900/40 border-white/5 hover:bg-slate-800'}`}
                      >
                          <div className="flex justify-between items-start mb-2">
                              <h4 className={`font-bold text-sm ${selectedSub?.id === sub.id ? 'text-white' : 'text-slate-300'}`}>
                                  {sub.merchant}
                                  {sub.isDemo && <span className="ml-2 text-[8px] uppercase tracking-widest bg-slate-800 px-1.5 py-0.5 rounded text-slate-500">Demo</span>}
                              </h4>
                              <div className={`px-2 py-0.5 rounded text-[9px] font-black uppercase tracking-wider ${
                                  sub.status === 'Crisis Pending' ? 'bg-rose-500 text-white animate-pulse' :
                                  sub.status === 'Review' ? 'bg-amber-500/20 text-amber-400' :
                                  'bg-emerald-500/20 text-emerald-400'
                              }`}>
                                  {sub.status}
                              </div>
                          </div>
                          <div className="flex justify-between items-end">
                              <div>
                                  <div className="text-[10px] text-slate-500 font-bold uppercase">Last Charge</div>
                                  <div className="text-white font-mono text-sm">${sub.amount.toFixed(2)}</div>
                              </div>
                              <div className="text-right">
                                  <div className="text-[10px] text-slate-500 font-bold uppercase">Est. Next</div>
                                  <div className="text-slate-300 text-xs flex items-center gap-1 justify-end">
                                      <Clock className="w-3 h-3" />
                                      {new Date(sub.nextDate).toLocaleDateString(undefined, {month:'short', day:'numeric'})}
                                  </div>
                              </div>
                          </div>
                      </div>
                  ))}
                  {subscriptions.length === 0 && (
                      <div className="text-center py-10 text-slate-500 text-xs font-medium italic">
                          No recurring vectors detected.
                      </div>
                  )}
              </div>

              <div className="absolute bottom-0 left-0 w-full p-6 bg-gradient-to-t from-[#0f172a] via-[#0f172a] to-transparent">
                  <button 
                    onClick={() => setManualModalOpen(true)}
                    className="w-full py-4 bg-slate-800 hover:bg-slate-700 text-slate-300 font-bold text-xs uppercase tracking-widest rounded-xl transition-all flex items-center justify-center gap-2 border border-white/5 shadow-lg"
                  >
                      <Plus className="w-4 h-4" /> Add Missing Subscription
                  </button>
              </div>
          </div>

          {/* RIGHT COLUMN: WORKBENCH */}
          <div className="lg:col-span-2 space-y-6">
              {selectedSub ? (
                  <div className="animate-slide-up space-y-6">
                      {/* HEADER CARD */}
                      <div className="glass-card p-8 rounded-[2.5rem] border border-white/10 relative overflow-hidden bg-slate-900/40">
                          <div className="absolute top-0 right-0 w-64 h-64 bg-indigo-500/10 rounded-full blur-[80px] -mr-16 -mt-16 pointer-events-none"></div>

                          <div className="flex justify-between items-start relative z-10 mb-8">
                              <div className="flex items-center gap-4">
                                  <div className="w-16 h-16 bg-slate-800 rounded-2xl flex items-center justify-center shadow-lg border border-white/5">
                                      <span className="text-2xl font-black text-white">{selectedSub.merchant.charAt(0)}</span>
                                  </div>
                                  <div>
                                      <h2 className="text-3xl font-black text-white tracking-tight">{selectedSub.merchant}</h2>
                                      <p className="text-slate-400 font-medium text-sm">Monthly Recurring Obligation</p>
                                  </div>
                              </div>
                              <div className="text-right">
                                  <div className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1">Annual Impact</div>
                                  <div className="text-3xl font-black text-emerald-400 tracking-tighter drop-shadow-sm">
                                      ${(selectedSub.amount * 12).toFixed(2)}
                                  </div>
                                  <div className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Potential Savings / Year</div>
                              </div>
                          </div>

                          {/* AI INSIGHT ROW */}
                          <div className="bg-slate-900/50 rounded-2xl p-4 border border-white/5 flex items-start gap-3 relative z-10">
                              <div className="p-2 bg-indigo-500/10 rounded-lg shrink-0">
                                  <Sparkles className="w-4 h-4 text-indigo-400 animate-pulse" />
                              </div>
                              <div className="flex-1">
                                  <h4 className="text-[10px] font-black text-indigo-300 uppercase tracking-widest mb-1">Neural Analysis</h4>
                                  <p className="text-sm text-slate-300 font-medium leading-relaxed">
                                      {aiInsight || "Analyzing vendor patterns and market rates..."}
                                  </p>
                              </div>
                              {(!isPro && !isElite) && (
