                              </button>
                              <button 
                                onClick={() => { setActiveTab('cancel'); setScript(null); }}
                                className={`flex-1 py-3 rounded-2xl text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'cancel' ? 'bg-rose-600 text-white shadow-lg' : 'text-slate-500 hover:text-white'}`}
                              >
                                  Cancel Service
                              </button>
                          </div>

                          <div className="p-6">
                              {activeTab === 'negotiate' && (
                                  <div className="space-y-6 animate-fade-in">
