                                              <DollarSign className="w-5 h-5 text-emerald-400 mb-2 group-hover:scale-110 transition-transform" />
                                              <div className="text-xs font-bold text-white">Discount</div>
                                              <div className="text-[10px] text-slate-500">Ask promo rate</div>
                                          </button>
                                          <button onClick={() => handleGenerate('cancel')} disabled={loading} className="p-4 bg-slate-800/50 border border-white/5 rounded-xl hover:bg-slate-800 hover:border-white/20 transition-all text-left group">
                                              <XCircle className="w-5 h-5 text-rose-400 mb-2 group-hover:scale-110 transition-transform" />
                                              <div className="text-xs font-bold text-white">Leverage</div>
                                              <div className="text-[10px] text-slate-500">Threaten exit</div>
                                          </button>
                                      </div>

                                      {/* SCRIPT OUTPUT */}
                                      <div className={`bg-slate-950 rounded-2xl border border-white/10 p-6 relative min-h-[150px] transition-all ${script ? 'opacity-100' : 'opacity-50'}`}>
                                          <div className="flex justify-between items-center mb-4">
                                              <div className="flex items-center gap-2">
                                                  <FileText className="w-4 h-4 text-indigo-400" />
                                                  <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Generated Script</span>
                                              </div>
                                              {script && (
                                                  <button onClick={handleCopy} className="text-xs font-bold text-indigo-400 hover:text-white transition-colors flex items-center gap-1">
