export default BillNegotiator;

import React, { useState, useMemo } from 'react';
import { generateNegotiationScript } from '../services/geminiService';
import { Handshake, Loader2, DollarSign, Copy, Check, FileText, Zap, ShieldAlert, ArrowRight, Plus, X, Search, TrendingDown, ExternalLink } from 'lucide-react';
import { UserPlan, Transaction, TransactionType, Category } from '../types';

interface BillNegotiatorProps {
  userPlan: UserPlan;
  onIncrementUsage: () => void;
  negotiationUsage: number;
  transactions?: Transaction[];
}

interface SubscriptionItem {
    id: string;
    name: string;
    amount: number;
    dueDate: string;
    status: 'active' | 'risk';
    isDemo?: boolean;
}

// ---------------------------------------------------------------------------
// FALLBACK DATA (Guarantees UI never renders blank)
// ---------------------------------------------------------------------------
const DEMO_ITEMS: SubscriptionItem[] = [
    { id: 'demo_1', name: 'Netflix (Demo)', amount: 19.99, dueDate: '2024-12-15', status: 'active', isDemo: true },
    { id: 'demo_2', name: 'Adobe Creative (Demo)', amount: 59.99, dueDate: '2024-12-20', status: 'risk', isDemo: true },
    { id: 'demo_3', name: 'Spotify (Demo)', amount: 11.99, dueDate: '2024-12-25', status: 'active', isDemo: true },
];

const BillNegotiator: React.FC<BillNegotiatorProps> = ({ userPlan, onIncrementUsage, negotiationUsage, transactions = [] }) => {
  // -------------------------------------------------------------------------
  // STATE
  // -------------------------------------------------------------------------
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [generatedScript, setGeneratedScript] = useState<string | null>(null);
  const [isGenerating, setIsGenerating] = useState(false);
  const [isCopied, setIsCopied] = useState(false);
  const [manualModalOpen, setManualModalOpen] = useState(false);
  const [manualItems, setManualItems] = useState<SubscriptionItem[]>([]);
  const [negotiationType, setNegotiationType] = useState<'discount' | 'cancel' | 'downgrade'>('discount');

  const isElite = userPlan === 'ultra';
  const isPro = userPlan === 'pro';
  const usageLimit = isElite ? 100 : isPro ? 20 : 3;
  const isLimitReached = negotiationUsage >= usageLimit;

  // -------------------------------------------------------------------------
  // DATA PROCESSING
  // -------------------------------------------------------------------------
  const subscriptions = useMemo(() => {
      try {
          const detected: SubscriptionItem[] = [];
          const safeTx = Array.isArray(transactions) ? transactions : [];

          // 1. Group transactions by merchant to find potential subscriptions
          const merchantMap = new Map<string, Transaction>();

          safeTx.forEach(t => {
              if (t.type === TransactionType.EXPENSE) {
                  const isSub = t.category === Category.SUBSCRIPTION || t.category === Category.UTILITIES || t.category === Category.ENTERTAINMENT;
                  if (isSub) {
                      // Keep the latest transaction for this merchant
                      const key = t.merchant.toLowerCase().trim();
                      const existing = merchantMap.get(key);
                      if (!existing || new Date(t.date) > new Date(existing.date)) {
                          merchantMap.set(key, t);
                      }
                  }
              }
          });

          // 2. Convert to SubscriptionItem
          merchantMap.forEach(t => {
              detected.push({
                  id: t.id,
                  name: t.merchant,
                  amount: t.amount,
                  dueDate: t.date, // Simplifying: just use last date as reference
                  status: t.amount > 50 ? 'risk' : 'active'
              });
          });

          // 3. Combine with manual items
          const allItems = [...detected, ...manualItems];

          // 4. Return Demo items if list is empty
          return allItems.length > 0 ? allItems : DEMO_ITEMS;

      } catch (err) {
          console.error("Error processing subscriptions:", err);
          return DEMO_ITEMS; // Fail safe
      }
  }, [transactions, manualItems]);

  const activeItem = subscriptions.find(s => s.id === selectedId) || null;

  // -------------------------------------------------------------------------
  // ACTIONS
  // -------------------------------------------------------------------------
  const handleGenerate = async () => {
      if (!activeItem || isLimitReached) return;

      setIsGenerating(true);
      setGeneratedScript(null);
      onIncrementUsage();

      // Artificial delay for UX feel
      setTimeout(async () => {
          const script = await generateNegotiationScript(activeItem.name, activeItem.amount, negotiationType);
          setGeneratedScript(script);
          setIsGenerating(false);
      }, 800);
  };

  const handleCopy = () => {
      if (generatedScript) {
          navigator.clipboard.writeText(generatedScript);
          setIsCopied(true);
          setTimeout(() => setIsCopied(false), 2000);
      }
  };

  const handleAddManual = (name: string, amount: number) => {
      const newItem: SubscriptionItem = {
          id: `manual_${Date.now()}`,
          name,
          amount,
          dueDate: new Date().toISOString().split('T')[0],
          status: 'active'
      };
      setManualItems(prev => [newItem, ...prev]);
      setManualModalOpen(false);
  };

  // -------------------------------------------------------------------------
  // RENDER
  // -------------------------------------------------------------------------
  return (
    <div className="max-w-6xl mx-auto space-y-8 animate-fade-in pb-20">

      {/* HEADER */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-end gap-4">
          <div>
              <h2 className="text-3xl font-black text-white tracking-tighter flex items-center gap-3">
                  <Handshake className="w-8 h-8 text-indigo-400" />
                  Bill Negotiator
              </h2>
              <p className="text-slate-400 font-medium mt-2 max-w-lg">
                  AI-powered scripts to lower your recurring expenses. Select a bill, choose a strategy, and copy the script.
              </p>
          </div>
          <div className="bg-slate-900 border border-white/10 px-4 py-2 rounded-xl text-right">
              <div className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Available Credits</div>
              <div className={`text-xl font-black ${isLimitReached ? 'text-rose-500' : 'text-emerald-400'}`}>
                  {usageLimit - negotiationUsage} <span className="text-slate-600 text-sm">/ {usageLimit}</span>
              </div>
          </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">

          {/* LEFT SIDEBAR: LIST */}
          <div className="lg:col-span-4 space-y-4">
              <div className="flex justify-between items-center px-1">
                  <h3 className="text-xs font-black text-slate-500 uppercase tracking-widest">Detected Bills</h3>
                  <button onClick={() => setManualModalOpen(true)} className="text-indigo-400 hover:text-white transition-colors">
                      <Plus className="w-5 h-5" />
                  </button>
              </div>

              <div className="space-y-3 h-[500px] overflow-y-auto custom-scrollbar pr-2">
                  {subscriptions.map(item => (
                      <div 
                        key={item.id}
                        onClick={() => { setSelectedId(item.id); setGeneratedScript(null); }}
                        className={`p-4 rounded-2xl border cursor-pointer transition-all group relative overflow-hidden ${selectedId === item.id ? 'bg-indigo-600/20 border-indigo-500 shadow-[0_0_20px_rgba(99,102,241,0.2)]' : 'bg-slate-900/40 border-white/5 hover:border-white/20'}`}
                      >
                          {item.isDemo && (
                              <div className="absolute top-0 right-0 bg-slate-800 px-2 py-0.5 rounded-bl-lg text-[8px] font-black uppercase text-slate-500 tracking-widest">Demo</div>
                          )}
                          <div className="flex justify-between items-center mb-1">
                              <h4 className={`font-bold text-sm ${selectedId === item.id ? 'text-white' : 'text-slate-300'}`}>{item.name}</h4>
                              <span className="font-mono text-white font-bold">${item.amount.toFixed(2)}</span>
                          </div>
                          <div className="flex justify-between items-center">
                              <span className="text-[10px] text-slate-500 font-medium">Last: {item.dueDate}</span>
                              {item.status === 'risk' && <span className="flex items-center gap-1 text-[9px] font-bold text-rose-400 uppercase tracking-wider"><ShieldAlert className="w-3 h-3" /> High Cost</span>}
                          </div>
                      </div>
                  ))}

                  {subscriptions.some(s => s.isDemo) && (
                      <div className="mt-4 p-4 rounded-xl bg-indigo-500/10 border border-indigo-500/20 text-center">
                          <p className="text-xs text-indigo-300 font-medium">
                              Demo mode active. Add real transactions categorized as "Subscription" to see them here.
                          </p>
                      </div>
                  )}
              </div>
          </div>

          {/* RIGHT PANEL: WORKBENCH */}
          <div className="lg:col-span-8">
              {activeItem ? (
                  <div className="glass-card rounded-[2.5rem] border border-white/10 overflow-hidden flex flex-col h-full bg-slate-900/40 min-h-[500px]">

                      {/* Item Header */}
                      <div className="p-8 border-b border-white/5 bg-slate-950/30">
                          <div className="flex items-center justify-between">
                              <div className="flex items-center gap-4">
                                  <div className="w-16 h-16 rounded-2xl bg-indigo-600 flex items-center justify-center text-2xl font-black text-white shadow-lg">
                                      {activeItem.name.charAt(0)}
                                  </div>
                                  <div>
                                      <h2 className="text-2xl font-bold text-white">{activeItem.name}</h2>
                                      <p className="text-slate-400 text-sm font-medium">Current Monthly Cost: <span className="text-white font-bold">${activeItem.amount}</span></p>
                                  </div>
                              </div>
                              <div className="hidden md:block text-right">
                                  <div className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1">Annual Impact</div>
                                  <div className="text-2xl font-black text-white">${(activeItem.amount * 12).toFixed(2)}</div>
                              </div>
                          </div>
                      </div>

                      <div className="p-8 flex-1 flex flex-col">

                          {/* Strategy Selector */}
                          <div className="grid grid-cols-3 gap-4 mb-8">
                              <button 
                                onClick={() => { setNegotiationType('discount'); setGeneratedScript(null); }}
                                className={`p-4 rounded-2xl border transition-all flex flex-col items-center gap-2 ${negotiationType === 'discount' ? 'bg-emerald-500/20 border-emerald-500 text-emerald-400' : 'bg-slate-800/50 border-white/5 text-slate-400 hover:bg-slate-800'}`}
                              >
                                  <DollarSign className="w-5 h-5" />
                                  <span className="text-xs font-bold uppercase tracking-wider">Get Discount</span>
                              </button>
                              <button 
                                onClick={() => { setNegotiationType('downgrade'); setGeneratedScript(null); }}
                                className={`p-4 rounded-2xl border transition-all flex flex-col items-center gap-2 ${negotiationType === 'downgrade' ? 'bg-amber-500/20 border-amber-500 text-amber-400' : 'bg-slate-800/50 border-white/5 text-slate-400 hover:bg-slate-800'}`}
                              >
                                  <TrendingDown className="w-5 h-5" />
                                  <span className="text-xs font-bold uppercase tracking-wider">Downgrade</span>
                              </button>
                              <button 
                                onClick={() => { setNegotiationType('cancel'); setGeneratedScript(null); }}
                                className={`p-4 rounded-2xl border transition-all flex flex-col items-center gap-2 ${negotiationType === 'cancel' ? 'bg-rose-500/20 border-rose-500 text-rose-400' : 'bg-slate-800/50 border-white/5 text-slate-400 hover:bg-slate-800'}`}
                              >
                                  <X className="w-5 h-5" />
                                  <span className="text-xs font-bold uppercase tracking-wider">Cancel</span>
                              </button>
                          </div>

                          {/* Action Area */}
                          <div className="flex-1 bg-slate-950 rounded-2xl border border-white/10 p-6 relative">
                              {!generatedScript && !isGenerating && (
                                  <div className="absolute inset-0 flex flex-col items-center justify-center text-center p-6 opacity-60">
                                      <Zap className="w-12 h-12 text-slate-600 mb-4" />
                                      <p className="text-slate-400 text-sm font-medium mb-6">Ready to generate a professional negotiation script for {activeItem.name}.</p>
                                      <button 
                                        onClick={handleGenerate}
                                        disabled={isLimitReached}
                                        className="px-8 py-3 bg-indigo-600 hover:bg-indigo-500 text-white font-bold rounded-xl shadow-lg transition-all flex items-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
                                      >
                                          <FileText className="w-4 h-4" /> Generate Script
                                      </button>
                                  </div>
                              )}

                              {isGenerating && (
                                  <div className="absolute inset-0 flex flex-col items-center justify-center bg-slate-950 z-10">
                                      <Loader2 className="w-10 h-10 text-indigo-500 animate-spin mb-4" />
                                      <p className="text-indigo-400 text-xs font-black uppercase tracking-widest animate-pulse">Consulting Neural Network...</p>
                                  </div>
                              )}

                              {generatedScript && (
                                  <div className="h-full flex flex-col animate-fade-in">
                                      <div className="flex justify-between items-center mb-4">
                                          <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">AI Generated Response</span>
                                          <button onClick={handleCopy} className="flex items-center gap-2 text-xs font-bold text-indigo-400 hover:text-white transition-colors">
                                              {isCopied ? <Check className="w-4 h-4" /> : <Copy className="w-4 h-4" />}
                                              {isCopied ? 'Copied' : 'Copy Text'}
                                          </button>
                                      </div>
                                      <div className="flex-1 overflow-y-auto custom-scrollbar p-4 bg-slate-900/50 rounded-xl border border-white/5">
                                          <p className="text-slate-300 text-sm leading-relaxed whitespace-pre-wrap font-medium">{generatedScript}</p>
                                      </div>
                                      <div className="mt-4 flex gap-3">
                                          <a href={`https://www.google.com/search?q=${activeItem.name}+customer+service`} target="_blank" rel="noreferrer" className="flex-1 py-3 bg-slate-800 hover:bg-slate-700 text-white font-bold text-xs rounded-xl flex items-center justify-center gap-2 transition-colors">
                                              Find Contact Info <ExternalLink className="w-3 h-3" />
                                          </a>
                                          <button onClick={handleGenerate} className="flex-1 py-3 bg-indigo-600/20 hover:bg-indigo-600/30 text-indigo-400 font-bold text-xs rounded-xl transition-colors border border-indigo-500/30">
                                              Regenerate
                                          </button>
                                      </div>
                                  </div>
                              )}
                          </div>

                      </div>
                  </div>
              ) : (
                  <div className="h-full flex flex-col items-center justify-center text-center p-10 border-2 border-dashed border-slate-800 rounded-[3rem]">
                      <div className="w-20 h-20 bg-slate-900 rounded-full flex items-center justify-center mb-6">
                          <Search className="w-8 h-8 text-slate-600" />
                      </div>
                      <h3 className="text-xl font-bold text-white mb-2">No Bill Selected</h3>
                      <p className="text-slate-500 text-sm font-medium">Select a subscription from the list to start the negotiation process.</p>
                  </div>
              )}
          </div>
      </div>

      {/* MANUAL ADD MODAL */}
      {manualModalOpen && (
          <ManualAddModal onClose={() => setManualModalOpen(false)} onAdd={handleAddManual} />
      )}

    </div>
  );
};

