                 <div className="flex-1 p-10 flex flex-col">
                    <div className="mb-10">
                        <div className="flex items-center gap-3 mb-1"><Fingerprint className="w-6 h-6 text-indigo-500" /><h2 className="text-2xl font-black text-white tracking-tight uppercase">Authorize</h2></div>
