                            <div className="text-right space-y-1"><div className="text-[10px] text-slate-500 font-black uppercase tracking-widest">Magnitude</div><div className="text-2xl font-black text-white tracking-tighter">{price}</div></div>
                        </div>
                        <div className="space-y-5">
                            <div className="space-y-2">
                                <label className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] ml-1">Card Identification Cluster</label>
                                <div className="relative group">
                                    <input required value={card} onChange={e => setCard(formatCardNumber(e.target.value))} placeholder="0000 0000 0000 0000" className="w-full bg-slate-950 border border-white/10 rounded-2xl p-4 text-white focus:border-indigo-500 focus:ring-4 focus:ring-indigo-500/10 font-mono transition-all placeholder:text-slate-900 text-lg shadow-inner" />
                                    <Lock className="absolute right-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-800" />
                                </div>
                            </div>
                            <div className="grid grid-cols-2 gap-5">
                                <div className="space-y-2"><label className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] ml-1">Exp Cycle</label><input required value={expiry} onChange={e => setExpiry(e.target.value)} placeholder="MM/YY" className="w-full bg-slate-950 border border-white/10 rounded-2xl p-4 text-white focus:border-indigo-500 outline-none font-mono text-center" /></div>
                                <div className="space-y-2"><label className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] ml-1">Security Node</label><input required value={cvc} onChange={e => setCvc(e.target.value)} placeholder="CVC" className="w-full bg-slate-950 border border-white/10 rounded-2xl p-4 text-white focus:border-indigo-500 outline-none font-mono text-center" /></div>
                            </div>
                        </div>
                        {error && <div className="p-4 bg-rose-500/10 border border-rose-500/20 text-rose-400 text-xs font-black uppercase tracking-widest rounded-xl animate-fade-in flex items-center gap-3"><AlertTriangle className="w-4 h-4" /> {error}</div>}
                        <button disabled={isProcessing} className="w-full py-5 bg-white text-slate-950 font-black uppercase text-sm tracking-[0.3em] rounded-2xl shadow-2xl active:scale-95 transition-all mt-4 disabled:opacity-50 disabled:grayscale">
                            {isProcessing ? 'Synchronizing...' : 'Authorize Transaction'}
                        </button>
                        <div className="flex justify-center items-center gap-2 mt-6 opacity-60">
                            <ShieldCheck className="w-3 h-3 text-emerald-500" />
                            <span className="text-[9px] uppercase font-bold text-slate-500 tracking-widest">Payments Secured via Stripe</span>
                        </div>
                    </form>
                 </div>
             </div>
        </div>
    );
};

export default Plans;

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { Account, Budget, Goal, Transaction, UserPlan, ToastMessage, BotMode, Currency, Language, TransactionType, SpendingPeriod, SpendingStatus } from './types';
import { ACCOUNTS, INITIAL_TRANSACTIONS, INITIAL_BUDGETS, INITIAL_GOALS, NAV_ITEMS, TRANSLATIONS } from './constants';
import { evaluateSpending } from './services/ruleEngine';
import Dashboard from './components/Dashboard';
import Transactions from './components/Transactions';
import Accounts from './components/Accounts';
import Insights from './components/Insights';
import Goals from './components/Goals';
import Plans from './components/Plans';
import Settings from './components/Settings';
import ScenarioSandbox from './components/ScenarioSandbox';
import UpcomingFeatures from './components/UpcomingFeatures';
import CashflowBeta from './components/CashflowBeta';
import BillNegotiator from './components/BillNegotiator';
import LandingPage from './components/LandingPage';
import OnboardingModal from './components/OnboardingModal';
import ToastContainer from './components/Toast';
import FloatingAssistant from './components/FloatingAssistant';
import { Sparkles, LogOut, MessageCircle, Zap, Crown, AlertTriangle, ShieldX, Terminal, ArrowRight, Eye, EyeOff, Shield, Lock } from 'lucide-react';

const getMonthlyUsage = (key: string) => {
    try {
        const item = localStorage.getItem(key);
        if (!item) return 0;
        const parsed = JSON.parse(item);
        const now = new Date();
        if (parsed.month !== now.getMonth() || parsed.year !== now.getFullYear()) return 0;
        return parsed.count || 0;
    } catch (e) { return 0; }
};

const safeSetItem = (key: string, value: string) => {
    try { localStorage.setItem(key, value); } catch (e) { console.warn(`Storage quota exceeded for ${key}`); }
};

// Feature IDs for Pin System
const PINNABLE_FEATURES = ['budget-monitor', 'sandbox-link', 'goal-tracker', 'system-alerts', 'neural-quota'];

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isPrivacyMode, setIsPrivacyMode] = useState(() => localStorage.getItem('nova_privacy_mode') === 'true');
  const [isPinMode, setIsPinMode] = useState(false);

  // Onboarding & Enforcement State
  const [onboardingComplete, setOnboardingComplete] = useState(() => localStorage.getItem('nova_onboarding_complete') === 'true');
  const [spendingLimit, setSpendingLimit] = useState<number>(() => parseFloat(localStorage.getItem('nova_spending_limit') || '1000'));
  const [spendingPeriod, setSpendingPeriod] = useState<SpendingPeriod>(() => (localStorage.getItem('nova_spending_period') as SpendingPeriod) || 'monthly');

  // Pin System State
  const [pinnedIds, setPinnedIds] = useState<string[]>(() => {
    try {
        const saved = localStorage.getItem('nova_pinned_ids');
        return saved ? JSON.parse(saved) : []; 
    } catch { return []; }
  });

  const [featureUsage, setFeatureUsage] = useState<Record<string, number>>(() => {
      try {
          const saved = localStorage.getItem('nova_feature_usage');
          return saved ? JSON.parse(saved) : {};
      } catch { return {}; }
  });

  const [accounts, setAccounts] = useState<Account[]>(() => {
      const saved = localStorage.getItem('nova_accounts');
      return saved ? JSON.parse(saved) : ACCOUNTS;
  });
  const [transactions, setTransactions] = useState<Transaction[]>(() => {
      const saved = localStorage.getItem('nova_transactions');
      return saved ? JSON.parse(saved) : INITIAL_TRANSACTIONS;
  });
  const [budgets, setBudgets] = useState<Budget[]>(() => {
      const saved = localStorage.getItem('nova_budgets');
      return saved ? JSON.parse(saved) : INITIAL_BUDGETS;
  });
  const [goals, setGoals] = useState<Goal[]>(() => {
      const saved = localStorage.getItem('nova_goals');
      return saved ? JSON.parse(saved) : INITIAL_GOALS;
  });

  const [userPlan, setUserPlan] = useState<UserPlan>(() => localStorage.getItem('nova_user_plan') as UserPlan || 'free');
  const [insightUsage, setInsightUsage] = useState(() => getMonthlyUsage('nova_insight_usage'));
  const [scanUsage, setScanUsage] = useState(() => getMonthlyUsage('nova_scan_usage'));
  const [negotiationUsage, setNegotiationUsage] = useState(() => getMonthlyUsage('nova_negotiation_usage'));

  const [isLoggedIn, setIsLoggedIn] = useState(() => localStorage.getItem('nova_auth_token') !== null);
  const [isLogoutModalOpen, setIsLogoutModalOpen] = useState(false);
  const [toasts, setToasts] = useState<ToastMessage[]>([]);
  const [botMode, setBotMode] = useState<BotMode>(() => (localStorage.getItem('nova_bot_mode') as BotMode) || 'ruthless');
  const [pendingChatQuery, setPendingChatQuery] = useState<string | null>(null);

  const [userName, setUserName] = useState(() => localStorage.getItem('nova_user_name') || 'Pilot');
  const [userEmail, setUserEmail] = useState(() => localStorage.getItem('nova_user_email') || 'pilot@nova.io');
  const [userAvatar, setUserAvatar] = useState(() => localStorage.getItem('nova_user_avatar') || '');
  const [userAvatarZoom, setUserAvatarZoom] = useState(1);
  const [userAvatarPos, setUserAvatarPos] = useState({ x: 0, y: 0 });
  const [userBorder, setUserBorder] = useState('default');
  const [userBackground, setUserBackground] = useState(() => localStorage.getItem('nova_user_bg') || '');

  const [currency, setCurrency] = useState<Currency>(() => (localStorage.getItem('nova_currency') as Currency) || 'USD');
  const [language, setLanguage] = useState<Language>(() => (localStorage.getItem('nova_language') as Language) || 'en');

  // Persistence Effects
  useEffect(() => safeSetItem('nova_accounts', JSON.stringify(accounts)), [accounts]);
  useEffect(() => safeSetItem('nova_transactions', JSON.stringify(transactions)), [transactions]);
  useEffect(() => safeSetItem('nova_budgets', JSON.stringify(budgets)), [budgets]);
  useEffect(() => safeSetItem('nova_goals', JSON.stringify(goals)), [goals]);
  useEffect(() => safeSetItem('nova_user_plan', userPlan), [userPlan]);
  useEffect(() => safeSetItem('nova_currency', currency), [currency]);
  useEffect(() => safeSetItem('nova_language', language), [language]);
  useEffect(() => safeSetItem('nova_bot_mode', botMode), [botMode]);
  useEffect(() => safeSetItem('nova_privacy_mode', isPrivacyMode.toString()), [isPrivacyMode]);
  useEffect(() => safeSetItem('nova_pinned_ids', JSON.stringify(pinnedIds)), [pinnedIds]);
  useEffect(() => safeSetItem('nova_feature_usage', JSON.stringify(featureUsage)), [featureUsage]);
  useEffect(() => safeSetItem('nova_user_bg', userBackground), [userBackground]);
  useEffect(() => safeSetItem('nova_spending_limit', spendingLimit.toString()), [spendingLimit]);
  useEffect(() => safeSetItem('nova_spending_period', spendingPeriod), [spendingPeriod]);
  useEffect(() => safeSetItem('nova_onboarding_complete', onboardingComplete.toString()), [onboardingComplete]);

  // Spending Enforcement Calculation (Zero AI, Pure Math)
  const spendingStatus: { currentSpend: number; status: SpendingStatus } = useMemo(() => {
      const now = new Date();
      let startDate = new Date();

      if (spendingPeriod === 'weekly') {
          // Set to previous Sunday (or today if Sunday)
          const day = now.getDay();
          const diff = now.getDate() - day;
          startDate = new Date(now.setDate(diff));
          startDate.setHours(0, 0, 0, 0);
      } else {
          // Set to 1st of current month
          startDate = new Date(now.getFullYear(), now.getMonth(), 1);
      }

      const currentSpend = transactions
          .filter(t => t.type === TransactionType.EXPENSE && new Date(t.date) >= startDate)
          .reduce((acc, t) => acc + t.amount, 0);

      const status = evaluateSpending(currentSpend, spendingLimit);
      return { currentSpend, status };
  }, [transactions, spendingPeriod, spendingLimit]);

  // Usage counters
  useEffect(() => {
      const now = new Date();
      const meta = { month: now.getMonth(), year: now.getFullYear(), count: insightUsage };
      safeSetItem('nova_insight_usage', JSON.stringify(meta));
  }, [insightUsage]);

  useEffect(() => {
      const now = new Date();
      const meta = { month: now.getMonth(), year: now.getFullYear(), count: scanUsage };
      safeSetItem('nova_scan_usage', JSON.stringify(meta));
  }, [scanUsage]);

  useEffect(() => {
      const now = new Date();
      const meta = { month: now.getMonth(), year: now.getFullYear(), count: negotiationUsage };
      safeSetItem('nova_negotiation_usage', JSON.stringify(meta));
  }, [negotiationUsage]);

  const addToast = useCallback((message: string, type: 'success' | 'error' | 'info' = 'info') => {
    setToasts(prev => [...prev, { id: Date.now().toString(), message, type }]);
  }, []);

  const trackFeatureUsage = useCallback((featureId: string) => {
      setFeatureUsage(prev => ({
          ...prev,
          [featureId]: (prev[featureId] || 0) + 1
      }));
  }, []);

  // Auto-Pin Heuristic
  useEffect(() => {
      if (!isLoggedIn) return;
      const hasAutoPinned = localStorage.getItem('nova_has_auto_pinned');
      if (hasAutoPinned) return;

      const totalActions = (Object.values(featureUsage) as number[]).reduce((a, b) => a + b, 0);
      if (totalActions > 10) {
          const sorted = Object.entries(featureUsage)
              .filter(([key]) => PINNABLE_FEATURES.includes(key))
              .sort((a, b) => (b[1] as number) - (a[1] as number))
              .map(([key]) => key)
              .slice(0, 2); 

          if (sorted.length > 0) {
              setPinnedIds(sorted);
              addToast(`System optimization complete. Top ${sorted.length} modules pinned.`, 'info');
              localStorage.setItem('nova_has_auto_pinned', 'true');
          }
      }
  }, [featureUsage, isLoggedIn, addToast]);

  const handleTogglePin = (id: string) => {
    setPinnedIds(prev => {
        if (prev.includes(id)) {
            return prev.filter(p => p !== id);
        }
        const limit = userPlan === 'ultra' ? 5 : userPlan === 'pro' ? 3 : 1;
        if (prev.length >= limit) {
            addToast(`Slot Limit Reached (${limit}). Unpin a module to replace.`, 'error');
            return prev;
        }
        return [...prev, id];
    });
  };

  const handleToggleStealth = useCallback(() => {
    if (userPlan !== 'ultra') {
        addToast('Stealth Protocol is an Elite-exclusive feature.', 'info');
        setActiveTab('plans');
        return;
    }
    setIsPrivacyMode(prev => !prev);
    addToast(`Stealth Protocol ${!isPrivacyMode ? 'Engaged' : 'Disengaged'}`, 'info');
  }, [userPlan, isPrivacyMode, addToast]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
        const isModI = (e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'i';
        if (isModI) {
            e.preventDefault();
            setIsPinMode(prev => {
                const newVal = !prev;
                addToast(newVal ? 'Pin Configuration Mode: ACTIVE' : 'Pin Configuration Mode: END', 'info');
                if (newVal) setActiveTab('dashboard');
                return newVal;
            });
        }
        if (e.key === 'Escape' && isPinMode) {
            setIsPinMode(false);
            addToast('Pin Configuration Mode: END', 'info');
        }
        if (e.shiftKey && e.key.toLowerCase() === 'p') {
            handleToggleStealth();
        }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isPinMode, handleToggleStealth, addToast]);

  const removeToast = (id: string) => {
    setToasts(prev => prev.filter(t => t.id !== id));
  };

  const formatCurrency = (amount: number) => {
    const val = new Intl.NumberFormat(language === 'vi' ? 'vi-VN' : 'en-US', { 
        style: 'currency', currency: currency,
    }).format(amount);

    if (isPrivacyMode && userPlan === 'ultra') {
        return <span className="blur-md opacity-50 bg-white/5 px-1 rounded-md">{val.replace('-', '')}</span>;
    }
    return val;
  };

  const reconcileBalance = (tx: Transaction, direction: 'add' | 'delete') => {
      if (tx.accountId === 'manual') return;
      setAccounts(prev => prev.map(acc => {
          if (acc.id === tx.accountId) {
              const isIncome = tx.type === TransactionType.INCOME;
              let change = tx.amount;
              if (direction === 'add') change = isIncome ? change : -change;
              else change = isIncome ? -change : change;
              return { ...acc, balance: acc.balance + change };
          }
          return acc;
      }));
  };

  const handleAddTransaction = (t: Transaction) => {
      setTransactions(prev => [t, ...prev]);
      reconcileBalance(t, 'add');
      addToast('Transaction recorded.', 'success');
  };

  const handleDeleteTransaction = (id: string) => {
      const tx = transactions.find(t => t.id === id);
      if (tx) {
          reconcileBalance(tx, 'delete');
          setTransactions(prev => prev.filter(t => t.id !== id));
          addToast('Transaction purged.', 'info');
      }
  };

  const handleLogin = (name: string) => {
    setIsLoggedIn(true);
    setUserName(name);
    localStorage.setItem('nova_user_name', name);
  };

  const confirmLogout = () => {
    localStorage.removeItem('nova_auth_token');
    setIsLoggedIn(false);
    setIsLogoutModalOpen(false);
  };

  const handleAskCoach = (message?: string) => {
    if (message) {
      setPendingChatQuery(message);
    }
    setActiveTab('insights');
  };

  const handleOnboardingComplete = (lang: Language, per: SpendingPeriod, lim: number) => {
      setLanguage(lang);
      setSpendingPeriod(per);
      setSpendingLimit(lim);
      setOnboardingComplete(true);
      addToast('System Initialized. Spending parameters locked.', 'success');
  };

  const branding = useMemo(() => {
    switch (userPlan) {
      case 'ultra':
        return {
          bg: 'bg-gradient-to-tr from-indigo-600 to-purple-600',
          shadow: 'shadow-indigo-500/40',
          icon: <Sparkles className="w-6 h-6 text-white" />,
          label: 'Elite Terminal'
        };
      case 'pro':
        return {
          bg: 'bg-gradient-to-tr from-amber-400 to-orange-500',
          shadow: 'shadow-amber-500/40',
          icon: <Zap className="w-6 h-6 text-white" />,
          label: 'Pro Uplink'
        };
      default:
        return {
          bg: 'bg-slate-800',
          shadow: 'shadow-black/20',
          icon: <Shield className="w-6 h-6 text-slate-400" />,
          label: 'Free Tier'
        };
    }
  }, [userPlan]);

  if (!isLoggedIn) return <LandingPage onLoginSuccess={handleLogin} />;

  if (!onboardingComplete) return <OnboardingModal onComplete={handleOnboardingComplete} />;

  return (
    <div className={`flex h-screen bg-[#020617] text-slate-100 font-sans selection:bg-indigo-500/30 overflow-hidden relative ${isPinMode ? 'cursor-default' : ''}`}>
      <FloatingAssistant transactions={transactions} budgets={budgets} userPlan={userPlan} botMode={botMode} isVisible={activeTab !== 'insights'} onOpenChat={handleAskCoach} insightUsage={insightUsage} />

      <aside className="hidden md:flex flex-col w-64 p-4 pb-8 z-20 bg-slate-950/40 backdrop-blur-md border-r border-white/5 relative">
        <div className="flex items-center gap-3 px-4 py-3 mb-8 shrink-0">
            <div className={`w-10 h-10 rounded-xl flex items-center justify-center shadow-lg ring-1 ring-white/10 ${branding.bg} ${branding.shadow}`}>{branding.icon}</div>
            <div><h1 className="text-xl font-bold tracking-tight text-white">Nova AI</h1><p className={`text-[10px] font-bold uppercase tracking-wider ${userPlan === 'ultra' ? 'text-purple-400' : userPlan === 'pro' ? 'text-amber-400' : 'text-slate-500'}`}>{branding.label}</p></div>
        </div>
        <nav className="flex-1 space-y-1 overflow-y-auto custom-scrollbar pr-1">
            {NAV_ITEMS.map((item) => {
                const isActive = activeTab === item.id;
                const label = TRANSLATIONS[language]?.[item.id as keyof typeof TRANSLATIONS['en']] || item.label;
                return (
                    <button key={item.id} onClick={() => setActiveTab(item.id)} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold transition-all duration-300 group ${isActive ? 'bg-indigo-600/10 text-indigo-400 shadow-[0_0_20px_rgba(99,102,241,0.15)] ring-1 ring-indigo-500/20' : 'text-slate-400 hover:text-white hover:bg-white/5'}`}>
                        <item.icon className={`w-5 h-5 transition-colors ${isActive ? 'text-indigo-400' : 'text-slate-500 group-hover:text-white'}`} />{label}
                    </button>
                );
            })}
        </nav>
        <div className="mt-auto pt-6 border-t border-white/5 shrink-0">
             <button onClick={handleToggleStealth} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all mb-2 ${isPrivacyMode && userPlan === 'ultra' ? 'bg-indigo-500/20 text-indigo-400 border border-indigo-500/30' : 'text-slate-500 hover:text-slate-300 hover:bg-white/5'}`}>
                {isPrivacyMode ? <EyeOff className="w-5 h-5" /> : <Shield className="w-5 h-5" />} {isPrivacyMode ? 'Stealth Engaged' : 'Stealth Protocol'}
             </button>
             <button onClick={() => setActiveTab('settings')} className="w-full text-left px-4 py-4 rounded-2xl bg-slate-900/50 border border-white/5 flex items-center gap-3 mb-4 hover:bg-slate-800 transition-colors group">
                 <div className="w-10 h-10 rounded-full bg-indigo-500 flex items-center justify-center text-white overflow-hidden relative border border-white/10 shadow-inner">{userAvatar ? <img src={userAvatar} className="w-full h-full object-cover" alt="User" /> : <span className="font-bold text-lg">{userName.charAt(0)}</span>}</div>
                 <div className="overflow-hidden"><h4 className="font-bold text-white text-sm truncate group-hover:text-indigo-400 transition-colors">{userName}</h4><p className="text-[10px] text-slate-500 truncate font-bold uppercase tracking-widest">{userPlan} tier</p></div>
             </button>
             <button onClick={() => setIsLogoutModalOpen(true)} className="w-full flex items-center gap-2 px-4 py-2 mb-4 text-xs font-bold text-slate-500 hover:text-rose-400 transition-colors uppercase tracking-widest"><LogOut className="w-4 h-4" /> Sign Out</button>
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 z-10 relative overflow-hidden">
        {isPinMode && (
          <div className="absolute inset-0 z-[100] bg-black/40 backdrop-blur-[2px] pointer-events-none flex flex-col items-center justify-start pt-20">
              <div className="bg-indigo-600/90 text-white font-black text-xs uppercase tracking-[0.3em] px-8 py-4 rounded-2xl shadow-[0_0_50px_rgba(99,102,241,0.5)] border border-indigo-400/50 animate-pulse pointer-events-auto">
                  Pin Mode Active :: Select Priority Nodes :: Esc to Exit
              </div>
          </div>
        )}

        <div className="flex-1 overflow-y-auto p-4 md:p-8 pb-24 md:pb-8 custom-scrollbar">
            {activeTab === 'dashboard' && <Dashboard accounts={accounts} transactions={transactions} goals={goals} budgets={budgets} onNavigate={setActiveTab} onAddAccount={() => setActiveTab('accounts')} onAddTransaction={() => setActiveTab('transactions')} onAddGoal={() => setActiveTab('goals')} formatCurrency={formatCurrency} userPlan={userPlan} onAskCoach={handleAskCoach} negotiationUsage={negotiationUsage} onIncrementNegotiation={() => setNegotiationUsage(prev => prev + 1)} isPinMode={isPinMode} pinnedIds={pinnedIds} onTogglePin={handleTogglePin} trackEvent={trackFeatureUsage} insightUsage={insightUsage} spendingStatus={spendingStatus.status} currentPeriodSpend={spendingStatus.currentSpend} spendingLimit={spendingLimit} spendingPeriod={spendingPeriod} />}
            {activeTab === 'transactions' && <Transactions transactions={transactions} accounts={accounts} onDelete={handleDeleteTransaction} onAdd={handleAddTransaction} formatCurrency={formatCurrency} onNavigateToAccounts={() => setActiveTab('accounts')} userPlan={userPlan} scanUsage={scanUsage} onIncrementScan={() => setScanUsage(prev => prev + 1)} currency={currency} />}
            {activeTab === 'accounts' && <Accounts accounts={accounts} budgets={budgets} transactions={transactions} userPlan={userPlan} onAdd={(acc) => { setAccounts(prev => [...prev, acc]); addToast('Account linked.', 'success'); }} onUpdate={(acc) => { setAccounts(prev => prev.map(a => a.id === acc.id ? acc : a)); addToast('Account updated.', 'success'); }} onDelete={(id) => { setAccounts(prev => prev.filter(a => a.id !== id)); setTransactions(prev => prev.map(t => t.accountId === id ? { ...t, accountId: 'manual' } : t)); addToast('Account removed.', 'info'); }} formatCurrency={formatCurrency} userName={userName} userAvatar={userAvatar} userAvatarZoom={userAvatarZoom} userAvatarPos={userAvatarPos} userBorder={userBorder} onNavigate={setActiveTab} />}
            {activeTab === 'cashflow' && <CashflowBeta transactions={transactions} accounts={accounts} goals={goals} formatCurrency={formatCurrency} userPlan={userPlan} />}
            {activeTab === 'negotiator' && <BillNegotiator userPlan={userPlan} onIncrementUsage={() => setNegotiationUsage(prev => prev + 1)} negotiationUsage={negotiationUsage} transactions={transactions} />}
            {activeTab === 'insights' && <Insights transactions={transactions} userPlan={userPlan} onUpgradeClick={() => setActiveTab('plans')} formatCurrency={formatCurrency} insightUsage={insightUsage} onIncrementUsage={() => setInsightUsage(prev => prev + 1)} onApplyBudgets={(newBudgets) => { const existingCats = new Set(budgets.map(b => b.category)); const toAdd = newBudgets.filter(b => !existingCats.has(b.category)); setBudgets(prev => [...prev, ...toAdd]); addToast(`Applied ${toAdd.length} AI limits.`, 'success'); }} initialPrompt={pendingChatQuery} onPromptHandled={() => setPendingChatQuery(null)} botMode={botMode} onNavigate={setActiveTab} onAddGoal={(g) => { setGoals(prev => [...prev, g]); addToast('Goal created from proposal.', 'success'); }} goals={goals} budgets={budgets} />}
            {activeTab === 'sandbox' && <ScenarioSandbox transactions={transactions} goals={goals} formatCurrency={formatCurrency} userPlan={userPlan} onUpgradeClick={() => setActiveTab('plans')} insightUsage={insightUsage} onIncrementUsage={(val) => setInsightUsage(prev => prev + (val || 1))} />}
            {activeTab === 'goals' && <Goals goals={goals} budgets={budgets} transactions={transactions} onAddGoal={(g) => { setGoals(prev => [...prev, g]); addToast('Goal deployed.', 'success'); }} onUpdateGoal={(g) => { setGoals(prev => prev.map(goal => goal.id === g.id ? g : goal)); addToast('Goal updated.', 'success'); }} onAddBudget={(b) => { setBudgets(prev => [...prev, b]); addToast('Limit set.', 'success'); }} onDeleteBudget={(id) => { setBudgets(prev => prev.filter(b => b.id !== id)); addToast('Limit removed.', 'info'); }} formatCurrency={formatCurrency} />}
            {activeTab === 'plans' && <Plans currentPlan={userPlan} onUpgrade={(plan) => { setUserPlan(plan); addToast(`Plan upgraded.`, 'success'); }} onDowngrade={() => { setUserPlan('free'); addToast('Plan reset.', 'info'); }} onNavigateDashboard={() => setActiveTab('dashboard')} />}
            {activeTab === 'upcoming' && <UpcomingFeatures />}
            {activeTab === 'settings' && <Settings userName={userName} userEmail={userEmail} userAvatar={userAvatar} userAvatarZoom={userAvatarZoom} userAvatarPos={userAvatarPos} userBorder={userBorder} userBackground={userBackground} onUpdateBackground={setUserBackground} userPlan={userPlan} onUpdateProfile={(n, e, a, z, p, b) => { setUserName(n); setUserEmail(e); setUserAvatar(a); setUserAvatarZoom(z); setUserAvatarPos(p); setUserBorder(b); addToast('Profile updated.', 'success'); }} addToast={addToast} onExportData={() => addToast('Exporting...')} onImportData={() => addToast('Importing...')} onClearData={() => addToast('Clearing...')} language={language} onUpdateLanguage={setLanguage} currency={currency} onUpdateCurrency={setCurrency} botMode={botMode} onUpdateBotMode={setBotMode} spendingLimit={spendingLimit} onUpdateSpendingLimit={setSpendingLimit} spendingPeriod={spendingPeriod} onUpdateSpendingPeriod={setSpendingPeriod} />}
        </div>
      </main>

      {isLogoutModalOpen && (
          <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/95 backdrop-blur-2xl animate-fade-in">
              <div className="bg-[#0f172a] border border-rose-500/30 rounded-[3rem] w-full max-w-sm shadow-[0_0_100px_rgba(244,63,94,0.2)] p-10 text-center animate-slide-up relative">
                  <div className="w-20 h-20 bg-rose-500/20 rounded-[2rem] flex items-center justify-center mx-auto mb-8 border border-rose-500/30"><ShieldX className="w-10 h-10 text-rose-500" /></div>
                  <h3 className="text-2xl font-black text-white mb-3 uppercase tracking-tighter">Terminate?</h3>
                  <div className="space-y-4">
                      <button onClick={confirmLogout} className="w-full py-4 bg-rose-600 hover:bg-rose-500 text-white font-black rounded-2xl shadow-xl transition-all">Sign Out</button>
                      <button onClick={() => setIsLogoutModalOpen(false)} className="w-full py-4 bg-slate-900/50 text-slate-400 font-bold rounded-2xl border border-white/5 hover:text-white transition-all">Stay Connected</button>
                  </div>
              </div>
          </div>
      )}

      <ToastContainer toasts={toasts} onRemove={removeToast} />
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { generateNegotiationScript } from '../services/geminiService';
import { Handshake, Loader2, DollarSign, Copy, Check, FileText, Zap, ShieldAlert, ArrowRight, Plus, X, Search, TrendingDown, ExternalLink, AlertTriangle, Info, CheckCircle } from 'lucide-react';
import { UserPlan, Transaction, TransactionType, Category } from '../types';

interface BillNegotiatorProps {
  userPlan: UserPlan;
  onIncrementUsage: () => void;
  negotiationUsage: number;
  transactions?: Transaction[];
}

interface SubscriptionItem {
    id: string;
    name: string;
    amount: number;
    lastDate: string;
    nextEstimate: string;
    status: 'Safe' | 'Medium' | 'Danger';
    insight: string;
    isDemo?: boolean;
}

// ---------------------------------------------------------------------------
// FALLBACK DATA
// ---------------------------------------------------------------------------
const DEMO_ITEMS: SubscriptionItem[] = [
    { 
        id: 'demo_1', 
        name: 'Netflix (Demo)', 
        amount: 19.99, 
        lastDate: '2023-11-15', 
        nextEstimate: '2023-12-15', 
        status: 'Safe', 
        insight: 'Standard renewal pattern detected.',
        isDemo: true 
    },
    { 
        id: 'demo_2', 
        name: 'Adobe Creative (Demo)', 
        amount: 59.99, 
        lastDate: '2023-11-20', 
        nextEstimate: '2023-12-20', 
        status: 'Danger', 
        insight: 'Cheaper plan available (Student/Retention offer).',
        isDemo: true 
    },
    { 
        id: 'demo_3', 
        name: 'Spotify (Demo)', 
        amount: 11.99, 
        lastDate: '2023-11-25', 
        nextEstimate: '2023-12-25', 
        status: 'Safe', 
        insight: 'No usage pattern anomalies.',
        isDemo: true 
    },
];

const BillNegotiator: React.FC<BillNegotiatorProps> = ({ userPlan, onIncrementUsage, negotiationUsage, transactions = [] }) => {
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [generatedScript, setGeneratedScript] = useState<string | null>(null);
  const [isGenerating, setIsGenerating] = useState(false);
  const [isCopied, setIsCopied] = useState(false);
  const [manualModalOpen, setManualModalOpen] = useState(false);
  const [manualItems, setManualItems] = useState<SubscriptionItem[]>([]);
  const [negotiationType, setNegotiationType] = useState<'discount' | 'cancel' | 'downgrade'>('discount');

  const isElite = userPlan === 'ultra';
  const isPro = userPlan === 'pro';

  // Usage Limits: Free=1, Gold(Pro)=100, Elite=Unlimited
  const usageLimit = isElite ? 9999 : isPro ? 100 : 1;
  const isLimitReached = negotiationUsage >= usageLimit;

  // -------------------------------------------------------------------------
  // DATA PROCESSING
  // -------------------------------------------------------------------------
  const subscriptions = useMemo(() => {
      try {
          const detected: SubscriptionItem[] = [];
          const safeTx = Array.isArray(transactions) ? transactions : [];

          // 1. Group transactions by merchant
          const merchantMap = new Map<string, Transaction>();

          safeTx.forEach(t => {
              if (t.type === TransactionType.EXPENSE) {
                  const isSub = t.category === Category.SUBSCRIPTION || t.category === Category.UTILITIES || t.category === Category.ENTERTAINMENT;
                  if (isSub) {
                      const key = t.merchant.toLowerCase().trim();
                      const existing = merchantMap.get(key);
                      if (!existing || new Date(t.date) > new Date(existing.date)) {
                          merchantMap.set(key, t);
                      }
                  }
              }
          });

          // 2. Convert to SubscriptionItem with Logic
          merchantMap.forEach(t => {
              const lastDateObj = new Date(t.date);
              const nextDateObj = new Date(lastDateObj);
              nextDateObj.setDate(lastDateObj.getDate() + 30); // 30-day cycle estimation

              // Pure Math Status
              let status: 'Safe' | 'Medium' | 'Danger' = 'Safe';
              if (t.amount > 100) status = 'Danger';
              else if (t.amount > 40) status = 'Medium';

              // Insight Logic
              let insight = "";
              if (t.amount > 80) insight = "Cheaper plan available via retention desk.";
              else if (t.amount > 40) insight = "Increase in cost detected vs category average.";
              else insight = "No usage pattern anomalies.";

              // Elite Enrichment
              if (isElite) {
                  insight += " [Deep Scan: 98% Confidence]";
              }

              detected.push({
                  id: t.id,
                  name: t.merchant,
                  amount: t.amount,
                  lastDate: t.date,
                  nextEstimate: nextDateObj.toISOString().split('T')[0],
                  status,
                  insight
              });
          });

          const allItems = [...detected, ...manualItems];

          // Prioritization for Gold/Elite
          if (isPro || isElite) {
              allItems.sort((a, b) => b.amount - a.amount);
          }

          return allItems.length > 0 ? allItems : DEMO_ITEMS;

      } catch (err) {
          console.error("Error processing subscriptions:", err);
          return DEMO_ITEMS;
      }
  }, [transactions, manualItems, isPro, isElite]);

  const activeItem = subscriptions.find(s => s.id === selectedId) || null;

  // -------------------------------------------------------------------------
  // ACTIONS
  // -------------------------------------------------------------------------
  const handleGenerate = async () => {
      if (!activeItem || isLimitReached) return;

      setIsGenerating(true);
      setGeneratedScript(null);
      onIncrementUsage();

      setTimeout(async () => {
          const script = await generateNegotiationScript(activeItem.name, activeItem.amount, negotiationType);
          setGeneratedScript(script);
          setIsGenerating(false);
      }, 800);
  };

  const handleCopy = () => {
      if (generatedScript) {
          navigator.clipboard.writeText(generatedScript);
          setIsCopied(true);
          setTimeout(() => setIsCopied(false), 2000);
      }
  };

  const handleAddManual = (name: string, amt: number) => {
      const today = new Date();
      const next = new Date();
      next.setDate(today.getDate() + 30);

      const status = amt > 100 ? 'Danger' : amt > 40 ? 'Medium' : 'Safe';

      const newItem: SubscriptionItem = {
          id: `manual_${Date.now()}`,
          name,
          amount: amt,
          lastDate: today.toISOString().split('T')[0],
          nextEstimate: next.toISOString().split('T')[0],
          status,
          insight: "Manual Entry - Monitoring started."
      };
      setManualItems(prev => [newItem, ...prev]);
      setManualModalOpen(false);
  };

  const getStatusColor = (status: string) => {
      switch(status) {
          case 'Danger': return 'bg-rose-500/20 text-rose-400 border-rose-500/30';
          case 'Medium': return 'bg-amber-500/20 text-amber-400 border-amber-500/30';
          default: return 'bg-emerald-500/20 text-emerald-400 border-emerald-500/30';
      }
  };

  return (
    <div className="max-w-7xl mx-auto space-y-8 animate-fade-in pb-20">

      {/* HEADER */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-end gap-4">
          <div>
              <h2 className="text-3xl font-black text-white tracking-tighter flex items-center gap-3">
                  <Handshake className="w-8 h-8 text-indigo-400" />
                  Negotiator Node
              </h2>
              <p className="text-slate-400 font-medium mt-2 max-w-lg">
                  Automated retention scripting and subscription auditing.
              </p>
          </div>
          <div className="bg-slate-900 border border-white/10 px-4 py-2 rounded-xl text-right">
              <div className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Generations</div>
              <div className={`text-xl font-black ${isLimitReached ? 'text-rose-500' : 'text-emerald-400'}`}>
                  {isElite ? '∞' : usageLimit - negotiationUsage} <span className="text-slate-600 text-sm">{isElite ? '' : `/ ${usageLimit}`}</span>
              </div>
          </div>
      </div>

      <div className="grid grid-cols-1 xl:grid-cols-12 gap-8">

          {/* LEFT SIDEBAR: TABLE */}
          <div className="xl:col-span-7 space-y-4">
              <div className="flex justify-between items-center px-1">
                  <h3 className="text-xs font-black text-slate-500 uppercase tracking-widest">Active Subscriptions</h3>
                  <button onClick={() => setManualModalOpen(true)} className="text-indigo-400 hover:text-white transition-colors flex items-center gap-1 text-xs font-bold">
                      <Plus className="w-4 h-4" /> Add Manual
                  </button>
              </div>

              <div className="bg-slate-900/40 border border-white/5 rounded-[2rem] overflow-hidden">
                  <div className="overflow-x-auto custom-scrollbar">
                      <table className="w-full text-left border-collapse">
                          <thead>
                              <tr className="bg-slate-900/80 border-b border-white/5 text-[10px] uppercase font-black text-slate-500 tracking-widest">
                                  <th className="p-5">Provider</th>
                                  <th className="p-5">Last Charge</th>
                                  <th className="p-5">Next Est.</th>
                                  <th className="p-5">Status</th>
                              </tr>
                          </thead>
                          <tbody className="divide-y divide-white/5">
                              {subscriptions.map(item => (
                                  <React.Fragment key={item.id}>
                                      <tr 
                                        onClick={() => { setSelectedId(item.id); setGeneratedScript(null); }}
                                        className={`cursor-pointer transition-colors group ${selectedId === item.id ? 'bg-indigo-600/10' : 'hover:bg-white/5'}`}
                                      >
                                          <td className="p-5 font-bold text-white text-sm">
                                              {item.name}
                                              {item.isDemo && <span className="ml-2 text-[9px] bg-slate-800 text-slate-500 px-1.5 py-0.5 rounded uppercase tracking-wide">Demo</span>}
                                          </td>
                                          <td className="p-5 font-mono text-slate-300 text-sm">${item.amount.toFixed(2)}</td>
                                          <td className="p-5 text-slate-400 text-xs">{item.nextEstimate}</td>
                                          <td className="p-5">
                                              <span className={`px-2 py-1 rounded text-[10px] font-black uppercase tracking-widest border ${getStatusColor(item.status)}`}>
                                                  {item.status}
                                              </span>
                                          </td>
                                      </tr>
                                      {/* Insight Line */}
                                      <tr className={`${selectedId === item.id ? 'bg-indigo-600/5' : 'bg-transparent'}`}>
                                          <td colSpan={4} className="px-5 pb-4 pt-0">
                                              <div className="flex items-center gap-2 text-xs text-indigo-300 font-medium pl-2 border-l-2 border-indigo-500/30">
                                                  <Info className="w-3 h-3" />
                                                  {item.insight}
                                              </div>
                                          </td>
                                      </tr>
                                  </React.Fragment>
                              ))}
                          </tbody>
                      </table>
                  </div>
                  {subscriptions.length === 0 && (
                      <div className="p-10 text-center text-slate-500 text-sm">No subscriptions detected.</div>
                  )}
              </div>
          </div>

          {/* RIGHT PANEL: WORKBENCH */}
          <div className="xl:col-span-5">
              {activeItem ? (
                  <div className="glass-card rounded-[2.5rem] border border-white/10 overflow-hidden flex flex-col h-full bg-slate-900/60 min-h-[600px] shadow-2xl relative">

                      {/* Item Header */}
                      <div className="p-8 border-b border-white/5 bg-slate-950/50">
                          <div className="flex items-center gap-5">
                              <div className="w-16 h-16 rounded-2xl bg-gradient-to-br from-indigo-600 to-violet-700 flex items-center justify-center text-3xl font-black text-white shadow-lg ring-1 ring-white/10">
                                  {activeItem.name.charAt(0)}
                              </div>
                              <div>
                                  <h2 className="text-2xl font-bold text-white tracking-tight">{activeItem.name}</h2>
                                  <div className="flex items-center gap-3 mt-1">
                                      <span className="text-slate-400 text-sm font-medium">Monthly: <span className="text-white font-bold">${activeItem.amount}</span></span>
                                      <span className="text-slate-600 text-xs">•</span>
                                      <span className="text-emerald-400 text-xs font-bold uppercase tracking-wide">Active</span>
                                  </div>
                              </div>
                          </div>
                      </div>

                      <div className="p-8 flex-1 flex flex-col">

                          {/* Strategy Selector */}
                          <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-3">Negotiation Strategy</h4>
                          <div className="grid grid-cols-3 gap-3 mb-8">
                              <button 
                                onClick={() => { setNegotiationType('discount'); setGeneratedScript(null); }}
                                className={`p-3 rounded-2xl border transition-all flex flex-col items-center gap-2 ${negotiationType === 'discount' ? 'bg-emerald-500/10 border-emerald-500/50 text-emerald-400' : 'bg-slate-800/30 border-white/5 text-slate-400 hover:bg-slate-800'}`}
                              >
                                  <DollarSign className="w-5 h-5" />
                                  <span className="text-[10px] font-bold uppercase tracking-wider">Discount</span>
                              </button>
                              <button 
                                onClick={() => { setNegotiationType('downgrade'); setGeneratedScript(null); }}
                                className={`p-3 rounded-2xl border transition-all flex flex-col items-center gap-2 ${negotiationType === 'downgrade' ? 'bg-amber-500/10 border-amber-500/50 text-amber-400' : 'bg-slate-800/30 border-white/5 text-slate-400 hover:bg-slate-800'}`}
                              >
                                  <TrendingDown className="w-5 h-5" />
                                  <span className="text-[10px] font-bold uppercase tracking-wider">Downgrade</span>
                              </button>
                              <button 
                                onClick={() => { setNegotiationType('cancel'); setGeneratedScript(null); }}
                                className={`p-3 rounded-2xl border transition-all flex flex-col items-center gap-2 ${negotiationType === 'cancel' ? 'bg-rose-500/10 border-rose-500/50 text-rose-400' : 'bg-slate-800/30 border-white/5 text-slate-400 hover:bg-slate-800'}`}
                              >
                                  <X className="w-5 h-5" />
                                  <span className="text-[10px] font-bold uppercase tracking-wider">Cancel</span>
                              </button>
                          </div>

                          {/* Action Area */}
                          <div className="flex-1 bg-slate-950 rounded-[1.5rem] border border-white/10 p-6 relative overflow-hidden">
                              {!generatedScript && !isGenerating && (
                                  <div className="absolute inset-0 flex flex-col items-center justify-center text-center p-8 opacity-70">
                                      <div className="w-16 h-16 bg-slate-900 rounded-full flex items-center justify-center mb-6 border border-white/5">
                                          <Zap className="w-8 h-8 text-indigo-500" />
                                      </div>
                                      <p className="text-slate-300 text-sm font-medium mb-8 max-w-xs">
                                          Ready to generate a professional negotiation script for {activeItem.name}.
                                      </p>
                                      {isLimitReached ? (
                                          <div className="p-4 bg-rose-500/10 border border-rose-500/20 rounded-xl text-rose-300 text-xs font-bold flex items-center gap-2">
                                              <AlertTriangle className="w-4 h-4" /> Usage Limit Reached
                                          </div>
                                      ) : (
                                          <button 
                                            onClick={handleGenerate}
                                            className="px-8 py-4 bg-indigo-600 hover:bg-indigo-500 text-white font-bold rounded-2xl shadow-xl shadow-indigo-500/20 transition-all flex items-center gap-2 active:scale-95"
                                          >
                                              <FileText className="w-4 h-4" /> Generate Script
                                          </button>
                                      )}
                                  </div>
                              )}

                              {isGenerating && (
                                  <div className="absolute inset-0 flex flex-col items-center justify-center bg-slate-950 z-20">
                                      <Loader2 className="w-10 h-10 text-indigo-500 animate-spin mb-4" />
                                      <p className="text-indigo-400 text-xs font-black uppercase tracking-widest animate-pulse">Consulting Neural Network...</p>
                                  </div>
                              )}

                              {generatedScript && (
                                  <div className="h-full flex flex-col animate-fade-in relative z-10">
                                      <div className="flex justify-between items-center mb-4">
                                          <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">AI Response</span>
                                          <button onClick={handleCopy} className="flex items-center gap-2 text-xs font-bold text-indigo-400 hover:text-white transition-colors bg-indigo-500/10 px-3 py-1.5 rounded-lg border border-indigo-500/20">
                                              {isCopied ? <Check className="w-3 h-3" /> : <Copy className="w-3 h-3" />}
                                              {isCopied ? 'Copied' : 'Copy'}
                                          </button>
                                      </div>
                                      <div className="flex-1 overflow-y-auto custom-scrollbar p-4 bg-slate-900/50 rounded-xl border border-white/5 mb-4">
                                          <p className="text-slate-300 text-sm leading-relaxed whitespace-pre-wrap font-medium">{generatedScript}</p>
                                      </div>
                                      <div className="flex gap-3">
                                          <a href={`https://www.google.com/search?q=${activeItem.name}+customer+service`} target="_blank" rel="noreferrer" className="flex-1 py-3 bg-slate-800 hover:bg-slate-700 text-white font-bold text-xs rounded-xl flex items-center justify-center gap-2 transition-colors border border-white/5">
                                              Find Contact <ExternalLink className="w-3 h-3" />
                                          </a>
                                          {!isLimitReached && (
                                              <button onClick={handleGenerate} className="flex-1 py-3 bg-indigo-600/20 hover:bg-indigo-600/30 text-indigo-400 font-bold text-xs rounded-xl transition-colors border border-indigo-500/30">
                                                  Regenerate
                                              </button>
                                          )}
                                      </div>
                                  </div>
                              )}
                          </div>

                      </div>
                  </div>
              ) : (
                  <div className="h-full flex flex-col items-center justify-center text-center p-12 border-2 border-dashed border-slate-800 rounded-[2.5rem] bg-slate-900/20">
                      <div className="w-20 h-20 bg-slate-900 rounded-[2rem] flex items-center justify-center mb-6 shadow-xl ring-1 ring-white/5">
                          <Search className="w-8 h-8 text-slate-600" />
                      </div>
                      <h3 className="text-xl font-bold text-white mb-2">No Bill Selected</h3>
                      <p className="text-slate-500 text-sm font-medium max-w-xs">Select a subscription from the list to start the negotiation process.</p>
                  </div>
              )}
          </div>
      </div>

      {/* MANUAL ADD MODAL */}
      {manualModalOpen && (
          <ManualAddModal onClose={() => setManualModalOpen(false)} onAdd={handleAddManual} />
      )}

    </div>
  );
};

const ManualAddModal: React.FC<{ onClose: () => void, onAdd: (name: string, amt: number) => void }> = ({ onClose, onAdd }) => {
    const [name, setName] = useState('');
    const [amt, setAmt] = useState('');

    return (
