                    <button onClick={() => { if(name && amt) onAdd(name, parseFloat(amt)) }} className="w-full py-3 bg-indigo-600 hover:bg-indigo-500 text-white font-bold rounded-xl uppercase text-xs tracking-widest mt-4">
