                  <div className="h-full flex flex-col items-center justify-center text-center p-12 border-2 border-dashed border-slate-800 rounded-[2.5rem] bg-slate-900/20 sticky top-6">
                      <div className="w-24 h-24 bg-slate-900 rounded-[2.5rem] flex items-center justify-center mb-8 shadow-2xl ring-1 ring-white/5">
                          <Calculator className="w-10 h-10 text-slate-600" />
                      </div>
                      <h3 className="text-2xl font-black text-white mb-3 uppercase tracking-tight">Workbench Idle</h3>
                      <p className="text-slate-500 text-sm font-medium max-w-xs leading-relaxed">
                          Select a subscription from the list on the left to initialize the negotiation engine.
                      </p>
                  </div>
              )}
          </div>
      </div>

      {/* MANUAL ADD MODAL */}
      {manualModalOpen && (
          <ManualAddModal onClose={() => setManualModalOpen(false)} onAdd={handleAddManual} />
      )}

    </div>
  );
};

