export default BillNegotiator;

import React, { useState, useMemo } from 'react';
import { generateNegotiationScript } from '../services/geminiService';
import { Handshake, Loader2, DollarSign, Copy, Check, FileText, Zap, ShieldAlert, ArrowRight, Plus, X, Search, TrendingDown, ExternalLink, AlertTriangle, Info, CheckCircle, Calculator, Calendar, AlertOctagon } from 'lucide-react';
import { UserPlan, Transaction, TransactionType, Category } from '../types';

interface BillNegotiatorProps {
  userPlan: UserPlan;
  onIncrementUsage: () => void;
  negotiationUsage: number;
  transactions?: Transaction[];
}

interface SubscriptionItem {
    id: string;
    name: string;
    amount: number;
    lastDate: string;
    nextEstimate: string;
    status: 'Safe' | 'Medium' | 'Danger';
    insight: string;
    annualCost: number;
}

const BillNegotiator: React.FC<BillNegotiatorProps> = ({ userPlan, onIncrementUsage, negotiationUsage, transactions = [] }) => {
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [generatedScript, setGeneratedScript] = useState<string | null>(null);
  const [isGenerating, setIsGenerating] = useState(false);
  const [isCopied, setIsCopied] = useState(false);
  const [manualModalOpen, setManualModalOpen] = useState(false);
  const [manualItems, setManualItems] = useState<SubscriptionItem[]>([]);
  const [negotiationType, setNegotiationType] = useState<'discount' | 'cancel' | 'downgrade'>('discount');

  const isElite = userPlan === 'ultra';
  const isPro = userPlan === 'pro';

  // Usage Limits: Free=1, Gold(Pro)=100, Elite=Unlimited
  const usageLimit = isElite ? 9999 : isPro ? 100 : 1;
  const isLimitReached = negotiationUsage >= usageLimit;

  // -------------------------------------------------------------------------
  // DATA PROCESSING
  // -------------------------------------------------------------------------
  const subscriptions = useMemo(() => {
      try {
          const detected: SubscriptionItem[] = [];
          const safeTx = Array.isArray(transactions) ? transactions : [];

          // 1. Group transactions by merchant to find recurring ones
          const merchantMap = new Map<string, Transaction>();

          safeTx.forEach(t => {
              if (t.type === TransactionType.EXPENSE) {
                  // Heuristic: Check specifically for subscription categories OR recurring keywords
                  const isSubCategory = t.category === Category.SUBSCRIPTION || t.category === Category.UTILITIES || t.category === Category.ENTERTAINMENT;

                  if (isSubCategory) {
                      const key = t.merchant.toLowerCase().trim();
                      const existing = merchantMap.get(key);
                      // Keep the most recent transaction for date calculation
                      if (!existing || new Date(t.date) > new Date(existing.date)) {
                          merchantMap.set(key, t);
                      }
                  }
              }
          });

          // 2. Convert to SubscriptionItem with Logic
          merchantMap.forEach(t => {
              const lastDateObj = new Date(t.date);
              const nextDateObj = new Date(lastDateObj);
              nextDateObj.setDate(lastDateObj.getDate() + 30); // 30-day cycle estimation

              // Pure Math Status
              let status: 'Safe' | 'Medium' | 'Danger' = 'Safe';
              if (t.amount > 100) status = 'Danger';
              else if (t.amount > 40) status = 'Medium';

              // Insight Logic based on Tier
              let insight = "Standard billing cycle detected.";

              if (isElite) {
                  // Elite Deep Analysis Simulation
                  if (t.amount > 100) insight = "Price elasticity high. Competitor rates ~20% lower. High probability of retention offer.";
                  else if (t.amount > 50) insight = "Usage pattern indicates cheaper tier sufficiency. Downgrade recommended.";
                  else insight = "Optimized. No significant arbitrage opportunities detected.";
              } else if (isPro) {
                  // Pro Logic
                  if (t.amount > 80) insight = "Cost increase detected relative to category average.";
                  else if (t.amount > 40) insight = "Mid-tier expense. Periodic review suggested.";
              } else {
                  // Free Logic
                  insight = t.amount > 50 ? "High cost subscription." : "Active subscription.";
              }

              detected.push({
                  id: t.id,
                  name: t.merchant,
                  amount: t.amount,
                  lastDate: t.date,
                  nextEstimate: nextDateObj.toISOString().split('T')[0],
                  status,
                  insight,
                  annualCost: t.amount * 12
              });
          });

          const allItems = [...detected, ...manualItems];

          // Prioritization for Gold/Elite (Higher cost = Higher priority)
          if (isPro || isElite) {
              allItems.sort((a, b) => b.amount - a.amount);
          }

          return allItems;

      } catch (err) {
          console.error("Error processing subscriptions:", err);
          return [];
      }
  }, [transactions, manualItems, isPro, isElite]);

  const activeItem = subscriptions.find(s => s.id === selectedId) || null;

  // -------------------------------------------------------------------------
  // ACTIONS
  // -------------------------------------------------------------------------
  const handleGenerate = async () => {
      if (!activeItem || isLimitReached) return;

      setIsGenerating(true);
      setGeneratedScript(null);
      onIncrementUsage();

      setTimeout(async () => {
          const script = await generateNegotiationScript(activeItem.name, activeItem.amount, negotiationType);
          setGeneratedScript(script);
          setIsGenerating(false);
      }, 800);
  };

  const handleCopy = () => {
      if (generatedScript) {
          navigator.clipboard.writeText(generatedScript);
          setIsCopied(true);
          setTimeout(() => setIsCopied(false), 2000);
      }
  };

  const handleAddManual = (name: string, amt: number, date: string) => {
      const lastDateObj = new Date(date);
      const nextDateObj = new Date(lastDateObj);
      nextDateObj.setDate(lastDateObj.getDate() + 30);

      const status = amt > 100 ? 'Danger' : amt > 40 ? 'Medium' : 'Safe';

      const newItem: SubscriptionItem = {
          id: `manual_${Date.now()}`,
          name,
          amount: amt,
          lastDate: date,
          nextEstimate: nextDateObj.toISOString().split('T')[0],
          status,
          insight: "Manual Entry - Tracking started.",
          annualCost: amt * 12
      };
      setManualItems(prev => [newItem, ...prev]);
      setManualModalOpen(false);
  };

  const getStatusBadge = (status: string) => {
      switch(status) {
          case 'Danger': return (
              <span className="flex items-center gap-1.5 px-2.5 py-1 rounded-lg bg-rose-500/10 border border-rose-500/20 text-rose-400 text-[10px] font-black uppercase tracking-widest">
                  <AlertOctagon className="w-3 h-3" /> Critical
              </span>
          );
          case 'Medium': return (
              <span className="flex items-center gap-1.5 px-2.5 py-1 rounded-lg bg-amber-500/10 border border-amber-500/20 text-amber-400 text-[10px] font-black uppercase tracking-widest">
                  <AlertTriangle className="w-3 h-3" /> Warning
              </span>
          );
          default: return (
              <span className="flex items-center gap-1.5 px-2.5 py-1 rounded-lg bg-emerald-500/10 border border-emerald-500/20 text-emerald-400 text-[10px] font-black uppercase tracking-widest">
                  <CheckCircle className="w-3 h-3" /> Stable
              </span>
          );
      }
  };

  return (
    <div className="max-w-[1600px] mx-auto space-y-8 animate-fade-in pb-20">

      {/* HEADER */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-end gap-6 bg-gradient-to-r from-indigo-900/20 to-transparent p-8 rounded-[2.5rem] border border-white/5 relative overflow-hidden">
          <div className="absolute top-0 right-0 w-64 h-64 bg-indigo-600/10 blur-[80px] rounded-full pointer-events-none"></div>
          <div className="relative z-10">
              <h2 className="text-3xl font-black text-white tracking-tighter flex items-center gap-4">
                  <div className="p-3 bg-indigo-600 rounded-2xl shadow-lg shadow-indigo-500/30">
                    <Handshake className="w-8 h-8 text-white" />
                  </div>
                  Negotiator Node
              </h2>
              <p className="text-slate-400 font-medium mt-4 max-w-lg leading-relaxed">
                  Automated retention scripting and deep-subscription auditing. Select a liability to generate a negotiation strategy.
              </p>
          </div>
          <div className="flex gap-4 relative z-10">
              <div className="bg-slate-900/80 border border-white/10 px-6 py-4 rounded-2xl text-right backdrop-blur-md">
                  <div className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1">AI Usage</div>
                  <div className={`text-2xl font-black ${isLimitReached ? 'text-rose-500' : 'text-emerald-400'}`}>
                      {isElite ? '∞' : usageLimit - negotiationUsage} <span className="text-slate-600 text-sm font-bold">{isElite ? '' : `/ ${usageLimit}`}</span>
                  </div>
              </div>
              <button 
                onClick={() => setManualModalOpen(true)} 
                className="bg-slate-900/80 hover:bg-slate-800 border border-white/10 hover:border-indigo-500/50 px-6 py-4 rounded-2xl text-slate-300 hover:text-white transition-all flex flex-col items-center justify-center gap-1 group active:scale-95"
              >
                  <Plus className="w-5 h-5 group-hover:text-indigo-400 transition-colors" />
                  <span className="text-[10px] font-black uppercase tracking-widest">Manual Add</span>
              </button>
          </div>
      </div>

      <div className="grid grid-cols-1 xl:grid-cols-12 gap-8 items-start">

          {/* LEFT SIDEBAR: TABLE */}
          <div className="xl:col-span-7 space-y-6">
              <div className="bg-slate-900/40 border border-white/5 rounded-[2.5rem] overflow-hidden shadow-2xl backdrop-blur-sm min-h-[600px] flex flex-col">
                  {subscriptions.length > 0 ? (
                      <div className="flex-1 overflow-x-auto custom-scrollbar">
                          <table className="w-full text-left border-collapse">
                              <thead>
                                  <tr className="bg-slate-950/50 border-b border-white/5 text-[10px] uppercase font-black text-slate-500 tracking-widest">
                                      <th className="p-6 pl-8">Provider</th>
                                      <th className="p-6">Last Charge</th>
                                      <th className="p-6">Next Est.</th>
                                      <th className="p-6 pr-8 text-right">Status</th>
                                  </tr>
                              </thead>
                              <tbody className="divide-y divide-white/5">
                                  {subscriptions.map(item => (
                                      <React.Fragment key={item.id}>
                                          <tr 
                                            onClick={() => { setSelectedId(item.id); setGeneratedScript(null); }}
                                            className={`cursor-pointer transition-all duration-200 group ${selectedId === item.id ? 'bg-indigo-600/10' : 'hover:bg-white/5'}`}
                                          >
                                              <td className="p-6 pl-8">
                                                  <div className="font-bold text-white text-base group-hover:text-indigo-300 transition-colors">{item.name}</div>
