                                              </td>
                                              <td className="p-6">
                                                  <div className="font-mono text-white font-bold text-sm bg-slate-950/50 px-3 py-1.5 rounded-lg border border-white/5 inline-block group-hover:border-white/10 transition-colors">
                                                      ${item.amount.toFixed(2)}
                                                  </div>
                                              </td>
                                              <td className="p-6">
                                                  <div className="flex items-center gap-2 text-slate-400 text-xs font-medium">
                                                      <Calendar className="w-3.5 h-3.5" />
                                                      {new Date(item.nextEstimate).toLocaleDateString(undefined, { month: 'short', day: 'numeric' })}
                                                  </div>
                                              </td>
                                              <td className="p-6 pr-8 text-right">
                                                  <div className="flex justify-end">{getStatusBadge(item.status)}</div>
                                              </td>
                                          </tr>
                                          {/* Insight Line */}
                                          <tr className={`${selectedId === item.id ? 'bg-indigo-600/5' : 'bg-transparent'}`}>
                                              <td colSpan={4} className="px-8 pb-6 pt-0">
                                                  <div className={`flex items-start gap-3 text-xs font-medium pl-4 py-3 border-l-2 ${selectedId === item.id ? 'border-indigo-500 text-indigo-200 bg-indigo-500/5 rounded-r-xl' : 'border-slate-700 text-slate-500'}`}>
                                                      <Info className={`w-4 h-4 shrink-0 mt-0.5 ${selectedId === item.id ? 'text-indigo-400' : 'text-slate-600'}`} />
                                                      {item.insight}
                                                  </div>
                                              </td>
                                          </tr>
                                      </React.Fragment>
                                  ))}
                              </tbody>
                          </table>
                      </div>
                  ) : (
                      <div className="flex-1 flex flex-col items-center justify-center text-center p-12 opacity-60">
                          <div className="w-24 h-24 bg-slate-800 rounded-3xl flex items-center justify-center mb-6 shadow-xl ring-1 ring-white/5 rotate-12">
                              <Search className="w-10 h-10 text-slate-500" />
                          </div>
                          <h3 className="text-xl font-bold text-white mb-2 uppercase tracking-tight">No Liabilities Detected</h3>
                          <p className="text-slate-500 text-sm font-medium max-w-xs leading-relaxed mb-8">
                              Add transactions categorized as "Subscription", "Utilities", or "Entertainment" to populate this list.
                          </p>
                          <button onClick={() => setManualModalOpen(true)} className="px-6 py-3 bg-indigo-600 text-white font-bold rounded-xl shadow-lg hover:bg-indigo-500 transition-all text-xs uppercase tracking-widest flex items-center gap-2">
                              <Plus className="w-4 h-4" /> Manual Add
                          </button>
                      </div>
