              </div>
          </div>

          {/* RIGHT PANEL: WORKBENCH */}
          <div className="xl:col-span-5 h-full">
              {activeItem ? (
                  <div className="glass-card rounded-[2.5rem] border border-white/10 overflow-hidden flex flex-col h-full bg-slate-900/60 shadow-2xl relative animate-slide-up sticky top-6">

                      {/* Item Header */}
