                              <div className="w-20 h-20 rounded-3xl bg-gradient-to-br from-indigo-600 to-purple-700 flex items-center justify-center text-4xl font-black text-white shadow-2xl shadow-indigo-900/50 ring-1 ring-white/20">
                                  {activeItem.name.charAt(0).toUpperCase()}
