                          <div className="grid grid-cols-2 gap-4 mt-8">
                              <div className="bg-slate-800/50 p-4 rounded-2xl border border-white/5">
                                  <div className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1">Monthly Cost</div>
                                  <div className="text-2xl font-black text-white">${activeItem.amount.toFixed(2)}</div>
                              </div>
                              <div className="bg-slate-800/50 p-4 rounded-2xl border border-white/5">
