                                              <div className="w-2.5 h-2.5 rounded-full bg-emerald-500"></div>
                                              <span className="ml-2 text-[10px] font-mono text-slate-500 font-bold uppercase">secure_script.txt</span>
                                          </div>
                                          <button onClick={handleCopy} className={`flex items-center gap-2 text-[10px] font-black uppercase tracking-widest px-3 py-1.5 rounded-lg border transition-all ${isCopied ? 'bg-emerald-500/20 text-emerald-400 border-emerald-500/30' : 'bg-indigo-500/10 text-indigo-300 border-indigo-500/20 hover:bg-indigo-500/20'}`}>
                                              {isCopied ? <Check className="w-3 h-3" /> : <Copy className="w-3 h-3" />}
                                              {isCopied ? 'Copied' : 'Copy Text'}
                                          </button>
                                      </div>

                                      <div className="flex-1 overflow-y-auto custom-scrollbar p-6 bg-slate-950">
                                          <p className="text-slate-300 text-xs leading-relaxed whitespace-pre-wrap font-mono">{generatedScript}</p>
                                      </div>

                                      <div className="p-4 bg-slate-900/50 border-t border-white/5 flex gap-3 rounded-b-[1.8rem]">
                                          <a href={`https://www.google.com/search?q=${activeItem.name}+customer+service+contact`} target="_blank" rel="noreferrer" className="flex-1 py-3 bg-slate-800 hover:bg-slate-700 text-white font-bold text-xs rounded-xl flex items-center justify-center gap-2 transition-colors border border-white/5 uppercase tracking-wider">
                                              Find Contact <ExternalLink className="w-3 h-3" />
                                          </a>
                                          {!isLimitReached && (
                                              <button onClick={handleGenerate} className="flex-1 py-3 bg-indigo-600/10 hover:bg-indigo-600/20 text-indigo-400 font-bold text-xs rounded-xl transition-colors border border-indigo-500/20 uppercase tracking-wider">
                                                  Regenerate
                                              </button>
                                          )}
                                      </div>
                                  </div>
                              )}
                          </div>

                      </div>
                  </div>
              ) : (
                  <div className="h-full flex flex-col items-center justify-center text-center p-12 border-2 border-dashed border-slate-800 rounded-[2.5rem] bg-slate-900/20 sticky top-6">
                      <div className="w-24 h-24 bg-slate-900 rounded-[2.5rem] flex items-center justify-center mb-8 shadow-2xl ring-1 ring-white/5">
                          <Calculator className="w-10 h-10 text-slate-600" />
                      </div>
                      <h3 className="text-2xl font-black text-white mb-3 uppercase tracking-tight">Workbench Idle</h3>
                      <p className="text-slate-500 text-sm font-medium max-w-xs leading-relaxed">
                          Select a subscription from the list on the left to initialize the negotiation engine.
                      </p>
                  </div>
              )}
          </div>
      </div>

      {/* MANUAL ADD MODAL */}
      {manualModalOpen && (
          <ManualAddModal onClose={() => setManualModalOpen(false)} onAdd={handleAddManual} />
      )}

    </div>
  );
};

const ManualAddModal: React.FC<{ onClose: () => void, onAdd: (name: string, amt: number, date: string) => void }> = ({ onClose, onAdd }) => {
    const [name, setName] = useState('');
    const [amt, setAmt] = useState('');
    const [date, setDate] = useState(new Date().toISOString().split('T')[0]);

    return (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/80 backdrop-blur-md animate-fade-in">
            <div className="bg-[#0f172a] border border-white/10 rounded-3xl w-full max-w-sm p-8 shadow-2xl animate-slide-up relative">
                <button onClick={onClose} className="absolute top-4 right-4 text-slate-500 hover:text-white"><X className="w-5 h-5" /></button>
                <div className="mb-6">
                    <div className="w-12 h-12 bg-indigo-500/20 rounded-2xl flex items-center justify-center mb-4"><Plus className="w-6 h-6 text-indigo-400" /></div>
                    <h3 className="text-xl font-black text-white uppercase tracking-tight">Add Bill Manually</h3>
                    <p className="text-slate-400 text-xs mt-1">Track off-ledger subscriptions.</p>
                </div>
                <div className="space-y-5">
                    <div>
                        <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest block mb-2">Service Name</label>
                        <input autoFocus value={name} onChange={e => setName(e.target.value)} className="w-full bg-slate-900 border border-white/10 rounded-xl p-3.5 text-white text-sm focus:border-indigo-500 outline-none transition-all placeholder:text-slate-700" placeholder="e.g. Hulu" />
                    </div>
                    <div>
                        <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest block mb-2">Monthly Cost</label>
                        <div className="relative">
                            <span className="absolute left-3.5 top-1/2 -translate-y-1/2 text-slate-500 font-bold">$</span>
                            <input type="number" value={amt} onChange={e => setAmt(e.target.value)} className="w-full bg-slate-900 border border-white/10 rounded-xl p-3.5 pl-8 text-white text-sm focus:border-indigo-500 outline-none transition-all placeholder:text-slate-700" placeholder="0.00" />
                        </div>
                    </div>
                    <div>
                        <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest block mb-2">Date Bought</label>
                        <input type="date" value={date} onChange={e => setDate(e.target.value)} className="w-full bg-slate-900 border border-white/10 rounded-xl p-3.5 text-white text-sm focus:border-indigo-500 outline-none transition-all [color-scheme:dark]" />
                    </div>
                    <button onClick={() => { if(name && amt && date) onAdd(name, parseFloat(amt), date) }} className="w-full py-4 bg-indigo-600 hover:bg-indigo-500 text-white font-black rounded-xl uppercase text-xs tracking-[0.2em] mt-2 shadow-lg active:scale-95 transition-all">
                        Track Bill
                    </button>
                </div>
            </div>
        </div>
    );
};

