const BudgetCard: React.FC<{ budget: Budget, transactions: Transaction[], onDelete?: (id: string) => void, formatCurrency: (amount: number) => string | React.ReactNode }> = ({ budget, transactions, onDelete, formatCurrency }) => {
    const spent = useMemo(() => {
        if (budget.startDate) {
            // AI-Suggested Budget Logic (Custom Cycle)
            const startDate = new Date(budget.startDate);
            const endDate = new Date(startDate);
            endDate.setDate(endDate.getDate() + 30);

            // Rolling 30-day cycle logic
            const now = new Date();
            const timeDiff = now.getTime() - startDate.getTime();
            const daysDiff = Math.floor(timeDiff / (1000 * 3600 * 24));
            const cyclesPassed = Math.floor(daysDiff / 30);

            const currentCycleStart = new Date(startDate);
            currentCycleStart.setDate(currentCycleStart.getDate() + (cyclesPassed * 30));

            const currentCycleEnd = new Date(currentCycleStart);
            currentCycleEnd.setDate(currentCycleEnd.getDate() + 30);

            return transactions
                .filter(t => 
                    t.category === budget.category && 
                    t.type === TransactionType.EXPENSE && 
                    new Date(t.date) >= currentCycleStart &&
                    new Date(t.date) < currentCycleEnd
                )
                .reduce((acc, t) => acc + t.amount, 0);
        } else {
            // Standard Logic (Calendar Month) - Fallback
            const now = new Date();
            const currentMonth = now.getMonth();
            const currentYear = now.getFullYear();
            return transactions
                .filter(t => 
                    t.category === budget.category && 
                    t.type === TransactionType.EXPENSE && 
                    new Date(t.date).getMonth() === currentMonth && 
                    new Date(t.date).getFullYear() === currentYear
                )
                .reduce((acc, t) => acc + t.amount, 0);
        }
    }, [budget.category, transactions, budget.startDate]);

    const percentage = Math.min((spent / budget.limit) * 100, 100);
    const remaining = budget.limit - spent;
    const isOver = spent > budget.limit;
    const isWarning = percentage > 80 && !isOver;
    let statusColor = "bg-emerald-500";
    if (isWarning) statusColor = "bg-amber-500";
    else if (isOver) statusColor = "bg-rose-500";

    return (
        <div className="glass-card p-6 rounded-3xl relative group overflow-hidden border border-white/5 hover:border-white/20 transition-all">
            {onDelete && (<button onClick={() => onDelete(budget.id)} className="absolute top-4 right-4 p-2 bg-slate-900/50 rounded-lg text-slate-500 hover:text-rose-400 hover:bg-rose-950 opacity-0 group-hover:opacity-100 transition-all z-20"><Trash2 className="w-4 h-4" /></button>)}
            <div className="flex justify-between items-start mb-4">
                <div className="flex items-center gap-3">
                    <div className={`p-3 rounded-xl bg-slate-800/50 border border-white/10 ${isOver ? 'ring-2 ring-rose-500/20' : ''}`}>
                        <PieChart className={`w-6 h-6 ${isOver ? 'text-rose-400' : 'text-indigo-400'}`} />
                    </div>
                    <div>
                        <h4 className="font-bold text-white">{budget.category}</h4>
                        <p className="text-xs text-slate-400 font-medium">
                            {isOver ? 'Over Budget' : `${percentage.toFixed(0)}% Used`}
                        </p>
                    </div>
                </div>
            </div>

            {budget.startDate && (
                <div className="mb-3 flex items-center gap-1.5 text-[10px] font-bold text-indigo-400 uppercase tracking-wider bg-indigo-500/10 px-2 py-1 rounded w-fit border border-indigo-500/20">
                    <Calendar className="w-3 h-3" /> Cooldown Active
                </div>
            )}

            <div className="space-y-2">
                <div className="flex justify-between text-sm font-bold text-slate-300"><span className={isOver ? 'text-rose-400' : ''}>{formatCurrency(spent)}</span><span className="text-slate-500">/{formatCurrency(budget.limit)}</span></div>
                <div className="w-full bg-slate-800 h-2.5 rounded-full overflow-hidden flex border border-white/5"><div className={`h-full rounded-full transition-all duration-1000 ${statusColor} relative`} style={{ width: `${percentage}%` }}>{isOver && <div className="absolute inset-0 bg-white/20 animate-pulse"></div>}</div></div>
                <div className="flex justify-between items-center mt-2"><span className="text-xs font-bold text-slate-500 uppercase tracking-wider">Remaining</span><span className={`text-xs font-bold ${remaining < 0 ? 'text-rose-400' : 'text-emerald-400'}`}>{remaining < 0 ? '-' : ''}{formatCurrency(Math.abs(remaining))}</span></div>
            </div>
        </div>
    );
};

const AddGoalModal: React.FC<{ onClose: () => void, onSubmit: (g: Goal) => void }> = ({ onClose, onSubmit }) => {
