    { 
        id: '1', 
        role: 'assistant', 
        content: botMode === 'ruthless' 
            ? 'System initialized. Ready to audit your spending vectors.' 
            : 'Hello! I\'m ready to help you optimize your financial wellness. What\'s on your mind?', 
        timestamp: new Date(),
        sentiment: 'info'
    }
  ]);
  const [chatLoading, setChatLoading] = useState(false);
  const [showRejectModal, setShowRejectModal] = useState<GoalProposal | null>(null);
  const [rejectionReason, setRejectionReason] = useState('');

  const chatEndRef = useRef<HTMLDivElement>(null);

  const isUltra = userPlan === 'ultra';
  const isElite = isUltra;
  const isPro = userPlan === 'pro';

  // Industrial Grade Limits
  const FREE_LIMIT = 3;
  const PRO_LIMIT = 50;
  const ULTRA_LIMIT = 1500;

  const currentLimit = isUltra ? ULTRA_LIMIT : isPro ? PRO_LIMIT : FREE_LIMIT;
  const isLocked = insightUsage >= currentLimit;

  // Logic Variables for UI (Raw Math)
  const burnoutData = useMemo(() => {
    const expenseMap = new Map<string, number>();
    transactions
        .filter(t => t.type === TransactionType.EXPENSE)
        .forEach(t => {
            expenseMap.set(t.category, (expenseMap.get(t.category) || 0) + t.amount);
        });

    let maxCat = '';
    let maxAmount = 0;
    expenseMap.forEach((val, key) => {
        if (val > maxAmount) {
            maxAmount = val;
            maxCat = key;
        }
    });
    return { category: maxCat, amount: maxAmount };
  }, [transactions]);

  const leakageData = useMemo(() => {
    const expenses = transactions.filter(t => t.type === TransactionType.EXPENSE);
    const totalExpense = expenses.reduce((acc, t) => acc + t.amount, 0);

    // Group by Category
    const catMap: Record<string, number> = {};
    expenses.forEach(t => {
        catMap[t.category] = (catMap[t.category] || 0) + t.amount;
    });

    const sortedCats = Object.entries(catMap).sort((a, b) => b[1] - a[1]);
    const topLeak = sortedCats[0] || ['None', 0];

    // "Impulse" or Discretionary - rough heuristic
    const discretionaryCats = [Category.SHOPPING, Category.ENTERTAINMENT, Category.FOOD, Category.SUBSCRIPTION];
    const discretionaryTotal = expenses
        .filter(t => discretionaryCats.includes(t.category))
        .reduce((acc, t) => acc + t.amount, 0);

    return {
        topCategory: topLeak[0],
        topAmount: topLeak[1],
        discretionaryTotal,
        totalExpense
    };
  }, [transactions]);

  // Manual Trigger Logic - Removed useEffect for auto-run
  const runAnalysis = async () => {
    if (isLocked) return;
    setLoading(true);
    setError(null);
    onIncrementUsage();
    try {
      const result = await analyzeFinancialData(transactions, userPlan);

      // Filter out recent rejections (7-day cooldown)
      if (result && result.goal_proposals) {
          const rejectedRaw = localStorage.getItem('nova_rejected_proposals');
          const rejectedList: {id: string, type: string, timestamp: number}[] = rejectedRaw ? JSON.parse(rejectedRaw) : [];
          const sevenDaysMs = 7 * 24 * 60 * 60 * 1000;

          result.goal_proposals = result.goal_proposals.filter(p => {
              const rejection = rejectedList.find(r => r.id === p.id || (r.type === p.type && p.title.includes(r.id))); // Heuristic matching
              if (!rejection) return true;
              return (Date.now() - rejection.timestamp) > sevenDaysMs;
          });
      }

      if (result) {
        setAnalysis(result);
      } else {
        setError("Coach is analyzing other portfolios. Try again.");
      }
    } catch (e) {
      setError("Unable to connect to financial brain.");
    } finally {
      setLoading(false);
    }
  };

  const handleAcceptProposal = (proposal: GoalProposal) => {
      if (proposal.type === 'goal' && onAddGoal) {
          onAddGoal({
              id: Date.now().toString(),
              name: proposal.title,
              targetAmount: proposal.target_amount,
              currentAmount: 0,
              deadline: proposal.deadline || new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
              icon: 'star',
              color: 'from-emerald-500 to-teal-500'
          });
      } else if (proposal.type === 'budget' && onApplyBudgets) {
          onApplyBudgets([{
              id: `ai_${Date.now()}`,
              category: (proposal.category as Category) || Category.OTHER,
              limit: proposal.target_amount,
              startDate: new Date().toISOString() // Set cooldown start date
          }]);
      }

      // Remove from view
      if (analysis) {
          setAnalysis({
              ...analysis,
              goal_proposals: analysis.goal_proposals.filter(p => p.id !== proposal.id)
          });
      }
  };

  const handleRejectProposal = () => {
      if (!showRejectModal) return;

      const rejectedRaw = localStorage.getItem('nova_rejected_proposals');
      const rejectedList = rejectedRaw ? JSON.parse(rejectedRaw) : [];
      rejectedList.push({
          id: showRejectModal.id, // Or a simplified ID to track category/type
          type: showRejectModal.type,
          title: showRejectModal.title, // Use title for loose matching on re-proposal
          timestamp: Date.now(),
          reason: rejectionReason
      });
      localStorage.setItem('nova_rejected_proposals', JSON.stringify(rejectedList));

      // Remove from view
      if (analysis) {
          setAnalysis({
              ...analysis,
              goal_proposals: analysis.goal_proposals.filter(p => p.id !== showRejectModal.id)
          });
      }

      setShowRejectModal(null);
      setRejectionReason('');
  };

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [chatHistory, chatLoading]);

  useEffect(() => {
      if (!isLocked && initialPrompt && !chatLoading) {
          handleSendMessage(null, initialPrompt);
          if (onPromptHandled) onPromptHandled();
      }
  }, [initialPrompt, isLocked]);

  const handleSendMessage = async (e: React.FormEvent | null, promptOverride?: string) => {
    if (e) e.preventDefault();
    const content = promptOverride || chatInput;
    if (!content.trim() || isLocked) return;

    onIncrementUsage();
    const userMsg: ChatMessage = { id: Date.now().toString(), role: 'user', content: content, timestamp: new Date() };
    setChatHistory(prev => [...prev, userMsg]);
    setChatInput('');
    setChatLoading(true);

    // Build Financial Snapshot (Client-Side Logic)
    const now = new Date();
    const currentMonthTxs = transactions.filter(t => new Date(t.date).getMonth() === now.getMonth());
    const income = currentMonthTxs.filter(t => t.type === TransactionType.INCOME).reduce((sum, t) => sum + t.amount, 0);
    const expense = currentMonthTxs.filter(t => t.type === TransactionType.EXPENSE).reduce((sum, t) => sum + t.amount, 0);

    // Calculate top category
    const catMap: Record<string, number> = {};
    currentMonthTxs.filter(t => t.type === TransactionType.EXPENSE).forEach(t => { catMap[t.category] = (catMap[t.category] || 0) + t.amount; });
    const topCat = Object.entries(catMap).sort((a,b) => b[1] - a[1])[0];

    const snapshot: FinancialSnapshot = {
        currentMonthMetrics: {
            income,
            expense,
            savingsRate: income > 0 ? (income - expense) / income : 0,
            topExpenseCategory: topCat ? topCat[0] : 'None'
        },
        recentTransactions: transactions.slice(0, 10), // Context-Aware Agent (Limited to 10)
        activeGoals: goals,
        budgets: budgets
    };

    const response = await chatWithFinancialCoach(userMsg.content, chatHistory, snapshot, botMode);

    const aiMsg: ChatMessage = { 
        id: (Date.now() + 1).toString(), 
        role: 'assistant', 
        content: response.message, 
        timestamp: new Date(),
        sentiment: response.sentiment as any,
        suggestedActions: response.suggestedActions
    };

    setChatHistory(prev => [...prev, aiMsg]);
    setChatLoading(false);
  };

  const handleActionClick = (action: SuggestedAction) => {
      if (action.actionId.startsWith('navigate_')) {
          const tab = action.actionId.replace('navigate_', '');
          onNavigate(tab);
      } else {
          // Assume it's a chat prompt or generic ID
          handleSendMessage(null, action.payload || action.label);
      }
  };

  const handleAutoTune = () => {
      if (!analysis || !onApplyBudgets) return;
      // Filter out budgets that already exist (safety check, though filtered below in render)
      const existingCats = new Set(budgets.map(b => b.category));
      const newBudgets: Budget[] = analysis.budget_suggestions
          .filter(bs => !existingCats.has(bs.category as Category))
          .map(bs => ({
              id: `ai_${Date.now()}_${bs.category}`,
              category: bs.category as any,
              limit: bs.suggested_limit,
              startDate: new Date().toISOString() // Set cooldown start date
          }));
      onApplyBudgets(newBudgets);
  };

  const getColorClass = (type: string) => {
    switch (type) {
        case 'success': return 'bg-emerald-500/10 border-emerald-500/20 text-emerald-100 shadow-[0_4px_20px_rgba(16,185,129,0.1)]';
        case 'warning': return 'bg-amber-500/10 border-amber-500/20 text-amber-100 shadow-[0_4px_20px_rgba(245,158,11,0.1)]';
        case 'critical': return 'bg-rose-500/10 border-rose-500/20 text-rose-100 shadow-[0_4px_20px_rgba(244,63,94,0.1)]';
        default: return 'bg-blue-500/10 border-blue-500/20 text-blue-100 shadow-[0_4px_20px_rgba(59,130,246,0.1)]';
    }
  };

  const getIconForType = (type: string) => {
      switch (type) {
        case 'success': return <CheckCircle className="w-5 h-5 text-emerald-400" />;
        case 'warning': return <AlertTriangle className="w-5 h-5 text-amber-400" />;
        case 'critical': return <ShieldAlert className="w-5 h-5 text-rose-400" />;
        default: return <Info className="w-5 h-5 text-blue-400" />;
      }
    };

  const getChatBubbleStyle = (role: string, sentiment?: string) => {
      if (role === 'user') return 'bg-indigo-600 text-white border-indigo-500/50';

      switch (sentiment) {
          case 'critical': return 'bg-rose-950/40 border-rose-500/30 text-rose-100 shadow-[0_0_15px_rgba(244,63,94,0.2)]';
          case 'warning': return 'bg-amber-950/40 border-amber-500/30 text-amber-100 shadow-[0_0_15px_rgba(245,158,11,0.2)]';
          case 'success': return 'bg-emerald-950/40 border-emerald-500/30 text-emerald-100 shadow-[0_0_15px_rgba(16,185,129,0.2)]';
          default: return 'bg-slate-800/80 border-white/10 text-slate-200';
      }
  };

  // Filter out budget suggestions that already exist
  const filteredBudgetSuggestions = useMemo(() => {
      if (!analysis?.budget_suggestions) return [];
      const existingCategories = new Set(budgets.map(b => b.category));
      return analysis.budget_suggestions.filter(bs => !existingCategories.has(bs.category as Category));
  }, [analysis, budgets]);

  // Filter out goal proposals that already exist
  const filteredGoalProposals = useMemo(() => {
      if (!analysis?.goal_proposals) return [];
      const existingGoalNames = new Set(goals.map(g => g.name.toLowerCase()));
      const existingBudgetCats = new Set(budgets.map(b => b.category));

      return analysis.goal_proposals.filter(p => {
          if (p.type === 'goal') {
              return !existingGoalNames.has(p.title.toLowerCase());
          } else if (p.type === 'budget') {
              return !existingBudgetCats.has(p.category as Category);
          }
          return true;
      });
  }, [analysis, goals, budgets]);

  return (
    <div className="relative h-[calc(100vh-8rem)]">
      {isLocked && (
        <div className="absolute inset-0 z-50 flex items-center justify-center bg-slate-950/60 backdrop-blur-xl rounded-[2rem] border border-white/10 transform scale-105 transition-transform duration-500">
            <div className="text-center p-8 max-w-md animate-slide-up">
                <div className="w-20 h-20 rounded-3xl bg-gradient-to-tr from-indigo-500 to-purple-500 flex items-center justify-center mx-auto mb-6 shadow-2xl shadow-indigo-500/40"><Lock className="w-10 h-10 text-white" /></div>
                <h2 className="text-3xl font-bold text-white mb-3">Limit Reached</h2>
                <p className="text-slate-400 mb-8 leading-relaxed">
                    You've hit your monthly cap of {currentLimit} interactions for your {userPlan.toUpperCase()} plan. Upgrade or manage your plan to continue using the AI Coach.
                </p>
                {!isUltra && (
                    <button onClick={onUpgradeClick} className="w-full py-4 bg-white text-indigo-900 font-bold rounded-xl shadow-xl hover:scale-[1.02] active:scale-95 transition-all flex items-center justify-center gap-2 group"><Sparkles className="w-5 h-5 text-indigo-600 group-hover:rotate-12 transition-transform" />Upgrade Plan</button>
                )}
            </div>
        </div>
      )}

      <div className={`grid grid-cols-1 lg:grid-cols-3 gap-8 pb-10 h-full transition-all duration-500 ${isLocked ? 'blur-md opacity-50 pointer-events-none select-none overflow-hidden' : ''}`}>
        <div className="lg:col-span-2 overflow-y-auto custom-scrollbar space-y-8 pr-2">

            {/* Manual Trigger Header */}
            <div className="bg-gradient-to-r from-slate-900 via-slate-900/80 to-indigo-900/20 p-8 rounded-[2.5rem] border border-white/10 shadow-2xl relative overflow-hidden group">
                <div className="flex justify-between items-start relative z-10">
                    <div>
                        <h2 className="text-2xl font-black text-white flex items-center gap-3"><BrainCircuit className="w-8 h-8 text-indigo-400" />Command Center</h2>
                        <p className="text-slate-400 text-sm mt-2 max-w-md font-medium">Initiate deep neural scans or query the agent directly.</p>
                        <div className={`mt-4 inline-flex items-center gap-2 px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest border ${isUltra ? 'bg-indigo-500/10 border-indigo-500/20 text-indigo-400' : isPro ? 'bg-amber-500/10 border-amber-500/20 text-amber-400' : 'bg-slate-700/50 border-white/10 text-slate-400'}`}>
                            {isUltra ? <Crown className="w-3 h-3" /> : isPro ? <Zap className="w-3 h-3" /> : null}
                            Tokens: {insightUsage}/{currentLimit}
                        </div>
                    </div>
                    <button 
                        onClick={runAnalysis} 
                        disabled={loading} 
                        className="flex flex-col items-center justify-center w-24 h-24 bg-slate-800 hover:bg-indigo-600 rounded-3xl border border-white/10 transition-all group shadow-xl active:scale-95"
                    >
                        <RefreshCcw className={`w-8 h-8 text-slate-300 group-hover:text-white mb-2 transition-colors ${loading ? 'animate-spin' : ''}`} />
                        <span className="text-[9px] font-black text-slate-400 group-hover:text-white uppercase tracking-widest">Scan</span>
                    </button>
                </div>
            </div>

            {loading && (
                <div className="flex flex-col items-center justify-center py-20 space-y-4">
                    <Activity className="w-12 h-12 text-indigo-500 animate-bounce" />
                    <p className="text-slate-400 text-xs font-bold uppercase tracking-widest animate-pulse">Running Neural Audit...</p>
                </div>
            )}

            {analysis && !loading && (
            <div className="animate-fade-in space-y-8">
                {/* 1. Risk & Forecast */}
                <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                    <div className="glass-card p-6 rounded-3xl relative overflow-hidden group border-indigo-500/10 hover:border-indigo-500/30 transition-all hover:shadow-[0_0_40px_rgba(79,70,229,0.15)]">
                        <h3 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-4">Risk Matrix</h3>
                        <div className="flex items-center gap-4">
                            <div className="relative w-16 h-16 flex items-center justify-center shrink-0">
                                <svg className="w-full h-full transform -rotate-90 filter drop-shadow-md" viewBox="0 0 64 64">
                                    <circle cx="32" cy="32" r="28" stroke="currentColor" strokeWidth="6" fill="transparent" className="text-slate-800/50" />
                                    <circle cx="32" cy="32" r="28" stroke="currentColor" strokeWidth="6" fill="transparent" className={`${analysis.risk_score > 50 ? 'text-rose-500' : 'text-emerald-500'} transition-all duration-1000 ease-out`} strokeDasharray={175.9} strokeDashoffset={175.9 - (175.9 * analysis.risk_score) / 100} strokeLinecap="round" />
                                </svg>
                                <span className="absolute text-lg font-bold text-white tracking-tighter">{Math.round(analysis.risk_score)}</span>
                            </div>
                            <div className="flex-1 min-w-0">
                                <h4 className={`text-lg font-bold ${analysis.risk_score > 50 ? 'text-rose-400' : 'text-emerald-400'} mb-1`}>{analysis.risk_score > 50 ? 'Critical' : 'Stable'}</h4>
                                <p className="text-[10px] text-slate-400 font-medium">System Health</p>
                            </div>
                        </div>
                    </div>

                    <div className="glass-card p-6 rounded-3xl relative overflow-hidden border-indigo-500/10 hover:border-indigo-500/30 transition-all group">
                         <h3 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-4">Trajectory (30d)</h3>
                         <div className="text-3xl font-bold text-white tracking-tight">{formatCurrency(analysis.predicted_spend_next_month).toString().replace(/\.00$/, '')}</div>
                         <p className="text-[10px] text-slate-500 mt-2 font-medium flex items-center gap-1.5"><TrendingUp className="w-3 h-3 text-indigo-400" /> Forecasted Burn</p>
                    </div>

                    <div className="glass-card p-6 rounded-3xl relative overflow-hidden border-rose-500/10 hover:border-rose-500/30 transition-all group bg-rose-500/5">
                        <div className="absolute top-0 right-0 w-32 h-32 bg-rose-500/10 rounded-full blur-2xl -mr-8 -mt-8 pointer-events-none"></div>
                        <h3 className="text-[10px] font-bold text-rose-300 uppercase tracking-widest mb-4 flex items-center gap-1.5"><Flame className="w-3 h-3 text-rose-500" /> Burnout Alert</h3>
                        <div className="text-xl font-bold text-white tracking-tight truncate">{burnoutData.category || 'N/A'}</div>
                        <p className="text-[10px] text-slate-400 mt-1 font-medium">{formatCurrency(burnoutData.amount)} consumed</p>
                    </div>
                </div>

                {/* 2. Strategic Insights List */}
                <div>
                    <h3 className="text-lg font-bold text-white mb-5 px-1 flex items-center gap-2"><Lightbulb className="w-5 h-5 text-amber-400" />Strategic Insights</h3>
                    <div className="grid grid-cols-1 gap-4">
                        {analysis.insights.map((insight, idx) => (
                            <div key={idx} className={`p-6 rounded-2xl border flex gap-5 backdrop-blur-md transition-all hover:translate-x-1 hover:shadow-lg ${getColorClass(insight.type)}`}>
                                <div className="mt-0.5 shrink-0 bg-white/10 p-2.5 rounded-xl h-fit ring-1 ring-white/10 shadow-sm">{getIconForType(insight.type)}</div>
                                <div>
                                    <h4 className="font-bold text-base mb-1.5">{insight.title}</h4>
                                    <p className="text-sm opacity-90 leading-relaxed font-medium">{insight.description}</p>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>

                {/* 3. CAPITAL LEAKAGE ANALYSIS */}
                <div className="glass-card p-8 rounded-[2.5rem] border border-white/5 relative overflow-hidden">
                    <div className="absolute top-0 right-0 w-64 h-64 bg-rose-500/5 rounded-full blur-[80px] -mr-16 -mt-16 pointer-events-none"></div>
                    <h3 className="text-lg font-bold text-white mb-6 px-1 flex items-center gap-2">
                        <TrendingDown className="w-5 h-5 text-rose-400" />
                        Capital Leakage Detectors
                    </h3>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6 relative z-10">
                        <div className="bg-slate-900/50 p-5 rounded-2xl border border-white/5 flex items-center gap-4">
                            <div className="w-12 h-12 rounded-xl bg-rose-500/10 flex items-center justify-center shrink-0">
                                <AlertTriangle className="w-6 h-6 text-rose-400" />
                            </div>
                            <div>
                                <p className="text-[10px] text-slate-500 font-black uppercase tracking-widest mb-1">Primary Drain</p>
                                <div className="text-white font-bold text-lg">{leakageData.topCategory}</div>
                                <div className="text-rose-400 text-xs font-medium">{formatCurrency(leakageData.topAmount)} consumed</div>
                            </div>
                        </div>

                        <div className="bg-slate-900/50 p-5 rounded-2xl border border-white/5 flex items-center gap-4">
                            <div className="w-12 h-12 rounded-xl bg-amber-500/10 flex items-center justify-center shrink-0">
                                <ShoppingCart className="w-6 h-6 text-amber-400" />
                            </div>
                            <div>
                                <p className="text-[10px] text-slate-500 font-black uppercase tracking-widest mb-1">Discretionary Burn</p>
                                <div className="text-white font-bold text-lg">{formatCurrency(leakageData.discretionaryTotal)}</div>
                                <div className="text-amber-400 text-xs font-medium">{((leakageData.discretionaryTotal / (leakageData.totalExpense || 1)) * 100).toFixed(1)}% of total outflow</div>
                            </div>
                        </div>
                    </div>

                    <div className="mt-6 p-4 rounded-xl bg-indigo-500/5 border border-indigo-500/10 flex gap-3 items-start">
                        <Info className="w-4 h-4 text-indigo-400 mt-0.5 shrink-0" />
                        <p className="text-xs text-indigo-200/80 leading-relaxed">
                            <span className="font-bold text-indigo-300">Analysis:</span> Your spending pattern indicates a heavy skew towards {leakageData.topCategory}. 
                            Reducing this vector by 10% would reclaim {formatCurrency(leakageData.topAmount * 0.1)} monthly.
                        </p>
                    </div>
                </div>

                {/* 4. Optimization Opportunities */}
                {filteredBudgetSuggestions.length > 0 && (
                    <div>
                        <div className="flex items-center justify-between mb-5 px-1">
                            <h3 className="text-lg font-bold text-white flex items-center gap-2"><TrendingUp className="w-5 h-5 text-indigo-400" />Optimization Opportunities</h3>
                            {onApplyBudgets && (
                                <button onClick={handleAutoTune} className="text-xs font-bold text-indigo-300 bg-indigo-500/20 hover:bg-indigo-500/30 border border-indigo-500/30 px-3 py-1.5 rounded-lg transition-all flex items-center gap-1.5 active:scale-95"><Sparkles className="w-3 h-3" /> Auto-Tune Limits</button>
                            )}
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
                            {filteredBudgetSuggestions.map((budget, idx) => (
                                <div key={idx} className="bg-slate-900/40 p-6 rounded-3xl border border-white/5 hover:border-indigo-500/30 transition-all hover:shadow-[0_4px_25px_rgba(99,102,241,0.15)] group relative overflow-hidden">
                                    <div className="flex justify-between mb-4 relative z-10">
                                        <span className="text-xs font-bold text-indigo-200 bg-indigo-500/20 px-3 py-1 rounded-lg uppercase tracking-wide border border-indigo-500/20">{budget.category}</span>
                                        <span className="text-xs text-rose-300 font-bold bg-rose-500/20 px-3 py-1 rounded-lg border border-rose-500/20">{formatCurrency(Math.max(0, budget.current_spend - budget.suggested_limit))} cut needed</span>
                                    </div>
                                    <p className="text-slate-300 text-sm mb-6 line-clamp-2 font-medium relative z-10">"{budget.reason}"</p>
                                    <div className="space-y-2 relative z-10">
                                        <div className="flex justify-between text-[10px] text-slate-400 font-bold uppercase tracking-wider"><span>Target Limit</span><span>Current</span></div>
                                        <div className="w-full bg-slate-800 h-2.5 rounded-full overflow-hidden flex border border-white/5">
                                            <div className="bg-indigo-500 h-full shadow-[0_0_15px_#6366f1]" style={{ width: `${Math.min(100, (budget.suggested_limit / budget.current_spend) * 100)}%` }}></div>
                                            <div className="bg-rose-500 h-full flex-1 opacity-80 striped-bg"></div>
                                        </div>
                                        <div className="flex justify-between text-sm font-bold text-white mt-1.5"><span>{formatCurrency(budget.suggested_limit)}</span><span>{formatCurrency(budget.current_spend)}</span></div>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                )}

                {/* 5. Strategic Proposal */}
                {filteredGoalProposals.length > 0 && (
                    <div className="space-y-4">
