                        <button type="submit" className="w-full py-4 bg-indigo-600 hover:bg-indigo-500 text-white font-black text-sm uppercase tracking-[0.2em] rounded-xl shadow-lg active:scale-95 transition-all">Synchronize Entry</button>
                    </form>
                </div>
            </div>
