                                        <div>
                                            <h4 className="text-lg font-bold text-white tracking-tight">{proposal.title}</h4>
                                            <p className="text-xs text-indigo-300 font-bold uppercase tracking-wider">{proposal.type === 'goal' ? 'Savings Target' : 'Budget Correction'}</p>
                                        </div>
                                    </div>
                                    <div className="text-right">
                                        <div className="text-2xl font-black text-white">{formatCurrency(proposal.target_amount)}</div>
