                                                    <p className="text-xs font-bold text-slate-400 mb-2">Detailed Math & Impact Analysis Locked</p>
                                                    <button onClick={onUpgradeClick} className="text-[10px] font-black text-indigo-400 uppercase tracking-widest hover:text-indigo-300">Upgrade to Elite</button>
                                                </div>
                                                <div className="blur-sm opacity-50">
                                                    <h5 className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-2">Projected Impact</h5>
                                                    <p className="text-sm font-medium text-slate-300">Lorem ipsum math calculation deficit reduction by 32% if applied...</p>
                                                </div>
                                            </>
                                        ) : (
                                            <>
                                                <h5 className="text-[10px] font-black text-indigo-400/80 uppercase tracking-widest mb-2">Elite Scenario Impact</h5>
                                                {proposal.reason_math && <p className="text-xs font-mono text-slate-400 mb-2">{proposal.reason_math}</p>}
                                                <p className="text-xs font-bold text-white border-l-2 border-indigo-500 pl-3 italic">"{proposal.scenario_impact}"</p>
                                            </>
                                        )}
                                    </div>
                                </div>

                                <div className="mt-6 flex gap-3 relative z-10">
                                    <button 
                                        onClick={() => setShowRejectModal(proposal)}
                                        className="flex-1 py-3 bg-slate-900/50 hover:bg-slate-800 text-slate-400 font-bold text-xs uppercase tracking-widest rounded-xl border border-white/10 transition-all"
                                    >
                                        Reject
                                    </button>
                                    <button 
                                        onClick={() => handleAcceptProposal(proposal)}
                                        className="flex-[2] py-3 bg-indigo-600 hover:bg-indigo-500 text-white font-bold text-xs uppercase tracking-widest rounded-xl shadow-lg transition-all flex items-center justify-center gap-2"
                                    >
                                        <Check className="w-4 h-4" /> Accept & Deploy
                                    </button>
                                </div>
                            </div>
                        ))}
                    </div>
                )}
            </div>
            )}
        </div>

        <div className="glass-card rounded-[2rem] border border-white/10 flex flex-col h-full overflow-hidden shadow-2xl relative">
            <div className="p-5 border-b border-white/5 bg-slate-950/40 backdrop-blur-xl z-10 flex items-center justify-between">
                <div className="flex items-center gap-3">
                    <div className={`w-10 h-10 rounded-2xl flex items-center justify-center shadow-lg ring-1 ring-white/20 ${botMode === 'ruthless' ? 'bg-slate-800' : 'bg-gradient-to-tr from-indigo-500 via-purple-500 to-pink-500'}`}>
                        {botMode === 'ruthless' ? <Terminal className="w-5 h-5 text-slate-300" /> : <Bot className="w-6 h-6 text-white" />}
                    </div>
                    <div>
                        <h3 className="font-bold text-white text-sm tracking-tight">Agent Uplink</h3>
                        <div className="flex items-center gap-1.5">
                            <div className={`w-1.5 h-1.5 rounded-full ${botMode === 'ruthless' ? 'bg-amber-500' : 'bg-emerald-500'}`}></div>
                            <p className="text-[10px] text-slate-400 font-bold uppercase tracking-wide">{botMode === 'ruthless' ? 'Ruthless Mode' : 'Supportive Mode'}</p>
                        </div>
                    </div>
                </div>
            </div>

            <div className="flex-1 overflow-y-auto p-5 space-y-6 custom-scrollbar bg-slate-950/20">
                {chatHistory.map((msg) => (
                    <div key={msg.id} className={`flex gap-3 ${msg.role === 'user' ? 'flex-row-reverse' : 'flex-row'} animate-slide-up`}>
                        <div className={`w-8 h-8 rounded-full flex items-center justify-center shrink-0 border border-white/10 shadow-sm ${msg.role === 'user' ? 'bg-slate-800' : botMode === 'ruthless' ? 'bg-slate-700' : 'bg-gradient-to-tr from-indigo-500 to-purple-500'}`}>
                            {msg.role === 'user' ? <User className="w-4 h-4 text-slate-300" /> : <Bot className="w-4 h-4 text-white" />}
                        </div>
                        <div className="flex flex-col gap-2 max-w-[85%]">
                            <div className={`p-4 text-sm leading-relaxed shadow-md border rounded-[1.2rem] ${msg.role === 'user' ? 'rounded-tr-sm' : 'rounded-tl-sm'} ${getChatBubbleStyle(msg.role, msg.sentiment)}`}>
                                {msg.content}
                            </div>
                            {/* Render Action Chips */}
                            {msg.suggestedActions && msg.suggestedActions.length > 0 && (
                                <div className="flex flex-wrap gap-2 mt-1">
                                    {msg.suggestedActions.map((action, idx) => (
                                        <button 
                                            key={idx}
                                            onClick={() => handleActionClick(action)}
                                            className="flex items-center gap-1.5 px-3 py-1.5 bg-indigo-500/10 hover:bg-indigo-500/20 border border-indigo-500/20 text-indigo-300 rounded-lg text-[10px] font-bold uppercase tracking-wide transition-all active:scale-95 hover:border-indigo-500/40"
                                        >
                                            {action.actionId.startsWith('navigate_') ? <ChevronRight className="w-3 h-3" /> : <MousePointerClick className="w-3 h-3" />}
                                            {action.label}
                                        </button>
                                    ))}
                                </div>
                            )}
                            <p className={`text-[9px] font-medium opacity-50 ${msg.role === 'user' ? 'text-right' : 'text-left'}`}>
                                {msg.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                            </p>
                        </div>
                    </div>
                ))}
                {chatLoading && (
                    <div className="flex justify-start gap-3 animate-fade-in">
                        <div className="w-8 h-8 rounded-full bg-slate-800 flex items-center justify-center shrink-0 border border-white/10"><Bot className="w-4 h-4 text-white" /></div>
                        <div className="bg-slate-800/80 px-5 py-4 rounded-[1.2rem] rounded-tl-sm flex gap-1.5 items-center border border-white/5 shadow-sm"><div className="w-1.5 h-1.5 bg-slate-400 rounded-full animate-bounce"></div><div className="w-1.5 h-1.5 bg-slate-400 rounded-full animate-bounce delay-100"></div><div className="w-1.5 h-1.5 bg-slate-400 rounded-full animate-bounce delay-200"></div></div>
                    </div>
                )}
                <div ref={chatEndRef} />
            </div>

            <div className="p-5 border-t border-white/5 bg-slate-900/60 backdrop-blur-md">
                <form onSubmit={(e) => handleSendMessage(e)} className="relative group">
                    <input type="text" value={chatInput} onChange={(e) => setChatInput(e.target.value)} placeholder="Type command..." className="w-full bg-slate-950/80 border border-white/10 text-white text-sm rounded-2xl pl-5 pr-14 py-4 focus:outline-none focus:border-indigo-500/50 focus:bg-slate-950 transition-all placeholder:text-slate-500 shadow-inner font-medium" />
                    <button type="submit" disabled={!chatInput.trim() || chatLoading} className="absolute right-2 top-1/2 -translate-y-1/2 p-2.5 bg-indigo-600 hover:bg-indigo-500 rounded-xl text-white transition-all disabled:opacity-50 disabled:cursor-not-allowed shadow-lg active:scale-95"><Send className="w-4 h-4" /></button>
                </form>
            </div>
        </div>
      </div>

      {showRejectModal && (
          <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/90 backdrop-blur-md animate-fade-in">
              <div className="bg-[#0f172a] border border-white/10 rounded-3xl w-full max-w-sm p-6 shadow-2xl relative animate-slide-up">
                  <h3 className="text-lg font-bold text-white mb-2">Decline Proposal</h3>
                  <p className="text-sm text-slate-400 mb-4">Why are you rejecting this? The AI will learn from your feedback.</p>
                  <textarea 
                    value={rejectionReason}
                    onChange={(e) => setRejectionReason(e.target.value)}
                    className="w-full h-24 bg-slate-900 border border-white/10 rounded-xl p-3 text-white text-sm focus:border-indigo-500 outline-none resize-none mb-4"
                    placeholder="e.g. Too aggressive, prefer different timeline..."
                  />
                  <div className="flex gap-3">
                      <button onClick={() => setShowRejectModal(null)} className="flex-1 py-3 bg-slate-800 text-slate-300 font-bold rounded-xl text-xs uppercase tracking-widest">Cancel</button>
                      <button onClick={handleRejectProposal} className="flex-1 py-3 bg-white text-slate-900 font-bold rounded-xl text-xs uppercase tracking-widest hover:bg-indigo-50">Confirm</button>
                  </div>
              </div>
          </div>
      )}
    </div>
  );
};

export default Insights;

