  onNavigateToAccounts?: () => void;
  userPlan?: UserPlan;
  scanUsage?: number;
  onIncrementScan?: () => void;
  currency?: Currency;
}

const Transactions: React.FC<TransactionsProps> = ({ transactions, accounts = [], onDelete, onAdd, formatCurrency, onNavigateToAccounts, userPlan = 'free', scanUsage = 0, onIncrementScan, currency = 'USD' }) => {
