          {filtered.map(t => (
            <div 
                key={t.id} 
                className="group glass-card rounded-2xl p-4 md:px-6 md:py-4 flex flex-col md:grid md:grid-cols-12 items-center gap-4 transition-all duration-300 hover:bg-slate-800/40 hover:border-indigo-500/20"
            >
