let lastCallTime = 0;
const MIN_INTERVAL_MS = 1500; // Efficient throttle

// --- CONFIGURATION ---
const PRIMARY_API_KEY = process.env.API_KEY; // Paid Google Key (Elite)
export const SECONDARY_API_KEY = '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'; // OpenRouter Key (Free/Pro)

// OpenRouter Configuration
const OPENROUTER_URL = "https://openrouter.ai/api/v1/chat/completions";
// Using the Free tier model to strictly avoid API burn
const OPENROUTER_MODEL = "google/gemini-2.0-flash-lite-preview-02-05:free"; 

const checkRateLimit = () => {
  const now = Date.now();
  if (now - lastCallTime < MIN_INTERVAL_MS) {
    throw new Error("Cooling down. Please wait a moment.");
  }
  lastCallTime = now;
