const cleanJsonResponse = (text: string) => {
  return text.replace(/```json/g, '').replace(/```/g, '').trim();
};

/**
 * OpenRouter Fetch Implementation (Frontend Only)
 * Used for Free/Pro users to offload cost.
 */
async function callOpenRouter(
  systemInstruction: string,
  userPrompt: string,
  responseSchema?: any
): Promise<string> {
  const headers = {
    "Authorization": `Bearer ${SECONDARY_API_KEY}`,
    "Content-Type": "application/json",
    "HTTP-Referer": "https://nova-finance.app", 
    "X-Title": "Nova Finance",
  };

  // If schema is provided, append it to the system instruction 
  // (OpenRouter/OpenAI often prefer schema in prompt for reliability across different models)
  let finalSystemInstruction = systemInstruction;
  if (responseSchema) {
      finalSystemInstruction += `\n\nIMPORTANT: Respond with valid JSON strictly adhering to this schema:\n${JSON.stringify(responseSchema, null, 2)}`;
  }

  const body = {
    "model": OPENROUTER_MODEL,
    "messages": [
      { "role": "system", "content": finalSystemInstruction },
      { "role": "user", "content": userPrompt }
    ],
    "response_format": responseSchema ? { "type": "json_object" } : undefined
  };

  const response = await fetch(OPENROUTER_URL, {
    method: "POST",
    headers: headers,
    body: JSON.stringify(body)
  });

  if (!response.ok) {
    const err = await response.text();
    throw new Error(`OpenRouter Error ${response.status}: ${err}`);
  }

  const data = await response.json();
  return data.choices[0].message.content || "";
}

/**
 * Hybrid Execution Engine
 * 1. Elite Users -> Direct Google SDK (Fastest, Highest Limits)
 * 2. Free/Pro Users -> Try OpenRouter (Free Model) -> Fallback to Google SDK (Reliability)
 */
async function generateHybridContent(
  userPlan: UserPlan,
  systemInstruction: string,
  prompt: string,
  schema?: any
): Promise<string> {
  checkRateLimit();

  const isElite = userPlan === 'ultra';

  // Strategy 1: Elite Direct Access
  if (isElite) {
    const ai = new GoogleGenAI({ apiKey: PRIMARY_API_KEY });
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        systemInstruction: systemInstruction,
        responseMimeType: "application/json",
        responseSchema: schema
      }
    });
    return response.text || "";
  }

  // Strategy 2: Burn Avoidance (OpenRouter)
  try {
    const text = await callOpenRouter(systemInstruction, prompt, schema);
    return text;
  } catch (error) {
    console.warn("OpenRouter failed, engaging fallback thrusters (Google SDK).", error);

    // Strategy 3: Fallback to Google SDK
    const fallbackAi = new GoogleGenAI({ apiKey: PRIMARY_API_KEY });
    const response = await fallbackAi.models.generateContent({
      model: "gemini-3-flash-preview", // Use standard flash for fallback
      contents: prompt,
      config: {
        systemInstruction: systemInstruction,
        responseMimeType: "application/json",
        responseSchema: schema
      }
    });
    return response.text || "";
  }
}

