}

const QUOTES = [
  { text: "Do not save what is left after spending, but spend what is left after saving.", author: "Warren Buffett" },
  { text: "A budget is telling your money where to go instead of wondering where it went.", author: "Dave Ramsey" },
  { text: "It's not your salary that makes you rich, it's your spending habits.", author: "Charles A. Jaffe" },
];

const COLORS = ['#6366f1', '#f43f5e', '#f59e0b', '#10b981', '#8b5cf6', '#06b6d4', '#ec4899', '#64748b'];

const Dashboard: React.FC<DashboardProps> = ({ 
    accounts, 
    transactions, 
    goals, 
    budgets,
    onNavigate, 
    onAddAccount, 
    onAddTransaction, 
    onAddGoal, 
    formatCurrency, 
    userPlan, 
    onAskCoach, 
    isPinMode = false,
    pinnedIds = [],
    onTogglePin,
    trackEvent,
    insightUsage = 0,
    spendingStatus,
    currentPeriodSpend = 0,
    spendingLimit = 1000,
    spendingPeriod = 'monthly'
}) => {
  const hasData = accounts.length > 0 || transactions.length > 0;
  const randomQuote = useMemo(() => QUOTES[Math.floor(Math.random() * QUOTES.length)], []);
  const netWorth = useMemo(() => accounts.reduce((acc, curr) => acc + curr.balance, 0), [accounts]);

  const [showAnalysisConfirm, setShowAnalysisConfirm] = useState(false);

  const today = new Date();
  const currentMonth = today.getMonth();
  const currentYear = today.getFullYear();
  const currentDay = today.getDate();
  const daysInMonth = new Date(currentYear, currentMonth + 1, 0).getDate();

  const stats = useMemo(() => {
    const currentMTDExpenses = transactions.filter(t => {
      const d = new Date(t.date);
      return t.type === TransactionType.EXPENSE && d.getMonth() === currentMonth && d.getFullYear() === currentYear;
    });
    const currentMTDTotal = currentMTDExpenses.reduce((acc, t) => acc + t.amount, 0);

    const prevMonthDate = new Date(currentYear, currentMonth - 1, 1);
    const prevMonth = prevMonthDate.getMonth();
    const prevMonthYear = prevMonthDate.getFullYear();

    const prevMTDExpenses = transactions.filter(t => {
      const d = new Date(t.date);
      return t.type === TransactionType.EXPENSE && d.getMonth() === prevMonth && d.getFullYear() === prevMonthYear && d.getDate() <= currentDay;
    });
    const prevMTDTotal = prevMTDExpenses.reduce((acc, t) => acc + t.amount, 0);
    const spendChange = prevMTDTotal > 0 ? ((currentMTDTotal - prevMTDTotal) / prevMTDTotal) * 100 : 0;

    const mtdNetFlow = transactions
      .filter(t => {
        const d = new Date(t.date);
        return d.getMonth() === currentMonth && d.getFullYear() === currentYear;
      })
      .reduce((acc, t) => acc + (t.type === TransactionType.INCOME ? t.amount : -t.amount), 0);
    const monthStartNW = netWorth - mtdNetFlow;
    const nwChange = monthStartNW !== 0 ? (mtdNetFlow / Math.abs(monthStartNW)) * 100 : 0;

    const currentDailyAvg = currentMTDTotal / Math.max(currentDay, 1);
    const forecastedTotal = currentDailyAvg * daysInMonth;

    const prevMonthTotalExpenses = transactions.filter(t => {
      const d = new Date(t.date);
      return t.type === TransactionType.EXPENSE && d.getMonth() === prevMonth && d.getFullYear() === prevMonthYear;
    }).reduce((acc, t) => acc + t.amount, 0);

    const burnChange = spendChange;
    const forecastChange = prevMonthTotalExpenses > 0 ? ((forecastedTotal - prevMonthTotalExpenses) / prevMonthTotalExpenses) * 100 : 0;

    return { currentMTDTotal, spendChange, nwChange, currentDailyAvg, forecastedTotal, burnChange, forecastChange };
  }, [transactions, currentMonth, currentYear, currentDay, netWorth, daysInMonth]);

  const expenditureData = useMemo(() => {
    const expenses = transactions.filter(t => 
        t.type === TransactionType.EXPENSE && 
        new Date(t.date).getMonth() === currentMonth &&
        new Date(t.date).getFullYear() === currentYear
    );

    const total = expenses.reduce((acc, t) => acc + t.amount, 0);
    const catMap: Record<string, number> = {};

    expenses.forEach(t => {
        catMap[t.category] = (catMap[t.category] || 0) + t.amount;
    });

    const chartData = Object.entries(catMap)
        .map(([name, value]) => ({ name, value }))
        .sort((a, b) => b.value - a.value);

    const topCategories = chartData
        .slice(0, 4)
        .map((item) => ({ ...item, percent: total > 0 ? (item.value / total) * 100 : 0 }));

    return { chartData, topCategories, total };
  }, [transactions, currentMonth, currentYear]);

  const pinnableModules = useMemo(() => {
      // 1. Budget Monitor (Breaches)
      const overBudgetCount = budgets.filter(b => {
          const spent = transactions.filter(t => t.category === b.category && t.type === TransactionType.EXPENSE && new Date(t.date).getMonth() === currentMonth).reduce((acc, t) => acc + t.amount, 0);
          return spent > b.limit;
      }).length;

      // 2. Goal Vector Logic
      // Budget Utilization
      const budgetUtilization = spendingLimit > 0 ? (currentPeriodSpend / spendingLimit) * 100 : 0;

      // Goals Progress
      const totalGoalTarget = goals.reduce((acc, g) => acc + g.targetAmount, 0);
      const totalGoalCurrent = goals.reduce((acc, g) => acc + g.currentAmount, 0);
      const goalProgress = totalGoalTarget > 0 ? (totalGoalCurrent / totalGoalTarget) * 100 : 0;

      // Mix Budgets and Goals for the list view
      const mixedDetails = [
          ...budgets.map(b => {
              const spent = transactions.filter(t => t.category === b.category && t.type === TransactionType.EXPENSE && new Date(t.date).getMonth() === currentMonth).reduce((acc, t) => acc + t.amount, 0);
              return { 
                  id: b.id, 
                  name: b.category, 
                  limit: b.limit, 
                  current: spent, 
                  percent: b.limit > 0 ? (spent / b.limit) * 100 : 0, 
                  type: 'budget' as const 
              };
          }),
          ...goals.map(g => ({
              id: g.id, 
              name: g.name, 
              limit: g.targetAmount, 
              current: g.currentAmount, 
              percent: g.targetAmount > 0 ? (g.currentAmount / g.targetAmount) * 100 : 0, 
              type: 'goal' as const 
          }))
      ].sort((a, b) => b.percent - a.percent).slice(0, 5);

      // 3. System Alerts
      const alertsCount = overBudgetCount + (stats.spendChange > 10 ? 1 : 0);

      // 4. Token Logic
      const limit = userPlan === 'ultra' ? 1500 : userPlan === 'pro' ? 50 : 3;
      const remaining = Math.max(0, limit - (insightUsage || 0));

      return [
          {
              id: 'budget-monitor',
              title: 'Budget Integrity',
              icon: <PieChartIcon className="w-5 h-5 text-white" />,
              value: overBudgetCount > 0 ? `${overBudgetCount} Breaches` : 'Secure',
              subtext: overBudgetCount > 0 ? 'Immediate audit required' : 'All limits respected',
              color: overBudgetCount > 0 ? 'bg-rose-600' : 'bg-emerald-600',
              spotlight: overBudgetCount > 0 ? 'rgba(244, 63, 94, 0.4)' : 'rgba(16, 185, 129, 0.4)',
              onClick: () => onNavigate('goals')
          },
          {
              id: 'sandbox-link',
              title: 'Sim Sandbox',
              icon: <Microscope className="w-5 h-5 text-white" />,
              value: 'Predictive Core',
              subtext: 'Run ghost scenarios',
              color: 'bg-indigo-600',
              spotlight: 'rgba(99, 102, 241, 0.4)',
              onClick: () => onNavigate('sandbox')
          },
          {
              id: 'goal-tracker',
              title: 'Goal Vector',
              icon: <Target className="w-5 h-5 text-white" />,
              value: formatCurrency(totalGoalCurrent),
              subtext: `Total Saved across ${goals.length} targets`,
              color: 'bg-indigo-600', 
              spotlight: 'rgba(99, 102, 241, 0.4)', 
              budgetUtilization,
              goalProgress,
              details: mixedDetails, 
              span: 'md:col-start-3 md:row-span-2',
              onClick: () => onNavigate('goals')
          },
          {
              id: 'system-alerts',
              title: 'System Alerts',
              icon: <ShieldAlert className="w-5 h-5 text-white" />,
              value: alertsCount > 0 ? `${alertsCount} Active` : 'Nominal',
              subtext: alertsCount > 0 ? 'Review diagnostic' : 'Systems nominal',
              color: alertsCount > 0 ? 'bg-orange-600' : 'bg-slate-600',
              spotlight: alertsCount > 0 ? 'rgba(234, 88, 12, 0.4)' : 'rgba(148, 163, 184, 0.4)',
              onClick: () => setShowAnalysisConfirm(true)
          },
          {
              id: 'neural-quota',
              title: 'Neural Capacity',
              icon: <BrainCircuit className="w-5 h-5 text-white" />,
              value: `${remaining} Remaining`,
              subtext: `Monthly Cap: ${limit}`,
              color: remaining === 0 ? 'bg-rose-600' : remaining < 10 ? 'bg-amber-600' : 'bg-purple-600',
              spotlight: 'rgba(168, 85, 247, 0.4)',
              onClick: () => onNavigate('plans')
          }
      ];
  }, [budgets, goals, transactions, stats, insightUsage, onNavigate, userPlan, spendingLimit, currentPeriodSpend]);

  const handleCardMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
      const rect = e.currentTarget.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;
      e.currentTarget.style.setProperty('--mouse-x', `${x}px`);
      e.currentTarget.style.setProperty('--mouse-y', `${y}px`);
  };

  if (!hasData) return (
    <div className="flex flex-col items-center justify-center min-h-[70vh] text-center animate-fade-in relative px-6">
        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-96 h-96 bg-indigo-600/10 rounded-full blur-[100px] pointer-events-none"></div>
        <div className="w-20 h-20 bg-slate-900 border border-white/10 rounded-3xl flex items-center justify-center mb-8 rotate-6 shadow-2xl relative z-10"><Quote className="w-10 h-10 text-indigo-400" /></div>
        <h1 className="text-4xl font-black text-white mb-4 uppercase tracking-tighter italic relative z-10">Vault Initializing...</h1>
        <p className="text-slate-400 max-w-md italic mb-12 relative z-10">"{randomQuote.text}" — {randomQuote.author}</p>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6 w-full max-w-4xl relative z-10">
             <button onClick={onAddAccount} className="p-8 bg-slate-900/60 backdrop-blur-xl border border-white/5 rounded-[2.5rem] hover:border-indigo-500 transition-all text-left shadow-xl hover:-translate-y-1 group"><Landmark className="w-8 h-8 text-indigo-400 mb-6 group-hover:scale-110 transition-transform" /><h3 className="text-xl font-bold text-white mb-2">Sync Nodes</h3><p className="text-slate-500 text-sm">Link bank or manual ledgers.</p></button>
             <button onClick={onAddTransaction} className="p-8 bg-slate-900/60 backdrop-blur-xl border border-white/5 rounded-[2.5rem] hover:border-indigo-500 transition-all text-left shadow-xl hover:-translate-y-1 group"><PlusCircle className="w-8 h-8 text-indigo-400 mb-6 group-hover:scale-110 transition-transform" /><h3 className="text-xl font-bold text-white mb-2">Record Spend</h3><p className="text-slate-500 text-sm">Archive current activity.</p></button>
             <button onClick={onAddGoal} className="p-8 bg-slate-900/60 backdrop-blur-xl border border-white/5 rounded-[2.5rem] hover:border-indigo-500 transition-all text-left shadow-xl hover:-translate-y-1 group"><Target className="w-8 h-8 text-indigo-400 mb-6 group-hover:scale-110 transition-transform" /><h3 className="text-xl font-bold text-white mb-2">Set Objectives</h3><p className="text-slate-500 text-sm">Deploy capital milestones.</p></button>
        </div>
    </div>
  );

  return (
    <div className="space-y-6 pb-10 relative">
      <style>{`
        .spotlight-card { 
            position: relative; 
            overflow: hidden; 
            transition: transform 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94), box-shadow 0.3s ease;
            --mouse-x: -100px;
            --mouse-y: -100px;
            --spotlight-color: rgba(255, 255, 255, 0.1);
        }
        .spotlight-card::before { 
            content: ""; 
            position: absolute; 
            inset: 0; 
            background: radial-gradient(500px circle at var(--mouse-x) var(--mouse-y), var(--spotlight-color), transparent 40%); 
            z-index: 0; 
            pointer-events: none; 
            opacity: 0;
            transition: opacity 0.3s ease;
        }
        .spotlight-card:hover::before {
            opacity: 1;
        }
        .spotlight-card:hover {
            transform: translateY(-2px);
            box-shadow: 0 10px 40px -10px rgba(0,0,0,0.5);
        }
        .pin-mode-overlay {
            position: absolute; inset: -20px; background: rgba(2, 6, 23, 0.85); backdrop-filter: blur(4px); z-index: 50; border-radius: 2rem; pointer-events: none; opacity: 0; transition: opacity 0.3s;
        }
        .pin-active .pin-mode-overlay { opacity: 1; pointer-events: auto; }
        .pin-active .pinnable-item { z-index: 60; position: relative; transform: scale(1.02); box-shadow: 0 0 30px rgba(99, 102, 241, 0.3); border-color: rgba(99, 102, 241, 0.5); cursor: pointer; }
      `}</style>

      <div className={`transition-all duration-500 ${isPinMode ? 'pin-active' : ''}`}>

          <div className="flex justify-between items-center relative z-40 mb-6">
            <div>
              <h2 className="text-3xl font-black text-white tracking-tighter uppercase italic">Control Room</h2>
              {!isPinMode && <p className="text-slate-400 text-xs font-bold uppercase tracking-widest mt-1">Financial performance for {today.toLocaleDateString('en-US', { month: 'long', year: 'numeric' })}</p>}
            </div>
          </div>

          {/* SYSTEM MODULES (Pinnable Grid) */}
          <div className="relative group/pin-container">
              {isPinMode && <div className="pin-mode-overlay"></div>}

              <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8 relative auto-rows-fr">
                  {pinnableModules.map((mod) => {
                      const isPinned = pinnedIds.includes(mod.id);
                      const spanClass = mod.id === 'goal-tracker' ? mod.span : '';
                      const isGoalTracker = mod.id === 'goal-tracker';

                      return (
                          <div 
                            key={mod.id}
                            onMouseMove={handleCardMouseMove}
                            onClick={() => {
                                if (isPinMode && onTogglePin) {
                                    onTogglePin(mod.id);
                                } else if (!isPinMode) {
                                    trackEvent?.(mod.id);
                                    mod.onClick();
                                }
                            }}
                            style={{ '--spotlight-color': mod.spotlight } as React.CSSProperties}
                            className={`pinnable-item spotlight-card glass-card p-6 rounded-[2rem] border border-white/5 flex flex-col ${isGoalTracker ? 'justify-start gap-6' : 'justify-between gap-5'} cursor-pointer h-full ${spanClass} ${isPinMode ? 'hover:bg-slate-900' : ''}`}
                          >
                              <div className="flex items-start justify-between w-full relative z-10">
                                  <div className={`w-14 h-14 rounded-2xl flex items-center justify-center shadow-lg ${mod.color} shrink-0`}>{mod.icon}</div>
                                  {isPinMode && (
                                      <div className={`w-8 h-8 rounded-lg border-2 flex items-center justify-center transition-all ${isPinned ? 'bg-indigo-600 border-indigo-600' : 'border-white/20 bg-slate-950'}`}>
                                          {isPinned && <Check className="w-5 h-5 text-white" />}
                                      </div>
                                  )}
                              </div>

                              <div className={`flex-1 min-w-0 relative z-10 flex flex-col ${isGoalTracker ? 'justify-start pt-2' : 'justify-end'}`}>
                                  <h4 className="text-xs font-black text-slate-400 uppercase tracking-widest mb-1">{mod.title}</h4>
                                  <div className="text-2xl font-bold text-white tracking-tight truncate">{mod.value}</div>
                                  <p className="text-[10px] text-slate-500 font-medium truncate mt-1">
                                      {mod.subtext}
                                  </p>

                                  {/* Multi-Track Visual for Goal Vector */}
                                  {isGoalTracker && (
                                      <div className="mt-8 grid grid-cols-2 gap-4">
                                          <div>
                                              <div className="flex justify-between text-[10px] font-bold text-slate-500 mb-2 uppercase tracking-wider">
                                                  <span>Budget Burn</span>
                                                  <span>{(mod as any).budgetUtilization.toFixed(0)}%</span>
                                              </div>
                                              <div className="w-full h-2 bg-slate-800 rounded-full overflow-hidden border border-white/5">
                                                  <div 
                                                      className={`h-full transition-all duration-1000 ease-out ${(mod as any).budgetUtilization > 100 ? 'bg-red-500' : 'bg-gradient-to-r from-amber-500 to-rose-500'}`} 
                                                      style={{ width: `${Math.min((mod as any).budgetUtilization, 100)}%` }}
                                                  ></div>
                                              </div>
                                          </div>
                                          <div>
                                              <div className="flex justify-between text-[10px] font-bold text-slate-500 mb-2 uppercase tracking-wider">
                                                  <span>Goal Drive</span>
                                                  <span>{(mod as any).goalProgress.toFixed(0)}%</span>
                                              </div>
                                              <div className="w-full h-2 bg-slate-800 rounded-full overflow-hidden border border-white/5">
                                                  <div 
                                                      className="h-full transition-all duration-1000 ease-out bg-gradient-to-r from-indigo-500 to-cyan-500" 
                                                      style={{ width: `${Math.min((mod as any).goalProgress, 100)}%` }}
                                                  ></div>
                                              </div>
                                          </div>
                                      </div>
                                  )}

                                  {/* Detailed Mixed List of Budgets & Goals */}
                                  {isGoalTracker && (mod as any).details && (mod as any).details.length > 0 && (
                                      <div className="mt-6 space-y-3 flex-1 overflow-hidden">
                                          <div className="h-px bg-white/5 w-full mb-4"></div>
                                          {(mod as any).details.map((item: any, i: number) => (
                                              <div key={i} className="group/item">
                                                  <div className="flex justify-between text-[10px] font-bold text-slate-400 mb-1">
                                                      <div className="flex items-center gap-1.5">
                                                          {item.type === 'goal' ? <Target className="w-3 h-3 text-indigo-400" /> : <PieChartIcon className="w-3 h-3 text-rose-400" />}
                                                          <span className="text-white truncate max-w-[100px]">{item.name}</span>
                                                      </div>
                                                      <span className="text-[9px] opacity-70">{formatCurrency(item.current)} / {formatCurrency(item.limit)}</span>
                                                  </div>
                                                  <div className="w-full h-1 bg-slate-800 rounded-full overflow-hidden">
                                                      <div 
                                                          className={`h-full rounded-full ${item.type === 'goal' ? 'bg-indigo-500' : item.percent > 100 ? 'bg-rose-600' : 'bg-rose-400'}`} 
                                                          style={{ width: `${Math.min(item.percent, 100)}%` }}
                                                      ></div>
                                                  </div>
                                              </div>
                                          ))}
                                      </div>
                                  )}
                              </div>
                          </div>
                      );
                  })}
              </div>
          </div>

          {/* Standard Stats (Always Visible) */}
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 relative z-10">
            <StatCard 
                title="Net Worth" 
                value={formatCurrency(netWorth)} 
                icon={<Wallet className="w-5 h-5 text-indigo-400" />} 
                change={stats.nwChange.toFixed(1) + '%'} 
                positive={stats.nwChange >= 0} 
                delay="0s" 
                spotlightColor="rgba(99, 102, 241, 0.3)" 
                onMouseMove={handleCardMouseMove}
            />

            <div 
                className={`spotlight-card glass-card p-8 rounded-[2.5rem] border transition-all shadow-lg group animate-slide-up ${spendingStatus?.colorClass || 'border-white/5'}`} 
                style={{ '--spotlight-color': 'rgba(16, 185, 129, 0.3)', animationDelay: '0.1s' } as React.CSSProperties}
                onMouseMove={handleCardMouseMove}
            >
                <div className="flex justify-between items-start mb-6 relative z-10">
                    <div className="p-4 bg-slate-800 rounded-2xl border border-white/5 text-slate-400 shadow-inner">
                        {spendingStatus?.status === 'violation' ? <ShieldAlert className="w-5 h-5 text-rose-500" /> : spendingStatus?.status === 'warning' ? <AlertTriangle className="w-5 h-5 text-amber-400" /> : <CreditCard className="w-5 h-5 text-emerald-400" />}
                    </div>
                    <div className="text-right">
                        <div className="text-[9px] font-black uppercase tracking-widest text-slate-500 mb-1">{spendingPeriod} Limit</div>
                        <div className="text-xs font-bold text-white">{formatCurrency(spendingLimit || 0)}</div>
                    </div>
                </div>
                <div className="relative z-10">
                    <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-[0.3em] mb-1">Period Spend</h4>
                    <div className="text-3xl font-black text-white tracking-tighter">{formatCurrency(currentPeriodSpend)}</div>
                    <div className={`mt-2 text-[9px] font-black uppercase tracking-widest px-2 py-1 rounded w-fit ${spendingStatus?.status === 'violation' ? 'bg-rose-500 text-white' : spendingStatus?.status === 'warning' ? 'bg-amber-500 text-slate-900' : 'bg-emerald-500/20 text-emerald-400'}`}>
                        {spendingStatus?.message || 'Nominal'}
                    </div>
                </div>
            </div>

            <StatCard 
                title="Burn Rate/Day" 
                value={formatCurrency(stats.currentDailyAvg)} 
                icon={<Flame className="w-5 h-5 text-amber-400" />} 
                change={Math.abs(stats.burnChange).toFixed(1) + '%'} 
                positive={stats.burnChange <= 0} 
                delay="0.2s" 
                spotlightColor="rgba(245, 158, 11, 0.3)" 
                onMouseMove={handleCardMouseMove}
            />
            <StatCard 
                title="Predicted Spend" 
                value={formatCurrency(stats.forecastedTotal)} 
                icon={<TrendingUp className="w-5 h-5 text-emerald-400" />} 
                change={Math.abs(stats.forecastChange).toFixed(1) + '%'} 
                positive={stats.forecastChange <= 0} 
                delay="0.3s"
                spotlightColor="rgba(16, 185, 129, 0.3)" 
                onMouseMove={handleCardMouseMove}
            />
          </div>

          <div 
            className="mt-8 spotlight-card glass-card p-8 md:p-10 rounded-[2.5rem] border border-white/5 animate-slide-up relative z-10"
            style={{ '--spotlight-color': 'rgba(99, 102, 241, 0.15)' } as React.CSSProperties}
            onMouseMove={handleCardMouseMove}
          >
              <h3 className="text-xl font-black text-white uppercase tracking-tight flex items-center gap-3 mb-10 relative z-10"><Layers className="w-7 h-7 text-indigo-400" />Expenditure Topology</h3>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-8 items-center relative z-10">
                  <div className="flex justify-center relative h-64">
                      {expenditureData.total > 0 ? (
                          <ResponsiveContainer width="100%" height="100%">
                              <PieChart>
                                  <Pie
                                      data={expenditureData.chartData}
                                      cx="50%"
                                      cy="50%"
                                      innerRadius={60}
                                      outerRadius={80}
                                      paddingAngle={5}
                                      dataKey="value"
                                      stroke="none"
                                  >
                                      {expenditureData.chartData.map((entry, index) => (
                                          <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                                      ))}
                                  </Pie>
                                  <Tooltip 
                                      contentStyle={{ backgroundColor: '#0f172a', borderColor: '#1e293b', borderRadius: '12px', fontSize: '12px' }}
                                      itemStyle={{ color: '#fff', fontWeight: 'bold' }}
                                      formatter={(value: number) => formatCurrency(value)}
                                  />
                                  <text x="50%" y="50%" textAnchor="middle" dominantBaseline="middle" className="fill-white font-black" style={{ fontSize: '18px', fontWeight: 900 }}>
                                      {formatCurrency(expenditureData.total)}
                                  </text>
                                  <text x="50%" y="50%" dy={20} textAnchor="middle" dominantBaseline="middle" className="fill-slate-500 text-[10px] font-bold uppercase tracking-widest">
                                      Total
                                  </text>
                              </PieChart>
                          </ResponsiveContainer>
                      ) : (
                          <div className="relative w-48 h-48 rounded-full border-4 border-slate-800 border-dashed flex flex-col items-center justify-center opacity-50">
                              <span className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">No Data</span>
                              <span className="text-[9px] text-slate-600 font-medium">Add transactions</span>
                          </div>
                      )}
                  </div>

                  <div className="space-y-6">
                      <h4 className="text-xs font-black text-slate-500 uppercase tracking-[0.2em] mb-4">Primary Drain Vectors</h4>
                      <div className="space-y-4">
                          {expenditureData.topCategories.map((cat, i) => (
                              <div key={i} className="group/item">
                                  <div className="flex justify-between items-end mb-2">
                                      <div className="flex items-center gap-3">
                                          <div className={`w-8 h-8 rounded-lg flex items-center justify-center text-xs font-bold`} style={{ backgroundColor: `${COLORS[i % COLORS.length]}20`, color: COLORS[i % COLORS.length], borderColor: `${COLORS[i % COLORS.length]}40`, borderWidth: '1px' }}>
                                              {i + 1}
                                          </div>
                                          <div>
                                              <div className="text-white font-bold text-sm">{cat.name}</div>
                                              <div className="text-[10px] text-slate-500 font-medium">{cat.percent.toFixed(1)}% of total</div>
                                          </div>
                                      </div>
                                      <div className="text-right">
                                          <div className="text-white font-bold">{formatCurrency(cat.value)}</div>
                                      </div>
                                  </div>
                                  <div className="w-full h-1.5 bg-slate-800 rounded-full overflow-hidden">
                                      <div 
                                          className="h-full rounded-full transition-all duration-1000" 
                                          style={{ width: `${cat.percent}%`, backgroundColor: COLORS[i % COLORS.length] }}
                                      ></div>
                                  </div>
                              </div>
                          ))}
                          {expenditureData.topCategories.length === 0 && (
                              <div className="text-center py-8 text-slate-500 text-xs italic">
                                  No expenditure data available for topology mapping.
                              </div>
                          )}
                      </div>
                  </div>
              </div>
          </div>
      </div>

      {showAnalysisConfirm && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm animate-fade-in">
            <div className="bg-slate-900 border border-white/10 rounded-3xl w-full max-w-md p-8 shadow-2xl animate-slide-up relative">
                <button onClick={() => setShowAnalysisConfirm(false)} className="absolute top-6 right-6 text-slate-500 hover:text-white transition-colors"><X className="w-6 h-6" /></button>
                <div className="flex items-center gap-4 mb-6">
                    <div className="w-14 h-14 rounded-2xl bg-indigo-500/20 flex items-center justify-center border border-indigo-500/30">
                        <BrainCircuit className="w-8 h-8 text-indigo-400" />
                    </div>
                    <div>
                        <h3 className="text-2xl font-black text-white tracking-tight">Neural Analysis</h3>
                        <p className="text-indigo-400 text-xs font-bold uppercase tracking-widest">Confirmation Required</p>
                    </div>
                </div>
                <p className="text-slate-300 text-base mb-8 leading-relaxed font-medium">
                    Scanning system alerts requires deep neural processing. This action will consume <span className="text-white font-bold bg-white/10 px-2 py-0.5 rounded">1 Analysis Token</span> from your monthly quota.
                </p>
                <div className="flex gap-4">
                    <button 
                        onClick={() => setShowAnalysisConfirm(false)}
                        className="flex-1 py-4 rounded-2xl bg-slate-800 text-slate-300 font-bold text-sm uppercase tracking-wider hover:bg-slate-700 transition-colors border border-white/5"
                    >
                        Cancel
                    </button>
                    <button 
                        onClick={() => {
                            setShowAnalysisConfirm(false);
                            onAskCoach?.('Show my active alerts');
                        }}
                        className="flex-1 py-4 rounded-2xl bg-indigo-600 text-white font-bold text-sm uppercase tracking-wider hover:bg-indigo-500 transition-all shadow-xl shadow-indigo-500/20 hover:scale-[1.02] active:scale-95"
                    >
                        Confirm Scan
                    </button>
                </div>
            </div>
        </div>
      )}
    </div>
  );
};

const StatCard: React.FC<{ 
    title: string, 
    value: string | React.ReactNode, 
    icon: React.ReactNode, 
    change?: string, 
    positive?: boolean, 
    delay: string,
    spotlightColor: string,
    onMouseMove: (e: React.MouseEvent<HTMLDivElement>) => void
}> = ({ title, value, icon, change, positive, delay, spotlightColor, onMouseMove }) => (
    <div 
        className="spotlight-card glass-card p-8 rounded-[2.5rem] border border-white/5 animate-slide-up h-full" 
        style={{ animationDelay: delay, '--spotlight-color': spotlightColor } as React.CSSProperties}
        onMouseMove={onMouseMove}
    >
        <div className="flex justify-between items-start mb-6 relative z-10">
            <div className="p-4 bg-slate-800 rounded-2xl border border-white/5 text-slate-400 group-hover:text-indigo-400 transition-colors shadow-inner">{icon}</div>
            {change && (
                <div className={`flex items-center gap-1 text-[11px] font-black uppercase tracking-widest ${positive ? 'text-emerald-500' : 'text-rose-500'}`}>
                    {positive ? <ArrowUpRight className="w-4 h-4" /> : <ArrowDownRight className="w-4 h-4" />}
                    {change}
