);

export default Dashboard;

import React, { useState, useMemo } from 'react';
import { generateNegotiationScript } from '../services/geminiService';
import { Handshake, Loader2, DollarSign, Copy, Check, FileText, Zap, ShieldAlert, ArrowRight, Plus, X, Search, TrendingDown, ExternalLink, AlertTriangle, Info, CheckCircle, Calculator, Calendar, AlertOctagon, TrendingUp, Clock, PauseCircle, Star, Crown, ChevronRight } from 'lucide-react';
import { UserPlan, Transaction, TransactionType, Category } from '../types';

interface BillNegotiatorProps {
  userPlan: UserPlan;
  onIncrementUsage: () => void;
  negotiationUsage: number;
  transactions?: Transaction[];
}

interface SubscriptionItem {
    id: string;
    name: string;
    amount: number;
    lastDate: string;
    status: 'Safe' | 'Medium' | 'Danger';
}

const BillNegotiator: React.FC<BillNegotiatorProps> = ({ userPlan, onIncrementUsage, negotiationUsage, transactions = [] }) => {
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [generatedScript, setGeneratedScript] = useState<string | null>(null);
  const [isGenerating, setIsGenerating] = useState(false);
  const [isCopied, setIsCopied] = useState(false);
  const [negotiationType, setNegotiationType] = useState<'discount' | 'cancel' | 'downgrade'>('discount');

  const isElite = userPlan === 'ultra';
  const isPro = userPlan === 'pro';

  // Usage Limits
  const usageLimit = isElite ? 9999 : isPro ? 100 : 1;
  const remainingCredits = Math.max(0, usageLimit - negotiationUsage);
  const isLimitReached = !isElite && remainingCredits === 0;

  const subscriptions = useMemo(() => {
      try {
          const merchantMap = new Map<string, Transaction>();
          const safeTx = Array.isArray(transactions) ? transactions : [];

          safeTx.forEach(t => {
              if (t.type === TransactionType.EXPENSE) {
                  const isSubCategory = t.category === Category.SUBSCRIPTION || t.category === Category.UTILITIES || t.category === Category.ENTERTAINMENT;
                  if (isSubCategory) {
                      const key = t.merchant.toLowerCase().trim();
                      const existing = merchantMap.get(key);
                      if (!existing || new Date(t.date) > new Date(existing.date)) {
                          merchantMap.set(key, t);
                      }
                  }
              }
          });

          const detected: SubscriptionItem[] = [];
          merchantMap.forEach(t => {
              let status: 'Safe' | 'Medium' | 'Danger' = 'Safe';
              if (t.amount > 100) status = 'Danger';
              else if (t.amount > 40) status = 'Medium';

              detected.push({
                  id: t.id,
                  name: t.merchant,
                  amount: t.amount,
                  lastDate: t.date,
                  status
              });
          });

          return detected.sort((a, b) => b.amount - a.amount);
      } catch (err) {
          return [];
      }
  }, [transactions]);

  const activeItem = subscriptions.find(s => s.id === selectedId) || null;

  const handleGenerate = async () => {
      if (!activeItem || isLimitReached) return;
      setIsGenerating(true);
      setGeneratedScript(null);
      onIncrementUsage();

      setTimeout(async () => {
          const script = await generateNegotiationScript(activeItem.name, activeItem.amount, negotiationType, userPlan);
          setGeneratedScript(script);
          setIsGenerating(false);
      }, 800);
  };

  const handleCopy = () => {
      if (generatedScript) {
          navigator.clipboard.writeText(generatedScript);
          setIsCopied(true);
          setTimeout(() => setIsCopied(false), 2000);
      }
  };

  return (
    <div className="max-w-6xl mx-auto space-y-8 animate-fade-in pb-20">
      <div className="flex items-center gap-4 mb-8">
          <div className="p-3 bg-indigo-600 rounded-2xl shadow-lg shadow-indigo-600/20">
              <Handshake className="w-8 h-8 text-white" />
          </div>
          <div>
              <h2 className="text-3xl font-black text-white uppercase tracking-tighter">Negotiator</h2>
              <p className="text-slate-400 font-medium">Select a recurring bill to generate an optimization script.</p>
          </div>
          <div className="ml-auto px-4 py-2 bg-slate-900 rounded-xl border border-white/10 text-xs font-bold text-slate-300">
              {isElite ? 'Unlimited Access' : `${remainingCredits} Credits Left`}
          </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 h-[600px]">
          {/* LEFT: INBOX LIST */}
          <div className="lg:col-span-5 bg-slate-900/40 border border-white/5 rounded-[2.5rem] overflow-hidden flex flex-col">
              <div className="p-6 border-b border-white/5 bg-slate-900/60 backdrop-blur-md sticky top-0 z-10">
                  <h3 className="text-sm font-black text-slate-400 uppercase tracking-widest">Detected Subscriptions</h3>
              </div>
              <div className="flex-1 overflow-y-auto custom-scrollbar p-4 space-y-3">
                  {subscriptions.length === 0 ? (
                      <div className="text-center py-10 opacity-50">
                          <Search className="w-10 h-10 text-slate-500 mx-auto mb-3" />
                          <p className="text-sm text-slate-400 font-bold">No recurring bills found.</p>
                      </div>
                  ) : (
                      subscriptions.map(item => (
                          <div 
                            key={item.id}
                            onClick={() => { setSelectedId(item.id); setGeneratedScript(null); }}
                            className={`p-4 rounded-2xl cursor-pointer transition-all border group ${selectedId === item.id ? 'bg-indigo-600/10 border-indigo-500 shadow-lg shadow-indigo-900/20' : 'bg-slate-900/60 border-white/5 hover:border-white/20 hover:bg-slate-800'}`}
                          >
                              <div className="flex justify-between items-center">
                                  <div className="flex items-center gap-4">
                                      <div className={`w-12 h-12 rounded-xl flex items-center justify-center text-lg font-black text-white ${selectedId === item.id ? 'bg-indigo-500 shadow-lg' : 'bg-slate-800 group-hover:bg-slate-700'}`}>
                                          {item.name.charAt(0).toUpperCase()}
                                      </div>
                                      <div>
                                          <h4 className={`font-bold text-base ${selectedId === item.id ? 'text-white' : 'text-slate-300'}`}>{item.name}</h4>
                                          <p className="text-[10px] text-slate-500 font-black uppercase tracking-widest mt-0.5">
                                              {item.status === 'Danger' ? <span className="text-rose-400">High Cost</span> : 'Recurring'}
                                          </p>
                                      </div>
                                  </div>
                                  <div className="text-right">
                                      <div className={`text-lg font-black ${selectedId === item.id ? 'text-indigo-300' : 'text-white'}`}>${item.amount.toFixed(0)}</div>
                                      <ChevronRight className={`w-4 h-4 ml-auto mt-1 transition-transform ${selectedId === item.id ? 'text-indigo-500 rotate-90' : 'text-slate-600'}`} />
                                  </div>
                              </div>
                          </div>
                      ))
                  )}
              </div>
          </div>

          {/* RIGHT: WORKBENCH */}
          <div className="lg:col-span-7 bg-slate-950 border border-white/10 rounded-[2.5rem] flex flex-col relative overflow-hidden shadow-2xl">
              {activeItem ? (
                  <div className="flex-1 flex flex-col">
                      <div className="p-8 border-b border-white/5 bg-gradient-to-r from-slate-900 to-slate-950 flex justify-between items-start">
                          <div>
                              <h2 className="text-2xl font-black text-white">{activeItem.name}</h2>
                              <p className="text-slate-400 text-sm mt-1">Current Cost: <span className="text-white font-bold">${activeItem.amount}/mo</span></p>
                          </div>
                          <div className="flex bg-slate-900 rounded-xl p-1 border border-white/10">
                              {['discount', 'downgrade', 'cancel'].map((type) => (
                                  <button
                                    key={type}
                                    onClick={() => { setNegotiationType(type as any); setGeneratedScript(null); }}
                                    className={`px-4 py-2 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${negotiationType === type ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:text-slate-300'}`}
                                  >
                                      {type}
                                  </button>
                              ))}
                          </div>
                      </div>

                      <div className="flex-1 p-8 bg-slate-900/20 overflow-y-auto custom-scrollbar relative">
                          {!generatedScript ? (
                              <div className="h-full flex flex-col items-center justify-center text-center">
                                  {isGenerating ? (
                                      <div className="space-y-4">
                                          <Loader2 className="w-10 h-10 text-indigo-500 animate-spin mx-auto" />
                                          <p className="text-sm font-bold text-white animate-pulse">Constructing Negotiation Logic...</p>
                                      </div>
                                  ) : (
                                      <div className="space-y-6 max-w-xs">
                                          <div className="w-20 h-20 bg-slate-900 rounded-3xl flex items-center justify-center mx-auto border border-white/5 shadow-xl">
                                              <Zap className="w-10 h-10 text-indigo-500" />
                                          </div>
                                          <div>
                                              <h3 className="text-lg font-bold text-white mb-2">Ready to Optimize</h3>
                                              <p className="text-slate-500 text-sm">Generate a professional script to {negotiationType} this service.</p>
                                          </div>
                                          {isLimitReached ? (
                                              <div className="p-4 bg-rose-500/10 border border-rose-500/20 rounded-xl text-rose-400 text-xs font-bold uppercase tracking-wide">
                                                  Limit Reached
                                              </div>
                                          ) : (
                                              <button 
                                                onClick={handleGenerate}
                                                className="w-full py-4 bg-white text-indigo-950 font-black uppercase text-xs tracking-widest rounded-xl shadow-lg hover:scale-105 active:scale-95 transition-all flex items-center justify-center gap-2"
                                              >
                                                  Generate Script
                                              </button>
                                          )}
                                      </div>
                                  )}
                              </div>
                          ) : (
                              <div className="space-y-6 animate-slide-up">
                                  <div className="p-6 bg-slate-950 rounded-2xl border border-white/10 shadow-inner">
                                      <p className="text-slate-300 text-sm leading-relaxed whitespace-pre-wrap font-mono">{generatedScript}</p>
                                  </div>
                                  <div className="flex gap-4">
                                      <button 
                                        onClick={handleCopy}
                                        className={`flex-1 py-4 rounded-xl font-bold text-xs uppercase tracking-widest flex items-center justify-center gap-2 transition-all ${isCopied ? 'bg-emerald-600 text-white' : 'bg-indigo-600 text-white hover:bg-indigo-500 shadow-lg'}`}
                                      >
                                          {isCopied ? <Check className="w-4 h-4" /> : <Copy className="w-4 h-4" />}
                                          {isCopied ? 'Copied' : 'Copy to Clipboard'}
                                      </button>
                                      {!isLimitReached && (
                                          <button onClick={handleGenerate} className="px-6 py-4 bg-slate-800 hover:bg-slate-700 text-slate-300 rounded-xl font-bold text-xs uppercase tracking-widest border border-white/5 transition-all">
                                              Regenerate
                                          </button>
                                      )}
                                  </div>
                              </div>
                          )}
                      </div>
                  </div>
              ) : (
                  <div className="flex-1 flex flex-col items-center justify-center text-center p-12 opacity-40">
                      <div className="w-24 h-24 bg-slate-900 rounded-[2.5rem] flex items-center justify-center mb-6">
                          <Calculator className="w-10 h-10 text-slate-600" />
                      </div>
                      <h3 className="text-xl font-bold text-white mb-2">Workbench Idle</h3>
                      <p className="text-slate-500 text-sm font-medium">Select a subscription from the inbox.</p>
                  </div>
              )}
          </div>
      </div>
    </div>
  );
};

export default BillNegotiator;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { Transaction, AIAnalysisResponse, ChatMessage, UserPlan, TransactionType, Budget, BotMode, Category, Goal, FinancialSnapshot, SuggestedAction, GoalProposal } from '../types';
import { analyzeFinancialData, chatWithFinancialCoach } from '../services/geminiService';
import { RefreshCcw, CheckCircle, AlertTriangle, ShieldAlert, Info, TrendingUp, Bot, User, BrainCircuit, Lightbulb, Send, Lock, Sparkles, RefreshCw, Flame, ArrowRight, Zap, Crown, TrendingDown, ShoppingCart, Wallet, Terminal, Activity, MousePointerClick, ChevronRight, Check, X, EyeOff, Target, MessageSquare } from 'lucide-react';

interface InsightsProps {
  transactions: Transaction[];
  goals: Goal[];
  budgets: Budget[];
  userPlan: UserPlan;
  onUpgradeClick: () => void;
  formatCurrency: (amount: number) => string | React.ReactNode;
  initialPrompt?: string | null; 
  onPromptHandled?: () => void; 
  onApplyBudgets?: (budgets: Budget[]) => void; 
  insightUsage: number; 
  onIncrementUsage: () => void; 
  botMode: BotMode;
  onNavigate: (tab: string) => void;
  onAddGoal?: (goal: Goal) => void;
}

const Insights: React.FC<InsightsProps> = ({ transactions, goals, budgets, userPlan, onUpgradeClick, formatCurrency, initialPrompt, onPromptHandled, onApplyBudgets, insightUsage, onIncrementUsage, botMode, onNavigate, onAddGoal }) => {
  const [analysis, setAnalysis] = useState<AIAnalysisResponse | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [chatInput, setChatInput] = useState('');
  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([
    { 
        id: '1', 
        role: 'assistant', 
        content: botMode === 'ruthless' 
            ? 'System initialized. Ready to audit your spending vectors.' 
            : 'Hello! I\'m ready to help you optimize your financial wellness. What\'s on your mind?', 
        timestamp: new Date(),
        sentiment: 'info'
    }
  ]);
  const [chatLoading, setChatLoading] = useState(false);
  const [showRejectModal, setShowRejectModal] = useState<GoalProposal | null>(null);
  const [rejectionReason, setRejectionReason] = useState('');

  const chatEndRef = useRef<HTMLDivElement>(null);

  const isUltra = userPlan === 'ultra';
  const isElite = isUltra;
  const isPro = userPlan === 'pro';

  const currentLimit = isUltra ? 1500 : isPro ? 50 : 3;
  const isLocked = insightUsage >= currentLimit;

  // Manual Trigger Logic
  const runAnalysis = async () => {
    if (isLocked) return;
    setLoading(true);
    setError(null);
    onIncrementUsage();
    try {
      const result = await analyzeFinancialData(transactions, userPlan);

      if (result && result.goal_proposals) {
          const rejectedRaw = localStorage.getItem('nova_rejected_proposals');
          const rejectedList: {id: string, type: string, timestamp: number}[] = rejectedRaw ? JSON.parse(rejectedRaw) : [];
          const sevenDaysMs = 7 * 24 * 60 * 60 * 1000;

          result.goal_proposals = result.goal_proposals.filter(p => {
              const rejection = rejectedList.find(r => r.id === p.id || (r.type === p.type && p.title.includes(r.id)));
              if (!rejection) return true;
              return (Date.now() - rejection.timestamp) > sevenDaysMs;
          });
      }

      if (result) {
        setAnalysis(result);
      } else {
        setError("Coach is analyzing other portfolios. Try again.");
      }
    } catch (e) {
      setError("Unable to connect to financial brain.");
    } finally {
      setLoading(false);
    }
  };

  const handleAcceptProposal = (proposal: GoalProposal) => {
      if (proposal.type === 'goal' && onAddGoal) {
          onAddGoal({
              id: Date.now().toString(),
              name: proposal.title,
              targetAmount: proposal.target_amount,
              currentAmount: 0,
              deadline: proposal.deadline || new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
              icon: 'star',
              color: 'from-emerald-500 to-teal-500'
          });
      } else if (proposal.type === 'budget' && onApplyBudgets) {
          onApplyBudgets([{
              id: `ai_${Date.now()}`,
              category: (proposal.category as Category) || Category.OTHER,
              limit: proposal.target_amount,
              startDate: new Date().toISOString()
          }]);
      }

      if (analysis) {
          setAnalysis({
              ...analysis,
              goal_proposals: analysis.goal_proposals.filter(p => p.id !== proposal.id)
          });
      }
  };

  const handleRejectProposal = () => {
      if (!showRejectModal) return;
      const rejectedRaw = localStorage.getItem('nova_rejected_proposals');
      const rejectedList = rejectedRaw ? JSON.parse(rejectedRaw) : [];
      rejectedList.push({
          id: showRejectModal.id,
          type: showRejectModal.type,
          title: showRejectModal.title,
          timestamp: Date.now(),
          reason: rejectionReason
      });
      localStorage.setItem('nova_rejected_proposals', JSON.stringify(rejectedList));

      if (analysis) {
          setAnalysis({
              ...analysis,
              goal_proposals: analysis.goal_proposals.filter(p => p.id !== showRejectModal.id)
          });
      }
      setShowRejectModal(null);
      setRejectionReason('');
  };

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [chatHistory, chatLoading]);

  useEffect(() => {
      if (!isLocked && initialPrompt && !chatLoading) {
          handleSendMessage(null, initialPrompt);
          if (onPromptHandled) onPromptHandled();
      }
  }, [initialPrompt, isLocked]);

  const handleSendMessage = async (e: React.FormEvent | null, promptOverride?: string) => {
    if (e) e.preventDefault();
    const content = promptOverride || chatInput;
    if (!content.trim() || isLocked) return;

    onIncrementUsage();
    const userMsg: ChatMessage = { id: Date.now().toString(), role: 'user', content: content, timestamp: new Date() };
    setChatHistory(prev => [...prev, userMsg]);
    setChatInput('');
    setChatLoading(true);

    const now = new Date();
    const currentMonthTxs = transactions.filter(t => new Date(t.date).getMonth() === now.getMonth());
    const income = currentMonthTxs.filter(t => t.type === TransactionType.INCOME).reduce((sum, t) => sum + t.amount, 0);
    const expense = currentMonthTxs.filter(t => t.type === TransactionType.EXPENSE).reduce((sum, t) => sum + t.amount, 0);

    const catMap: Record<string, number> = {};
    currentMonthTxs.filter(t => t.type === TransactionType.EXPENSE).forEach(t => { catMap[t.category] = (catMap[t.category] || 0) + t.amount; });
    const topCat = Object.entries(catMap).sort((a,b) => b[1] - a[1])[0];

    const snapshot: FinancialSnapshot = {
        currentMonthMetrics: {
            income,
            expense,
            savingsRate: income > 0 ? (income - expense) / income : 0,
            topExpenseCategory: topCat ? topCat[0] : 'None'
        },
        recentTransactions: transactions.slice(0, 10),
        activeGoals: goals,
        budgets: budgets
    };

    const response = await chatWithFinancialCoach(userMsg.content, chatHistory, snapshot, botMode, userPlan);

    const aiMsg: ChatMessage = { 
        id: (Date.now() + 1).toString(), 
        role: 'assistant', 
        content: response.message, 
        timestamp: new Date(),
        sentiment: response.sentiment as any,
        suggestedActions: response.suggestedActions
    };

    setChatHistory(prev => [...prev, aiMsg]);
    setChatLoading(false);
  };

  const handleActionClick = (action: SuggestedAction) => {
      if (action.actionId.startsWith('navigate_')) {
          const tab = action.actionId.replace('navigate_', '');
          onNavigate(tab);
      } else {
          handleSendMessage(null, action.payload || action.label);
      }
  };

  const handleAutoTune = () => {
      if (!analysis || !onApplyBudgets) return;
      const existingCats = new Set(budgets.map(b => b.category));
      const newBudgets: Budget[] = analysis.budget_suggestions
          .filter(bs => !existingCats.has(bs.category as Category))
          .map(bs => ({
              id: `ai_${Date.now()}_${bs.category}`,
              category: bs.category as any,
              limit: bs.suggested_limit,
              startDate: new Date().toISOString()
          }));
      onApplyBudgets(newBudgets);
  };

  const getColorClass = (type: string) => {
    switch (type) {
        case 'success': return 'bg-emerald-500/10 border-emerald-500/20 text-emerald-100 shadow-sm';
        case 'warning': return 'bg-amber-500/10 border-amber-500/20 text-amber-100 shadow-sm';
        case 'critical': return 'bg-rose-500/10 border-rose-500/20 text-rose-100 shadow-sm';
        default: return 'bg-blue-500/10 border-blue-500/20 text-blue-100 shadow-sm';
    }
  };

  const getIconForType = (type: string) => {
      switch (type) {
        case 'success': return <CheckCircle className="w-5 h-5 text-emerald-400" />;
        case 'warning': return <AlertTriangle className="w-5 h-5 text-amber-400" />;
        case 'critical': return <ShieldAlert className="w-5 h-5 text-rose-400" />;
        default: return <Info className="w-5 h-5 text-blue-400" />;
      }
    };

  return (
    <div className="relative h-[calc(100vh-8rem)]">
      {isLocked && (
        <div className="absolute inset-0 z-50 flex items-center justify-center bg-slate-950/60 backdrop-blur-xl rounded-[2rem] border border-white/10 transform scale-105 transition-transform duration-500">
            <div className="text-center p-8 max-w-md animate-slide-up">
                <div className="w-20 h-20 rounded-3xl bg-gradient-to-tr from-indigo-500 to-purple-500 flex items-center justify-center mx-auto mb-6 shadow-2xl shadow-indigo-500/40"><Lock className="w-10 h-10 text-white" /></div>
                <h2 className="text-3xl font-bold text-white mb-3">Limit Reached</h2>
                <p className="text-slate-400 mb-8 leading-relaxed">
                    You've hit your monthly cap of {currentLimit} interactions. Upgrade to continue using the AI Coach.
                </p>
                {!isUltra && (
                    <button onClick={onUpgradeClick} className="w-full py-4 bg-white text-indigo-900 font-bold rounded-xl shadow-xl hover:scale-[1.02] active:scale-95 transition-all flex items-center justify-center gap-2 group"><Sparkles className="w-5 h-5 text-indigo-600 group-hover:rotate-12 transition-transform" />Upgrade Plan</button>
                )}
            </div>
        </div>
      )}

      <div className={`grid grid-cols-1 lg:grid-cols-12 gap-8 pb-10 h-full transition-all duration-500 ${isLocked ? 'blur-md opacity-50 pointer-events-none select-none overflow-hidden' : ''}`}>

        {/* LEFT COLUMN: ANALYSIS REPORT */}
        <div className="lg:col-span-7 overflow-y-auto custom-scrollbar space-y-8 pr-2">

            {/* Header / Trigger */}
            <div className="flex items-center justify-between mb-2">
                <div>
                    <h2 className="text-2xl font-black text-white flex items-center gap-3 tracking-tight"><BrainCircuit className="w-8 h-8 text-indigo-400" />Neural Audit</h2>
                    <p className="text-slate-400 text-xs mt-1 font-bold uppercase tracking-widest">System Analysis & Strategic Insights</p>
                </div>
                <div className="flex items-center gap-4">
                    <div className={`inline-flex items-center gap-2 px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest border ${isUltra ? 'bg-indigo-500/10 border-indigo-500/20 text-indigo-400' : isPro ? 'bg-amber-500/10 border-amber-500/20 text-amber-400' : 'bg-slate-700/50 border-white/10 text-slate-400'}`}>
                        {isUltra ? <Crown className="w-3 h-3" /> : isPro ? <Zap className="w-3 h-3" /> : null}
                        Tokens: {insightUsage}/{currentLimit}
                    </div>
                    <button 
                        onClick={runAnalysis} 
                        disabled={loading} 
                        className="px-6 py-3 bg-white text-indigo-950 rounded-xl font-black text-xs uppercase tracking-widest shadow-lg hover:scale-105 active:scale-95 transition-all flex items-center gap-2 disabled:opacity-50"
                    >
                        {loading ? <RefreshCw className="w-4 h-4 animate-spin" /> : <RefreshCcw className="w-4 h-4" />}
                        Run Scan
                    </button>
                </div>
            </div>

            {loading && (
                <div className="flex flex-col items-center justify-center py-32 space-y-6">
                    <Activity className="w-16 h-16 text-indigo-500 animate-bounce" />
                    <p className="text-slate-400 text-sm font-bold uppercase tracking-[0.3em] animate-pulse">Processing Neural Vectors...</p>
                </div>
            )}

            {!analysis && !loading && (
                <div className="flex flex-col items-center justify-center py-20 text-center border-2 border-dashed border-slate-800 rounded-[3rem] bg-slate-900/20">
                    <div className="w-24 h-24 bg-slate-900 rounded-full flex items-center justify-center mb-6 shadow-xl"><BrainCircuit className="w-10 h-10 text-slate-600" /></div>
                    <h3 className="text-xl font-bold text-white mb-2">System Idle</h3>
