                        <div className="flex items-end justify-between">
                            <div className="flex-1 min-w-0">
                                <h4 className={`text-3xl font-black ${analysis.risk_score > 50 ? 'text-rose-400' : 'text-emerald-400'} tracking-tighter`}>
