                                </div>
                            ))}
                        </div>
                    </div>
                )}
            </div>
            )}
        </div>

        {/* RIGHT COLUMN: CHAT INTERFACE */}
        <div className="lg:col-span-5 h-[600px] lg:h-auto flex flex-col bg-slate-900/60 rounded-[2.5rem] border border-white/10 shadow-2xl relative overflow-hidden">

            {/* Chat Header */}
            <div className="p-6 border-b border-white/5 bg-slate-950/80 backdrop-blur-xl z-10 flex justify-between items-center">
                <div className="flex items-center gap-3">
                    <div className={`w-10 h-10 rounded-xl flex items-center justify-center shadow-lg ring-1 ring-white/10 ${botMode === 'ruthless' ? 'bg-slate-800' : 'bg-gradient-to-tr from-indigo-500 to-purple-500'}`}>
                        {botMode === 'ruthless' ? <Terminal className="w-5 h-5 text-slate-300" /> : <Bot className="w-5 h-5 text-white" />}
                    </div>
                    <div>
                        <h3 className="font-bold text-white text-sm">Financial Agent</h3>
                        <div className="flex items-center gap-1.5 mt-0.5">
