import React, { useMemo, useState } from 'react';
import { AreaChart, Area, LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, PieChart, Pie, Cell } from 'recharts';
import { Account, Transaction, TransactionType, Category, UserPlan, Goal, Budget, SpendingStatus, SpendingPeriod } from '../types';
import { Activity, Flame, TrendingUp, Wallet, PlusCircle, CreditCard, Target, Quote, Landmark, Zap, Radio, Repeat, Check, Copy, X, Loader2, Sparkles, ArrowUpRight, ArrowDownRight, LayoutGrid, ArrowRight, Pin, Square, CheckSquare, Microscope, PieChart as PieChartIcon, ShieldAlert, BrainCircuit, GripVertical, AlertTriangle, Layers, Circle, Trophy, MessageSquare, Handshake, FileText, ChevronRight } from 'lucide-react';

interface DashboardProps {
  accounts: Account[];
  transactions: Transaction[];
  goals: Goal[];
  budgets: Budget[];
  onNavigate: (tab: string) => void;
  onAddAccount?: () => void;
  onAddTransaction?: () => void;
  onAddGoal?: () => void;
  formatCurrency: (amount: number) => string | React.ReactNode;
  userPlan?: UserPlan;
  onAskCoach?: (message: string) => void;
  isPinMode?: boolean;
  pinnedIds?: string[];
  onTogglePin?: (id: string) => void;
  trackEvent?: (id: string) => void;
  insightUsage?: number;
  spendingStatus?: SpendingStatus;
  currentPeriodSpend?: number;
  spendingLimit?: number;
  spendingPeriod?: SpendingPeriod;
}

const COLORS = ['#6366f1', '#f43f5e', '#f59e0b', '#10b981', '#8b5cf6', '#06b6d4', '#ec4899', '#64748b'];

const Dashboard: React.FC<DashboardProps> = ({ 
    accounts, 
    transactions, 
    goals, 
    budgets,
    onNavigate, 
    onAddAccount, 
    onAddTransaction, 
    onAddGoal, 
    formatCurrency, 
    userPlan, 
    onAskCoach, 
    insightUsage = 0,
    spendingStatus,
    currentPeriodSpend = 0,
    spendingLimit = 1000,
    spendingPeriod = 'monthly'
}) => {
  const today = new Date();
  const currentMonth = today.getMonth();
  const currentYear = today.getFullYear();
  const currentMonthName = today.toLocaleDateString('en-US', { month: 'long' });

  // --- Data Calculations ---

  const netWorth = useMemo(() => accounts.reduce((acc, curr) => acc + curr.balance, 0), [accounts]);

  const stats = useMemo(() => {
    const currentMTDExpenses = transactions.filter(t => {
      const d = new Date(t.date);
      return t.type === TransactionType.EXPENSE && d.getMonth() === currentMonth && d.getFullYear() === currentYear;
    });
    const currentMTDTotal = currentMTDExpenses.reduce((acc, t) => acc + t.amount, 0);
    const currentDay = today.getDate();
    const currentDailyAvg = currentMTDTotal / Math.max(currentDay, 1);

    return { currentDailyAvg };
  }, [transactions, currentMonth, currentYear]);

  const expenditureData = useMemo(() => {
    const expenses = transactions.filter(t => 
        t.type === TransactionType.EXPENSE && 
        new Date(t.date).getMonth() === currentMonth &&
        new Date(t.date).getFullYear() === currentYear
    );

    const total = expenses.reduce((acc, t) => acc + t.amount, 0);
    const catMap: Record<string, number> = {};

    expenses.forEach(t => {
        catMap[t.category] = (catMap[t.category] || 0) + t.amount;
    });

    const chartData = Object.entries(catMap)
        .map(([name, value]) => ({ name, value }))
        .sort((a, b) => b.value - a.value);

    return { chartData, total };
  }, [transactions, currentMonth, currentYear]);

  const lineChartData = useMemo(() => {
    const daysInCurrentMonth = new Date(currentYear, currentMonth + 1, 0).getDate();
    const data = [];

    const getDailySpend = (month: number, year: number) => {
        const daily = new Array(32).fill(0);
        transactions.forEach(t => {
            const d = new Date(t.date);
            if (t.type === TransactionType.EXPENSE && d.getMonth() === month && d.getFullYear() === year) {
                daily[d.getDate()] += t.amount;
            }
        });
        // Cumulative
        for (let i = 1; i < daily.length; i++) daily[i] += daily[i-1];
        return daily;
    };

    const currentMonthData = getDailySpend(currentMonth, currentYear);
    const prevMonthDate = new Date(currentYear, currentMonth - 1, 1);
    const prevMonthData = getDailySpend(prevMonthDate.getMonth(), prevMonthDate.getFullYear());

    for (let i = 1; i <= daysInCurrentMonth; i++) {
        data.push({
            day: i,
            ThisMonth: currentMonthData[i],
            LastMonth: prevMonthData[i]
        });
    }
    return data;
  }, [transactions, currentMonth, currentYear]);

  const recurringBills = useMemo(() => {
      const subs = transactions.filter(t => t.category === Category.SUBSCRIPTION);
      const unique = new Map();
      subs.forEach(t => {
          if (!unique.has(t.merchant)) unique.set(t.merchant, t);
      });
      return Array.from(unique.values()).slice(0, 3);
  }, [transactions]);

  const recentTransactions = useMemo(() => {
      return transactions.slice(0, 8);
  }, [transactions]);

  // Goal Vector Logic
  const goalMetrics = useMemo(() => {
      const totalGoalTarget = goals.reduce((acc, g) => acc + g.targetAmount, 0);
      const totalGoalCurrent = goals.reduce((acc, g) => acc + g.currentAmount, 0);
      const goalProgress = totalGoalTarget > 0 ? (totalGoalCurrent / totalGoalTarget) * 100 : 0;

      const budgetUtilization = spendingLimit > 0 ? (currentPeriodSpend / spendingLimit) * 100 : 0;

      return { totalGoalCurrent, totalGoalTarget, goalProgress, budgetUtilization };
  }, [goals, currentPeriodSpend, spendingLimit]);

  const neuralCapacity = userPlan === 'ultra' ? 1500 : userPlan === 'pro' ? 50 : 3;
  const neuralRemaining = Math.max(0, neuralCapacity - insightUsage);

  return (
    <div className="h-[calc(100vh-6rem)] overflow-y-auto md:overflow-hidden flex flex-col md:grid md:grid-cols-12 gap-6 pb-20 md:pb-0 pr-2">

        {/* LEFT COLUMN (3/12) */}
        <div className="md:col-span-3 flex flex-col gap-6 overflow-y-auto custom-scrollbar pr-1">

            {/* Spending Categorization (Pie) */}
            <div className="glass-card p-5 rounded-[2rem] border border-white/5 relative overflow-hidden bg-slate-900/40">
                <div className="flex justify-between items-start mb-2">
                    <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Good {today.toLocaleDateString('en-US', {weekday: 'long'})}</h3>
                </div>
                <h2 className="text-sm font-bold text-white mb-4">Spending Categorization for {currentMonthName}</h2>

                <div className="h-40 relative">
                    <ResponsiveContainer width="100%" height="100%">
                        <PieChart>
                            <Pie
                                data={expenditureData.chartData}
                                cx="50%"
                                cy="50%"
                                innerRadius={40}
                                outerRadius={60}
                                paddingAngle={5}
                                dataKey="value"
                                stroke="none"
                            >
                                {expenditureData.chartData.map((entry, index) => (
                                    <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                                ))}
                            </Pie>
                            <Tooltip contentStyle={{ backgroundColor: '#0f172a', borderRadius: '12px', border: 'none' }} itemStyle={{ color: '#fff', fontSize: '10px' }} formatter={(v: number) => formatCurrency(v)} />
                        </PieChart>
                    </ResponsiveContainer>
                    {/* Legend Overlay */}
                    <div className="absolute top-0 right-0 h-full flex flex-col justify-center gap-1">
                        {expenditureData.chartData.slice(0, 3).map((item, i) => (
                            <div key={i} className="flex items-center gap-1 text-[9px] text-slate-400">
                                <div className="w-2 h-2 rounded-full" style={{ backgroundColor: COLORS[i] }}></div>
                                <span className="truncate max-w-[60px]">{item.name}</span>
                            </div>
                        ))}
                    </div>
                </div>
            </div>

            {/* Small Stats Row */}
            <div className="grid grid-cols-1 gap-4">
                <div className="glass-card p-4 rounded-[1.5rem] border border-white/5 flex flex-col justify-between bg-slate-900/40">
                    <div className="flex items-center gap-2 mb-2">
                        <div className="p-1.5 bg-amber-500/10 rounded-lg"><Flame className="w-4 h-4 text-amber-500" /></div>
                        <span className="text-[9px] font-black text-slate-500 uppercase tracking-widest">Burn Rate/Day</span>
                    </div>
                    <div className="text-xl font-black text-white">{formatCurrency(stats.currentDailyAvg)}</div>
                </div>

                <div className="glass-card p-4 rounded-[1.5rem] border border-white/5 flex flex-col justify-between bg-slate-900/40">
                    <div className="flex items-center gap-2 mb-2">
                        <div className="p-1.5 bg-purple-500/10 rounded-lg"><BrainCircuit className="w-4 h-4 text-purple-500" /></div>
                        <span className="text-[9px] font-black text-slate-500 uppercase tracking-widest">Remaining Capacity</span>
                    </div>
                    <div className="text-xl font-black text-white">{neuralRemaining} <span className="text-[10px] text-slate-500 font-bold">Tokens</span></div>
                </div>
            </div>

            {/* Spending Graph */}
            <div className="glass-card p-5 rounded-[2rem] border border-white/5 bg-slate-900/40 flex-1 min-h-[200px] flex flex-col">
                <div className="flex justify-between items-center mb-4">
                    <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Spending Trend</h3>
                    <div className="px-2 py-1 bg-slate-800 rounded text-[9px] text-slate-300 font-bold">This Month vs Last</div>
                </div>
                <div className="flex-1 w-full min-h-0">
                    <ResponsiveContainer width="100%" height="100%">
                        <LineChart data={lineChartData}>
                            <Tooltip 
                                contentStyle={{ backgroundColor: '#020617', border: '1px solid rgba(255,255,255,0.1)', borderRadius: '12px' }} 
                                labelStyle={{ color: '#94a3b8', fontSize: '10px' }}
                                itemStyle={{ fontSize: '11px', fontWeight: 'bold' }}
                            />
                            <Line type="monotone" dataKey="ThisMonth" stroke="#6366f1" strokeWidth={3} dot={false} />
                            <Line type="monotone" dataKey="LastMonth" stroke="#64748b" strokeWidth={2} strokeDasharray="4 4" dot={false} />
                        </LineChart>
                    </ResponsiveContainer>
                </div>
            </div>
        </div>

        {/* CENTER COLUMN (5/12) - Transactions */}
        <div className="md:col-span-5 flex flex-col overflow-hidden glass-card rounded-[2.5rem] border border-white/5 bg-slate-950/30">
            <div className="p-6 border-b border-white/5 flex justify-between items-center bg-slate-900/20 backdrop-blur-md">
                <div>
                    <h2 className="text-lg font-black text-white uppercase tracking-tight">My Recent Transactions</h2>
                    <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest mt-1">Live Feed</p>
                </div>
                <button onClick={onAddTransaction} className="p-2 bg-indigo-600 rounded-xl hover:bg-indigo-500 text-white shadow-lg shadow-indigo-500/20"><PlusCircle className="w-5 h-5" /></button>
            </div>

            <div className="flex-1 overflow-y-auto custom-scrollbar p-2">
                <table className="w-full text-left border-collapse">
                    <thead className="sticky top-0 bg-[#0a0f1e] z-10 text-[9px] font-black text-slate-500 uppercase tracking-widest">
                        <tr>
                            <th className="p-4 rounded-tl-xl rounded-bl-xl">Date</th>
                            <th className="p-4">Name</th>
                            <th className="p-4 text-right rounded-tr-xl rounded-br-xl">Amount</th>
                        </tr>
                    </thead>
                    <tbody className="text-sm font-medium">
                        {recentTransactions.map((t, i) => (
                            <tr key={t.id} className="group hover:bg-white/5 transition-colors border-b border-white/5 last:border-0">
                                <td className="p-4 text-slate-400 font-mono text-xs">{new Date(t.date).toLocaleDateString('en-US', {day: '2-digit', month: 'short'})}</td>
                                <td className="p-4 text-slate-200">
                                    <div className="font-bold truncate max-w-[140px]">{t.merchant}</div>
                                    <div className="text-[9px] text-slate-500 uppercase tracking-wider">{t.category}</div>
                                </td>
                                <td className={`p-4 text-right font-black ${t.type === TransactionType.INCOME ? 'text-emerald-400' : 'text-white'}`}>
                                    {t.type === TransactionType.INCOME ? '+' : ''}{formatCurrency(t.amount)}
                                </td>
                            </tr>
                        ))}
                        {recentTransactions.length === 0 && (
                            <tr><td colSpan={3} className="p-10 text-center text-slate-500 text-xs italic">No recent activity detected.</td></tr>
                        )}
                    </tbody>
                </table>
            </div>
        </div>

        {/* RIGHT COLUMN (4/12) */}
        <div className="md:col-span-4 flex flex-col gap-5 overflow-y-auto custom-scrollbar pl-1">

            {/* Goal Vector Card */}
            <div className="glass-card p-6 rounded-[2rem] border border-white/5 bg-slate-900/40 relative group cursor-pointer hover:border-indigo-500/30 transition-all" onClick={() => onNavigate('goals')}>
                <div className="flex justify-between items-start mb-4">
                    <div className="w-12 h-12 bg-indigo-600 rounded-2xl flex items-center justify-center shadow-lg shadow-indigo-500/30"><Target className="w-6 h-6 text-white" /></div>
                    <span className="px-2 py-1 bg-slate-800 rounded text-[9px] font-black uppercase text-slate-400">Status: Active</span>
                </div>
                <h3 className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1">Goal Vector</h3>
                <div className="text-3xl font-black text-white tracking-tighter mb-4">{formatCurrency(goalMetrics.totalGoalCurrent)} <span className="text-sm text-slate-500 font-bold align-top opacity-60">/ {formatCurrency(goalMetrics.totalGoalTarget)}</span></div>

                <div className="space-y-3">
                    <div>
                        <div className="flex justify-between text-[9px] font-bold text-slate-400 mb-1"><span>Target Progress</span><span>{goalMetrics.goalProgress.toFixed(0)}%</span></div>
                        <div className="h-2 w-full bg-slate-800 rounded-full overflow-hidden"><div className="h-full bg-gradient-to-r from-indigo-500 to-cyan-500 w-[50%]" style={{ width: `${Math.min(goalMetrics.goalProgress, 100)}%` }}></div></div>
                    </div>
                    <div>
                        <div className="flex justify-between text-[9px] font-bold text-slate-400 mb-1"><span>Budget Burn</span><span>{goalMetrics.budgetUtilization.toFixed(0)}%</span></div>
                        <div className="h-2 w-full bg-slate-800 rounded-full overflow-hidden"><div className={`h-full bg-gradient-to-r from-amber-500 to-rose-500 transition-all duration-500`} style={{ width: `${Math.min(goalMetrics.budgetUtilization, 100)}%` }}></div></div>
                    </div>
                </div>

                <div className="mt-5 p-3 bg-slate-950/50 rounded-xl border border-white/5 flex items-center gap-3">
                    <div className="w-1.5 h-8 bg-indigo-500 rounded-full"></div>
                    <p className="text-[9px] font-medium text-slate-400 leading-tight">Check the duration estimated to achieve your goal in <span className="text-white font-bold">Sandbox</span>.</p>
                </div>
            </div>

            {/* Net Worth & Credit Card Row */}
            <div className="grid grid-cols-2 gap-4">
                <div className="glass-card p-4 rounded-[1.5rem] border border-white/5 bg-slate-900/40">
                    <div className="flex justify-between items-start mb-2">
                        <span className="text-[9px] font-black text-slate-500 uppercase tracking-widest">Net Worth</span>
                        <Wallet className="w-3 h-3 text-slate-600" />
                    </div>
                    <div className="text-sm font-black text-white truncate">{formatCurrency(netWorth)}</div>
                </div>
                <div className="glass-card p-4 rounded-[1.5rem] border border-white/5 bg-slate-900/40">
                    <div className="flex justify-between items-start mb-2">
                        <span className="text-[9px] font-black text-slate-500 uppercase tracking-widest">Spend Limit</span>
                        <CreditCard className="w-3 h-3 text-slate-600" />
                    </div>
                    <div className="text-sm font-black text-white truncate">{formatCurrency(spendingLimit || 0)}</div>
                </div>
            </div>

            {/* Action Buttons List */}
            <div className="space-y-2">
                <button onClick={() => onAskCoach && onAskCoach("Act as my financial advisor. Review my situation.")} className="w-full p-3 bg-slate-900/50 hover:bg-slate-800 border border-white/5 rounded-xl flex items-center justify-between group transition-all">
                    <span className="text-[10px] font-bold text-slate-300 uppercase tracking-wider group-hover:text-white">Financial Advisor</span>
                    <MessageSquare className="w-3.5 h-3.5 text-indigo-500" />
                </button>
                <button onClick={() => onNavigate('sandbox')} className="w-full p-3 bg-slate-900/50 hover:bg-slate-800 border border-white/5 rounded-xl flex items-center justify-between group transition-all">
                    <span className="text-[10px] font-bold text-slate-300 uppercase tracking-wider group-hover:text-white">Smart Money Tools</span>
                    <Microscope className="w-3.5 h-3.5 text-emerald-500" />
                </button>
                <button onClick={() => onNavigate('negotiator')} className="w-full p-3 bg-slate-900/50 hover:bg-slate-800 border border-white/5 rounded-xl flex items-center justify-between group transition-all">
                    <span className="text-[10px] font-bold text-slate-300 uppercase tracking-wider group-hover:text-white">Negotiate My Bill</span>
                    <Handshake className="w-3.5 h-3.5 text-amber-500" />
                </button>
                <button onClick={() => onAskCoach && onAskCoach("Summarize my required actions for today based on recent transactions.")} className="w-full p-3 bg-slate-900/50 hover:bg-slate-800 border border-white/5 rounded-xl flex items-center justify-between group transition-all">
                    <span className="text-[10px] font-bold text-slate-300 uppercase tracking-wider group-hover:text-white">Summarize Actions</span>
                    <FileText className="w-3.5 h-3.5 text-rose-500" />
                </button>
                <button onClick={() => onNavigate('accounts')} className="w-full p-3 bg-slate-900/50 hover:bg-slate-800 border border-white/5 rounded-xl flex items-center justify-between group transition-all">
                    <span className="text-[10px] font-bold text-slate-300 uppercase tracking-wider group-hover:text-white">Investment</span>
                    <TrendingUp className="w-3.5 h-3.5 text-cyan-500" />
                </button>
            </div>

            {/* Recurring Bills */}
            <div className="glass-card p-5 rounded-[2rem] border border-white/5 bg-slate-900/40 mt-auto">
                <div className="flex justify-between items-center mb-4">
                    <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">My Recurring Bill</h3>
                    <span className="text-[8px] bg-slate-800 px-2 py-0.5 rounded text-slate-400 uppercase">This Month</span>
                </div>
                <div className="space-y-3">
                    {recurringBills.length === 0 ? (
                        <p className="text-[10px] text-slate-500 italic">Add transactions with 'Subscription' category to track.</p>
                    ) : (
                        recurringBills.map(t => (
                            <div key={t.id} className="flex justify-between items-center group">
                                <div className="flex items-center gap-2">
                                    <div className="w-1.5 h-1.5 rounded-full bg-indigo-500"></div>
                                    <span className="text-xs font-bold text-slate-300 group-hover:text-white transition-colors truncate max-w-[100px]">{t.merchant}</span>
                                </div>
                                <span className="text-xs font-bold text-white">{formatCurrency(t.amount)}</span>
                            </div>
                        ))
                    )}
                </div>
            </div>

        </div>
    </div>
  );
};

export default Dashboard;

import React, { useMemo } from 'react';
import { AreaChart, Area, LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, PieChart, Pie, Cell } from 'recharts';
import { Account, Transaction, TransactionType, Category, UserPlan, Goal, Budget, SpendingStatus, SpendingPeriod } from '../types';
import { Activity, Flame, TrendingUp, Wallet, PlusCircle, CreditCard, Target, Quote, Landmark, Zap, Radio, Repeat, Check, Copy, X, Loader2, Sparkles, ArrowUpRight, ArrowDownRight, LayoutGrid, ArrowRight, Pin, Square, CheckSquare, Microscope, PieChart as PieChartIcon, ShieldAlert, BrainCircuit, GripVertical, AlertTriangle, Layers, Circle, Trophy, MessageSquare, Handshake, FileText, ChevronRight, Clock } from 'lucide-react';

interface DashboardProps {
  accounts: Account[];
  transactions: Transaction[];
  goals: Goal[];
  budgets: Budget[];
  onNavigate: (tab: string) => void;
  onAddAccount?: () => void;
  onAddTransaction?: () => void;
  onAddGoal?: () => void;
  formatCurrency: (amount: number) => string | React.ReactNode;
  userPlan?: UserPlan;
  onAskCoach?: (message: string) => void;
  isPinMode?: boolean;
  pinnedIds?: string[];
  onTogglePin?: (id: string) => void;
  trackEvent?: (id: string) => void;
  insightUsage?: number;
  spendingStatus?: SpendingStatus;
  currentPeriodSpend?: number;
  spendingLimit?: number;
  spendingPeriod?: SpendingPeriod;
}

const COLORS = ['#6366f1', '#f43f5e', '#f59e0b', '#10b981', '#8b5cf6', '#06b6d4', '#ec4899', '#64748b'];

const Dashboard: React.FC<DashboardProps> = ({ 
    accounts, 
    transactions, 
    goals, 
    budgets,
    onNavigate, 
    onAddAccount, 
    onAddTransaction, 
    onAddGoal, 
    formatCurrency, 
    userPlan, 
    onAskCoach, 
    insightUsage = 0,
    spendingStatus,
    currentPeriodSpend = 0,
    spendingLimit = 1000,
    spendingPeriod = 'monthly'
}) => {
  const today = new Date();
  const currentMonth = today.getMonth();
  const currentYear = today.getFullYear();
  const currentMonthName = today.toLocaleDateString('en-US', { month: 'long' });
  const dayName = today.toLocaleDateString('en-US', { weekday: 'long' });
  const userName = localStorage.getItem('nova_user_name') || 'User';

  // --- Data Calculations ---

  const netWorth = useMemo(() => accounts.reduce((acc, curr) => acc + curr.balance, 0), [accounts]);

  // Estimate credit card balance (negative balances in accounts of type Credit Card)
  const creditCardBalance = useMemo(() => {
      return accounts
        .filter(a => a.type === 'Credit Card')
        .reduce((acc, curr) => acc + (curr.balance < 0 ? Math.abs(curr.balance) : 0), 0);
  }, [accounts]);

  const stats = useMemo(() => {
    const currentMTDExpenses = transactions.filter(t => {
      const d = new Date(t.date);
      return t.type === TransactionType.EXPENSE && d.getMonth() === currentMonth && d.getFullYear() === currentYear;
    });
    const currentMTDTotal = currentMTDExpenses.reduce((acc, t) => acc + t.amount, 0);
    const currentDay = today.getDate();
    const currentDailyAvg = currentMTDTotal / Math.max(currentDay, 1);

    return { currentDailyAvg };
  }, [transactions, currentMonth, currentYear]);

  const expenditureData = useMemo(() => {
    const expenses = transactions.filter(t => 
        t.type === TransactionType.EXPENSE && 
        new Date(t.date).getMonth() === currentMonth &&
        new Date(t.date).getFullYear() === currentYear
    );

    const total = expenses.reduce((acc, t) => acc + t.amount, 0);
    const catMap: Record<string, number> = {};

    expenses.forEach(t => {
        catMap[t.category] = (catMap[t.category] || 0) + t.amount;
    });

    const chartData = Object.entries(catMap)
        .map(([name, value]) => ({ name, value }))
        .sort((a, b) => b.value - a.value);

    return { chartData, total };
  }, [transactions, currentMonth, currentYear]);

  const lineChartData = useMemo(() => {
    const daysInCurrentMonth = new Date(currentYear, currentMonth + 1, 0).getDate();
    const data = [];

    const getDailySpend = (month: number, year: number) => {
        const daily = new Array(32).fill(0);
        transactions.forEach(t => {
            const d = new Date(t.date);
            if (t.type === TransactionType.EXPENSE && d.getMonth() === month && d.getFullYear() === year) {
                daily[d.getDate()] += t.amount;
            }
        });
        // Cumulative
        for (let i = 1; i < daily.length; i++) daily[i] += daily[i-1];
        return daily;
    };

    const currentMonthData = getDailySpend(currentMonth, currentYear);
    const prevMonthDate = new Date(currentYear, currentMonth - 1, 1);
    const prevMonthData = getDailySpend(prevMonthDate.getMonth(), prevMonthDate.getFullYear());

    for (let i = 1; i <= daysInCurrentMonth; i++) {
        data.push({
            day: i,
            ThisMonth: currentMonthData[i],
            LastMonth: prevMonthData[i]
        });
    }
    return data;
  }, [transactions, currentMonth, currentYear]);

  const recurringBills = useMemo(() => {
      const subs = transactions.filter(t => t.category === Category.SUBSCRIPTION);
      const unique = new Map();
      subs.forEach(t => {
          if (!unique.has(t.merchant)) unique.set(t.merchant, t);
      });
      return Array.from(unique.values()).slice(0, 3);
  }, [transactions]);

  const recentTransactions = useMemo(() => {
      return transactions.slice(0, 5);
  }, [transactions]);

  // Goal Vector Logic
  const goalMetrics = useMemo(() => {
      const totalGoalTarget = goals.reduce((acc, g) => acc + g.targetAmount, 0);
      const totalGoalCurrent = goals.reduce((acc, g) => acc + g.currentAmount, 0);
      const goalProgress = totalGoalTarget > 0 ? (totalGoalCurrent / totalGoalTarget) * 100 : 0;

      const budgetUtilization = spendingLimit > 0 ? (currentPeriodSpend / spendingLimit) * 100 : 0;

      return { totalGoalCurrent, totalGoalTarget, goalProgress, budgetUtilization };
  }, [goals, currentPeriodSpend, spendingLimit]);

  const neuralCapacity = userPlan === 'ultra' ? 1500 : userPlan === 'pro' ? 50 : 3;
  const neuralRemaining = Math.max(0, neuralCapacity - insightUsage);

  return (
    <div className="h-full overflow-y-auto custom-scrollbar pb-20">

        {/* Header */}
        <div className="mb-8 px-2">
            <h1 className="text-3xl font-black text-white uppercase tracking-tight">Good {dayName}, {userName}</h1>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">

            {/* LEFT MAIN PANEL (Span 8) */}
            <div className="lg:col-span-8 space-y-8">

                {/* 1. Spending Categorization */}
                <div className="glass-card p-8 rounded-[2.5rem] border border-white/5 relative overflow-hidden bg-slate-900/40 min-h-[320px] flex flex-col md:flex-row items-center gap-8">
                    <div className="flex-1 w-full h-64 relative">
                        <div className="absolute top-0 left-0 text-sm font-bold text-slate-400 uppercase tracking-widest">Spending Categorization for {currentMonthName}</div>
                        <ResponsiveContainer width="100%" height="100%">
                            <PieChart>
                                <Pie
                                    data={expenditureData.chartData}
                                    cx="50%"
                                    cy="55%"
                                    innerRadius={70}
                                    outerRadius={95}
                                    paddingAngle={5}
                                    dataKey="value"
                                    stroke="none"
                                >
                                    {expenditureData.chartData.map((entry, index) => (
                                        <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                                    ))}
                                </Pie>
                                <Tooltip contentStyle={{ backgroundColor: '#0f172a', borderRadius: '12px', border: 'none' }} itemStyle={{ color: '#fff', fontSize: '10px' }} formatter={(v: number) => formatCurrency(v)} />
                            </PieChart>
                        </ResponsiveContainer>
                        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 text-center mt-2 pointer-events-none">
                            <div className="text-3xl font-black text-white">{expenditureData.chartData.length}</div>
                            <div className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Categories</div>
                        </div>
                    </div>
                    <div className="w-full md:w-1/3 space-y-4">
                        <div className="space-y-2">
                            {expenditureData.chartData.slice(0, 4).map((item, i) => (
                                <div key={i} className="flex justify-between items-center group cursor-default">
                                    <div className="flex items-center gap-2">
                                        <div className="w-3 h-3 rounded-full" style={{ backgroundColor: COLORS[i % COLORS.length] }}></div>
                                        <span className="text-xs font-bold text-slate-400 group-hover:text-white transition-colors">{item.name}</span>
                                    </div>
                                    <span className="text-xs font-bold text-slate-500">{((item.value / expenditureData.total) * 100).toFixed(0)}%</span>
                                </div>
                            ))}
                        </div>
                        <div className="h-px bg-white/5 w-full my-4"></div>
                        <div className="flex justify-between items-center">
                            <span className="text-xs font-bold text-slate-400 uppercase tracking-widest">Total</span>
                            <span className="text-lg font-black text-white">{formatCurrency(expenditureData.total)}</span>
                        </div>
                    </div>
                </div>

                {/* 2. Middle Row: Stats + Transactions */}
                <div className="grid grid-cols-1 md:grid-cols-12 gap-8">

                    {/* Left Sub-Col: Small Cards (Span 4) */}
                    <div className="md:col-span-4 flex flex-col gap-6">
                        <div className="glass-card p-6 rounded-[2rem] border border-white/5 bg-slate-900/40 flex-1 flex flex-col justify-center">
                            <div className="flex items-center gap-3 mb-3">
                                <div className="p-2 bg-amber-500/10 rounded-xl"><Flame className="w-5 h-5 text-amber-500" /></div>
                                <span className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em]">Burn Rate/Day</span>
                            </div>
                            <div className="text-3xl font-black text-white tracking-tighter">{formatCurrency(stats.currentDailyAvg)}</div>
                        </div>

                        <div className="glass-card p-6 rounded-[2rem] border border-white/5 bg-slate-900/40 flex-1 flex flex-col justify-center">
                            <div className="flex items-center gap-3 mb-3">
                                <div className="p-2 bg-purple-500/10 rounded-xl"><Zap className="w-5 h-5 text-purple-500" /></div>
                                <span className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em]">Remaining Cap</span>
                            </div>
                            <div className="text-3xl font-black text-white tracking-tighter">{neuralRemaining} <span className="text-sm text-slate-500 font-bold align-middle">Tokens</span></div>
                        </div>
                    </div>

                    {/* Right Sub-Col: Transactions (Span 8) */}
                    <div className="md:col-span-8 glass-card rounded-[2.5rem] border border-white/5 bg-slate-900/40 overflow-hidden flex flex-col">
                        <div className="p-6 pb-2 border-b border-white/5 bg-slate-950/20">
                            <h3 className="text-xs font-black text-slate-500 uppercase tracking-[0.2em]">My Recent Transactions</h3>
                        </div>
                        <div className="flex-1 overflow-y-auto custom-scrollbar p-2">
                            <table className="w-full text-left">
                                <thead className="text-[9px] font-black text-slate-600 uppercase tracking-widest bg-slate-950/20">
                                    <tr>
                                        <th className="p-3 pl-6">Date</th>
                                        <th className="p-3">Name</th>
                                        <th className="p-3 text-right pr-6">Amount</th>
                                    </tr>
                                </thead>
                                <tbody className="text-xs font-bold text-slate-300">
                                    {recentTransactions.map((t) => (
                                        <tr key={t.id} className="border-b border-white/5 last:border-0 hover:bg-white/5 transition-colors">
                                            <td className="p-4 pl-6 text-slate-500">{new Date(t.date).toLocaleDateString('en-US', { month: 'short', day: 'numeric' })}</td>
                                            <td className="p-4 text-white truncate max-w-[120px]">{t.merchant}</td>
                                            <td className={`p-4 text-right pr-6 ${t.type === TransactionType.INCOME ? 'text-emerald-400' : ''}`}>{formatCurrency(t.amount)}</td>
                                        </tr>
                                    ))}
                                    {recentTransactions.length === 0 && (
                                        <tr><td colSpan={3} className="p-8 text-center text-slate-500 italic">No activity yet.</td></tr>
                                    )}
                                </tbody>
                            </table>
                        </div>
                    </div>
                </div>

                {/* 3. Spending Graph */}
                <div className="glass-card p-8 rounded-[2.5rem] border border-white/5 bg-slate-900/40 h-[300px] flex flex-col">
                    <div className="flex justify-between items-center mb-6">
                        <h3 className="text-sm font-black text-slate-400 uppercase tracking-[0.2em]">Spending</h3>
                        <div className="flex items-center gap-2 px-3 py-1.5 rounded-lg bg-slate-950 border border-white/10">
                            <span className="text-[10px] font-bold text-slate-400 uppercase">This month vs. last year</span>
                            <ChevronRight className="w-3 h-3 text-slate-500 rotate-90" />
                        </div>
                    </div>
                    <div className="flex-1 w-full min-h-0">
                        <ResponsiveContainer width="100%" height="100%">
                            <AreaChart data={lineChartData}>
                                <defs>
                                    <linearGradient id="colorSpent" x1="0" y1="0" x2="0" y2="1">
                                        <stop offset="5%" stopColor="#6366f1" stopOpacity={0.3}/>
                                        <stop offset="95%" stopColor="#6366f1" stopOpacity={0}/>
                                    </linearGradient>
                                </defs>
                                <Tooltip 
                                    contentStyle={{ backgroundColor: '#020617', border: '1px solid rgba(255,255,255,0.1)', borderRadius: '12px' }} 
                                    itemStyle={{ fontSize: '11px', fontWeight: 'bold' }}
                                    formatter={(v: number) => formatCurrency(v)}
                                />
                                <Area type="monotone" dataKey="ThisMonth" stroke="#6366f1" strokeWidth={3} fill="url(#colorSpent)" />
                                <Area type="monotone" dataKey="LastMonth" stroke="#475569" strokeWidth={2} strokeDasharray="4 4" fill="transparent" />
                            </AreaChart>
                        </ResponsiveContainer>
                    </div>
                    <div className="flex justify-between text-[9px] font-black text-slate-600 uppercase tracking-widest mt-2 px-4">
                        <span>Day 1</span>
                        <span>Day 15</span>
                        <span>Day 30</span>
                    </div>
                </div>

            </div>

            {/* RIGHT SIDEBAR (Span 4) */}
            <div className="lg:col-span-4 flex flex-col gap-6">

                {/* Goal Vector */}
                <div 
                    className="glass-card p-8 rounded-[2.5rem] border border-white/5 bg-slate-900/40 relative overflow-hidden cursor-pointer group hover:border-indigo-500/30 transition-all"
                    onClick={() => onNavigate('goals')}
                >
                    <div className="flex justify-between items-start mb-6">
                        <div className="w-14 h-14 rounded-full bg-indigo-600 flex items-center justify-center shadow-lg shadow-indigo-500/20 relative">
                            {/* Simple circular progress visualization */}
                            <svg className="absolute inset-0 w-full h-full -rotate-90">
                                <circle cx="28" cy="28" r="26" fill="transparent" stroke="#1e1b4b" strokeWidth="3" />
                                <circle cx="28" cy="28" r="26" fill="transparent" stroke="#a5b4fc" strokeWidth="3" strokeDasharray="163" strokeDashoffset={163 - (163 * goalMetrics.goalProgress) / 100} />
                            </svg>
                            <span className="text-xs font-black text-white">{goalMetrics.goalProgress.toFixed(0)}%</span>
                        </div>
                        <span className="px-3 py-1 rounded-lg bg-slate-950 border border-white/10 text-[9px] font-black text-slate-500 uppercase tracking-widest">Status</span>
                    </div>

                    <div className="mb-6">
                        <h3 className="text-xs font-black text-slate-500 uppercase tracking-[0.2em] mb-1">Goal Vector</h3>
                        <div className="text-3xl font-black text-white tracking-tighter">{formatCurrency(goalMetrics.totalGoalCurrent)}</div>
                    </div>

                    <div className="space-y-3">
                        <div className="h-1.5 w-full bg-slate-800 rounded-full overflow-hidden">
                            <div className="h-full bg-indigo-500 rounded-full" style={{ width: '100%' }}></div>
                        </div>
                        <div className="h-1.5 w-full bg-slate-800 rounded-full overflow-hidden">
                            <div className="h-full bg-slate-700 rounded-full" style={{ width: '70%' }}></div>
                        </div>
                        <div className="h-1.5 w-full bg-slate-800 rounded-full overflow-hidden">
                            <div className="h-full bg-slate-700 rounded-full" style={{ width: '40%' }}></div>
                        </div>
                    </div>

                    <div className="mt-6 p-4 bg-slate-950 rounded-2xl border border-white/5">
                        <p className="text-[10px] text-slate-400 font-medium leading-relaxed uppercase tracking-wider">
                            Check the duration estimated to achieve your goal in <span className="text-white font-bold">Sandbox</span>.
                        </p>
                    </div>
                </div>

                {/* Net Worth & Credit Card */}
                <div className="grid grid-cols-2 gap-4">
                    <div className="glass-card p-5 rounded-[2rem] border border-white/5 bg-slate-900/40 flex flex-col justify-between h-32">
                        <div className="flex justify-between items-start">
                            <span className="text-[9px] font-black text-slate-500 uppercase tracking-wider leading-tight">Net Worth</span>
                            <Wallet className="w-3.5 h-3.5 text-indigo-400" />
                        </div>
                        <div className="text-sm font-black text-white truncate tracking-tight">{formatCurrency(netWorth)}</div>
                    </div>
                    <div className="glass-card p-5 rounded-[2rem] border border-white/5 bg-slate-900/40 flex flex-col justify-between h-32">
                        <div className="flex justify-between items-start">
                            <span className="text-[9px] font-black text-slate-500 uppercase tracking-wider leading-tight">Credit Card Balance</span>
                            <CreditCard className="w-3.5 h-3.5 text-rose-400" />
                        </div>
                        <div className="text-sm font-black text-white truncate tracking-tight">{formatCurrency(creditCardBalance)}</div>
                    </div>
                </div>

                {/* Actions List */}
                <div className="space-y-3">
                    <button onClick={() => onAskCoach && onAskCoach("Analyze my spending.")} className="w-full p-4 bg-white text-slate-900 rounded-2xl text-xs font-black uppercase tracking-widest flex justify-between items-center hover:bg-slate-200 transition-colors shadow-lg">
                        Financial Overview <ChevronRight className="w-4 h-4" />
                    </button>
                    <button onClick={() => onNavigate('sandbox')} className="w-full p-4 bg-slate-900/60 border border-white/5 text-slate-300 rounded-2xl text-xs font-black uppercase tracking-widest flex justify-between items-center hover:bg-slate-800 transition-colors">
                        Smart Money Tools <ChevronRight className="w-4 h-4" />
                    </button>
                    <div className="grid grid-cols-2 gap-3">
                        <button onClick={() => onNavigate('negotiator')} className="p-4 bg-slate-900/60 border border-white/5 text-slate-300 rounded-2xl text-[9px] font-black uppercase tracking-widest hover:bg-slate-800 transition-colors text-center">
                            Negotiate My Bill
                        </button>
                        <button onClick={() => onAskCoach && onAskCoach("Summarize actions for today.")} className="p-4 bg-indigo-600 text-white rounded-2xl text-[9px] font-black uppercase tracking-widest hover:bg-indigo-500 transition-colors text-center shadow-lg shadow-indigo-500/20">
                            Summarize Action
                        </button>
                    </div>
                    <button onClick={() => onNavigate('accounts')} className="w-full p-4 bg-slate-900/60 border border-white/5 text-slate-300 rounded-2xl text-xs font-black uppercase tracking-widest flex justify-between items-center hover:bg-slate-800 transition-colors">
                        Investment <ChevronRight className="w-4 h-4" />
                    </button>
                </div>

                {/* Recurring Bills */}
                <div className="glass-card p-6 rounded-[2.5rem] border border-white/5 bg-slate-900/40 mt-auto">
                    <div className="flex justify-between items-center mb-6">
                        <h3 className="text-xs font-black text-slate-500 uppercase tracking-[0.2em]">My Recurring Bill</h3>
                        <span className="px-2 py-1 rounded bg-slate-950 border border-white/5 text-[8px] font-bold text-slate-400 uppercase">This Month</span>
                    </div>
                    <div className="space-y-4">
                        {recurringBills.length > 0 ? (
                            recurringBills.map(bill => (
                                <div key={bill.id} className="flex items-center justify-between group">
                                    <div className="flex items-center gap-3">
                                        <div className="w-8 h-8 rounded-full bg-slate-800 flex items-center justify-center text-xs font-black text-white uppercase">{bill.merchant.charAt(0)}</div>
                                        <div>
                                            <div className="text-xs font-bold text-white group-hover:text-indigo-400 transition-colors">{bill.merchant}</div>
                                            <div className="text-[9px] font-bold text-slate-500 uppercase">Subscription</div>
                                        </div>
                                    </div>
                                    <div className="text-xs font-bold text-slate-300">{formatCurrency(bill.amount)}/mo</div>
                                </div>
                            ))
                        ) : (
                            <p className="text-[10px] text-slate-500 italic">No subscriptions detected.</p>
                        )}
                    </div>
                </div>

            </div>
        </div>
    </div>
  );
};

export default Dashboard;

import React, { useMemo } from 'react';
import { AreaChart, Area, LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, PieChart, Pie, Cell } from 'recharts';
import { Account, Transaction, TransactionType, Category, UserPlan, Goal, Budget, SpendingStatus, SpendingPeriod } from '../types';
import { Activity, Flame, TrendingUp, Wallet, PlusCircle, CreditCard, Target, Quote, Landmark, Zap, Radio, Repeat, Check, Copy, X, Loader2, Sparkles, ArrowUpRight, ArrowDownRight, LayoutGrid, ArrowRight, Pin, Square, CheckSquare, Microscope, PieChart as PieChartIcon, ShieldAlert, BrainCircuit, GripVertical, AlertTriangle, Layers, Circle, Trophy, MessageSquare, Handshake, FileText, ChevronRight, Clock, ChevronDown } from 'lucide-react';

interface DashboardProps {
  accounts: Account[];
  transactions: Transaction[];
  goals: Goal[];
  budgets: Budget[];
  onNavigate: (tab: string) => void;
  onAddAccount?: () => void;
  onAddTransaction?: () => void;
  onAddGoal?: () => void;
  formatCurrency: (amount: number) => string | React.ReactNode;
  userPlan?: UserPlan;
  onAskCoach?: (message: string) => void;
  isPinMode?: boolean;
  pinnedIds?: string[];
  onTogglePin?: (id: string) => void;
  trackEvent?: (id: string) => void;
  insightUsage?: number;
  spendingStatus?: SpendingStatus;
  currentPeriodSpend?: number;
  spendingLimit?: number;
  spendingPeriod?: SpendingPeriod;
}

const COLORS = ['#3b82f6', '#f97316', '#10b981', '#8b5cf6', '#06b6d4', '#ec4899', '#64748b'];

const Dashboard: React.FC<DashboardProps> = ({ 
    accounts, 
    transactions, 
    goals, 
    budgets,
    onNavigate, 
    onAddAccount, 
    onAddTransaction, 
    onAddGoal, 
    formatCurrency, 
    userPlan, 
    onAskCoach, 
    insightUsage = 0,
    spendingStatus,
    currentPeriodSpend = 0,
    spendingLimit = 1000,
    spendingPeriod = 'monthly'
}) => {
  const today = new Date();
  const currentMonth = today.getMonth();
  const currentYear = today.getFullYear();
  const currentMonthName = today.toLocaleDateString('en-US', { month: 'long' });
  const dayName = today.toLocaleDateString('en-US', { weekday: 'long' });
  const userName = localStorage.getItem('nova_user_name') || 'User';

  // --- Data Calculations ---

  const netWorth = useMemo(() => accounts.reduce((acc, curr) => acc + curr.balance, 0), [accounts]);

  // Estimate credit card balance (sum of negative balances on Credit Card types)
  const creditCardBalance = useMemo(() => {
      return accounts
        .filter(a => a.type === 'Credit Card')
        .reduce((acc, curr) => acc + (curr.balance < 0 ? Math.abs(curr.balance) : 0), 0);
  }, [accounts]);

  const stats = useMemo(() => {
    const currentMTDExpenses = transactions.filter(t => {
      const d = new Date(t.date);
      return t.type === TransactionType.EXPENSE && d.getMonth() === currentMonth && d.getFullYear() === currentYear;
    });
    const currentMTDTotal = currentMTDExpenses.reduce((acc, t) => acc + t.amount, 0);
    const currentDay = today.getDate();
    const currentDailyAvg = currentMTDTotal / Math.max(currentDay, 1);

    return { currentDailyAvg };
  }, [transactions, currentMonth, currentYear]);

  const expenditureData = useMemo(() => {
    const expenses = transactions.filter(t => 
        t.type === TransactionType.EXPENSE && 
        new Date(t.date).getMonth() === currentMonth &&
        new Date(t.date).getFullYear() === currentYear
    );

    const total = expenses.reduce((acc, t) => acc + t.amount, 0);
    const catMap: Record<string, number> = {};

    expenses.forEach(t => {
        catMap[t.category] = (catMap[t.category] || 0) + t.amount;
    });

    const chartData = Object.entries(catMap)
        .map(([name, value]) => ({ name, value }))
        .sort((a, b) => b.value - a.value);

    // If no data, provide placeholder for visual fidelity
    if (chartData.length === 0) {
        return { chartData: [{ name: 'No Data', value: 1 }], total: 0, isEmpty: true };
    }

    return { chartData, total, isEmpty: false };
  }, [transactions, currentMonth, currentYear]);

  const lineChartData = useMemo(() => {
    const daysInCurrentMonth = new Date(currentYear, currentMonth + 1, 0).getDate();
    const data = [];

    // Simulate "Last Year" data for visual fidelity as requested in sketch
    const getDailySpend = (month: number, year: number, randomize = false) => {
        const daily = new Array(32).fill(0);
        if (randomize) {
             let accum = 0;
             for(let i=1; i<=31; i++) {
                 accum += Math.random() * 50 + 20;
                 daily[i] = accum;
             }
             return daily;
        }

        transactions.forEach(t => {
            const d = new Date(t.date);
            if (t.type === TransactionType.EXPENSE && d.getMonth() === month && d.getFullYear() === year) {
                daily[d.getDate()] += t.amount;
            }
        });
        // Cumulative
        for (let i = 1; i < daily.length; i++) daily[i] += daily[i-1];
        return daily;
    };

    const currentMonthData = getDailySpend(currentMonth, currentYear);
    // Use simulated data for "Last Year" to match the graph curve in the sketch if no real data
    const lastYearData = getDailySpend(currentMonth, currentYear - 1, true);

    for (let i = 1; i <= daysInCurrentMonth; i++) {
        data.push({
            day: i,
            ThisMonth: currentMonthData[i],
            LastYear: lastYearData[i] 
        });
    }
    return data;
  }, [transactions, currentMonth, currentYear]);

  const recurringBills = useMemo(() => {
      const subs = transactions.filter(t => t.category === Category.SUBSCRIPTION);
      const unique = new Map();
      subs.forEach(t => {
          if (!unique.has(t.merchant)) unique.set(t.merchant, t);
      });
      return Array.from(unique.values()).slice(0, 3);
  }, [transactions]);

  const recentTransactions = useMemo(() => {
      return transactions.slice(0, 4);
  }, [transactions]);

  // Goal Vector Logic
  const goalMetrics = useMemo(() => {
      const totalGoalTarget = goals.reduce((acc, g) => acc + g.targetAmount, 0);
      const totalGoalCurrent = goals.reduce((acc, g) => acc + g.currentAmount, 0);
      const goalProgress = totalGoalTarget > 0 ? (totalGoalCurrent / totalGoalTarget) * 100 : 30; // Default 30 for visual if empty

      const budgetUtilization = spendingLimit > 0 ? (currentPeriodSpend / spendingLimit) * 100 : 0;

      return { totalGoalCurrent, totalGoalTarget, goalProgress, budgetUtilization };
  }, [goals, currentPeriodSpend, spendingLimit]);

  const neuralCapacity = userPlan === 'ultra' ? 1500 : userPlan === 'pro' ? 50 : 3;
  const neuralRemaining = Math.max(0, neuralCapacity - insightUsage);

  return (
    <div className="h-full overflow-y-auto custom-scrollbar pb-20 px-2 md:px-0">

        {/* Header */}
        <div className="mb-6 mt-2">
            <h1 className="text-2xl md:text-3xl font-black text-white uppercase tracking-tight">Good {dayName}, {userName}</h1>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">

            {/* LEFT MAIN PANEL (Span 8) */}
            <div className="lg:col-span-8 flex flex-col gap-6">

                {/* 1. Spending Categorization (Pie Chart) */}
                <div className="glass-card p-6 md:p-8 rounded-[2.5rem] border border-white/5 bg-[#0f172a]/60 backdrop-blur-xl relative overflow-hidden flex flex-col md:flex-row items-center gap-8 min-h-[300px]">
                    {/* Donut Chart */}
                    <div className="w-48 h-48 md:w-56 md:h-56 relative shrink-0">
                        <ResponsiveContainer width="100%" height="100%">
                            <PieChart>
                                <Pie
                                    data={expenditureData.chartData}
                                    cx="50%"
                                    cy="50%"
                                    innerRadius={60}
                                    outerRadius={90}
                                    paddingAngle={0}
                                    dataKey="value"
                                    stroke="none"
                                >
                                    {expenditureData.chartData.map((entry, index) => (
                                        <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                                    ))}
                                </Pie>
                                <Tooltip 
                                    contentStyle={{ backgroundColor: '#020617', border: 'none', borderRadius: '12px', padding: '8px' }} 
                                    itemStyle={{ color: '#fff', fontSize: '12px', fontWeight: 'bold' }} 
                                    formatter={(v: number) => formatCurrency(v)} 
                                />
                            </PieChart>
                        </ResponsiveContainer>
                    </div>

                    {/* Legend / Text Area */}
                    <div className="flex-1 w-full">
                        <div className="flex justify-between items-start mb-6">
                            <h3 className="text-sm font-black text-slate-400 uppercase tracking-widest">Spending Categorization For {currentMonthName}</h3>
                        </div>

                        <div className="space-y-4">
                            {/* Legend Items replicating lines in sketch */}
                            {expenditureData.chartData.slice(0, 3).map((item, i) => (
                                <div key={i} className="flex items-center justify-between group">
                                    <div className="flex items-center gap-3">
                                        <div className="w-3 h-3 rounded-full" style={{ backgroundColor: COLORS[i % COLORS.length] }}></div>
                                        <span className="text-sm font-bold text-slate-300 group-hover:text-white transition-colors">{item.name}</span>
                                    </div>
                                    <div className="h-1 flex-1 mx-4 bg-slate-800/50 rounded-full overflow-hidden">
                                        <div className="h-full rounded-full" style={{ width: '40%', backgroundColor: COLORS[i % COLORS.length], opacity: 0.5 }}></div>
                                    </div>
                                    <span className="text-xs font-bold text-slate-500">This Month</span>
                                </div>
                            ))}
                            {/* Fake "Last Month" comparison line for visual matching */}
                            <div className="flex items-center justify-between opacity-50">
                                 <div className="flex items-center gap-3">
                                    <div className="w-3 h-3 rounded-full bg-slate-600"></div>
                                    <span className="text-sm font-bold text-slate-400">Previous Period</span>
                                </div>
                                <div className="h-1 flex-1 mx-4 bg-slate-800/50 rounded-full"></div>
                                <span className="text-xs font-bold text-slate-600">Last Month</span>
                            </div>
                        </div>
                    </div>
                </div>

                {/* 2. Middle Row: Stats + Transactions */}
                <div className="grid grid-cols-1 md:grid-cols-12 gap-6">

                    {/* Left Sub-Col: Small Cards (Span 4) */}
                    <div className="md:col-span-4 flex flex-col gap-6">
                        {/* Burn Rate */}
                        <div className="glass-card p-6 rounded-[2rem] border border-white/5 bg-slate-900/60 flex flex-col justify-center min-h-[140px]">
                            <div className="flex items-center gap-2 mb-2">
                                <Flame className="w-4 h-4 text-orange-500" />
                                <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Burn Rate/Day</span>
                            </div>
                            <div className="text-3xl font-black text-white">{formatCurrency(stats.currentDailyAvg)}</div>
                        </div>

                        {/* Remaining Capacity */}
                        <div className="glass-card p-6 rounded-[2rem] border border-white/5 bg-slate-900/60 flex flex-col justify-center min-h-[140px]">
                            <div className="flex items-center gap-2 mb-2">
                                <Zap className="w-4 h-4 text-purple-500" />
                                <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Remaining Capacity</span>
                            </div>
                            <div className="text-xl font-black text-white">{neuralRemaining} <span className="text-[10px] text-slate-500 uppercase">Tokens Left</span></div>
                        </div>
                    </div>

                    {/* Right Sub-Col: Transactions (Span 8) */}
                    <div className="md:col-span-8 glass-card rounded-[2.5rem] border border-white/5 bg-slate-50 p-6 text-slate-900 overflow-hidden flex flex-col">
                        <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest mb-4">My Recent Transactions</h3>

                        <div className="flex-1 w-full">
                            <table className="w-full text-left border-collapse">
                                <thead className="text-[9px] font-black text-slate-400 uppercase tracking-widest border-b border-slate-200">
                                    <tr>
                                        <th className="py-2">Date</th>
                                        <th className="py-2">Name</th>
                                        <th className="py-2 text-right">Amount</th>
                                    </tr>
                                </thead>
                                <tbody className="text-xs font-bold text-slate-700">
                                    {recentTransactions.map((t) => (
                                        <tr key={t.id} className="border-b border-slate-100 last:border-0">
                                            <td className="py-4 text-slate-400 font-mono text-[10px]">{new Date(t.date).toLocaleDateString('en-US', { month: 'short', day: 'numeric' }).toUpperCase()}</td>
                                            <td className="py-4">{t.merchant}</td>
                                            <td className="py-4 text-right">{formatCurrency(t.amount)}</td>
                                        </tr>
                                    ))}
                                    {recentTransactions.length === 0 && (
                                        <tr><td colSpan={3} className="py-8 text-center text-slate-400 italic">No recent activity.</td></tr>
                                    )}
                                </tbody>
                            </table>
                        </div>
                    </div>
                </div>

                {/* 3. Spending Graph */}
                <div className="glass-card p-8 rounded-[2.5rem] border border-white/5 bg-slate-50 text-slate-900 h-[280px] flex flex-col">
                    <div className="flex justify-between items-center mb-2">
                        <h3 className="text-sm font-black text-slate-500 uppercase tracking-widest">Spending</h3>
                        <div className="flex items-center gap-1 border border-slate-300 rounded px-2 py-1 bg-white cursor-pointer">
                            <span className="text-[10px] font-bold text-slate-600 uppercase">This month vs. last year</span>
                            <ChevronDown className="w-3 h-3 text-slate-400" />
                        </div>
                    </div>
                    <div className="flex-1 w-full min-h-0 relative">
                        <ResponsiveContainer width="100%" height="100%">
                            <LineChart data={lineChartData}>
                                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                                <Tooltip 
                                    contentStyle={{ backgroundColor: '#fff', border: '1px solid #e2e8f0', borderRadius: '8px', boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.1)' }} 
                                    itemStyle={{ fontSize: '11px', fontWeight: 'bold', color: '#0f172a' }}
                                    formatter={(v: number) => formatCurrency(v)}
                                />
                                <Line type="monotone" dataKey="LastYear" stroke="#94a3b8" strokeWidth={2} dot={false} strokeDasharray="5 5" />
                                <Line type="monotone" dataKey="ThisMonth" stroke="#6366f1" strokeWidth={3} dot={false} />
                            </LineChart>
                        </ResponsiveContainer>
                    </div>
                    <div className="flex justify-center gap-6 mt-2">
                        <div className="flex items-center gap-2">
                            <div className="w-2 h-2 rounded-full bg-slate-400"></div>
                            <span className="text-[10px] font-bold text-slate-400 uppercase">Month Last Year</span>
                        </div>
                        <div className="flex items-center gap-2">
                            <div className="w-2 h-2 rounded-full bg-indigo-500"></div>
                            <span className="text-[10px] font-bold text-indigo-500 uppercase">This Month</span>
                        </div>
                    </div>
                </div>

            </div>

            {/* RIGHT SIDEBAR (Span 4) */}
            <div className="lg:col-span-4 flex flex-col gap-6">

                {/* Goal Vector */}
                <div 
                    className="glass-card p-8 rounded-[2.5rem] border border-white/5 bg-slate-200 text-slate-900 relative overflow-hidden cursor-pointer hover:shadow-xl transition-all"
                    onClick={() => onNavigate('goals')}
                >
                    <div className="flex items-center gap-6 mb-6">
                        {/* Circular Progress SVG */}
                        <div className="relative w-16 h-16 flex items-center justify-center">
                            <svg className="w-full h-full -rotate-90">
                                <circle cx="32" cy="32" r="28" fill="none" stroke="#cbd5e1" strokeWidth="6" />
                                <circle cx="32" cy="32" r="28" fill="none" stroke="#3b82f6" strokeWidth="6" strokeDasharray="175" strokeDashoffset={175 - (175 * goalMetrics.goalProgress) / 100} strokeLinecap="round" />
                            </svg>
                            <span className="absolute text-xs font-black text-slate-900">{goalMetrics.goalProgress.toFixed(0)}%</span>
                        </div>
                        <div>
                            <div className="flex justify-between items-start w-full gap-4">
                                <h3 className="text-xs font-black text-slate-500 uppercase tracking-widest">Goal Vector</h3>
                                <span className="bg-slate-300 text-slate-600 text-[8px] font-bold px-2 py-0.5 rounded">Status</span>
                            </div>
                            <div className="text-xl font-black text-slate-900">{formatCurrency(goalMetrics.totalGoalTarget > 0 ? goalMetrics.totalGoalTarget : 12500)}</div>
                        </div>
                    </div>

                    {/* Progress Lines */}
                    <div className="space-y-3 mb-6">
                        <div className="h-1 w-full bg-slate-300 rounded-full overflow-hidden"><div className="h-full bg-blue-500 w-full rounded-full"></div></div>
                        <div className="h-1 w-full bg-slate-300 rounded-full overflow-hidden"><div className="h-full bg-slate-400 w-[70%] rounded-full"></div></div>
                        <div className="h-1 w-full bg-slate-300 rounded-full overflow-hidden"><div className="h-full bg-slate-400 w-[40%] rounded-full"></div></div>
                    </div>

                    <div className="p-4 bg-white rounded-xl shadow-sm border border-slate-100">
                        <p className="text-[10px] text-slate-500 font-bold leading-tight uppercase">
                            Check the duration estimated to achieve your goal.
                        </p>
                    </div>
                </div>

                {/* Net Worth & Credit Card */}
                <div className="grid grid-cols-2 gap-4">
                    <div className="bg-white p-5 rounded-[2rem] shadow-sm flex flex-col justify-between h-32 border border-slate-100">
                        <div className="flex justify-between items-start">
                            <span className="text-[10px] font-black text-slate-400 uppercase tracking-wider">Net Worth</span>
                            <Wallet className="w-4 h-4 text-blue-500" />
                        </div>
                        <div className="text-slate-900 font-black text-sm truncate">{formatCurrency(netWorth)}</div>
                    </div>
                    <div className="bg-white p-5 rounded-[2rem] shadow-sm flex flex-col justify-between h-32 border border-slate-100">
                        <div className="flex justify-between items-start">
                            <div className="flex flex-col">
                                <span className="text-[10px] font-black text-slate-400 uppercase tracking-wider">Credit Card</span>
                                <span className="text-[9px] font-bold text-slate-300">Balance</span>
                            </div>
                            <CreditCard className="w-4 h-4 text-slate-400" />
                        </div>
                        <div className="text-slate-900 font-black text-sm truncate">{formatCurrency(creditCardBalance)}</div>
                    </div>
                </div>

                {/* Actions List */}
                <div className="space-y-3">
                    <button onClick={() => onAskCoach && onAskCoach("Overview.")} className="w-full p-4 bg-white text-slate-900 rounded-2xl text-[10px] font-black uppercase tracking-widest flex justify-between items-center shadow-sm hover:bg-slate-50 transition-colors border border-slate-100">
                        Financial Overview <ChevronDown className="w-4 h-4 text-slate-400" />
                    </button>
                    <button onClick={() => onNavigate('sandbox')} className="w-full p-4 bg-white text-slate-900 rounded-2xl text-[10px] font-black uppercase tracking-widest flex justify-between items-center shadow-sm hover:bg-slate-50 transition-colors border border-slate-100">
                        Smart Money Tools <ChevronDown className="w-4 h-4 text-slate-400" />
                    </button>
                    <div className="grid grid-cols-2 gap-3">
                        <button onClick={() => onNavigate('negotiator')} className="p-4 bg-white text-slate-900 rounded-2xl text-[9px] font-black uppercase tracking-widest shadow-sm hover:bg-slate-50 transition-colors border border-slate-100 text-center">
                            Negotiate My Bill
                        </button>
                        <button onClick={() => onAskCoach && onAskCoach("Summarize actions.")} className="p-4 bg-blue-500 text-white rounded-2xl text-[9px] font-black uppercase tracking-widest shadow-lg shadow-blue-500/30 hover:bg-blue-600 transition-colors text-center">
                            Summarize Action For Today
                        </button>
                    </div>
                    <button onClick={() => onNavigate('accounts')} className="w-full p-4 bg-white text-slate-900 rounded-2xl text-[10px] font-black uppercase tracking-widest flex justify-between items-center shadow-sm hover:bg-slate-50 transition-colors border border-slate-100">
                        Investment <ChevronDown className="w-4 h-4 text-slate-400" />
                    </button>
                </div>

                {/* Recurring Bills */}
                <div className="bg-white p-6 rounded-[2.5rem] shadow-sm border border-slate-100 mt-auto">
                    <div className="flex justify-between items-center mb-6">
                        <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest">My Recurring Bill</h3>
                        <span className="px-2 py-1 rounded bg-slate-100 text-[8px] font-bold text-slate-500 uppercase">This Month</span>
                    </div>
                    <div className="space-y-4">
                        {recurringBills.length > 0 ? (
                            recurringBills.map(bill => (
                                <div key={bill.id} className="flex items-center gap-3">
                                    <div className={`w-8 h-8 rounded-full flex items-center justify-center text-[10px] font-black text-white ${bill.merchant.toLowerCase().includes('netflix') ? 'bg-red-600' : bill.merchant.toLowerCase().includes('spotify') ? 'bg-green-500' : 'bg-slate-900'}`}>
                                        {bill.merchant.charAt(0)}
                                    </div>
                                    <div className="flex-1 flex justify-between items-center">
                                        <span className="text-xs font-bold text-slate-900">{bill.merchant}</span>
                                        <span className="text-xs font-bold text-slate-500">{formatCurrency(bill.amount)}/mo</span>
                                    </div>
                                </div>
                            ))
                        ) : (
                            <div className="flex items-center gap-3 opacity-50">
                                <div className="w-8 h-8 rounded-full bg-red-600 flex items-center justify-center text-white font-bold text-[10px]">N</div>
                                <div className="flex-1 flex justify-between items-center">
                                    <span className="text-xs font-bold text-slate-900">Netflix</span>
                                    <span className="text-xs font-bold text-slate-500">$15.99/mo</span>
                                </div>
                            </div>
                        )}
                    </div>
                </div>

            </div>
        </div>
    </div>
  );
};

export default Dashboard;

import React, { useMemo } from 'react';
import { AreaChart, Area, LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, PieChart, Pie, Cell } from 'recharts';
import { Account, Transaction, TransactionType, Category, UserPlan, Goal, Budget, SpendingStatus, SpendingPeriod } from '../types';
import { Activity, Flame, TrendingUp, Wallet, PlusCircle, CreditCard, Target, Quote, Landmark, Zap, Radio, Repeat, Check, Copy, X, Loader2, Sparkles, ArrowUpRight, ArrowDownRight, LayoutGrid, ArrowRight, Pin, Square, CheckSquare, Microscope, PieChart as PieChartIcon, ShieldAlert, BrainCircuit, GripVertical, AlertTriangle, Layers, Circle, Trophy, MessageSquare, Handshake, FileText, ChevronRight, Clock, ChevronDown, AlignLeft } from 'lucide-react';

interface DashboardProps {
  accounts: Account[];
  transactions: Transaction[];
  goals: Goal[];
  budgets: Budget[];
  onNavigate: (tab: string) => void;
  onAddAccount?: () => void;
  onAddTransaction?: () => void;
  onAddGoal?: () => void;
  formatCurrency: (amount: number) => string | React.ReactNode;
  userPlan?: UserPlan;
  onAskCoach?: (message: string) => void;
  isPinMode?: boolean;
  pinnedIds?: string[];
  onTogglePin?: (id: string) => void;
  trackEvent?: (id: string) => void;
  insightUsage?: number;
  spendingStatus?: SpendingStatus;
  currentPeriodSpend?: number;
  spendingLimit?: number;
  spendingPeriod?: SpendingPeriod;
}

const COLORS = ['#3b82f6', '#f97316', '#10b981', '#8b5cf6', '#06b6d4', '#ec4899', '#64748b'];

const Dashboard: React.FC<DashboardProps> = ({ 
    accounts, 
    transactions, 
    goals, 
    budgets,
    onNavigate, 
    onAddAccount, 
    onAddTransaction, 
    onAddGoal, 
    formatCurrency, 
    userPlan, 
    onAskCoach, 
    insightUsage = 0,
    spendingStatus,
    currentPeriodSpend = 0,
    spendingLimit = 1000,
    spendingPeriod = 'monthly'
}) => {
  const today = new Date();
  const currentMonth = today.getMonth();
  const currentYear = today.getFullYear();
  const currentMonthName = today.toLocaleDateString('en-US', { month: 'long' });
  const dayName = today.toLocaleDateString('en-US', { weekday: 'long' });
  const userName = localStorage.getItem('nova_user_name') || 'User';

  // --- Data Calculations ---

  const netWorth = useMemo(() => accounts.reduce((acc, curr) => acc + curr.balance, 0), [accounts]);

  // Estimate credit card balance (sum of negative balances on Credit Card types)
  const creditCardBalance = useMemo(() => {
      return accounts
        .filter(a => a.type === 'Credit Card')
        .reduce((acc, curr) => acc + (curr.balance < 0 ? Math.abs(curr.balance) : 0), 0);
  }, [accounts]);

  const stats = useMemo(() => {
    const currentMTDExpenses = transactions.filter(t => {
      const d = new Date(t.date);
      return t.type === TransactionType.EXPENSE && d.getMonth() === currentMonth && d.getFullYear() === currentYear;
    });
    const currentMTDTotal = currentMTDExpenses.reduce((acc, t) => acc + t.amount, 0);
    const currentDay = today.getDate();
    const currentDailyAvg = currentMTDTotal / Math.max(currentDay, 1);

    return { currentDailyAvg };
  }, [transactions, currentMonth, currentYear]);

  const expenditureData = useMemo(() => {
    const expenses = transactions.filter(t => 
        t.type === TransactionType.EXPENSE && 
        new Date(t.date).getMonth() === currentMonth &&
        new Date(t.date).getFullYear() === currentYear
    );

    const total = expenses.reduce((acc, t) => acc + t.amount, 0);
    const catMap: Record<string, number> = {};

    expenses.forEach(t => {
        catMap[t.category] = (catMap[t.category] || 0) + t.amount;
    });

    const chartData = Object.entries(catMap)
        .map(([name, value]) => ({ name, value }))
        .sort((a, b) => b.value - a.value);

    // If no data, provide placeholder for visual fidelity
    if (chartData.length === 0) {
        return { chartData: [{ name: 'No Data', value: 1 }], total: 0, isEmpty: true, topCategory: null };
    }

    const topCategory = chartData[0];

    return { chartData, total, isEmpty: false, topCategory };
  }, [transactions, currentMonth, currentYear]);

  const lineChartData = useMemo(() => {
    const daysInCurrentMonth = new Date(currentYear, currentMonth + 1, 0).getDate();
    const data = [];

    // Simulate "Last Year" data for visual fidelity as requested in sketch
    const getDailySpend = (month: number, year: number, randomize = false) => {
        const daily = new Array(32).fill(0);
        if (randomize) {
             let accum = 0;
             for(let i=1; i<=31; i++) {
                 accum += Math.random() * 50 + 20;
                 daily[i] = accum;
             }
             return daily;
        }

        transactions.forEach(t => {
            const d = new Date(t.date);
            if (t.type === TransactionType.EXPENSE && d.getMonth() === month && d.getFullYear() === year) {
                daily[d.getDate()] += t.amount;
            }
        });
        // Cumulative
        for (let i = 1; i < daily.length; i++) daily[i] += daily[i-1];
        return daily;
    };

    const currentMonthData = getDailySpend(currentMonth, currentYear);
    // Use simulated data for "Last Year" to match the graph curve in the sketch if no real data
    const lastYearData = getDailySpend(currentMonth, currentYear - 1, true);

    for (let i = 1; i <= daysInCurrentMonth; i++) {
        data.push({
            day: i,
            ThisMonth: currentMonthData[i],
            LastYear: lastYearData[i] 
        });
    }
    return data;
  }, [transactions, currentMonth, currentYear]);

  const recurringBills = useMemo(() => {
      const subs = transactions.filter(t => t.category === Category.SUBSCRIPTION);
      const unique = new Map();
      subs.forEach(t => {
          if (!unique.has(t.merchant)) unique.set(t.merchant, t);
      });
      return Array.from(unique.values()).slice(0, 3);
  }, [transactions]);

  const recentTransactions = useMemo(() => {
      return transactions.slice(0, 4);
  }, [transactions]);

  // Goal Vector Logic
  const goalMetrics = useMemo(() => {
      const totalGoalTarget = goals.reduce((acc, g) => acc + g.targetAmount, 0);
      const totalGoalCurrent = goals.reduce((acc, g) => acc + g.currentAmount, 0);
      const goalProgress = totalGoalTarget > 0 ? (totalGoalCurrent / totalGoalTarget) * 100 : 30; // Default 30 for visual if empty

      const budgetUtilization = spendingLimit > 0 ? (currentPeriodSpend / spendingLimit) * 100 : 0;

      return { totalGoalCurrent, totalGoalTarget, goalProgress, budgetUtilization };
  }, [goals, currentPeriodSpend, spendingLimit]);

  const neuralCapacity = userPlan === 'ultra' ? 1500 : userPlan === 'pro' ? 50 : 3;
  const neuralRemaining = Math.max(0, neuralCapacity - insightUsage);

  return (
    <div className="h-full overflow-y-auto custom-scrollbar pb-20 px-2 md:px-0">

        {/* Header */}
        <div className="mb-6 mt-2">
            <h1 className="text-2xl md:text-3xl font-black text-white uppercase tracking-tight">Good {dayName}, {userName}</h1>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">

            {/* LEFT MAIN PANEL (Span 8) */}
            <div className="lg:col-span-8 flex flex-col gap-6">

                {/* 1. Expenditure Topology (Pie Chart) */}
                <div className="glass-card p-6 md:p-8 rounded-[2.5rem] border border-white/5 bg-[#0f172a]/60 backdrop-blur-xl relative overflow-hidden flex flex-col md:flex-row items-center gap-8 min-h-[300px]">
                    {/* Donut Chart */}
                    <div className="w-48 h-48 md:w-56 md:h-56 relative shrink-0">
                        <ResponsiveContainer width="100%" height="100%">
                            <PieChart>
                                <Pie
                                    data={expenditureData.chartData}
                                    cx="50%"
                                    cy="50%"
                                    innerRadius={60}
                                    outerRadius={90}
                                    paddingAngle={2}
                                    dataKey="value"
                                    stroke="none"
                                >
                                    {expenditureData.chartData.map((entry, index) => (
                                        <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                                    ))}
                                </Pie>
                                <Tooltip 
                                    contentStyle={{ backgroundColor: '#020617', border: 'none', borderRadius: '12px', padding: '8px' }} 
                                    itemStyle={{ color: '#fff', fontSize: '12px', fontWeight: 'bold' }} 
                                    formatter={(v: number) => formatCurrency(v)} 
                                />
                            </PieChart>
                        </ResponsiveContainer>
                    </div>

                    {/* Legend / Text Area */}
                    <div className="flex-1 w-full">
                        <div className="flex justify-between items-start mb-6">
                            <h3 className="text-sm font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
                                <AlignLeft className="w-4 h-4 text-indigo-500" />
                                Expenditure Topology
                            </h3>
                        </div>

                        {expenditureData.topCategory && (
                            <div className="mb-6 p-4 rounded-2xl bg-indigo-500/10 border border-indigo-500/20 flex items-center justify-between">
                                <div>
                                    <span className="text-[10px] font-black text-indigo-400 uppercase tracking-widest block mb-1">Primary Drain</span>
                                    <span className="text-lg font-bold text-white">{expenditureData.topCategory.name}</span>
                                </div>
                                <div className="text-right">
                                    <span className="text-xl font-black text-white">{formatCurrency(expenditureData.topCategory.value)}</span>
                                    <span className="text-[10px] font-bold text-slate-400 block">{((expenditureData.topCategory.value / expenditureData.total) * 100).toFixed(1)}%</span>
                                </div>
                            </div>
                        )}

                        <div className="space-y-3">
                            {/* Legend Items replicating lines in sketch */}
                            {expenditureData.chartData.slice(0, 3).map((item, i) => (
                                <div key={i} className="flex items-center justify-between group">
                                    <div className="flex items-center gap-3">
                                        <div className="w-2.5 h-2.5 rounded-full" style={{ backgroundColor: COLORS[i % COLORS.length] }}></div>
                                        <span className="text-xs font-bold text-slate-300 group-hover:text-white transition-colors">{item.name}</span>
                                    </div>
                                    <div className="h-1 flex-1 mx-4 bg-slate-800/50 rounded-full overflow-hidden">
                                        <div className="h-full rounded-full transition-all duration-1000" style={{ width: `${(item.value / expenditureData.total) * 60}%`, backgroundColor: COLORS[i % COLORS.length], opacity: 0.6 }}></div>
                                    </div>
                                    <span className="text-[10px] font-bold text-slate-500">This Month</span>
                                </div>
                            ))}
                        </div>
                    </div>
                </div>

                {/* 2. Middle Row: Stats + Transactions */}
                <div className="grid grid-cols-1 md:grid-cols-12 gap-6">

                    {/* Left Sub-Col: Small Cards (Span 4) */}
                    <div className="md:col-span-4 flex flex-col gap-6">
                        {/* Burn Rate */}
                        <div className="glass-card p-6 rounded-[2rem] border border-white/5 bg-slate-900/60 flex flex-col justify-center min-h-[140px]">
                            <div className="flex items-center gap-2 mb-2">
                                <Flame className="w-4 h-4 text-orange-500" />
                                <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Burn Rate/Day</span>
                            </div>
                            <div className="text-3xl font-black text-white">{formatCurrency(stats.currentDailyAvg)}</div>
                        </div>

                        {/* Remaining Capacity */}
                        <div className="glass-card p-6 rounded-[2rem] border border-white/5 bg-slate-900/60 flex flex-col justify-center min-h-[140px]">
                            <div className="flex items-center gap-2 mb-2">
                                <Zap className="w-4 h-4 text-purple-500" />
                                <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Remaining Capacity</span>
                            </div>
                            <div className="text-xl font-black text-white">{neuralRemaining} <span className="text-[10px] text-slate-500 uppercase">Tokens Left</span></div>
                        </div>
                    </div>

                    {/* Right Sub-Col: Transactions (Span 8) */}
                    <div className="md:col-span-8 glass-card rounded-[2.5rem] border border-white/5 bg-slate-50 p-6 text-slate-900 overflow-hidden flex flex-col">
                        <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest mb-4">My Recent Transactions</h3>

                        <div className="flex-1 w-full">
                            <table className="w-full text-left border-collapse">
                                <thead className="text-[9px] font-black text-slate-400 uppercase tracking-widest border-b border-slate-200">
                                    <tr>
                                        <th className="py-2">Date</th>
                                        <th className="py-2">Name</th>
                                        <th className="py-2 text-right">Amount</th>
                                    </tr>
                                </thead>
                                <tbody className="text-xs font-bold text-slate-700">
                                    {recentTransactions.map((t) => (
                                        <tr key={t.id} className="border-b border-slate-100 last:border-0">
                                            <td className="py-4 text-slate-400 font-mono text-[10px]">{new Date(t.date).toLocaleDateString('en-US', { month: 'short', day: 'numeric' }).toUpperCase()}</td>
                                            <td className="py-4">{t.merchant}</td>
                                            <td className="py-4 text-right">{formatCurrency(t.amount)}</td>
                                        </tr>
                                    ))}
                                    {recentTransactions.length === 0 && (
                                        <tr><td colSpan={3} className="py-8 text-center text-slate-400 italic">No recent activity.</td></tr>
                                    )}
                                </tbody>
                            </table>
                        </div>
                    </div>
                </div>

                {/* 3. Spending Graph */}
                <div className="glass-card p-8 rounded-[2.5rem] border border-white/5 bg-slate-50 text-slate-900 h-[280px] flex flex-col">
                    <div className="flex justify-between items-center mb-2">
                        <h3 className="text-sm font-black text-slate-500 uppercase tracking-widest">Spending</h3>
                        <div className="flex items-center gap-1 border border-slate-300 rounded px-2 py-1 bg-white cursor-pointer">
                            <span className="text-[10px] font-bold text-slate-600 uppercase">This month vs. last year</span>
                            <ChevronDown className="w-3 h-3 text-slate-400" />
                        </div>
                    </div>
                    <div className="flex-1 w-full min-h-0 relative">
                        <ResponsiveContainer width="100%" height="100%">
                            <LineChart data={lineChartData}>
                                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                                <Tooltip 
                                    contentStyle={{ backgroundColor: '#fff', border: '1px solid #e2e8f0', borderRadius: '8px', boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.1)' }} 
                                    itemStyle={{ fontSize: '11px', fontWeight: 'bold', color: '#0f172a' }}
                                    formatter={(v: number) => formatCurrency(v)}
                                />
                                <Line type="monotone" dataKey="LastYear" stroke="#94a3b8" strokeWidth={2} dot={false} strokeDasharray="5 5" />
                                <Line type="monotone" dataKey="ThisMonth" stroke="#6366f1" strokeWidth={3} dot={false} />
                            </LineChart>
                        </ResponsiveContainer>
                    </div>
                    <div className="flex justify-center gap-6 mt-2">
                        <div className="flex items-center gap-2">
                            <div className="w-2 h-2 rounded-full bg-slate-400"></div>
                            <span className="text-[10px] font-bold text-slate-400 uppercase">Month Last Year</span>
                        </div>
                        <div className="flex items-center gap-2">
                            <div className="w-2 h-2 rounded-full bg-indigo-500"></div>
                            <span className="text-[10px] font-bold text-indigo-500 uppercase">This Month</span>
                        </div>
                    </div>
                </div>

            </div>

            {/* RIGHT SIDEBAR (Span 4) */}
            <div className="lg:col-span-4 flex flex-col gap-6">

                {/* 1. Goal Vector */}
                <div 
                    className="glass-card p-8 rounded-[2.5rem] border border-white/5 bg-slate-200 text-slate-900 relative overflow-hidden cursor-pointer hover:shadow-xl transition-all"
                    onClick={() => onNavigate('goals')}
                >
                    <div className="flex items-center gap-6 mb-6">
                        {/* Circular Progress SVG */}
                        <div className="relative w-16 h-16 flex items-center justify-center">
                            <svg className="w-full h-full -rotate-90">
                                <circle cx="32" cy="32" r="28" fill="none" stroke="#cbd5e1" strokeWidth="6" />
                                <circle cx="32" cy="32" r="28" fill="none" stroke="#3b82f6" strokeWidth="6" strokeDasharray="175" strokeDashoffset={175 - (175 * goalMetrics.goalProgress) / 100} strokeLinecap="round" />
                            </svg>
                            <span className="absolute text-xs font-black text-slate-900">{goalMetrics.goalProgress.toFixed(0)}%</span>
                        </div>
                        <div>
                            <div className="flex justify-between items-start w-full gap-4">
                                <h3 className="text-xs font-black text-slate-500 uppercase tracking-widest">Goal Vector</h3>
                                <span className="bg-slate-300 text-slate-600 text-[8px] font-bold px-2 py-0.5 rounded">Status</span>
                            </div>
                            <div className="text-xl font-black text-slate-900">{formatCurrency(goalMetrics.totalGoalTarget > 0 ? goalMetrics.totalGoalTarget : 12500)}</div>
                        </div>
                    </div>

                    {/* Progress Lines */}
                    <div className="space-y-3 mb-6">
                        <div className="h-1 w-full bg-slate-300 rounded-full overflow-hidden"><div className="h-full bg-blue-500 w-full rounded-full"></div></div>
                        <div className="h-1 w-full bg-slate-300 rounded-full overflow-hidden"><div className="h-full bg-slate-400 w-[70%] rounded-full"></div></div>
                        <div className="h-1 w-full bg-slate-300 rounded-full overflow-hidden"><div className="h-full bg-slate-400 w-[40%] rounded-full"></div></div>
                    </div>

                    <div className="p-4 bg-white rounded-xl shadow-sm border border-slate-100">
                        <p className="text-[10px] text-slate-500 font-bold leading-tight uppercase">
                            Check the duration estimated to achieve your goal.
                        </p>
                    </div>
                </div>

                {/* 2. Recurring Bills (Moved Up) */}
                <div className="bg-white p-6 rounded-[2.5rem] shadow-sm border border-slate-100">
                    <div className="flex justify-between items-center mb-6">
                        <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest">My Recurring Bill</h3>
                        <span className="px-2 py-1 rounded bg-slate-100 text-[8px] font-bold text-slate-500 uppercase">This Month</span>
                    </div>
                    <div className="space-y-4">
                        {recurringBills.length > 0 ? (
                            recurringBills.map(bill => (
                                <div key={bill.id} className="flex items-center gap-3">
                                    <div className={`w-8 h-8 rounded-full flex items-center justify-center text-[10px] font-black text-white ${bill.merchant.toLowerCase().includes('netflix') ? 'bg-red-600' : bill.merchant.toLowerCase().includes('spotify') ? 'bg-green-500' : 'bg-slate-900'}`}>
                                        {bill.merchant.charAt(0)}
                                    </div>
                                    <div className="flex-1 flex justify-between items-center">
                                        <span className="text-xs font-bold text-slate-900">{bill.merchant}</span>
                                        <span className="text-xs font-bold text-slate-500">{formatCurrency(bill.amount)}/mo</span>
                                    </div>
                                </div>
                            ))
                        ) : (
                            <div className="flex items-center gap-3 opacity-50">
                                <div className="w-8 h-8 rounded-full bg-red-600 flex items-center justify-center text-white font-bold text-[10px]">N</div>
                                <div className="flex-1 flex justify-between items-center">
                                    <span className="text-xs font-bold text-slate-900">Netflix</span>
                                    <span className="text-xs font-bold text-slate-500">$15.99/mo</span>
                                </div>
                            </div>
                        )}
                    </div>
                </div>

                {/* 3. Net Worth & Credit Card */}
                <div className="grid grid-cols-2 gap-4">
                    <div className="bg-white p-5 rounded-[2rem] shadow-sm flex flex-col justify-between h-32 border border-slate-100">
                        <div className="flex justify-between items-start">
                            <span className="text-[10px] font-black text-slate-400 uppercase tracking-wider">Net Worth</span>
                            <Wallet className="w-4 h-4 text-blue-500" />
                        </div>
                        <div className="text-slate-900 font-black text-sm truncate">{formatCurrency(netWorth)}</div>
                    </div>
                    <div className="bg-white p-5 rounded-[2rem] shadow-sm flex flex-col justify-between h-32 border border-slate-100">
                        <div className="flex justify-between items-start">
                            <div className="flex flex-col">
                                <span className="text-[10px] font-black text-slate-400 uppercase tracking-wider">Credit Card</span>
                                <span className="text-[9px] font-bold text-slate-300">Balance</span>
                            </div>
                            <CreditCard className="w-4 h-4 text-slate-400" />
                        </div>
                        <div className="text-slate-900 font-black text-sm truncate">{formatCurrency(creditCardBalance)}</div>
                    </div>
                </div>

                {/* 4. Actions List */}
                <div className="space-y-3">
                    <button onClick={() => onAskCoach && onAskCoach("Overview.")} className="w-full p-4 bg-white text-slate-900 rounded-2xl text-[10px] font-black uppercase tracking-widest flex justify-between items-center shadow-sm hover:bg-slate-50 transition-colors border border-slate-100">
                        Financial Overview <ChevronDown className="w-4 h-4 text-slate-400" />
                    </button>
                    <button onClick={() => onNavigate('sandbox')} className="w-full p-4 bg-white text-slate-900 rounded-2xl text-[10px] font-black uppercase tracking-widest flex justify-between items-center shadow-sm hover:bg-slate-50 transition-colors border border-slate-100">
                        Smart Money Tools <ChevronDown className="w-4 h-4 text-slate-400" />
                    </button>
                    <div className="grid grid-cols-2 gap-3">
                        <button onClick={() => onNavigate('negotiator')} className="p-4 bg-white text-slate-900 rounded-2xl text-[9px] font-black uppercase tracking-widest shadow-sm hover:bg-slate-50 transition-colors border border-slate-100 text-center">
                            Negotiate My Bill
                        </button>
                        <button onClick={() => onAskCoach && onAskCoach("Summarize actions.")} className="p-4 bg-blue-500 text-white rounded-2xl text-[9px] font-black uppercase tracking-widest shadow-lg shadow-blue-500/30 hover:bg-blue-600 transition-colors text-center">
                            Summarize Action For Today
                        </button>
                    </div>
                    <button onClick={() => onNavigate('accounts')} className="w-full p-4 bg-white text-slate-900 rounded-2xl text-[10px] font-black uppercase tracking-widest flex justify-between items-center shadow-sm hover:bg-slate-50 transition-colors border border-slate-100">
                        Investment <ChevronDown className="w-4 h-4 text-slate-400" />
                    </button>
                </div>

            </div>
        </div>
    </div>
  );
};

export default Dashboard;

import React, { useMemo } from 'react';
import { AreaChart, Area, LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, PieChart, Pie, Cell } from 'recharts';
import { Account, Transaction, TransactionType, Category, UserPlan, Goal, Budget, SpendingStatus, SpendingPeriod } from '../types';
import { Activity, Flame, TrendingUp, Wallet, PlusCircle, CreditCard, Target, Quote, Landmark, Zap, Radio, Repeat, Check, Copy, X, Loader2, Sparkles, ArrowUpRight, ArrowDownRight, LayoutGrid, ArrowRight, Pin, Square, CheckSquare, Microscope, PieChart as PieChartIcon, ShieldAlert, BrainCircuit, GripVertical, AlertTriangle, Layers, Circle, Trophy, MessageSquare, Handshake, FileText, ChevronRight, Clock, ChevronDown, AlignLeft } from 'lucide-react';

interface DashboardProps {
  accounts: Account[];
  transactions: Transaction[];
  goals: Goal[];
  budgets: Budget[];
  onNavigate: (tab: string) => void;
  onAddAccount?: () => void;
  onAddTransaction?: () => void;
  onAddGoal?: () => void;
  formatCurrency: (amount: number) => string | React.ReactNode;
  userPlan?: UserPlan;
  onAskCoach?: (message: string) => void;
  isPinMode?: boolean;
  pinnedIds?: string[];
  onTogglePin?: (id: string) => void;
  trackEvent?: (id: string) => void;
  insightUsage?: number;
  spendingStatus?: SpendingStatus;
  currentPeriodSpend?: number;
  spendingLimit?: number;
  spendingPeriod?: SpendingPeriod;
}

const COLORS = ['#3b82f6', '#f97316', '#10b981', '#8b5cf6', '#06b6d4', '#ec4899', '#64748b'];

const Dashboard: React.FC<DashboardProps> = ({ 
    accounts, 
    transactions, 
    goals, 
    budgets,
    onNavigate, 
    onAddAccount, 
    onAddTransaction, 
    onAddGoal, 
    formatCurrency, 
    userPlan, 
    onAskCoach, 
    insightUsage = 0,
    spendingStatus,
    currentPeriodSpend = 0,
    spendingLimit = 1000,
    spendingPeriod = 'monthly'
}) => {
  const today = new Date();
  const currentMonth = today.getMonth();
  const currentYear = today.getFullYear();
  const currentMonthName = today.toLocaleDateString('en-US', { month: 'long' });
  const dayName = today.toLocaleDateString('en-US', { weekday: 'long' });
  const userName = localStorage.getItem('nova_user_name') || 'User';

  // --- Data Calculations ---

  const netWorth = useMemo(() => accounts.reduce((acc, curr) => acc + curr.balance, 0), [accounts]);

  // Estimate credit card balance (sum of negative balances on Credit Card types)
  const creditCardBalance = useMemo(() => {
      return accounts
        .filter(a => a.type === 'Credit Card')
        .reduce((acc, curr) => acc + (curr.balance < 0 ? Math.abs(curr.balance) : 0), 0);
  }, [accounts]);

  const stats = useMemo(() => {
    const currentMTDExpenses = transactions.filter(t => {
      const d = new Date(t.date);
      return t.type === TransactionType.EXPENSE && d.getMonth() === currentMonth && d.getFullYear() === currentYear;
    });
    const currentMTDTotal = currentMTDExpenses.reduce((acc, t) => acc + t.amount, 0);
    const currentDay = today.getDate();
    const currentDailyAvg = currentMTDTotal / Math.max(currentDay, 1);

    return { currentDailyAvg };
  }, [transactions, currentMonth, currentYear]);

  const expenditureData = useMemo(() => {
    const expenses = transactions.filter(t => 
        t.type === TransactionType.EXPENSE && 
        new Date(t.date).getMonth() === currentMonth &&
        new Date(t.date).getFullYear() === currentYear
    );

    const total = expenses.reduce((acc, t) => acc + t.amount, 0);
    const catMap: Record<string, number> = {};

    expenses.forEach(t => {
        catMap[t.category] = (catMap[t.category] || 0) + t.amount;
    });

    const chartData = Object.entries(catMap)
        .map(([name, value]) => ({ name, value }))
        .sort((a, b) => b.value - a.value);

    // If no data, provide placeholder for visual fidelity
    if (chartData.length === 0) {
        return { chartData: [{ name: 'No Data', value: 1 }], total: 0, isEmpty: true, topCategory: null };
    }

    const topCategory = chartData[0];

    return { chartData, total, isEmpty: false, topCategory };
  }, [transactions, currentMonth, currentYear]);

  const lineChartData = useMemo(() => {
    const daysInCurrentMonth = new Date(currentYear, currentMonth + 1, 0).getDate();
    const data = [];

    // Simulate "Last Year" data for visual fidelity as requested in sketch
    const getDailySpend = (month: number, year: number, randomize = false) => {
        const daily = new Array(32).fill(0);
        if (randomize) {
             let accum = 0;
             for(let i=1; i<=31; i++) {
                 accum += Math.random() * 50 + 20;
                 daily[i] = accum;
             }
             return daily;
        }

        transactions.forEach(t => {
            const d = new Date(t.date);
            if (t.type === TransactionType.EXPENSE && d.getMonth() === month && d.getFullYear() === year) {
                daily[d.getDate()] += t.amount;
            }
        });
        // Cumulative
        for (let i = 1; i < daily.length; i++) daily[i] += daily[i-1];
        return daily;
    };

    const currentMonthData = getDailySpend(currentMonth, currentYear);
    // Use simulated data for "Last Year" to match the graph curve in the sketch if no real data
    const lastYearData = getDailySpend(currentMonth, currentYear - 1, true);

    for (let i = 1; i <= daysInCurrentMonth; i++) {
        data.push({
            day: i,
            ThisMonth: currentMonthData[i],
            LastYear: lastYearData[i] 
        });
    }
    return data;
  }, [transactions, currentMonth, currentYear]);

  const recurringBills = useMemo(() => {
      const subs = transactions.filter(t => t.category === Category.SUBSCRIPTION);
      const unique = new Map();
      subs.forEach(t => {
          if (!unique.has(t.merchant)) unique.set(t.merchant, t);
      });
      return Array.from(unique.values()).slice(0, 3);
  }, [transactions]);

  const recentTransactions = useMemo(() => {
      return transactions.slice(0, 4);
  }, [transactions]);

  // Goal Vector Logic
  const goalMetrics = useMemo(() => {
      const totalGoalTarget = goals.reduce((acc, g) => acc + g.targetAmount, 0);
      const totalGoalCurrent = goals.reduce((acc, g) => acc + g.currentAmount, 0);
      const goalProgress = totalGoalTarget > 0 ? (totalGoalCurrent / totalGoalTarget) * 100 : 30; // Default 30 for visual if empty

      const budgetUtilization = spendingLimit > 0 ? (currentPeriodSpend / spendingLimit) * 100 : 0;

      return { totalGoalCurrent, totalGoalTarget, goalProgress, budgetUtilization };
  }, [goals, currentPeriodSpend, spendingLimit]);

  const neuralCapacity = userPlan === 'ultra' ? 1500 : userPlan === 'pro' ? 50 : 3;
  const neuralRemaining = Math.max(0, neuralCapacity - insightUsage);

  return (
    <div className="h-full overflow-y-auto custom-scrollbar pb-20 px-2 md:px-0">

        {/* Header */}
        <div className="mb-6 mt-2">
            <h1 className="text-2xl md:text-3xl font-black text-white uppercase tracking-tight">Good {dayName}, {userName}</h1>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">

            {/* LEFT MAIN PANEL (Span 8) */}
            <div className="lg:col-span-8 flex flex-col gap-6">

                {/* 1. Expenditure Topology (Pie Chart) */}
                <div className="glass-card p-6 md:p-8 rounded-[2.5rem] border border-white/5 bg-[#0f172a]/60 backdrop-blur-xl relative overflow-hidden flex flex-col md:flex-row items-center gap-8 min-h-[300px]">
                    {/* Donut Chart */}
                    <div className="w-48 h-48 md:w-56 md:h-56 relative shrink-0">
                        <ResponsiveContainer width="100%" height="100%">
                            <PieChart>
                                <Pie
                                    data={expenditureData.chartData}
                                    cx="50%"
                                    cy="50%"
                                    innerRadius={60}
                                    outerRadius={90}
                                    paddingAngle={2}
                                    dataKey="value"
                                    stroke="none"
                                >
                                    {expenditureData.chartData.map((entry, index) => (
                                        <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                                    ))}
                                </Pie>
                                <Tooltip 
                                    contentStyle={{ backgroundColor: '#020617', border: '1px solid rgba(255,255,255,0.1)', borderRadius: '12px', padding: '8px' }} 
                                    itemStyle={{ color: '#fff', fontSize: '12px', fontWeight: 'bold' }} 
                                    formatter={(v: number) => formatCurrency(v)} 
                                />
                            </PieChart>
                        </ResponsiveContainer>
                    </div>

                    {/* Legend / Text Area */}
                    <div className="flex-1 w-full">
                        <div className="flex justify-between items-start mb-6">
                            <h3 className="text-sm font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
                                <AlignLeft className="w-4 h-4 text-indigo-500" />
                                Expenditure Topology
                            </h3>
                        </div>

                        {expenditureData.topCategory && (
                            <div className="mb-6 p-4 rounded-2xl bg-indigo-500/10 border border-indigo-500/20 flex items-center justify-between">
                                <div>
                                    <span className="text-[10px] font-black text-indigo-400 uppercase tracking-widest block mb-1">Primary Drain</span>
                                    <span className="text-lg font-bold text-white">{expenditureData.topCategory.name}</span>
                                </div>
                                <div className="text-right">
                                    <span className="text-xl font-black text-white">{formatCurrency(expenditureData.topCategory.value)}</span>
                                    <span className="text-[10px] font-bold text-slate-400 block">{((expenditureData.topCategory.value / expenditureData.total) * 100).toFixed(1)}%</span>
                                </div>
                            </div>
                        )}

                        <div className="space-y-3">
                            {/* Legend Items */}
                            {expenditureData.chartData.slice(0, 3).map((item, i) => (
                                <div key={i} className="flex items-center justify-between group">
                                    <div className="flex items-center gap-3">
                                        <div className="w-2.5 h-2.5 rounded-full" style={{ backgroundColor: COLORS[i % COLORS.length] }}></div>
                                        <span className="text-xs font-bold text-slate-300 group-hover:text-white transition-colors">{item.name}</span>
                                    </div>
                                    <div className="h-1 flex-1 mx-4 bg-slate-800/50 rounded-full overflow-hidden">
                                        <div className="h-full rounded-full transition-all duration-1000" style={{ width: `${(item.value / expenditureData.total) * 60}%`, backgroundColor: COLORS[i % COLORS.length], opacity: 0.6 }}></div>
                                    </div>
                                    <span className="text-[10px] font-bold text-slate-500">This Month</span>
                                </div>
                            ))}
                        </div>
                    </div>
                </div>

                {/* 2. Middle Row: Stats + Transactions */}
                <div className="grid grid-cols-1 md:grid-cols-12 gap-6">

                    {/* Left Sub-Col: Small Cards (Span 4) */}
                    <div className="md:col-span-4 flex flex-col gap-6">
                        {/* Burn Rate */}
                        <div className="glass-card p-6 rounded-[2rem] border border-white/5 bg-[#0f172a]/60 flex flex-col justify-center min-h-[140px]">
                            <div className="flex items-center gap-2 mb-2">
                                <Flame className="w-4 h-4 text-orange-500" />
                                <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Burn Rate/Day</span>
                            </div>
                            <div className="text-3xl font-black text-white">{formatCurrency(stats.currentDailyAvg)}</div>
                        </div>

                        {/* Remaining Capacity */}
                        <div className="glass-card p-6 rounded-[2rem] border border-white/5 bg-[#0f172a]/60 flex flex-col justify-center min-h-[140px]">
                            <div className="flex items-center gap-2 mb-2">
                                <Zap className="w-4 h-4 text-purple-500" />
                                <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Remaining Capacity</span>
                            </div>
                            <div className="text-xl font-black text-white">{neuralRemaining} <span className="text-[10px] text-slate-500 uppercase">Tokens Left</span></div>
                        </div>
                    </div>

                    {/* Right Sub-Col: Transactions (Span 8) */}
                    <div className="md:col-span-8 glass-card rounded-[2.5rem] border border-white/5 bg-[#0f172a]/60 p-6 overflow-hidden flex flex-col">
                        <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest mb-4">My Recent Transactions</h3>

                        <div className="flex-1 w-full">
                            <table className="w-full text-left border-collapse">
                                <thead className="text-[9px] font-black text-slate-500 uppercase tracking-widest border-b border-white/5">
                                    <tr>
                                        <th className="py-2">Date</th>
                                        <th className="py-2">Name</th>
                                        <th className="py-2 text-right">Amount</th>
                                    </tr>
                                </thead>
                                <tbody className="text-xs font-bold text-slate-300">
                                    {recentTransactions.map((t) => (
                                        <tr key={t.id} className="border-b border-white/5 last:border-0 hover:bg-white/5 transition-colors">
                                            <td className="py-4 text-slate-500 font-mono text-[10px]">{new Date(t.date).toLocaleDateString('en-US', { month: 'short', day: 'numeric' }).toUpperCase()}</td>
                                            <td className="py-4">{t.merchant}</td>
                                            <td className={`py-4 text-right ${t.type === TransactionType.INCOME ? 'text-emerald-400' : 'text-white'}`}>{formatCurrency(t.amount)}</td>
                                        </tr>
                                    ))}
                                    {recentTransactions.length === 0 && (
                                        <tr><td colSpan={3} className="py-8 text-center text-slate-500 italic">No recent activity.</td></tr>
                                    )}
                                </tbody>
                            </table>
                        </div>
                    </div>
                </div>

                {/* 3. Spending Graph */}
                <div className="glass-card p-8 rounded-[2.5rem] border border-white/5 bg-[#0f172a]/60 h-[280px] flex flex-col">
                    <div className="flex justify-between items-center mb-2">
                        <h3 className="text-sm font-black text-slate-400 uppercase tracking-widest">Spending</h3>
                        <div className="flex items-center gap-1 border border-white/10 rounded px-2 py-1 bg-slate-900 cursor-pointer">
                            <span className="text-[10px] font-bold text-slate-400 uppercase">This month vs. last year</span>
                            <ChevronDown className="w-3 h-3 text-slate-500" />
                        </div>
                    </div>
                    <div className="flex-1 w-full min-h-0 relative">
                        <ResponsiveContainer width="100%" height="100%">
                            <LineChart data={lineChartData}>
                                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#1e293b" />
                                <Tooltip 
                                    contentStyle={{ backgroundColor: '#020617', border: '1px solid rgba(255,255,255,0.1)', borderRadius: '8px', boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.5)' }} 
                                    itemStyle={{ fontSize: '11px', fontWeight: 'bold', color: '#fff' }}
                                    formatter={(v: number) => formatCurrency(v)}
                                />
                                <Line type="monotone" dataKey="LastYear" stroke="#475569" strokeWidth={2} dot={false} strokeDasharray="5 5" />
                                <Line type="monotone" dataKey="ThisMonth" stroke="#6366f1" strokeWidth={3} dot={false} />
                            </LineChart>
                        </ResponsiveContainer>
                    </div>
                    <div className="flex justify-center gap-6 mt-2">
                        <div className="flex items-center gap-2">
                            <div className="w-2 h-2 rounded-full bg-slate-600"></div>
                            <span className="text-[10px] font-bold text-slate-500 uppercase">Month Last Year</span>
                        </div>
                        <div className="flex items-center gap-2">
                            <div className="w-2 h-2 rounded-full bg-indigo-500"></div>
                            <span className="text-[10px] font-bold text-indigo-400 uppercase">This Month</span>
                        </div>
                    </div>
                </div>

            </div>

            {/* RIGHT SIDEBAR (Span 4) */}
            <div className="lg:col-span-4 flex flex-col gap-6">

                {/* 1. Goal Vector */}
                <div 
                    className="glass-card p-8 rounded-[2.5rem] border border-white/5 bg-slate-900/40 relative overflow-hidden cursor-pointer hover:border-indigo-500/30 transition-all"
                    onClick={() => onNavigate('goals')}
                >
                    <div className="flex items-center gap-6 mb-6">
                        {/* Circular Progress SVG */}
                        <div className="relative w-16 h-16 flex items-center justify-center">
                            <svg className="w-full h-full -rotate-90">
                                <circle cx="32" cy="32" r="28" fill="none" stroke="#1e293b" strokeWidth="6" />
                                <circle cx="32" cy="32" r="28" fill="none" stroke="#3b82f6" strokeWidth="6" strokeDasharray="175" strokeDashoffset={175 - (175 * goalMetrics.goalProgress) / 100} strokeLinecap="round" />
                            </svg>
                            <span className="absolute text-xs font-black text-white">{goalMetrics.goalProgress.toFixed(0)}%</span>
                        </div>
                        <div className="flex-1">
                            <div className="flex justify-between items-start w-full gap-4">
                                <h3 className="text-xs font-black text-slate-500 uppercase tracking-widest">Goal Vector</h3>
                                <span className="bg-slate-800 border border-white/5 text-slate-400 text-[8px] font-bold px-2 py-0.5 rounded">Status</span>
                            </div>
                            <div className="text-xl font-black text-white mt-1">{formatCurrency(goalMetrics.totalGoalTarget > 0 ? goalMetrics.totalGoalTarget : 12500)}</div>
                        </div>
                    </div>

                    {/* Progress Lines */}
                    <div className="space-y-3 mb-6">
                        <div className="h-1 w-full bg-slate-800 rounded-full overflow-hidden"><div className="h-full bg-blue-500 w-full rounded-full"></div></div>
                        <div className="h-1 w-full bg-slate-800 rounded-full overflow-hidden"><div className="h-full bg-slate-600 w-[70%] rounded-full"></div></div>
                        <div className="h-1 w-full bg-slate-800 rounded-full overflow-hidden"><div className="h-full bg-slate-600 w-[40%] rounded-full"></div></div>
                    </div>

                    <div className="p-4 bg-slate-950 rounded-xl border border-white/5">
                        <p className="text-[10px] text-slate-400 font-bold leading-tight uppercase">
                            Check the duration estimated to achieve your goal in <span className="text-white">Sandbox</span>.
                        </p>
                    </div>
                </div>

                {/* 2. Net Worth & Credit Card */}
                <div className="grid grid-cols-2 gap-4">
                    <div className="glass-card p-5 rounded-[2rem] border border-white/5 bg-slate-900/40 flex flex-col justify-between h-32">
                        <div className="flex justify-between items-start">
                            <span className="text-[10px] font-black text-slate-500 uppercase tracking-wider">Net Worth</span>
                            <Wallet className="w-4 h-4 text-blue-500" />
                        </div>
                        <div className="text-white font-black text-sm truncate">{formatCurrency(netWorth)}</div>
                    </div>
                    <div className="glass-card p-5 rounded-[2rem] border border-white/5 bg-slate-900/40 flex flex-col justify-between h-32">
                        <div className="flex justify-between items-start">
                            <div className="flex flex-col">
                                <span className="text-[10px] font-black text-slate-500 uppercase tracking-wider">Credit Card</span>
                                <span className="text-[9px] font-bold text-slate-400">Balance</span>
                            </div>
                            <CreditCard className="w-4 h-4 text-slate-400" />
                        </div>
                        <div className="text-white font-black text-sm truncate">{formatCurrency(creditCardBalance)}</div>
                    </div>
                </div>

                {/* 3. Actions List */}
                <div className="space-y-3">
                    <button onClick={() => onAskCoach && onAskCoach("Overview.")} className="w-full p-4 bg-slate-900/40 border border-white/5 text-slate-300 rounded-2xl text-[10px] font-black uppercase tracking-widest flex justify-between items-center hover:bg-slate-800 transition-colors">
                        Financial Overview <ChevronDown className="w-4 h-4 text-slate-500" />
                    </button>
                    <button onClick={() => onNavigate('sandbox')} className="w-full p-4 bg-slate-900/40 border border-white/5 text-slate-300 rounded-2xl text-[10px] font-black uppercase tracking-widest flex justify-between items-center hover:bg-slate-800 transition-colors">
                        Smart Money Tools <ChevronDown className="w-4 h-4 text-slate-500" />
                    </button>
                    <div className="grid grid-cols-2 gap-3">
                        <button onClick={() => onNavigate('negotiator')} className="p-4 bg-slate-900/40 border border-white/5 text-slate-300 rounded-2xl text-[9px] font-black uppercase tracking-widest hover:bg-slate-800 transition-colors text-center">
                            Negotiate My Bill
                        </button>
                        <button onClick={() => onAskCoach && onAskCoach("Summarize actions.")} className="p-4 bg-indigo-600 text-white rounded-2xl text-[9px] font-black uppercase tracking-widest shadow-lg shadow-indigo-500/20 hover:bg-indigo-500 transition-colors text-center border border-indigo-500/50">
                            Summarize Action For Today
                        </button>
                    </div>
                    <button onClick={() => onNavigate('accounts')} className="w-full p-4 bg-slate-900/40 border border-white/5 text-slate-300 rounded-2xl text-[10px] font-black uppercase tracking-widest flex justify-between items-center hover:bg-slate-800 transition-colors">
                        Investment <ChevronDown className="w-4 h-4 text-slate-500" />
                    </button>
                </div>

                {/* 4. Recurring Bills (Moved to bottom) */}
                <div className="glass-card p-6 rounded-[2.5rem] border border-white/5 bg-slate-900/40 mt-auto">
                    <div className="flex justify-between items-center mb-6">
                        <h3 className="text-xs font-black text-slate-500 uppercase tracking-widest">My Recurring Bill</h3>
                        <span className="px-2 py-1 rounded bg-slate-950 border border-white/5 text-[8px] font-bold text-slate-500 uppercase">This Month</span>
                    </div>
                    <div className="space-y-4">
                        {recurringBills.length > 0 ? (
                            recurringBills.map(bill => (
                                <div key={bill.id} className="flex items-center gap-3 group">
                                    <div className={`w-8 h-8 rounded-full flex items-center justify-center text-[10px] font-black text-white ${bill.merchant.toLowerCase().includes('netflix') ? 'bg-red-600' : bill.merchant.toLowerCase().includes('spotify') ? 'bg-green-500' : 'bg-slate-800'}`}>
                                        {bill.merchant.charAt(0)}
                                    </div>
                                    <div className="flex-1 flex justify-between items-center">
                                        <span className="text-xs font-bold text-slate-300 group-hover:text-white transition-colors">{bill.merchant}</span>
                                        <span className="text-xs font-bold text-slate-500">{formatCurrency(bill.amount)}/mo</span>
                                    </div>
                                </div>
                            ))
                        ) : (
                            <div className="flex items-center gap-3 opacity-50">
                                <div className="w-8 h-8 rounded-full bg-red-900/50 flex items-center justify-center text-white font-bold text-[10px]">N</div>
                                <div className="flex-1 flex justify-between items-center">
                                    <span className="text-xs font-bold text-slate-400">Netflix</span>
                                    <span className="text-xs font-bold text-slate-600">$15.99/mo</span>
                                </div>
                            </div>
                        )}
                    </div>
                </div>

            </div>
        </div>
    </div>
  );
};

export default Dashboard;

import React, { useMemo } from 'react';
import { AreaChart, Area, LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, PieChart, Pie, Cell } from 'recharts';
import { Account, Transaction, TransactionType, Category, UserPlan, Goal, Budget, SpendingStatus, SpendingPeriod } from '../types';
import { Activity, Flame, TrendingUp, Wallet, PlusCircle, CreditCard, Target, Quote, Landmark, Zap, Radio, Repeat, Check, Copy, X, Loader2, Sparkles, ArrowUpRight, ArrowDownRight, LayoutGrid, ArrowRight, Pin, Square, CheckSquare, Microscope, PieChart as PieChartIcon, ShieldAlert, BrainCircuit, GripVertical, AlertTriangle, Layers, Circle, Trophy, MessageSquare, Handshake, FileText, ChevronRight, Clock, ChevronDown, AlignLeft } from 'lucide-react';

interface DashboardProps {
  accounts: Account[];
  transactions: Transaction[];
  goals: Goal[];
  budgets: Budget[];
  onNavigate: (tab: string) => void;
  onAddAccount?: () => void;
  onAddTransaction?: () => void;
  onAddGoal?: () => void;
  formatCurrency: (amount: number) => string | React.ReactNode;
  userPlan?: UserPlan;
  onAskCoach?: (message: string) => void;
  isPinMode?: boolean;
  pinnedIds?: string[];
  onTogglePin?: (id: string) => void;
  trackEvent?: (id: string) => void;
  insightUsage?: number;
  spendingStatus?: SpendingStatus;
  currentPeriodSpend?: number;
  spendingLimit?: number;
  spendingPeriod?: SpendingPeriod;
}

const COLORS = ['#3b82f6', '#f97316', '#10b981', '#8b5cf6', '#06b6d4', '#ec4899', '#64748b'];

const Dashboard: React.FC<DashboardProps> = ({ 
    accounts, 
    transactions, 
    goals, 
    budgets,
    onNavigate, 
    onAddAccount, 
    onAddTransaction, 
    onAddGoal, 
    formatCurrency, 
    userPlan, 
    onAskCoach, 
    insightUsage = 0,
    spendingStatus,
    currentPeriodSpend = 0,
    spendingLimit = 1000,
    spendingPeriod = 'monthly'
}) => {
  const today = new Date();
  const currentMonth = today.getMonth();
  const currentYear = today.getFullYear();
  const currentMonthName = today.toLocaleDateString('en-US', { month: 'long' });
  const dayName = today.toLocaleDateString('en-US', { weekday: 'long' });
  const userName = localStorage.getItem('nova_user_name') || 'User';

  // --- Data Calculations ---

  const netWorth = useMemo(() => accounts.reduce((acc, curr) => acc + curr.balance, 0), [accounts]);

  // Estimate credit card balance (sum of negative balances on Credit Card types)
  const creditCardBalance = useMemo(() => {
      return accounts
        .filter(a => a.type === 'Credit Card')
        .reduce((acc, curr) => acc + (curr.balance < 0 ? Math.abs(curr.balance) : 0), 0);
  }, [accounts]);

  const stats = useMemo(() => {
    const currentMTDExpenses = transactions.filter(t => {
      const d = new Date(t.date);
      return t.type === TransactionType.EXPENSE && d.getMonth() === currentMonth && d.getFullYear() === currentYear;
    });
    const currentMTDTotal = currentMTDExpenses.reduce((acc, t) => acc + t.amount, 0);
    const currentDay = today.getDate();
    const currentDailyAvg = currentMTDTotal / Math.max(currentDay, 1);

    return { currentDailyAvg };
  }, [transactions, currentMonth, currentYear]);

  const expenditureData = useMemo(() => {
    const expenses = transactions.filter(t => 
        t.type === TransactionType.EXPENSE && 
        new Date(t.date).getMonth() === currentMonth &&
        new Date(t.date).getFullYear() === currentYear
    );

    const total = expenses.reduce((acc, t) => acc + t.amount, 0);
    const catMap: Record<string, number> = {};

    expenses.forEach(t => {
        catMap[t.category] = (catMap[t.category] || 0) + t.amount;
    });

    const chartData = Object.entries(catMap)
        .map(([name, value]) => ({ name, value }))
        .sort((a, b) => b.value - a.value);

    // If no data, provide placeholder for visual fidelity
    if (chartData.length === 0) {
        return { chartData: [{ name: 'No Data', value: 1 }], total: 0, isEmpty: true, topCategory: null };
    }

    const topCategory = chartData[0];

    return { chartData, total, isEmpty: false, topCategory };
  }, [transactions, currentMonth, currentYear]);

  const lineChartData = useMemo(() => {
    const daysInCurrentMonth = new Date(currentYear, currentMonth + 1, 0).getDate();
    const data = [];

    // Simulate "Last Year" data for visual fidelity as requested in sketch
    const getDailySpend = (month: number, year: number, randomize = false) => {
        const daily = new Array(32).fill(0);
        if (randomize) {
             let accum = 0;
             for(let i=1; i<=31; i++) {
                 accum += Math.random() * 50 + 20;
                 daily[i] = accum;
             }
             return daily;
        }

        transactions.forEach(t => {
            const d = new Date(t.date);
            if (t.type === TransactionType.EXPENSE && d.getMonth() === month && d.getFullYear() === year) {
                daily[d.getDate()] += t.amount;
            }
        });
        // Cumulative
        for (let i = 1; i < daily.length; i++) daily[i] += daily[i-1];
        return daily;
    };

    const currentMonthData = getDailySpend(currentMonth, currentYear);
    // Use simulated data for "Last Year" to match the graph curve in the sketch if no real data
    const lastYearData = getDailySpend(currentMonth, currentYear - 1, true);

    for (let i = 1; i <= daysInCurrentMonth; i++) {
        data.push({
            day: i,
            ThisMonth: currentMonthData[i],
            LastYear: lastYearData[i] 
        });
    }
    return data;
  }, [transactions, currentMonth, currentYear]);

  const recurringBills = useMemo(() => {
      const subs = transactions.filter(t => t.category === Category.SUBSCRIPTION);
      const unique = new Map();
      subs.forEach(t => {
          if (!unique.has(t.merchant)) unique.set(t.merchant, t);
      });
      return Array.from(unique.values()).slice(0, 3);
  }, [transactions]);

  const recentTransactions = useMemo(() => {
      return transactions.slice(0, 4);
  }, [transactions]);

  // Goal Vector Logic
  const goalMetrics = useMemo(() => {
      const totalGoalTarget = goals.reduce((acc, g) => acc + g.targetAmount, 0);
      const totalGoalCurrent = goals.reduce((acc, g) => acc + g.currentAmount, 0);
      const goalProgress = totalGoalTarget > 0 ? (totalGoalCurrent / totalGoalTarget) * 100 : 0;

      const budgetUtilization = spendingLimit > 0 ? (currentPeriodSpend / spendingLimit) * 100 : 0;

      return { totalGoalCurrent, totalGoalTarget, goalProgress, budgetUtilization };
  }, [goals, currentPeriodSpend, spendingLimit]);

  const neuralCapacity = userPlan === 'ultra' ? 1500 : userPlan === 'pro' ? 50 : 3;
  const neuralRemaining = Math.max(0, neuralCapacity - insightUsage);

  return (
    <div className="h-full overflow-y-auto custom-scrollbar pb-20 px-2 md:px-0">

        {/* Header */}
        <div className="mb-6 mt-2">
            <h1 className="text-2xl md:text-3xl font-black text-white uppercase tracking-tight">Good {dayName}, {userName}</h1>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">

            {/* LEFT MAIN PANEL (Span 8) */}
            <div className="lg:col-span-8 flex flex-col gap-6">

                {/* 1. Expenditure Topology (Pie Chart) */}
                <div className="glass-card p-6 md:p-8 rounded-[2.5rem] border border-white/5 bg-[#0f172a]/60 backdrop-blur-xl relative overflow-hidden flex flex-col md:flex-row items-center gap-8 min-h-[300px]">
                    {/* Donut Chart */}
                    <div className="w-48 h-48 md:w-56 md:h-56 relative shrink-0">
                        <ResponsiveContainer width="100%" height="100%">
                            <PieChart>
                                <Pie
                                    data={expenditureData.chartData}
                                    cx="50%"
                                    cy="50%"
                                    innerRadius={60}
                                    outerRadius={90}
                                    paddingAngle={2}
                                    dataKey="value"
                                    stroke="none"
                                >
                                    {expenditureData.chartData.map((entry, index) => (
                                        <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                                    ))}
                                </Pie>
                                <Tooltip 
                                    contentStyle={{ backgroundColor: '#020617', border: '1px solid rgba(255,255,255,0.1)', borderRadius: '12px', padding: '8px' }} 
                                    itemStyle={{ color: '#fff', fontSize: '12px', fontWeight: 'bold' }} 
                                    formatter={(v: number) => formatCurrency(v)} 
                                />
                            </PieChart>
                        </ResponsiveContainer>
                    </div>

                    {/* Legend / Text Area */}
                    <div className="flex-1 w-full">
                        <div className="flex justify-between items-start mb-6">
                            <h3 className="text-sm font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
                                <AlignLeft className="w-4 h-4 text-indigo-500" />
                                Expenditure Topology
                            </h3>
                        </div>

                        {expenditureData.topCategory && (
                            <div className="mb-6 p-4 rounded-2xl bg-indigo-500/10 border border-indigo-500/20 flex items-center justify-between">
                                <div>
                                    <span className="text-[10px] font-black text-indigo-400 uppercase tracking-widest block mb-1">Primary Drain</span>
                                    <span className="text-lg font-bold text-white">{expenditureData.topCategory.name}</span>
                                </div>
                                <div className="text-right">
                                    <span className="text-xl font-black text-white">{formatCurrency(expenditureData.topCategory.value)}</span>
                                    <span className="text-[10px] font-bold text-slate-400 block">{((expenditureData.topCategory.value / expenditureData.total) * 100).toFixed(1)}%</span>
                                </div>
                            </div>
                        )}

                        <div className="space-y-3">
                            {/* Legend Items */}
                            {expenditureData.chartData.slice(0, 3).map((item, i) => (
                                <div key={i} className="flex items-center justify-between group">
                                    <div className="flex items-center gap-3">
                                        <div className="w-2.5 h-2.5 rounded-full" style={{ backgroundColor: COLORS[i % COLORS.length] }}></div>
                                        <span className="text-xs font-bold text-slate-300 group-hover:text-white transition-colors">{item.name}</span>
                                    </div>
                                    <div className="h-1 flex-1 mx-4 bg-slate-800/50 rounded-full overflow-hidden">
                                        <div className="h-full rounded-full transition-all duration-1000" style={{ width: `${(item.value / expenditureData.total) * 60}%`, backgroundColor: COLORS[i % COLORS.length], opacity: 0.6 }}></div>
                                    </div>
                                    <span className="text-[10px] font-bold text-slate-500">This Month</span>
                                </div>
                            ))}
                        </div>
                    </div>
                </div>

                {/* 2. Middle Row: Stats + Transactions */}
                <div className="grid grid-cols-1 md:grid-cols-12 gap-6">

                    {/* Left Sub-Col: Small Cards (Span 4) */}
                    <div className="md:col-span-4 flex flex-col gap-6">
                        {/* Burn Rate */}
                        <div className="glass-card p-6 rounded-[2rem] border border-white/5 bg-[#0f172a]/60 flex flex-col justify-center min-h-[140px]">
                            <div className="flex items-center gap-2 mb-2">
                                <Flame className="w-4 h-4 text-orange-500" />
                                <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Burn Rate/Day</span>
                            </div>
                            <div className="text-3xl font-black text-white">{formatCurrency(stats.currentDailyAvg)}</div>
                        </div>

                        {/* Remaining Capacity */}
                        <div className="glass-card p-6 rounded-[2rem] border border-white/5 bg-[#0f172a]/60 flex flex-col justify-center min-h-[140px]">
                            <div className="flex items-center gap-2 mb-2">
