import UpcomingFeatures from './components/UpcomingFeatures';
import CashflowBeta from './components/CashflowBeta';
import BillNegotiator from './components/BillNegotiator';
import LandingPage from './components/LandingPage';
import OnboardingModal from './components/OnboardingModal';
import ToastContainer from './components/Toast';
import FloatingAssistant from './components/FloatingAssistant';
import Investment from './components/Investment';
import { Sparkles, LogOut, MessageCircle, Zap, Crown, AlertTriangle, ShieldX, Terminal, ArrowRight, Eye, EyeOff, Shield, Lock } from 'lucide-react';

const getMonthlyUsage = (key: string) => {
    try {
        const item = localStorage.getItem(key);
        if (!item) return 0;
        const parsed = JSON.parse(item);
        const now = new Date();
        if (parsed.month !== now.getMonth() || parsed.year !== now.getFullYear()) return 0;
        return parsed.count || 0;
    } catch (e) { return 0; }
};

const safeSetItem = (key: string, value: string) => {
    try { localStorage.setItem(key, value); } catch (e) { console.warn(`Storage quota exceeded for ${key}`); }
};

// Feature IDs for Pin System
const PINNABLE_FEATURES = ['budget-monitor', 'sandbox-link', 'goal-tracker', 'system-alerts', 'neural-quota'];

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isPrivacyMode, setIsPrivacyMode] = useState(() => localStorage.getItem('nova_privacy_mode') === 'true');
  const [isPinMode, setIsPinMode] = useState(false);

  // Onboarding & Enforcement State
  const [onboardingComplete, setOnboardingComplete] = useState(() => localStorage.getItem('nova_onboarding_complete') === 'true');

  // Fix: Ensure spendingLimit is always a valid number to prevent NaN
  const [spendingLimit, setSpendingLimit] = useState<number>(() => {
      const stored = localStorage.getItem('nova_spending_limit');
      if (!stored) return 1000;
      const parsed = parseFloat(stored);
      // Strict check: if parsed is NaN or infinite, fallback to 1000
      return Number.isFinite(parsed) && parsed > 0 ? parsed : 1000;
  });

  const [spendingPeriod, setSpendingPeriod] = useState<SpendingPeriod>(() => (localStorage.getItem('nova_spending_period') as SpendingPeriod) || 'monthly');

  // Pin System State
  const [pinnedIds, setPinnedIds] = useState<string[]>(() => {
    try {
        const saved = localStorage.getItem('nova_pinned_ids');
        return saved ? JSON.parse(saved) : []; 
    } catch { return []; }
  });

  const [featureUsage, setFeatureUsage] = useState<Record<string, number>>(() => {
      try {
          const saved = localStorage.getItem('nova_feature_usage');
          return saved ? JSON.parse(saved) : {};
      } catch { return {}; }
  });

  const [accounts, setAccounts] = useState<Account[]>(() => {
      const saved = localStorage.getItem('nova_accounts');
      return saved ? JSON.parse(saved) : ACCOUNTS;
  });
  const [transactions, setTransactions] = useState<Transaction[]>(() => {
      const saved = localStorage.getItem('nova_transactions');
      return saved ? JSON.parse(saved) : INITIAL_TRANSACTIONS;
  });
  const [budgets, setBudgets] = useState<Budget[]>(() => {
      const saved = localStorage.getItem('nova_budgets');
      return saved ? JSON.parse(saved) : INITIAL_BUDGETS;
  });
  const [goals, setGoals] = useState<Goal[]>(() => {
      const saved = localStorage.getItem('nova_goals');
      return saved ? JSON.parse(saved) : INITIAL_GOALS;
  });

  const [userPlan, setUserPlan] = useState<UserPlan>(() => localStorage.getItem('nova_user_plan') as UserPlan || 'free');
  const [insightUsage, setInsightUsage] = useState(() => getMonthlyUsage('nova_insight_usage'));
  const [scanUsage, setScanUsage] = useState(() => getMonthlyUsage('nova_scan_usage'));
  const [negotiationUsage, setNegotiationUsage] = useState(() => getMonthlyUsage('nova_negotiation_usage'));

  const [isLoggedIn, setIsLoggedIn] = useState(() => localStorage.getItem('nova_auth_token') !== null);
  const [isLogoutModalOpen, setIsLogoutModalOpen] = useState(false);
  const [toasts, setToasts] = useState<ToastMessage[]>([]);
  const [botMode, setBotMode] = useState<BotMode>(() => (localStorage.getItem('nova_bot_mode') as BotMode) || 'ruthless');
  const [pendingChatQuery, setPendingChatQuery] = useState<string | null>(null);

  // User Profile State with Proper Initialization
  const [userName, setUserName] = useState(() => localStorage.getItem('nova_user_name') || 'Pilot');
  const [userEmail, setUserEmail] = useState(() => localStorage.getItem('nova_user_email') || 'pilot@nova.io');
  const [userAvatar, setUserAvatar] = useState(() => localStorage.getItem('nova_user_avatar') || '');
  const [userAvatarZoom, setUserAvatarZoom] = useState(() => parseFloat(localStorage.getItem('nova_user_avatar_zoom') || '1'));
  const [userAvatarPos, setUserAvatarPos] = useState(() => {
      try {
          const saved = localStorage.getItem('nova_user_avatar_pos');
          return saved ? JSON.parse(saved) : { x: 0, y: 0 };
      } catch { return { x: 0, y: 0 }; }
  });
  const [userBorder, setUserBorder] = useState(() => localStorage.getItem('nova_user_border') || 'default');
  const [userBackground, setUserBackground] = useState(() => localStorage.getItem('nova_user_bg') || '');

  const [currency, setCurrency] = useState<Currency>(() => (localStorage.getItem('nova_currency') as Currency) || 'USD');
  const [language, setLanguage] = useState<Language>(() => (localStorage.getItem('nova_language') as Language) || 'en');

  // Persistence Effects - Data
  useEffect(() => safeSetItem('nova_accounts', JSON.stringify(accounts)), [accounts]);
  useEffect(() => safeSetItem('nova_transactions', JSON.stringify(transactions)), [transactions]);
  useEffect(() => safeSetItem('nova_budgets', JSON.stringify(budgets)), [budgets]);
  useEffect(() => safeSetItem('nova_goals', JSON.stringify(goals)), [goals]);

  // Persistence Effects - Settings & Profile
  useEffect(() => safeSetItem('nova_user_plan', userPlan), [userPlan]);
  useEffect(() => safeSetItem('nova_currency', currency), [currency]);
  useEffect(() => safeSetItem('nova_language', language), [language]);
  useEffect(() => safeSetItem('nova_bot_mode', botMode), [botMode]);
  useEffect(() => safeSetItem('nova_privacy_mode', isPrivacyMode.toString()), [isPrivacyMode]);
  useEffect(() => safeSetItem('nova_pinned_ids', JSON.stringify(pinnedIds)), [pinnedIds]);
  useEffect(() => safeSetItem('nova_feature_usage', JSON.stringify(featureUsage)), [featureUsage]);
  useEffect(() => safeSetItem('nova_spending_limit', spendingLimit.toString()), [spendingLimit]);
  useEffect(() => safeSetItem('nova_spending_period', spendingPeriod), [spendingPeriod]);
  useEffect(() => safeSetItem('nova_onboarding_complete', onboardingComplete.toString()), [onboardingComplete]);

  // Persistence Effects - User Identity (Ensure robust saving)
  useEffect(() => {
      localStorage.setItem('nova_user_name', userName);
  }, [userName]);
  useEffect(() => {
      localStorage.setItem('nova_user_email', userEmail);
  }, [userEmail]);
  useEffect(() => {
      if(userAvatar) safeSetItem('nova_user_avatar', userAvatar);
  }, [userAvatar]);
  useEffect(() => safeSetItem('nova_user_avatar_zoom', userAvatarZoom.toString()), [userAvatarZoom]);
  useEffect(() => safeSetItem('nova_user_avatar_pos', JSON.stringify(userAvatarPos)), [userAvatarPos]);
  useEffect(() => safeSetItem('nova_user_border', userBorder), [userBorder]);
  useEffect(() => safeSetItem('nova_user_bg', userBackground), [userBackground]);

  // Spending Enforcement Calculation (Zero AI, Pure Math)
  const spendingStatus: { currentSpend: number; status: SpendingStatus } = useMemo(() => {
      const now = new Date();
      let startDate = new Date();

      if (spendingPeriod === 'weekly') {
          // Set to previous Sunday (or today if Sunday)
          const day = now.getDay();
          const diff = now.getDate() - day;
          startDate = new Date(now.setDate(diff));
          startDate.setHours(0, 0, 0, 0);
      } else {
          // Set to 1st of current month
          startDate = new Date(now.getFullYear(), now.getMonth(), 1);
      }

      const currentSpend = transactions
          .filter(t => t.type === TransactionType.EXPENSE && new Date(t.date) >= startDate)
          .reduce((acc, t) => acc + t.amount, 0);

      const status = evaluateSpending(currentSpend, spendingLimit);
      return { currentSpend, status };
  }, [transactions, spendingPeriod, spendingLimit]);

  // Usage counters
  useEffect(() => {
      const now = new Date();
      const meta = { month: now.getMonth(), year: now.getFullYear(), count: insightUsage };
      safeSetItem('nova_insight_usage', JSON.stringify(meta));
  }, [insightUsage]);

  useEffect(() => {
      const now = new Date();
      const meta = { month: now.getMonth(), year: now.getFullYear(), count: scanUsage };
      safeSetItem('nova_scan_usage', JSON.stringify(meta));
  }, [scanUsage]);

  useEffect(() => {
      const now = new Date();
      const meta = { month: now.getMonth(), year: now.getFullYear(), count: negotiationUsage };
      safeSetItem('nova_negotiation_usage', JSON.stringify(meta));
  }, [negotiationUsage]);

  const addToast = useCallback((message: string, type: 'success' | 'error' | 'info' = 'info') => {
    setToasts(prev => [...prev, { id: Date.now().toString(), message, type }]);
  }, []);

  const trackFeatureUsage = useCallback((featureId: string) => {
      setFeatureUsage(prev => ({
          ...prev,
          [featureId]: (prev[featureId] || 0) + 1
      }));
  }, []);

  // Auto-Pin Heuristic
  useEffect(() => {
      if (!isLoggedIn) return;
      const hasAutoPinned = localStorage.getItem('nova_has_auto_pinned');
      if (hasAutoPinned) return;

      const totalActions = (Object.values(featureUsage) as number[]).reduce((a, b) => a + b, 0);
      if (totalActions > 10) {
          const sorted = Object.entries(featureUsage)
              .filter(([key]) => PINNABLE_FEATURES.includes(key))
              .sort((a, b) => (b[1] as number) - (a[1] as number))
              .map(([key]) => key)
              .slice(0, 2); 

          if (sorted.length > 0) {
              setPinnedIds(sorted);
              addToast(`System optimization complete. Top ${sorted.length} modules pinned.`, 'info');
              localStorage.setItem('nova_has_auto_pinned', 'true');
          }
      }
  }, [featureUsage, isLoggedIn, addToast]);

  const handleTogglePin = (id: string) => {
    setPinnedIds(prev => {
        if (prev.includes(id)) {
            return prev.filter(p => p !== id);
        }
        const limit = userPlan === 'ultra' ? 5 : userPlan === 'pro' ? 3 : 1;
        if (prev.length >= limit) {
            addToast(`Slot Limit Reached (${limit}). Unpin a module to replace.`, 'error');
            return prev;
        }
        return [...prev, id];
    });
  };

  const handleToggleStealth = useCallback(() => {
    if (userPlan !== 'ultra') {
        addToast('Stealth Protocol is an Elite-exclusive feature.', 'info');
        setActiveTab('plans');
        return;
    }
    setIsPrivacyMode(prev => !prev);
    addToast(`Stealth Protocol ${!isPrivacyMode ? 'Engaged' : 'Disengaged'}`, 'info');
  }, [userPlan, isPrivacyMode, addToast]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
        const isModI = (e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'i';
        if (isModI) {
            e.preventDefault();
            setIsPinMode(prev => {
                const newVal = !prev;
                addToast(newVal ? 'Pin Configuration Mode: ACTIVE' : 'Pin Configuration Mode: END', 'info');
                if (newVal) setActiveTab('dashboard');
                return newVal;
            });
        }
        if (e.key === 'Escape' && isPinMode) {
            setIsPinMode(false);
            addToast('Pin Configuration Mode: END', 'info');
        }
        if (e.shiftKey && e.key.toLowerCase() === 'p') {
            handleToggleStealth();
        }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isPinMode, handleToggleStealth, addToast]);

  const removeToast = (id: string) => {
    setToasts(prev => prev.filter(t => t.id !== id));
  };

  const formatCurrency = (amount: number) => {
    const safeAmount = isNaN(amount) ? 0 : amount;
    const val = new Intl.NumberFormat(language === 'vi' ? 'vi-VN' : 'en-US', { 
        style: 'currency', currency: currency,
    }).format(safeAmount);

    if (isPrivacyMode && userPlan === 'ultra') {
        return <span className="blur-md opacity-50 bg-white/5 px-1 rounded-md">{val.replace('-', '')}</span>;
    }
    return val;
  };

  const reconcileBalance = (tx: Transaction, direction: 'add' | 'delete') => {
      if (tx.accountId === 'manual') return;
      setAccounts(prev => prev.map(acc => {
          if (acc.id === tx.accountId) {
              const isIncome = tx.type === TransactionType.INCOME;
              let change = tx.amount;
              if (direction === 'add') change = isIncome ? change : -change;
              else change = isIncome ? -change : change;
              return { ...acc, balance: acc.balance + change };
          }
          return acc;
      }));
  };

  const handleAddTransaction = (t: Transaction) => {
      setTransactions(prev => [t, ...prev]);
      reconcileBalance(t, 'add');
      addToast('Transaction recorded.', 'success');
  };

  const handleDeleteTransaction = (id: string) => {
      const tx = transactions.find(t => t.id === id);
      if (tx) {
          reconcileBalance(tx, 'delete');
          setTransactions(prev => prev.filter(t => t.id !== id));
          addToast('Transaction purged.', 'info');
      }
  };

  const handleLogin = (name: string) => {
    setIsLoggedIn(true);
    setUserName(name);
    localStorage.setItem('nova_user_name', name);
  };

  const confirmLogout = () => {
    localStorage.removeItem('nova_auth_token');
    setIsLoggedIn(false);
    setIsLogoutModalOpen(false);
  };

  const handleAskCoach = (message?: string) => {
    if (message) {
      setPendingChatQuery(message);
    }
    setActiveTab('insights');
  };

  const handleOnboardingComplete = (name: string, lang: Language, per: SpendingPeriod, lim: number) => {
      const validName = name && name.trim().length > 0 ? name : 'Commander';
      setUserName(validName);
      localStorage.setItem('nova_user_name', validName);

      setLanguage(lang);
      setSpendingPeriod(per);

      const validLimit = Number.isFinite(lim) && lim > 0 ? lim : 1000;
      setSpendingLimit(validLimit);
      localStorage.setItem('nova_spending_limit', validLimit.toString());

      setOnboardingComplete(true);
      addToast(`Welcome, ${validName}. Systems online.`, 'success');
  };

  const branding = useMemo(() => {
    switch (userPlan) {
      case 'ultra':
        return {
          bg: 'bg-gradient-to-tr from-indigo-600 to-purple-600',
          shadow: 'shadow-indigo-500/40',
          icon: <Sparkles className="w-6 h-6 text-white" />,
          label: 'Elite Terminal'
        };
      case 'pro':
        return {
          bg: 'bg-gradient-to-tr from-amber-400 to-orange-500',
          shadow: 'shadow-amber-500/40',
          icon: <Zap className="w-6 h-6 text-white" />,
          label: 'Pro Uplink'
        };
      default:
        return {
          bg: 'bg-slate-800',
          shadow: 'shadow-black/20',
          icon: <Shield className="w-6 h-6 text-slate-400" />,
          label: 'Free Tier'
        };
    }
  }, [userPlan]);

  if (!isLoggedIn) return <LandingPage onLoginSuccess={handleLogin} />;

  if (!onboardingComplete) return <OnboardingModal onComplete={handleOnboardingComplete} />;

  return (
    <div className={`flex h-screen bg-[#020617] text-slate-100 font-sans selection:bg-indigo-500/30 overflow-hidden relative ${isPinMode ? 'cursor-default' : ''}`}>
      <FloatingAssistant transactions={transactions} budgets={budgets} userPlan={userPlan} botMode={botMode} isVisible={activeTab !== 'insights'} onOpenChat={handleAskCoach} insightUsage={insightUsage} />

      <aside className="hidden md:flex flex-col w-64 p-4 pb-8 z-20 bg-slate-950/40 backdrop-blur-md border-r border-white/5 relative">
        <div className="flex items-center gap-3 px-4 py-3 mb-8 shrink-0">
            <div className={`w-10 h-10 rounded-xl flex items-center justify-center shadow-lg ring-1 ring-white/10 ${branding.bg} ${branding.shadow}`}>{branding.icon}</div>
            <div><h1 className="text-xl font-bold tracking-tight text-white">Nova AI</h1><p className={`text-[10px] font-bold uppercase tracking-wider ${userPlan === 'ultra' ? 'text-purple-400' : userPlan === 'pro' ? 'text-amber-400' : 'text-slate-500'}`}>{branding.label}</p></div>
        </div>
        <nav className="flex-1 space-y-1 overflow-y-auto custom-scrollbar pr-1">
            {NAV_ITEMS.map((item) => {
                const isActive = activeTab === item.id;
                const label = TRANSLATIONS[language]?.[item.id as keyof typeof TRANSLATIONS['en']] || item.label;
                return (
                    <button key={item.id} onClick={() => setActiveTab(item.id)} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold transition-all duration-300 group ${isActive ? 'bg-indigo-600/10 text-indigo-400 shadow-[0_0_20px_rgba(99,102,241,0.15)] ring-1 ring-indigo-500/20' : 'text-slate-400 hover:text-white hover:bg-white/5'}`}>
                        <item.icon className={`w-5 h-5 transition-colors ${isActive ? 'text-indigo-400' : 'text-slate-500 group-hover:text-white'}`} />{label}
                    </button>
                );
            })}
        </nav>
        <div className="mt-auto pt-6 border-t border-white/5 shrink-0">
             <button onClick={handleToggleStealth} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all mb-2 ${isPrivacyMode && userPlan === 'ultra' ? 'bg-indigo-500/20 text-indigo-400 border border-indigo-500/30' : 'text-slate-500 hover:text-slate-300 hover:bg-white/5'}`}>
                {isPrivacyMode ? <EyeOff className="w-5 h-5" /> : <Shield className="w-5 h-5" />} {isPrivacyMode ? 'Stealth Engaged' : 'Stealth Protocol'}
             </button>
             <button onClick={() => setActiveTab('settings')} className="w-full text-left px-4 py-4 rounded-2xl bg-slate-900/50 border border-white/5 flex items-center gap-3 mb-4 hover:bg-slate-800 transition-colors group">
                 <div className="w-10 h-10 rounded-full bg-indigo-500 flex items-center justify-center text-white overflow-hidden relative border border-white/10 shadow-inner">{userAvatar ? <img src={userAvatar} className="w-full h-full object-cover" alt="User" /> : <span className="font-bold text-lg">{userName.charAt(0)}</span>}</div>
                 <div className="overflow-hidden"><h4 className="font-bold text-white text-sm truncate group-hover:text-indigo-400 transition-colors">{userName}</h4><p className="text-[10px] text-slate-500 truncate font-bold uppercase tracking-widest">{userPlan} tier</p></div>
             </button>
             <button onClick={() => setIsLogoutModalOpen(true)} className="w-full flex items-center gap-2 px-4 py-2 mb-4 text-xs font-bold text-slate-500 hover:text-rose-400 transition-colors uppercase tracking-widest"><LogOut className="w-4 h-4" /> Sign Out</button>
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 z-10 relative overflow-hidden">
        {isPinMode && (
          <div className="absolute inset-0 z-[100] bg-black/40 backdrop-blur-[2px] pointer-events-none flex flex-col items-center justify-start pt-20">
              <div className="bg-indigo-600/90 text-white font-black text-xs uppercase tracking-[0.3em] px-8 py-4 rounded-2xl shadow-[0_0_50px_rgba(99,102,241,0.5)] border border-indigo-400/50 animate-pulse pointer-events-auto">
                  Pin Mode Active :: Select Priority Nodes :: Esc to Exit
              </div>
          </div>
        )}

        <div className="flex-1 overflow-y-auto p-4 md:p-8 pb-24 md:pb-8 custom-scrollbar">
            {activeTab === 'dashboard' && <Dashboard userName={userName} accounts={accounts} transactions={transactions} goals={goals} budgets={budgets} onNavigate={setActiveTab} onAddAccount={() => setActiveTab('accounts')} onAddTransaction={() => setActiveTab('transactions')} onAddGoal={() => setActiveTab('goals')} formatCurrency={formatCurrency} userPlan={userPlan} onAskCoach={handleAskCoach} isPinMode={isPinMode} pinnedIds={pinnedIds} onTogglePin={handleTogglePin} trackEvent={trackFeatureUsage} insightUsage={insightUsage} spendingStatus={spendingStatus.status} currentPeriodSpend={spendingStatus.currentSpend} spendingLimit={spendingLimit} spendingPeriod={spendingPeriod} />}
            {activeTab === 'transactions' && <Transactions transactions={transactions} accounts={accounts} onDelete={handleDeleteTransaction} onAdd={handleAddTransaction} formatCurrency={formatCurrency} onNavigateToAccounts={() => setActiveTab('accounts')} userPlan={userPlan} scanUsage={scanUsage} onIncrementScan={() => setScanUsage(prev => prev + 1)} currency={currency} />}
            {activeTab === 'accounts' && <Accounts accounts={accounts} budgets={budgets} transactions={transactions} userPlan={userPlan} onAdd={(acc) => { setAccounts(prev => [...prev, acc]); addToast('Account linked.', 'success'); }} onUpdate={(acc) => { setAccounts(prev => prev.map(a => a.id === acc.id ? acc : a)); addToast('Account updated.', 'success'); }} onDelete={(id) => { setAccounts(prev => prev.filter(a => a.id !== id)); setTransactions(prev => prev.map(t => t.accountId === id ? { ...t, accountId: 'manual' } : t)); addToast('Account removed.', 'info'); }} formatCurrency={formatCurrency} userName={userName} userAvatar={userAvatar} userAvatarZoom={userAvatarZoom} userAvatarPos={userAvatarPos} userBorder={userBorder} onNavigate={setActiveTab} />}
            {activeTab === 'cashflow' && <CashflowBeta transactions={transactions} accounts={accounts} goals={goals} formatCurrency={formatCurrency} userPlan={userPlan} />}
            {activeTab === 'negotiator' && <BillNegotiator userPlan={userPlan} onIncrementUsage={() => setNegotiationUsage(prev => prev + 1)} negotiationUsage={negotiationUsage} transactions={transactions} />}
            {activeTab === 'insights' && <Insights transactions={transactions} userPlan={userPlan} onUpgradeClick={() => setActiveTab('plans')} formatCurrency={formatCurrency} insightUsage={insightUsage} onIncrementUsage={() => setInsightUsage(prev => prev + 1)} onApplyBudgets={(newBudgets) => { const existingCats = new Set(budgets.map(b => b.category)); const toAdd = newBudgets.filter(b => !existingCats.has(b.category)); setBudgets(prev => [...prev, ...toAdd]); addToast(`Applied ${toAdd.length} AI limits.`, 'success'); }} initialPrompt={pendingChatQuery} onPromptHandled={() => setPendingChatQuery(null)} botMode={botMode} onNavigate={setActiveTab} onAddGoal={(g) => { setGoals(prev => [...prev, g]); addToast('Goal created from proposal.', 'success'); }} goals={goals} budgets={budgets} />}
            {activeTab === 'sandbox' && <ScenarioSandbox transactions={transactions} goals={goals} formatCurrency={formatCurrency} userPlan={userPlan} onUpgradeClick={() => setActiveTab('plans')} insightUsage={insightUsage} onIncrementUsage={(val) => setInsightUsage(prev => prev + (val || 1))} />}
            {activeTab === 'goals' && <Goals goals={goals} budgets={budgets} transactions={transactions} onAddGoal={(g) => { setGoals(prev => [...prev, g]); addToast('Goal deployed.', 'success'); }} onUpdateGoal={(g) => { setGoals(prev => prev.map(goal => goal.id === g.id ? g : goal)); addToast('Goal updated.', 'success'); }} onAddBudget={(b) => { setBudgets(prev => [...prev, b]); addToast('Limit set.', 'success'); }} onDeleteBudget={(id) => { setBudgets(prev => prev.filter(b => b.id !== id)); addToast('Limit removed.', 'info'); }} formatCurrency={formatCurrency} />}
            {activeTab === 'plans' && <Plans currentPlan={userPlan} onUpgrade={(plan) => { setUserPlan(plan); addToast(`Plan upgraded.`, 'success'); }} onDowngrade={() => { setUserPlan('free'); addToast('Plan reset.', 'info'); }} onNavigateDashboard={() => setActiveTab('dashboard')} />}
            {activeTab === 'investment' && <Investment accounts={accounts} formatCurrency={formatCurrency} userPlan={userPlan} />}
            {activeTab === 'upcoming' && <UpcomingFeatures />}
            {activeTab === 'settings' && <Settings userName={userName} userEmail={userEmail} userAvatar={userAvatar} userAvatarZoom={userAvatarZoom} userAvatarPos={userAvatarPos} userBorder={userBorder} userBackground={userBackground} onUpdateBackground={setUserBackground} userPlan={userPlan} onUpdateProfile={(n, e, a, z, p, b) => { 
                // Immediate manual save to ensure persistence
                localStorage.setItem('nova_user_name', n);
                localStorage.setItem('nova_user_email', e);
                if (a) localStorage.setItem('nova_user_avatar', a);

                setUserName(n); 
                setUserEmail(e); 
                setUserAvatar(a); 
                setUserAvatarZoom(z); 
                setUserAvatarPos(p); 
                setUserBorder(b); 
                addToast('Profile updated.', 'success'); 
            }} addToast={addToast} onExportData={() => addToast('Exporting...')} onImportData={() => addToast('Importing...')} onClearData={() => addToast('Clearing...')} language={language} onUpdateLanguage={setLanguage} currency={currency} onUpdateCurrency={setCurrency} botMode={botMode} onUpdateBotMode={setBotMode} spendingLimit={spendingLimit} onUpdateSpendingLimit={setSpendingLimit} spendingPeriod={spendingPeriod} onUpdateSpendingPeriod={setSpendingPeriod} />}
        </div>
      </main>

      {isLogoutModalOpen && (
          <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/95 backdrop-blur-2xl animate-fade-in">
              <div className="bg-[#0f172a] border border-rose-500/30 rounded-[3rem] w-full max-w-sm shadow-[0_0_100px_rgba(244,63,94,0.2)] p-10 text-center animate-slide-up relative">
                  <div className="w-20 h-20 bg-rose-500/20 rounded-[2rem] flex items-center justify-center mx-auto mb-8 border border-rose-500/30"><ShieldX className="w-10 h-10 text-rose-500" /></div>
                  <h3 className="text-2xl font-black text-white mb-3 uppercase tracking-tighter">Terminate?</h3>
                  <div className="space-y-4">
                      <button onClick={confirmLogout} className="w-full py-4 bg-rose-600 hover:bg-rose-500 text-white font-black rounded-2xl shadow-xl transition-all">Sign Out</button>
                      <button onClick={() => setIsLogoutModalOpen(false)} className="w-full py-4 bg-slate-900/50 text-slate-400 font-bold rounded-2xl border border-white/5 hover:text-white transition-all">Stay Connected</button>
                  </div>
              </div>
          </div>
      )}

      <ToastContainer toasts={toasts} onRemove={removeToast} />
    </div>
  );
};

export default App;

import React, { useMemo, useState, useEffect } from 'react';
import { LineChart, Line, CartesianGrid, Tooltip, ResponsiveContainer, PieChart, Pie, Cell } from 'recharts';
import { Account, Transaction, TransactionType, Category, UserPlan, Goal, Budget, SpendingStatus, SpendingPeriod } from '../types';
import { Flame, Wallet, CreditCard, Target, Zap, Microscope, FileText, ChevronDown, AlignLeft, GitFork, UserCircle, PieChart as PieChartIcon, TrendingUp } from 'lucide-react';

interface DashboardProps {
  accounts: Account[];
  transactions: Transaction[];
  goals: Goal[];
  budgets: Budget[];
  onNavigate: (tab: string) => void;
  onAddAccount?: () => void;
  onAddTransaction?: () => void;
  onAddGoal?: () => void;
  formatCurrency: (amount: number) => string | React.ReactNode;
  userPlan?: UserPlan;
  onAskCoach?: (message: string) => void;
  isPinMode?: boolean;
  pinnedIds?: string[];
  onTogglePin?: (id: string) => void;
  trackEvent?: (id: string) => void;
  insightUsage?: number;
  spendingStatus?: SpendingStatus;
  currentPeriodSpend?: number;
  spendingLimit?: number;
  spendingPeriod?: SpendingPeriod;
  userName?: string;
}

const COLORS = ['#3b82f6', '#f97316', '#10b981', '#8b5cf6', '#06b6d4', '#ec4899', '#64748b'];

const Dashboard: React.FC<DashboardProps> = ({ 
    accounts, 
    transactions, 
    goals, 
    budgets,
    onNavigate, 
    onAddAccount, 
    onAddTransaction, 
    onAddGoal, 
    formatCurrency, 
    userPlan, 
    onAskCoach, 
    insightUsage = 0,
    spendingStatus,
    currentPeriodSpend = 0,
    spendingLimit = 1000,
    spendingPeriod = 'monthly',
    userName = 'Pilot'
}) => {
  const [spendingComparison, setSpendingComparison] = useState<'year' | 'month'>('year');
  const [activeMenu, setActiveMenu] = useState<string | null>(null);

  // Close menus on click outside
  useEffect(() => {
      const handleClickOutside = () => setActiveMenu(null);
      document.addEventListener('click', handleClickOutside);
      return () => document.removeEventListener('click', handleClickOutside);
  }, []);

  const toggleMenu = (e: React.MouseEvent, menuId: string) => {
      e.stopPropagation();
      setActiveMenu(activeMenu === menuId ? null : menuId);
  };

  const today = new Date();
  const currentMonth = today.getMonth();
  const currentYear = today.getFullYear();
  const dayName = today.toLocaleDateString('en-US', { weekday: 'long' });

  // --- Data Calculations ---

  const netWorth = useMemo(() => accounts.reduce((acc, curr) => acc + curr.balance, 0), [accounts]);

  // Credit Card Debt: Sum of absolute values of NEGATIVE balances on 'Credit Card' type accounts
  const creditCardDebt = useMemo(() => {
      return accounts
        .filter(a => a.type === 'Credit Card' && a.balance < 0)
        .reduce((acc, curr) => acc + Math.abs(curr.balance), 0);
  }, [accounts]);

  const stats = useMemo(() => {
    const currentMTDExpenses = transactions.filter(t => {
      const d = new Date(t.date);
      return t.type === TransactionType.EXPENSE && d.getMonth() === currentMonth && d.getFullYear() === currentYear;
    });
    const currentMTDTotal = currentMTDExpenses.reduce((acc, t) => acc + t.amount, 0);
    const currentDay = today.getDate();
    const currentDailyAvg = currentMTDTotal / Math.max(currentDay, 1);

    return { currentDailyAvg };
  }, [transactions, currentMonth, currentYear]);

  const expenditureData = useMemo(() => {
    const expenses = transactions.filter(t => 
        t.type === TransactionType.EXPENSE && 
        new Date(t.date).getMonth() === currentMonth &&
        new Date(t.date).getFullYear() === currentYear
    );

    const total = expenses.reduce((acc, t) => acc + t.amount, 0);
    const catMap: Record<string, number> = {};

    expenses.forEach(t => {
        catMap[t.category] = (catMap[t.category] || 0) + t.amount;
    });

    const chartData = Object.entries(catMap)
        .map(([name, value]) => ({ name, value }))
        .sort((a, b) => b.value - a.value);

    // No Mock Data: Return empty state if no data
    if (chartData.length === 0) {
        return { chartData: [], total: 0, isEmpty: true, topCategory: null };
    }

    const topCategory = chartData[0];

    return { chartData, total, isEmpty: false, topCategory };
  }, [transactions, currentMonth, currentYear]);

  const lineChartData = useMemo(() => {
    const daysInCurrentMonth = new Date(currentYear, currentMonth + 1, 0).getDate();
    const data = [];

    const getDailySpend = (month: number, year: number) => {
        const daily = new Array(32).fill(0);
        transactions.forEach(t => {
            const d = new Date(t.date);
            if (t.type === TransactionType.EXPENSE && d.getMonth() === month && d.getFullYear() === year) {
                daily[d.getDate()] += t.amount;
            }
        });
        // Cumulative
        for (let i = 1; i < daily.length; i++) daily[i] += daily[i-1];
        return daily;
    };

    const currentMonthData = getDailySpend(currentMonth, currentYear);

    let comparisonData: number[] = [];
    if (spendingComparison === 'year') {
        comparisonData = getDailySpend(currentMonth, currentYear - 1);
    } else {
        // Last Month Logic
        let prevMonth = currentMonth - 1;
        let prevYear = currentYear;
        if (prevMonth < 0) { prevMonth = 11; prevYear = currentYear - 1; }
        comparisonData = getDailySpend(prevMonth, prevYear);
    }

    for (let i = 1; i <= daysInCurrentMonth; i++) {
        data.push({
            day: i,
            ThisMonth: currentMonthData[i],
            Comparison: comparisonData[i] 
        });
    }
    return data;
  }, [transactions, currentMonth, currentYear, spendingComparison]);

  const recurringBills = useMemo(() => {
      const subs = transactions.filter(t => t.category === Category.SUBSCRIPTION);
      const unique = new Map();
      subs.forEach(t => {
          if (!unique.has(t.merchant)) unique.set(t.merchant, t);
      });
      return Array.from(unique.values()).slice(0, 5);
  }, [transactions]);

  const recentTransactions = useMemo(() => {
      return transactions.slice(0, 4);
  }, [transactions]);

  // Goal Vector Logic
  const goalMetrics = useMemo(() => {
      const limitVal = Number(spendingLimit);
      const safeLimit = !isNaN(limitVal) && limitVal > 0 ? limitVal : 1;
      const budgetUtilization = (currentPeriodSpend / safeLimit) * 100;

      // Calculate individual budget progress
      const budgetProgress = budgets.map(b => {
          const spent = transactions
            .filter(t => t.category === b.category && t.type === TransactionType.EXPENSE && new Date(t.date).getMonth() === currentMonth)
            .reduce((sum, t) => sum + t.amount, 0);
          return { ...b, spent, percentage: Math.min((spent / b.limit) * 100, 100) };
      });

      return { budgetUtilization, budgetProgress };
  }, [currentPeriodSpend, spendingLimit, budgets, transactions, currentMonth]);

  const neuralCapacity = userPlan === 'ultra' ? 1500 : userPlan === 'pro' ? 50 : 3;
  const neuralRemaining = Math.max(0, neuralCapacity - insightUsage);

  // Safe Name Display
  const safeName = userName && userName.trim() !== '' ? userName : 'Pilot';

  // Safe Limit Display
  const displayLimit = spendingLimit && !isNaN(Number(spendingLimit)) ? Number(spendingLimit) : 0;

  return (
    <div className="h-full overflow-y-auto custom-scrollbar pb-20 px-2 md:px-0">

        {/* Header */}
        <div className="mb-6 mt-2">
            <h1 className="text-2xl md:text-3xl font-black text-white uppercase tracking-tight">Good {dayName}, {safeName}</h1>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">

            {/* LEFT MAIN PANEL (Span 8) */}
            <div className="lg:col-span-8 flex flex-col gap-6">

                {/* 1. Expenditure Topology (Pie Chart) */}
                <div className="glass-card p-6 md:p-8 rounded-[2.5rem] border border-white/5 bg-[#0f172a]/60 backdrop-blur-xl relative overflow-hidden flex flex-col md:flex-row items-center gap-8 min-h-[300px]">
                    {/* Donut Chart */}
                    <div className="w-48 h-48 md:w-56 md:h-56 relative shrink-0 flex items-center justify-center">
                        {expenditureData.isEmpty ? (
                            <div className="text-center opacity-50">
                                <div className="w-40 h-40 rounded-full border-4 border-slate-800 border-dashed flex items-center justify-center">
                                    <span className="text-xs font-bold text-slate-500">No Data</span>
                                </div>
                            </div>
                        ) : (
                            <ResponsiveContainer width="100%" height="100%">
                                <PieChart>
                                    <Pie
                                        data={expenditureData.chartData}
                                        cx="50%"
                                        cy="50%"
                                        innerRadius={60}
                                        outerRadius={90}
                                        paddingAngle={2}
                                        dataKey="value"
                                        stroke="none"
                                    >
                                        {expenditureData.chartData.map((entry, index) => (
                                            <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                                        ))}
                                    </Pie>
                                    <Tooltip 
                                        contentStyle={{ backgroundColor: '#020617', border: '1px solid rgba(255,255,255,0.1)', borderRadius: '12px', padding: '8px' }} 
                                        itemStyle={{ color: '#fff', fontSize: '12px', fontWeight: 'bold' }} 
                                        formatter={(v: number) => formatCurrency(v)} 
                                    />
                                </PieChart>
                            </ResponsiveContainer>
                        )}
                    </div>

                    {/* Legend / Text Area */}
                    <div className="flex-1 w-full">
                        <div className="flex justify-between items-start mb-6">
                            <h3 className="text-sm font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
                                <AlignLeft className="w-4 h-4 text-indigo-500" />
                                Expenditure Topology
                            </h3>
                        </div>

                        {expenditureData.topCategory ? (
                            <div className="mb-6 p-4 rounded-2xl bg-indigo-500/10 border border-indigo-500/20 flex items-center justify-between">
                                <div>
                                    <span className="text-[10px] font-black text-indigo-400 uppercase tracking-widest block mb-1">Primary Drain</span>
                                    <span className="text-lg font-bold text-white">{expenditureData.topCategory.name}</span>
                                </div>
                                <div className="text-right">
                                    <span className="text-xl font-black text-white">{formatCurrency(expenditureData.topCategory.value)}</span>
                                    <span className="text-[10px] font-bold text-slate-400 block">{((expenditureData.topCategory.value / expenditureData.total) * 100).toFixed(1)}%</span>
                                </div>
                            </div>
                        ) : (
                            <div className="mb-6 p-4 rounded-2xl bg-slate-900 border border-white/5 flex items-center justify-center text-slate-500 text-xs font-bold">
                                No spending detected this month.
                            </div>
                        )}

                        <div className="space-y-3">
                            {expenditureData.chartData.slice(0, 3).map((item, i) => (
                                <div key={i} className="flex items-center justify-between group">
                                    <div className="flex items-center gap-3">
                                        <div className="w-2.5 h-2.5 rounded-full" style={{ backgroundColor: COLORS[i % COLORS.length] }}></div>
                                        <span className="text-xs font-bold text-slate-300 group-hover:text-white transition-colors">{item.name}</span>
                                    </div>
                                    <div className="h-1 flex-1 mx-4 bg-slate-800/50 rounded-full overflow-hidden">
                                        <div className="h-full rounded-full transition-all duration-1000" style={{ width: `${(item.value / expenditureData.total) * 60}%`, backgroundColor: COLORS[i % COLORS.length], opacity: 0.6 }}></div>
                                    </div>
                                    <span className="text-[10px] font-bold text-slate-500">This Month</span>
                                </div>
                            ))}
                        </div>
                    </div>
                </div>

                {/* 2. Middle Row: Stats + Transactions */}
                <div className="grid grid-cols-1 md:grid-cols-12 gap-6">
                    {/* Left Sub-Col: Small Cards (Span 4) */}
                    <div className="md:col-span-4 flex flex-col gap-6">
                        <div className="glass-card p-6 rounded-[2rem] border border-white/5 bg-[#0f172a]/60 flex flex-col justify-center min-h-[140px]">
                            <div className="flex items-center gap-2 mb-2">
                                <Flame className="w-4 h-4 text-orange-500" />
                                <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Burn Rate/Day</span>
                            </div>
                            <div className="text-3xl font-black text-white">{formatCurrency(stats.currentDailyAvg)}</div>
                        </div>

                        <div className="glass-card p-6 rounded-[2rem] border border-white/5 bg-[#0f172a]/60 flex flex-col justify-center min-h-[140px]">
                            <div className="flex items-center gap-2 mb-2">
                                <Zap className="w-4 h-4 text-purple-500" />
                                <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Remaining Capacity</span>
                            </div>
                            <div className="text-xl font-black text-white">{neuralRemaining} <span className="text-[10px] text-slate-500 uppercase">Tokens Left</span></div>
                        </div>
                    </div>

                    {/* Right Sub-Col: Transactions (Span 8) */}
                    <div className="md:col-span-8 glass-card rounded-[2.5rem] border border-white/5 bg-[#0f172a]/60 p-6 overflow-hidden flex flex-col">
                        <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest mb-4">My Recent Transactions</h3>
                        <div className="flex-1 w-full">
                            <table className="w-full text-left border-collapse">
                                <thead className="text-[9px] font-black text-slate-500 uppercase tracking-widest border-b border-white/5">
                                    <tr>
                                        <th className="py-2">Date</th>
                                        <th className="py-2">Name</th>
                                        <th className="py-2 text-right">Amount</th>
                                    </tr>
                                </thead>
                                <tbody className="text-xs font-bold text-slate-300">
                                    {recentTransactions.map((t) => (
                                        <tr key={t.id} className="border-b border-white/5 last:border-0 hover:bg-white/5 transition-colors">
                                            <td className="py-4 text-slate-500 font-mono text-[10px]">{new Date(t.date).toLocaleDateString('en-US', { month: 'short', day: 'numeric' }).toUpperCase()}</td>
                                            <td className="py-4">{t.merchant}</td>
                                            <td className={`py-4 text-right ${t.type === TransactionType.INCOME ? 'text-emerald-400' : 'text-white'}`}>{formatCurrency(t.amount)}</td>
                                        </tr>
                                    ))}
                                    {recentTransactions.length === 0 && (
                                        <tr><td colSpan={3} className="py-8 text-center text-slate-500 italic">No recent activity.</td></tr>
                                    )}
                                </tbody>
                            </table>
                        </div>
                    </div>
                </div>

                {/* 3. Spending Graph */}
                <div className="glass-card p-8 rounded-[2.5rem] border border-white/5 bg-[#0f172a]/60 h-[280px] flex flex-col">
                    <div className="flex justify-between items-center mb-2">
                        <h3 className="text-sm font-black text-slate-400 uppercase tracking-widest">Spending</h3>

                        <div className="relative">
                            <button 
                                onClick={(e) => toggleMenu(e, 'spending_menu')}
                                className="flex items-center gap-2 border border-white/10 rounded px-2 py-1 bg-slate-900 cursor-pointer hover:bg-slate-800 transition-colors"
                            >
                                <span className="text-[10px] font-bold text-slate-400 uppercase">
                                    This month vs. {spendingComparison === 'year' ? 'Last Year' : 'Last Month'}
                                </span>
                                <ChevronDown className="w-3 h-3 text-slate-500" />
                            </button>
                            {activeMenu === 'spending_menu' && (
                                <div className="absolute right-0 top-full mt-2 w-40 bg-slate-900 border border-white/10 rounded-xl shadow-xl z-20 overflow-hidden animate-fade-in">
                                    <button onClick={() => { setSpendingComparison('year'); setActiveMenu(null); }} className="w-full text-left px-4 py-3 text-[10px] font-bold text-slate-300 hover:bg-white/5 hover:text-white uppercase tracking-wider">Vs Last Year</button>
                                    <button onClick={() => { setSpendingComparison('month'); setActiveMenu(null); }} className="w-full text-left px-4 py-3 text-[10px] font-bold text-slate-300 hover:bg-white/5 hover:text-white uppercase tracking-wider">Vs Last Month</button>
                                </div>
                            )}
                        </div>
                    </div>
                    <div className="flex-1 w-full min-h-0 relative">
                        <ResponsiveContainer width="100%" height="100%">
                            <LineChart data={lineChartData}>
                                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#1e293b" />
                                <Tooltip 
                                    contentStyle={{ backgroundColor: '#020617', border: '1px solid rgba(255,255,255,0.1)', borderRadius: '8px', boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.5)' }} 
                                    itemStyle={{ fontSize: '11px', fontWeight: 'bold', color: '#fff' }}
                                    formatter={(v: number) => formatCurrency(v)}
                                />
                                <Line type="monotone" dataKey="Comparison" stroke="#475569" strokeWidth={2} dot={false} strokeDasharray="5 5" />
                                <Line type="monotone" dataKey="ThisMonth" stroke="#6366f1" strokeWidth={3} dot={false} />
                            </LineChart>
                        </ResponsiveContainer>
                    </div>
                    <div className="flex justify-center gap-6 mt-2">
                        <div className="flex items-center gap-2">
                            <div className="w-2 h-2 rounded-full bg-slate-600"></div>
                            <span className="text-[10px] font-bold text-slate-500 uppercase">{spendingComparison === 'year' ? 'Month Last Year' : 'Last Month'}</span>
                        </div>
                        <div className="flex items-center gap-2">
                            <div className="w-2 h-2 rounded-full bg-indigo-500"></div>
                            <span className="text-[10px] font-bold text-indigo-400 uppercase">This Month</span>
                        </div>
                    </div>
                </div>

            </div>

            {/* RIGHT SIDEBAR (Span 4) */}
            <div className="lg:col-span-4 flex flex-col gap-6">

                {/* 1. Goal Vector */}
                <div className="glass-card p-6 rounded-[2.5rem] border border-white/5 bg-slate-900/40 flex flex-col gap-6">
                    <div className="flex items-center gap-3">
                        <div className="w-10 h-10 rounded-full bg-indigo-500/20 flex items-center justify-center border border-indigo-500/30">
                            <Target className="w-5 h-5 text-indigo-400" />
                        </div>
                        <div>
                            <h3 className="text-sm font-black text-white uppercase tracking-wider">Goal Vector</h3>
                            <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">Financial Velocity</p>
                        </div>
                    </div>

                    <div className="space-y-5 max-h-60 overflow-y-auto custom-scrollbar pr-1">
                        {/* 1. Global Monthly Limit */}
                        <div>
                            <div className="flex justify-between items-end mb-2">
                                <span className="text-[10px] font-bold text-slate-400 uppercase tracking-wider">Monthly Limit</span>
                                <span className="text-[10px] font-black text-amber-400">
                                    {formatCurrency(currentPeriodSpend)} <span className="text-slate-600">/ {formatCurrency(displayLimit)}</span>
                                </span>
                            </div>
                            <div className="h-2 w-full bg-slate-800 rounded-full overflow-hidden border border-white/5">
                                <div 
                                    className={`h-full rounded-full transition-all duration-1000 ${goalMetrics.budgetUtilization > 100 ? 'bg-rose-500' : 'bg-gradient-to-r from-amber-400 to-orange-500'}`}
                                    style={{ width: `${Math.min(goalMetrics.budgetUtilization, 100)}%` }}
                                ></div>
                            </div>
                        </div>

                        {/* 2. Individual Savings Goals */}
                        {goals.length > 0 && (
                            <>
                                <div className="h-px bg-white/5 my-2"></div>
                                <span className="text-[9px] font-black text-emerald-400 uppercase tracking-widest block mb-2 opacity-80">Active Goals</span>
                                {goals.map(goal => {
                                    const progress = Math.min((goal.currentAmount / goal.targetAmount) * 100, 100);
                                    return (
                                        <div key={goal.id}>
                                            <div className="flex justify-between items-end mb-1">
                                                <span className="text-[10px] font-bold text-slate-400 uppercase tracking-wider truncate max-w-[120px]">{goal.name}</span>
                                                <span className="text-[9px] font-black text-emerald-400">
                                                    {formatCurrency(goal.currentAmount)}
                                                </span>
                                            </div>
                                            <div className="h-1.5 w-full bg-slate-800 rounded-full overflow-hidden border border-white/5">
                                                <div 
                                                    className={`h-full rounded-full transition-all duration-1000 bg-gradient-to-r ${goal.color}`} 
                                                    style={{ width: `${progress}%` }}
                                                ></div>
                                            </div>
                                        </div>
                                    );
                                })}
                            </>
                        )}

                        {/* 3. Category Limits (Secondary) */}
                        {goalMetrics.budgetProgress && goalMetrics.budgetProgress.length > 0 && (
                            <>
                                <div className="h-px bg-white/5 my-2"></div>
                                <span className="text-[9px] font-black text-indigo-400 uppercase tracking-widest block mb-2 opacity-80">Category Budgets</span>
                                {goalMetrics.budgetProgress.map(budget => (
                                    <div key={budget.id}>
                                        <div className="flex justify-between items-end mb-1">
                                            <span className="text-[10px] font-bold text-slate-400 uppercase tracking-wider truncate max-w-[120px]">{budget.category}</span>
                                            <span className="text-[9px] font-black text-indigo-300">
                                                {formatCurrency(budget.spent)} / {formatCurrency(budget.limit)}
                                            </span>
                                        </div>
                                        <div className="h-1.5 w-full bg-slate-800 rounded-full overflow-hidden border border-white/5">
                                            <div 
                                                className={`h-full rounded-full transition-all duration-1000 ${budget.percentage > 100 ? 'bg-rose-500' : 'bg-indigo-500'}`}
                                                style={{ width: `${budget.percentage}%` }}
                                            ></div>
                                        </div>
                                    </div>
                                ))}
                            </>
                        )}

                        {goals.length === 0 && !goalMetrics.budgetProgress?.length && (
                            <div className="text-center py-4 border border-dashed border-white/10 rounded-xl">
                                <p className="text-[10px] text-slate-500 font-medium">No extra targets set.</p>
                                <button onClick={() => onAddGoal && onAddGoal()} className="text-[10px] text-indigo-400 font-bold uppercase mt-1 hover:text-indigo-300">Create Goal</button>
                            </div>
                        )}
                    </div>

                    <button 
                        onClick={() => onNavigate('sandbox')}
                        className="w-full py-3.5 bg-indigo-600 hover:bg-indigo-500 text-white rounded-xl text-xs font-black uppercase tracking-widest shadow-lg shadow-indigo-500/20 active:scale-95 transition-all flex items-center justify-center gap-2 mt-auto shrink-0"
                    >
                        <Microscope className="w-3.5 h-3.5" /> Simulate My Goal
                    </button>
                </div>

                {/* 2. Net Worth & Credit Card */}
                <div className="grid grid-cols-2 gap-4">
                    <div className="glass-card p-5 rounded-[2rem] border border-white/5 bg-slate-900/40 flex flex-col justify-between h-32">
                        <div className="flex justify-between items-start">
                            <span className="text-[10px] font-black text-slate-500 uppercase tracking-wider">Net Worth</span>
                            <Wallet className="w-4 h-4 text-blue-500" />
                        </div>
                        <div className="text-white font-black text-sm truncate">{formatCurrency(netWorth)}</div>
                    </div>
                    <div className="glass-card p-5 rounded-[2rem] border border-white/5 bg-slate-900/40 flex flex-col justify-between h-32">
                        <div className="flex justify-between items-start">
