import React, { useState } from 'react';
import { Language, SpendingPeriod } from '../types';
import { Check, ArrowRight, Shield, User } from 'lucide-react';

interface OnboardingModalProps {
  onComplete: (name: string, lang: Language, period: SpendingPeriod, limit: number) => void;
}

const OnboardingModal: React.FC<OnboardingModalProps> = ({ onComplete }) => {
  const [step, setStep] = useState(1);
  const [name, setName] = useState('');
  const [language, setLanguage] = useState<Language>('en');
  const [period, setPeriod] = useState<SpendingPeriod>('monthly');
  const [limit, setLimit] = useState<string>('1000');

  const totalSteps = 4;

  const handleNext = () => {
    if (step < totalSteps) {
      if (step === 1 && !name.trim()) return; 
      setStep(step + 1);
    } else {
      const numLimit = parseFloat(limit);
      const finalLimit = isNaN(numLimit) || numLimit <= 0 ? 1000 : numLimit;
      onComplete(name.trim() || 'Pilot', language, period, finalLimit);
    }
  };

  return (
    <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-[#020617] bg-opacity-95 backdrop-blur-xl">
      <div className="w-full max-w-md bg-slate-950 border border-white/10 rounded-[2rem] p-8 shadow-2xl animate-fade-in relative overflow-hidden">
        <div className="absolute top-0 left-0 w-full h-1 bg-slate-800">
          <div 
            className="h-full bg-indigo-500 transition-all duration-500" 
            style={{ width: `${(step / totalSteps) * 100}%` }} 
          />
        </div>

        <div className="mb-8 text-center">
          <div className="w-12 h-12 bg-indigo-500/20 rounded-full flex items-center justify-center mx-auto mb-4 border border-indigo-500/30">
            <Shield className="w-6 h-6 text-indigo-400" />
          </div>
          <h2 className="text-2xl font-black text-white uppercase tracking-tight">System Initialization</h2>
          <p className="text-slate-400 text-xs font-bold uppercase tracking-widest mt-2">Mandatory Configuration</p>
        </div>

        <div className="min-h-[200px]">
          {step === 1 && (
            <div className="space-y-4 animate-slide-up">
              <label className="block text-sm font-bold text-slate-300 mb-2">What should we call you?</label>
              <div className="relative">
                <User className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-500" />
                <input 
                  type="text" 
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  className="w-full bg-slate-900 border border-white/20 rounded-xl py-4 pl-12 pr-4 text-lg font-bold text-white focus:outline-none focus:border-indigo-500 transition-all placeholder:text-slate-700"
                  placeholder="e.g. Commander"
                  autoFocus
                />
              </div>
              <p className="text-xs text-slate-500">This will be your identity in the Nova ecosystem.</p>
            </div>
          )}

          {step === 2 && (
            <div className="space-y-4 animate-slide-up">
              <label className="block text-sm font-bold text-slate-300 mb-2">Select Interface Language</label>
              <div className="grid grid-cols-2 gap-4">
                <button 
                  onClick={() => setLanguage('en')}
                  className={`p-4 rounded-xl border-2 font-bold transition-all ${language === 'en' ? 'border-indigo-500 bg-indigo-500/20 text-white' : 'border-white/10 bg-white/5 text-slate-500 hover:border-white/20'}`}
                >
                  English
                </button>
                <button 
                  onClick={() => setLanguage('vi')}
                  className={`p-4 rounded-xl border-2 font-bold transition-all ${language === 'vi' ? 'border-indigo-500 bg-indigo-500/20 text-white' : 'border-white/10 bg-white/5 text-slate-500 hover:border-white/20'}`}
                >
                  Tiếng Việt
                </button>
              </div>
            </div>
          )}

          {step === 3 && (
            <div className="space-y-4 animate-slide-up">
              <label className="block text-sm font-bold text-slate-300 mb-2">Enforcement Cycle</label>
              <p className="text-xs text-slate-500 mb-4">How often should Nova reset your spending tracking?</p>
              <div className="space-y-3">
                <button 
                  onClick={() => setPeriod('weekly')}
                  className={`w-full p-4 rounded-xl border-2 font-bold text-left transition-all flex justify-between items-center ${period === 'weekly' ? 'border-indigo-500 bg-indigo-500/20 text-white' : 'border-white/10 bg-white/5 text-slate-500 hover:border-white/20'}`}
                >
                  <span>Weekly (Mon - Sun)</span>
                  {period === 'weekly' && <Check className="w-5 h-5 text-indigo-400" />}
                </button>
                <button 
                  onClick={() => setPeriod('monthly')}
                  className={`w-full p-4 rounded-xl border-2 font-bold text-left transition-all flex justify-between items-center ${period === 'monthly' ? 'border-indigo-500 bg-indigo-500/20 text-white' : 'border-white/10 bg-white/5 text-slate-500 hover:border-white/20'}`}
                >
                  <span>Monthly (1st - 30th)</span>
                  {period === 'monthly' && <Check className="w-5 h-5 text-indigo-400" />}
                </button>
              </div>
            </div>
          )}

          {step === 4 && (
            <div className="space-y-4 animate-slide-up">
              <label className="block text-sm font-bold text-slate-300 mb-2">Hard Spending Limit</label>
              <p className="text-xs text-slate-500 mb-4">Enter a numeric value. Alerts trigger at 80% and 100%.</p>
              <div className="relative">
                <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 font-bold">$</span>
                <input 
                  type="number" 
                  value={limit}
                  onChange={(e) => setLimit(e.target.value)}
                  className="w-full bg-slate-900 border border-white/20 rounded-xl py-4 pl-8 pr-4 text-2xl font-bold text-white focus:outline-none focus:border-indigo-500 transition-all placeholder:text-slate-700"
                  autoFocus
                />
              </div>
            </div>
          )}
        </div>

        <button 
          onClick={handleNext}
          disabled={step === 1 && !name.trim()}
          className="w-full mt-8 py-4 bg-white text-slate-950 font-black uppercase tracking-[0.2em] rounded-xl hover:bg-slate-200 transition-all active:scale-95 flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
        >
          {step === totalSteps ? 'Initialize Core' : 'Next Step'} <ArrowRight className="w-4 h-4" />
        </button>
      </div>
    </div>
  );
};

