export default Dashboard;

import React, { useMemo, useState, useEffect } from 'react';
import { LineChart, Line, CartesianGrid, Tooltip, ResponsiveContainer, PieChart, Pie, Cell, XAxis, YAxis } from 'recharts';
import { Account, Transaction, TransactionType, Category, UserPlan, Goal, Budget, SpendingStatus, SpendingPeriod } from '../types';
import { Flame, Wallet, CreditCard, Target, Zap, Microscope, FileText, ChevronDown, AlignLeft, GitFork, UserCircle, PieChart as PieChartIcon, TrendingUp, AlertCircle, Check, Flag, Handshake, BrainCircuit, BarChart3, ArrowRight } from 'lucide-react';

interface DashboardProps {
  accounts: Account[];
  transactions: Transaction[];
  goals: Goal[];
  budgets: Budget[];
  onNavigate: (tab: string, params?: any) => void;
  onAddAccount?: () => void;
  onAddTransaction?: () => void;
  onAddGoal?: () => void;
  formatCurrency: (amount: number) => string | React.ReactNode;
  userPlan?: UserPlan;
  onAskCoach?: (message: string) => void;
  isPinMode?: boolean;
  pinnedIds?: string[];
  onTogglePin?: (id: string) => void;
  trackEvent?: (id: string) => void;
  insightUsage?: number;
  spendingStatus?: SpendingStatus;
  currentPeriodSpend?: number;
  spendingLimit?: number;
  spendingPeriod?: SpendingPeriod;
  userName?: string;
}

const COLORS = ['#3b82f6', '#f97316', '#10b981', '#8b5cf6', '#06b6d4', '#ec4899', '#64748b'];

const Dashboard: React.FC<DashboardProps> = ({ 
    accounts, 
    transactions, 
    goals, 
    budgets,
    onNavigate, 
    onAddAccount, 
    onAddTransaction, 
    onAddGoal, 
    formatCurrency, 
    userPlan, 
    onAskCoach, 
    insightUsage = 0,
    spendingStatus,
    currentPeriodSpend = 0,
    spendingLimit = 1000,
    spendingPeriod = 'monthly',
    userName = 'Pilot'
}) => {
  const [spendingComparison, setSpendingComparison] = useState<'year' | 'month'>('year');
  const [showScanConfirm, setShowScanConfirm] = useState(false);

  const today = new Date();
  const currentMonth = today.getMonth();
  const currentYear = today.getFullYear();
  const dayName = today.toLocaleDateString('en-US', { weekday: 'long' });

  const netWorth = useMemo(() => accounts.reduce((acc, curr) => acc + curr.balance, 0), [accounts]);

  const creditCardDebt = useMemo(() => {
      return accounts
        .filter(a => a.type === 'Credit Card' && a.balance < 0)
        .reduce((acc, curr) => acc + Math.abs(curr.balance), 0);
  }, [accounts]);

  const stats = useMemo(() => {
    const currentMTDExpenses = transactions.filter(t => {
      const d = new Date(t.date);
      return t.type === TransactionType.EXPENSE && d.getMonth() === currentMonth && d.getFullYear() === currentYear;
    });
    const currentMTDTotal = currentMTDExpenses.reduce((acc, t) => acc + t.amount, 0);
    const currentDailyAvg = currentMTDTotal / Math.max(today.getDate(), 1);

    return { currentDailyAvg };
  }, [transactions, currentMonth, currentYear]);

  const expenditureData = useMemo(() => {
    const expenses = transactions.filter(t => 
        t.type === TransactionType.EXPENSE && 
        new Date(t.date).getMonth() === currentMonth &&
        new Date(t.date).getFullYear() === currentYear
    );
    const total = expenses.reduce((acc, t) => acc + t.amount, 0);
    const catMap: Record<string, number> = {};
    expenses.forEach(t => { catMap[t.category] = (catMap[t.category] || 0) + t.amount; });
    const chartData = Object.entries(catMap)
        .map(([name, value]) => ({ name, value }))
        .sort((a, b) => b.value - a.value);
    if (chartData.length === 0) return { chartData: [], total: 0, isEmpty: true, topCategory: null };
    return { chartData, total, isEmpty: false, topCategory: chartData[0] };
  }, [transactions, currentMonth, currentYear]);

  const lineChartData = useMemo(() => {
    const daysInCurrentMonth = new Date(currentYear, currentMonth + 1, 0).getDate();
    const data = [];
    const getDailySpend = (month: number, year: number) => {
        const daily = new Array(32).fill(0);
        transactions.forEach(t => {
            const d = new Date(t.date);
            if (t.type === TransactionType.EXPENSE && d.getMonth() === month && d.getFullYear() === year) {
                daily[d.getDate()] += t.amount;
            }
        });
        for (let i = 1; i < daily.length; i++) daily[i] += daily[i-1];
        return daily;
    };
    const currentMonthData = getDailySpend(currentMonth, currentYear);
    let comparisonData: number[] = [];
    if (spendingComparison === 'year') {
        comparisonData = getDailySpend(currentMonth, currentYear - 1);
    } else {
        let prevMonth = currentMonth - 1;
        let prevYear = currentYear;
        if (prevMonth < 0) { prevMonth = 11; prevYear = currentYear - 1; }
        comparisonData = getDailySpend(prevMonth, prevYear);
    }
    for (let i = 1; i <= daysInCurrentMonth; i++) {
        data.push({ day: i, ThisMonth: currentMonthData[i], Comparison: comparisonData[i] });
    }
    return data;
  }, [transactions, currentMonth, currentYear, spendingComparison]);

  const recurringBills = useMemo(() => {
      const subs = transactions.filter(t => t.category === Category.SUBSCRIPTION);
      const unique = new Map();
      subs.forEach(t => { if (!unique.has(t.merchant)) unique.set(t.merchant, t); });
      return Array.from(unique.values()).slice(0, 5);
  }, [transactions]);

  const recentTransactions = useMemo(() => transactions.slice(0, 4), [transactions]);

  const goalMetrics = useMemo(() => {
      const limitVal = Number(spendingLimit);
      const safeLimit = !isNaN(limitVal) && limitVal > 0 ? limitVal : 1;
      const budgetUtilization = (currentPeriodSpend / safeLimit) * 100;
      const budgetProgress = budgets.map(b => {
          const spent = transactions
            .filter(t => t.category === b.category && t.type === TransactionType.EXPENSE && new Date(t.date).getMonth() === currentMonth)
            .reduce((sum, t) => sum + t.amount, 0);
          return { ...b, spent, percentage: Math.min((spent / b.limit) * 100, 100) };
      });
      return { budgetUtilization, budgetProgress };
  }, [currentPeriodSpend, spendingLimit, budgets, transactions, currentMonth]);

  const neuralCapacity = userPlan === 'ultra' ? 1500 : userPlan === 'pro' ? 50 : 3;
  const neuralRemaining = Math.max(0, neuralCapacity - insightUsage);
  const safeName = userName && userName.trim() !== '' ? userName : 'Pilot';
  const displayLimit = spendingLimit && !isNaN(Number(spendingLimit)) ? Number(spendingLimit) : 0;

  // Comparison logic for Spending Velocity Title
  const velocityDiff = useMemo(() => {
      const last = lineChartData[lineChartData.length - 1];
      if(!last) return 0;
      return last.ThisMonth - last.Comparison;
  }, [lineChartData]);

  return (
    <div className="h-full overflow-y-auto custom-scrollbar pb-24 px-2 md:px-0">
        <div className="mb-8 mt-2 flex flex-col md:flex-row md:items-end justify-between gap-4">
            <div>
                <h1 className="text-2xl md:text-3xl font-black text-white uppercase tracking-tight">Good {dayName}, {safeName}</h1>
                <p className="text-slate-400 text-xs font-bold uppercase tracking-widest mt-1">System Nominal • All Systems Go</p>
            </div>

            {/* Smart Money Tools / Quick Actions */}
            <div className="flex items-center gap-3">
                <button onClick={() => onNavigate('insights')} className="flex items-center gap-2 px-4 py-2 bg-indigo-600 hover:bg-indigo-500 rounded-xl text-white text-xs font-bold shadow-lg transition-all active:scale-95">
                    <BrainCircuit className="w-4 h-4" /> Advisor
                </button>
                <button onClick={() => onNavigate('negotiator')} className="flex items-center gap-2 px-4 py-2 bg-slate-800 hover:bg-slate-700 rounded-xl text-white text-xs font-bold border border-white/5 transition-all">
                    <Handshake className="w-4 h-4 text-emerald-400" /> Negotiate
                </button>
                <button onClick={() => onNavigate('investment')} className="flex items-center gap-2 px-4 py-2 bg-slate-800 hover:bg-slate-700 rounded-xl text-white text-xs font-bold border border-white/5 transition-all">
                    <BarChart3 className="w-4 h-4 text-amber-400" /> Invest
                </button>
            </div>
        </div>

        {/* Daily Summary Action */}
        <div className="mb-8 bg-gradient-to-r from-indigo-900/30 to-purple-900/30 border border-indigo-500/20 rounded-2xl p-4 flex items-center justify-between">
            <div className="flex items-center gap-4">
                <div className="w-10 h-10 rounded-full bg-indigo-500/20 flex items-center justify-center border border-indigo-500/30">
                    <Zap className="w-5 h-5 text-indigo-400" />
                </div>
                <div>
                    <h3 className="text-sm font-bold text-white">Daily Action Summary</h3>
                    <p className="text-xs text-slate-400">You have {goals.length} active goals and are tracking {Math.round(goalMetrics.budgetUtilization)}% of your monthly limit.</p>
                </div>
            </div>
            <button onClick={() => onNavigate('insights', { autoScan: true })} className="p-2 bg-indigo-600 rounded-lg text-white hover:bg-indigo-500 transition-colors">
                <ArrowRight className="w-4 h-4" />
            </button>
        </div>

        {/* Main Grid */}
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 items-stretch">

            {/* LEFT MAIN PANEL */}
            <div className="lg:col-span-8 flex flex-col gap-6">

                {/* 1. Spending Graph - SMALLER & CLEANER */}
                <div className="glass-card p-6 rounded-[2.5rem] border border-white/5 bg-[#0f172a]/60 h-[300px] flex flex-col">
                    <div className="flex justify-between items-center mb-2">
                        <div>
                            <h3 className="text-sm font-black text-slate-400 uppercase tracking-widest">Spending Velocity</h3>
                            <p className={`text-[10px] font-bold uppercase tracking-wider ${velocityDiff > 0 ? 'text-rose-400' : 'text-emerald-400'}`}>
                                {velocityDiff > 0 ? 'Last Year < This Month' : 'Last Year > This Month'}
                            </p>
                        </div>
                        <div className="flex bg-slate-950 border border-white/10 rounded-xl p-1">
                            <button onClick={() => setSpendingComparison('year')} className={`px-3 py-1.5 rounded-lg text-[9px] font-black uppercase transition-all ${spendingComparison === 'year' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-500 hover:text-slate-300'}`}>Vs Year</button>
                            <button onClick={() => setSpendingComparison('month')} className={`px-3 py-1.5 rounded-lg text-[9px] font-black uppercase transition-all ${spendingComparison === 'month' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-500 hover:text-slate-300'}`}>Vs Month</button>
                        </div>
                    </div>

                    {/* Compact Chart Container */}
                    <div className="flex-1 w-full min-h-0">
                        <ResponsiveContainer width="100%" height="100%">
                            <LineChart data={lineChartData} margin={{ top: 10, right: 30, left: -10, bottom: 5 }}>
                                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#1e293b" />
                                <XAxis dataKey="day" stroke="#475569" fontSize={10} tickLine={false} axisLine={false} dy={10} interval={6} />
                                <YAxis stroke="#475569" fontSize={10} tickLine={false} axisLine={false} tickFormatter={(val) => `$${val >= 1000 ? (val/1000).toFixed(0) + 'k' : val}`} />
                                <Tooltip contentStyle={{ backgroundColor: '#020617', border: '1px solid rgba(255,255,255,0.1)', borderRadius: '12px' }} itemStyle={{ fontSize: '11px', fontWeight: 'bold' }} formatter={(v: number) => formatCurrency(v)} />
                                <Line type="monotone" dataKey="Comparison" name="Last Year" stroke="#334155" strokeWidth={2} dot={false} strokeDasharray="5 5" />
                                <Line type="monotone" dataKey="ThisMonth" name="This Month" stroke="#6366f1" strokeWidth={3} dot={false} />
                            </LineChart>
                        </ResponsiveContainer>
                    </div>
                </div>

