                        <div className="flex justify-between items-start"><span className="text-[10px] font-black text-slate-500 uppercase tracking-wider">Debt</span><CreditCard className="w-4 h-4 text-rose-400" /></div>
                        <div className="text-white font-black text-sm truncate">{formatCurrency(creditCardDebt)}</div>
                    </div>
                </div>

                {/* 3. Recurring Bills - Balanced Height */}
