                    <button onClick={() => onNavigate('negotiator')} className="w-full py-3 bg-slate-800/50 hover:bg-slate-800 text-slate-400 hover:text-white rounded-xl text-[10px] font-black uppercase tracking-widest border border-white/5 mt-6 transition-all">Optimize Bills</button>
                </div>

            </div>
        </div>

        {/* Audit Modal */}
        {showScanConfirm && (
            <div className="fixed inset-0 z-[150] flex items-center justify-center p-4 bg-black/90 backdrop-blur-md animate-fade-in">
