export default Dashboard;

import React, { useMemo, useState, useEffect } from 'react';
import { LineChart, Line, CartesianGrid, Tooltip, ResponsiveContainer, PieChart, Pie, Cell, XAxis, YAxis } from 'recharts';
import { Account, Transaction, TransactionType, Category, UserPlan, Goal, Budget, SpendingStatus, SpendingPeriod } from '../types';
import { Flame, Wallet, CreditCard, Target, Zap, Microscope, FileText, ChevronDown, AlignLeft, GitFork, UserCircle, PieChart as PieChartIcon, TrendingUp, AlertCircle, Check, Flag, Handshake, BrainCircuit, BarChart3, ArrowRight } from 'lucide-react';

interface DashboardProps {
  accounts: Account[];
  transactions: Transaction[];
  goals: Goal[];
  budgets: Budget[];
  onNavigate: (tab: string, params?: any) => void;
  onAddAccount?: () => void;
  onAddTransaction?: () => void;
  onAddGoal?: () => void;
  formatCurrency: (amount: number) => string | React.ReactNode;
  userPlan?: UserPlan;
  onAskCoach?: (message: string) => void;
  isPinMode?: boolean;
  pinnedIds?: string[];
  onTogglePin?: (id: string) => void;
  trackEvent?: (id: string) => void;
  insightUsage?: number;
  spendingStatus?: SpendingStatus;
  currentPeriodSpend?: number;
  spendingLimit?: number;
  spendingPeriod?: SpendingPeriod;
  userName?: string;
}

const COLORS = ['#3b82f6', '#f97316', '#10b981', '#8b5cf6', '#06b6d4', '#ec4899', '#64748b'];

const Dashboard: React.FC<DashboardProps> = ({ 
    accounts, 
    transactions, 
    goals, 
    budgets,
    onNavigate, 
    onAddAccount, 
    onAddTransaction, 
    onAddGoal, 
    formatCurrency, 
    userPlan, 
    onAskCoach, 
    insightUsage = 0,
    spendingStatus,
    currentPeriodSpend = 0,
    spendingLimit = 1000,
    spendingPeriod = 'monthly',
    userName = 'Pilot'
}) => {
  const [spendingComparison, setSpendingComparison] = useState<'year' | 'month'>('year');
  const [showScanConfirm, setShowScanConfirm] = useState(false);

  const today = new Date();
  const currentMonth = today.getMonth();
  const currentYear = today.getFullYear();
  const dayName = today.toLocaleDateString('en-US', { weekday: 'long' });

  const netWorth = useMemo(() => accounts.reduce((acc, curr) => acc + curr.balance, 0), [accounts]);

  const creditCardDebt = useMemo(() => {
      return accounts
        .filter(a => a.type === 'Credit Card' && a.balance < 0)
        .reduce((acc, curr) => acc + Math.abs(curr.balance), 0);
  }, [accounts]);

  const stats = useMemo(() => {
    const currentMTDExpenses = transactions.filter(t => {
      const d = new Date(t.date);
      return t.type === TransactionType.EXPENSE && d.getMonth() === currentMonth && d.getFullYear() === currentYear;
    });
    const currentMTDTotal = currentMTDExpenses.reduce((acc, t) => acc + t.amount, 0);
    const currentDailyAvg = currentMTDTotal / Math.max(today.getDate(), 1);

    return { currentDailyAvg };
  }, [transactions, currentMonth, currentYear]);

  const expenditureData = useMemo(() => {
    const expenses = transactions.filter(t => 
        t.type === TransactionType.EXPENSE && 
        new Date(t.date).getMonth() === currentMonth && 
        new Date(t.date).getFullYear() === currentYear
    );
    const total = expenses.reduce((acc, t) => acc + t.amount, 0);
    const catMap: Record<string, number> = {};
    expenses.forEach(t => { catMap[t.category] = (catMap[t.category] || 0) + t.amount; });
    const chartData = Object.entries(catMap)
        .map(([name, value]) => ({ name, value }))
        .sort((a, b) => b.value - a.value);
    if (chartData.length === 0) return { chartData: [], total: 0, isEmpty: true, topCategory: null };
    return { chartData, total, isEmpty: false, topCategory: chartData[0] };
  }, [transactions, currentMonth, currentYear]);

  const lineChartData = useMemo(() => {
    const daysInCurrentMonth = new Date(currentYear, currentMonth + 1, 0).getDate();
    const data = [];
    const getDailySpend = (month: number, year: number) => {
        const daily = new Array(32).fill(0);
        transactions.forEach(t => {
            const d = new Date(t.date);
            if (t.type === TransactionType.EXPENSE && d.getMonth() === month && d.getFullYear() === year) {
                daily[d.getDate()] += t.amount;
            }
        });
        for (let i = 1; i < daily.length; i++) daily[i] += daily[i-1];
        return daily;
    };
    const currentMonthData = getDailySpend(currentMonth, currentYear);
    let comparisonData: number[] = [];
    if (spendingComparison === 'year') {
        comparisonData = getDailySpend(currentMonth, currentYear - 1);
    } else {
        let prevMonth = currentMonth - 1;
        let prevYear = currentYear;
        if (prevMonth < 0) { prevMonth = 11; prevYear = currentYear - 1; }
        comparisonData = getDailySpend(prevMonth, prevYear);
    }
    for (let i = 1; i <= daysInCurrentMonth; i++) {
        data.push({ day: i, ThisMonth: currentMonthData[i], Comparison: comparisonData[i] });
    }
    return data;
  }, [transactions, currentMonth, currentYear, spendingComparison]);

  const recurringBills = useMemo(() => {
      const subs = transactions.filter(t => t.category === Category.SUBSCRIPTION);
      const unique = new Map();
      subs.forEach(t => { if (!unique.has(t.merchant)) unique.set(t.merchant, t); });
      return Array.from(unique.values()).slice(0, 5);
  }, [transactions]);

  const recentTransactions = useMemo(() => transactions.slice(0, 4), [transactions]);

  const goalMetrics = useMemo(() => {
      const limitVal = Number(spendingLimit);
      const safeLimit = !isNaN(limitVal) && limitVal > 0 ? limitVal : 1;
      const budgetUtilization = (currentPeriodSpend / safeLimit) * 100;
      const budgetProgress = budgets.map(b => {
          const spent = transactions
            .filter(t => t.category === b.category && t.type === TransactionType.EXPENSE && new Date(t.date).getMonth() === currentMonth)
            .reduce((sum, t) => sum + t.amount, 0);
          return { ...b, spent, percentage: Math.min((spent / b.limit) * 100, 100) };
      });
      return { budgetUtilization, budgetProgress };
  }, [currentPeriodSpend, spendingLimit, budgets, transactions, currentMonth]);

  const neuralCapacity = userPlan === 'ultra' ? 1500 : userPlan === 'pro' ? 50 : 3;
  const neuralRemaining = Math.max(0, neuralCapacity - insightUsage);
  const safeName = userName && userName.trim() !== '' ? userName : 'Pilot';
  const displayLimit = spendingLimit && !isNaN(Number(spendingLimit)) ? Number(spendingLimit) : 0;

  // Comparison logic for Spending Velocity Title
  const velocityDiff = useMemo(() => {
      const last = lineChartData[lineChartData.length - 1];
      if(!last) return 0;
      return last.ThisMonth - last.Comparison;
  }, [lineChartData]);

  return (
    <div className="h-full overflow-y-auto custom-scrollbar pb-24 px-2 md:px-0">
        <div className="mb-8 mt-2 flex flex-col md:flex-row md:items-end justify-between gap-4">
            <div>
                <h1 className="text-2xl md:text-3xl font-black text-white uppercase tracking-tight">Good {dayName}, {safeName}</h1>
                <p className="text-slate-400 text-xs font-bold uppercase tracking-widest mt-1">System Nominal • All Systems Go</p>
            </div>

            {/* RESTORED: Smart Money Tools / Quick Actions */}
            <div className="flex items-center gap-3">
                <button onClick={() => onNavigate('insights')} className="flex items-center gap-2 px-4 py-2 bg-indigo-600 hover:bg-indigo-500 rounded-xl text-white text-xs font-bold shadow-lg transition-all active:scale-95">
                    <BrainCircuit className="w-4 h-4" /> Advisor
                </button>
                <button onClick={() => onNavigate('negotiator')} className="flex items-center gap-2 px-4 py-2 bg-slate-800 hover:bg-slate-700 rounded-xl text-white text-xs font-bold border border-white/5 transition-all">
                    <Handshake className="w-4 h-4 text-emerald-400" /> Negotiate
                </button>
                <button onClick={() => onNavigate('investment')} className="flex items-center gap-2 px-4 py-2 bg-slate-800 hover:bg-slate-700 rounded-xl text-white text-xs font-bold border border-white/5 transition-all">
                    <BarChart3 className="w-4 h-4 text-amber-400" /> Invest
                </button>
            </div>
        </div>

        {/* RESTORED: Daily Summary Action */}
        <div className="mb-8 bg-gradient-to-r from-indigo-900/30 to-purple-900/30 border border-indigo-500/20 rounded-2xl p-4 flex items-center justify-between">
            <div className="flex items-center gap-4">
                <div className="w-10 h-10 rounded-full bg-indigo-500/20 flex items-center justify-center border border-indigo-500/30">
                    <Zap className="w-5 h-5 text-indigo-400" />
                </div>
                <div>
                    <h3 className="text-sm font-bold text-white">Daily Action Summary</h3>
                    <p className="text-xs text-slate-400">You have {goals.length} active goals and are tracking {Math.round(goalMetrics.budgetUtilization)}% of your monthly limit.</p>
                </div>
            </div>
            <button onClick={() => onNavigate('insights', { autoScan: true })} className="p-2 bg-indigo-600 rounded-lg text-white hover:bg-indigo-500 transition-colors">
                <ArrowRight className="w-4 h-4" />
            </button>
        </div>

        {/* Main Grid: items-stretch to ensure equal height */}
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 items-stretch">

            {/* LEFT MAIN PANEL */}
            <div className="lg:col-span-8 flex flex-col gap-6">

                {/* 1. Spending Graph - EXTENDED HEIGHT & FIXED AXIS MARGINS */}
                <div className="glass-card p-6 rounded-[2.5rem] border border-white/5 bg-[#0f172a]/60 h-[380px] flex flex-col">
                    <div className="flex justify-between items-center mb-6">
                        <div>
                            <h3 className="text-sm font-black text-slate-400 uppercase tracking-widest">Spending Velocity</h3>
                            {/* Added Comparison Text Variable */}
                            <p className={`text-[10px] font-bold uppercase tracking-wider mt-1 ${velocityDiff > 0 ? 'text-rose-400' : 'text-emerald-400'}`}>
                                {velocityDiff > 0 ? 'Last Year < This Month' : 'Last Year > This Month'}
                            </p>
                        </div>
                        <div className="flex bg-slate-950 border border-white/10 rounded-xl p-1">
                            <button onClick={() => setSpendingComparison('year')} className={`px-3 py-1.5 rounded-lg text-[9px] font-black uppercase transition-all ${spendingComparison === 'year' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-500 hover:text-slate-300'}`}>Vs Year</button>
                            <button onClick={() => setSpendingComparison('month')} className={`px-3 py-1.5 rounded-lg text-[9px] font-black uppercase transition-all ${spendingComparison === 'month' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-500 hover:text-slate-300'}`}>Vs Month</button>
                        </div>
                    </div>

                    {/* Extended Chart Container with Proper Margins for Axis */}
                    <div className="flex-1 w-full min-h-0">
                        <ResponsiveContainer width="100%" height="100%">
                            <LineChart data={lineChartData} margin={{ top: 20, right: 30, left: 0, bottom: 10 }}>
                                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#1e293b" />
                                <XAxis dataKey="day" stroke="#475569" fontSize={10} tickLine={false} axisLine={false} dy={10} interval={6} />
                                <YAxis stroke="#475569" fontSize={10} tickLine={false} axisLine={false} tickFormatter={(val) => `$${val >= 1000 ? (val/1000).toFixed(0) + 'k' : val}`} />
                                <Tooltip contentStyle={{ backgroundColor: '#020617', border: '1px solid rgba(255,255,255,0.1)', borderRadius: '12px' }} itemStyle={{ fontSize: '11px', fontWeight: 'bold' }} formatter={(v: number) => formatCurrency(v)} />
                                <Line type="monotone" dataKey="Comparison" name="Last Year" stroke="#334155" strokeWidth={2} dot={false} strokeDasharray="5 5" />
                                <Line type="monotone" dataKey="ThisMonth" name="This Month" stroke="#6366f1" strokeWidth={3} dot={false} />
                            </LineChart>
                        </ResponsiveContainer>
                    </div>
                </div>

                {/* 2. Expenditure Topology */}
                <div className="glass-card p-6 md:p-8 rounded-[2.5rem] border border-white/5 bg-[#0f172a]/60 backdrop-blur-xl relative flex flex-col md:flex-row items-center gap-8">
                    <div className="w-48 h-48 md:w-56 md:h-56 relative shrink-0 flex items-center justify-center">
                        {expenditureData.isEmpty ? (
                            <div className="w-40 h-40 rounded-full border-4 border-slate-800 border-dashed flex items-center justify-center">
                                <span className="text-xs font-bold text-slate-500">No Data</span>
                            </div>
                        ) : (
                            <ResponsiveContainer width="100%" height="100%">
                                <PieChart>
                                    <Pie data={expenditureData.chartData} cx="50%" cy="50%" innerRadius={60} outerRadius={90} paddingAngle={2} dataKey="value" stroke="none">
                                        {expenditureData.chartData.map((entry, index) => (
                                            <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                                        ))}
                                    </Pie>
                                    <Tooltip contentStyle={{ backgroundColor: '#020617', border: '1px solid rgba(255,255,255,0.1)', borderRadius: '12px' }} itemStyle={{ color: '#fff', fontSize: '12px', fontWeight: 'bold' }} formatter={(v: number) => formatCurrency(v)} />
                                </PieChart>
                            </ResponsiveContainer>
                        )}
                    </div>

                    <div className="flex-1 w-full">
                        <h3 className="text-sm font-black text-slate-400 uppercase tracking-widest flex items-center gap-2 mb-6">
                            <AlignLeft className="w-4 h-4 text-indigo-500" /> Expenditure Topology
                        </h3>
                        {expenditureData.topCategory ? (
                            <div className="mb-6 p-4 rounded-2xl bg-indigo-500/10 border border-indigo-500/20 flex items-center justify-between">
                                <div>
                                    <span className="text-[10px] font-black text-indigo-400 uppercase tracking-widest block mb-1">Primary Drain</span>
                                    <span className="text-lg font-bold text-white">{expenditureData.topCategory.name}</span>
                                </div>
                                <div className="text-right">
                                    <span className="text-xl font-black text-white">{formatCurrency(expenditureData.topCategory.value)}</span>
                                    <span className="text-[10px] font-bold text-slate-400 block">{((expenditureData.topCategory.value / expenditureData.total) * 100).toFixed(1)}%</span>
                                </div>
                            </div>
                        ) : <div className="mb-6 p-4 rounded-2xl bg-slate-900 border border-white/5 flex items-center justify-center text-slate-500 text-xs font-bold">No spending detected.</div>}
                        <div className="space-y-3">
                            {expenditureData.chartData.slice(0, 3).map((item, i) => (
                                <div key={i} className="flex items-center justify-between group text-xs">
                                    <div className="flex items-center gap-3">
                                        <div className="w-2.5 h-2.5 rounded-full" style={{ backgroundColor: COLORS[i % COLORS.length] }}></div>
                                        <span className="font-bold text-slate-300">{item.name}</span>
                                    </div>
                                    <div className="h-1 flex-1 mx-4 bg-slate-800/50 rounded-full overflow-hidden">
                                        <div className="h-full rounded-full transition-all duration-1000" style={{ width: `${(item.value / expenditureData.total) * 60}%`, backgroundColor: COLORS[i % COLORS.length], opacity: 0.6 }}></div>
                                    </div>
                                    <span className="text-[10px] font-bold text-slate-500">MTD</span>
                                </div>
                            ))}
                        </div>
                    </div>
                </div>

                {/* 3. Middle Grid */}
                <div className="grid grid-cols-1 md:grid-cols-12 gap-6">
                    <div className="md:col-span-4 flex flex-col gap-6">
                        <div className="glass-card p-6 rounded-[2rem] border border-white/5 bg-[#0f172a]/60 flex flex-col justify-center min-h-[120px]">
                            <div className="flex items-center gap-2 mb-2"><Flame className="w-4 h-4 text-orange-500" /><span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Burn Rate/Day</span></div>
                            <div className="text-3xl font-black text-white">{formatCurrency(stats.currentDailyAvg)}</div>
                        </div>
                        <div className="glass-card p-6 rounded-[2rem] border border-white/5 bg-[#0f172a]/60 flex flex-col justify-center min-h-[120px]">
                            <div className="flex items-center gap-2 mb-2"><Zap className="w-4 h-4 text-purple-500" /><span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Remaining Capacity</span></div>
                            <div className="text-xl font-black text-white">{neuralRemaining} <span className="text-[10px] text-slate-500 uppercase">Tokens</span></div>
                        </div>
                    </div>
                    <div className="md:col-span-8 glass-card rounded-[2.5rem] border border-white/5 bg-[#0f172a]/60 p-6 flex flex-col">
                        <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest mb-4">My Recent Transactions</h3>
                        <table className="w-full text-left">
                            <thead className="text-[9px] font-black text-slate-500 uppercase border-b border-white/5">
                                <tr><th className="py-2">Date</th><th className="py-2">Merchant</th><th className="py-2 text-right">Amount</th></tr>
                            </thead>
                            <tbody className="text-xs font-bold text-slate-300">
                                {recentTransactions.map((t) => (
                                    <tr key={t.id} className="border-b border-white/5 last:border-0 hover:bg-white/5 transition-colors">
                                        <td className="py-4 text-slate-500 font-mono text-[10px]">{new Date(t.date).toLocaleDateString('en-US', { month: 'short', day: 'numeric' }).toUpperCase()}</td>
                                        <td className="py-4">{t.merchant}</td>
                                        <td className={`py-4 text-right ${t.type === TransactionType.INCOME ? 'text-emerald-400' : 'text-white'}`}>{formatCurrency(t.amount)}</td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </div>

            </div>

            {/* RIGHT SIDEBAR - Stretched to fit */}
            <div className="lg:col-span-4 flex flex-col gap-6 h-full">

                {/* 1. Goal Vector - Added Saving Targets */}
                <div className="glass-card p-6 rounded-[2.5rem] border border-white/5 bg-slate-900/40 flex flex-col">
                    <div className="flex items-center gap-3 mb-6">
                        <div className="w-10 h-10 rounded-full bg-indigo-500/20 flex items-center justify-center border border-indigo-500/30"><Target className="w-5 h-5 text-indigo-400" /></div>
                        <div><h3 className="text-sm font-black text-white uppercase tracking-wider">Goal Vector</h3><p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">Neural Performance</p></div>
                    </div>

                    <div className="space-y-6 flex-1 min-h-[350px]">
                        <div>
                            <div className="flex justify-between items-end mb-2">
                                <span className="text-[10px] font-black text-slate-400 uppercase tracking-wider">Global Limit</span>
                                <span className="text-[10px] font-black text-amber-400">{formatCurrency(currentPeriodSpend)} / {formatCurrency(displayLimit)}</span>
                            </div>
                            <div className="h-2 w-full bg-slate-800 rounded-full overflow-hidden border border-white/5">
                                <div className={`h-full rounded-full transition-all duration-1000 ${goalMetrics.budgetUtilization > 100 ? 'bg-rose-500' : 'bg-gradient-to-r from-amber-400 to-orange-500'}`} style={{ width: `${Math.min(goalMetrics.budgetUtilization, 100)}%` }}></div>
                            </div>
                        </div>

                        {/* Active Goals Section */}
                        <div className="pt-4 border-t border-white/5">
                            <h4 className="text-[10px] font-black text-indigo-400 uppercase tracking-widest mb-4 flex items-center gap-2">
                                <Flag className="w-3 h-3" /> Active Savings Targets
                            </h4>
                            <div className="space-y-4 max-h-56 overflow-y-auto custom-scrollbar pr-2">
                                {goals.length > 0 ? goals.map(goal => {
                                    const progress = Math.min((goal.currentAmount / goal.targetAmount) * 100, 100);
                                    return (
                                        <div key={goal.id}>
                                            <div className="flex justify-between items-end mb-1">
                                                <span className="text-[10px] font-bold text-slate-300 truncate max-w-[120px] uppercase tracking-wide">{goal.name}</span>
                                                {/* ADDED SAVINGS TARGET DISPLAY */}
                                                <span className="text-[9px] font-black text-emerald-400">
                                                    {formatCurrency(goal.currentAmount)} <span className="text-slate-500">/ {formatCurrency(goal.targetAmount)}</span>
                                                </span>
                                            </div>
                                            <div className="h-1.5 w-full bg-slate-800 rounded-full overflow-hidden border border-white/5">
                                                <div className={`h-full rounded-full transition-all duration-1000 bg-gradient-to-r ${goal.color}`} style={{ width: `${progress}%` }}></div>
                                            </div>
                                        </div>
                                    );
                                }) : (
                                    <div className="text-center py-4 border border-dashed border-white/10 rounded-2xl bg-slate-900/50">
                                        <p className="text-[9px] text-slate-500 font-bold uppercase tracking-widest">No active targets</p>
                                        <button onClick={() => onNavigate('goals')} className="text-[9px] text-indigo-400 font-black uppercase mt-1 hover:text-indigo-300">Configure Goals</button>
                                    </div>
                                )}
                            </div>
                        </div>
                    </div>
                    <button onClick={() => onNavigate('sandbox')} className="w-full py-3.5 bg-indigo-600 hover:bg-indigo-500 text-white rounded-xl text-xs font-black uppercase tracking-widest shadow-lg mt-6 flex items-center justify-center gap-2"><Microscope className="w-3.5 h-3.5" /> Simulate Goal</button>
                </div>

                {/* 2. Portfolio Stats */}
                <div className="grid grid-cols-2 gap-4">
                    <div className="glass-card p-5 rounded-[2rem] border border-white/5 bg-slate-900/40 flex flex-col justify-between min-h-[100px]">
                        <div className="flex justify-between items-start"><span className="text-[10px] font-black text-slate-500 uppercase tracking-wider">Net Worth</span><Wallet className="w-4 h-4 text-blue-500" /></div>
                        <div className="text-white font-black text-sm truncate">{formatCurrency(netWorth)}</div>
                    </div>
                    <div className="glass-card p-5 rounded-[2rem] border border-white/5 bg-slate-900/40 flex flex-col justify-between min-h-[100px]">
                        <div className="flex justify-between items-start"><span className="text-[10px] font-black text-slate-500 uppercase tracking-wider">Debt</span><CreditCard className="w-4 h-4 text-rose-400" /></div>
                        <div className="text-white font-black text-sm truncate">{formatCurrency(creditCardDebt)}</div>
                    </div>
                </div>

                {/* 3. Recurring Bills - Balanced Height */}
                <div className="glass-card p-6 rounded-[2.5rem] border border-white/5 bg-slate-900/40 flex-1 flex flex-col min-h-[280px]">
                    <div className="flex justify-between items-center mb-6">
                        <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest">My Recurring Bills</h3>
                        <span className="px-2 py-1 rounded bg-slate-950 border border-white/5 text-[8px] font-bold text-slate-500 uppercase tracking-widest">Active System</span>
                    </div>
                    <div className="space-y-4 overflow-y-auto custom-scrollbar flex-1 pr-1">
                        {recurringBills.length > 0 ? recurringBills.map(bill => (
                            <div key={bill.id} className="flex items-center gap-3 group">
                                <div className={`w-8 h-8 rounded-xl flex items-center justify-center text-[10px] font-black text-white ${bill.merchant.toLowerCase().includes('netflix') ? 'bg-red-600' : bill.merchant.toLowerCase().includes('spotify') ? 'bg-green-500' : 'bg-slate-800'}`}>{bill.merchant.charAt(0)}</div>
                                <div className="flex-1 flex justify-between items-center">
                                    <span className="text-xs font-bold text-slate-300 group-hover:text-white transition-colors truncate max-w-[120px]">{bill.merchant}</span>
                                    <span className="text-xs font-bold text-slate-500">{formatCurrency(bill.amount)}</span>
                                </div>
                            </div>
                        )) : <div className="flex flex-col items-center justify-center h-full opacity-40 text-center space-y-2"><FileText className="w-8 h-8 text-slate-600" /><p className="text-[10px] font-black uppercase tracking-widest text-slate-500">No active subscriptions</p></div>}
                    </div>
                    <button onClick={() => onNavigate('negotiator')} className="w-full py-3 bg-slate-800/50 hover:bg-slate-800 text-slate-400 hover:text-white rounded-xl text-[10px] font-black uppercase tracking-widest border border-white/5 mt-6 transition-all">Optimize Bills</button>
                </div>

            </div>
        </div>

        {/* Audit Modal */}
        {showScanConfirm && (
            <div className="fixed inset-0 z-[150] flex items-center justify-center p-4 bg-black/90 backdrop-blur-md animate-fade-in">
                <div className="bg-[#0f172a] border border-white/10 rounded-[2.5rem] w-full max-w-sm p-10 shadow-2xl relative animate-slide-up">
                    <div className="w-16 h-16 bg-indigo-500/20 rounded-2xl flex items-center justify-center mx-auto mb-6 border border-indigo-500/30"><Zap className="w-8 h-8 text-indigo-400 animate-pulse" /></div>
                    <h3 className="text-xl font-black text-white mb-2 text-center uppercase tracking-tight">Execute Audit?</h3>
                    <p className="text-sm text-slate-400 mb-8 text-center leading-relaxed font-medium">Initialize neural scan for strategic capital intelligence.</p>
                    <div className="grid grid-cols-2 gap-4">
                        <button onClick={() => setShowScanConfirm(false)} className="py-4 bg-slate-800 text-slate-500 font-black rounded-xl text-[10px] uppercase tracking-widest">Abort</button>
                        <button onClick={() => { setShowScanConfirm(false); onNavigate('insights', { autoScan: true }); }} className="py-4 bg-indigo-600 text-white font-black rounded-xl text-[10px] uppercase tracking-widest shadow-lg flex items-center justify-center gap-2"><Check className="w-4 h-4" /> Proceed</button>
                    </div>
                </div>
            </div>
        )}
    </div>
  );
};

export default Dashboard;
